// src/components/audio/DJBroadcastBar.jsx
//
// The DJ's live-broadcast + recording control bar. It reads/writes the
// persistent LiveDJSession (mounted above the router), so going live and
// recording survive navigation — the stream no longer stops when the DJ
// clicks Home or another button. It also broadcasts the real DJ mixer audio
// into the same room viewers join (event-<id>) and surfaces a shareable
// "watch" link so an audience can actually join.

import React, { useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { getFirestore, addDoc, collection, serverTimestamp } from 'firebase/firestore';
import { Radio, Square, Disc, Copy, Check, Users, ExternalLink, Loader } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { useDJMixer } from '../../contexts/DJMixerContext';
import { useLiveDJSession } from '../../contexts/LiveDJSessionContext';

const formatElapsed = (ms) => {
  if (!ms || ms < 0) ms = 0;
  const total = Math.floor(ms / 1000);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  const pad = (n) => String(n).padStart(2, '0');
  return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${m}:${pad(s)}`;
};

const DJBroadcastBar = ({ currentEvent, artistProfile }) => {
  const navigate = useNavigate();
  const { currentUser } = useAuth();
  const djMixer = useDJMixer();
  const {
    isLive, liveEvent, liveStartedAt, connecting, error, watchUrl,
    goLive, endSet,
    isRecording, recordingStartedAt, startRecording, stopRecording,
  } = useLiveDJSession();

  const [preparing, setPreparing] = useState(false);
  const [copied, setCopied] = useState(false);
  const [now, setNow] = useState(Date.now());

  // Tick a clock while live or recording so the elapsed timers update.
  useEffect(() => {
    if (!isLive && !isRecording) return;
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, [isLive, isRecording]);

  // Ensure there's an event to broadcast into. Uses the selected event, or
  // creates a lightweight DJ-set event for any registered user (no artist
  // profile required) so anyone can go live.
  const ensureEvent = useCallback(async () => {
    if (currentEvent?.id) return { id: currentEvent.id, title: currentEvent.title || 'DJ Set' };
    if (!currentUser) return null;

    const title = `DJ Set - ${artistProfile?.artistName || currentUser.displayName || 'Live'}`;
    const db = getFirestore();
    const eventData = {
      title,
      description: 'Live DJ mix session',
      type: 'dj-set',
      artistId: currentUser.uid,
      artistName: artistProfile?.artistName || currentUser.displayName || 'DJ',
      genre: artistProfile?.genre || 'Electronic',
      startTime: Date.now(),           // numeric ms — matches how the event lists read startTime
      endTime: null,
      isLive: true,
      isDJSet: true,
      ticketPrice: 0,
      maxAttendees: 1000,
      attendees: [],
      streamUrl: '',
      status: 'live',
      createdAt: serverTimestamp(),
    };
    const docRef = await addDoc(collection(db, 'events'), eventData);
    return { id: docRef.id, title };
  }, [currentEvent, currentUser, artistProfile]);

  const handleGoLive = useCallback(async () => {
    setPreparing(true);
    try {
      // Resume the audio graph (this click is the required user gesture).
      try { await djMixer.resumeAudioContext?.(); } catch (_) { /* ignore */ }

      const event = await ensureEvent();
      if (!event) { setPreparing(false); return; }

      const audioStream = djMixer.getDJAudioStream?.();
      await goLive({ event, user: currentUser, audioStream });
    } finally {
      setPreparing(false);
    }
  }, [djMixer, ensureEvent, goLive, currentUser]);

  const handleRecord = useCallback(async () => {
    if (isRecording) {
      await stopRecording();
      return;
    }
    try { await djMixer.resumeAudioContext?.(); } catch (_) { /* ignore */ }
    startRecording(djMixer.getDJAudioStream?.());
  }, [isRecording, stopRecording, startRecording, djMixer]);

  const handleCopy = useCallback(async () => {
    if (!watchUrl) return;
    try {
      await navigator.clipboard.writeText(watchUrl);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (_) { /* ignore */ }
  }, [watchUrl]);

  const btnBase = {
    display: 'inline-flex', alignItems: 'center', gap: '0.4rem',
    border: 'none', borderRadius: '8px', padding: '0.6rem 1.1rem',
    cursor: 'pointer', fontWeight: 600, fontSize: '0.95rem', whiteSpace: 'nowrap',
  };
  const busy = preparing || connecting;

  return (
    <div style={{
      background: 'linear-gradient(135deg, #0f172a 0%, #1e293b 100%)',
      border: '1px solid #334155',
      borderRadius: '12px',
      padding: '1rem 1.25rem',
      marginBottom: '1rem',
      color: '#e2e8f0',
    }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '1rem', flexWrap: 'wrap' }}>
        {/* Status */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
          <span style={{
            display: 'inline-flex', alignItems: 'center', gap: '0.4rem',
            backgroundColor: isLive ? '#dc2626' : '#334155',
            color: 'white', borderRadius: '999px', padding: '0.3rem 0.75rem',
            fontSize: '0.8rem', fontWeight: 700, letterSpacing: '0.03em',
          }}>
            <Radio size={14} />
            {isLive ? 'LIVE' : 'OFFLINE'}
          </span>
          <div>
            <div style={{ fontWeight: 700 }}>
              {isLive ? (liveEvent?.title || 'DJ Set') : 'Broadcast your set'}
            </div>
            <div style={{ fontSize: '0.8rem', color: '#94a3b8' }}>
              {isLive
                ? `On air · ${formatElapsed(now - (liveStartedAt || now))}`
                : 'Go live to stream this mix to your audience.'}
            </div>
          </div>
        </div>

        {/* Actions */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', flexWrap: 'wrap' }}>
          <button
            onClick={handleRecord}
            style={{
              ...btnBase,
              backgroundColor: isRecording ? '#b91c1c' : 'transparent',
              color: isRecording ? 'white' : '#e2e8f0',
              border: `1px solid ${isRecording ? '#b91c1c' : '#475569'}`,
            }}
            title="Record the mixed set to a file (works with or without going live)"
          >
            <Disc size={16} />
            {isRecording ? `Stop Rec · ${formatElapsed(now - (recordingStartedAt || now))}` : 'Record Set'}
          </button>

          {isLive ? (
            <button onClick={endSet} style={{ ...btnBase, backgroundColor: '#ef4444', color: 'white' }}>
              <Square size={16} /> End Set
            </button>
          ) : (
            <button
              onClick={handleGoLive}
              disabled={busy}
              style={{ ...btnBase, backgroundColor: busy ? '#475569' : '#10b981', color: 'white', opacity: busy ? 0.8 : 1 }}
            >
              {busy ? <Loader size={16} className="spin" /> : <Radio size={16} />}
              {busy ? 'Starting…' : 'Go Live'}
            </button>
          )}
        </div>
      </div>

      {/* Shareable watch link — how the audience joins */}
      {isLive && watchUrl && (
        <div style={{
          marginTop: '0.9rem', paddingTop: '0.9rem', borderTop: '1px solid #334155',
          display: 'flex', alignItems: 'center', gap: '0.6rem', flexWrap: 'wrap',
        }}>
          <Users size={16} color="#38bdf8" />
          <span style={{ fontSize: '0.85rem', color: '#94a3b8' }}>Share this link so people can join:</span>
          <code style={{
            backgroundColor: '#0b1220', border: '1px solid #334155', borderRadius: '6px',
            padding: '0.35rem 0.6rem', fontSize: '0.82rem', color: '#e2e8f0',
            maxWidth: '100%', overflowX: 'auto', whiteSpace: 'nowrap',
          }}>{watchUrl}</code>
          <button onClick={handleCopy} style={{ ...btnBase, padding: '0.4rem 0.7rem', backgroundColor: '#1d4ed8', color: 'white' }}>
            {copied ? <Check size={15} /> : <Copy size={15} />}
            {copied ? 'Copied' : 'Copy'}
          </button>
          <button
            onClick={() => liveEvent?.id && navigate(`/events/${liveEvent.id}`)}
            style={{ ...btnBase, padding: '0.4rem 0.7rem', backgroundColor: 'transparent', color: '#e2e8f0', border: '1px solid #475569' }}
            title="Open the audience view in this tab"
          >
            <ExternalLink size={15} /> View as audience
          </button>
        </div>
      )}

      {error && (
        <div style={{ marginTop: '0.75rem', color: '#fca5a5', fontSize: '0.85rem' }}>
          {error}
        </div>
      )}

      <style>{`@keyframes djspin { to { transform: rotate(360deg); } } .spin { animation: djspin 1s linear infinite; }`}</style>
    </div>
  );
};

export default DJBroadcastBar;
