// src/scripts/initialize-profiles.js
import { getFirestore, collection, getDocs, doc, getDoc } from 'firebase/firestore';
import { createProfile } from '../services/profiles';

/**
 * Initialize profiles for all existing users
 * This script should be run once to create profiles for all existing users
 */
export const initializeProfiles = async () => {
  try {
    console.log('Starting profile initialization...');
    const db = getFirestore();
    
    // Get all users
    const usersSnapshot = await getDocs(collection(db, 'users'));
    const totalUsers = usersSnapshot.size;
    
    console.log(`Found ${totalUsers} users to process`);
    let createdCount = 0;
    let existingCount = 0;
    let errorCount = 0;
    
    // Process each user
    for (const userDoc of usersSnapshot.docs) {
      const userId = userDoc.id;
      const userData = userDoc.data();
      
      try {
        // Check if profile already exists
        const profileRef = doc(db, 'profiles', userId);
        const profileDoc = await getDoc(profileRef);
        
        if (!profileDoc.exists()) {
          // Create profile
          await createProfile(userId, {
            displayName: userData.displayName || userData.username || 'User',
            email: userData.email,
            photoURL: userData.photoURL || null,
            username: userData.username || null
          });
          
          createdCount++;
          console.log(`Created profile for user ${userId}`);
        } else {
          existingCount++;
          console.log(`Profile already exists for user ${userId}`);
        }
      } catch (error) {
        errorCount++;
        console.error(`Error creating profile for user ${userId}:`, error);
      }
    }
    
    console.log('Profile initialization complete:');
    console.log(`- Created: ${createdCount}`);
    console.log(`- Already existed: ${existingCount}`);
    console.log(`- Errors: ${errorCount}`);
    console.log(`- Total processed: ${totalUsers}`);
    
    return {
      created: createdCount,
      existing: existingCount,
      errors: errorCount,
      total: totalUsers
    };
  } catch (error) {
    console.error('Failed to initialize profiles:', error);
    throw error;
  }
};

export default initializeProfiles;