import { TrendingUp, TrendingDown, Minus } from 'lucide-react'

const config = {
  up: { icon: TrendingUp, color: 'text-emerald-400', label: 'Rising' },
  down: { icon: TrendingDown, color: 'text-red-400', label: 'Falling' },
  stable: { icon: Minus, color: 'text-amber-400', label: 'Stable' },
}

export default function TrendIndicator({ trend, size = 14, showLabel = false }) {
  const { icon: Icon, color, label } = config[trend] || config.stable

  return (
    <span className={`inline-flex items-center gap-1 ${color}`}>
      <Icon size={size} />
      {showLabel && <span className="text-xs font-medium">{label}</span>}
    </span>
  )
}
