import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useStreamingLiveKit as useStreaming } from '../../contexts/StreamingContextLiveKit';
import { useNavigate } from 'react-router-dom';
import { getFirestore, doc, getDoc, setDoc, collection, query, where, orderBy, onSnapshot, addDoc, updateDoc, deleteDoc, serverTimestamp } from 'firebase/firestore';
import { getRtdb } from '../../firebase';
import { ref, set, push, serverTimestamp as rtdbServerTimestamp } from 'firebase/database';
import DJSetManager from '../audio/DJSetManager';
import { 
  Music, 
  Users, 
  Calendar, 
  DollarSign, 
  Settings, 
  BarChart,
  Play,
  Edit,
  Camera,
  AlertCircle,
  Plus,
  Clock,
  Crown,
  Trash2,
  Eye,
  ChevronRight,
  Video,
  ExternalLink
} from 'lucide-react';
import './ArtistStreamingPortal.css';
// import { streamingConfigFixed as streamingConfig } from "../../config/streaming-fixed.js"

const ArtistStreamingPortal = () => {
  const { currentUser } = useAuth();
  const { 
    streamingServiceReady = false, 
    error: streamingError = null 
  } = useStreaming() || {};
  // Fallback streaming functions while LiveKit services initialize
  const startEventStream = async (eventId, config = {}) => {
    console.log('🚧 Streaming services initializing...', { eventId, config });
    return {
      success: false,
      message: 'Streaming services are still initializing. Please try again in a moment.'
    };
  };

  const testStreamingConnectivity = async (eventId) => {
    console.log('🚧 Testing connectivity...', { eventId });
    return {
      success: false,
      message: 'Connectivity testing is currently unavailable. Please try again later.'
    };
  };
  
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [artistProfile, setArtistProfile] = useState(null);
  const [activeTab, setActiveTab] = useState('overview');
  
  // Debug logging
  console.log('ArtistStreamingPortal - activeTab:', activeTab);
  const [events, setEvents] = useState([]);
  const [showEventForm, setShowEventForm] = useState(false);
  const [editingEvent, setEditingEvent] = useState(null);
  const [eventForm, setEventForm] = useState({
    title: '',
    description: '',
    category: 'music',
    accessLevel: 'premium',
    maxViewers: 500,
    duration: 60,
    startTime: new Date().toISOString().slice(0, 16),
    recordingEnabled: true,
    chatEnabled: true,
    reactionsEnabled: true,
    tipsEnabled: false
  });
  const [stats, setStats] = useState({
    followers: 0,
    totalStreams: 0,
    revenue: 0,
    upcomingEvents: 0
  });

  useEffect(() => {
    if (!currentUser) {
      navigate('/login');
      return;
    }

    loadArtistProfile();
    loadEvents();
  }, [currentUser, navigate]);

  const loadEvents = () => {
    if (!currentUser) return;
    
    const db = getFirestore();
    const eventsQuery = query(
      collection(db, 'events'),
      where('artistId', '==', currentUser.uid),
      orderBy('startTime', 'desc')
    );
    
    const unsubscribe = onSnapshot(eventsQuery, (snapshot) => {
      const eventsList = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setEvents(eventsList);
      
      // Update upcoming events count
      const upcomingCount = eventsList.filter(event => 
        event.status === 'scheduled' && new Date(event.startTime) > new Date()
      ).length;
      
      setStats(prev => ({
        ...prev,
        upcomingEvents: upcomingCount
      }));
    });
    
    return unsubscribe;
  };

  const createEvent = async () => {
    try {
      if (!eventForm.title.trim()) {
        alert('Please enter an event title');
        return;
      }
      
      const db = getFirestore();
      const eventData = {
        title: eventForm.title,
        description: eventForm.description,
        category: eventForm.category,
        artistId: currentUser.uid,
        artistName: currentUser.displayName || 'Unknown Artist',
        artistAvatar: currentUser.photoURL || null,
        artistVerified: true,
        
        status: 'scheduled',
        startTime: new Date(eventForm.startTime).getTime(),
        duration: eventForm.duration,
        maxViewers: eventForm.maxViewers,
        
        accessLevel: eventForm.accessLevel,
        
        chatEnabled: eventForm.chatEnabled,
        reactionsEnabled: eventForm.reactionsEnabled,
        recordingEnabled: eventForm.recordingEnabled,
        tipsEnabled: eventForm.tipsEnabled,
        
        viewerCount: 0,
        peakViewers: 0,
        totalViews: 0,
        revenue: 0,
        
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp()
      };
      
      if (editingEvent) {
        await updateDoc(doc(db, 'events', editingEvent.id), {
          ...eventData,
          updatedAt: serverTimestamp()
        });
        setEditingEvent(null);
      } else {
        // Create the event
        const eventRef = await addDoc(collection(db, 'events'), eventData);
        const eventId = eventRef.id;
        
        // Create chat room for the event
        await createEventChatRoom(eventId, eventData);
        
        console.log('🎭 Event and chat room created:', eventId);
      }
      
      setShowEventForm(false);
      resetEventForm();
      
    } catch (error) {
      console.error('Error creating/updating event:', error);
      alert('Failed to save event: ' + error.message);
    }
  };

  const editEvent = (event) => {
    setEditingEvent(event);
    setEventForm({
      title: event.title,
      description: event.description,
      category: event.category,
      accessLevel: event.accessLevel,
      maxViewers: event.maxViewers,
      duration: event.duration,
      startTime: new Date(event.startTime).toISOString().slice(0, 16),
      recordingEnabled: event.recordingEnabled,
      chatEnabled: event.chatEnabled,
      reactionsEnabled: event.reactionsEnabled,
      tipsEnabled: event.tipsEnabled
    });
    setShowEventForm(true);
  };

  const deleteEvent = async (eventId) => {
    if (!confirm('Are you sure you want to delete this event?')) return;
    
    try {
      const db = getFirestore();
      await deleteDoc(doc(db, 'events', eventId));
    } catch (error) {
      console.error('Error deleting event:', error);
      alert('Failed to delete event: ' + error.message);
    }
  };

  // NEW: Start stream for specific event using new streaming services
  const startStreamForEvent = async (event) => {
    try {
      console.log('🎬 Starting stream for event:', event.id);
      
      if (!streamingServiceReady) {
        alert('⚠️ Streaming services are initializing. The full streaming functionality will be available once LiveKit services are configured.');
        return;
      }
      
      // Test connectivity first
      const connectivityTest = await testStreamingConnectivity(event.id);
      if (!connectivityTest.success) {
        const proceed = confirm(
          `❌ Connectivity test failed: ${connectivityTest.message}\n\n` +
          'Do you want to proceed anyway? (Not recommended)'
        );
        if (!proceed) return;
      }
      
      // Start the event stream
      const streamResult = await startEventStream(event.id, {
        quality: 'high',
        enableAudio: true,
        enableVideo: true,
        deviceType: 'desktop'
      });
      
      if (streamResult && streamResult.success) {
        // Store the stream configuration for the streaming interface
        sessionStorage.setItem('activeStreamConfig', JSON.stringify({
          eventId: event.id,
          eventTitle: event.title,
          streamKey: streamResult.streamKey,
          rtmpUrl: streamResult.rtmpUrl,
          chatRoomPath: `chats/public/event_${event.id}`,
          streamId: streamResult.streamId
        }));
        
        // Navigate to the Artist Streaming Studio
        navigate('/events/studio');
        
        console.log('✅ Stream started successfully, navigating to streaming interface');
      } else {
        alert('❌ Failed to start stream. Please check your connection and try again.');
      }
    } catch (error) {
      console.error('Error starting stream for event:', error);
      alert(`❌ Failed to start stream: ${error.message}`);
    }
  };

  const createEventChatRoom = async (eventId, eventData) => {
    try {
      const { getDatabase, ref, set, push } = await import('firebase/database');
      const database = getDatabase();
      
      // Create chat room in RTDB under chats/public/ - CORRECT PATH
      const chatRoomPath = `chats/public/event_${eventId}`;
      console.log('🏗️ Creating chat room at:', chatRoomPath);
      const chatRoomData = {
        type: 'event',
        eventId: eventId,
        eventTitle: eventData.title,
        artistId: eventData.artistId,
        artistName: eventData.artistName,
        artistAvatar: eventData.artistAvatar,
        
        // Chat room settings
        isActive: false, // Will be activated when event goes live
        allowUserStreaming: true,
        artistPriority: true,
        maxConcurrentUserStreams: 8, // Updated to 8 as per requirements
        
        // Moderation settings
        moderationEnabled: true,
        autoModeration: true,
        slowModeEnabled: false,
        slowModeDelay: 0,
        
        // Access control
        accessLevel: eventData.accessLevel,
        allowAnonymous: true, // Allow anonymous users in chat
        
        // Video streaming settings
        artistVideoActive: false,
        userStreams: {},
        
        // Analytics
        totalMessages: 0,
        activeUsers: 0,
        peakUsers: 0,
        
        // Timestamps
        createdAt: Date.now(),
        updatedAt: Date.now()
      };
      
      // Create the chat room
      await set(ref(database, chatRoomPath), chatRoomData);
      
      // Create initial system message
      const messagesRef = ref(database, `${chatRoomPath}/messages`);
      await push(messagesRef, {
        type: 'system',
        message: `Welcome to ${eventData.title}! Event chat room created. Anonymous users can chat, registered users can stream.`,
        timestamp: Date.now(),
        userId: 'system',
        userName: 'System'
      });
      
      console.log('💬 Event chat room created in RTDB:', chatRoomPath);
      
    } catch (error) {
      console.error('Failed to create event chat room:', error);
      // Don't block event creation if chat room fails
    }
  };

  const resetEventForm = () => {
    setEventForm({
      title: '',
      description: '',
      category: 'music',
      accessLevel: 'premium',
      maxViewers: 500,
      duration: 60,
      startTime: new Date().toISOString().slice(0, 16),
      recordingEnabled: true,
      chatEnabled: true,
      reactionsEnabled: true,
      tipsEnabled: false
    });
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'live': return '#ef4444';
      case 'scheduled': return '#f59e0b';
      case 'ended': return '#6b7280';
      default: return '#6b7280';
    }
  };

  const getAccessLevelIcon = (level) => {
    switch (level) {
      case 'vip': return <Crown className="text-yellow-500" size={16} />;
      case 'premium': return <Crown className="text-purple-500" size={16} />;
      case 'ticket': return <DollarSign className="text-green-500" size={16} />;
      default: return <Users className="text-gray-500" size={16} />;
    }
  };

  const getAccessLevelText = (level) => {
    switch (level) {
      case 'vip': return 'VIP Members Only';
      case 'premium': return 'Premium Members Only';
      case 'ticket': return 'Ticket Required';
      case 'free': return 'Free Access';
      default: return 'Premium Members Only';
    }
  };

  const formatEventTime = (timestamp) => {
    return new Date(timestamp).toLocaleString();
  };

  const loadArtistProfile = async () => {
    try {
      const db = getFirestore();
      // Every signed-in user is a creator by default — there is no artist
      // gate here anymore. We no longer bounce non-artists to /artist-signup
      // (that made "Go live" feel like a dead button and depended on a
      // Firestore write that could fail). Just load or create their profile.

      const artistDoc = await getDoc(doc(db, 'artists', currentUser.uid));
      if (artistDoc.exists()) {
        setArtistProfile(artistDoc.data());
      } else {
        // Create initial artist profile
        const initialProfile = {
          displayName: currentUser.displayName || 'Artist',
          bio: '',
          profileImage: currentUser.photoURL || '',
          coverImage: '',
          genres: [],
          socialLinks: {},
          createdAt: new Date().toISOString()
        };
        await setDoc(doc(db, 'artists', currentUser.uid), initialProfile);
        setArtistProfile(initialProfile);
      }

      // Load stats (mock data for now)
      setStats({
        followers: Math.floor(Math.random() * 10000),
        totalStreams: Math.floor(Math.random() * 50000),
        revenue: Math.floor(Math.random() * 5000),
        upcomingEvents: Math.floor(Math.random() * 5)
      });

      setLoading(false);
    } catch (error) {
      console.error('Error loading artist profile:', error);
      setLoading(false);
    }
  };

  const startStream = () => {
    navigate('/events/studio');
  };

  const editProfile = () => {
    navigate('/artist-profile');
  };

  if (loading) {
    return (
      <div className="artist-portal-loading">
        <div className="loading-spinner"></div>
        <p>Loading artist portal...</p>
      </div>
    );
  }

  return (
    <div className="artist-streaming-portal">
      {/* Header Section */}
      <div className="artist-header">
        <div 
          className="cover-image" 
          style={{
            backgroundImage: artistProfile?.coverImage 
              ? `url(${artistProfile.coverImage})` 
              : 'linear-gradient(to right, #7c3aed, #ec4899)'
          }}
        >
          <button className="edit-cover-btn">
            <Camera size={20} />
            <span>Edit Cover</span>
          </button>
        </div>
        
        <div className="artist-info">
          <div className="profile-section">
            <div className="profile-image-container">
              {artistProfile?.profileImage ? (
                <img 
                  src={artistProfile.profileImage} 
                  alt={artistProfile.displayName}
                  className="profile-image"
                />
              ) : (
                <div className="profile-image-placeholder">
                  <Music size={40} />
                </div>
              )}
              <button className="edit-profile-image">
                <Camera size={16} />
              </button>
            </div>
            
            <div className="artist-details">
              <h1>{artistProfile?.displayName || 'Artist'}</h1>
              <p className="artist-bio">{artistProfile?.bio || 'No bio added yet'}</p>
              <div className="artist-genres">
                {artistProfile?.genres?.length > 0 ? (
                  artistProfile.genres.map((genre, index) => (
                    <span key={index} className="genre-tag">{genre}</span>
                  ))
                ) : (
                  <span className="no-genres">No genres added</span>
                )}
              </div>
            </div>
          </div>
          
          <div className="action-buttons">
            <button className="primary-btn" onClick={startStream}>
              <Play size={18} />
              <span>Start Streaming</span>
            </button>
            <button className="secondary-btn" onClick={editProfile}>
              <Edit size={18} />
              <span>Edit Profile</span>
            </button>
          </div>
        </div>
      </div>

      {/* Stats Overview */}
      <div className="stats-overview">
        <div className="stat-card">
          <Users size={24} className="stat-icon" />
          <div className="stat-content">
            <h3>{stats.followers.toLocaleString()}</h3>
            <p>Followers</p>
          </div>
        </div>
        
        <div className="stat-card">
          <BarChart size={24} className="stat-icon" />
          <div className="stat-content">
            <h3>{stats.totalStreams.toLocaleString()}</h3>
            <p>Total Streams</p>
          </div>
        </div>
        
        <div className="stat-card">
          <DollarSign size={24} className="stat-icon" />
          <div className="stat-content">
            <h3>${stats.revenue.toLocaleString()}</h3>
            <p>Revenue</p>
          </div>
        </div>
        
        <div className="stat-card">
          <Calendar size={24} className="stat-icon" />
          <div className="stat-content">
            <h3>{stats.upcomingEvents}</h3>
            <p>Upcoming Events</p>
          </div>
        </div>
      </div>

      {/* Tabs Navigation */}
      <div className="portal-tabs">
        <button 
          className={`tab-btn ${activeTab === 'overview' ? 'active' : ''}`}
          onClick={() => setActiveTab('overview')}
        >
          Overview
        </button>
        <button 
          className={`tab-btn ${activeTab === 'streams' ? 'active' : ''}`}
          onClick={() => setActiveTab('streams')}
        >
          My Streams
        </button>
        <button 
          className={`tab-btn ${activeTab === 'tracks' ? 'active' : ''}`}
          onClick={() => setActiveTab('tracks')}
        >
          My Tracks
        </button>
        <button 
          className={`tab-btn ${activeTab === 'events' ? 'active' : ''}`}
          onClick={() => setActiveTab('events')}
        >
          Events
        </button>
        <button 
          className={`tab-btn ${activeTab === 'analytics' ? 'active' : ''}`}
          onClick={() => setActiveTab('analytics')}
        >
          Analytics
        </button>
        <button 
          className={`tab-btn ${activeTab === 'earnings' ? 'active' : ''}`}
          onClick={() => setActiveTab('earnings')}
        >
          Earnings
        </button>
        <button 
          className={`tab-btn ${activeTab === 'settings' ? 'active' : ''}`}
          onClick={() => setActiveTab('settings')}
        >
          Settings
        </button>
      </div>

      {/* Tab Content */}
      <div className="tab-content">
        {/* Debug info */}
        {console.log('Rendering tab content for:', activeTab)}
        
        {activeTab === 'overview' && (
          <div className="overview-content">
            <div className="quick-actions">
              <h2>Quick Actions</h2>
              <div className="actions-grid">
                <button className="action-card" onClick={startStream}>
                  <Play size={24} />
                  <span>Start Live Stream</span>
                </button>
                <button className="action-card">
                  <Calendar size={24} />
                  <span>Schedule Stream</span>
                </button>
                <button className="action-card" onClick={editProfile}>
                  <Edit size={24} />
                  <span>Edit Profile</span>
                </button>
                <button className="action-card" onClick={() => navigate('/artist-streaming')}>
                  <Music size={24} />
                  <span>Upload Tracks</span>
                </button>
                <button className="action-card">
                  <BarChart size={24} />
                  <span>View Analytics</span>
                </button>
              </div>
            </div>

            <div className="recent-activity">
              <h2>Recent Activity</h2>
              <div className="activity-list">
                <div className="activity-item">
                  <div className="activity-icon">
                    <AlertCircle size={20} />
                  </div>
                  <div className="activity-content">
                    <p>Welcome to your Artist Portal!</p>
                    <span className="activity-time">Just now</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'events' && (
          <div className="events-content">
            <div className="events-header">
              <h2>My Events</h2>
              <button 
                className="primary-btn" 
                onClick={() => {
                  resetEventForm();
                  setEditingEvent(null);
                  setShowEventForm(true);
                }}
              >
                <Plus size={18} />
                <span>Create Event</span>
              </button>
            </div>

            {showEventForm && (
              <div className="event-form-modal">
                <div className="event-form">
                  <div className="form-header">
                    <h3>{editingEvent ? 'Edit Event' : 'Create New Event'}</h3>
                    <button 
                      className="close-btn"
                      onClick={() => {
                        setShowEventForm(false);
                        setEditingEvent(null);
                        resetEventForm();
                      }}
                    >
                      ×
                    </button>
                  </div>
                  
                  <div className="form-body">
                    <div className="form-group">
                      <label>Event Title *</label>
                      <input
                        type="text"
                        value={eventForm.title}
                        onChange={(e) => setEventForm({...eventForm, title: e.target.value})}
                        placeholder="Enter event title..."
                      />
                    </div>
                    
                    <div className="form-group">
                      <label>Description</label>
                      <textarea
                        value={eventForm.description}
                        onChange={(e) => setEventForm({...eventForm, description: e.target.value})}
                        placeholder="Describe your event..."
                        rows={3}
                      />
                    </div>
                    
                    <div className="form-row">
                      <div className="form-group">
                        <label>Category</label>
                        <select
                          value={eventForm.category}
                          onChange={(e) => setEventForm({...eventForm, category: e.target.value})}
                        >
                          <option value="music">Music</option>
                          <option value="talk">Talk Show</option>
                          <option value="performance">Performance</option>
                          <option value="education">Education</option>
                          <option value="other">Other</option>
                        </select>
                      </div>
                      
                      <div className="form-group">
                        <label>Access Level</label>
                        <select
                          value={eventForm.accessLevel}
                          onChange={(e) => setEventForm({...eventForm, accessLevel: e.target.value})}
                        >
                          <option value="premium">Premium Members</option>
                          <option value="vip">VIP Members Only</option>
                          <option value="free">Free Access</option>
                        </select>
                      </div>
                    </div>
                    
                    <div className="form-row">
                      <div className="form-group">
                        <label>Start Time</label>
                        <input
                          type="datetime-local"
                          value={eventForm.startTime}
                          onChange={(e) => setEventForm({...eventForm, startTime: e.target.value})}
                        />
                      </div>
                      
                      <div className="form-group">
                        <label>Duration (minutes)</label>
                        <input
                          type="number"
                          value={eventForm.duration}
                          onChange={(e) => setEventForm({...eventForm, duration: parseInt(e.target.value) || 60})}
                          min="15"
                          max="300"
                        />
                      </div>
                    </div>
                    
                    <div className="form-group">
                      <label>Max Viewers</label>
                      <input
                        type="number"
                        value={eventForm.maxViewers}
                        onChange={(e) => setEventForm({...eventForm, maxViewers: parseInt(e.target.value) || 100})}
                        min="10"
                        max="10000"
                      />
                    </div>
                    
                    <div className="feature-toggles">
                      <label className="toggle-label">
                        <input
                          type="checkbox"
                          checked={eventForm.recordingEnabled}
                          onChange={(e) => setEventForm({...eventForm, recordingEnabled: e.target.checked})}
                        />
                        <span>Enable Recording</span>
                      </label>
                      
                      <label className="toggle-label">
                        <input
                          type="checkbox"
                          checked={eventForm.chatEnabled}
                          onChange={(e) => setEventForm({...eventForm, chatEnabled: e.target.checked})}
                        />
                        <span>Enable Chat</span>
                      </label>
                      
                      <label className="toggle-label">
                        <input
                          type="checkbox"
                          checked={eventForm.reactionsEnabled}
                          onChange={(e) => setEventForm({...eventForm, reactionsEnabled: e.target.checked})}
                        />
                        <span>Enable Reactions</span>
                      </label>
                      
                      <label className="toggle-label">
                        <input
                          type="checkbox"
                          checked={eventForm.tipsEnabled}
                          onChange={(e) => setEventForm({...eventForm, tipsEnabled: e.target.checked})}
                        />
                        <span>Enable Tips</span>
                      </label>
                    </div>
                  </div>
                  
                  <div className="form-footer">
                    <button 
                      className="secondary-btn"
                      onClick={() => {
                        setShowEventForm(false);
                        setEditingEvent(null);
                        resetEventForm();
                      }}
                    >
                      Cancel
                    </button>
                    <button 
                      className="primary-btn"
                      onClick={createEvent}
                    >
                      {editingEvent ? 'Update Event' : 'Create Event'}
                    </button>
                  </div>
                </div>
              </div>
            )}

            <div className="events-list">
              {events.length > 0 ? (
                events.map((event) => (
                  <div key={event.id} className="event-card">
                    <div className="event-header">
                      <div className="event-title-section">
                        <h3>{event.title}</h3>
                        <div className="event-meta">
                          <span 
                            className="event-status"
                            style={{ color: getStatusColor(event.status) }}
                          >
                            {event.status.toUpperCase()}
                          </span>
                          <span className="event-category">{event.category}</span>
                        </div>
                      </div>
                      
                      <div className="event-actions">
                        {/* NEW: Stream button for scheduled events */}
                        {event.status === 'scheduled' && (
                          <button 
                            className={`action-btn stream-btn ${!streamingServiceReady ? 'disabled' : ''}`}
                            onClick={() => startStreamForEvent(event)}
                            title={streamingServiceReady ? "Start Stream for this Event" : "Streaming services not ready"}
                            disabled={!streamingServiceReady}
                          >
                            <Video size={16} />
                            <span>{streamingServiceReady ? 'Stream' : 'Loading...'}</span>
                          </button>
                        )}
                        <button 
                          className="action-btn"
                          onClick={() => editEvent(event)}
                          title="Edit Event"
                        >
                          <Edit size={16} />
                        </button>
                        <button 
                          className="action-btn danger"
                          onClick={() => deleteEvent(event.id)}
                          title="Delete Event"
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </div>
                    
                    <p className="event-description">{event.description}</p>
                    
                    <div className="event-details">
                      <div className="detail-item">
                        <Clock size={16} />
                        <span>{formatEventTime(event.startTime)}</span>
                      </div>
                      <div className="detail-item">
                        <Users size={16} />
                        <span>Max {event.maxViewers} viewers</span>
                      </div>
                      <div className="detail-item">
                        {getAccessLevelIcon(event.accessLevel)}
                        <span>
                          {event.accessLevel === 'ticket' && event.ticketPrice 
                            ? `${event.ticketPrice}` 
                            : event.accessLevel.charAt(0).toUpperCase() + event.accessLevel.slice(1)
                          }
                        </span>
                      </div>
                      {event.viewerCount > 0 && (
                        <div className="detail-item">
                          <Eye size={16} />
                          <span>{event.viewerCount} watching</span>
                        </div>
                      )}
                    </div>

                    {/* NEW: Event-specific actions */}
                    <div className="event-footer">
                    <button 
                    className="secondary-btn"
                    onClick={() => navigate(`/events/${event.id}/chat`)}
                    >
                    <Users size={16} />
                    <span>View Chat</span>
                    </button>
                    <button 
                    className="secondary-btn"
                    onClick={() => navigate(`/events/${event.id}`)}
                    >
                    <ExternalLink size={16} />
                    <span>Event Page</span>
                    </button>
                      {/* Service status indicator */}
                        <div className={`service-status-indicator ${streamingServiceReady ? 'ready' : 'not-ready'}`}>
                          <span>{streamingServiceReady ? '🟢 Services Ready' : '🔴 Services Loading'}</span>
                        </div>
                      </div>
                  </div>
                ))
              ) : (
                <div className="events-empty">
                  <Calendar size={48} />
                  <h3>No Events Created</h3>
                  <p>Create your first event to start streaming to premium audiences</p>
                  <button 
                    className="primary-btn"
                    onClick={() => {
                      resetEventForm();
                      setEditingEvent(null);
                      setShowEventForm(true);
                    }}
                  >
                    <Plus size={18} />
                    <span>Create Your First Event</span>
                  </button>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'streams' && (
          <div className="streams-content">
            <h2>My Streams</h2>
            <div className="streams-empty">
              <Music size={48} />
              <p>You haven't streamed yet</p>
              <button className="primary-btn" onClick={startStream}>
                Start Your First Stream
              </button>
            </div>
          </div>
        )}

        {activeTab === 'tracks' && (
          <div className="tracks-content" style={{ minHeight: '400px', padding: '20px' }}>
            <h2 style={{ marginBottom: '20px' }}>My Tracks</h2>
            <DJSetManager isOwner={true} />
          </div>
        )}

        {activeTab === 'analytics' && (
          <div className="analytics-content">
            <h2>Analytics</h2>
            <div className="analytics-empty">
              <BarChart size={48} />
              <p>Analytics will appear here once you start streaming</p>
            </div>
          </div>
        )}

        {activeTab === 'earnings' && (
          <div className="earnings-content">
            <h2>Earnings</h2>
            <div className="earnings-summary">
              <div className="earnings-card">
                <h3>Total Earnings</h3>
                <p className="earnings-amount">${stats.revenue.toLocaleString()}</p>
              </div>
              <div className="earnings-card">
                <h3>This Month</h3>
                <p className="earnings-amount">$0</p>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'settings' && (
          <div className="settings-content">
            <h2>Artist Settings</h2>
            
            {/* NEW: Streaming Service Status */}
            <div className="settings-section">
              <h3>Streaming Services</h3>
              <div className="service-status-display">
                <div className={`status-item ${streamingServiceReady ? 'ready' : 'not-ready'}`}>
                  <span className="status-icon">{streamingServiceReady ? '✅' : '❌'}</span>
                  <div className="status-info">
                    <strong>Cloud Streaming Services</strong>
                    <p>{streamingServiceReady ? 'Ready for streaming' : 'Services are initializing...'}</p>
                  </div>
                </div>
                {streamingError && (
                  <div className="service-error">
                    <span className="error-icon">⚠️</span>
                    <p>Error: {streamingError}</p>
                  </div>
                )}
              </div>
              <div className="service-endpoints">
                <h4>Service Information</h4>
                <div className="endpoint-info">
                  <p><strong>Streaming Mode:</strong> LiveKit WebRTC</p>
                  <p><strong>Status:</strong> {streamingServiceReady ? 'Connected' : 'Initializing'}</p>
                  <p><strong>Protocol:</strong> WebRTC (Real-time Communication)</p>
                </div>
              </div>
            </div>
            
            <div className="settings-section">
              <h3>Profile Settings</h3>
              <button className="settings-btn" onClick={editProfile}>
                <Edit size={18} />
                <span>Edit Profile Information</span>
              </button>
            </div>
            <div className="settings-section">
              <h3>Account Settings</h3>
              <button className="settings-btn" onClick={() => navigate('/settings')}>
                <Settings size={18} />
                <span>Account Settings</span>
              </button>
            </div>
          </div>
        )}
        
        {/* Fallback for any unhandled tabs */}
        {!['overview', 'streams', 'tracks', 'events', 'analytics', 'earnings', 'settings'].includes(activeTab) && (
          <div className="error-content">
            <h2>Tab not found</h2>
            <p>The selected tab "{activeTab}" is not available.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ArtistStreamingPortal;