// Census ACS (American Community Survey) 5-Year client.
//
// Endpoint: https://api.census.gov/data/{YEAR}/acs/acs5
// Key is OPTIONAL — Census serves anonymous requests and allows keys for
// higher rate ceilings. CORS is supported directly, no proxy needed.
//
// Variables used:
//   B19013_001E — Median household income (USD)
//   B25064_001E — Median gross rent (USD)
//   B01003_001E — Total population (persons)
//   B25003_001E — Occupied housing units (tenure universe)
//   B25003_002E — Owner-occupied housing units
//
// We pull national ("us:1") aggregates on a single refresh. The latest ACS
// 5-Year estimate release lags real-time by ~12 months; we target 2 years
// back to avoid hitting the "not yet released" window.

import apiKeyService from '../apiKeyService'
import { corsFetch } from '../../utils/corsFetch'

const ACS_YEAR = new Date().getFullYear() - 3 // stay safely inside released vintages

const VARIABLES = [
  'B19013_001E', // median household income
  'B25064_001E', // median gross rent
  'B01003_001E', // population
  'B25003_001E', // occupied HU (universe)
  'B25003_002E', // owner-occupied HU
]

function buildUrl(key) {
  const base = `https://api.census.gov/data/${ACS_YEAR}/acs/acs5`
  const params = new URLSearchParams({
    get: VARIABLES.join(','),
    for: 'us:1',
  })
  if (key) params.set('key', key)
  return `${base}?${params}`
}

// Census returns a 2-row tabular array: [header, values].
function parseAcsResponse(data) {
  if (!Array.isArray(data) || data.length < 2) return null
  const [header, row] = data
  const out = {}
  header.forEach((col, i) => { out[col] = row[i] })
  return out
}

function num(v) {
  if (v === null || v === undefined || v === '') return null
  const n = Number(v)
  return Number.isFinite(n) ? n : null
}

function buildSignals(parsed) {
  if (!parsed) return []
  const asOf = new Date().toISOString()
  const period = String(ACS_YEAR)
  const signals = []

  const medIncome = num(parsed.B19013_001E)
  if (medIncome !== null) {
    signals.push({
      id: 'census.med_income.national',
      tag: 'demographics.median_income.national',
      category: 'demographics',
      label: 'US Median Household Income',
      value: medIncome,
      unit: 'USD',
      trend: 'stable',
      delta: null,
      deltaLabel: null,
      period,
      asOf,
      source: `Census ACS 5-Yr (${ACS_YEAR})`,
      sourceUrl: 'https://www.census.gov/programs-surveys/acs',
      reliability: 0.95,
      sentimentHint: 'neutral',
    })
  }

  const medRent = num(parsed.B25064_001E)
  if (medRent !== null) {
    signals.push({
      id: 'census.med_rent.national',
      tag: 'housing.median_rent.national',
      category: 'housing',
      label: 'US Median Gross Rent',
      value: medRent,
      unit: 'USD/mo',
      trend: 'stable',
      delta: null,
      deltaLabel: null,
      period,
      asOf,
      source: `Census ACS 5-Yr (${ACS_YEAR})`,
      sourceUrl: 'https://www.census.gov/programs-surveys/acs',
      reliability: 0.95,
      sentimentHint: 'neutral',
    })
  }

  const pop = num(parsed.B01003_001E)
  if (pop !== null) {
    signals.push({
      id: 'census.population.national',
      tag: 'demographics.population.national',
      category: 'demographics',
      label: 'US Total Population',
      value: pop,
      unit: 'persons',
      trend: 'stable',
      delta: null,
      deltaLabel: null,
      period,
      asOf,
      source: `Census ACS 5-Yr (${ACS_YEAR})`,
      sourceUrl: 'https://www.census.gov/programs-surveys/acs',
      reliability: 0.98,
      sentimentHint: 'neutral',
    })
  }

  const totalHU = num(parsed.B25003_001E)
  const ownerHU = num(parsed.B25003_002E)
  if (totalHU && ownerHU !== null && totalHU > 0) {
    const rate = +((ownerHU / totalHU) * 100).toFixed(1)
    signals.push({
      id: 'census.homeownership.national',
      tag: 'housing.homeownership.national',
      category: 'housing',
      label: 'US Homeownership Rate',
      value: rate,
      unit: '%',
      trend: 'stable',
      delta: null,
      deltaLabel: null,
      period,
      asOf,
      source: `Census ACS 5-Yr (${ACS_YEAR})`,
      sourceUrl: 'https://www.census.gov/programs-surveys/acs',
      reliability: 0.94,
      sentimentHint: 'neutral',
    })
  }

  return signals
}

const censusService = {
  async fetchAll() {
    const key = apiKeyService.getCensusApiKey()
    const res = await corsFetch(buildUrl(key), {
      method: 'GET',
      parse: 'json',
      timeout: 12000,
    })
    if (!res.ok) return { signals: [], error: res.error || 'Census fetch failed' }
    const parsed = parseAcsResponse(res.data)
    if (!parsed) return { signals: [], error: 'Unexpected Census response shape' }
    return { signals: buildSignals(parsed), error: null }
  },
}

export default censusService
