// src/components/widgets/TopAgentsWidget.jsx
import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import {
  getFirestore,
  collection,
  query,
  orderBy,
  limit as qLimit,
  getDocs,
} from 'firebase/firestore';
import StarBadge from '../stars/StarBadge';
import { starTierFromUserDoc } from '../../utils/stars';

/**
 * Top agents by closedDealCount (descending).
 * Requires a Firestore index on users.closedDealCount DESC — see plan §7.
 */
const TopAgentsWidget = ({ limitCount = 5 }) => {
  const [agents, setAgents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const run = async () => {
      try {
        const db = getFirestore();
        const q = query(
          collection(db, 'users'),
          orderBy('closedDealCount', 'desc'),
          qLimit(limitCount)
        );
        const snap = await getDocs(q);
        setAgents(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
      } catch (err) {
        console.warn('TopAgentsWidget error:', err.message);
        setError('Leaderboard not available yet.');
      } finally {
        setLoading(false);
      }
    };
    run();
  }, [limitCount]);

  if (loading) return <div className="top-agents-empty">Loading leaderboard…</div>;
  if (error) return <div className="top-agents-empty">{error}</div>;
  if (agents.length === 0) {
    return <div className="top-agents-empty">No agent activity yet.</div>;
  }

  return (
    <ul className="top-agents-list">
      {agents.map((a, idx) => {
        const closed = a.closedDealCount ?? a.dealCount ?? 0;
        const tier = starTierFromUserDoc({ ...a, closedDealCount: closed });
        const market = a.market || {};
        const marketLabel = [market.city, market.state].filter(Boolean).join(', ');
        return (
          <li key={a.id} className="top-agents-row">
            <span className="top-agents-rank">#{idx + 1}</span>
            <div className="top-agents-body">
              <Link to={`/agent/${a.id}`} className="top-agents-name">
                {a.displayName || 'Anonymous agent'}
              </Link>
              {marketLabel && <div className="top-agents-market">{marketLabel}</div>}
            </div>
            <StarBadge tier={tier} count={closed} size="sm" showCount />
          </li>
        );
      })}
      <style>{`
        .top-agents-list {
          list-style: none;
          padding: 0;
          margin: 0;
          display: flex;
          flex-direction: column;
          gap: 4px;
        }
        .top-agents-row {
          display: flex;
          align-items: center;
          gap: 10px;
          padding: 10px 0;
          border-bottom: 1px solid #f1f5f9;
        }
        .top-agents-row:last-child { border-bottom: none; }
        .top-agents-rank {
          font-size: 13px;
          font-weight: 700;
          color: #9ca3af;
          width: 28px;
        }
        .top-agents-body { flex: 1; min-width: 0; }
        .top-agents-name {
          font-weight: 600;
          color: #0f172a;
          text-decoration: none;
          display: block;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }
        .top-agents-market {
          font-size: 12px;
          color: #6b7280;
        }
        .top-agents-empty {
          text-align: center;
          color: #6b7280;
          padding: 24px 8px;
          font-size: 14px;
        }
      `}</style>
    </ul>
  );
};

export default TopAgentsWidget;
