// src/components/activity/ActivityFeed.jsx
//
// A creator's activity, newest first: the entries the platform writes when
// they go live, plus what they post themselves — plans, releases, clips and
// pictures.

import React, { useCallback, useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { Radio, Disc3, MessageSquare, ImagePlus, Trash2, ExternalLink, Clock, Users } from 'lucide-react';
import { listActivityByUser, deleteActivity, ACTIVITY_TYPES } from '../../services/activityService';
import './ActivityFeed.css';

const ICONS = {
  [ACTIVITY_TYPES.STREAM]: Radio,
  [ACTIVITY_TYPES.PLAN]: Radio,
  [ACTIVITY_TYPES.RELEASE]: Disc3,
  [ACTIVITY_TYPES.MEDIA]: ImagePlus,
  [ACTIVITY_TYPES.UPDATE]: MessageSquare,
};

const toDate = (value) => {
  if (!value) return null;
  if (typeof value.toDate === 'function') return value.toDate();
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
};

const formatWhen = (value) => {
  const date = toDate(value);
  if (!date) return '';
  const diffMs = Date.now() - date.getTime();
  const minutes = Math.round(diffMs / 60000);
  if (minutes >= 0 && minutes < 1) return 'just now';
  if (minutes > 0 && minutes < 60) return `${minutes}m ago`;
  const hours = Math.round(minutes / 60);
  if (hours > 0 && hours < 24) return `${hours}h ago`;
  return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
};

const formatDateTime = (value) => {
  const date = toDate(value);
  return date
    ? date.toLocaleString(undefined, {
        weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit',
      })
    : '';
};

const formatDuration = (ms) => {
  if (!ms || ms < 0) return null;
  const minutes = Math.round(ms / 60000);
  if (minutes < 60) return `${minutes} min`;
  const hours = Math.floor(minutes / 60);
  return `${hours}h ${minutes % 60}m`;
};

const headlineFor = (item) => {
  switch (item.type) {
    case ACTIVITY_TYPES.STREAM:
      return item.stream?.status === 'live'
        ? `Live now — ${item.stream.title}`
        : `Streamed “${item.stream?.title || 'a set'}”`;
    case ACTIVITY_TYPES.PLAN:
      return 'Streaming plan';
    case ACTIVITY_TYPES.RELEASE:
      return `New release — ${item.release?.title || 'untitled'}`;
    case ACTIVITY_TYPES.MEDIA:
      return 'Clips & pictures';
    default:
      return 'Update';
  }
};

const ActivityFeed = ({ userId, isOwner = false, reloadToken = 0, emptyMessage = null }) => {
  const [items, setItems] = useState(null);
  const [error, setError] = useState(null);

  const load = useCallback(async () => {
    if (!userId) { setItems([]); return; }
    try {
      setItems(await listActivityByUser(userId));
    } catch (err) {
      console.warn('[ActivityFeed] load failed:', err.message);
      setError('Could not load activity');
      setItems([]);
    }
  }, [userId]);

  useEffect(() => { load(); }, [load, reloadToken]);

  const handleDelete = async (item) => {
    if (!window.confirm('Delete this activity entry?')) return;
    try {
      await deleteActivity(item.id);
      setItems((prev) => (prev || []).filter((i) => i.id !== item.id));
    } catch (err) {
      setError(err.message || 'Could not delete that entry');
    }
  };

  if (items === null) return <div className="activity-empty">Loading activity…</div>;

  if (error) return <div className="activity-error">{error}</div>;

  if (items.length === 0) {
    return (
      <div className="activity-empty">
        {emptyMessage ||
          (isOwner
            ? 'Nothing here yet — post your streaming plans, a release, or a clip. Going live adds entries here automatically.'
            : 'No activity yet.')}
      </div>
    );
  }

  return (
    <div className="activity-feed">
      {items.map((item) => {
        const Icon = ICONS[item.type] || MessageSquare;
        const isLive = item.type === ACTIVITY_TYPES.STREAM && item.stream?.status === 'live';
        const duration = formatDuration(item.stream?.durationMs);

        return (
          <article key={item.id} className={`activity-item ${isLive ? 'live' : ''}`}>
            <div className="activity-item-icon">
              <Icon size={16} />
            </div>

            <div className="activity-item-body">
              <header className="activity-item-header">
                <span className="activity-item-headline">{headlineFor(item)}</span>
                {isLive && <span className="activity-live-badge">LIVE</span>}
                <span className="activity-item-time">{formatWhen(item.createdAt)}</span>
                {isOwner && (
                  <button
                    type="button"
                    className="activity-delete"
                    onClick={() => handleDelete(item)}
                    title="Delete entry"
                  >
                    <Trash2 size={14} />
                  </button>
                )}
              </header>

              {item.type === ACTIVITY_TYPES.PLAN && item.scheduledFor && (
                <div className="activity-meta">
                  <Clock size={13} />
                  <span>Going live {formatDateTime(item.scheduledFor)}</span>
                </div>
              )}

              {item.type === ACTIVITY_TYPES.STREAM && (
                <div className="activity-meta">
                  {duration && (<><Clock size={13} /><span>{duration}</span></>)}
                  {Boolean(item.stream?.viewerCount) && (
                    <><Users size={13} /><span>{item.stream.viewerCount} viewers</span></>
                  )}
                  {isLive && item.stream?.eventId && (
                    <Link className="activity-watch" to={`/events/${item.stream.eventId}`}>
                      Watch now
                    </Link>
                  )}
                </div>
              )}

              {item.text && <p className="activity-text">{item.text}</p>}

              {item.type === ACTIVITY_TYPES.RELEASE && item.release && (
                <div className="activity-release">
                  {item.release.artworkUrl && (
                    <img src={item.release.artworkUrl} alt={item.release.title} />
                  )}
                  <div>
                    <div className="activity-release-title">{item.release.title}</div>
                    {item.release.releaseDate && (
                      <div className="activity-release-date">
                        Out {formatDateTime(item.release.releaseDate)}
                      </div>
                    )}
                    {item.release.url && (
                      <a
                        href={item.release.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="activity-release-link"
                      >
                        <ExternalLink size={13} />
                        <span>Listen</span>
                      </a>
                    )}
                  </div>
                </div>
              )}

              {Array.isArray(item.media) && item.media.length > 0 && (
                <div className="activity-media">
                  {item.media.map((media) => (
                    <div key={media.id} className="activity-media-item">
                      {media.type === 'clip' ? (
                        <video src={media.url} poster={media.thumbUrl || undefined} controls playsInline />
                      ) : (
                        <img src={media.url} alt={media.title} loading="lazy" />
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          </article>
        );
      })}
    </div>
  );
};

export default ActivityFeed;
