/**
 * VideoLoadingDiagnostic.jsx - Diagnostic test for video loading issues
 * Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\components\debug\VideoLoadingDiagnostic.jsx
 */

import React, { useState, useEffect } from 'react';
import ReplayService from '../../services/recording/ReplayService';
import { getFirestore, doc, getDoc } from 'firebase/firestore';
import { storage } from '../../firebase';
import { ref, listAll, getDownloadURL } from 'firebase/storage';

const VideoLoadingDiagnostic = () => {
  const [diagnosticResults, setDiagnosticResults] = useState([]);
  const [isRunning, setIsRunning] = useState(false);
  const [currentStep, setCurrentStep] = useState('');
  const [eventId] = useState('4S5WjB6vHRSqfoVc6lGK');

  const addResult = (step, status, message, data = null) => {
    const result = {
      step,
      status, // 'success', 'error', 'warning', 'info'
      message,
      data,
      timestamp: new Date().toISOString()
    };
    
    setDiagnosticResults(prev => [...prev, result]);
    console.log(`[${status.toUpperCase()}] ${step}: ${message}`, data);
  };

  const runDiagnostic = async () => {
    setIsRunning(true);
    setDiagnosticResults([]);
    
    try {
      // Step 1: Test Firebase Connection
      setCurrentStep('Testing Firebase Connection');
      addResult('Firebase Connection', 'info', 'Testing Firestore connection...');
      
      const db = getFirestore();
      const testDoc = await getDoc(doc(db, 'test', 'connection'));
      addResult('Firebase Connection', 'success', 'Firestore connection successful');
      
      // Step 2: Test Firebase Storage
      setCurrentStep('Testing Firebase Storage');
      addResult('Firebase Storage', 'info', 'Testing storage connection...');
      
      const storageRef = ref(storage, 'recordings/');
      const storageList = await listAll(storageRef);
      addResult('Firebase Storage', 'success', `Storage connection successful. Found ${storageList.items.length} items`, {
        items: storageList.items.map(item => item.name)
      });
      
      // Step 3: Test ReplayService
      setCurrentStep('Testing ReplayService');
      addResult('ReplayService', 'info', 'Initializing ReplayService...');
      
      const serviceInitialized = await ReplayService.initialize({
        onError: (error) => {
          addResult('ReplayService', 'error', `Service error: ${error.message}`, error);
        },
        onLoadingStateChange: (loading, progress) => {
          addResult('ReplayService', 'info', `Loading: ${loading}, Progress: ${progress}%`);
        }
      });
      
      if (serviceInitialized) {
        addResult('ReplayService', 'success', 'ReplayService initialized successfully');
      } else {
        addResult('ReplayService', 'error', 'ReplayService initialization failed');
      }
      
      // Step 4: Test Event Loading
      setCurrentStep('Testing Event Loading');
      addResult('Event Loading', 'info', `Loading event: ${eventId}`);
      
      const eventData = await ReplayService.loadReplayEvent(eventId);
      if (eventData) {
        addResult('Event Loading', 'success', 'Event loaded successfully', {
          id: eventData.id,
          title: eventData.title,
          videos: Object.keys(eventData.videos?.combined || {}),
          hasVideos: Object.keys(eventData.videos?.combined || {}).length > 0
        });
        
        // Step 5: Test Video URLs
        setCurrentStep('Testing Video URLs');
        if (eventData.videos?.combined) {
          for (const [quality, videoData] of Object.entries(eventData.videos.combined)) {
            try {
              const response = await fetch(videoData.url, { method: 'HEAD' });
              if (response.ok) {
                addResult('Video URL Test', 'success', `${quality} quality video accessible`, {
                  quality,
                  url: videoData.url,
                  size: response.headers.get('content-length'),
                  type: response.headers.get('content-type')
                });
              } else {
                addResult('Video URL Test', 'error', `${quality} quality video not accessible: ${response.status}`, {
                  quality,
                  url: videoData.url,
                  status: response.status
                });
              }
            } catch (error) {
              addResult('Video URL Test', 'error', `${quality} quality video test failed: ${error.message}`, {
                quality,
                url: videoData.url,
                error: error.message
              });
            }
          }
        } else {
          addResult('Video URL Test', 'warning', 'No video data found in event');
        }
      } else {
        addResult('Event Loading', 'error', 'Event not found or failed to load');
      }
      
      // Step 6: Test Storage Structure
      setCurrentStep('Testing Storage Structure');
      addResult('Storage Structure', 'info', 'Checking storage structure...');
      
      try {
        const eventStorageRef = ref(storage, `recordings/${eventId}`);
        const eventStorageList = await listAll(eventStorageRef);
        
        addResult('Storage Structure', 'info', `Found ${eventStorageList.prefixes.length} folders and ${eventStorageList.items.length} files`, {
          folders: eventStorageList.prefixes.map(p => p.name),
          files: eventStorageList.items.map(i => i.name)
        });
        
        // Check combined folder
        const combinedRef = ref(storage, `recordings/${eventId}/combined`);
        try {
          const combinedList = await listAll(combinedRef);
          addResult('Storage Structure', 'success', `Combined folder found with ${combinedList.prefixes.length} quality folders`, {
            qualities: combinedList.prefixes.map(p => p.name)
          });
          
          // Check each quality folder
          for (const qualityFolder of combinedList.prefixes) {
            const qualityList = await listAll(qualityFolder);
            addResult('Storage Structure', 'info', `Quality ${qualityFolder.name} has ${qualityList.items.length} files`, {
              quality: qualityFolder.name,
              files: qualityList.items.map(i => i.name)
            });
          }
        } catch (error) {
          addResult('Storage Structure', 'warning', 'No combined folder found', error);
        }
      } catch (error) {
        addResult('Storage Structure', 'error', `Storage structure check failed: ${error.message}`, error);
      }
      
      // Step 7: Test Firestore Event Document
      setCurrentStep('Testing Firestore Event Document');
      try {
        const eventDoc = await getDoc(doc(db, 'replayEvents', eventId));
        if (eventDoc.exists()) {
          addResult('Firestore Event', 'success', 'Event document found in Firestore', eventDoc.data());
        } else {
          addResult('Firestore Event', 'warning', 'Event document not found in replayEvents collection');
          
          // Check events collection as fallback
          const eventsDoc = await getDoc(doc(db, 'events', eventId));
          if (eventsDoc.exists()) {
            addResult('Firestore Event', 'info', 'Event document found in events collection', eventsDoc.data());
          } else {
            addResult('Firestore Event', 'error', 'Event document not found in any collection');
          }
        }
      } catch (error) {
        addResult('Firestore Event', 'error', `Firestore event check failed: ${error.message}`, error);
      }
      
      setCurrentStep('Diagnostic Complete');
      addResult('Diagnostic', 'success', 'All tests completed');
      
    } catch (error) {
      addResult('Diagnostic', 'error', `Diagnostic failed: ${error.message}`, error);
    } finally {
      setIsRunning(false);
      setCurrentStep('');
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'success': return 'text-green-600';
      case 'error': return 'text-red-600';
      case 'warning': return 'text-yellow-600';
      case 'info': return 'text-blue-600';
      default: return 'text-gray-600';
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'success': return '✅';
      case 'error': return '❌';
      case 'warning': return '⚠️';
      case 'info': return 'ℹ️';
      default: return '•';
    }
  };

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <div className="bg-white rounded-lg shadow-md p-6">
        <h2 className="text-2xl font-bold mb-4">Video Loading Diagnostic</h2>
        <p className="text-gray-600 mb-6">
          This diagnostic will test the video loading system for event ID: <code className="bg-gray-100 px-2 py-1 rounded">{eventId}</code>
        </p>
        
        <div className="mb-6">
          <button
            onClick={runDiagnostic}
            disabled={isRunning}
            className="bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 text-white px-4 py-2 rounded-lg font-medium"
          >
            {isRunning ? 'Running Diagnostic...' : 'Run Diagnostic'}
          </button>
          
          {currentStep && (
            <div className="mt-4 p-3 bg-blue-50 rounded-lg">
              <div className="flex items-center">
                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-blue-600 mr-2"></div>
                <span className="text-blue-700 font-medium">{currentStep}</span>
              </div>
            </div>
          )}
        </div>
        
        {diagnosticResults.length > 0 && (
          <div className="bg-gray-50 rounded-lg p-4">
            <h3 className="text-lg font-semibold mb-4">Diagnostic Results</h3>
            <div className="space-y-3 max-h-96 overflow-y-auto">
              {diagnosticResults.map((result, index) => (
                <div key={index} className="bg-white p-3 rounded border-l-4 border-gray-200">
                  <div className="flex items-start">
                    <span className="mr-2 text-lg">{getStatusIcon(result.status)}</span>
                    <div className="flex-1">
                      <div className="flex items-center justify-between">
                        <span className="font-medium">{result.step}</span>
                        <span className="text-xs text-gray-500">{new Date(result.timestamp).toLocaleTimeString()}</span>
                      </div>
                      <p className={`text-sm ${getStatusColor(result.status)}`}>{result.message}</p>
                      {result.data && (
                        <details className="mt-2">
                          <summary className="text-xs text-gray-500 cursor-pointer hover:text-gray-700">
                            View Details
                          </summary>
                          <pre className="mt-1 text-xs bg-gray-100 p-2 rounded overflow-x-auto">
                            {JSON.stringify(result.data, null, 2)}
                          </pre>
                        </details>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
        
        {diagnosticResults.length > 0 && (
          <div className="mt-6 p-4 bg-blue-50 rounded-lg">
            <h4 className="font-medium text-blue-900 mb-2">Summary</h4>
            <div className="text-sm text-blue-800">
              <p>✅ Success: {diagnosticResults.filter(r => r.status === 'success').length}</p>
              <p>❌ Errors: {diagnosticResults.filter(r => r.status === 'error').length}</p>
              <p>⚠️ Warnings: {diagnosticResults.filter(r => r.status === 'warning').length}</p>
              <p>ℹ️ Info: {diagnosticResults.filter(r => r.status === 'info').length}</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default VideoLoadingDiagnostic;