// src/components/common/UserStatusBadge.jsx
import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { User } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';

const UserStatusBadge = () => {
  const { currentUser } = useAuth();
  const [anonymousUsername, setAnonymousUsername] = useState('');
  
  // Determine if user is anonymous
  const isAnonymous = !currentUser || currentUser.isAnonymous;
  
  // Generate or retrieve anonymous username
  useEffect(() => {
    if (isAnonymous) {
      // Check if a username is already stored in localStorage
      const storedUsername = localStorage.getItem('anonymousUsername');
      
      if (storedUsername) {
        setAnonymousUsername(storedUsername);
      } else {
        // Generate a random username with format: Word + Number
        const adjectives = ['Solar', 'Cosmic', 'Lunar', 'Stellar', 'Quantum', 'Cyber', 'Digital', 'Mystic', 'Astro', 'Neon'];
        const nouns = ['Fox', 'Wolf', 'Eagle', 'Tiger', 'Dragon', 'Lion', 'Hawk', 'Bear', 'Panther', 'Phoenix'];
        
        const randomAdjective = adjectives[Math.floor(Math.random() * adjectives.length)];
        const randomNoun = nouns[Math.floor(Math.random() * nouns.length)];
        const randomNumber = Math.floor(1000 + Math.random() * 9000); // 4 digit number
        
        const username = `${randomAdjective}${randomNoun}${randomNumber}`;
        localStorage.setItem('anonymousUsername', username);
        setAnonymousUsername(username);
      }
    }
  }, [isAnonymous]);
  
  // Get display name
  const displayName = isAnonymous 
    ? `Anonymous (${anonymousUsername})` 
    : (currentUser.displayName || currentUser.email || 'User');
  
  return (
    <div className="user-status-badge">
      <div className="user-status-icon">
        {currentUser && currentUser.photoURL ? (
          <img 
            src={currentUser.photoURL} 
            alt={displayName} 
            className="user-photo"
          />
        ) : (
          <User size={16} />
        )}
      </div>
      <div className="user-status-text">
        <span className="username">
          {displayName}
        </span>
        {isAnonymous && (
          <Link to="/login" className="login-link">
            Login
          </Link>
        )}
      </div>
      
      <style jsx="true">{`
        .user-status-badge {
          display: flex;
          align-items: center;
          padding: 6px 10px;
          background-color: ${isAnonymous ? '#f3f4f6' : '#e0f2fe'};
          border: 1px solid ${isAnonymous ? '#e5e7eb' : '#bfdbfe'};
          border-radius: 6px;
          font-size: 0.875rem;
          margin-bottom: 0.75rem;
          box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
        }
        
        .user-status-icon {
          display: flex;
          align-items: center;
          justify-content: center;
          width: 24px;
          height: 24px;
          background-color: ${isAnonymous ? '#e5e7eb' : '#bfdbfe'};
          border-radius: 50%;
          margin-right: 8px;
          color: ${isAnonymous ? '#4b5563' : '#1d4ed8'};
          overflow: hidden;
        }
        
        .user-photo {
          width: 100%;
          height: 100%;
          object-fit: cover;
        }
        
        .user-status-text {
          display: flex;
          flex-direction: column;
        }
        
        .username {
          font-weight: 500;
          color: ${isAnonymous ? '#4b5563' : '#1d4ed8'};
        }
        
        .login-link {
          font-size: 0.75rem;
          color: #4f46e5;
          text-decoration: underline;
        }
      `}</style>
    </div>
  );
};

export default UserStatusBadge;
