import React, { useRef, useEffect, useCallback } from 'react';

const WaveformVisualizer = ({ 
  audioBuffer, 
  isPlaying, 
  currentTime, 
  duration, 
  onSeek, 
  color = '#4ecdc4',
  height = 100,
  width = 400 
}) => {
  const canvasRef = useRef(null);
  const animationFrameRef = useRef(null);

  const drawWaveform = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas || !audioBuffer) return;

    const ctx = canvas.getContext('2d');
    const { width: canvasWidth, height: canvasHeight } = canvas;
    
    // Clear canvas
    ctx.fillStyle = 'rgba(0, 0, 0, 0.8)';
    ctx.fillRect(0, 0, canvasWidth, canvasHeight);

    // Get audio data
    const channelData = audioBuffer.getChannelData(0);
    const samples = channelData.length;
    const barWidth = canvasWidth / samples;
    
    // Calculate which samples to display (downsample for performance)
    const displaySamples = Math.min(samples, canvasWidth);
    const step = Math.floor(samples / displaySamples);
    
    // Draw waveform
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.7;
    
    for (let i = 0; i < displaySamples; i++) {
      const sample = channelData[i * step];
      const amplitude = Math.abs(sample);
      const barHeight = amplitude * canvasHeight;
      const x = (i / displaySamples) * canvasWidth;
      const y = (canvasHeight - barHeight) / 2;
      
      ctx.fillRect(x, y, Math.max(1, canvasWidth / displaySamples), barHeight);
    }
    
    // Draw progress indicator
    if (duration > 0) {
      const progress = currentTime / duration;
      const progressX = progress * canvasWidth;
      
      // Progress line
      ctx.globalAlpha = 1;
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(progressX - 1, 0, 2, canvasHeight);
      
      // Played section overlay
      ctx.globalAlpha = 0.3;
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, progressX, canvasHeight);
    }
    
    // Draw cue points (if any)
    ctx.globalAlpha = 1;
    ctx.fillStyle = '#ff6b6b';
    // Add cue point logic here if needed
    
  }, [audioBuffer, currentTime, duration, color]);

  useEffect(() => {
    const animate = () => {
      drawWaveform();
      if (isPlaying) {
        animationFrameRef.current = requestAnimationFrame(animate);
      }
    };
    
    if (isPlaying) {
      animate();
    } else {
      drawWaveform();
    }
    
    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, [isPlaying, drawWaveform]);

  const handleCanvasClick = (event) => {
    if (!audioBuffer || !onSeek) return;
    
    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const clickProgress = x / canvas.width;
    const seekTime = clickProgress * duration;
    
    onSeek(seekTime);
  };

  return (
    <canvas
      ref={canvasRef}
      width={width}
      height={height}
      onClick={handleCanvasClick}
      style={{
        cursor: 'pointer',
        borderRadius: '6px',
        border: '1px solid rgba(255, 255, 255, 0.1)'
      }}
    />
  );
};

export default WaveformVisualizer;