// src/utils/stripe-key-checker.js
/**
 * Utility to check for missing or invalid Stripe keys
 * Run this on application startup to detect key issues
 */

import { loadStripe } from '@stripe/stripe-js';

// Check if a Stripe key is valid (basic format check)
const isValidStripeKey = (key) => {
  // Basic format check: pk_test_ or pk_live_ followed by at least 10 chars
  if (!key) return false;
  return /^pk_(test|live)_[a-zA-Z0-9]{10,}$/.test(key);
};

// Detect current environment
const getCurrentEnvironment = () => {
  const hostname = window.location.hostname;

  if (hostname.includes('localhost') || hostname.includes('127.0.0.1')) {
    return 'development';
  } else if (hostname.includes('ondigitalocean.app')) {
    return 'testing';
  } else if (hostname === 'talkstudio.space' || hostname === 'talkstud.io') {
    return 'production';
  }

  return 'unknown';
};

// Log Stripe key status (only in development/testing)
export const checkStripeKeys = () => {
  const environment = getCurrentEnvironment();
  
  // Only run key checks in development or testing
  if (environment === 'production') {
    console.log('🔑 Stripe key checking disabled in production');
    return;
  }
  
  console.group('🔑 Stripe Key Check');
  
  // Check environment variables
  const testKey = import.meta.env.VITE_STRIPE_TEST_PUBLIC_KEY;
  const liveKey = import.meta.env.VITE_STRIPE_LIVE_PUBLIC_KEY;
  
  console.log('VITE_STRIPE_TEST_PUBLIC_KEY:', testKey ? 
    `${testKey.substring(0, 12)}...${testKey.substring(testKey.length - 4)}` : 
    '❌ Missing');
  
  console.log('VITE_STRIPE_LIVE_PUBLIC_KEY:', liveKey ? 
    `${liveKey.substring(0, 12)}...${liveKey.substring(liveKey.length - 4)}` : 
    '❌ Missing');
  
  // Validate format
  if (testKey && !isValidStripeKey(testKey)) {
    console.error('❌ TEST key format is invalid! Must start with pk_test_');
  }
  
  if (liveKey && !isValidStripeKey(liveKey)) {
    console.error('❌ LIVE key format is invalid! Must start with pk_live_');
  }
  
  console.groupEnd();
};

// Test initialization to check if the key works (only in development/testing)
export const testStripeInitialization = async () => {
  const environment = getCurrentEnvironment();
  
  // Only run tests in development or testing
  if (environment === 'production') {
    console.log('🧪 Stripe initialization testing disabled in production');
    return;
  }
  
  try {
    console.group('🧪 Testing Stripe Initialization');
    
    const testKey = import.meta.env.VITE_STRIPE_TEST_PUBLIC_KEY;
    
    if (!testKey) {
      console.error('❌ No test Stripe key available for testing!');
      console.groupEnd();
      return;
    }
    
    console.log('Testing with key:', `${testKey.substring(0, 12)}...${testKey.substring(testKey.length - 4)}`);
    
    try {
      const stripePromise = await loadStripe(testKey);
      if (stripePromise) {
        console.log('✅ Stripe initialized successfully!');
      } else {
        console.error('❌ Stripe returned null instance!');
      }
    } catch (stripeErr) {
      console.error('❌ Stripe initialization failed:', stripeErr.message);
    }
    
    console.groupEnd();
  } catch (err) {
    console.error('Error testing Stripe:', err);
  }
};