// src/components/LiveStreamViewer.jsx
import React, { useState, useEffect, useRef } from 'react';
import { getFirestore, doc, onSnapshot } from 'firebase/firestore';
import { MessageSquare, Volume2, VolumeX, Maximize, Users } from 'lucide-react';

const LiveStreamViewer = ({ onChatToggle }) => {
  const [streamData, setStreamData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [muted, setMuted] = useState(true);
  const [viewerCount, setViewerCount] = useState(0);
  const videoRef = useRef(null);

  useEffect(() => {
    const db = getFirestore();
    const streamRef = doc(db, 'streams', 'currentStream');
    
    const unsubscribe = onSnapshot(streamRef, (docSnapshot) => {
      if (docSnapshot.exists()) {
        const data = docSnapshot.data();
        setStreamData(data);
        setViewerCount(data.viewerCount || 0);
        setLoading(false);
      } else {
        setError('Stream not found');
        setLoading(false);
      }
    }, (err) => {
      console.error('Error getting stream data:', err);
      setError('Failed to load stream');
      setLoading(false);
    });
    
    return () => unsubscribe();
  }, []);

  // Toggle mute state
  const toggleMute = () => {
    if (videoRef.current) {
      videoRef.current.muted = !muted;
      setMuted(!muted);
    }
  };

  // Enter fullscreen
  const enterFullscreen = () => {
    if (videoRef.current && videoRef.current.requestFullscreen) {
      videoRef.current.requestFullscreen().catch(err => {
        console.error('Error attempting to enable fullscreen:', err);
      });
    }
  };

  if (loading) {
    return (
      <div className="w-full h-64 bg-gray-900 flex items-center justify-center">
        <div className="text-white">Loading stream...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="w-full h-64 bg-gray-900 flex items-center justify-center">
        <div className="text-red-400">{error}</div>
      </div>
    );
  }

  return (
    <div className="live-stream-viewer">
      <div className="stream-header bg-gray-800 text-white p-2 flex justify-between items-center">
        <div className="flex items-center">
          <span className="inline-flex items-center px-2 py-1 rounded-md bg-red-600 text-white font-medium text-sm mr-3">
            LIVE
          </span>
          <h3 className="font-medium">{streamData.title || 'Live Stream'}</h3>
        </div>
        <div className="flex items-center space-x-2">
          <span className="flex items-center text-sm">
            <Users size={16} className="mr-1" />
            {viewerCount}
          </span>
        </div>
      </div>

      <div className="stream-content relative">
        {streamData.streamUrl ? (
          <video
            ref={videoRef}
            src={streamData.streamUrl}
            className="w-full"
            autoPlay
            playsInline
            muted={muted}
            controls={false}
          ></video>
        ) : (
          <div className="w-full h-64 bg-gray-900 flex items-center justify-center">
            <div className="text-white">No stream source available</div>
          </div>
        )}

        <div className="stream-controls absolute bottom-4 right-4 flex space-x-2">
          <button 
            className="p-2 rounded-full bg-gray-800 bg-opacity-60 text-white hover:bg-opacity-80 transition"
            onClick={toggleMute}
            title={muted ? "Unmute" : "Mute"}
          >
            {muted ? <VolumeX size={20} /> : <Volume2 size={20} />}
          </button>
          
          <button 
            className="p-2 rounded-full bg-gray-800 bg-opacity-60 text-white hover:bg-opacity-80 transition"
            onClick={enterFullscreen}
            title="Fullscreen"
          >
            <Maximize size={20} />
          </button>
          
          <button 
            className="p-2 rounded-full bg-gray-800 bg-opacity-60 text-white hover:bg-opacity-80 transition"
            onClick={onChatToggle}
            title="Toggle Chat"
          >
            <MessageSquare size={20} />
          </button>
        </div>
      </div>
      
      <div className="stream-footer bg-gray-800 text-white p-2">
        <p className="text-sm">{streamData.description || 'No description available'}</p>
      </div>
    </div>
  );
};

export default LiveStreamViewer;