// Firebase Performance Fix
const fixFirebasePerformance = () => {
  // Replace problematic Firebase Performance initialization
  if (window.firebase && window.firebase.performance) {
    try {
      // Create safer versions of the trace functions
      const originalPerformance = window.firebase.performance();
      const safeTrace = (traceName) => {
        try {
          const originalTrace = originalPerformance.trace(traceName);
          // Add safety check for start method
          if (!originalTrace || typeof originalTrace.start !== 'function') {
            console.log(`Creating safe trace object for: ${traceName}`);
            return {
              start: () => console.log(`Started trace: ${traceName}`),
              stop: () => console.log(`Stopped trace: ${traceName}`),
              putAttribute: () => {},
              incrementMetric: () => {}
            };
          }
          return originalTrace;
        } catch (e) {
          console.warn(`Error in trace creation for ${traceName}:`, e);
          // Return a dummy trace object
          return {
            start: () => console.log(`Started trace: ${traceName}`),
            stop: () => console.log(`Stopped trace: ${traceName}`),
            putAttribute: () => {},
            incrementMetric: () => {}
          };
        }
      };
      
      // Replace the performance method
      const originalPerformanceMethod = window.firebase.performance;
      window.firebase.performance = function() {
        try {
          const perfInstance = originalPerformanceMethod.apply(this, arguments);
          return {
            ...perfInstance,
            trace: safeTrace
          };
        } catch (e) {
          console.warn('Error in firebase.performance():', e);
          // Return a dummy performance object
          return {
            trace: safeTrace
          };
        }
      };
      
      console.log('Firebase Performance patched successfully');
    } catch (e) {
      console.warn('Failed to patch Firebase Performance:', e);
    }
  } else {
    console.warn('Firebase Performance not available, nothing to patch');
  }
};

