// src/components/media/MediaLibrary.jsx
//
// The creator's pictures + short clips in one grid: upload here once, then
// reuse the same items on an activity post or as the visuals behind a set.
//
// Two modes:
//   browse  — manage your library (upload, delete)
//   select  — pick items for something else (`onSelect` receives media refs)

import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Image as ImageIcon, Film, Upload, Trash2, Check, X } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import {
  uploadMedia,
  listMediaByUser,
  deleteMedia,
  mediaRefOf,
  MAX_CLIP_SECONDS,
} from '../../services/mediaLibraryService';
import './MediaLibrary.css';

const formatDuration = (ms) => {
  if (!ms) return null;
  const total = Math.round(ms / 1000);
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, '0')}`;
};

const MediaLibrary = ({
  ownerId = null,
  mode = 'browse',
  filter = null,            // 'image' | 'clip' | null
  selected = [],            // media refs already chosen (select mode)
  onSelect = null,          // (mediaRef) => void
  onDeselect = null,        // (mediaId) => void
  emptyHint = 'Upload pictures and short clips to use on your profile and in your sets.',
}) => {
  const { currentUser } = useAuth();
  const uid = ownerId || currentUser?.uid;
  const isOwner = Boolean(currentUser && uid === currentUser.uid);

  const [items, setItems] = useState(null);
  const [error, setError] = useState(null);
  const [uploading, setUploading] = useState(null); // { name, progress }
  const fileInputRef = useRef(null);

  const load = useCallback(async () => {
    if (!uid) { setItems([]); return; }
    try {
      setItems(await listMediaByUser(uid, { type: filter }));
    } catch (err) {
      console.warn('[MediaLibrary] load failed:', err.message);
      setError('Could not load your media');
      setItems([]);
    }
  }, [uid, filter]);

  useEffect(() => { load(); }, [load]);

  const handleFiles = async (fileList) => {
    const files = Array.from(fileList || []);
    if (!files.length) return;
    setError(null);

    for (const file of files) {
      setUploading({ name: file.name, progress: 0 });
      try {
        const media = await uploadMedia({
          file,
          user: currentUser,
          onProgress: (progress) => setUploading({ name: file.name, progress }),
        });
        setItems((prev) => [media, ...(prev || [])]);
        if (mode === 'select' && onSelect) onSelect(mediaRefOf(media));
      } catch (err) {
        setError(err.message || 'Upload failed');
      }
    }
    setUploading(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleDelete = async (media) => {
    if (!window.confirm(`Delete "${media.title}" from your library?`)) return;
    try {
      await deleteMedia(media);
      setItems((prev) => (prev || []).filter((m) => m.id !== media.id));
      if (onDeselect) onDeselect(media.id);
    } catch (err) {
      setError(err.message || 'Could not delete that item');
    }
  };

  const isSelected = (id) => selected.some((m) => m.id === id);

  const toggle = (media) => {
    if (mode !== 'select') return;
    if (isSelected(media.id)) {
      if (onDeselect) onDeselect(media.id);
    } else if (onSelect) {
      onSelect(mediaRefOf(media));
    }
  };

  const accept = filter === 'image'
    ? 'image/*'
    : filter === 'clip'
      ? 'video/*'
      : 'image/*,video/*';

  return (
    <div className="media-library">
      {isOwner && (
        <div className="media-library-actions">
          <button
            type="button"
            className="media-upload-button"
            onClick={() => fileInputRef.current?.click()}
            disabled={Boolean(uploading)}
          >
            <Upload size={16} />
            <span>
              {uploading
                ? `Uploading ${uploading.name} — ${uploading.progress}%`
                : filter === 'image'
                  ? 'Upload pictures'
                  : filter === 'clip'
                    ? 'Upload clips'
                    : 'Upload pictures or clips'}
            </span>
          </button>
          <span className="media-library-hint">
            Clips up to {MAX_CLIP_SECONDS}s
          </span>
          <input
            ref={fileInputRef}
            type="file"
            accept={accept}
            multiple
            onChange={(e) => handleFiles(e.target.files)}
            style={{ display: 'none' }}
          />
        </div>
      )}

      {uploading && (
        <div className="media-upload-progress">
          <div className="media-upload-bar" style={{ width: `${uploading.progress}%` }} />
        </div>
      )}

      {error && (
        <div className="media-library-error">
          {error}
          <button type="button" onClick={() => setError(null)} aria-label="Dismiss">
            <X size={14} />
          </button>
        </div>
      )}

      {items === null && <div className="media-library-empty">Loading media…</div>}

      {items && items.length === 0 && (
        <div className="media-library-empty">{isOwner ? emptyHint : 'No media yet.'}</div>
      )}

      {items && items.length > 0 && (
        <div className="media-grid">
          {items.map((media) => (
            <div
              key={media.id}
              className={`media-tile ${mode === 'select' ? 'selectable' : ''} ${isSelected(media.id) ? 'selected' : ''}`}
              onClick={() => toggle(media)}
            >
              {media.thumbUrl ? (
                <img src={media.thumbUrl} alt={media.title} loading="lazy" />
              ) : (
                <div className="media-tile-placeholder">
                  {media.type === 'clip' ? <Film size={22} /> : <ImageIcon size={22} />}
                </div>
              )}

              <div className="media-tile-badge">
                {media.type === 'clip' ? <Film size={12} /> : <ImageIcon size={12} />}
                {media.type === 'clip' && formatDuration(media.durationMs) && (
                  <span>{formatDuration(media.durationMs)}</span>
                )}
              </div>

              {mode === 'select' && isSelected(media.id) && (
                <div className="media-tile-check"><Check size={14} /></div>
              )}

              {isOwner && mode === 'browse' && (
                <button
                  type="button"
                  className="media-tile-delete"
                  onClick={(e) => { e.stopPropagation(); handleDelete(media); }}
                  title="Delete"
                >
                  <Trash2 size={14} />
                </button>
              )}

              <div className="media-tile-title">{media.title}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default MediaLibrary;
