import React, { useState, useRef } from 'react';
import { useAudioProfileHybrid } from '../hooks/useAudioProfileHybrid';
import { app } from '../firebase'; // Use the existing Firebase app instance

export const CreateAudioProfileHybrid = () => {
  const [selectedFile, setSelectedFile] = useState(null);
  const [profileName, setProfileName] = useState('');
  const [profileResult, setProfileResult] = useState(null);
  const [roomOnly, setRoomOnly] = useState(false);
  const fileInputRef = useRef(null);
  
  const {
    isReady,
    isAuthenticated,
    currentUser,
    error,
    isLoading,
    createProfile,
    createRoom,
    ensureAuth
  } = useAudioProfileHybrid(app);
  
  const handleFileSelect = (event) => {
    const file = event.target.files[0];
    if (file) {
      setSelectedFile(file);
      setProfileResult(null);
    }
  };
  
  const handleSubmit = async (event) => {
    event.preventDefault();
    
    if (!roomOnly && !selectedFile) {
      alert('Please select an audio file');
      return;
    }
    
    try {
      // Ensure user is authenticated
      if (!isAuthenticated) {
        console.log('User not authenticated, signing in...');
        await ensureAuth();
      }
      
      let result;
      
      if (roomOnly) {
        // Create room only (Realtime Database)
        result = await createRoom({
          name: profileName || 'Untitled Room',
          type: 'audio_room',
          createdBy: currentUser?.uid
        });
      } else {
        // Create full profile (Firestore + Realtime Database)
        const arrayBuffer = await selectedFile.arrayBuffer();
        const blob = new Blob([arrayBuffer], { type: selectedFile.type });
        
        result = await createProfile(blob, {
          name: profileName || 'Untitled Profile',
          originalFileName: selectedFile.name,
          fileType: selectedFile.type,
          fileSize: selectedFile.size
        });
      }
      
      setProfileResult(result);
      setSelectedFile(null);
      setProfileName('');
      setRoomOnly(false);
      
      // Reset file input
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    } catch (err) {
      console.error('Error creating profile/room:', err);
    }
  };
  
  if (!isReady) {
    return <div>Loading Firebase services...</div>;
  }
  
  return (
    <div style={{ 
      padding: '20px', 
      maxWidth: '600px', 
      margin: '0 auto',
      fontFamily: 'Arial, sans-serif'
    }}>
      <h2>Create Audio Profile (Hybrid)</h2>
      
      {/* Authentication Status */}
      <div style={{ 
        marginBottom: '20px',
        padding: '10px',
        backgroundColor: isAuthenticated ? '#e8f5e9' : '#fff3e0',
        borderRadius: '4px'
      }}>
        <strong>Auth Status:</strong> {
          isAuthenticated 
            ? `Authenticated (${currentUser?.uid?.substring(0, 8)}...)`
            : 'Not authenticated (will sign in automatically)'
        }
      </div>
      
      {/* Error Display */}
      {error && (
        <div style={{ 
          marginBottom: '20px',
          padding: '10px',
          backgroundColor: '#ffebee',
          color: '#c62828',
          borderRadius: '4px'
        }}>
          <strong>Error:</strong> {error}
        </div>
      )}
      
      {/* Profile Creation Form */}
      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="profileName" style={{ display: 'block', marginBottom: '5px' }}>
            Profile/Room Name:
          </label>
          <input
            type="text"
            id="profileName"
            value={profileName}
            onChange={(e) => setProfileName(e.target.value)}
            placeholder="Enter profile or room name"
            style={{
              width: '100%',
              padding: '8px',
              border: '1px solid #ddd',
              borderRadius: '4px'
            }}
          />
        </div>
        
        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'flex', alignItems: 'center' }}>
            <input
              type="checkbox"
              checked={roomOnly}
              onChange={(e) => setRoomOnly(e.target.checked)}
              style={{ marginRight: '8px' }}
            />
            Create room only (no audio file)
          </label>
        </div>
        
        {!roomOnly && (
          <div style={{ marginBottom: '15px' }}>
            <label htmlFor="audioFile" style={{ display: 'block', marginBottom: '5px' }}>
              Audio File:
            </label>
            <input
              ref={fileInputRef}
              type="file"
              id="audioFile"
              accept="audio/*"
              onChange={handleFileSelect}
              style={{
                width: '100%',
                padding: '8px',
                border: '1px solid #ddd',
                borderRadius: '4px'
              }}
            />
          </div>
        )}
        
        {selectedFile && !roomOnly && (
          <div style={{ 
            marginBottom: '15px',
            padding: '10px',
            backgroundColor: '#f5f5f5',
            borderRadius: '4px'
          }}>
            <strong>Selected File:</strong> {selectedFile.name} ({(selectedFile.size / 1024 / 1024).toFixed(2)} MB)
          </div>
        )}
        
        <button
          type="submit"
          disabled={isLoading || (!roomOnly && !selectedFile)}
          style={{
            padding: '10px 20px',
            backgroundColor: '#2196F3',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
            opacity: isLoading || (!roomOnly && !selectedFile) ? 0.6 : 1
          }}
        >
          {isLoading ? 'Creating...' : (roomOnly ? 'Create Room' : 'Create Audio Profile')}
        </button>
      </form>
      
      {/* Success Result */}
      {profileResult && (
        <div style={{ 
          marginTop: '20px',
          padding: '15px',
          backgroundColor: '#e8f5e9',
          borderRadius: '4px'
        }}>
          <h3>{profileResult.roomId ? 'Created Successfully!' : 'Profile Created Successfully!'}</h3>
          
          {profileResult.id && (
            <p><strong>Profile ID:</strong> {profileResult.id}</p>
          )}
          
          {profileResult.roomId && (
            <p><strong>Room ID:</strong> {profileResult.roomId}</p>
          )}
          
          {profileResult.audioUrl && (
            <p><strong>Audio URL:</strong> <a href={profileResult.audioUrl} target="_blank" rel="noopener noreferrer">View Audio</a></p>
          )}
          
          {profileResult.fingerprint && (
            <p><strong>Fingerprint Length:</strong> {profileResult.fingerprint.length} values</p>
          )}
          
          <p><strong>Created At:</strong> {new Date().toLocaleString()}</p>
          
          <div style={{ marginTop: '10px' }}>
            <strong>Database Locations:</strong>
            <ul>
              {profileResult.id && <li>Firestore: audioProfiles/{profileResult.id}</li>}
              {profileResult.roomId && <li>Realtime DB: rooms/{profileResult.roomId}</li>}
            </ul>
          </div>
        </div>
      )}
      
      {/* Debug Information */}
      <details style={{ marginTop: '20px' }}>
        <summary style={{ cursor: 'pointer' }}>Debug Information</summary>
        <pre style={{ 
          padding: '10px',
          backgroundColor: '#f5f5f5',
          borderRadius: '4px',
          overflow: 'auto'
        }}>
          {JSON.stringify({
            isReady,
            isAuthenticated,
            currentUser: currentUser ? {
              uid: currentUser.uid,
              isAnonymous: currentUser.isAnonymous
            } : null,
            hasError: !!error,
            isLoading,
            roomOnly
          }, null, 2)}
        </pre>
      </details>
    </div>
  );
};