// VideoPlayer.jsx
// Component for displaying videos in posts with thumbnail and controls

import React, { useState, useRef, useEffect } from 'react';
import { PlayCircle, Pause, Volume2, VolumeX, Maximize } from 'lucide-react';
import './VideoPlayer.css';

const VideoPlayer = ({ video }) => {
  const [showThumbnail, setShowThumbnail] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(video?.duration || 0);
  const videoRef = useRef(null);

  useEffect(() => {
    // Cleanup function to revoke object URLs
    return () => {
      if (videoRef.current) {
        videoRef.current.pause();
      }
    };
  }, []);

  const handleThumbnailClick = () => {
    setShowThumbnail(false);
    if (videoRef.current) {
      videoRef.current.play();
      setIsPlaying(true);
    }
  };

  const handlePlayPause = () => {
    if (!videoRef.current) return;

    if (isPlaying) {
      videoRef.current.pause();
      setIsPlaying(false);
    } else {
      videoRef.current.play();
      setIsPlaying(true);
    }
  };

  const handleMuteToggle = () => {
    if (!videoRef.current) return;
    videoRef.current.muted = !isMuted;
    setIsMuted(!isMuted);
  };

  const handleFullscreen = () => {
    if (!videoRef.current) return;

    if (videoRef.current.requestFullscreen) {
      videoRef.current.requestFullscreen();
    } else if (videoRef.current.webkitRequestFullscreen) {
      videoRef.current.webkitRequestFullscreen();
    } else if (videoRef.current.mozRequestFullScreen) {
      videoRef.current.mozRequestFullScreen();
    } else if (videoRef.current.msRequestFullscreen) {
      videoRef.current.msRequestFullscreen();
    }
  };

  const handleTimeUpdate = () => {
    if (videoRef.current) {
      setCurrentTime(videoRef.current.currentTime);
    }
  };

  const handleLoadedMetadata = () => {
    if (videoRef.current) {
      setDuration(videoRef.current.duration);
    }
  };

  const handleVideoEnded = () => {
    setIsPlaying(false);
    setShowThumbnail(true);
    if (videoRef.current) {
      videoRef.current.currentTime = 0;
    }
  };

  const formatTime = (seconds) => {
    if (isNaN(seconds)) return '0:00';
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  if (!video || !video.url) {
    return null;
  }

  return (
    <div className="video-player-wrapper">
      <div className="video-player-container">
        {showThumbnail && video.thumbnail && (
          <div className="video-thumbnail" onClick={handleThumbnailClick}>
            <img src={video.thumbnail} alt="Video thumbnail" loading="lazy" />
            <div className="play-overlay">
              <PlayCircle size={64} className="play-icon" />
            </div>
            {duration > 0 && (
              <div className="video-duration-badge">
                {formatTime(duration)}
              </div>
            )}
          </div>
        )}

        <video
          ref={videoRef}
          src={video.url}
          className={`video-element ${showThumbnail ? 'hidden' : 'visible'}`}
          controls
          preload="metadata"
          playsInline
          onPlay={() => setIsPlaying(true)}
          onPause={() => setIsPlaying(false)}
          onTimeUpdate={handleTimeUpdate}
          onLoadedMetadata={handleLoadedMetadata}
          onEnded={handleVideoEnded}
        >
          Your browser does not support the video tag.
        </video>
      </div>
    </div>
  );
};

export default VideoPlayer;
