// src/components/posts/CreatePost.jsx
import React, { useState } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { collection, addDoc, serverTimestamp, doc, getDoc } from 'firebase/firestore';
import { ref, uploadBytesResumable, getDownloadURL } from 'firebase/storage';
import { db, storage } from '../../firebase';
import { Send, Image, X, Loader, MapPin, Video } from 'lucide-react';
import videoUploadService from '../../services/VideoUploadService';
import './CreatePost.css';

const CreatePost = ({ onPostCreated }) => {
  const { currentUser } = useAuth();
  const [content, setContent] = useState('');
  const [images, setImages] = useState([]);
  const [video, setVideo] = useState(null);
  const [videoPreview, setVideoPreview] = useState(null);
  const [isPosting, setIsPosting] = useState(false);
  const [error, setError] = useState('');
  const [uploadProgress, setUploadProgress] = useState({});
  const [includeLocation, setIncludeLocation] = useState(false);
  const [location, setLocation] = useState(null);
  const [gettingLocation, setGettingLocation] = useState(false);

  const handleImageSelect = (e) => {
    const files = Array.from(e.target.files);
    if (files.length > 4) {
      setError('You can only upload up to 4 images');
      return;
    }

    const validFiles = files.filter(file => {
      if (file.size > 25 * 1024 * 1024) { // 25MB limit to match Firebase rules
        setError(`${file.name} is too large. Maximum size is 25MB`);
        return false;
      }
      if (!file.type.startsWith('image/')) {
        setError(`${file.name} is not an image`);
        return false;
      }

      // Validate file extension to match Firebase rules
      const validExtensions = ['jpg', 'jpeg', 'png', 'gif', 'webp'];
      const fileExtension = file.name.split('.').pop().toLowerCase();
      if (!validExtensions.includes(fileExtension)) {
        setError(`${file.name} has invalid extension. Use: ${validExtensions.join(', ')}`);
        return false;
      }

      return true;
    });

    // Clear video if images are selected (mutually exclusive)
    if (validFiles.length > 0) {
      removeVideo();
    }

    setImages(validFiles);
    setError('');
  };

  const removeImage = (index) => {
    setImages(images.filter((_, i) => i !== index));
  };

  const handleVideoSelect = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Validate video file
    const validation = videoUploadService.validateVideoFile(file);
    if (!validation.valid) {
      setError(validation.error);
      return;
    }

    // Set video and clear images (mutually exclusive)
    setVideo(file);
    setImages([]);
    setVideoPreview(URL.createObjectURL(file));
    setError('');
  };

  const removeVideo = () => {
    if (videoPreview) {
      URL.revokeObjectURL(videoPreview);
    }
    setVideo(null);
    setVideoPreview(null);
    setUploadProgress({});
  };

  // Get user's current location
  const getCurrentLocation = () => {
    if (!navigator.geolocation) {
      setError('Geolocation is not supported by this browser');
      return;
    }

    setGettingLocation(true);
    setError('');

    navigator.geolocation.getCurrentPosition(
      (position) => {
        setLocation({
          latitude: position.coords.latitude,
          longitude: position.coords.longitude,
          accuracy: position.coords.accuracy
        });
        setGettingLocation(false);
      },
      (error) => {
        console.error('Error getting location:', error);
        setError('Failed to get your location. Please enable location services.');
        setGettingLocation(false);
        setIncludeLocation(false);
      },
      {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 300000 // 5 minutes
      }
    );
  };

  // Handle location checkbox change
  const handleLocationToggle = (checked) => {
    setIncludeLocation(checked);
    if (checked && !location) {
      getCurrentLocation();
    }
  };

  const uploadImages = async () => {
    const uploadedUrls = [];
    
    for (let i = 0; i < images.length; i++) {
      const image = images[i];
      
      // Create proper filename with timestamp and random string
      const timestamp = Date.now();
      const randomString = Math.random().toString(36).substr(2, 9);
      const fileExtension = image.name.split('.').pop().toLowerCase();
      const fileName = `${timestamp}_${randomString}.${fileExtension}`;
      
      // Use correct path format: posts/{userId}/{fileName}
      const storageRef = ref(storage, `posts/${currentUser.uid}/${fileName}`);
      
      console.log(`Uploading image ${i + 1}/${images.length}: ${fileName}`);
      console.log(`Storage path: posts/${currentUser.uid}/${fileName}`);
      console.log(`File type: ${image.type}, Size: ${(image.size / 1024 / 1024).toFixed(2)}MB`);
      
      try {
        const uploadTask = uploadBytesResumable(storageRef, image);
        
        await new Promise((resolve, reject) => {
          uploadTask.on(
            'state_changed',
            (snapshot) => {
              const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
              setUploadProgress(prev => ({ ...prev, [i]: progress }));
              console.log(`Upload progress for image ${i + 1}: ${progress.toFixed(1)}%`);
            },
            (error) => {
              console.error(`Error uploading image ${i + 1}:`, error);
              console.error('Error code:', error.code);
              console.error('Error message:', error.message);
              reject(error);
            },
            async () => {
              try {
                const downloadURL = await getDownloadURL(uploadTask.snapshot.ref);
                uploadedUrls.push(downloadURL);
                console.log(`Image ${i + 1} uploaded successfully:`, downloadURL);
                resolve();
              } catch (error) {
                console.error(`Error getting download URL for image ${i + 1}:`, error);
                reject(error);
              }
            }
          );
        });
      } catch (error) {
        console.error(`Failed to upload image ${i + 1}:`, error);
        
        // Provide more specific error messages
        if (error.code === 'storage/unauthorized') {
          throw new Error('Permission denied. Please make sure you are logged in.');
        } else if (error.code === 'storage/unknown') {
          throw new Error('Upload failed. Please check your internet connection and try again.');
        } else {
          throw new Error(`Upload failed: ${error.message}`);
        }
      }
    }
    
    return uploadedUrls;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!content.trim() && images.length === 0 && !video) {
      setError('Please add some text, images, or a video to your post');
      return;
    }

    if (!currentUser) {
      setError('You must be logged in to create posts');
      return;
    }

    setIsPosting(true);
    setError('');

    try {
      console.log('Starting post creation...');
      console.log('User:', currentUser.uid);
      console.log('Content length:', content.trim().length);
      console.log('Images count:', images.length);
      console.log('Has video:', !!video);

      let imageUrls = [];
      let videoData = null;

      // Upload video if present
      if (video) {
        console.log('Uploading video...');
        try {
          videoData = await videoUploadService.uploadVideoWithThumbnail(
            video,
            currentUser.uid,
            (progress) => {
              setUploadProgress({ video: progress });
            }
          );
          console.log('Video uploaded successfully:', videoData);
        } catch (videoError) {
          console.error('Video upload failed:', videoError);
          throw new Error(`Video upload failed: ${videoError.message}`);
        }
      }

      // Upload images if present (and no video)
      if (images.length > 0) {
        console.log('Uploading images...');
        imageUrls = await uploadImages();
        console.log('All images uploaded successfully:', imageUrls);
      }

      const postData = {
        content: content.trim(),
        images: imageUrls,
        video: videoData,
        authorId: currentUser.uid,
        authorName: currentUser.displayName || 'Anonymous',
        authorPhoto: currentUser.photoURL || '',
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        likes: [],
        likesCount: 0,
        commentsCount: 0,
        isArtist: false // We'll update this based on user data
      };

      // Add location data if user opted to include it
      if (includeLocation && location) {
        postData.location = {
          latitude: location.latitude,
          longitude: location.longitude,
          accuracy: location.accuracy
        };
      }

      // Check if user is an artist
      try {
        const userRef = doc(db, 'users', currentUser.uid);
        const userDoc = await getDoc(userRef);
        if (userDoc.exists() && userDoc.data().isArtist === true) {
          postData.isArtist = true;
        }
      } catch (userError) {
        console.warn('Could not check artist status:', userError);
        // Continue with post creation even if user check fails
      }

      console.log('Creating post document...', postData);
      const postsRef = collection(db, 'posts');
      const docRef = await addDoc(postsRef, postData);
      console.log('Post created successfully with ID:', docRef.id);

      // Reset form
      setContent('');
      setImages([]);
      removeVideo();
      setUploadProgress({});
      setIncludeLocation(false);
      setLocation(null);

      if (onPostCreated) {
        onPostCreated({ id: docRef.id, ...postData });
      }

      // Show success message
      console.log('Post creation completed successfully!');
      
    } catch (err) {
      console.error('Error creating post:', err);
      console.error('Error details:', {
        code: err.code,
        message: err.message,
        stack: err.stack
      });
      
      // Set user-friendly error message
      if (err.message.includes('Permission denied')) {
        setError('You do not have permission to create posts. Please make sure you are logged in.');
      } else if (err.message.includes('Upload failed')) {
        setError(err.message); // Already user-friendly from uploadImages
      } else {
        setError('Failed to create post. Please try again.');
      }
    } finally {
      setIsPosting(false);
    }
  };

  if (!currentUser || currentUser.isAnonymous) {
    return (
      <div className="create-post-container create-post-disabled">
        <div className="disabled-create-post">
          <div className="user-avatar-placeholder">
            <div className="avatar-placeholder">?</div>
          </div>
          <div className="disabled-message">
            <p>Please log in to create posts</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="create-post-container">
      <form onSubmit={handleSubmit}>
        <div className="post-input-wrapper">
          <div className="user-avatar">
            {currentUser.photoURL ? (
              <img src={currentUser.photoURL} alt={currentUser.displayName} />
            ) : (
              <div className="avatar-placeholder">
                {currentUser.displayName?.charAt(0) || 'U'}
              </div>
            )}
          </div>
          
          <div className="post-content-area">
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="What's on your mind?"
              rows={3}
              maxLength={500}
              disabled={isPosting}
            />
            
            {images.length > 0 && (
              <div className="image-preview-container">
                {images.map((image, index) => (
                  <div key={index} className="image-preview">
                    <img src={URL.createObjectURL(image)} alt={`Preview ${index + 1}`} />
                    <button
                      type="button"
                      className="remove-image"
                      onClick={() => removeImage(index)}
                      disabled={isPosting}
                    >
                      <X size={16} />
                    </button>
                    {uploadProgress[index] !== undefined && (
                      <div className="upload-progress">
                        <div
                          className="progress-bar"
                          style={{ width: `${uploadProgress[index]}%` }}
                        />
                        <span className="progress-text">
                          {uploadProgress[index].toFixed(0)}%
                        </span>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}

            {videoPreview && (
              <div className="video-preview-container">
                <video src={videoPreview} controls className="video-preview" />
                <button
                  type="button"
                  className="remove-video"
                  onClick={removeVideo}
                  disabled={isPosting}
                >
                  <X size={20} />
                </button>
                {uploadProgress.video !== undefined && (
                  <div className="video-upload-progress">
                    <div className="progress-info">
                      <span>Uploading video...</span>
                      <span>{uploadProgress.video.toFixed(0)}%</span>
                    </div>
                    <div className="progress-bar-container">
                      <div
                        className="progress-bar"
                        style={{ width: `${uploadProgress.video}%` }}
                      />
                    </div>
                  </div>
                )}
              </div>
            )}
            
            {error && (
              <div className="error-message" style={{
                backgroundColor: '#fee',
                color: '#c00',
                padding: '8px 12px',
                borderRadius: '4px',
                fontSize: '14px',
                marginTop: '8px'
              }}>
                {error}
              </div>
            )}
            
            {/* Location checkbox */}
            <div className="location-section" style={{
              marginTop: '12px',
              padding: '8px 0',
              borderTop: '1px solid #eee'
            }}>
              <label className="location-checkbox" style={{
                display: 'flex',
                alignItems: 'center',
                cursor: 'pointer',
                fontSize: '14px',
                color: '#666'
              }}>
                <input
                  type="checkbox"
                  checked={includeLocation}
                  onChange={(e) => handleLocationToggle(e.target.checked)}
                  disabled={isPosting || gettingLocation}
                  style={{
                    marginRight: '8px'
                  }}
                />
                <MapPin size={16} style={{ marginRight: '6px' }} />
                <span>Include my location</span>
                {gettingLocation && (
                  <Loader size={14} className="spin" style={{ marginLeft: '8px' }} />
                )}
              </label>
              {includeLocation && location && (
                <div className="location-status" style={{
                  marginTop: '4px',
                  fontSize: '12px',
                  color: '#10b981',
                  marginLeft: '24px'
                }}>
                  ✓ Location captured (accuracy: ~{Math.round(location.accuracy)}m)
                </div>
              )}
            </div>
            
            <div className="post-actions">
              <div className="media-buttons">
                <label className="image-upload-button" htmlFor="image-upload">
                  <Image size={20} />
                  <span>Photo</span>
                  <input
                    id="image-upload"
                    type="file"
                    accept="image/jpeg,image/jpg,image/png,image/gif,image/webp"
                    multiple
                    onChange={handleImageSelect}
                    disabled={isPosting || !!video}
                    style={{ display: 'none' }}
                  />
                </label>

                <label className="video-upload-button" htmlFor="video-upload">
                  <Video size={20} />
                  <span>Video</span>
                  <input
                    id="video-upload"
                    type="file"
                    accept="video/mp4,video/webm,video/ogg,video/quicktime"
                    onChange={handleVideoSelect}
                    disabled={isPosting || images.length > 0}
                    style={{ display: 'none' }}
                  />
                </label>
              </div>
              
              <button
                type="submit"
                className="post-button"
                disabled={isPosting || (!content.trim() && images.length === 0 && !video)}
              >
                {isPosting ? (
                  <>
                    <Loader size={16} className="spin" />
                    Posting...
                  </>
                ) : (
                  <>
                    <Send size={16} />
                    Post
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      </form>
    </div>
  );
};

export default CreatePost;