// src/services/roomChatService.js
//
// Chat inside a scheduled room. Messages live under the airing they belong to
// (occurrences/{id}/messages) so a replay keeps the conversation that happened
// during it, and the next week's airing starts clean.
//
// Anyone can read; posting needs a name — an anonymous account is enough,
// which is what the "Chat needs a name" line on Discover refers to.

import {
  getFirestore,
  collection,
  addDoc,
  query,
  orderBy,
  limit as fsLimit,
  onSnapshot,
  serverTimestamp,
} from 'firebase/firestore';
import { app } from '../firebase';

const db = () => getFirestore(app);

const messagesRef = (occurrenceId) =>
  collection(db(), 'occurrences', occurrenceId, 'messages');

/** Live message list, oldest first. Returns an unsubscribe function. */
export function subscribeToRoomChat(occurrenceId, callback, { max = 120 } = {}) {
  if (!occurrenceId) return () => {};
  return onSnapshot(
    query(messagesRef(occurrenceId), orderBy('createdAt', 'desc'), fsLimit(max)),
    (snap) => {
      const rows = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      callback(rows.reverse());
    },
    (err) => {
      console.warn('[roomChat] subscription failed:', err.message);
      callback([]);
    },
  );
}

export async function sendRoomMessage({ occurrenceId, user, text, isHost = false }) {
  const body = (text || '').trim();
  if (!body) return null;
  if (!user || !user.uid) throw new Error('Sign in — or pick a name — to chat');

  const ref = await addDoc(messagesRef(occurrenceId), {
    authorId: user.uid,
    authorName: user.displayName || user.email || 'listener',
    authorPhotoURL: user.photoURL || null,
    isHost,
    body: body.slice(0, 500),
    system: false,
    createdAt: serverTimestamp(),
  });
  return ref.id;
}

/** "tipped €5 ♥" and friends — posted by the app, styled apart from chat. */
export async function postSystemMessage({ occurrenceId, user, text }) {
  if (!occurrenceId || !text) return null;
  const ref = await addDoc(messagesRef(occurrenceId), {
    authorId: user?.uid || 'system',
    authorName: user?.displayName || user?.email || 'someone',
    isHost: false,
    body: text,
    system: true,
    createdAt: serverTimestamp(),
  });
  return ref.id;
}

export default { subscribeToRoomChat, sendRoomMessage, postSystemMessage };
