// Updated EventChatRoom.jsx with proper LiveKit integration to consume artist streams
// Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\components\events\EventChatRoom.jsx

import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { getFirestore, doc, getDoc } from 'firebase/firestore';
import { getDatabase, ref, onValue, push, set, off } from 'firebase/database';
import { 
  MessageCircle, 
  Users, 
  Video, 
  VideoOff, 
  Mic, 
  MicOff, 
  Settings, 
  Send,
  Play,
  Square,
  Crown,
  ArrowLeft,
  Monitor,
  User,
  Lock,
  Camera,
  CameraOff,
  Radio,
  Wifi,
  WifiOff,
  Zap,
  Activity,
  Eye,
  AlertCircle,
  CheckCircle
} from 'lucide-react';

// LiveKit Components
import LiveKitRoom from '../livekit/LiveKitRoom.jsx';
import liveKitService from '../../services/livekit/LiveKitService.js';
import EnhancedTipButton from '../monetization/EnhancedTipButton.jsx';

import './EventChatRoom.css';

const EventChatRoom = () => {
  const { eventId } = useParams();
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  
  // UI State
  const [loading, setLoading] = useState(true);
  const [event, setEvent] = useState(null);
  const [chatRoom, setChatRoom] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [activeUsers, setActiveUsers] = useState({});
  
  // LiveKit Integration - For viewing artist stream
  const [liveKitToken, setLiveKitToken] = useState(null);
  const [liveKitConnected, setLiveKitConnected] = useState(false);
  const [liveKitError, setLiveKitError] = useState(null);
  const [roomName, setRoomName] = useState('');
  const [participantName, setParticipantName] = useState('');
  const [isGeneratingToken, setIsGeneratingToken] = useState(false);
  
  // Detect if component is being rendered in an iframe
  const [isEmbedded, setIsEmbedded] = useState(false);
  
  // Refs
  const messagesEndRef = useRef(null);
  const chatInputRef = useRef(null);

  useEffect(() => {
    // Check if we're in an iframe
    const inIframe = window.self !== window.top;
    setIsEmbedded(inIframe);
  }, []);

  useEffect(() => {
    if (!eventId) {
      navigate('/events');
      return;
    }
    
    loadEventData();
    setupChatRoom();
    
    return () => {
      // Cleanup listeners
      cleanupListeners();
    };
  }, [eventId, currentUser]);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Generate LiveKit viewer token to watch artist stream
  const generateViewerToken = async () => {
    if (!currentUser || !eventId) {
      console.log('❌ Cannot generate token: missing user or eventId');
      return null;
    }

    try {
      setIsGeneratingToken(true);
      setLiveKitError(null);
      
      const roomNameForEvent = `event-${eventId}`;
      const participantNameForUser = currentUser?.displayName || currentUser?.email || 'Viewer';
      
      console.log('🔑 Generating LiveKit viewer token:', {
        roomName: roomNameForEvent,
        participantName: participantNameForUser,
        userId: currentUser.uid
      });

      const token = await liveKitService.generateAccessToken(
        roomNameForEvent,
        participantNameForUser,
        {
          canPublish: false,  // Viewers cannot publish (only watch artist)
          canSubscribe: true, // Viewers can subscribe to artist's stream
        }
      );

      if (token) {
        setLiveKitToken(token);
        setRoomName(roomNameForEvent);
        setParticipantName(participantNameForUser);
        console.log('✅ LiveKit viewer token generated successfully');
        return token;
      } else {
        throw new Error('Token generation returned null');
      }
    } catch (error) {
      console.error('❌ Failed to generate LiveKit viewer token:', error);
      setLiveKitError(`Token generation failed: ${error.message}`);
      return null;
    } finally {
      setIsGeneratingToken(false);
    }
  };

  const loadEventData = async () => {
    try {
      const db = getFirestore();
      const eventDoc = await getDoc(doc(db, 'events', eventId));
      
      if (!eventDoc.exists()) {
        alert('Event not found');
        navigate('/events');
        return;
      }
      
      const eventData = { id: eventDoc.id, ...eventDoc.data() };
      setEvent(eventData);
      
      console.log('🎭 Event loaded for LiveKit viewing:', {
        title: eventData.title,
        artistName: eventData.artistName,
        status: eventData.status,
        eventId: eventId
      });
      
      // Generate viewer token for LiveKit if user is logged in
      if (currentUser) {
        await generateViewerToken();
      }
      
    } catch (error) {
      console.error('Failed to load event:', error);
      navigate('/events');
    }
  };

  const setupChatRoom = () => {
    const rtdb = getDatabase();
    const chatRoomPath = `chats/public/event_${eventId}`;
    console.log('🔗 Setting up chat room listeners for:', chatRoomPath);
    
    // Listen to chat room data
    const chatRoomRef = ref(rtdb, chatRoomPath);
    onValue(chatRoomRef, (snapshot) => {
      const data = snapshot.val();
      console.log('📡 Chat room data received:', data);
      if (data) {
        setChatRoom(data);
        setActiveUsers(data.activeUsers || {});
        console.log('👤 Active users loaded:', Object.keys(data.activeUsers || {}).length);
        setLoading(false);
      } else {
        console.warn('⚠️ No chat room data found at:', chatRoomPath);
        setLoading(false);
      }
    }, (error) => {
      console.error('❌ Error listening to chat room:', error);
      setLoading(false);
    });
    
    // Listen to messages
    const messagesRef = ref(rtdb, `${chatRoomPath}/messages`);
    console.log('💬 Setting up messages listener for:', `${chatRoomPath}/messages`);
    onValue(messagesRef, (snapshot) => {
      const data = snapshot.val();
      console.log('📨 Messages data received:', data);
      if (data) {
        const messagesList = Object.entries(data).map(([id, message]) => ({
          id,
          ...message
        })).sort((a, b) => a.timestamp - b.timestamp);
        console.log('📋 Processed messages:', messagesList.length);
        setMessages(messagesList);
      } else {
        console.log('📭 No messages found, setting empty array');
        setMessages([]);
      }
    }, (error) => {
      console.error('❌ Error listening to messages:', error);
    });
    
    // Add user to active users if logged in
    if (currentUser) {
      const userRef = ref(rtdb, `${chatRoomPath}/activeUsers/${currentUser.uid}`);
      console.log('👤 Adding user to active users:', currentUser.uid);
      set(userRef, {
        uid: currentUser.uid,
        name: currentUser.displayName || 'Viewer',
        avatar: currentUser.photoURL || null,
        joinedAt: Date.now(),
        isStreaming: false,
        isViewing: true,
        viewingLiveKit: true // Flag to indicate LiveKit viewing
      }).catch(error => {
        console.error('❌ Error adding user to active users:', error);
      });
      
      // Remove user on unmount
      return () => {
        console.log('🧹 Removing user from active users on cleanup');
        set(userRef, null);
      };
    }
  };

  const cleanupListeners = () => {
    if (eventId) {
      const rtdb = getDatabase();
      const chatRoomPath = `chats/public/event_${eventId}`;
      off(ref(rtdb, chatRoomPath));
      off(ref(rtdb, `${chatRoomPath}/messages`));
    }
  };

  const sendMessage = async () => {
    if (!newMessage.trim()) {
      console.log('⚠️ Message is empty, not sending');
      return;
    }
    
    if (!currentUser) {
      console.log('❌ User not authenticated, cannot send message');
      alert('Please log in to send messages');
      return;
    }
    
    const rtdb = getDatabase();
    const messagesPath = `chats/public/event_${eventId}/messages`;
    const messagesRef = ref(rtdb, messagesPath);
    
    const messageData = {
      type: 'user',
      message: newMessage.trim(),
      timestamp: Date.now(),
      userId: currentUser.uid,
      userName: currentUser.displayName || currentUser.email || 'User',
      userAvatar: currentUser.photoURL || null
    };
    
    console.log('🚀 Sending message to:', messagesPath);
    console.log('📝 Message data:', messageData);
    
    try {
      const result = await push(messagesRef, messageData);
      console.log('✅ Message sent successfully:', result.key);
      setNewMessage('');
      chatInputRef.current?.focus();
      
      // Also update the total message count in the chat room
      const chatRoomRef = ref(rtdb, `chats/public/event_${eventId}/totalMessages`);
      const currentCount = chatRoom?.totalMessages || 0;
      await set(chatRoomRef, currentCount + 1);
      
    } catch (error) {
      console.error('❌ Failed to send message:', error);
      
      if (error.code === 'PERMISSION_DENIED') {
        alert('Permission denied. Please check your login status and try again.');
      } else {
        alert('Failed to send message. Please try again.');
      }
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  // LiveKit event handlers
  const handleLiveKitConnected = (room) => {
    setLiveKitConnected(true);
    setLiveKitError(null);
    console.log('✅ LiveKit room connected as viewer:', {
      roomName: room?.name,
      participants: room?.participants?.size || 0
    });
  };

  const handleLiveKitDisconnected = () => {
    setLiveKitConnected(false);
    console.log('❌ LiveKit room disconnected');
  };

  const handleLiveKitError = (error) => {
    setLiveKitError(`Connection error: ${error.message}`);
    setLiveKitConnected(false);
    console.error('❌ LiveKit room error:', error);
  };

  const retryLiveKitConnection = async () => {
    console.log('🔄 Retrying LiveKit connection...');
    await generateViewerToken();
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const formatTime = (timestamp) => {
    return new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const isAnonymousUser = () => {
    return !currentUser;
  };

  if (loading) {
    return (
      <div className="event-chat-loading">
        <div className="loading-spinner"></div>
        <p>Loading event chat...</p>
      </div>
    );
  }

  return (
    <div className={`event-chat-room ${isEmbedded ? 'embedded' : ''}`}>
      
      {/* Header - Hidden when embedded */}
      {!isEmbedded && (
        <div className="chat-room-header">
          <button className="back-btn" onClick={() => navigate('/events')}>
            <ArrowLeft size={20} />
          </button>
          <div className="event-info">
            <h2>{event?.title}</h2>
            <p>{event?.artistName} • {Object.keys(activeUsers).length} viewers</p>
          </div>
          <div className="event-status">
            <div className={`status-indicator ${event?.status}`}>
              {event?.status?.toUpperCase()}
            </div>
            {/* LiveKit status indicator */}
            <div className="livekit-status" title={liveKitConnected ? 'LiveKit Connected' : 'LiveKit Disconnected'}>
              {liveKitConnected ? (
                <Zap className="text-green-500" size={16} />
              ) : (
                <WifiOff className="text-gray-500" size={16} />
              )}
            </div>
          </div>
        </div>
      )}

      <div className={`chat-room-body ${isEmbedded ? 'embedded-body' : ''}`}>
        {/* Video Area - LiveKit Artist Stream Viewer */}
        {!isEmbedded && (
          <div className="video-pane">
            <div className="main-video-container">
              {liveKitToken && roomName ? (
                <div className="livekit-viewer-container">
                  <LiveKitRoom
                    roomName={roomName}
                    participantName={participantName}
                    token={liveKitToken}
                    onConnected={handleLiveKitConnected}
                    onDisconnected={handleLiveKitDisconnected}
                    onError={handleLiveKitError}
                    className="artist-stream-viewer"
                    options={{
                      video: true,
                      audio: true,
                      // Viewer-specific options
                      adaptiveStream: true,
                      dynacast: true,
                    }}
                  />
                  
                  {/* Artist Badge Overlay */}
                  <div className="video-overlay">
                    <div className="artist-badge">
                      <Crown size={16} />
                      <span>{event?.artistName}</span>
                      <span className="livekit-badge">⚡ LiveKit</span>
                    </div>
                    
                    {/* Connection Status */}
                    <div className="connection-status-overlay">
                      {liveKitConnected ? (
                        <div className="status-connected">
                          <CheckCircle size={14} />
                          <span>Live</span>
                        </div>
                      ) : (
                        <div className="status-connecting">
                          <Wifi size={14} />
                          <span>Connecting...</span>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              ) : (
                <div className="no-main-video">
                  {currentUser ? (
                    <div className="connecting-video">
                      {isGeneratingToken ? (
                        <>
                          <div className="loading-spinner-small"></div>
                          <p>Generating access token...</p>
                        </>
                      ) : liveKitError ? (
                        <>
                          <AlertCircle size={48} className="text-red-500" />
                          <p className="error-message">Connection Failed</p>
                          <p className="error-details">{liveKitError}</p>
                          <button onClick={retryLiveKitConnection} className="retry-btn">
                            Retry Connection
                          </button>
                        </>
                      ) : (
                        <>
                          <Zap size={48} className="text-blue-500" />
                          <p>Connecting to LiveKit stream...</p>
                          <button onClick={generateViewerToken} className="retry-btn">
                            Connect to Stream
                          </button>
                        </>
                      )}
                    </div>
                  ) : (
                    <div className="anonymous-video-overlay">
                      <Lock size={24} />
                      <p>Register to view live streams</p>
                      <button className="register-btn" onClick={() => navigate('/register')}>
                        Register Now
                      </button>
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* LiveKit Stream Info */}
            {liveKitConnected && (
              <div className="stream-info-overlay">
                <div className="stream-stats">
                  <div className="stat-item">
                    <Eye size={14} />
                    <span>Watching Live</span>
                  </div>
                  <div className="stat-item">
                    <Zap size={14} className="text-green-500" />
                    <span>Ultra-Low Latency</span>
                  </div>
                  <div className="stat-item">
                    <Activity size={14} />
                    <span>Room: {roomName}</span>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {/* Chat Pane */}
        <div className={`chat-pane ${isEmbedded ? 'embedded-chat' : ''}`}>
          
          {/* LiveKit Connection Status */}
          <div className="livekit-connection-info">
            <h4>
              <Zap size={16} className={liveKitConnected ? 'text-green-500' : 'text-gray-500'} />
              Artist Stream
            </h4>
            
            {currentUser ? (
              <div className="connection-status-detail">
                {liveKitConnected ? (
                  <div className="status-connected">
                    <CheckCircle size={16} className="text-green-500" />
                    <span>Connected to {event?.artistName}'s stream</span>
                  </div>
                ) : liveKitError ? (
                  <div className="status-error">
                    <AlertCircle size={16} className="text-red-500" />
                    <span>Connection failed</span>
                    <button onClick={retryLiveKitConnection} className="retry-btn-small">
                      Retry
                    </button>
                  </div>
                ) : isGeneratingToken ? (
                  <div className="status-loading">
                    <div className="loading-spinner-tiny"></div>
                    <span>Connecting...</span>
                  </div>
                ) : (
                  <div className="status-disconnected">
                    <WifiOff size={16} className="text-gray-500" />
                    <span>Not connected</span>
                    <button onClick={generateViewerToken} className="connect-btn-small">
                      Connect
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="anonymous-connection">
                <p>Login to watch the live stream</p>
                <button className="login-btn-small" onClick={() => navigate('/login')}>
                  Login
                </button>
              </div>
            )}
          </div>

          {/* Chat Messages */}
          <div className="chat-messages">
            <div className="messages-header">
              <MessageCircle size={16} />
              <span>Event Chat</span>
              <span className="message-count">({messages.length})</span>
            </div>
            
            <div className="messages-container">
              {messages.map((message) => (
                <div key={message.id} className={`message ${message.type}`}>
                  {message.type === 'system' ? (
                    <div className="system-message">
                      <span className="system-text">{message.message}</span>
                      <span className="message-time">{formatTime(message.timestamp)}</span>
                    </div>
                  ) : (
                    <div className="user-message">
                      <div className="message-avatar">
                        {message.userAvatar ? (
                          <img src={message.userAvatar} alt={message.userName} />
                        ) : (
                          <div className="avatar-placeholder">
                            {message.userName?.charAt(0) || 'A'}
                          </div>
                        )}
                      </div>
                      <div className="message-content">
                        <div className="message-header">
                          <span className="message-author">
                            {message.userName}
                            {message.isArtist && (
                              <Crown size={12} className="artist-badge" />
                            )}
                          </span>
                          <span className="message-time">{formatTime(message.timestamp)}</span>
                        </div>
                        <p className="message-text">{message.message}</p>
                      </div>
                    </div>
                  )}
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>
          </div>

          {/* Tipping Section */}
          {!isEmbedded && event && (
            <div className="tipping-section">
              <EnhancedTipButton 
                event={event}
                artistId={event?.artistId}
                venueId={event?.venueId}
                size="small"
                showAmountSelector={true}
                onTipStart={(tipRecord) => {
                  console.log('🎁 Tip started in EventChatRoom:', tipRecord);
                  // Optional: Show tip started message in chat
                }}
                onTipComplete={(tipRecord) => {
                  console.log('✅ Tip completed in EventChatRoom:', tipRecord);
                  // Optional: Show tip completed message in chat
                }}
              />
            </div>
          )}

          {/* Chat Input */}
          <div className="chat-input-container">
            <div className="chat-input">
              <input
                ref={chatInputRef}
                type="text"
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                onKeyPress={handleKeyPress}
                placeholder={isAnonymousUser() ? "Please login to chat" : "Type a message..."}
                maxLength={500}
                disabled={isAnonymousUser()}
              />
              <button 
                className="send-btn"
                onClick={sendMessage}
                disabled={!newMessage.trim() || isAnonymousUser()}
              >
                <Send size={16} />
              </button>
            </div>
            {isAnonymousUser() && (
              <div className="anonymous-note">
                <p>You're viewing anonymously. <button onClick={() => navigate('/login')}>Login</button> to chat and watch the live stream.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default EventChatRoom;