// src/components/widgets/PostsWidget.jsx
import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { 
  getDB, 
  collection, 
  query, 
  orderBy, 
  limit, 
  onSnapshot 
} from '../../utils/firebase-utils';
import { useAuth } from '../../contexts/AuthContext';
import { Heart, MessageCircle } from 'lucide-react';
import LikeService from '../../services/LikeService';
import './PostsWidget.css';
import { startTiming, endTiming } from '../../utils/performance-monitor';

const PostsWidget = ({ limit: itemLimit = 5, onSelectPost, onError, onLoaded }) => {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [likedPosts, setLikedPosts] = useState({});
  const [processingLikes, setProcessingLikes] = useState({});
  const [showCommentModal, setShowCommentModal] = useState(false);
  const [selectedPostForComment, setSelectedPostForComment] = useState(null);
  const [commentText, setCommentText] = useState('');
  const [submittingComment, setSubmittingComment] = useState(false);
  const { currentUser } = useAuth();
  
  useEffect(() => {
    startTiming('PostsWidget:initialization');
    
    // Add a very short timeout to prevent hanging
    const timeoutId = setTimeout(() => {
      console.warn('PostsWidget initialization timed out - forcing fallback data');
      setPosts([
        {
          id: 'timeout-fallback-1',
          title: 'Timeout Occurred',
          content: 'The database connection timed out. Using fallback data.',
          createdAt: new Date(),
          userId: 'system',
          username: 'System',
          likes: 0,
          comments: 0
        }
      ]);
      setLoading(false);
      if (onLoaded) onLoaded();
      endTiming('PostsWidget:initialization');
    }, 3000); // 3 second timeout
    // Get db instance using the utility function to ensure proper region handling
    const db = getDB();
    if (!db) {
      console.error('Firestore database not available');
      setError('Database connection failed. Please try again later.');
      setLoading(false);
      onError && onError('Database connection failed');
      clearTimeout(timeoutId); // Clear the timeout
      endTiming('PostsWidget:initialization');
      return () => {};
    }
    
    console.log('Setting up posts subscription');
    
    try {
      startTiming('PostsWidget:query');
      // Create a query for the 'posts' collection directly at the root level
      const postsCollection = collection(db, 'posts');
      const postsQuery = query(
        postsCollection,
        orderBy('createdAt', 'desc'),
        limit(itemLimit)
      );
      endTiming('PostsWidget:query');
      
      // Provide fallback data for permission issues or empty state
      const fallbackPosts = [
        {
          id: 'getting-started',
          title: 'Getting Started Guide',
          content: 'Learn how to create posts, join discussions, and connect with other users.',
          createdAt: new Date(Date.now() - 86400000 * 2), // 2 days ago
          userId: 'system',
          username: 'TalkStudio',
          likesCount: 3,
          commentCount: 1,
          imageUrls: []
        },
        {
          id: 'welcome-post',
          title: 'Welcome to TalkStudio',
          content: 'Join our community and start conversations with others. Share your thoughts and ideas!',
          createdAt: new Date(Date.now() - 86400000), // 1 day ago
          userId: 'system',
          username: 'TalkStudio',
          likesCount: 5,
          commentCount: 2,
          imageUrls: []
        }
      ];
      
      // Set up real-time listener with error handling
      startTiming('PostsWidget:subscription');
      const unsubscribe = onSnapshot(
        postsQuery,
        (querySnapshot) => {
          startTiming('PostsWidget:dataProcessing');
          const postsList = [];
          querySnapshot.forEach((doc) => {
            postsList.push({
              id: doc.id,
              ...doc.data(),
              // Handle potential missing or invalid dates
              createdAt: doc.data().createdAt ? 
                (doc.data().createdAt.toDate ? doc.data().createdAt.toDate() : doc.data().createdAt) : 
                new Date(),
              // Include image URLs if they exist
              imageUrls: doc.data().imageUrls || [],
              likesCount: doc.data().likesCount || 0,
              commentCount: doc.data().commentCount || 0
            });
          });
          
          console.log('Posts loaded:', postsList.length);
          
          // If no posts were found, use fallback data
          if (postsList.length === 0) {
            setPosts(fallbackPosts);
          } else {
            setPosts(postsList);
          }
          
          setLoading(false);
          setError(null);
          endTiming('PostsWidget:dataProcessing');
          
          // Clear the timeout since we completed successfully
          clearTimeout(timeoutId);
          
          // Notify parent component that posts are loaded
          if (onLoaded) {
            onLoaded();
          }
          endTiming('PostsWidget:initialization');
        },
        (err) => {
          startTiming('PostsWidget:errorHandling');
          console.error('Error getting posts:', err);
          
          // Still provide fallback data
          setPosts(fallbackPosts);
          setError(null); // Don't show error to user since we have fallback data
          setLoading(false);
          
          // Clear the timeout since we completed with fallback data
          clearTimeout(timeoutId);
          
          // Notify parent component
          if (onLoaded) {
            onLoaded();
          }
          endTiming('PostsWidget:errorHandling');
          endTiming('PostsWidget:initialization');
        }
      );
      
      // Clean up the subscription when the component unmounts
      return () => {
        startTiming('PostsWidget:unsubscribe');
        clearTimeout(timeoutId); // Ensure timeout is cleared on unmount
        unsubscribe();
        endTiming('PostsWidget:unsubscribe');
      };
    } catch (err) {
      startTiming('PostsWidget:setupError');
      console.error('Error setting up posts subscription:', err);
      setError(`Failed to set up posts subscription: ${err.message}`);
      setLoading(false);
      onError && onError(err.message);
      
      // Clear the timeout since we have an error
      clearTimeout(timeoutId);
      
      endTiming('PostsWidget:setupError');
      endTiming('PostsWidget:initialization');
      return () => {};
    }
  }, [itemLimit, onError]);
  
  // Check liked status for all posts when user or posts change
  useEffect(() => {
    const checkLikedStatus = async () => {
      if (!currentUser || posts.length === 0) return;
      
      const likedStatus = {};
      for (const post of posts) {
        try {
          const isLiked = await LikeService.isPostLiked(post.id);
          likedStatus[post.id] = isLiked;
        } catch (error) {
          console.error('Error checking like status for post:', post.id, error);
          likedStatus[post.id] = false;
        }
      }
      setLikedPosts(likedStatus);
    };
    
    checkLikedStatus();
  }, [currentUser, posts]);
  
  // Function to format dates
  const formatDate = (date) => {
    if (!date) return 'Unknown date';
    
    try {
      // Handle both Date objects and Firestore timestamps
      const dateObj = date instanceof Date ? date : 
                     (date.toDate ? date.toDate() : new Date(date));
      
      return new Intl.DateTimeFormat('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric'
      }).format(dateObj);
    } catch (err) {
      console.error('Error formatting date:', err);
      return 'Invalid date';
    }
  };
  
  // Function to truncate text
  const truncateText = (text, maxLength = 100) => {
    if (!text) return '';
    if (text.length <= maxLength) return text;
    return text.substring(0, maxLength) + '...';
  };
  
  // Function to handle post click
  const handlePostClick = (post) => {
    if (onSelectPost) {
      onSelectPost(post);
    }
  };
  
  // Function to handle like toggle
  const handleLikeToggle = async (e, postId) => {
    e.stopPropagation(); // Prevent triggering post click
    
    if (!currentUser) {
      alert('Please log in to like posts');
      return;
    }
    
    if (processingLikes[postId]) return;
    
    try {
      setProcessingLikes(prev => ({ ...prev, [postId]: true }));
      
      // Optimistic UI update
      const currentlyLiked = likedPosts[postId];
      setLikedPosts(prev => ({ ...prev, [postId]: !currentlyLiked }));
      
      // Update likes count optimistically
      setPosts(prevPosts => 
        prevPosts.map(post => 
          post.id === postId 
            ? { ...post, likesCount: currentlyLiked ? post.likesCount - 1 : post.likesCount + 1 }
            : post
        )
      );
      
      // Call the like service
      const result = await LikeService.togglePostLike(postId);
      
      // Update with actual result from server
      setLikedPosts(prev => ({ ...prev, [postId]: result.liked }));
      setPosts(prevPosts => 
        prevPosts.map(post => 
          post.id === postId 
            ? { ...post, likesCount: result.likesCount }
            : post
        )
      );
    } catch (error) {
      console.error('Error toggling like:', error);
      // Revert on error
      setLikedPosts(prev => ({ ...prev, [postId]: !likedPosts[postId] }));
      alert('Failed to update like status. Please try again.');
    } finally {
      setProcessingLikes(prev => ({ ...prev, [postId]: false }));
    }
  };
  
  // Function to handle comment button click
  const handleCommentClick = (e, post) => {
    e.stopPropagation();
    
    if (!currentUser) {
      alert('Please log in to comment on posts');
      return;
    }
    
    setSelectedPostForComment(post);
    setShowCommentModal(true);
    setCommentText('');
  };
  
  // Function to submit comment
  const handleCommentSubmit = async () => {
    if (!commentText.trim() || !selectedPostForComment || submittingComment) return;
    
    try {
      setSubmittingComment(true);
      
      // Import CommentService dynamically
      const CommentService = (await import('../../services/CommentService')).default;
      
      // Add comment
      await CommentService.addComment(selectedPostForComment.id, commentText.trim());
      
      // Update comment count
      setPosts(prevPosts => 
        prevPosts.map(post => 
          post.id === selectedPostForComment.id 
            ? { ...post, commentCount: (post.commentCount || 0) + 1 }
            : post
        )
      );
      
      // Close modal and reset
      setShowCommentModal(false);
      setSelectedPostForComment(null);
      setCommentText('');
    } catch (error) {
      console.error('Error adding comment:', error);
      alert('Failed to add comment. Please try again.');
    } finally {
      setSubmittingComment(false);
    }
  };
  
  if (loading) {
    return (
      <div className="posts-widget">
        <div className="loading-indicator">
          Loading posts...
        </div>
      </div>
    );
  }
  
  if (error) {
    return (
      <div className="posts-widget error">
        <div className="error-message">
          {error}
        </div>
      </div>
    );
  }
  
  if (posts.length === 0) {
    return (
      <div className="posts-widget empty">
        <p>No posts available. Be the first to create a post!</p>
      </div>
    );
  }
  
  return (
    <div className="posts-widget">
      <ul className="posts-list">
        {posts.map((post) => (
          <li 
            key={post.id} 
            className="post-item"
            onClick={() => handlePostClick(post)}
          >
            <div className="post-header">
              <h3 className="post-title">{post.title}</h3>
              <span className="post-date">
                {formatDate(post.createdAt)}
              </span>
            </div>
            
            <div className="post-author">
              {post.username ? `Posted by ${post.username}` : 'Anonymous'}
            </div>
            
            <div className="post-preview">
              {truncateText(post.content, 120)}
            </div>
            
            {/* Display images if available */}
            {post.imageUrls && post.imageUrls.length > 0 && (
              <div className="post-images">
                {post.imageUrls.slice(0, 2).map((imageUrl, index) => (
                  <img 
                    key={index}
                    src={imageUrl} 
                    alt={`Post image ${index + 1}`}
                    className="post-image-thumbnail"
                    onClick={(e) => e.stopPropagation()}
                  />
                ))}
                {post.imageUrls.length > 2 && (
                  <div className="more-images">+{post.imageUrls.length - 2}</div>
                )}
              </div>
            )}
            
            <div className="post-meta">
              <button 
                className={`like-button ${likedPosts[post.id] ? 'liked' : ''}`}
                onClick={(e) => handleLikeToggle(e, post.id)}
                disabled={processingLikes[post.id]}
              >
                <Heart 
                  size={16} 
                  fill={likedPosts[post.id] ? '#ef4444' : 'none'}
                  color={likedPosts[post.id] ? '#ef4444' : '#6b7280'}
                />
                <span>{post.likesCount || 0}</span>
              </button>
              <button 
                className="comment-button"
                onClick={(e) => handleCommentClick(e, post)}
              >
                <MessageCircle size={16} />
                <span>{post.commentCount || 0}</span>
              </button>
              {post.topic && (
                <span className="post-topic">
                  #{post.topic}
                </span>
              )}
            </div>
          </li>
        ))}
      </ul>
      
      {/* Comment Modal */}
      {showCommentModal && selectedPostForComment && (
        <div className="comment-modal-overlay" onClick={() => setShowCommentModal(false)}>
          <div className="comment-modal" onClick={(e) => e.stopPropagation()}>
            <div className="comment-modal-header">
              <h3>Add a comment</h3>
              <button 
                className="close-button" 
                onClick={() => setShowCommentModal(false)}
              >
                ×
              </button>
            </div>
            <div className="comment-modal-body">
              <div className="post-info">
                <strong>{selectedPostForComment.title}</strong>
                <p>{truncateText(selectedPostForComment.content, 100)}</p>
              </div>
              <textarea
                className="comment-input"
                placeholder="Write your comment..."
                value={commentText}
                onChange={(e) => setCommentText(e.target.value)}
                rows={4}
                maxLength={500}
              />
              <div className="comment-actions">
                <span className="char-count">{commentText.length}/500</span>
                <button 
                  className="submit-comment-button"
                  onClick={handleCommentSubmit}
                  disabled={!commentText.trim() || submittingComment}
                >
                  {submittingComment ? 'Posting...' : 'Post Comment'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PostsWidget;