// src/services/profiles/ProfileService.js
import { 
  getFirestore, 
  doc, 
  getDoc, 
  setDoc, 
  updateDoc, 
  serverTimestamp, 
  collection,
  query,
  where,
  onSnapshot,
  orderBy,
  limit
} from 'firebase/firestore';

/**
 * Create a new profile for a user
 * @param {string} userId - The user ID
 * @param {Object} userData - User data from authentication
 * @returns {Promise<void>}
 */
export const createProfile = async (userId, userData) => {
  if (!userId) {
    throw new Error('User ID is required to create a profile');
  }
  
  const db = getFirestore();
  const profileRef = doc(db, 'profiles', userId);
  
  try {
    // Check if profile already exists
    const profileDoc = await getDoc(profileRef);
    
    if (!profileDoc.exists()) {
      // Create a new profile document
      const profileData = {
        userId,
        displayName: userData?.displayName || 'Anonymous User',
        email: userData?.email || null,
        photoURL: userData?.photoURL || null,
        username: userData?.username || null,
        status: 'online',
        lastActive: serverTimestamp(),
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        isOnline: true
      };
      
      await setDoc(profileRef, profileData);
      console.log(`Created new profile for user ${userId}`);
      
      return profileData;
    } else {
      console.log(`Profile already exists for user ${userId}`);
      return profileDoc.data();
    }
  } catch (error) {
    console.error('Error creating user profile:', error);
    throw error;
  }
};

/**
 * Get a user's profile
 * @param {string} userId - The user ID
 * @returns {Promise<Object|null>} The user profile or null if not found
 */
export const getProfile = async (userId) => {
  if (!userId) return null;
  
  const db = getFirestore();
  const profileRef = doc(db, 'profiles', userId);
  
  try {
    const profileDoc = await getDoc(profileRef);
    if (profileDoc.exists()) {
      return { id: profileDoc.id, ...profileDoc.data() };
    }
    return null;
  } catch (error) {
    console.error('Error getting user profile:', error);
    return null;
  }
};

/**
 * Update a user's profile
 * @param {string} userId - The user ID
 * @param {Object} data - The data to update
 * @returns {Promise<void>}
 */
export const updateProfile = async (userId, data) => {
  if (!userId) {
    throw new Error('User ID is required to update a profile');
  }
  
  const db = getFirestore();
  const profileRef = doc(db, 'profiles', userId);
  
  try {
    // Check if profile exists
    const profileDoc = await getDoc(profileRef);
    
    if (!profileDoc.exists()) {
      // Create profile if it doesn't exist
      console.log(`Profile doesn't exist for user ${userId}, creating it now`);
      await createProfile(userId, data);
    } else {
      // Update the profile
      await updateDoc(profileRef, {
        ...data,
        updatedAt: serverTimestamp()
      });
      console.log(`Updated profile for user ${userId}`);
    }
  } catch (error) {
    console.error('Error updating user profile:', error);
    throw error;
  }
};

/**
 * Update a user's online status and last active timestamp
 * @param {string} userId - The user ID
 * @param {boolean} isOnline - Whether the user is online
 * @returns {Promise<void>}
 */
export const updateOnlineStatus = async (userId, isOnline) => {
  if (!userId) return;
  
  const db = getFirestore();
  const profileRef = doc(db, 'profiles', userId);
  
  try {
    // Check if profile exists
    const profileDoc = await getDoc(profileRef);
    
    if (!profileDoc.exists()) {
      // Create a basic profile if it doesn't exist
      console.log(`Profile doesn't exist for user ${userId}, creating a basic one`);
      await createProfile(userId, {});
    }
    
    // Update online status and last active timestamp
    await updateDoc(profileRef, {
      isOnline,
      status: isOnline ? 'online' : 'offline',
      lastActive: serverTimestamp(),
      updatedAt: serverTimestamp()
    });
  } catch (error) {
    console.error('Error updating online status:', error);
  }
};

/**
 * Get active users
 * @param {number} limitCount - Maximum number of users to return
 * @param {number} minutes - Minutes to consider a user as "active"
 * @returns {Function} Unsubscribe function
 */
export const getActiveUsers = (callback, limitCount = 50, minutes = 10) => {
  try {
    const db = getFirestore();
    const now = new Date();
    const activeThreshold = new Date(now.getTime() - minutes * 60 * 1000);
    
    // Query for users who were active in the last X minutes
    const profilesQuery = query(
      collection(db, 'profiles'),
      where('lastActive', '>=', activeThreshold),
      orderBy('lastActive', 'desc'),
      limit(limitCount)
    );
    
    // Subscribe to real-time updates
    const unsubscribe = onSnapshot(profilesQuery, (snapshot) => {
      const activeUsers = [];
      snapshot.forEach(doc => {
        activeUsers.push({
          id: doc.id,
          ...doc.data()
        });
      });
      
      callback(activeUsers);
    }, (err) => {
      console.error('Error fetching active users:', err);
      callback([]);
    });
    
    return unsubscribe;
  } catch (err) {
    console.error('Error setting up active users listener:', err);
    callback([]);
    return () => {};
  }
};

/**
 * Ensure a user profile exists and is up-to-date
 * @param {Object} user - The user object from Firebase Auth
 * @returns {Promise<Object>} The user profile
 */
export const ensureUserProfile = async (user) => {
  if (!user || user.isAnonymous) {
    return null;
  }
  
  try {
    const db = getFirestore();
    const profileRef = doc(db, 'profiles', user.uid);
    
    // Check if profile exists
    const profileDoc = await getDoc(profileRef);
    
    if (!profileDoc.exists()) {
      // Create new profile
      const profileData = {
        userId: user.uid,
        displayName: user.displayName || 'Anonymous User',
        email: user.email || null,
        photoURL: user.photoURL || null,
        username: user.username || null,
        status: 'online',
        lastActive: serverTimestamp(),
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        isOnline: true
      };
      
      await setDoc(profileRef, profileData);
      console.log(`Created new profile for user ${user.uid}`);
      
      return profileData;
    } else {
      // Update existing profile with latest user data
      const updates = {
        displayName: user.displayName || profileDoc.data().displayName,
        email: user.email || profileDoc.data().email,
        photoURL: user.photoURL || profileDoc.data().photoURL,
        status: 'online',
        lastActive: serverTimestamp(),
        updatedAt: serverTimestamp(),
        isOnline: true
      };
      
      await updateDoc(profileRef, updates);
      console.log(`Updated profile for user ${user.uid}`);
      
      return {
        ...profileDoc.data(),
        ...updates
      };
    }
  } catch (error) {
    console.error('Error ensuring user profile:', error);
    return null;
  }
};

/**
 * Update a user's online status
 * @param {string} userId - The user ID
 * @param {boolean} isOnline - Whether the user is online
 * @returns {Promise<void>}
 */
export const updateUserOnlineStatus = async (userId, isOnline) => {
  // This is just an alias for updateOnlineStatus
  return updateOnlineStatus(userId, isOnline);
};