// src/services/PeriodicSubscriptionValidator.js - Periodic subscription validation

import { subscriptionService } from './SubscriptionService';
import { stripeSubscriptionService } from './StripeSubscriptionService';
import { detectEnvironment, isDevelopment, isTest } from '../utils/environmentDetection';

class PeriodicSubscriptionValidator {
  constructor() {
    this.environment = detectEnvironment();
    this.validationInterval = 4 * 60 * 60 * 1000; // 4 hours in milliseconds
    this.intervalId = null;
    this.lastValidation = null;
  }

  /**
   * Get cache key for current user's subscription status
   */
  getCacheKey(userId) {
    return `subscription_cache_${this.environment}_${userId}`;
  }

  /**
   * Get last validation timestamp key
   */
  getLastValidationKey(userId) {
    return `last_validation_${this.environment}_${userId}`;
  }

  /**
   * Check if cache is still valid (less than 4 hours old)
   */
  isCacheValid(userId) {
    try {
      const lastValidation = localStorage.getItem(this.getLastValidationKey(userId));
      if (!lastValidation) return false;

      const lastValidationTime = new Date(lastValidation);
      const now = new Date();
      const timeDiff = now.getTime() - lastValidationTime.getTime();

      const isValid = timeDiff < this.validationInterval;
      console.log(`🕐 Cache validation check - Age: ${Math.round(timeDiff / (1000 * 60))} minutes, Valid: ${isValid}`);
      
      return isValid;
    } catch (error) {
      console.warn('Error checking cache validity:', error);
      return false;
    }
  }

  /**
   * Get cached subscription status
   */
  getCachedStatus(userId) {
    try {
      const cachedData = localStorage.getItem(this.getCacheKey(userId));
      if (!cachedData) return null;

      const parsed = JSON.parse(cachedData);
      console.log(`💾 Using cached subscription status (${this.environment}):`, {
        isActive: parsed.isActive,
        cachedAt: parsed.cachedAt
      });
      
      return parsed;
    } catch (error) {
      console.warn('Error reading cached subscription status:', error);
      return null;
    }
  }

  /**
   * Cache subscription status
   */
  cacheStatus(userId, status) {
    try {
      const cacheData = {
        ...status,
        cachedAt: new Date().toISOString(),
        environment: this.environment,
        cacheVersion: '1.0'
      };

      localStorage.setItem(this.getCacheKey(userId), JSON.stringify(cacheData));
      localStorage.setItem(this.getLastValidationKey(userId), new Date().toISOString());
      
      console.log(`💾 Cached subscription status for 4 hours (${this.environment})`);
    } catch (error) {
      console.warn('Error caching subscription status:', error);
    }
  }

  /**
   * Perform full subscription validation
   */
  async performValidation(userId, email, forceRefresh = false) {
    console.log(`🔍 Starting subscription validation (${this.environment}${forceRefresh ? ' - FORCED' : ''})`);
    
    try {
      // 1. Get Firebase status
      const firebaseStatus = await subscriptionService.getSubscriptionStatus(userId);
      console.log('Firebase status:', { isActive: firebaseStatus.isActive });

      // 2. In dev/test environments, also check Stripe
      let finalStatus = firebaseStatus;
      
      if (isDevelopment() || isTest()) {
        console.log(`🔍 ${this.environment} environment - checking Stripe status`);
        
        try {
          const stripeStatus = await stripeSubscriptionService.checkSubscriptionStatus(userId, email);
          console.log('Stripe status:', { isActive: stripeStatus.isActive });
          
          // If Stripe shows different status than Firebase, sync them
          if (stripeStatus.success && stripeStatus.isActive !== firebaseStatus.isActive) {
            console.log('🔄 Syncing Firebase with Stripe status');
            
            if (stripeStatus.isActive && !firebaseStatus.isActive) {
              // Stripe active, Firebase inactive - activate Firebase
              await subscriptionService.updateSubscriptionFromStripe(userId, stripeStatus);
              finalStatus = { ...firebaseStatus, isActive: true, isPremium: true };
            } else if (!stripeStatus.isActive && firebaseStatus.isActive) {
              // Stripe inactive, Firebase active - deactivate Firebase
              await subscriptionService.cancelSubscription();
              finalStatus = { ...firebaseStatus, isActive: false, isPremium: false };
            }
          }
        } catch (stripeError) {
          console.warn('Could not validate Stripe status:', stripeError.message);
          // Continue with Firebase status if Stripe check fails
        }
      }

      // 3. Cache the result
      this.cacheStatus(userId, finalStatus);
      
      console.log(`✅ Validation complete (${this.environment}):`, {
        isActive: finalStatus.isActive,
        nextValidation: new Date(Date.now() + this.validationInterval).toLocaleString()
      });

      return finalStatus;
      
    } catch (error) {
      console.error(`❌ Validation failed (${this.environment}):`, error);
      throw error;
    }
  }

  /**
   * Get subscription status with caching
   */
  async getSubscriptionStatus(userId, email, forceRefresh = false) {
    // If forced refresh or cache invalid, perform validation
    if (forceRefresh || !this.isCacheValid(userId)) {
      return await this.performValidation(userId, email, forceRefresh);
    }

    // Use cached status
    const cachedStatus = this.getCachedStatus(userId);
    if (cachedStatus) {
      return cachedStatus;
    }

    // Cache miss, perform validation
    return await this.performValidation(userId, email);
  }

  /**
   * Start periodic validation for current user
   */
  startPeriodicValidation(userId, email) {
    // Don't start multiple intervals
    if (this.intervalId) {
      this.stopPeriodicValidation();
    }

    console.log(`🔄 Starting periodic validation every 4 hours (${this.environment})`);
    
    // Perform initial validation if cache is invalid
    if (!this.isCacheValid(userId)) {
      this.performValidation(userId, email).catch(error => {
        console.warn('Initial validation failed:', error);
      });
    }

    // Set up 4-hour interval
    this.intervalId = setInterval(async () => {
      try {
        console.log(`⏰ Periodic validation triggered (${this.environment})`);
        await this.performValidation(userId, email);
      } catch (error) {
        console.error('Periodic validation failed:', error);
      }
    }, this.validationInterval);

    this.lastValidation = new Date();
  }

  /**
   * Stop periodic validation
   */
  stopPeriodicValidation() {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
      console.log(`⏹️ Stopped periodic validation (${this.environment})`);
    }
  }

  /**
   * Force refresh subscription status (for dev controls)
   */
  async forceRefresh(userId, email) {
    console.log(`🔧 Force refreshing subscription status (${this.environment})`);
    return await this.getSubscriptionStatus(userId, email, true);
  }

  /**
   * Clear cache for user
   */
  clearCache(userId) {
    localStorage.removeItem(this.getCacheKey(userId));
    localStorage.removeItem(this.getLastValidationKey(userId));
    console.log(`🧹 Cleared subscription cache (${this.environment})`);
  }

  /**
   * Get cache info for debugging
   */
  getCacheInfo(userId) {
    const cacheValid = this.isCacheValid(userId);
    const cachedStatus = this.getCachedStatus(userId);
    const lastValidation = localStorage.getItem(this.getLastValidationKey(userId));

    return {
      environment: this.environment,
      cacheValid,
      lastValidation: lastValidation ? new Date(lastValidation) : null,
      nextValidation: lastValidation ? 
        new Date(new Date(lastValidation).getTime() + this.validationInterval) : null,
      hasCachedData: !!cachedStatus,
      cachedStatus: cachedStatus ? {
        isActive: cachedStatus.isActive,
        cachedAt: cachedStatus.cachedAt
      } : null
    };
  }

  /**
   * Cleanup when component unmounts
   */
  cleanup() {
    this.stopPeriodicValidation();
  }
}

// Export singleton instance
export const periodicValidator = new PeriodicSubscriptionValidator();
export default periodicValidator;
