// src/predict/utils/markets.js
//
// "Predictions by your scenes" feature.
//
// A "scene" is a slice of the music world a fan/artist cares about — a genre
// (hip-hop, indie, electronic), a regional music city (Atlanta, London,
// Lagos), or a coarse descriptor like "Global". Each user picks the scenes
// that matter to them; predictions are then filtered / prioritized based on
// which scenes they touch.
//
// NOTE: internally a scene is still called a "market" in the data model and
// the public API of this module (deriveMarketTags, predictionMatchesMarkets,
// etc.) so the rest of Predict didn't need to change when we re-themed from
// the old real-estate "markets" concept to music scenes. Prediction records
// carry their scene ids in the existing `marketTags` field.
//
// Pass 1 tactics:
//   - Canonical scene list below.
//   - `deriveMarketTags(prediction)` auto-tags a prediction by keyword-
//     matching its title + description against the catalog. No schema
//     change required.
//   - User preferences persisted to localStorage (Pass 2 will move this to
//     the Firestore user doc when Predict migrates).

const LS_KEY = 'predict_user_scenes';

/**
 * Canonical catalog. Each entry has:
 *   id       — stable slug
 *   label    — display name
 *   region   — coarse bucket ('Genre', 'Scene City', 'Global')
 *   keywords — strings to match in prediction titles/descriptions
 *              (lowercased; genre + artist-scene variants)
 */
export const MARKET_CATALOG = [
  // Genres
  { id: 'pop',         label: 'Pop',                 region: 'Genre',      keywords: ['pop', 'pop star'] },
  { id: 'hip-hop',     label: 'Hip-Hop / Rap',       region: 'Genre',      keywords: ['hip-hop', 'hip hop', 'rap', 'rapper', 'drill', 'trap'] },
  { id: 'rnb',         label: 'R&B / Soul',          region: 'Genre',      keywords: ['r&b', 'rnb', 'soul', 'neo-soul'] },
  { id: 'rock',        label: 'Rock / Alt',          region: 'Genre',      keywords: ['rock', 'alt-rock', 'alternative', 'punk', 'grunge'] },
  { id: 'indie',       label: 'Indie',               region: 'Genre',      keywords: ['indie', 'bedroom pop', 'shoegaze'] },
  { id: 'electronic',  label: 'Electronic / EDM',    region: 'Genre',      keywords: ['electronic', 'edm', 'house music', 'techno', 'dnb', 'dubstep'] },
  { id: 'country',     label: 'Country / Americana', region: 'Genre',      keywords: ['country', 'americana', 'bluegrass'] },
  { id: 'latin',       label: 'Latin',               region: 'Genre',      keywords: ['latin', 'reggaeton', 'corridos', 'bachata'] },
  { id: 'kpop',        label: 'K-Pop',               region: 'Genre',      keywords: ['k-pop', 'kpop', 'k pop'] },
  { id: 'afrobeats',   label: 'Afrobeats',           region: 'Genre',      keywords: ['afrobeats', 'afrobeat', 'amapiano'] },
  { id: 'jazz',        label: 'Jazz',                region: 'Genre',      keywords: ['jazz'] },
  { id: 'metal',       label: 'Metal',               region: 'Genre',      keywords: ['metal', 'metalcore', 'hardcore'] },

  // Scene cities (where a sound is centered)
  { id: 'los-angeles', label: 'Los Angeles',         region: 'Scene City', keywords: ['los angeles', 'l.a.', 'hollywood'] },
  { id: 'atlanta',     label: 'Atlanta',             region: 'Scene City', keywords: ['atlanta', 'atl'] },
  { id: 'nashville',   label: 'Nashville',           region: 'Scene City', keywords: ['nashville'] },
  { id: 'new-york',    label: 'New York',            region: 'Scene City', keywords: ['new york', 'nyc', 'brooklyn'] },
  { id: 'london',      label: 'London / UK',         region: 'Scene City', keywords: ['london', 'british'] },
  { id: 'lagos',       label: 'Lagos',               region: 'Scene City', keywords: ['lagos', 'nigeria'] },
  { id: 'seoul',       label: 'Seoul',               region: 'Scene City', keywords: ['seoul', 'korea', 'korean'] },
  { id: 'berlin',      label: 'Berlin',              region: 'Scene City', keywords: ['berlin', 'germany'] },

  // Coarse global tag (matches when a prediction is industry-wide)
  { id: 'global',      label: 'Global / Industry',   region: 'Global',     keywords: ['global', 'worldwide', 'industry', 'grammy', 'billboard hot 100', 'streaming industry', 'spotify', 'apple music'] },
];

/** Returns the scene ids (slugs) touched by a prediction. */
export function deriveMarketTags(prediction) {
  if (!prediction) return [];
  // Respect an explicit `marketTags` field if the data model sets one.
  if (Array.isArray(prediction.marketTags) && prediction.marketTags.length) {
    return prediction.marketTags;
  }
  const haystack = (
    (prediction.title || '') + ' ' + (prediction.description || '')
  ).toLowerCase();
  const hits = [];
  for (const m of MARKET_CATALOG) {
    if (m.keywords.some(kw => haystack.includes(kw))) {
      hits.push(m.id);
    }
  }
  return hits;
}

/** Returns true if the prediction overlaps any of `selectedMarketIds`. */
export function predictionMatchesMarkets(prediction, selectedMarketIds) {
  if (!selectedMarketIds || selectedMarketIds.length === 0) return true; // no filter
  const tags = deriveMarketTags(prediction);
  // Always show Global/industry predictions when any scene is selected — they
  // affect everyone.
  if (tags.includes('global')) return true;
  return tags.some(t => selectedMarketIds.includes(t));
}

// ---- User preferences (localStorage, Pass 1) ----

/** Read the user's selected scenes (array of catalog ids). */
export function getUserMarkets() {
  if (typeof window === 'undefined') return [];
  try {
    const raw = localStorage.getItem(LS_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

/** Overwrite the user's selected scenes. */
export function setUserMarkets(ids) {
  if (typeof window === 'undefined') return;
  try {
    localStorage.setItem(LS_KEY, JSON.stringify(ids || []));
    // Fire an event so components in other tabs (or elsewhere on page)
    // re-read without a full reload.
    window.dispatchEvent(new CustomEvent('predict:user-markets-changed'));
  } catch {
    /* quota/private mode — tolerable silent failure */
  }
}

/** Look up a scene by id; returns null if not in catalog. */
export function getMarket(id) {
  return MARKET_CATALOG.find(m => m.id === id) || null;
}

/** Catalog grouped by region for nicer UIs. */
export function marketsByRegion() {
  const groups = {};
  for (const m of MARKET_CATALOG) {
    (groups[m.region] ||= []).push(m);
  }
  return groups;
}
