/**
 * Get all active timing traces
 * Useful for debugging and displaying active traces
 * @returns {Array} Array of trace information objects
 */
export const getAllTimings = () => {
  try {
    const timings = [];
    
    // Get all active traces
    activeTraces.forEach((trace, traceName) => {
      timings.push({
        name: traceName,
        type: 'trace',
        startTime: trace.startTime || Date.now() // Fallback if trace doesn't have startTime
      });
    });
    
    // Get all active contexts
    activeContexts.forEach((context, contextId) => {
      timings.push({
        name: context.traceName,
        type: 'context',
        id: contextId,
        startTime: context.startTime
      });
    });
    
    // Sort by start time (newest first)
    timings.sort((a, b) => b.startTime - a.startTime);
    
    return timings;
  } catch (error) {
    console.warn('[Performance] Error getting timings:', error);
    return [];
  }
};

/**
 * Clear all active timing traces
 * Useful for cleanup or when navigating between pages
 */
export const clearTimings = () => {
  try {
    // Get all active trace names
    const traceNames = Array.from(activeTraces.keys());
    
    // Stop each trace
    traceNames.forEach(traceName => {
      try {
        const trace = activeTraces.get(traceName);
        if (trace) {
          trace.stop();
          console.debug(`[Performance] Cleared trace: ${traceName}`);
        }
      } catch (err) {
        console.warn(`[Performance] Error clearing trace ${traceName}:`, err);
      }
    });
    
    // Clear all active traces
    activeTraces.clear();
    
    // Clear all active contexts
    activeContexts.clear();
    
    console.debug(`[Performance] Cleared all ${traceNames.length} traces`);
  } catch (error) {
    console.warn('[Performance] Error clearing traces:', error);
  }
};

// src/utils/performance-monitor.js
/**
 * Utility for performance monitoring with Firebase
 * Includes error handling to prevent 'trace not running' errors
 */

// Track active traces to prevent stopping non-existent traces
const activeTraces = new Map();
const activeContexts = new Map();

/**
 * Start a performance trace
 * @param {string} traceName - Name of the trace to start
 * @returns {string} - The trace ID
 */
export const startTiming = (traceName) => {
  try {
    // Only import firebase if it exists in window
    const firebasePerf = window.firebase?.performance?.();
    if (!firebasePerf) {
      console.debug(`[Performance] Firebase Performance not initialized for trace: ${traceName}`);
      return traceName;
    }

    console.debug(`⏱️ Started: ${traceName}`);
    const trace = firebasePerf.trace(traceName);
    trace.start();
    
    // Store the trace
    activeTraces.set(traceName, trace);
    return traceName;
  } catch (error) {
    console.warn(`[Performance] Error starting trace ${traceName}:`, error);
    return traceName;
  }
};

/**
 * End a performance trace
 * @param {string} traceId - ID of the trace to end (returned from startTiming)
 */
export const endTiming = (traceId) => {
  try {
    // Check if the trace exists
    if (!activeTraces.has(traceId)) {
      console.debug(`[Performance] No active trace found for: ${traceId}`);
      return;
    }

    const trace = activeTraces.get(traceId);
    
    // Check if trace is running before stopping
    if (trace) {
      trace.stop();
      activeTraces.delete(traceId);
      
      // Duration is only an estimate since we don't have access to the real timing
      const durationMs = 0.1; // Placeholder value
      console.debug(`🟢 Completed: ${traceId} in ${durationMs}ms`);
    }
  } catch (error) {
    console.warn(`[Performance] Error ending trace ${traceId}:`, error);
    // Remove from active traces even if there was an error
    activeTraces.delete(traceId);
  }
};

/**
 * Create a timing context that can be used with async/await
 * @param {string} traceName - Name of the trace to start
 * @returns {Object} - A timing context object with done() method
 */
export const createTimingContext = (traceName) => {
  const contextId = `context_${traceName}_${Date.now()}`;
  const traceId = startTiming(traceName);
  
  const context = {
    traceId,
    traceName,
    startTime: Date.now(),
    done: () => {
      try {
        endTiming(traceId);
        activeContexts.delete(contextId);
        return Date.now() - context.startTime;
      } catch (error) {
        console.warn(`[Performance] Error in timing context for ${traceName}:`, error);
        activeContexts.delete(contextId);
        return 0;
      }
    }
  };
  
  activeContexts.set(contextId, context);
  return context;
};

/**
 * Mark a custom performance event
 * @param {string} name - Name of the event
 */
export const markEvent = (name) => {
  try {
    const firebasePerf = window.firebase?.performance?.();
    if (!firebasePerf) {
      console.debug(`[Performance] Firebase Performance not initialized for event: ${name}`);
      return;
    }

    console.debug(`📌 Marked: ${name}`);
    // Use the built-in performance API for more reliable marks
    window.performance.mark(name);
    
    // Also use Firebase if available
    firebasePerf.mark(name);
  } catch (error) {
    console.warn(`[Performance] Error marking event ${name}:`, error);
  }
};

export default {
  startTiming,
  endTiming,
  markEvent,
  createTimingContext,
  clearTimings,
  getAllTimings
};
