// src/services/setStreamService.js
//
// Streams the sketch engine's live audio output into an event's LiveKit
// room — the real implementation of "stream your set", replacing the
// console.log stub that ArtistStreamingStudioUnified handed the DJ studio.
//
// Flow:
//   1. the room name — a scheduled room's occurrence key, or the unified
//      event room from generateAllRoomNames(eventId)
//   2. liveKitService.connect(...)  → existing token + connection path
//   3. publish the engine's MediaStream audio track to the room
//   4. ask the backend to attach a recording egress, which uploads the set to
//      the replay bucket when it ends
//
// Viewers in the event theatre / chat hear the set live; nothing about the
// viewer side needs to change.

import { generateAllRoomNames } from '../utils/roomNaming';
import liveKitService from './livekit/LiveKitService';
import { startReplayRecording, stopReplayRecording } from './recording/replayEgressService';

let activePublication = null; // { room, track, roomName, egress, startedAt }

export function isSetLive() {
  return !!activePublication;
}

/**
 * Go live: publish `mediaStream`'s audio track into the event's room.
 * Returns { roomName, listeners } on success; throws on failure.
 */
export async function startSetStream({
  eventId,
  user,
  mediaStream,
  setTitle = 'Live set',
  roomName = null,
  occurrenceId = null,
  record = true,
}) {
  if (activePublication) throw new Error('A set is already live — stop it first');
  if (!eventId && !roomName) throw new Error('Pick an event or a scheduled room to stream to');
  if (!user || !user.uid) throw new Error('Must be signed in to stream');
  if (!mediaStream) throw new Error('No audio stream from the engine');

  const audioTrack = mediaStream.getAudioTracks()[0];
  if (!audioTrack) throw new Error('Engine stream has no audio track');

  // A scheduled room names its own LiveKit room (occurrenceRoomKey), which is
  // the same room the listener's /r/:slug page subscribes to. Events keep the
  // derived event-<id> name.
  const liveKitRoom = roomName || generateAllRoomNames(eventId).liveKitRoom;
  const participantName = `${user.displayName || user.email || 'artist'} (set)`;

  const result = await liveKitService.connect(liveKitRoom, participantName, {
    canPublish: true,
    canSubscribe: false,
    autoSubscribe: false,
  });
  if (!result.success || !result.room) {
    throw new Error(result.error || 'Could not connect to the stream room');
  }

  const { Track } = await import('livekit-client');
  const publication = await result.room.localParticipant.publishTrack(audioTrack, {
    name: setTitle,
    source: Track.Source.Unknown,
    dtx: false, // music, not speech — keep continuous encoding
    red: true,
    stopMicTrackOnMute: false,
  });

  // Record the set so it becomes a replay. Best-effort by design: if the
  // recording API is unreachable the set still goes out live.
  const egress = record
    ? await startReplayRecording({
        roomName: liveKitRoom,
        occurrenceId,
        eventId,
        title: setTitle,
        audioOnly: true,
      })
    : null;

  activePublication = {
    room: result.room,
    track: audioTrack,
    publication,
    roomName: liveKitRoom,
    egress,
    startedAt: Date.now(),
  };

  return {
    roomName: liveKitRoom,
    listeners: Math.max(0, (result.participantCount || 1) - 1),
    recording: !!egress,
    egressId: egress ? egress.egressId : null,
  };
}

/**
 * How many people are currently in the room with the set. The Studio polls
 * this while live so the room's listener count — the number Discover sorts
 * live rooms by — reflects reality instead of sitting at zero.
 */
export function getSetListenerCount() {
  if (!activePublication) return 0;
  const participants = activePublication.room?.remoteParticipants;
  return Math.max(0, participants?.size || 0);
}

/**
 * Stop the live set and leave the room. Resolves to the replay the recording
 * produced — { replayId, replayUrl, durationMs } — so the caller can hand it to
 * markOccurrenceEnded, or null when nothing was recorded.
 */
export async function stopSetStream() {
  if (!activePublication) return null;
  const { room, track, egress, startedAt } = activePublication;
  activePublication = null;

  // Stop the egress before leaving: LiveKit ends an egress when the room
  // empties, but stopping it explicitly is what returns the replay URL now.
  let replay = null;
  if (egress && egress.egressId) {
    replay = await stopReplayRecording(egress.egressId);
    if (replay && !replay.replayUrl) replay.replayUrl = egress.videoUrl || null;
    if (replay && !replay.durationMs && startedAt) replay.durationMs = Date.now() - startedAt;
  }

  try {
    await room.localParticipant.unpublishTrack(track);
  } catch (_) { /* room may already be closing */ }
  try {
    await room.disconnect();
  } catch (_) { /* noop */ }

  return replay;
}

export default { startSetStream, stopSetStream, isSetLive, getSetListenerCount };
