const KEYS = {
  newsapi: 'predict_key_newsapi',
  claude: 'predict_key_claude',
  rssFeeds: 'predict_rss_feeds',
  // Context-source keys (Phase 2+).
  // EPA key is required for AirNow AQI.
  // BLS key is optional — anonymous BLS calls work at a lower rate cap.
  // Phase 3:
  //   Census key optional — improves rate limit, anonymous works fine.
  //   FBI Crime requires api.data.gov key.
  epa: 'predict_key_epa',
  bls: 'predict_key_bls',
  census: 'predict_key_census',
  fbi: 'predict_key_fbi',
}

const DEFAULT_RSS_FEEDS = [
  { url: 'https://rss.nytimes.com/services/xml/rss/nyt/World.xml', name: 'NY Times World', category: 'geopolitics' },
  { url: 'https://feeds.bbci.co.uk/news/world/rss.xml', name: 'BBC World', category: 'geopolitics' },
  { url: 'https://rss.nytimes.com/services/xml/rss/nyt/Politics.xml', name: 'NY Times Politics', category: 'politics' },
  { url: 'https://feeds.bbci.co.uk/news/technology/rss.xml', name: 'BBC Technology', category: 'tech' },
  { url: 'https://rss.nytimes.com/services/xml/rss/nyt/Business.xml', name: 'NY Times Business', category: 'economics' },
  { url: 'https://feeds.bbci.co.uk/news/science_and_environment/rss.xml', name: 'BBC Science', category: 'science' },
  { url: 'https://rss.nytimes.com/services/xml/rss/nyt/Sports.xml', name: 'NY Times Sports', category: 'sports' },
]

const apiKeyService = {
  getNewsApiKey() {
    return localStorage.getItem(KEYS.newsapi) || ''
  },

  setNewsApiKey(key) {
    localStorage.setItem(KEYS.newsapi, key.trim())
  },

  getClaudeApiKey() {
    return localStorage.getItem(KEYS.claude) || ''
  },

  setClaudeApiKey(key) {
    localStorage.setItem(KEYS.claude, key.trim())
  },

  getRssFeeds() {
    const stored = localStorage.getItem(KEYS.rssFeeds)
    return stored ? JSON.parse(stored) : DEFAULT_RSS_FEEDS
  },

  setRssFeeds(feeds) {
    localStorage.setItem(KEYS.rssFeeds, JSON.stringify(feeds))
  },

  addRssFeed(feed) {
    const feeds = this.getRssFeeds()
    feeds.push(feed)
    this.setRssFeeds(feeds)
  },

  removeRssFeed(url) {
    const feeds = this.getRssFeeds().filter(f => f.url !== url)
    this.setRssFeeds(feeds)
  },

  hasNewsApiKey() {
    return !!this.getNewsApiKey()
  },

  hasClaudeApiKey() {
    return !!this.getClaudeApiKey()
  },

  // ─── Context source keys ──────────────────────────────────────────
  getEpaApiKey() {
    return localStorage.getItem(KEYS.epa) || ''
  },

  setEpaApiKey(key) {
    localStorage.setItem(KEYS.epa, (key || '').trim())
  },

  hasEpaApiKey() {
    return !!this.getEpaApiKey()
  },

  getBlsApiKey() {
    return localStorage.getItem(KEYS.bls) || ''
  },

  setBlsApiKey(key) {
    localStorage.setItem(KEYS.bls, (key || '').trim())
  },

  hasBlsApiKey() {
    return !!this.getBlsApiKey()
  },

  getCensusApiKey() {
    return localStorage.getItem(KEYS.census) || ''
  },

  setCensusApiKey(key) {
    localStorage.setItem(KEYS.census, (key || '').trim())
  },

  hasCensusApiKey() {
    return !!this.getCensusApiKey()
  },

  getFbiApiKey() {
    return localStorage.getItem(KEYS.fbi) || ''
  },

  setFbiApiKey(key) {
    localStorage.setItem(KEYS.fbi, (key || '').trim())
  },

  hasFbiApiKey() {
    return !!this.getFbiApiKey()
  },
}

export default apiKeyService
