import React, { useRef, useEffect } from 'react';
import { User } from 'lucide-react';
import './Messages.css';

const MessageList = ({ messages, currentUser, onReply }) => {
  const messageEndRef = useRef(null);

  // Auto-scroll to bottom when new messages arrive
  useEffect(() => {
    if (messageEndRef.current) {
      messageEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages]);

  // Format timestamp for display
  const formatMessageTime = (timestamp) => {
    if (!timestamp) return '';
    
    const messageDate = timestamp.toDate ? timestamp.toDate() : new Date(timestamp);
    const now = new Date();
    const diffInMinutes = (now - messageDate) / (1000 * 60);
    const diffInHours = diffInMinutes / 60;
    const diffInDays = diffInHours / 24;
    
    if (diffInMinutes < 1) {
      return 'now';
    } else if (diffInMinutes < 60) {
      return `${Math.floor(diffInMinutes)}m ago`;
    } else if (diffInHours < 24) {
      return `${Math.floor(diffInHours)}h ago`;
    } else if (diffInDays < 7) {
      return `${Math.floor(diffInDays)}d ago`;
    } else {
      return messageDate.toLocaleDateString('en-US', { 
        month: 'short', 
        day: 'numeric',
        year: messageDate.getFullYear() !== now.getFullYear() ? 'numeric' : undefined
      });
    }
  };

  // Get display name for a user
  const getDisplayName = (message) => {
    if (message.senderName) {
      return message.senderName.startsWith('@') ? message.senderName : `@${message.senderName}`;
    }
    return message.senderId === currentUser.uid ? '@you' : '@user';
  };

  // Sort messages by timestamp
  const sortedMessages = [...messages].sort((a, b) => {
    const timeA = a.timestamp?.toDate ? a.timestamp.toDate() : new Date();
    const timeB = b.timestamp?.toDate ? b.timestamp.toDate() : new Date();
    return timeA - timeB;
  });

  // Group consecutive messages from the same sender
  const groupMessages = (messages) => {
    const groups = [];
    let currentGroup = null;
    
    messages.forEach((message, index) => {
      const isCurrentUser = message.senderId === currentUser.uid;
      const prevMessage = messages[index - 1];
      const prevIsCurrentUser = prevMessage?.senderId === currentUser.uid;
      
      // Start a new group if sender changed or if there's a time gap > 5 minutes
      const timeGap = prevMessage ? 
        (message.timestamp?.toDate() - prevMessage.timestamp?.toDate()) / (1000 * 60) : 
        0;
      
      if (!currentGroup || 
          message.senderId !== prevMessage?.senderId || 
          timeGap > 5) {
        currentGroup = {
          senderId: message.senderId,
          senderName: message.senderName,
          senderPhoto: message.senderPhoto,
          isCurrentUser,
          messages: []
        };
        groups.push(currentGroup);
      }
      
      currentGroup.messages.push(message);
    });
    
    return groups;
  };

  const messageGroups = groupMessages(sortedMessages);

  return (
    <div className="message-list">
      {messageGroups.length === 0 ? (
        <div className="no-messages">
          <h3>This is the beginning of your conversation</h3>
          <p>Send a message to get started!</p>
        </div>
      ) : (
        messageGroups.map((group, groupIndex) => (
          <div key={`group-${groupIndex}`} className="message-group">
            {group.messages.map((message, messageIndex) => (
              <div 
                key={message.id} 
                className={`message-wrapper ${group.isCurrentUser ? 'sent' : 'received'}`}
              >
                {/* Show avatar only for first message in group and non-current user */}
                {messageIndex === 0 && !group.isCurrentUser && (
                  <>
                    {message.senderPhoto ? (
                      <img 
                        src={message.senderPhoto} 
                        alt={getDisplayName(message)} 
                        className="message-avatar"
                      />
                    ) : (
                      <div className="message-avatar-placeholder">
                        <User size={16} />
                      </div>
                    )}
                  </>
                )}
                
                {/* Spacer for grouped messages */}
                {messageIndex > 0 && !group.isCurrentUser && (
                  <div style={{ width: '48px', flexShrink: 0 }} />
                )}
                
                <div className="message-content-wrapper">
                  {/* Show name and time only for first message in group */}
                  {messageIndex === 0 && !group.isCurrentUser && (
                    <div className="message-header-inline">
                      <span className="message-author">
                        {getDisplayName(message)}
                      </span>
                      <span className="message-time">
                        {formatMessageTime(message.timestamp)}
                      </span>
                    </div>
                  )}
                  
                  <div className="message-bubble">
                    <p>{message.content}</p>
                  </div>
                  
                  {/* Show timestamp on hover for sent messages */}
                  {group.isCurrentUser && (
                    <div className="message-time sent-time">
                      {formatMessageTime(message.timestamp)}
                    </div>
                  )}
                </div>
                
                {/* Message actions */}
                <div className="message-actions">
                  <button 
                    className="reply-button" 
                    onClick={() => onReply(message.id)}
                    title="Reply to message"
                  >
                    Reply
                  </button>
                </div>
              </div>
            ))}
          </div>
        ))
      )}
      <div ref={messageEndRef} />
    </div>
  );
};

export default MessageList;