// src/utils/environmentDetection.js

/**
 * Environment Detection Utility
 * Determines the current environment (DEV/TEST/PROD) based on hostname
 */

export const ENVIRONMENTS = {
  DEV: 'dev',
  TEST: 'test',
  PROD: 'prod'
};

/**
 * Detect current environment based on hostname
 * @returns {string} Environment identifier
 */
export const detectEnvironment = () => {
  const hostname = window.location.hostname;
  const port = window.location.port;
  
  // DEV = localhost (any port) or 127.0.0.1
  if (hostname === 'localhost' || 
      hostname === '127.0.0.1' || 
      hostname.includes('localhost') ||
      port === '3000' || port === '5173') {
    return ENVIRONMENTS.DEV;
  }
  
  // TEST = *.ondigitalocean.app (excluding production)
  if (hostname.includes('ondigitalocean.app') && 
      !hostname.includes('talkstudio-production-r6pmy.ondigitalocean.app')) {
    return ENVIRONMENTS.TEST;
  }
  
  // PROD = talkstudio.space or talkstud.io
  if (hostname === 'talkstudio.space' || hostname === 'talkstud.io') {
    return ENVIRONMENTS.PROD;
  }
  
  // Default to DEV for unknown environments (for safety in development)
  console.warn(`Unknown environment detected: ${hostname} - defaulting to DEV`);
  return ENVIRONMENTS.DEV;
};

/**
 * Check if current environment is development
 * @returns {boolean}
 */
export const isDevelopment = () => {
  return detectEnvironment() === ENVIRONMENTS.DEV;
};

/**
 * Check if current environment is test
 * @returns {boolean}
 */
export const isTest = () => {
  return detectEnvironment() === ENVIRONMENTS.TEST;
};

/**
 * Check if current environment is production
 * @returns {boolean}
 */
export const isProduction = () => {
  return detectEnvironment() === ENVIRONMENTS.PROD;
};

/**
 * Get basic environment configuration (no Stripe keys)
 * @returns {object} Environment configuration
 */
export const getEnvironmentConfig = () => {
  const environment = detectEnvironment();
  
  const configs = {
    [ENVIRONMENTS.DEV]: {
      name: 'Development',
      features: {
        debugMode: true,
        showEnvironmentIndicator: true
      }
    },
    [ENVIRONMENTS.TEST]: {
      name: 'Test',
      features: {
        debugMode: true,
        showEnvironmentIndicator: true
      }
    },
    [ENVIRONMENTS.PROD]: {
      name: 'Production',
      features: {
        debugMode: false,
        showEnvironmentIndicator: false
      }
    }
  };
  
  return configs[environment];
};

/**
 * Log environment information (for debugging)
 */
export const logEnvironmentInfo = () => {
  const env = detectEnvironment();
  const config = getEnvironmentConfig();
  
  console.group('🌍 Environment Detection');
  console.log('Hostname:', window.location.hostname);
  console.log('Port:', window.location.port);
  console.log('Environment:', env);
  console.log('Configuration:', config);
  console.groupEnd();
  
  return {
    environment: env,
    config
  };
};
