import { Search, X } from 'lucide-react'
import { useState, useEffect, useRef } from 'react'

export default function SearchBar({ value = '', onChange, placeholder = 'Search predictions...' }) {
  const [local, setLocal] = useState(value)
  const timerRef = useRef(null)

  useEffect(() => { setLocal(value) }, [value])

  function handleChange(e) {
    const v = e.target.value
    setLocal(v)
    clearTimeout(timerRef.current)
    timerRef.current = setTimeout(() => onChange(v), 300)
  }

  function handleClear() {
    setLocal('')
    onChange('')
  }

  return (
    <div className="relative">
      <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" />
      <input
        type="text"
        value={local}
        onChange={handleChange}
        placeholder={placeholder}
        className="w-full pl-9 pr-9 py-2 bg-gray-800/50 border border-gray-700 rounded-lg text-sm text-gray-200 placeholder-gray-500 focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500/30 transition-colors"
      />
      {local && (
        <button onClick={handleClear} className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-300">
          <X size={14} />
        </button>
      )}
    </div>
  )
}
