// Compact helper: create `inputs` with sensible defaults so each prediction
// entry stays readable.
function mkInputs(sigs) {
  return sigs.map(([source, type, weight, sentiment, reliability, daysAgo]) => ({
    source, type, weight, sentiment, reliability,
    timestamp: pastDate(daysAgo),
  }))
}

