// Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\components\events\ArtistStreamingStudio.jsx

import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useStreaming } from '../../contexts/StreamingContextLiveKit';
import { useNavigate } from 'react-router-dom';
import { 
  getFirestore, 
  doc, 
  getDoc, 
  addDoc, 
  updateDoc, 
  collection, 
  query,
  where,
  orderBy,
  onSnapshot,
  serverTimestamp 
} from 'firebase/firestore';
import { getDatabase, ref, onValue, push, set, off } from 'firebase/database';
import {
  Video,
  VideoOff,
  Mic,
  MicOff,
  Settings,
  Users,
  DollarSign,
  Calendar,
  Clock,
  Play,
  Square,
  Monitor,
  Camera,
  Headphones,
  Wifi,
  WifiOff,
  AlertCircle,
  CheckCircle,
  Zap,
  Star,
  Crown,
  Eye,
  Radio,
  Upload,
  Save,
  Share2,
  Plus,
  ExternalLink,
  MessageCircle,
  Send,
  Activity,
  User,
  Lock
} from 'lucide-react';
import './ArtistStreamingStudio.css';
import './ArtistStreamingStudio-EventDropdown.css';
import StreamingDebugPanel from '../debug/StreamingDebugPanel';

// Import LiveKit components
import LiveKitRoom from '../livekit/LiveKitRoom';
import LiveKitStreamManager from '../livekit/LiveKitStreamManager';

// Import DJ Studio component
import DJStudioArtistIntegration from '../audio/DJStudioArtistIntegration';

// Import DJ Streaming Diagnostic
import DJStreamingDiagnostic from '../debug/DJStreamingDiagnostic';

// Add debug logging for DJ Studio
console.log('🎛️ DJ Studio Integration imported:', DJStudioArtistIntegration);

const ArtistStreamingStudio = () => {
  const { currentUser } = useAuth();
  const { 
    startEventStream, 
    stopEventStream, 
    streamingServiceReady, 
    getStreamingStats,
    error: streamingError 
  } = useStreaming();
  const navigate = useNavigate();
  
  // Check if we're in developer mode
  const [isDeveloperMode, setIsDeveloperMode] = useState(false);
  
  useEffect(() => {
    const devMode = process.env.NODE_ENV === 'development' && localStorage.getItem('developerMode') === 'true';
    setIsDeveloperMode(devMode);
  }, []);
  
  // Artist verification - KEEP STRICT VERIFICATION FOR STUDIO
  const [isArtist, setIsArtist] = useState(false);
  const [artistProfile, setArtistProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  
  // Streaming state
  const [isStreaming, setIsStreaming] = useState(false);
  const [streamKey, setStreamKey] = useState('');
  const [streamUrl, setStreamUrl] = useState('');
  const [connectionStatus, setConnectionStatus] = useState('disconnected'); // disconnected, connecting, connected, error
  
  // LiveKit state
  const [liveKitToken, setLiveKitToken] = useState(null);
  const [liveKitRoomName, setLiveKitRoomName] = useState('');
  const [liveKitConnected, setLiveKitConnected] = useState(false);
  
  // Event management
  const [currentEvent, setCurrentEvent] = useState(null);
  const [availableEvents, setAvailableEvents] = useState([]);
  const [selectedEventId, setSelectedEventId] = useState('');
  const [eventMode, setEventMode] = useState('select'); // 'select' or 'create'
  const [eventSetup, setEventSetup] = useState({
    title: '',
    description: '',
    ticketPrice: 29.99,
    startTime: '',
    duration: 60,
    category: 'music',
    thumbnailUrl: '',
    maxViewers: 500,
    chatEnabled: true,
    recordingEnabled: true
  });
  
  // Device management state - Simplified for LiveKit
  const [devicePermissionGranted, setDevicePermissionGranted] = useState(false);
  
  // Stream analytics
  const [analytics, setAnalytics] = useState({
    currentViewers: 0,
    totalViews: 0,
    peakViewers: 0,
    chatMessages: 0,
    reactions: 0,
    revenue: 0
  });
  
  // UI state
  const [activeTab, setActiveTab] = useState('setup'); // setup, stream, analytics
  const [videoEnabled, setVideoEnabled] = useState(true);
  const [audioEnabled, setAudioEnabled] = useState(true);
  const [showSettings, setShowSettings] = useState(false);
  const [showDebugPanel, setShowDebugPanel] = useState(false);
  
  // Chat state - replacing iframe with real chat
  const [chatMessages, setChatMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [activeUsers, setActiveUsers] = useState({});
  const [chatRoomData, setChatRoomData] = useState(null);
  
  // Refs
  const messagesEndRef = useRef(null);
  const chatInputRef = useRef(null);

  useEffect(() => {
    if (!currentUser) {
      navigate('/login');
      return;
    }
    
    initializeStudio();
  }, [currentUser]);

  useEffect(() => {
    scrollToBottom();
  }, [chatMessages]);

  const initializeStudio = async () => {
    try {
      setLoading(true);
      
      // IMPORTANT: Keep strict artist verification for the Studio route
      await verifyArtistStatus();
      
      // Load artist profile
      await loadArtistProfile();
      
      // Initialize streaming setup
      await initializeStreamingSetup();
      
      // Setup basic device permissions (LiveKit will handle the rest)
      await checkDevicePermissions();
      
    } catch (error) {
      console.error('Failed to initialize studio:', error);
    } finally {
      setLoading(false);
    }
  };

  const verifyArtistStatus = async () => {
    try {
      const db = getFirestore();
      const userDoc = await getDoc(doc(db, 'users', currentUser.uid));
      const userData = userDoc.data();
      
      console.log('🔍 Checking artist status for user:', currentUser.uid);
      console.log('📋 User data:', userData);
      
      // TEMPORARY: Allow all users for testing (comment out for production)
      // TODO: Remove this override for production
      const isTestingMode = true; // Set to false for production
      
      if (isTestingMode) {
        console.log('🧪 TESTING MODE: Allowing all users into Artist Studio');
        setIsArtist(true);
        return;
      }
      
      // RELAXED VERIFICATION: Allow isArtist=true users into Studio (remove artistApproved requirement)
      const artistVerified = userData?.isArtist === true;
      
      if (!artistVerified) {
        console.log('❌ Artist Studio access denied - user is not marked as artist');
        console.log('💡 User needs isArtist=true in users collection');
        console.log('💡 To fix: Set isArtist=true in Firestore users/{userId} document');
        
        // Show helpful error message instead of redirecting
        alert(`Artist Studio Access Required\n\nYour account needs artist status to access the streaming studio.\n\nCurrent status: ${userData?.isArtist ? 'Artist' : 'Regular User'}\n\nPlease contact support to enable artist features.`);
        navigate('/');
        return;
      }
      
      setIsArtist(true);
      console.log('🎨 Artist verification successful for Studio access');
      
    } catch (error) {
      console.error('Artist verification failed:', error);
      alert('Failed to verify artist status. Please try again.');
      navigate('/');
    }
  };

  const loadArtistProfile = async () => {
    try {
      const db = getFirestore();
      const profileDoc = await getDoc(doc(db, 'artistProfiles', currentUser.uid));
      
      if (profileDoc.exists()) {
        const profile = profileDoc.data();
        setArtistProfile(profile);
        
        // Generate unique stream key for this artist
        const streamKey = `artist_${currentUser.uid}_${Date.now()}`;
        setStreamKey(streamKey);
        setStreamUrl(`${process.env.REACT_APP_STREAM_SERVER_URL}/live/${streamKey}`);
        
        console.log('🎭 Artist profile loaded:', profile.stageName);
      }
    } catch (error) {
      console.error('Failed to load artist profile:', error);
    }
  };

  const initializeStreamingSetup = async () => {
    try {
      // Load user's events from Firestore
      const db = getFirestore();
      const eventsQuery = query(
        collection(db, 'events'),
        where('artistId', '==', currentUser.uid),
        orderBy('startTime', 'desc')
      );
      
      const unsubscribe = onSnapshot(eventsQuery, (snapshot) => {
        const eventsList = snapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        }));
        
        setAvailableEvents(eventsList);
        console.log('🎥 User events loaded:', eventsList.length);
        
        // If no events available, switch to create mode
        if (eventsList.length === 0) {
          setEventMode('create');
        } else {
          // If no event selected yet, auto-select first scheduled event
          if (!selectedEventId) {
            const scheduledEvent = eventsList.find(e => e.status === 'scheduled');
            if (scheduledEvent) {
              setSelectedEventId(scheduledEvent.id);
              setCurrentEvent(scheduledEvent);
              setupEventChat(scheduledEvent.id);
              generateLiveKitRoom(scheduledEvent.id);
              console.log('🎤 Auto-selected event for streaming:', scheduledEvent.title);
            } else {
              // If no scheduled events, select the most recent one
              const recentEvent = eventsList[0];
              if (recentEvent) {
                setSelectedEventId(recentEvent.id);
                setCurrentEvent(recentEvent);
                setupEventChat(recentEvent.id);
                generateLiveKitRoom(recentEvent.id);
                console.log('🎤 Selected most recent event:', recentEvent.title);
              }
            }
          }
        }
      });
      
      console.log('🎥 Streaming setup initialized');
      return unsubscribe;
    } catch (error) {
      console.error('Streaming setup failed:', error);
    }
  };

  const generateLiveKitRoom = (eventId) => {
    const roomName = `event-${eventId}`;
    setLiveKitRoomName(roomName);
    console.log('🏠 LiveKit room name set:', roomName);
  };

  const setupEventChat = (eventId) => {
    if (!eventId) return;
    
    const rtdb = getDatabase();
    const chatRoomPath = `chats/public/event_${eventId}`;
    console.log('🔗 Setting up event chat for:', chatRoomPath);
    
    // Listen to chat room data
    const chatRoomRef = ref(rtdb, chatRoomPath);
    onValue(chatRoomRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setChatRoomData(data);
        setActiveUsers(data.activeUsers || {});
      }
    });
    
    // Listen to messages
    const messagesRef = ref(rtdb, `${chatRoomPath}/messages`);
    onValue(messagesRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const messagesList = Object.entries(data).map(([id, message]) => ({
          id,
          ...message
        })).sort((a, b) => a.timestamp - b.timestamp);
        setChatMessages(messagesList);
      } else {
        setChatMessages([]);
      }
    });
    
    // Add user to active users if logged in
    if (currentUser) {
      const userRef = ref(rtdb, `${chatRoomPath}/activeUsers/${currentUser.uid}`);
      set(userRef, {
        uid: currentUser.uid,
        name: currentUser.displayName || 'Artist',
        avatar: currentUser.photoURL || null,
        joinedAt: Date.now(),
        isStreaming: isStreaming,
        isArtist: true // Mark as artist in chat
      });
    }
  };

  const checkDevicePermissions = async () => {
    try {
      console.log('🎬 Checking basic device permissions...');
      
      // Check if getUserMedia is available
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        throw new Error('Your browser does not support camera/microphone access');
      }
      
      // Request basic permissions (LiveKit will handle device selection)
      const stream = await navigator.mediaDevices.getUserMedia({
        video: true,
        audio: true
      });
      
      console.log('✅ Permissions granted');
      
      // Stop the test stream immediately
      stream.getTracks().forEach(track => track.stop());
      
      setDevicePermissionGranted(true);
      setConnectionStatus('connected');
      
    } catch (error) {
      console.error('❌ Device permissions failed:', error);
      setDevicePermissionGranted(false);
      setConnectionStatus('error');
      
      // Show user-friendly error message
      let errorMessage = 'Failed to access camera and microphone.';
      
      if (error.name === 'NotAllowedError') {
        errorMessage = 'Camera and microphone access was denied. Please allow access in your browser settings and try again.';
      } else if (error.name === 'NotFoundError') {
        errorMessage = 'No camera or microphone found. Please connect your devices and try again.';
      }
      
      throw new Error(errorMessage);
    }
  };

  const sendChatMessage = async () => {
    if (!newMessage.trim() || !currentEvent) return;
    
    const rtdb = getDatabase();
    const messagesPath = `chats/public/event_${currentEvent.id}/messages`;
    const messagesRef = ref(rtdb, messagesPath);
    
    const messageData = {
      type: 'user',
      message: newMessage.trim(),
      timestamp: Date.now(),
      userId: currentUser.uid,
      userName: artistProfile?.stageName || currentUser.displayName || 'Artist',
      userAvatar: artistProfile?.avatar || currentUser.photoURL || null,
      isArtist: true, // Mark as artist message
      badges: ['artist'] // Add artist badge
    };
    
    try {
      await push(messagesRef, messageData);
      setNewMessage('');
      chatInputRef.current?.focus();
    } catch (error) {
      console.error('Failed to send chat message:', error);
    }
  };

  const handleChatKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendChatMessage();
    }
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const formatTime = (timestamp) => {
    return new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const createEvent = async () => {
    try {
      const db = getFirestore();
      
      const eventData = {
        ...eventSetup,
        artistId: currentUser.uid,
        artistName: artistProfile?.stageName || currentUser.displayName,
        artistAvatar: artistProfile?.avatar || currentUser.photoURL,
        artistVerified: artistProfile?.verified || false,
        streamKey,
        streamUrl,
        status: 'scheduled',
        createdAt: serverTimestamp(),
        startTime: new Date(eventSetup.startTime).getTime(),
        viewerCount: 0,
        revenue: 0,
        analytics: {
          totalViews: 0,
          peakViewers: 0,
          chatMessages: 0,
          reactions: 0
        }
      };
      
      const eventRef = await addDoc(collection(db, 'events'), eventData);
      const eventId = eventRef.id;
      
      // Create chat room for the event
      await createEventChatRoom(eventId, eventData);
      
      const newEvent = {
        id: eventId,
        ...eventData
      };
      
      setCurrentEvent(newEvent);
      setSelectedEventId(eventId);
      setupEventChat(eventId);
      generateLiveKitRoom(eventId);
      
      console.log('📅 Event and chat room created:', eventId);
      setActiveTab('stream');
      
    } catch (error) {
      console.error('Failed to create event:', error);
    }
  };
  
  const selectEvent = (eventId) => {
    const selectedEvent = availableEvents.find(e => e.id === eventId);
    if (selectedEvent) {
      setSelectedEventId(eventId);
      setCurrentEvent(selectedEvent);
      setupEventChat(eventId);
      generateLiveKitRoom(eventId);
      console.log('🎤 Selected event for streaming:', selectedEvent.title);
    }
  };
  
  const formatEventTime = (timestamp) => {
    if (!timestamp) return 'Not scheduled';
    return new Date(timestamp).toLocaleString();
  };
  
  const getEventStatusColor = (status) => {
    switch (status) {
      case 'live': return '#ef4444';
      case 'scheduled': return '#f59e0b';
      case 'ended': return '#6b7280';
      default: return '#6b7280';
    }
  };
  
  const getEventStatusText = (status) => {
    switch (status) {
      case 'live': return 'LIVE NOW';
      case 'scheduled': return 'SCHEDULED';
      case 'ended': return 'ENDED';
      default: return status?.toUpperCase() || 'UNKNOWN';
    }
  };

  const createEventChatRoom = async (eventId, eventData) => {
    try {
      const { getDatabase, ref, set, push } = await import('firebase/database');
      const database = getDatabase();
      
      // Create chat room in RTDB under chats/public/ - CORRECT PATH
      const chatRoomPath = `chats/public/event_${eventId}`;
      console.log('🏗️ Creating chat room at:', chatRoomPath);
      const chatRoomData = {
        type: 'event',
        eventId: eventId,
        eventTitle: eventData.title,
        artistId: eventData.artistId,
        artistName: eventData.artistName,
        artistAvatar: eventData.artistAvatar,
        
        // Chat room settings
        isActive: false, // Will be activated when event goes live
        allowUserStreaming: true,
        artistPriority: true,
        maxConcurrentUserStreams: 8,
        
        // Moderation settings
        moderationEnabled: true,
        autoModeration: true,
        slowModeEnabled: false,
        slowModeDelay: 0,
        
        // Access control
        accessLevel: eventData.accessLevel || 'free',
        allowAnonymous: true, // Allow anonymous users in chat
        
        // Video streaming settings
        artistVideoActive: false,
        userStreams: {},
        
        // Analytics
        totalMessages: 0,
        activeUsers: 0,
        peakUsers: 0,
        
        // Timestamps
        createdAt: Date.now(),
        updatedAt: Date.now()
      };
      
      // Create the chat room
      await set(ref(database, chatRoomPath), chatRoomData);
      
      // Create initial system message
      const messagesRef = ref(database, `${chatRoomPath}/messages`);
      await push(messagesRef, {
        type: 'system',
        message: `Welcome to ${eventData.title}! Event chat room created.`,
        timestamp: Date.now(),
        userId: 'system',
        userName: 'System'
      });
      
      console.log('💬 Event chat room created in RTDB:', chatRoomPath);
      
    } catch (error) {
      console.error('Failed to create event chat room:', error);
      // Don't block event creation if chat room fails
    }
  };

  const startStream = async () => {
    try {
      if (!currentEvent) {
        alert('Please select an event first');
        return;
      }
      
      if (!devicePermissionGranted) {
        alert('Camera and microphone permissions required. Please allow access and try again.');
        return;
      }
      
      setIsStreaming(true);
      setConnectionStatus('connecting');
      
      console.log('🎤 Starting LiveKit stream for event:', currentEvent.id);
      
      // Start the streaming service
      const streamStarted = await startEventStream(currentEvent.id);
      
      if (!streamStarted) {
        throw new Error('Failed to start streaming service');
      }
      
      // Update event status to live
      const db = getFirestore();
      await updateDoc(doc(db, 'events', currentEvent.id), {
        status: 'live',
        actualStartTime: serverTimestamp(),
        streamActive: true,
        artistStreaming: true
      });
      
      // Activate the chat room
      await activateEventChatRoom(currentEvent.id);
      
      setConnectionStatus('connected');
      
      // Start analytics tracking
      startAnalyticsTracking();
      
      console.log('✅ LiveKit stream started successfully');
      
    } catch (error) {
      console.error('Failed to start stream:', error);
      setConnectionStatus('error');
      setIsStreaming(false);
      alert(`Failed to start stream: ${error.message}`);
    }
  };

  const activateEventChatRoom = async (eventId) => {
    try {
      const { getDatabase, ref, update } = await import('firebase/database');
      const database = getDatabase();
      
      const chatRoomPath = `chats/public/event_${eventId}`;
      await update(ref(database, chatRoomPath), {
        isActive: true,
        artistVideoActive: true,
        goLiveTime: Date.now(),
        updatedAt: Date.now()
      });
      
      console.log('🟢 Chat room activated for live event:', chatRoomPath);
      
    } catch (error) {
      console.error('Failed to activate chat room:', error);
    }
  };

  const stopStream = async () => {
    try {
      console.log('⏹️ Stopping stream for event:', currentEvent?.id);
      
      if (currentEvent) {
        // Stop the streaming service
        await stopEventStream(currentEvent.id);
        
        // Update event status
        const db = getFirestore();
        await updateDoc(doc(db, 'events', currentEvent.id), {
          status: 'ended',
          endTime: serverTimestamp(),
          streamActive: false,
          artistStreaming: false,
          finalAnalytics: analytics
        });
      }
      
      setIsStreaming(false);
      setLiveKitConnected(false);
      
      console.log('✅ Stream stopped successfully');
      setConnectionStatus('disconnected');
      
    } catch (error) {
      console.error('Failed to stop stream:', error);
      // Still update local state even if service call fails
      setIsStreaming(false);
      setConnectionStatus('disconnected');
    }
  };

  const startAnalyticsTracking = () => {
    // Start real-time analytics using new streaming service
    const statsInterval = setInterval(async () => {
      if (!isStreaming || !currentEvent) {
        clearInterval(statsInterval);
        return;
      }
      
      try {
        // Get real streaming stats from new service
        const realStats = await getStreamingStats(currentEvent.id);
        
        if (realStats) {
          setAnalytics(prev => ({
            ...prev,
            currentViewers: realStats.viewers || prev.currentViewers,
            totalViews: realStats.totalViews || prev.totalViews,
            duration: realStats.duration || prev.duration
          }));
        } else {
          // Fallback to simulated analytics if real stats unavailable
          setAnalytics(prev => ({
            ...prev,
            currentViewers: Math.floor(Math.random() * 100) + prev.currentViewers * 0.9,
            totalViews: prev.totalViews + Math.floor(Math.random() * 5),
            chatMessages: prev.chatMessages + Math.floor(Math.random() * 3),
            reactions: prev.reactions + Math.floor(Math.random() * 2)
          }));
        }
      } catch (error) {
        console.warn('Failed to get streaming stats:', error);
        // Continue with simulated stats
        setAnalytics(prev => ({
          ...prev,
          currentViewers: Math.floor(Math.random() * 50) + prev.currentViewers * 0.95,
          totalViews: prev.totalViews + Math.floor(Math.random() * 3)
        }));
      }
    }, 5000);
    
    // Store interval reference for cleanup
    window.artistStudioStatsInterval = statsInterval;
  };
  
  // Cleanup interval on unmount
  useEffect(() => {
    return () => {
      if (window.artistStudioStatsInterval) {
        clearInterval(window.artistStudioStatsInterval);
        window.artistStudioStatsInterval = null;
      }
      
      // Cleanup RTDB listeners
      if (currentEvent) {
        const rtdb = getDatabase();
        const chatRoomPath = `chats/public/event_${currentEvent.id}`;
        off(ref(rtdb, chatRoomPath));
        off(ref(rtdb, `${chatRoomPath}/messages`));
      }
    };
  }, [currentEvent]);

  // LiveKit Event Handlers
  const handleLiveKitConnected = (room) => {
    setLiveKitConnected(true);
    setConnectionStatus('connected');
    console.log('✅ LiveKit room connected:', room?.name);
  };

  const handleLiveKitDisconnected = () => {
    setLiveKitConnected(false);
    setConnectionStatus('disconnected');
    console.log('❌ LiveKit room disconnected');
  };

  const handleLiveKitError = (error) => {
    setConnectionStatus('error');
    console.error('❌ LiveKit error:', error);
    alert(`LiveKit connection error: ${error.message}`);
  };

  if (loading) {
    return (
      <div className="studio-loading">
        <div className="loading-spinner"></div>
        <p>Initializing Artist Studio...</p>
      </div>
    );
  }

  if (!isArtist) {
    return (
      <div className="studio-access-denied">
        <div className="access-content">
          <Star size={64} />
          <h1>Artist Access Required</h1>
          <p>You need to be a verified artist to access the streaming studio.</p>
          <button onClick={() => navigate('/artist/apply')}>
            Apply to Become an Artist
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="artist-streaming-studio">
      {/* Studio Header */}
      <div className="studio-header">
        <div className="header-info">
          <h1>Artist Streaming Studio</h1>
          <div className="artist-info">
            <div className="artist-avatar">
              {artistProfile?.avatar ? (
                <img src={artistProfile.avatar} alt={artistProfile.stageName} />
              ) : (
                <div className="avatar-placeholder">
                  {artistProfile?.stageName?.charAt(0) || 'A'}
                </div>
              )}
            </div>
            <div className="artist-details">
              <h3>{artistProfile?.stageName || 'Artist'}</h3>
              <div className="connection-status">
                {connectionStatus === 'connected' && (
                  <>
                    <CheckCircle size={16} className="status-connected" />
                    <span>Connected</span>
                  </>
                )}
                {connectionStatus === 'connecting' && (
                  <>
                    <Wifi size={16} className="status-connecting" />
                    <span>Connecting...</span>
                  </>
                )}
                {connectionStatus === 'error' && (
                  <>
                    <AlertCircle size={16} className="status-error" />
                    <span>Connection Error</span>
                  </>
                )}
                {connectionStatus === 'disconnected' && (
                  <>
                    <WifiOff size={16} className="status-disconnected" />
                    <span>Disconnected</span>
                  </>
                )}
              </div>
            </div>
          </div>
        </div>
        
        <div className="header-actions">
          {/* Debug Button - Only visible in developer mode */}
          {isDeveloperMode && (
            <button 
              className="debug-btn"
              onClick={() => setShowDebugPanel(!showDebugPanel)}
              title="Show streaming diagnostics (Dev Mode Only)"
            >
              🔍 Debug
            </button>
          )}
          
          {/* Device Fix Button - Show when connection issues */}
          {connectionStatus !== 'connected' && (
            <button 
              className="fix-devices-btn"
              onClick={async () => {
                console.log('🔧 Attempting to fix device connection...');
                console.log('Current status:', connectionStatus);
                
                try {
                  await checkDevicePermissions();
                  console.log('✅ Device setup completed');
                } catch (error) {
                  console.error('❌ Device setup failed:', error);
                  alert(`Device setup failed: ${error.message}`);
                }
              }}
              title="Retry device connection"
            >
              🔧 Fix Devices
            </button>
          )}
          
          {isStreaming ? (
            <button className="stop-btn" onClick={stopStream}>
              <Square size={16} />
              Stop Stream
            </button>
          ) : (
            <button 
              className="start-btn" 
              onClick={() => {
                console.log('🎬 Go Live button clicked! Checking conditions...');
                console.log('Conditions check:', {
                  currentEvent: !!currentEvent,
                  eventId: currentEvent?.id,
                  connectionStatus,
                  devicePermissionGranted,
                  isDisabled: !currentEvent || connectionStatus !== 'connected' || !devicePermissionGranted
                });
                
                if (!currentEvent) {
                  alert('No event selected. Please select or create an event first.');
                  return;
                }
                
                if (connectionStatus !== 'connected') {
                  alert(`Device connection issue: ${connectionStatus}. Please check your camera and microphone.`);
                  return;
                }
                
                if (!devicePermissionGranted) {
                  alert('Camera and microphone permissions required. Please allow access and try again.');
                  return;
                }
                
                startStream();
              }}
              disabled={!currentEvent || connectionStatus !== 'connected' || !devicePermissionGranted}
            >
              <Radio size={16} />
              {!currentEvent ? 'Select Event First' : 
               connectionStatus !== 'connected' ? 'Device Issues' :
               !devicePermissionGranted ? 'Permissions Required' :
               'Go Live'}
            </button>
          )}
        </div>
      </div>

      {/* Studio Tabs */}
      <div className="studio-tabs">
        {console.log('📝 Rendering studio tabs, activeTab:', activeTab)}
        <button 
          className={`tab ${activeTab === 'setup' ? 'active' : ''}`}
          onClick={() => setActiveTab('setup')}
        >
          <Settings size={16} />
          Event Setup
        </button>
        <button 
          className={`tab ${activeTab === 'stream' ? 'active' : ''}`}
          onClick={() => setActiveTab('stream')}
        >
          <Video size={16} />
          Live Stream
        </button>
        <button 
          className={`tab ${activeTab === 'dj-studio' ? 'active' : ''}`}
          onClick={() => {
            console.log('🎛️ DJ Studio tab clicked!');
            setActiveTab('dj-studio');
          }}
          style={{ backgroundColor: activeTab === 'dj-studio' ? '#4ecdc4' : 'rgba(255,255,255,0.1)' }}
        >
          <Headphones size={16} />
          🎛️ DJ Studio
        </button>
        <button 
          className={`tab ${activeTab === 'analytics' ? 'active' : ''}`}
          onClick={() => setActiveTab('analytics')}
        >
          <Eye size={16} />
          Analytics
        </button>
      </div>

      {/* Tab Content */}
      <div className="studio-content">
        {activeTab === 'setup' && (
          <div className="setup-panel">
            {/* Event Selection/Creation Mode Toggle */}
            <div className="event-mode-section">
              <h2>Event Setup</h2>
              
              {availableEvents.length > 0 && (
                <div className="mode-selector">
                  <button 
                    className={`mode-btn ${eventMode === 'select' ? 'active' : ''}`}
                    onClick={() => setEventMode('select')}
                  >
                    <Calendar size={16} />
                    Select Existing Event
                  </button>
                  <button 
                    className={`mode-btn ${eventMode === 'create' ? 'active' : ''}`}
                    onClick={() => setEventMode('create')}
                  >
                    <Plus size={16} />
                    Create New Event
                  </button>
                </div>
              )}
            </div>
            
            {eventMode === 'select' && availableEvents.length > 0 ? (
              <div className="event-selector">
                <div className="form-group">
                  <label>Select Event to Stream</label>
                  <select
                    value={selectedEventId}
                    onChange={(e) => selectEvent(e.target.value)}
                    className="event-dropdown"
                  >
                    <option value="">Choose an event...</option>
                    {availableEvents.map((event) => (
                      <option key={event.id} value={event.id}>
                        {event.title} - {getEventStatusText(event.status)} - {formatEventTime(event.startTime)}
                      </option>
                    ))}
                  </select>
                </div>
                
                {currentEvent && (
                  <div className="event-preview">
                    <div className="event-preview-header">
                      <h3>{currentEvent.title}</h3>
                      <span 
                        className="status-badge"
                        style={{ 
                          backgroundColor: getEventStatusColor(currentEvent.status),
                          color: 'white',
                          padding: '4px 8px',
                          borderRadius: '4px',
                          fontSize: '12px',
                          fontWeight: 'bold'
                        }}
                      >
                        {getEventStatusText(currentEvent.status)}
                      </span>
                    </div>
                    
                    <p className="event-description">{currentEvent.description}</p>
                    
                    <div className="event-details">
                      <div className="detail-row">
                        <Clock size={16} />
                        <span><strong>Start Time:</strong> {formatEventTime(currentEvent.startTime)}</span>
                      </div>
                      <div className="detail-row">
                        <Users size={16} />
                        <span><strong>Max Viewers:</strong> {currentEvent.maxViewers || 500}</span>
                      </div>
                      <div className="detail-row">
                        <DollarSign size={16} />
                        <span><strong>Ticket Price:</strong> ${currentEvent.ticketPrice || 'Free'}</span>
                      </div>
                      <div className="detail-row">
                        <span className="category-badge">{currentEvent.category}</span>
                      </div>
                    </div>
                    
                    {currentEvent.status === 'ended' && (
                      <div className="event-warning">
                        <AlertCircle size={16} />
                        <span>This event has already ended. You can still stream to it for testing purposes.</span>
                      </div>
                    )}
                    
                    <div className="event-actions">
                      <button 
                        className="stream-to-event-btn"
                        onClick={() => {
                          setActiveTab('stream');
                        }}
                        disabled={!selectedEventId}
                      >
                        <Radio size={16} />
                        Stream to This Event
                      </button>
                      
                      <button 
                        className="view-chat-btn"
                        onClick={() => navigate(`/events/${currentEvent.id}/chat`)}
                      >
                        <Users size={16} />
                        View Event Chat
                      </button>
                    </div>
                  </div>
                )}
                
                {availableEvents.length === 0 && (
                  <div className="no-events">
                    <Calendar size={48} />
                    <h3>No Events Found</h3>
                    <p>You haven't created any events yet. Create your first event to start streaming!</p>
                    <button 
                      className="create-first-event-btn"
                      onClick={() => setEventMode('create')}
                    >
                      <Plus size={16} />
                      Create Your First Event
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="setup-form">
                <h3>Create New Event</h3>
                
                <div className="form-group">
                  <label>Event Title</label>
                  <input
                    type="text"
                    value={eventSetup.title}
                    onChange={(e) => setEventSetup(prev => ({ ...prev, title: e.target.value }))}
                    placeholder="Enter event title..."
                  />
                </div>
                
                <div className="form-group">
                  <label>Description</label>
                  <textarea
                    value={eventSetup.description}
                    onChange={(e) => setEventSetup(prev => ({ ...prev, description: e.target.value }))}
                    placeholder="Describe your event..."
                    rows={3}
                  />
                </div>
                
                <div className="form-row">
                  <div className="form-group">
                    <label>Ticket Price ($)</label>
                    <input
                      type="number"
                      value={eventSetup.ticketPrice}
                      onChange={(e) => setEventSetup(prev => ({ ...prev, ticketPrice: parseFloat(e.target.value) }))}
                      min="0"
                      step="0.01"
                    />
                  </div>
                  
                  <div className="form-group">
                    <label>Category</label>
                    <select
                      value={eventSetup.category}
                      onChange={(e) => setEventSetup(prev => ({ ...prev, category: e.target.value }))}
                    >
                      <option value="music">Music</option>
                      <option value="talk">Talk Show</option>
                      <option value="performance">Performance</option>
                      <option value="workshop">Workshop</option>
                    </select>
                  </div>
                </div>
                
                <div className="form-row">
                  <div className="form-group">
                    <label>Start Time</label>
                    <input
                      type="datetime-local"
                      value={eventSetup.startTime}
                      onChange={(e) => setEventSetup(prev => ({ ...prev, startTime: e.target.value }))}
                    />
                  </div>
                  
                  <div className="form-group">
                    <label>Duration (minutes)</label>
                    <input
                      type="number"
                      value={eventSetup.duration}
                      onChange={(e) => setEventSetup(prev => ({ ...prev, duration: parseInt(e.target.value) }))}
                      min="15"
                      max="300"
                    />
                  </div>
                </div>
                
                <div className="form-actions">
                  <button className="create-event-btn" onClick={createEvent}>
                    <Calendar size={16} />
                    Create Event
                  </button>
                </div>
              </div>
            )}
            
            <div className="setup-preview">
              <h3>LiveKit Streaming Settings</h3>
              
              {/* Permission Status */}
              {!devicePermissionGranted && (
                <div className="permission-warning">
                  <AlertCircle size={16} />
                  <span>Camera and microphone access required for streaming</span>
                  <button onClick={checkDevicePermissions} className="retry-permission-btn">
                    Grant Permissions
                  </button>
                </div>
              )}
              
              {devicePermissionGranted && (
                <div className="permission-success">
                  <CheckCircle size={16} />
                  <span>Device permissions granted - Ready for LiveKit streaming</span>
                </div>
              )}
              
              <h3>Technical Setup</h3>
              <div className="tech-info">
                <div className="info-item">
                  <Zap size={16} />
                  <span>Streaming: LiveKit Ultra-Low Latency</span>
                </div>
                <div className="info-item">
                  <Monitor size={16} />
                  <span>Quality: Adaptive (up to 1080p)</span>
                </div>
                <div className="info-item">
                  <Radio size={16} />
                  <span>Room: {liveKitRoomName || 'Not selected'}</span>
                </div>
                {currentEvent && (
                  <div className="info-item">
                    <Users size={16} />
                    <span>Target Event: {currentEvent.title}</span>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'stream' && (
          <div className="stream-panel">
            <div className="stream-main">
              {/* LiveKit Video Container */}
              <div className="livekit-video-container">
                {isStreaming && liveKitRoomName && currentEvent ? (
                  <LiveKitRoom
                    roomName={liveKitRoomName}
                    participantName={artistProfile?.stageName || currentUser?.displayName || 'Artist'}
                    onConnected={handleLiveKitConnected}
                    onDisconnected={handleLiveKitDisconnected}
                    onError={handleLiveKitError}
                    className="artist-studio-livekit-room"
                    isCreator={true}
                    eventId={currentEvent?.id}
                    options={{ video: true, audio: true }}
                  />
                ) : (
                  <div className="stream-preview-placeholder">
                    <div className="preview-content">
                      <Zap size={48} />
                      <h3>LiveKit Stream Ready</h3>
                      {!currentEvent ? (
                        <p>Select an event to begin streaming</p>
                      ) : !isStreaming ? (
                        <p>Click "Go Live" to start your LiveKit stream</p>
                      ) : (
                        <p>Connecting to LiveKit room...</p>
                      )}
                    </div>
                  </div>
                )}
              </div>
              
              {/* Current Event Info */}
              {currentEvent && (
                <div className="current-event">
                  <h3>{currentEvent.title}</h3>
                  <p>{currentEvent.description}</p>
                  <div className="event-meta">
                    <div className="meta-item">
                      <Users size={16} />
                      <span>{analytics.currentViewers} watching</span>
                    </div>
                    <div className="meta-item">
                      <DollarSign size={16} />
                      <span>${currentEvent.ticketPrice}</span>
                    </div>
                    <div className="meta-item">
                      <Clock size={16} />
                      <span>{currentEvent.duration} min</span>
                    </div>
                    {liveKitConnected && (
                      <div className="meta-item">
                        <Zap size={16} style={{ color: '#10b981' }} />
                        <span>LiveKit Connected</span>
                      </div>
                    )}
                  </div>
                </div>
              )}
              
              {/* Live Stats - Moved below video */}
              <div className="analytics-mini">
                <h4>Live Stats</h4>
                <div className="stat-grid">
                  <div className="stat-item">
                    <Eye size={16} />
                    <div>
                      <span className="stat-value">{analytics.currentViewers}</span>
                      <span className="stat-label">Viewers</span>
                    </div>
                  </div>
                  <div className="stat-item">
                    <Users size={16} />
                    <div>
                      <span className="stat-value">{analytics.totalViews}</span>
                      <span className="stat-label">Total Views</span>
                    </div>
                  </div>
                  <div className="stat-item">
                    <Star size={16} />
                    <div>
                      <span className="stat-value">{analytics.reactions}</span>
                      <span className="stat-label">Reactions</span>
                    </div>
                  </div>
                  <div className="stat-item">
                    <DollarSign size={16} />
                    <div>
                      <span className="stat-value">${analytics.revenue.toFixed(2)}</span>
                      <span className="stat-label">Revenue</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
            
            {/* Stream Actions */}
            <div className="stream-actions">
              <button 
                className="action-btn"
                onClick={() => window.open(`/events/${currentEvent?.id}/chat`, '_blank')}
                disabled={!currentEvent}
              >
                <ExternalLink size={16} />
                Open Chat
              </button>
              <button className="action-btn">
                <Share2 size={16} />
                Share Event
              </button>
              <button className="action-btn">
                <Save size={16} />
                Save Recording
              </button>
            </div>
          </div>
        )}

        {activeTab === 'analytics' && (
          <div className="analytics-panel">
            <div className="analytics-overview">
              <h2>Stream Analytics</h2>
              <div className="analytics-cards">
                <div className="analytics-card">
                  <div className="card-header">
                    <Eye size={20} />
                    <h3>Current Viewers</h3>
                  </div>
                  <div className="card-value">{analytics.currentViewers}</div>
                  <div className="card-change">Peak: {analytics.peakViewers}</div>
                </div>
                
                <div className="analytics-card">
                  <div className="card-header">
                    <Users size={20} />
                    <h3>Total Views</h3>
                  </div>
                  <div className="card-value">{analytics.totalViews}</div>
                  <div className="card-change">+12% from last stream</div>
                </div>
                
                <div className="analytics-card">
                  <div className="card-header">
                    <Star size={20} />
                    <h3>Engagement</h3>
                  </div>
                  <div className="card-value">{analytics.reactions}</div>
                  <div className="card-change">{analytics.chatMessages} messages</div>
                </div>
                
                <div className="analytics-card">
                  <div className="card-header">
                    <DollarSign size={20} />
                    <h3>Revenue</h3>
                  </div>
                  <div className="card-value">${analytics.revenue.toFixed(2)}</div>
                  <div className="card-change">+8% from last event</div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* DJ Studio Panel - Keep mounted but hidden to preserve state */}
        <div
          className="dj-studio-panel"
          style={{
            display: activeTab === 'dj-studio' ? 'block' : 'none',
            backgroundColor: '#1a1a1a',
            minHeight: '400px',
            padding: '20px',
            position: 'relative'
          }}
        >
          {console.log('🎛️ DJ Studio panel mounted, visible:', activeTab === 'dj-studio')}

          {/* DJ Streaming Diagnostic - Show when in DJ Studio tab and developer mode */}
          {activeTab === 'dj-studio' && isDeveloperMode && (
            <DJStreamingDiagnostic
              isStreaming={isStreaming}
              streamingService={{
                getLiveKitService,
                startEventStream,
                stopEventStream,
                getStreamingStats
              }}
            />
          )}

          <h2 style={{ color: 'white', marginBottom: '20px' }}>🎛️ DJ Studio Integration</h2>
          <div style={{ color: '#4ecdc4', marginBottom: '10px' }}>Status: DJ Studio component loaded successfully!</div>
          <div style={{ color: 'white', marginBottom: '20px' }}>Mix tracks and stream your DJ sets live!</div>
          <DJStudioArtistIntegration
            artistProfile={artistProfile}
            currentEvent={currentEvent}
            isStreaming={isStreaming}
            onStreamingUpdate={(streamData) => {
              console.log('📊 DJ Stream Update:', streamData);
              // Update streaming analytics with DJ mix data
              setAnalytics(prev => ({
                ...prev,
                ...streamData
              }));
            }}
            streamingService={{
              startEventStream,
              stopEventStream,
              getStreamingStats,
              getLiveKitService: () => {
                // Import at call time to avoid hook issues
                return liveKitService;
              }
            }}
            analytics={analytics}
          />
        </div>
      </div>

      {/* Chat Section - Now Below Video Instead of In Sidebar */}
      {currentEvent && (
        <div className="event-chat-section chat-below-video">
          <div className="chat-header">
            <MessageCircle size={16} />
            <span>Event Chat</span>
            <span className="message-count">({chatMessages.length})</span>
          </div>
          
          {/* Chat Messages */}
          <div className="chat-messages">
            <div className="messages-container">
              {chatMessages.map((message) => (
                <div key={message.id} className={`message ${message.type}`}>
                  {message.type === 'system' ? (
                    <div className="system-message">
                      <span className="system-text">{message.message}</span>
                      <span className="message-time">{formatTime(message.timestamp)}</span>
                    </div>
                  ) : (
                    <div className="user-message">
                      <div className="message-avatar">
                        {message.userAvatar ? (
                          <img src={message.userAvatar} alt={message.userName} />
                        ) : (
                          <div className="avatar-placeholder">
                            {message.userName?.charAt(0) || 'A'}
                          </div>
                        )}
                      </div>
                      <div className="message-content">
                        <div className="message-header">
                          <span className="message-author">
                            {message.userName}
                            {message.isArtist && (
                              <Crown size={12} className="artist-badge" />
                            )}
                          </span>
                          <span className="message-time">{formatTime(message.timestamp)}</span>
                        </div>
                        <p className="message-text">{message.message}</p>
                      </div>
                    </div>
                  )}
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>
          </div>

          {/* Chat Input */}
          <div className="chat-input-container">
            <div className="chat-input">
              <input
                ref={chatInputRef}
                type="text"
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                onKeyPress={handleChatKeyPress}
                placeholder="Type a message as the artist..."
                maxLength={500}
              />
              <button 
                className="send-btn"
                onClick={sendChatMessage}
                disabled={!newMessage.trim()}
              >
                <Send size={16} />
              </button>
            </div>
          </div>
        </div>
      )}
      
      {/* Debug Panel - Only visible in developer mode */}
      {isDeveloperMode && showDebugPanel && (
        <StreamingDebugPanel onClose={() => setShowDebugPanel(false)} />
      )}
    </div>
  );
};

export default ArtistStreamingStudio;