import React from 'react';
import { useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import { useDeveloperMode, isProduction } from '../../utils/devMode';

const RouterDebugger = () => {
  // All hooks must run unconditionally (Rules of Hooks).
  const devMode = useDeveloperMode();
  const location = useLocation();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();

  // Gated by production-host check + developer-mode toggle. Production
  // always wins; otherwise respect the Ctrl+Alt+D flag.
  if (isProduction() || !devMode) return null;
  
  const testWatchReplays = () => {
    navigate('/watch-replays?event=t6xQpo0OZAxzaGlOCU3u');
  };
  
  const testDirect = () => {
    window.location.href = '/watch-replays?event=t6xQpo0OZAxzaGlOCU3u';
  };
  
  return (
    <div style={{
      position: 'fixed',
      top: '10px',
      right: '10px',
      background: '#1a1a1a',
      color: '#fff',
      padding: '15px',
      borderRadius: '8px',
      fontFamily: 'monospace',
      fontSize: '12px',
      zIndex: 9999,
      maxWidth: '300px',
      border: '2px solid #333'
    }}>
      <h3 style={{ margin: '0 0 10px 0', color: '#4CAF50' }}>🔍 Router Debug</h3>
      
      <div style={{ marginBottom: '10px' }}>
        <strong>Current Path:</strong><br/>
        <code>{location.pathname}</code>
      </div>
      
      <div style={{ marginBottom: '10px' }}>
        <strong>Search Params:</strong><br/>
        <code>{location.search}</code>
      </div>
      
      <div style={{ marginBottom: '10px' }}>
        <strong>Full Location:</strong><br/>
        <code>{window.location.href}</code>
      </div>
      
      <div style={{ marginBottom: '10px' }}>
        <strong>Search Params Object:</strong><br/>
        <code>{JSON.stringify(Object.fromEntries(searchParams), null, 2)}</code>
      </div>
      
      <div style={{ marginBottom: '15px' }}>
        <strong>Test Routes:</strong>
      </div>
      
      <button 
        onClick={testWatchReplays}
        style={{
          background: '#2196F3',
          color: 'white',
          border: 'none',
          padding: '5px 10px',
          margin: '2px',
          borderRadius: '4px',
          cursor: 'pointer',
          fontSize: '11px'
        }}
      >
        Test /watch-replays (React Router)
      </button>
      
      <button 
        onClick={testDirect}
        style={{
          background: '#FF9800',
          color: 'white',
          border: 'none',
          padding: '5px 10px',
          margin: '2px',
          borderRadius: '4px',
          cursor: 'pointer',
          fontSize: '11px'
        }}
      >
        Test Direct Navigation
      </button>
      
      <button 
        onClick={() => navigate('/')}
        style={{
          background: '#4CAF50',
          color: 'white',
          border: 'none',
          padding: '5px 10px',
          margin: '2px',
          borderRadius: '4px',
          cursor: 'pointer',
          fontSize: '11px'
        }}
      >
        Go Home
      </button>
    </div>
  );
};

export default RouterDebugger;
