import React from 'react';
import { Link } from 'react-router-dom';
import { Shield, Home, AlertTriangle } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';

/**
 * UnauthorizedPage - Displayed when a user tries to access a page they don't have permissions for
 */
const UnauthorizedPage = () => {
  const { currentUser } = useAuth();

  return (
    <div className="flex flex-col items-center justify-center min-h-[70vh] text-center px-4">
      <div className="bg-red-50 rounded-full p-6 mb-6">
        <AlertTriangle size={64} className="text-red-500" />
      </div>
      
      <h1 className="text-3xl font-bold text-gray-800 mb-4">
        Access Denied
      </h1>
      
      <p className="text-lg text-gray-600 max-w-lg mb-8">
        You don't have permission to access this page. This area requires administrator privileges.
      </p>
      
      <div className="flex flex-col sm:flex-row gap-4">
        <Link 
          to="/" 
          className="bg-indigo-600 text-white px-6 py-3 rounded-lg font-medium flex items-center justify-center hover:bg-indigo-700 transition duration-200"
        >
          <Home size={20} className="mr-2" />
          Return to Home
        </Link>
        
        {currentUser && (
          <Link 
            to="/settings" 
            className="bg-gray-200 text-gray-800 px-6 py-3 rounded-lg font-medium flex items-center justify-center hover:bg-gray-300 transition duration-200"
          >
            <Shield size={20} className="mr-2" />
            Account Settings
          </Link>
        )}
      </div>
      
      <div className="mt-8 p-4 bg-amber-50 border border-amber-200 rounded-lg max-w-lg">
        <p className="text-amber-800">
          If you believe you should have access to this page, please contact the site administrator.
        </p>
      </div>
    </div>
  );
};

export default UnauthorizedPage;
