import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { PlusCircle, X, Coins } from 'lucide-react'
import { categories } from '../utils/categories'
import { usePredictions } from '../contexts/PredictionContext'
import { usePredictCredits, InsufficientCreditsError } from '../hooks/usePredictCredits'
import Card from '../components/common/Card'

export default function SubmitPrediction() {
  const navigate = useNavigate()
  const { addPrediction } = usePredictions()
  const { balance, costs, spendForAction } = usePredictCredits()
  const [error, setError] = useState(null)
  const [submitting, setSubmitting] = useState(false)
  const [form, setForm] = useState({
    title: '',
    description: '',
    category: 'charts',
    deadline: '',
    outcomes: [{ label: '', probability: 50 }, { label: '', probability: 50 }],
  })

  function updateField(field, value) {
    setForm(f => ({ ...f, [field]: value }))
  }

  function updateOutcome(index, field, value) {
    setForm(f => {
      const outcomes = [...f.outcomes]
      outcomes[index] = { ...outcomes[index], [field]: value }
      return { ...f, outcomes }
    })
  }

  function addOutcome() {
    if (form.outcomes.length >= 5) return
    setForm(f => ({ ...f, outcomes: [...f.outcomes, { label: '', probability: 0 }] }))
  }

  function removeOutcome(index) {
    if (form.outcomes.length <= 2) return
    setForm(f => ({ ...f, outcomes: f.outcomes.filter((_, i) => i !== index) }))
  }

  async function handleSubmit(e) {
    e.preventDefault()
    if (submitting) return
    setError(null)
    setSubmitting(true)

    const prediction = {
      id: `user-${Date.now()}`,
      title: form.title,
      description: form.description,
      category: form.category,
      outcomes: form.outcomes.map(o => ({ ...o, probability: Number(o.probability), trend: 'stable' })),
      inputs: [{ source: 'community', type: 'community', weight: 0.5, sentiment: form.outcomes[0].probability / 100, reliability: 0.55, timestamp: new Date().toISOString() }],
      deadline: new Date(form.deadline).toISOString(),
      status: 'active',
      createdBy: 'community-user-1',
      communityVotes: { agree: 0, disagree: 0 },
      historicalAccuracy: null,
      resolvedOutcome: null,
      trendData: [form.outcomes[0].probability],
      featured: false,
      createdAt: new Date().toISOString(),
    }

    try {
      // Charge credits first; if this throws we never persist the prediction.
      // prediction.id is the idempotency key so a double-submit can't double-charge.
      await spendForAction('submit', { title: form.title, category: form.category }, prediction.id)
      await addPrediction(prediction)
      navigate('/')
    } catch (err) {
      if (err instanceof InsufficientCreditsError) {
        setError(
          `You need ${costs.submit} credits to submit a prediction` +
          (err.available != null ? ` (you have ${err.available}).` : '.'),
        )
      } else {
        console.warn('[SubmitPrediction] submit failed:', err?.message)
        setError(err?.message || 'Could not submit your prediction. Please try again.')
      }
      setSubmitting(false)
    }
  }

  return (
    <div className="max-w-2xl space-y-6">
      <div className="flex items-start justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Submit Prediction</h1>
          <p className="text-sm text-gray-500 mt-1">
            Create a new prediction for the community to track · costs{' '}
            <span className="font-mono text-amber-400">{costs.submit}</span> credits
          </p>
        </div>
        <div className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-gray-900/60 border border-gray-800 text-sm">
          <Coins size={15} className="text-amber-400" />
          <span className="text-gray-400">Balance:</span>
          <span className="font-mono text-gray-200">
            {balance == null ? '—' : balance.toLocaleString()}
          </span>
        </div>
      </div>

      <Card className="p-6" hover={false}>
        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="block text-sm font-medium text-gray-300 mb-1.5">Title</label>
            <input
              type="text"
              required
              value={form.title}
              onChange={e => updateField('title', e.target.value)}
              placeholder="e.g., A pop single debuts at #1 on the Billboard Hot 100"
              className="w-full px-3 py-2 bg-gray-800/50 border border-gray-700 rounded-lg text-sm text-gray-200 placeholder-gray-600 focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500/30"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-300 mb-1.5">Description</label>
            <textarea
              required
              rows={3}
              value={form.description}
              onChange={e => updateField('description', e.target.value)}
              placeholder="Provide context and what data supports this prediction..."
              className="w-full px-3 py-2 bg-gray-800/50 border border-gray-700 rounded-lg text-sm text-gray-200 placeholder-gray-600 focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500/30 resize-none"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-300 mb-1.5">Category</label>
              <select
                value={form.category}
                onChange={e => updateField('category', e.target.value)}
                className="w-full px-3 py-2 bg-gray-800/50 border border-gray-700 rounded-lg text-sm text-gray-200 focus:outline-none focus:border-blue-500 cursor-pointer"
              >
                {categories.map(c => (
                  <option key={c.id} value={c.id}>{c.label}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-300 mb-1.5">Deadline</label>
              <input
                type="date"
                required
                value={form.deadline}
                onChange={e => updateField('deadline', e.target.value)}
                className="w-full px-3 py-2 bg-gray-800/50 border border-gray-700 rounded-lg text-sm text-gray-200 focus:outline-none focus:border-blue-500"
              />
            </div>
          </div>

          <div>
            <div className="flex items-center justify-between mb-2">
              <label className="text-sm font-medium text-gray-300">Outcomes</label>
              <button type="button" onClick={addOutcome} className="text-xs text-blue-400 hover:text-blue-300 flex items-center gap-1">
                <PlusCircle size={12} /> Add outcome
              </button>
            </div>
            <div className="space-y-2">
              {form.outcomes.map((outcome, i) => (
                <div key={i} className="flex items-center gap-2">
                  <input
                    type="text"
                    required
                    value={outcome.label}
                    onChange={e => updateOutcome(i, 'label', e.target.value)}
                    placeholder={`Outcome ${i + 1}`}
                    className="flex-1 px-3 py-2 bg-gray-800/50 border border-gray-700 rounded-lg text-sm text-gray-200 placeholder-gray-600 focus:outline-none focus:border-blue-500"
                  />
                  <input
                    type="number"
                    min={0}
                    max={100}
                    required
                    value={outcome.probability}
                    onChange={e => updateOutcome(i, 'probability', e.target.value)}
                    className="w-20 px-3 py-2 bg-gray-800/50 border border-gray-700 rounded-lg text-sm text-gray-200 font-mono text-center focus:outline-none focus:border-blue-500"
                  />
                  <span className="text-xs text-gray-500">%</span>
                  {form.outcomes.length > 2 && (
                    <button type="button" onClick={() => removeOutcome(i)} className="text-gray-600 hover:text-red-400">
                      <X size={14} />
                    </button>
                  )}
                </div>
              ))}
            </div>
          </div>

          {error && (
            <div className="p-3 rounded-lg bg-red-500/10 border border-red-500/30 text-red-300 text-sm">
              {error}{' '}
              <button
                type="button"
                onClick={() => navigate('/credits')}
                className="underline text-red-200 hover:text-white"
              >
                Buy more credits
              </button>
            </div>
          )}

          <button
            type="submit"
            disabled={submitting}
            className="w-full py-2.5 bg-blue-600 hover:bg-blue-500 disabled:bg-gray-700 disabled:cursor-wait text-white font-medium rounded-lg text-sm transition-colors flex items-center justify-center gap-2"
          >
            <Coins size={15} />
            {submitting ? 'Submitting…' : `Submit Prediction · ${costs.submit} credits`}
          </button>
        </form>
      </Card>
    </div>
  )
}
