import React, { useState } from 'react';
import { AudioListenerComponent } from './components/AudioListenerComponent';
import { useAudioDetectionFixed } from './hooks/useAudioDetectionFixed';
import { AudioMatchingService } from './services/AudioMatchingService';
import { getDb, getRtdb } from './firebase';

export default function AudioProfileTest() {
  const [debugMode, setDebugMode] = useState(true);
  const [testResults, setTestResults] = useState(null);
  const audioDetection = useAudioDetectionFixed();
  
  const runTest = async () => {
    console.log('Running comprehensive test...');
    const result = await audioDetection.testFingerprint();
    setTestResults(result);
    
    // Test the matching service
    const matchingService = new AudioMatchingService(getDb(), getRtdb());
    console.log('Matching threshold:', matchingService.MATCH_THRESHOLD);
  };
  
  return (
    <div style={{ 
      padding: '20px',
      fontFamily: 'Arial, sans-serif',
      maxWidth: '800px',
      margin: '0 auto'
    }}>
      <h1>Audio Fingerprint Test</h1>
      
      <div style={{ marginBottom: '20px' }}>
        <button
          onClick={() => setDebugMode(!debugMode)}
          style={{
            padding: '10px 20px',
            backgroundColor: '#2196F3',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
            marginRight: '10px'
          }}
        >
          {debugMode ? 'Hide Debug' : 'Show Debug'}
        </button>
        
        <button
          onClick={runTest}
          style={{
            padding: '10px 20px',
            backgroundColor: '#4CAF50',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer'
          }}
        >
          Test Fingerprint System
        </button>
      </div>
      
      {debugMode && (
        <div style={{
          marginBottom: '20px',
          padding: '15px',
          backgroundColor: '#f5f5f5',
          borderRadius: '4px',
          fontSize: '14px'
        }}>
          <h3>Debug Information</h3>
          <p><strong>How the algorithm works:</strong></p>
          <ul>
            <li>Audio divided into 64 time windows</li>
            <li>Each window analyzed for 33 frequency bands</li>
            <li>Creates 2-bit difference hashes between adjacent bins</li>
            <li>Fingerprint is 256 2-bit values (0-3)</li>
            <li>Compares exact value matches</li>
            <li>Match threshold: 70%</li>
          </ul>
          
          <p style={{ marginTop: '10px' }}><strong>Key features:</strong></p>
          <ul>
            <li>Time-frequency energy differences</li>
            <li>Logarithmic frequency bands (80Hz-8kHz)</li>
            <li>Robust to small time shifts</li>
            <li>Distinctive fingerprints for different audio</li>
          </ul>
          
          {testResults && (
            <div style={{ marginTop: '15px' }}>
              <h4>Test Results:</h4>
              <p>Self-similarity (same audio): {!isNaN(testResults.selfSimilarity) ? (testResults.selfSimilarity * 100).toFixed(2) : '0.00'}%</p>
              <p>Different audio similarity: {!isNaN(testResults.differentSimilarity) ? (testResults.differentSimilarity * 100).toFixed(2) : '0.00'}%</p>
              <p>Same audio similarity: {!isNaN(testResults.sameSimilarity) ? (testResults.sameSimilarity * 100).toFixed(2) : '0.00'}%</p>
              
              <div style={{ marginTop: '10px' }}>
                <p style={{ color: testResults.selfSimilarity > 0.95 ? 'green' : 'red' }}>
                  {testResults.selfSimilarity > 0.95 ? '✓ Self-test passed' : '✗ Self-test failed'}
                </p>
                <p style={{ color: testResults.differentSimilarity < 0.75 ? 'green' : 'red' }}>
                  {testResults.differentSimilarity < 0.75 ? '✓ Discrimination test passed' : '✗ Discrimination test failed'}
                </p>
                <p style={{ color: testResults.sameSimilarity > 0.75 ? 'green' : 'red' }}>
                  {testResults.sameSimilarity > 0.75 ? '✓ Same audio test passed' : '✗ Same audio test failed'}
                </p>
              </div>
              
              {testResults.fingerprints && (
                <div style={{ marginTop: '10px', fontSize: '12px', fontFamily: 'monospace' }}>
                  <p>Sample fingerprint values:</p>
                  <p>FP1: {JSON.stringify(testResults.fingerprints.fp1)}</p>
                  <p>FP2: {JSON.stringify(testResults.fingerprints.fp2)}</p>
                  <p>FP3: {JSON.stringify(testResults.fingerprints.fp3)}</p>
                </div>
              )}
            </div>
          )}
        </div>
      )}
      
      <AudioListenerComponent />
    </div>
  );
}