// src/services/PremiumCheckoutService.js
//
// The one place that knows how to start a TalkStudio Premium purchase.
//
// Payments go through the existing payment-proxy Cloud Run service (the same
// one paymentservice.js and the legacy checkout modals talk to). The proxy
// owns the Stripe secret key: we POST the plan + user id, it creates the
// subscription/payment intent in Stripe and hands back a client secret that
// Stripe Elements confirms in the browser.
//
// Entitlement is granted after confirmation on /subscription-success, which
// writes users/{uid}.isPremium via SubscriptionService — see PLAN_QUERY below.

import { PAYMENT_PROXY_URL } from '../config/cloudRunConfig';

/** Endpoint on the payment proxy that creates a premium membership intent. */
const PREMIUM_MEMBERSHIP_ENDPOINT = '/api/subscriptions/premium-membership';

/**
 * TalkStudio Premium plans. `id` is the value the payment proxy expects in
 * its `plan` field — do not rename without changing the proxy.
 */
export const PREMIUM_PLANS = [
  {
    id: 'monthly',
    name: 'Premium',
    displayPrice: '$9.99',
    interval: '/mo',
    priceCents: 999,
    durationDays: 30,
    tagline: 'Everything unlocked, billed monthly',
  },
  {
    id: 'yearly',
    name: 'Premium Yearly',
    displayPrice: '$99.99',
    interval: '/yr',
    priceCents: 9999,
    durationDays: 365,
    tagline: 'Two months free vs. monthly',
  },
];

/** Look up a plan by its id, or undefined. */
export const getPlan = (planId) => PREMIUM_PLANS.find((p) => p.id === planId);

/**
 * Ask the payment proxy for a client secret for `planId`.
 *
 * Deliberately sends only Content-Type: the proxy's CORS config allows the
 * simple headers, and adding an Authorization header here has previously
 * tripped preflight. The proxy authorizes on the userId in the body.
 *
 * @param {'monthly'|'yearly'} planId
 * @param {string} userId Firebase uid of the purchasing user.
 * @returns {Promise<{clientSecret: string}>}
 */
export async function createPremiumMembershipIntent(planId, userId) {
  const plan = getPlan(planId);
  if (!plan) throw new Error(`Unknown premium plan: ${planId}`);
  if (!userId) throw new Error('You must be signed in to upgrade.');

  let response;
  try {
    response = await fetch(`${PAYMENT_PROXY_URL}${PREMIUM_MEMBERSHIP_ENDPOINT}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ plan: plan.id, userId }),
    });
  } catch (networkError) {
    // fetch() only rejects on network/CORS failure, which users can't act on.
    console.error('Payment service unreachable:', networkError);
    throw new Error("We couldn't reach the payment service. Please try again in a moment.");
  }

  if (!response.ok) {
    const detail = await response.text().catch(() => '');
    console.error(`Payment service error ${response.status}:`, detail);
    throw new Error(`Payment service error (${response.status}). Please try again.`);
  }

  const data = await response.json();
  const clientSecret = data.clientSecret || data.client_secret;
  if (!clientSecret) {
    throw new Error('Payment service did not return a client secret.');
  }

  return { ...data, clientSecret };
}

/**
 * Where Stripe should land the user after confirming — including redirect
 * payment methods, which leave the page entirely. SubscriptionSuccess reads
 * `plan` and `amount` from the query to grant the right entitlement, and
 * Stripe appends payment_intent + redirect_status on its way back.
 */
export function successUrl(planId) {
  const plan = getPlan(planId);
  const amount = plan ? (plan.priceCents / 100).toFixed(2) : '';
  return `${window.location.origin}/subscription-success?plan=${planId}&amount=${amount}`;
}

export default {
  PREMIUM_PLANS,
  getPlan,
  createPremiumMembershipIntent,
  successUrl,
};
