// src/hooks/useJamPlayer.js
//
// One sketch engine shared across a list of track cards. Handles
// play/stop toggling, progress ticks, and engine disposal on unmount.

import { useEffect, useRef, useState } from 'react';

import { createSketchEngine } from '../services/sketchEngine';
import { countPlay } from '../services/jamService';

export function useJamPlayer() {
  const engineRef = useRef(null);
  const [playingId, setPlayingId] = useState(null);
  const [progress, setProgress] = useState(0);

  useEffect(() => () => {
    if (engineRef.current) {
      engineRef.current.dispose();
      engineRef.current = null;
    }
  }, []);

  const ensureEngine = async () => {
    if (engineRef.current) return engineRef.current;
    const eng = await createSketchEngine();
    eng.setOnTick(({ pct, ended }) => {
      setProgress(pct);
      if (ended) setPlayingId(null);
    });
    engineRef.current = eng;
    return eng;
  };

  const toggle = async (jam) => {
    const eng = await ensureEngine();
    if (playingId === jam.id) {
      eng.stop();
      setPlayingId(null);
      return;
    }
    eng.loadLayers(jam.layers || [], jam.theory);
    await eng.playLayers();
    setPlayingId(jam.id);
    setProgress(0);
    countPlay(jam.id);
  };

  const stop = () => {
    if (engineRef.current) engineRef.current.stop();
    setPlayingId(null);
  };

  return { playingId, progress, toggle, stop };
}

export default useJamPlayer;
