// src/services/livekit/liveKitTokenClient.js
//
// Thin client-side helper that requests a LiveKit access token from the
// `generateLiveKitToken` Cloud Function. All JWT signing happens server-side,
// so the LiveKit API secret never ships to the browser.
//
// Both LiveKitService and LiveKitTokenService route through this helper, and it
// returns the same shape the old client-side signer did:
//   { token, serverUrl, roomName, participantName, expiresAt, grants }

import { httpsCallable } from 'firebase/functions';
import { functions } from '../../firebase';

export async function requestLiveKitToken(roomName, participantName, options = {}) {
  const callable = httpsCallable(functions, 'generateLiveKitToken');
  const result = await callable({ roomName, participantName, options });
  const data = result?.data;

  if (!data || !data.token) {
    throw new Error('Token service returned no token');
  }

  return data;
}

export default requestLiveKitToken;
