import { getDatabase, ref, push, set, get, update, onValue, query, orderByChild } from 'firebase/database';
import { getAuth } from 'firebase/auth';

class CategoryService {
  constructor() {
    this.database = getDatabase();
    this.auth = getAuth();
    this.categoriesPath = 'categories';
  }

  /**
   * Get current user ID
   */
  getCurrentUserId() {
    return this.auth.currentUser?.uid;
  }

  /**
   * Create a new category
   */
  async createCategory({ name, description, iconName = 'category', colorHex = '#6B46C1', sortOrder = 0 }) {
    try {
      const userId = this.getCurrentUserId();
      if (!userId) {
        throw new Error('No authenticated user');
      }

      console.log('📁 Creating category:', name);

      const now = Date.now();
      const categoryData = {
        name,
        description,
        iconName,
        colorHex,
        sortOrder,
        isActive: true,
        topicCount: 0,
        followerCount: 0,
        createdAt: now,
        updatedAt: now,
      };

      const categoryRef = push(ref(this.database, this.categoriesPath));
      await set(categoryRef, categoryData);

      console.log('✅ Category created with ID:', categoryRef.key);
      return categoryRef.key;
    } catch (error) {
      console.error('❌ Failed to create category:', error);
      throw error;
    }
  }

  /**
   * Get a category by ID
   */
  async getCategory(categoryId) {
    try {
      console.log('🔍 Loading category:', categoryId);

      const categoryRef = ref(this.database, `${this.categoriesPath}/${categoryId}`);
      const snapshot = await get(categoryRef);

      if (!snapshot.exists()) {
        console.log('🚫 Category not found:', categoryId);
        return null;
      }

      const data = snapshot.val();
      return {
        id: categoryId,
        ...data,
      };
    } catch (error) {
      console.error('❌ Failed to load category:', error);
      throw error;
    }
  }

  /**
   * Stream all categories (real-time)
   */
  streamAllCategories(callback) {
    const categoriesRef = query(
      ref(this.database, this.categoriesPath),
      orderByChild('sortOrder')
    );

    const unsubscribe = onValue(categoriesRef, (snapshot) => {
      const categories = [];

      if (snapshot.exists()) {
        const data = snapshot.val();

        Object.entries(data).forEach(([key, value]) => {
          // Only include active categories
          if (value.isActive) {
            categories.push({
              id: key,
              ...value,
            });
          }
        });

        // Sort by sortOrder
        categories.sort((a, b) => a.sortOrder - b.sortOrder);
      }

      callback(categories);
    });

    return unsubscribe;
  }

  /**
   * Get all categories (one-time fetch)
   */
  async getAllCategories() {
    try {
      console.log('🔍 Loading all categories');

      const categoriesRef = query(
        ref(this.database, this.categoriesPath),
        orderByChild('sortOrder')
      );
      const snapshot = await get(categoriesRef);

      const categories = [];

      if (snapshot.exists()) {
        const data = snapshot.val();

        Object.entries(data).forEach(([key, value]) => {
          // Only include active categories
          if (value.isActive) {
            categories.push({
              id: key,
              ...value,
            });
          }
        });

        categories.sort((a, b) => a.sortOrder - b.sortOrder);
      }

      return categories;
    } catch (error) {
      console.error('❌ Failed to load categories:', error);
      return [];
    }
  }

  /**
   * Update a category
   */
  async updateCategory(categoryId, updates) {
    try {
      const userId = this.getCurrentUserId();
      if (!userId) {
        throw new Error('No authenticated user');
      }

      console.log('📝 Updating category:', categoryId);

      updates.updatedAt = Date.now();

      const categoryRef = ref(this.database, `${this.categoriesPath}/${categoryId}`);
      await update(categoryRef, updates);

      console.log('✅ Category updated');
      return true;
    } catch (error) {
      console.error('❌ Failed to update category:', error);
      throw error;
    }
  }

  /**
   * Delete/deactivate a category
   */
  async deleteCategory(categoryId) {
    try {
      const userId = this.getCurrentUserId();
      if (!userId) {
        throw new Error('No authenticated user');
      }

      console.log('🗑️ Deactivating category:', categoryId);

      const categoryRef = ref(this.database, `${this.categoriesPath}/${categoryId}`);
      await update(categoryRef, {
        isActive: false,
        updatedAt: Date.now(),
      });

      console.log('✅ Category deactivated');
      return true;
    } catch (error) {
      console.error('❌ Failed to deactivate category:', error);
      throw error;
    }
  }

  /**
   * Increment topic count
   */
  async incrementTopicCount(categoryId) {
    try {
      const category = await this.getCategory(categoryId);
      if (!category) return;

      await this.updateCategory(categoryId, {
        topicCount: (category.topicCount || 0) + 1,
      });
    } catch (error) {
      console.error('❌ Failed to increment topic count:', error);
    }
  }

  /**
   * Decrement topic count
   */
  async decrementTopicCount(categoryId) {
    try {
      const category = await this.getCategory(categoryId);
      if (!category) return;

      const newCount = Math.max(0, (category.topicCount || 0) - 1);
      await this.updateCategory(categoryId, {
        topicCount: newCount,
      });
    } catch (error) {
      console.error('❌ Failed to decrement topic count:', error);
    }
  }

  /**
   * Increment follower count
   */
  async incrementFollowerCount(categoryId) {
    try {
      const category = await this.getCategory(categoryId);
      if (!category) return;

      await this.updateCategory(categoryId, {
        followerCount: (category.followerCount || 0) + 1,
      });
    } catch (error) {
      console.error('❌ Failed to increment follower count:', error);
    }
  }

  /**
   * Decrement follower count
   */
  async decrementFollowerCount(categoryId) {
    try {
      const category = await this.getCategory(categoryId);
      if (!category) return;

      const newCount = Math.max(0, (category.followerCount || 0) - 1);
      await this.updateCategory(categoryId, {
        followerCount: newCount,
      });
    } catch (error) {
      console.error('❌ Failed to decrement follower count:', error);
    }
  }
}

export default new CategoryService();
