// src/admin/StreamManager.jsx
import React, { useState, useEffect, useRef } from 'react';
import { getFirestore, doc, getDoc, updateDoc, setDoc } from 'firebase/firestore';
import { getStorage, ref, uploadBytesResumable, getDownloadURL } from 'firebase/storage';
import { 
  Video, 
  Play, 
  Square, 
  Upload, 
  Save, 
  Link as LinkIcon,
  Edit,
  AlertTriangle,
  Check,
  Monitor,
  Settings as SettingsIcon
} from 'lucide-react';
import ActiveStreamsDisplay from './components/ActiveStreamsDisplay';

const StreamManager = () => {
  const [activeTab, setActiveTab] = useState('active'); // 'active' or 'settings'
  const [streamData, setStreamData] = useState({
    isLive: false,
    title: '',
    description: '',
    streamUrl: '',
    thumbnailUrl: '',
    startedAt: null,
    endedAt: null,
    streamType: 'rtmp', // 'rtmp', 'hls', 'youtube', 'custom'
    viewerCount: 0
  });
  
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef(null);
  
  // Fetch current stream data
  useEffect(() => {
    const fetchStreamData = async () => {
      setLoading(true);
      setError(null);
      
      try {
        const db = getFirestore();
        const streamRef = doc(db, 'streams', 'currentStream');
        const streamDoc = await getDoc(streamRef);
        
        if (streamDoc.exists()) {
          setStreamData(streamDoc.data());
        }
      } catch (err) {
        console.error('Error fetching stream data:', err);
        setError('Failed to load stream data');
      } finally {
        setLoading(false);
      }
    };
    
    fetchStreamData();
  }, []);
  
  // Handle input change
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setStreamData(prev => ({
      ...prev,
      [name]: value
    }));
  };
  
  // Handle checkbox change
  const handleCheckboxChange = (e) => {
    const { name, checked } = e.target;
    setStreamData(prev => ({
      ...prev,
      [name]: checked
    }));
  };
  
  // Toggle stream state
  const toggleStreamState = async () => {
    setSaving(true);
    setError(null);
    setSuccess(null);
    
    try {
      const db = getFirestore();
      const streamRef = doc(db, 'streams', 'currentStream');
      
      const newIsLive = !streamData.isLive;
      const updateData = {
        isLive: newIsLive,
        startedAt: newIsLive && !streamData.startedAt ? new Date() : streamData.startedAt,
        endedAt: !newIsLive ? new Date() : null
      };
      
      await updateDoc(streamRef, updateData);
      
      setStreamData(prev => ({
        ...prev,
        ...updateData
      }));
      
      setSuccess(`Stream ${newIsLive ? 'started' : 'stopped'} successfully`);
      
      // Hide success message after 3 seconds
      setTimeout(() => {
        setSuccess(null);
      }, 3000);
    } catch (err) {
      console.error('Error toggling stream state:', err);
      setError(`Failed to ${streamData.isLive ? 'stop' : 'start'} stream`);
    } finally {
      setSaving(false);
    }
  };
  
  // Save stream settings
  const saveStreamSettings = async () => {
    setSaving(true);
    setError(null);
    setSuccess(null);
    
    try {
      const db = getFirestore();
      const streamRef = doc(db, 'streams', 'currentStream');
      
      await setDoc(streamRef, streamData, { merge: true });
      
      setSuccess('Stream settings saved successfully');
      
      // Hide success message after 3 seconds
      setTimeout(() => {
        setSuccess(null);
      }, 3000);
    } catch (err) {
      console.error('Error saving stream settings:', err);
      setError('Failed to save stream settings');
    } finally {
      setSaving(false);
    }
  };
  
  // Handle thumbnail upload
  const handleThumbnailUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    
    setIsUploading(true);
    setUploadProgress(0);
    setError(null);
    
    const storage = getStorage();
    const storageRef = ref(storage, `stream-thumbnails/${file.name}`);
    const uploadTask = uploadBytesResumable(storageRef, file);
    
    uploadTask.on('state_changed',
      (snapshot) => {
        // Progress tracking
        const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
        setUploadProgress(progress);
      },
      (error) => {
        // Error handling
        console.error('Error uploading thumbnail:', error);
        setError('Failed to upload thumbnail');
        setIsUploading(false);
      },
      () => {
        // Upload complete
        getDownloadURL(uploadTask.snapshot.ref).then((downloadURL) => {
          setStreamData(prev => ({
            ...prev,
            thumbnailUrl: downloadURL
          }));
          setIsUploading(false);
          setSuccess('Thumbnail uploaded successfully');
          
          // Hide success message after 3 seconds
          setTimeout(() => {
            setSuccess(null);
          }, 3000);
        });
      }
    );
  };
  
  return (
    <div className="stream-manager">
      <h2 className="text-2xl font-bold mb-6 flex items-center">
        <Video className="mr-2" size={24} />
        Stream Manager
      </h2>
      
      {/* Tab Navigation */}
      <div className="bg-white rounded-lg border border-gray-200 mb-6">
        <div className="flex border-b border-gray-200">
          <button
            onClick={() => setActiveTab('active')}
            className={`px-6 py-3 font-medium flex items-center ${
              activeTab === 'active'
                ? 'bg-blue-50 text-blue-600 border-b-2 border-blue-600'
                : 'text-gray-600 hover:bg-gray-50'
            }`}
          >
            <Monitor className="mr-2" size={18} />
            Active Streams
          </button>
          <button
            onClick={() => setActiveTab('settings')}
            className={`px-6 py-3 font-medium flex items-center ${
              activeTab === 'settings'
                ? 'bg-blue-50 text-blue-600 border-b-2 border-blue-600'
                : 'text-gray-600 hover:bg-gray-50'
            }`}
          >
            <SettingsIcon className="mr-2" size={18} />
            Stream Settings
          </button>
        </div>
        
        <div className="p-6">
          {activeTab === 'active' && (
            <ActiveStreamsDisplay />
          )}
          
          {activeTab === 'settings' && (
            <StreamSettingsPanel
              streamData={streamData}
              loading={loading}
              saving={saving}
              error={error}
              success={success}
              uploadProgress={uploadProgress}
              isUploading={isUploading}
              fileInputRef={fileInputRef}
              onInputChange={handleInputChange}
              onCheckboxChange={handleCheckboxChange}
              onToggleStream={toggleStreamState}
              onSaveSettings={saveStreamSettings}
              onThumbnailUpload={handleThumbnailUpload}
            />
          )}
        </div>
      </div>
    </div>
  );
};

// Stream Settings Panel Component
const StreamSettingsPanel = ({
  streamData,
  loading,
  saving,
  error,
  success,
  uploadProgress,
  isUploading,
  fileInputRef,
  onInputChange,
  onCheckboxChange,
  onToggleStream,
  onSaveSettings,
  onThumbnailUpload
}) => {
  return (
    <div className="stream-settings-panel">
      <div className="bg-white rounded-lg overflow-hidden border border-gray-200">
        {/* Stream Status Header */}
        <div className={`p-4 flex justify-between items-center ${streamData.isLive ? 'bg-red-100' : 'bg-gray-100'}`}>
          <div className="flex items-center">
            <div className={`w-3 h-3 rounded-full mr-2 ${streamData.isLive ? 'bg-red-600 animate-pulse' : 'bg-gray-400'}`}></div>
            <span className="font-medium">
              {streamData.isLive ? 'LIVE' : 'OFFLINE'}
            </span>
          </div>
          
          <button
            onClick={toggleStreamState}
            disabled={saving}
            className={`flex items-center px-4 py-2 rounded-md font-medium ${
              streamData.isLive
                ? 'bg-gray-800 text-white hover:bg-gray-900'
                : 'bg-red-600 text-white hover:bg-red-700'
            } ${saving ? 'opacity-70 cursor-not-allowed' : ''}`}
          >
            {streamData.isLive ? (
              <>
                <Square size={16} className="mr-2" />
                {saving ? 'Stopping...' : 'End Stream'}
              </>
            ) : (
              <>
                <Play size={16} className="mr-2" />
                {saving ? 'Starting...' : 'Go Live'}
              </>
            )}
          </button>
        </div>
        
        {/* Status Messages */}
        {error && (
          <div className="flex items-center p-4 bg-red-50 border-l-4 border-red-500 text-red-700 mb-4">
            <AlertTriangle className="mr-2" size={20} />
            <span>{error}</span>
          </div>
        )}
        
        {success && (
          <div className="flex items-center p-4 bg-green-50 border-l-4 border-green-500 text-green-700 mb-4">
            <Check className="mr-2" size={20} />
            <span>{success}</span>
          </div>
        )}
        
        {/* Stream Configuration Form */}
        <div className="p-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <h3 className="text-lg font-medium mb-4">Stream Settings</h3>
              
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium mb-1">
                    Stream Title
                  </label>
                  <input
                    type="text"
                    name="title"
                    value={streamData.title}
                    onChange={handleInputChange}
                    className="w-full p-2 border border-gray-300 rounded-md"
                    placeholder="Enter stream title"
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-1">
                    Stream Description
                  </label>
                  <textarea
                    name="description"
                    value={streamData.description}
                    onChange={handleInputChange}
                    className="w-full p-2 border border-gray-300 rounded-md"
                    placeholder="Enter stream description"
                    rows={3}
                  ></textarea>
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-1">
                    Stream Type
                  </label>
                  <select
                    name="streamType"
                    value={streamData.streamType}
                    onChange={handleInputChange}
                    className="w-full p-2 border border-gray-300 rounded-md"
                  >
                    <option value="rtmp">RTMP Server</option>
                    <option value="hls">HLS Stream</option>
                    <option value="youtube">YouTube Embed</option>
                    <option value="custom">Custom URL</option>
                  </select>
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-1">
                    Stream URL
                  </label>
                  <div className="flex">
                    <input
                      type="text"
                      name="streamUrl"
                      value={streamData.streamUrl}
                      onChange={handleInputChange}
                      className="flex-1 p-2 border border-gray-300 rounded-l-md"
                      placeholder="Enter stream URL"
                    />
                    <button
                      className="bg-indigo-600 text-white p-2 rounded-r-md hover:bg-indigo-700"
                      title="Open Stream URL"
                      onClick={() => streamData.streamUrl && window.open(streamData.streamUrl, '_blank')}
                    >
                      <LinkIcon size={18} />
                    </button>
                  </div>
                </div>
              </div>
            </div>
            
            <div>
              <h3 className="text-lg font-medium mb-4">Thumbnail</h3>
              
              <div className="space-y-4">
                <div>
                  <div className="w-full h-48 bg-gray-100 rounded-md border border-gray-200 flex items-center justify-center overflow-hidden">
                    {streamData.thumbnailUrl ? (
                      <img
                        src={streamData.thumbnailUrl}
                        alt="Stream Thumbnail"
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <div className="text-gray-400 flex flex-col items-center">
                        <Video size={48} />
                        <span className="mt-2">No thumbnail uploaded</span>
                      </div>
                    )}
                  </div>
                </div>
                
                <div>
                  <input
                    type="file"
                    ref={fileInputRef}
                    onChange={handleThumbnailUpload}
                    accept="image/*"
                    className="hidden"
                  />
                  
                  <button
                    onClick={() => fileInputRef.current.click()}
                    disabled={isUploading}
                    className={`flex items-center px-4 py-2 rounded-md font-medium bg-gray-100 text-gray-700 hover:bg-gray-200 w-full justify-center ${isUploading ? 'opacity-70 cursor-not-allowed' : ''}`}
                  >
                    <Upload size={16} className="mr-2" />
                    {isUploading ? `Uploading (${Math.round(uploadProgress)}%)` : 'Upload Thumbnail'}
                  </button>
                </div>
                
                {isUploading && (
                  <div className="w-full bg-gray-200 rounded-full h-2.5">
                    <div
                      className="bg-indigo-600 h-2.5 rounded-full"
                      style={{ width: `${uploadProgress}%` }}
                    ></div>
                  </div>
                )}
              </div>
              
              {streamData.isLive && (
                <div className="mt-8">
                  <h3 className="text-lg font-medium mb-4">Stream Statistics</h3>
                  
                  <div className="grid grid-cols-2 gap-4">
                    <div className="bg-gray-50 p-4 rounded-md border border-gray-200">
                      <div className="text-sm text-gray-500 mb-1">Viewers</div>
                      <div className="text-2xl font-bold">{streamData.viewerCount || 0}</div>
                    </div>
                    
                    <div className="bg-gray-50 p-4 rounded-md border border-gray-200">
                      <div className="text-sm text-gray-500 mb-1">Duration</div>
                      <div className="text-2xl font-bold">
                        {streamData.startedAt ? (
                          formatDuration(new Date() - streamData.startedAt.toDate())
                        ) : (
                          '0:00:00'
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
          
          <div className="mt-8 pt-4 border-t border-gray-200 flex justify-end">
            <button
              onClick={saveStreamSettings}
              disabled={saving}
              className={`flex items-center px-6 py-2 rounded-md font-medium bg-indigo-600 text-white hover:bg-indigo-700 ${saving ? 'opacity-70 cursor-not-allowed' : ''}`}
            >
              <Save size={16} className="mr-2" />
              {saving ? 'Saving...' : 'Save Settings'}
            </button>
          </div>
        </div>
      </div>
      
      {/* Stream Setup Guide */}
      <div className="mt-8 bg-gray-50 rounded-lg p-6 border border-gray-200">
        <h3 className="text-lg font-medium mb-4 flex items-center">
          <Edit size={18} className="mr-2" />
          Streaming Guide
        </h3>
        
        <div className="prose max-w-none">
          <p>
            Configure your streaming software with the following settings to go live:
          </p>
          
          <div className="mt-4 bg-gray-100 p-4 rounded-md">
            <div className="mb-2">
              <span className="font-medium">RTMP URL:</span>
              <code className="ml-2 bg-gray-200 px-2 py-1 rounded text-sm">rtmp://streaming.talkstudio.com/live</code>
            </div>
            <div>
              <span className="font-medium">Stream Key:</span>
              <code className="ml-2 bg-gray-200 px-2 py-1 rounded text-sm">sk_live_******</code>
              <button className="ml-2 text-indigo-600 text-sm hover:text-indigo-700">
                Show Key
              </button>
            </div>
          </div>
          
          <p className="mt-4">
            For assistance with streaming setup, please consult our documentation or contact support.
          </p>
        </div>
      </div>
    </div>
  );
};

// Helper function to format duration
function formatDuration(milliseconds) {
  const totalSeconds = Math.floor(milliseconds / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  
  return `${hours}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
}

export default StreamManager;