// FBI Crime Data Explorer (CDE) client.
//
// Endpoint base: https://api.usa.gov/crime/fbi/cde
// Requires an api.data.gov key (free): https://api.data.gov/signup/
// CORS: api.data.gov ships CORS headers, so direct browser calls work.
//
// The CDE summarized national endpoints we hit:
//   /summarized/national/violent-crime/{fromYear}/{toYear}
//   /summarized/national/property-crime/{fromYear}/{toYear}
//
// Response shape (abridged):
//   { "offenses": { "actuals": { "2021": 1234567, "2022": 1200000, ... } } }
//
// We pull a 5-year window ending two years back (data trails ~18 months)
// and compute: latest year value, YoY delta vs prior year, as a rate per
// 100k using the matching US population from the same payload when present.
// Falls back to raw counts if population isn't returned.

import apiKeyService from '../apiKeyService'
import { corsFetch } from '../../utils/corsFetch'

const CDE_BASE = 'https://api.usa.gov/crime/fbi/cde'

const OFFENSES = [
  {
    slug: 'violent-crime',
    tag: 'safety.violent_crime.national',
    label: 'US Violent Crime (rate/100k)',
    id: 'fbi.violent_crime.national',
    sentimentHint: 'negative',
  },
  {
    slug: 'property-crime',
    tag: 'safety.property_crime.national',
    label: 'US Property Crime (rate/100k)',
    id: 'fbi.property_crime.national',
    sentimentHint: 'negative',
  },
]

function yearWindow() {
  const now = new Date().getFullYear()
  // FBI CDE lags ~18 months, so end the window 2 years behind current year
  const end = now - 2
  const start = end - 4
  return { start, end }
}

function classifyTrend(delta) {
  if (delta === null || Number.isNaN(delta)) return 'stable'
  // For crime rates, lower-is-better — but we emit 'up'/'down' as literal
  // numeric direction and let sentimentHint drive coloring.
  if (delta > 0.5) return 'up'
  if (delta < -0.5) return 'down'
  return 'stable'
}

function extractLatestTwo(actuals) {
  const years = Object.keys(actuals || {}).map(Number).filter(Number.isFinite).sort((a, b) => a - b)
  if (years.length === 0) return null
  const latestYear = years[years.length - 1]
  const prevYear = years.length >= 2 ? years[years.length - 2] : null
  return {
    latestYear,
    latestVal: Number(actuals[String(latestYear)]),
    prevYear,
    prevVal: prevYear !== null ? Number(actuals[String(prevYear)]) : null,
  }
}

function ratePer100k(count, population) {
  if (!population || !Number.isFinite(count) || !Number.isFinite(population)) return null
  return +(count / population * 100000).toFixed(1)
}

async function fetchOne(offense, key) {
  const { start, end } = yearWindow()
  const url = `${CDE_BASE}/summarized/national/${offense.slug}/${start}/${end}?API_KEY=${encodeURIComponent(key)}`
  const res = await corsFetch(url, { method: 'GET', parse: 'json', timeout: 12000 })
  if (!res.ok) return { offense, error: res.error || 'FBI fetch failed' }
  return { offense, data: res.data }
}

function buildSignal(offense, payload) {
  const actuals = payload?.offenses?.actuals
  const populations = payload?.populations?.actuals || payload?.actuals?.population || null
  const pair = extractLatestTwo(actuals)
  if (!pair) return null

  const asOf = new Date().toISOString()
  let value = pair.latestVal
  let unit = 'incidents'

  // Prefer rate/100k when population data is available
  if (populations) {
    const latestPop = Number(populations[String(pair.latestYear)])
    const prevPop = pair.prevYear !== null ? Number(populations[String(pair.prevYear)]) : null
    const latestRate = ratePer100k(pair.latestVal, latestPop)
    const prevRate = prevPop !== null ? ratePer100k(pair.prevVal, prevPop) : null
    if (latestRate !== null) {
      value = latestRate
      unit = 'per 100k'
      const delta = prevRate !== null ? +(latestRate - prevRate).toFixed(1) : null
      return {
        id: offense.id,
        tag: offense.tag,
        category: 'safety',
        label: offense.label,
        value,
        unit,
        trend: classifyTrend(delta),
        delta,
        deltaLabel: 'YoY change',
        period: String(pair.latestYear),
        asOf,
        source: `FBI CDE (${offense.slug})`,
        sourceUrl: 'https://cde.ucr.cjis.gov/',
        reliability: 0.93,
        sentimentHint: offense.sentimentHint,
      }
    }
  }

  // Fallback: raw counts with % change
  const pctDelta = pair.prevVal ? +(((pair.latestVal - pair.prevVal) / pair.prevVal) * 100).toFixed(1) : null
  return {
    id: offense.id,
    tag: offense.tag,
    category: 'safety',
    label: offense.label.replace('(rate/100k)', '(incidents)'),
    value,
    unit,
    trend: classifyTrend(pctDelta),
    delta: pctDelta,
    deltaLabel: pctDelta !== null ? 'YoY % change' : null,
    period: String(pair.latestYear),
    asOf,
    source: `FBI CDE (${offense.slug})`,
    sourceUrl: 'https://cde.ucr.cjis.gov/',
    reliability: 0.90,
    sentimentHint: offense.sentimentHint,
  }
}

const fbiCrimeService = {
  async fetchAll() {
    const key = apiKeyService.getFbiApiKey()
    if (!key) {
      return { signals: [], error: 'FBI Crime needs an api.data.gov key (see API Settings)' }
    }
    const results = await Promise.all(OFFENSES.map(o => fetchOne(o, key)))
    const errors = results.filter(r => r.error).map(r => `${r.offense.slug}: ${r.error}`)
    const signals = []
    for (const r of results) {
      if (r.error || !r.data) continue
      const sig = buildSignal(r.offense, r.data)
      if (sig) signals.push(sig)
    }
    return {
      signals,
      error: errors.length ? errors.join('; ') : null,
    }
  },
}

export default fbiCrimeService
