import { ArrowUpRight, ArrowDownRight, Minus, ExternalLink } from 'lucide-react'

// Format a signal value for display. Keeps one decimal for fractional
// values, integer otherwise. Big counts get comma separators.
function formatValue(value, unit) {
  if (value === null || value === undefined) return '—'
  if (typeof value !== 'number') return String(value)
  if (unit === 'events' || unit === 'count') {
    return value.toLocaleString('en-US')
  }
  if (Number.isInteger(value)) return value.toLocaleString('en-US')
  return value.toFixed(value < 10 ? 2 : 1)
}

function formatDelta(delta, unit) {
  if (delta === null || delta === undefined || delta === 0) return null
  const sign = delta > 0 ? '+' : ''
  if (unit === 'events' || unit === 'count') return `${sign}${delta}`
  return `${sign}${Math.abs(delta) < 10 ? delta.toFixed(2) : delta.toFixed(1)}`
}

function formatAsOf(period) {
  if (!period) return ''
  // Period can be a year ('2025'), year-quarter ('2026-Q1'), year-month
  // ('2026-03'), or an ISO date. Keep it short.
  if (/^\d{4}$/.test(period)) return period
  if (/^\d{4}-Q[1-4]$/.test(period)) return period
  if (/^\d{4}-\d{2}$/.test(period)) {
    const [y, m] = period.split('-')
    const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
    return `${months[parseInt(m, 10) - 1]} ${y}`
  }
  // Assume ISO date
  try {
    return new Date(period).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
  } catch {
    return period
  }
}

// Render a single context signal tile. Deliberately muted — this is
// reference data, not live/sentiment input, so we avoid the green/red
// confidence coloring the rest of the app uses.
export default function SignalCard({ signal }) {
  if (!signal) return null

  const TrendIcon = signal.trend === 'up' ? ArrowUpRight
    : signal.trend === 'down' ? ArrowDownRight
    : Minus

  // Trend color is neutral by default. If the signal author set a
  // sentimentHint we can tint the delta to match reader intuition.
  let trendColor = 'text-gray-500'
  if (signal.sentimentHint === 'positive') {
    trendColor = signal.trend === 'up' ? 'text-emerald-400'
      : signal.trend === 'down' ? 'text-red-400'
      : 'text-gray-500'
  } else if (signal.sentimentHint === 'negative') {
    trendColor = signal.trend === 'up' ? 'text-red-400'
      : signal.trend === 'down' ? 'text-emerald-400'
      : 'text-gray-500'
  }

  const deltaText = formatDelta(signal.delta, signal.unit)

  return (
    <div className="bg-gray-950/60 border border-gray-800 rounded-lg p-3 hover:border-gray-700 transition-colors">
      <div className="flex items-start justify-between gap-2 mb-2">
        <p className="text-[11px] uppercase tracking-wide text-gray-500 font-medium leading-tight">
          {signal.label}
        </p>
        <TrendIcon size={14} className={`${trendColor} shrink-0`} />
      </div>

      <div className="flex items-baseline gap-1.5 mb-1">
        <span className="font-mono text-xl font-bold text-gray-100 tabular-nums">
          {formatValue(signal.value, signal.unit)}
        </span>
        {signal.unit && signal.unit !== 'events' && signal.unit !== 'count' && (
          <span className="text-xs text-gray-500 font-mono">{signal.unit}</span>
        )}
      </div>

      <div className="flex items-center justify-between text-[10px] text-gray-600 font-mono">
        <span>
          {deltaText && (
            <span className={trendColor}>{deltaText}</span>
          )}
          {signal.deltaLabel && (
            <span className="ml-1">{signal.deltaLabel}</span>
          )}
        </span>
        <span>{formatAsOf(signal.period)}</span>
      </div>

      {signal.sourceUrl ? (
        <a
          href={signal.sourceUrl}
          target="_blank"
          rel="noopener noreferrer"
          className="mt-2 inline-flex items-center gap-1 text-[10px] text-gray-600 hover:text-gray-400 transition-colors"
        >
          {signal.source}
          <ExternalLink size={9} />
        </a>
      ) : (
        <p className="mt-2 text-[10px] text-gray-600">{signal.source}</p>
      )}
    </div>
  )
}
