// src/components/dev/ProfileInitializer.jsx
import React, { useState } from 'react';
import { initializeProfiles } from '../../scripts/initialize-profiles';
import './ProfileInitializer.css';

const ProfileInitializer = () => {
  const [isInitializing, setIsInitializing] = useState(false);
  const [results, setResults] = useState(null);
  const [error, setError] = useState(null);

  const handleInitializeProfiles = async () => {
    if (isInitializing) return;

    try {
      setIsInitializing(true);
      setError(null);
      setResults(null);

      // Start the initialization process
      const initResults = await initializeProfiles();
      setResults(initResults);
    } catch (err) {
      console.error('Failed to initialize profiles:', err);
      setError(err.message || 'Failed to initialize profiles');
    } finally {
      setIsInitializing(false);
    }
  };

  return (
    <div className="profile-initializer">
      <h1>Profile Database Initializer</h1>
      <p className="description">
        This tool creates profile entries in the profiles collection for all existing users.
        It should be run once after adding the profiles feature to ensure all users have profiles.
      </p>

      <div className="warning-box">
        <h3>⚠️ Warning</h3>
        <p>
          This operation will scan your users collection and create corresponding profile documents
          for any user that doesn't already have one. This operation is safe to run multiple times,
          as it will not override existing profiles.
        </p>
      </div>

      <div className="action-container">
        <button 
          className={`init-button ${isInitializing ? 'disabled' : ''}`}
          onClick={handleInitializeProfiles}
          disabled={isInitializing}
        >
          {isInitializing ? 'Initializing Profiles...' : 'Initialize Profiles'}
        </button>
      </div>

      {isInitializing && (
        <div className="loading-container">
          <div className="spinner"></div>
          <p>Creating profile entries, please wait...</p>
        </div>
      )}

      {error && (
        <div className="error-container">
          <h3>Error</h3>
          <p>{error}</p>
        </div>
      )}

      {results && (
        <div className="results-container">
          <h3>Initialization Results</h3>
          <div className="results-grid">
            <div className="result-item">
              <div className="result-label">Created Profiles:</div>
              <div className="result-value">{results.created}</div>
            </div>
            <div className="result-item">
              <div className="result-label">Existing Profiles:</div>
              <div className="result-value">{results.existing}</div>
            </div>
            <div className="result-item">
              <div className="result-label">Errors:</div>
              <div className="result-value">{results.errors}</div>
            </div>
            <div className="result-item">
              <div className="result-label">Total Users Processed:</div>
              <div className="result-value">{results.total}</div>
            </div>
          </div>
          <div className="completion-message">
            {results.errors === 0 
              ? 'Profile initialization completed successfully!'
              : `Profile initialization completed with ${results.errors} errors. Check the console for details.`
            }
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfileInitializer;