// src/contexts/PostsContext.jsx
import React, { createContext, useContext, useEffect, useState, useRef, useCallback, useMemo } from 'react';
import { doc, onSnapshot } from 'firebase/firestore';
import { db } from '../firebase';

const PostsContext = createContext();

export const usePostsContext = () => {
  const context = useContext(PostsContext);
  if (!context) {
    throw new Error('usePostsContext must be used within PostsProvider');
  }
  return context;
};

export const PostsProvider = ({ children }) => {
  const [postsData, setPostsData] = useState({});
  const listenersRef = useRef({});

  // Subscribe to a post's updates - memoized to prevent re-renders
  const subscribeToPost = useCallback((postId) => {
    // If already subscribed, don't create another listener
    if (listenersRef.current[postId]) {
      return;
    }

    console.log(`📡 Creating listener for post: ${postId}`);

    const postRef = doc(db, 'posts', postId);
    const unsubscribe = onSnapshot(postRef, (doc) => {
      if (doc.exists()) {
        const data = doc.data();
        setPostsData(prev => ({
          ...prev,
          [postId]: {
            likes: Array.isArray(data.likes) ? data.likes : [],
            commentsCount: data.commentsCount || 0,
            lastUpdated: Date.now()
          }
        }));
      }
    });

    listenersRef.current[postId] = unsubscribe;
  }, []);

  // Unsubscribe from a post's updates - memoized to prevent re-renders
  const unsubscribeFromPost = useCallback((postId) => {
    if (listenersRef.current[postId]) {
      console.log(`🔌 Removing listener for post: ${postId}`);
      listenersRef.current[postId]();
      delete listenersRef.current[postId];

      // Clean up data after a delay to allow for re-mounting
      setTimeout(() => {
        setPostsData(prev => {
          const newData = { ...prev };
          delete newData[postId];
          return newData;
        });
      }, 5000);
    }
  }, []);

  // Get post data - memoized to prevent re-renders
  const getPostData = useCallback((postId) => {
    return postsData[postId] || { likes: [], commentsCount: 0 };
  }, [postsData]);

  // Clean up all listeners on unmount
  useEffect(() => {
    return () => {
      console.log('🧹 Cleaning up all post listeners');
      Object.values(listenersRef.current).forEach(unsubscribe => {
        if (typeof unsubscribe === 'function') {
          unsubscribe();
        }
      });
    };
  }, []);

  // Memoize the context value to prevent unnecessary re-renders
  const value = useMemo(() => ({
    subscribeToPost,
    unsubscribeFromPost,
    getPostData,
    activeListeners: Object.keys(listenersRef.current).length
  }), [subscribeToPost, unsubscribeFromPost, getPostData]);

  return (
    <PostsContext.Provider value={value}>
      {children}
    </PostsContext.Provider>
  );
};