// src/utils/patchStorage.js
import { 
  ref as originalRef, 
  getDownloadURL as originalGetDownloadURL,
  listAll as originalListAll,
  uploadBytes as originalUploadBytes,
  uploadString as originalUploadString,
  deleteObject as originalDeleteObject
} from 'firebase/storage';

/**
 * A utility to patch Firebase Storage functions to bypass CORS issues
 */

// Proxy URL - Updated to use our enhanced proxy server
const PROXY_URL = 'http://localhost:3002/firebase-storage-proxy';
const FIREBASE_BUCKET = 'talkstudio-fb.appspot.com';

// Create a flag to track if we've already patched
let isPatched = false;

// Create custom wrapper functions that will replace the originals
let patchedRef = originalRef;
let patchedGetDownloadURL = originalGetDownloadURL;
let patchedListAll = originalListAll;
let patchedUploadBytes = originalUploadBytes;
let patchedUploadString = originalUploadString;
let patchedDeleteObject = originalDeleteObject;

/**
 * Patch the Firebase Storage functions to use a proxy
 */
export const patchFirebaseStorage = () => {
  // Only patch once
  if (isPatched) {
    console.log('Firebase Storage already patched');
    return;
  }
  
  console.log('Patching Firebase Storage to use enhanced proxy...');
  
  try {
    // Create patched ref function
    patchedRef = (storage, path) => {
      console.log('Creating proxied ref for:', path);
      const originalResult = originalRef(storage, path);
      
      // Add a flag to identify our proxied refs
      return {
        ...originalResult,
        _isProxied: true,
        _originalPath: path
      };
    };
    
    // Create patched getDownloadURL function
    patchedGetDownloadURL = async (ref) => {
      // Only proxy if this is one of our proxied refs
      if (ref && ref._isProxied) {
        const path = ref._originalPath || ref.fullPath;
        console.log('Getting proxied download URL for:', path);
        
        // Create proxied URL
        const encodedPath = encodeURIComponent(path);
        const url = `${PROXY_URL}/v0/b/${FIREBASE_BUCKET}/o/${encodedPath}?alt=media`;
        
        console.log('Proxied URL:', url);
        return url;
      }
      
      // Fall back to original implementation
      return originalGetDownloadURL(ref);
    };
    
    // Create patched listAll function
    patchedListAll = async (ref) => {
      // Only proxy if this is one of our proxied refs
      if (ref && ref._isProxied) {
        const path = ref._originalPath || ref.fullPath || '';
        console.log('Listing files via proxy for:', path);
        
        try {
          // Create proxied URL
          const encodedPath = encodeURIComponent(path);
          const url = `${PROXY_URL}/v0/b/${FIREBASE_BUCKET}/o?prefix=${encodedPath}&delimiter=/`;
          
          console.log('Proxied listAll URL:', url);
          
          // Make the request
          const response = await fetch(url);
          
          if (!response.ok) {
            throw new Error(`Proxy request failed: ${response.status}`);
          }
          
          const data = await response.json();
          
          // Transform the response to match the format Firebase expects
          return {
            items: (data.items || []).map(item => {
              // Create a ref-like object for each item
              const itemRef = originalRef(ref.storage, item.name);
              
              // Add our proxy flags
              itemRef._isProxied = true;
              itemRef._originalPath = item.name;
              
              return itemRef;
            }),
            prefixes: (data.prefixes || []).map(prefix => {
              // Create a ref-like object for each prefix
              const prefixRef = originalRef(ref.storage, prefix);
              
              // Add our proxy flags
              prefixRef._isProxied = true;
              prefixRef._originalPath = prefix;
              
              return prefixRef;
            })
          };
        } catch (error) {
          console.error('Error in proxied listAll:', error);
          console.log('Falling back to original implementation');
          return originalListAll(ref);
        }
      }
      
      // Fall back to original implementation
      return originalListAll(ref);
    };
    
    // Create patched uploadBytes function
    patchedUploadBytes = async (ref, data, metadata) => {
      if (ref && ref._isProxied) {
        const path = ref._originalPath || ref.fullPath;
        console.log('Uploading bytes via proxy for:', path);
        
        try {
          // Create proxied URL for upload
          const url = `${PROXY_URL}/v0/b/${FIREBASE_BUCKET}/o?name=${encodeURIComponent(path)}`;
          
          // Determine content type from metadata or data
          let contentType = 'application/octet-stream';
          if (metadata && metadata.contentType) {
            contentType = metadata.contentType;
          }
          
          console.log('Proxied upload URL:', url);
          console.log('Content-Type:', contentType);
          
          // Upload via proxy
          const response = await fetch(url, {
            method: 'POST',
            headers: {
              'Content-Type': contentType
            },
            body: data
          });
          
          if (!response.ok) {
            throw new Error(`Proxy upload failed: ${response.status}`);
          }
          
          const responseData = await response.json();
          console.log('Upload response:', responseData);
          
          // Create a mock upload result
          return {
            ref: ref,
            metadata: {
              ...metadata,
              ...responseData,
              name: path,
              fullPath: path
            }
          };
        } catch (error) {
          console.error('Error in proxied upload:', error);
          console.log('Falling back to original implementation');
          return originalUploadBytes(ref, data, metadata);
        }
      }
      
      // Fall back to original implementation
      return originalUploadBytes(ref, data, metadata);
    };
    
    // Create patched uploadString function
    patchedUploadString = async (ref, data, format, metadata) => {
      if (ref && ref._isProxied) {
        const path = ref._originalPath || ref.fullPath;
        console.log('Uploading string via proxy for:', path);
        
        try {
          // Convert string to proper format if needed
          let processedData = data;
          let contentType = 'text/plain';
          
          if (format === 'data_url') {
            // Extract content type and data from data URL
            const matches = data.match(/^data:([^;]+);base64,(.*)$/);
            if (matches && matches.length >= 3) {
              contentType = matches[1] || 'application/octet-stream';
              processedData = Buffer.from(matches[2], 'base64');
            }
          } else if (format === 'base64') {
            processedData = Buffer.from(data, 'base64');
            contentType = 'application/octet-stream';
          }
          
          // Use the uploadBytes implementation
          return patchedUploadBytes(ref, processedData, {
            ...metadata,
            contentType
          });
        } catch (error) {
          console.error('Error in proxied string upload:', error);
          console.log('Falling back to original implementation');
          return originalUploadString(ref, data, format, metadata);
        }
      }
      
      // Fall back to original implementation
      return originalUploadString(ref, data, format, metadata);
    };
    
    // Create patched deleteObject function
    patchedDeleteObject = async (ref) => {
      if (ref && ref._isProxied) {
        const path = ref._originalPath || ref.fullPath;
        console.log('Deleting object via proxy for:', path);
        
        try {
          // Create proxied URL for deletion
          const url = `${PROXY_URL}/v0/b/${FIREBASE_BUCKET}/o/${encodeURIComponent(path)}`;
          
          console.log('Proxied delete URL:', url);
          
          // Delete via proxy
          const response = await fetch(url, {
            method: 'DELETE'
          });
          
          if (!response.ok) {
            throw new Error(`Proxy delete failed: ${response.status}`);
          }
          
          console.log('Delete successful');
          return;
        } catch (error) {
          console.error('Error in proxied delete:', error);
          console.log('Falling back to original implementation');
          return originalDeleteObject(ref);
        }
      }
      
      // Fall back to original implementation
      return originalDeleteObject(ref);
    };
    
    isPatched = true;
    console.log('Firebase Storage successfully patched to use enhanced proxy');
  } catch (error) {
    console.error('Error patching Firebase Storage:', error);
    
    // Restore original functions in case of error
    patchedRef = originalRef;
    patchedGetDownloadURL = originalGetDownloadURL;
    patchedListAll = originalListAll;
    patchedUploadBytes = originalUploadBytes;
    patchedUploadString = originalUploadString;
    patchedDeleteObject = originalDeleteObject;
  }
};

/**
 * Export the patched functions for use throughout the app
 */
export const ref = (...args) => patchedRef(...args);
export const getDownloadURL = (...args) => patchedGetDownloadURL(...args);
export const listAll = (...args) => patchedListAll(...args);
export const uploadBytes = (...args) => patchedUploadBytes(...args);
export const uploadString = (...args) => patchedUploadString(...args);
export const deleteObject = (...args) => patchedDeleteObject(...args);

/**
 * Check if the proxy server is running
 * @returns {Promise<boolean>} True if the proxy is running
 */
export const isProxyRunning = async () => {
  try {
    // Update to use our enhanced proxy server
    const response = await fetch('http://localhost:3002/health');
    const running = response.ok;
    console.log('Enhanced proxy server running:', running);
    return running;
  } catch (error) {
    console.error('Enhanced proxy server check failed:', error);
    return false;
  }
};

/**
 * Unpatch Firebase Storage (restore original functions)
 */
export const unpatchFirebaseStorage = () => {
  if (!isPatched) {
    return;
  }
  
  patchedRef = originalRef;
  patchedGetDownloadURL = originalGetDownloadURL;
  patchedListAll = originalListAll;
  patchedUploadBytes = originalUploadBytes;
  patchedUploadString = originalUploadString;
  patchedDeleteObject = originalDeleteObject;
  
  isPatched = false;
  console.log('Firebase Storage restored to original implementation');
};
