// LiveKit Service - Fixed token generation with better error handling
// Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\services\livekit\LiveKitService.js

import liveKitTokenService from './LiveKitTokenService.js';
import LiveKitConfig from './LiveKitConfig.js';
import { requestLiveKitToken } from './liveKitTokenClient.js';

// livekit-client v2 renamed a couple of collections that this service reads:
//   Room.participants        -> Room.remoteParticipants
//   Participant.tracks       -> Participant.trackPublications
// Reading the old names on a v2 Room yields `undefined`, so calling .forEach /
// .size on them threw "Cannot read properties of undefined (reading 'forEach')"
// right after a *successful* connect — which connect() then reported back as a
// failed connection. These helpers read whichever name the installed client
// exposes and always hand back a Map-like value.
const EMPTY_MAP = new Map();

const getRemoteParticipants = (room) =>
  room?.remoteParticipants || room?.participants || EMPTY_MAP;

const getTrackPublications = (participant) =>
  participant?.trackPublications || participant?.tracks || EMPTY_MAP;

// Total participants in the room, including the local one.
const getParticipantCount = (room) =>
  getRemoteParticipants(room).size + (room?.localParticipant ? 1 : 0);

class LiveKitService {
  constructor() {
    this.isConnected = false;
    this.currentRoom = null;
    this.connectionAttempts = 0;
    this.maxRetries = 3;
    this.localParticipant = null;
    this.remoteParticipants = new Map();
    // Support multiple users streaming simultaneously
    this.rooms = new Map(); // roomName -> Room instance
    this.roomParticipants = new Map(); // roomName -> participant identity
  }

  // Generate access token with enhanced error handling
  async generateAccessToken(roomName, participantName, options = {}) {
    try {
      this.connectionAttempts++;

      console.log(`🔑 Requesting LiveKit token from server (attempt ${this.connectionAttempts}):`, {
        roomName,
        participantName,
        options
      });

      // Token is minted server-side by the `generateLiveKitToken` Cloud
      // Function — the LiveKit API secret never reaches the browser.
      const tokenData = await requestLiveKitToken(
        roomName,
        participantName,
        options
      );
      
      if (!tokenData || !tokenData.token) {
        throw new Error('Token generation returned null or invalid data');
      }
      
      // Validate token format
      if (typeof tokenData.token !== 'string' || !tokenData.token.includes('.')) {
        throw new Error('Generated token is not a valid JWT format');
      }
      
      console.log('✅ LiveKit token generated successfully:', {
        roomName: tokenData.roomName,
        participantName: tokenData.participantName,
        tokenLength: tokenData.token.length,
        expiresAt: new Date(tokenData.expiresAt).toISOString()
      });
      
      // Reset attempt counter on success
      this.connectionAttempts = 0;
      
      return tokenData;
      
    } catch (error) {
      console.error(`❌ LiveKit token generation failed (attempt ${this.connectionAttempts}):`, error);
      
      // Retry transient failures (network blips, cold-started function) up to
      // the max. Server-side config problems surface as a clear function error
      // after the retries are exhausted.
      if (this.connectionAttempts < this.maxRetries) {
        console.log(`🔄 Retrying token request in 1 second... (${this.connectionAttempts}/${this.maxRetries})`);

        await new Promise(resolve => setTimeout(resolve, 1000));
        return this.generateAccessToken(roomName, participantName, options);
      }
      
      // Reset attempts and throw the error
      this.connectionAttempts = 0;
      throw new Error(`Failed to generate access token: ${error.message}`);
    }
  }

  // Get configuration status for debugging
  getConfigStatus() {
    return liveKitTokenService.getConfigStatus();
  }

  // Connect to LiveKit room
  async connect(roomName, participantName, options = {}) {
    try {
      console.log('🔌 Connecting to LiveKit room:', { roomName, participantName });
      
      // Generate access token first
      const tokenData = await this.generateAccessToken(roomName, participantName, options);
      if (!tokenData || !tokenData.token) {
        throw new Error('Failed to generate access token');
      }
      
      // Dynamically import LiveKit client to avoid errors if not installed
      let Room;
      try {
        const liveKitClient = await import('livekit-client');
        Room = liveKitClient.Room;
      } catch (importError) {
        console.error('❌ LiveKit client not installed:', importError);
        throw new Error('LiveKit client library not available. Please install livekit-client package.');
      }
      
      // Check if already connected to this room
      if (this.rooms.has(roomName)) {
        console.log('⚠️ Already connected to room:', roomName);
        const existingRoom = this.rooms.get(roomName);
        return {
          success: true,
          room: existingRoom,
          participantCount: getParticipantCount(existingRoom),
          connectionTime: 0,
          roomName: tokenData.roomName,
          participantName: tokenData.participantName,
          alreadyConnected: true
        };
      }

      // Create room instance
      const room = new Room(options.roomOptions || {});

      // Server URL: prefer the one the token function returned, fall back to
      // the public client config (VITE_LIVEKIT_SERVER_URL).
      const config = LiveKitConfig.getCurrentConfig();
      const serverUrl = tokenData.serverUrl || config.serverUrl;
      if (!serverUrl) {
        throw new Error('LiveKit server URL not configured');
      }

      // Connect to the room
      const startTime = Date.now();
      await room.connect(serverUrl, tokenData.token, {
        autoSubscribe: options.autoSubscribe !== false,
        ...options.connectOptions
      });

      // Store room and participant info
      this.rooms.set(roomName, room);
      this.roomParticipants.set(roomName, participantName);

      // Set as current room for backward compatibility
      this.currentRoom = room;
      this.isConnected = true;
      this.localParticipant = room.localParticipant;
      
      // Track participants. This is bookkeeping only — never let it fail an
      // otherwise-successful connection.
      try {
        getRemoteParticipants(this.currentRoom).forEach((participant) => {
          this.remoteParticipants.set(participant.sid, participant);
        });
      } catch (bookkeepingError) {
        console.warn('⚠️ Could not snapshot remote participants:', bookkeepingError);
      }
      
      // Set up event listeners
      this.setupRoomEventListeners();
      
      const connectionTime = Date.now() - startTime;
      console.log('✅ Connected to LiveKit room successfully in', connectionTime, 'ms');
      
      return {
        success: true,
        room: this.currentRoom,
        participantCount: getParticipantCount(this.currentRoom),
        connectionTime,
        roomName: tokenData.roomName,
        participantName: tokenData.participantName,
        serverUrl
      };
      
    } catch (error) {
      console.error('❌ Failed to connect to LiveKit room:', error);
      this.isConnected = false;
      this.currentRoom = null;
      
      return {
        success: false,
        error: error.message,
        details: error
      };
    }
  }
  
  // Set up room event listeners
  setupRoomEventListeners() {
    if (!this.currentRoom) return;
    
    this.currentRoom.on('participantConnected', (participant) => {
      console.log('👤 Participant connected:', participant.identity);
      this.remoteParticipants.set(participant.sid, participant);
    });
    
    this.currentRoom.on('participantDisconnected', (participant) => {
      console.log('👤 Participant disconnected:', participant.identity);
      this.remoteParticipants.delete(participant.sid);
    });
    
    this.currentRoom.on('disconnected', () => {
      console.log('🔌 Disconnected from room');
      this.isConnected = false;
      this.remoteParticipants.clear();
    });
    
    this.currentRoom.on('reconnecting', () => {
      console.log('🔄 Reconnecting to room...');
    });
    
    this.currentRoom.on('reconnected', () => {
      console.log('✅ Reconnected to room');
      this.isConnected = true;
    });
  }
  
  // Start video track
  async startVideo(options = {}) {
    if (!this.currentRoom || !this.isConnected) {
      throw new Error('Not connected to a room');
    }
    
    try {
      await this.currentRoom.localParticipant.setCameraEnabled(true, options);
      console.log('📹 Video started');
      return { success: true };
    } catch (error) {
      console.error('❌ Failed to start video:', error);
      throw error;
    }
  }
  
  // Start audio track
  async startAudio(options = {}) {
    if (!this.currentRoom || !this.isConnected) {
      throw new Error('Not connected to a room');
    }
    
    try {
      await this.currentRoom.localParticipant.setMicrophoneEnabled(true, options);
      console.log('🎤 Audio started');
      return { success: true };
    } catch (error) {
      console.error('❌ Failed to start audio:', error);
      throw error;
    }
  }
  
  // Test token generation
  async testTokenGeneration() {
    try {
      const testRoom = `test-room-${Date.now()}`;
      const testParticipant = 'Test User';
      
      const tokenData = await this.generateAccessToken(testRoom, testParticipant, {
        canPublish: false,
        canSubscribe: true
      });
      
      return {
        success: true,
        tokenData,
        message: 'Token generation test passed'
      };
      
    } catch (error) {
      return {
        success: false,
        error: error.message,
        configStatus: this.getConfigStatus()
      };
    }
  }

  // Disconnect from LiveKit room (optionally specify roomName)
  async disconnect(roomName = null) {
    try {
      if (roomName) {
        // Disconnect from specific room
        const room = this.rooms.get(roomName);
        if (room) {
          await room.disconnect();
          this.rooms.delete(roomName);
          this.roomParticipants.delete(roomName);
          console.log(`✅ Disconnected from room: ${roomName}`);
        }

        // Update current room if it was the one we disconnected
        if (this.currentRoom === room) {
          // Set currentRoom to any remaining room, or null
          this.currentRoom = this.rooms.size > 0 ? this.rooms.values().next().value : null;
        }
      } else {
        // Disconnect from all rooms
        for (const [name, room] of this.rooms.entries()) {
          await room.disconnect();
          console.log(`✅ Disconnected from room: ${name}`);
        }
        this.rooms.clear();
        this.roomParticipants.clear();
        this.currentRoom = null;
      }

      this.isConnected = this.rooms.size > 0;
      this.localParticipant = this.currentRoom?.localParticipant || null;

      if (!this.isConnected) {
        this.remoteParticipants.clear();
      }

      console.log('✅ LiveKit service disconnect complete');
      return { success: true };
    } catch (error) {
      console.error('❌ Error during disconnect:', error);
      return { success: false, error: error.message };
    }
  }

  // Get room stats
  getRoomStats() {
    if (!this.currentRoom || !this.isConnected) {
      return {
        isConnected: false,
        connectionState: 'disconnected',
        participantCount: 0,
        publishedTracks: 0,
        subscribedTracks: 0
      };
    }
    
    const localTracks = getTrackPublications(this.currentRoom.localParticipant);
    let publishedTracks = 0;
    let subscribedTracks = 0;
    
    // Count published tracks. v2's LocalTrackPublication has no `isPublished`
    // flag — a local publication with a track attached *is* a published track.
    localTracks.forEach(publication => {
      if (publication.track) publishedTracks++;
    });
    
    // Count subscribed tracks
    getRemoteParticipants(this.currentRoom).forEach(participant => {
      getTrackPublications(participant).forEach(track => {
        if (track.isSubscribed) subscribedTracks++;
      });
    });
    
    return {
      isConnected: this.isConnected,
      connectionState: this.currentRoom.state || 'unknown',
      participantCount: getParticipantCount(this.currentRoom), // includes the local participant
      publishedTracks,
      subscribedTracks,
      roomName: this.currentRoom.name,
      localParticipant: this.localParticipant?.identity
    };
  }

  // Event system placeholders
  on(event, callback) {
    // Placeholder for event system
  }

  off(event, callback) {
    // Placeholder for event system
  }
}

// Export singleton instance
export const liveKitService = new LiveKitService();
export default liveKitService;

// Make available globally for debugging
if (typeof window !== 'undefined') {
  window.liveKitService = liveKitService;
  window.testLiveKitTokens = () => liveKitService.testTokenGeneration();
}
