// src/predict/components/common/MyMarketsSelector.jsx
//
// Chip editor for the user's selected markets.
// - Collapsed by default: shows selected markets + "Edit markets" button.
// - Expanded: shows the full catalog grouped by region, tap to toggle.
// - Persists to localStorage via utils/markets.js.

import { useEffect, useMemo, useState } from 'react';
import { MapPin, Plus, X, Check } from 'lucide-react';
import {
  MARKET_CATALOG,
  getMarket,
  getUserMarkets,
  marketsByRegion,
  setUserMarkets,
} from '../../utils/markets';

export default function MyMarketsSelector({ onChange }) {
  const [selected, setSelected] = useState(() => getUserMarkets());
  const [editing, setEditing] = useState(false);

  // Sync across tabs / external updates
  useEffect(() => {
    const sync = () => setSelected(getUserMarkets());
    window.addEventListener('predict:user-markets-changed', sync);
    window.addEventListener('storage', sync);
    return () => {
      window.removeEventListener('predict:user-markets-changed', sync);
      window.removeEventListener('storage', sync);
    };
  }, []);

  const regionGroups = useMemo(() => marketsByRegion(), []);

  const toggle = (id) => {
    const next = selected.includes(id)
      ? selected.filter(x => x !== id)
      : [...selected, id];
    setSelected(next);
    setUserMarkets(next);
    onChange?.(next);
  };

  const clearAll = () => {
    setSelected([]);
    setUserMarkets([]);
    onChange?.([]);
  };

  // ---- Collapsed summary row ----
  if (!editing) {
    return (
      <div className="flex items-center gap-2 flex-wrap p-3 rounded-lg bg-gray-900/60 border border-gray-800">
        <MapPin size={16} className="text-blue-400 shrink-0" />
        <span className="text-xs uppercase tracking-wider text-gray-500 mr-1">My scenes</span>

        {selected.length === 0 ? (
          <span className="text-sm text-gray-400">
            All scenes shown — <button
              className="text-blue-400 hover:text-blue-300 underline"
              onClick={() => setEditing(true)}
            >pick your scenes</button> to personalize.
          </span>
        ) : (
          <>
            {selected.map(id => {
              const m = getMarket(id);
              if (!m) return null;
              return (
                <span
                  key={id}
                  className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-blue-500/15 text-blue-300 border border-blue-500/25"
                >
                  {m.label}
                </span>
              );
            })}
            <button
              onClick={() => setEditing(true)}
              className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-gray-800 text-gray-300 hover:bg-gray-700 border border-gray-700 ml-1"
            >
              <Plus size={12} /> Edit
            </button>
          </>
        )}
      </div>
    );
  }

  // ---- Expanded editor ----
  return (
    <div className="p-4 rounded-lg bg-gray-900/80 border border-gray-800">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <MapPin size={16} className="text-blue-400" />
          <h3 className="text-sm font-semibold text-gray-200">Pick your scenes</h3>
          <span className="text-xs text-gray-500">
            ({selected.length} selected)
          </span>
        </div>
        <div className="flex items-center gap-2">
          {selected.length > 0 && (
            <button
              onClick={clearAll}
              className="text-xs text-gray-400 hover:text-gray-200"
            >
              Clear all
            </button>
          )}
          <button
            onClick={() => setEditing(false)}
            className="inline-flex items-center gap-1 px-2 py-1 rounded text-xs font-medium bg-blue-500 hover:bg-blue-400 text-white"
          >
            <Check size={12} /> Done
          </button>
        </div>
      </div>

      <p className="text-xs text-gray-500 mb-3">
        Predictions from the scenes you pick will surface first. Only
        global/industry predictions appear regardless, since they affect
        everyone.
      </p>

      <div className="space-y-3 max-h-80 overflow-y-auto pr-1">
        {Object.entries(regionGroups).map(([region, markets]) => (
          <div key={region}>
            <div className="text-[10px] uppercase tracking-wider text-gray-500 mb-1.5">
              {region}
            </div>
            <div className="flex flex-wrap gap-1.5">
              {markets.map(m => {
                const on = selected.includes(m.id);
                return (
                  <button
                    key={m.id}
                    onClick={() => toggle(m.id)}
                    className={
                      'inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium border transition-colors ' +
                      (on
                        ? 'bg-blue-500/20 text-blue-300 border-blue-500/40'
                        : 'bg-gray-800 text-gray-300 border-gray-700 hover:bg-gray-700')
                    }
                  >
                    {on && <Check size={11} />}
                    {m.label}
                    {on && <X size={10} className="opacity-70" />}
                  </button>
                );
              })}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
