// src/predict/components/common/LiveIndicator.jsx
//
// Shows Firebase RTDB connection state — the true "live" source for
// dealmaker predictions (votes + new submissions sync across users).
//
// Legacy news/RSS scanning was built for current-events predictions
// (politics, sports). Public CORS proxies are flaky and the data isn't
// dealmaker-relevant. We've kept the underlying scan infrastructure
// intact (apiKeyService / inputPipeline / newsService / rssService /
// aiService) so a Pass 2 admin can re-enable it for AI Elite features —
// but it's hidden from the default dashboard chrome.
//
// Pass 2 will replace this with a richer indicator covering:
//   - RTDB connection (here today)
//   - Census / BLS / EDGAR data freshness
//   - AI analysis pipeline status

import { useEffect, useState } from 'react'
import { Loader2, Radio, WifiOff } from 'lucide-react'
import { ref, onValue } from 'firebase/database'
import { rtdb } from '../../../firebase'

export default function LiveIndicator({ scanning, lastScan, onScan }) {
  // Subscribe to Firebase's built-in `.info/connected` flag — fires whenever
  // the RTDB websocket goes up or down. Non-Firebase users (e.g. local-only
  // demo) just see "offline" which is honest.
  const [connected, setConnected] = useState(false)
  useEffect(() => {
    if (!rtdb || typeof rtdb.app === 'undefined') return
    try {
      const connRef = ref(rtdb, '.info/connected')
      const unsub = onValue(connRef, (snap) => setConnected(snap.val() === true))
      return () => unsub()
    } catch {
      // RTDB not initialized — leave connected=false
    }
  }, [])

  return (
    <div className="flex items-center gap-3">
      {scanning ? (
        <span className="flex items-center gap-1.5 text-xs text-blue-400">
          <Loader2 size={12} className="animate-spin" />
          Refreshing…
        </span>
      ) : connected ? (
        <span className="flex items-center gap-1.5 text-xs text-emerald-400">
          <span className="relative flex h-2 w-2">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75" />
            <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500" />
          </span>
          Live · synced
        </span>
      ) : (
        <span className="flex items-center gap-1.5 text-xs text-gray-500">
          <WifiOff size={12} />
          Offline
        </span>
      )}

      {lastScan && (
        <span className="text-[10px] text-gray-600">
          Last refresh: {new Date(lastScan).toLocaleTimeString()}
        </span>
      )}

      <button
        onClick={onScan}
        disabled={scanning}
        className="px-2 py-1 text-[10px] font-medium bg-blue-500/10 text-blue-400 border border-blue-500/20 rounded hover:bg-blue-500/20 transition-colors disabled:opacity-50 inline-flex items-center gap-1"
        title="Re-pull predictions and run scan"
      >
        <Radio size={10} />
        {scanning ? 'Refreshing…' : 'Refresh'}
      </button>
    </div>
  )
}
