import React, { useEffect } from 'react';

const StreamingIframe = () => {
  useEffect(() => {
    // Hide main page body content when iframe is active
    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    
    // Cleanup when component unmounts
    return () => {
      document.body.style.overflow = originalOverflow;
    };
  }, []);

  return (
    <div style={{ 
      position: 'fixed',
      top: 0,
      left: 0,
      width: '100vw', 
      height: '100vh', 
      background: '#0f0f23',
      margin: 0,
      padding: 0,
      overflow: 'hidden',
      zIndex: 1000
    }}>
      <iframe
        src="/streaming-iframe.html"
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          border: 'none',
          margin: 0,
          padding: 0
        }}
        title="Artist Streaming Studio"
        allow="camera; microphone; display-capture"
      />
    </div>
  );
};

export default StreamingIframe;