// src/utils/streamPermissions.js
// Who is allowed to BROADCAST into an event.
//
// This is deliberately separate from src/utils/eventAccessTypes.js, which
// answers a different question: who is allowed to WATCH an event (free /
// registration / premium / VIP). An event has both: a viewing access level and
// a streaming permission.
//
// The rule: broadcasting into someone else's event is the creator's call, not
// a default. An event with no explicit setting is creator-only.

export const STREAM_PERMISSION_TYPES = {
  CREATOR_ONLY: 'creator_only', // Default — only the event creator broadcasts
  INVITED: 'invited',           // Creator + the uids listed in allowedStreamers
  ANYONE: 'anyone'              // Any signed-in (non-anonymous) user may broadcast
};

export const DEFAULT_STREAM_PERMISSION = STREAM_PERMISSION_TYPES.CREATOR_ONLY;

export const STREAM_PERMISSION_DESCRIPTIONS = {
  [STREAM_PERMISSION_TYPES.CREATOR_ONLY]: {
    label: 'Only me',
    short: 'Host only',
    description: 'You are the only one who can go live in this event.'
  },
  [STREAM_PERMISSION_TYPES.INVITED]: {
    label: 'Me and invited guests',
    short: 'Invite only',
    description: 'You and the guests you invite can go live. Everyone else watches.'
  },
  [STREAM_PERMISSION_TYPES.ANYONE]: {
    label: 'Anyone who joins',
    short: 'Open stage',
    description: 'Any signed-in viewer can start broadcasting into this event.'
  }
};

/**
 * The uid that owns an event. Events have been written with a few different
 * owner fields over the life of the platform, so check them in order.
 * @param {Object} event
 * @returns {string|null}
 */
export const getEventCreatorId = (event) =>
  event?.artistId || event?.creatorId || event?.createdBy || event?.hostId || null;

/**
 * Read an event's streaming permission, normalising legacy data.
 * @param {Object} event
 * @returns {string} one of STREAM_PERMISSION_TYPES
 */
export const getEventStreamPermission = (event) => {
  const explicit = event?.streamPermission;
  if (explicit && STREAM_PERMISSION_DESCRIPTIONS[explicit]) {
    return explicit;
  }

  // Legacy: the LiveKit room used to carry an `allowRegisteredToStream` flag.
  // Honour it when it was explicitly turned on, so existing open events keep
  // working; anything else falls back to creator-only.
  if (event?.allowRegisteredToStream === true) {
    return STREAM_PERMISSION_TYPES.ANYONE;
  }

  // An event with an explicit guest list is invite-only even if the mode field
  // never got written.
  if (Array.isArray(event?.allowedStreamers) && event.allowedStreamers.length > 0) {
    return STREAM_PERMISSION_TYPES.INVITED;
  }

  return DEFAULT_STREAM_PERMISSION;
};

/**
 * @param {Object|null} user - Firebase user (needs .uid)
 * @param {Object} event
 * @returns {boolean}
 */
export const isEventCreator = (user, event) => {
  const creatorId = getEventCreatorId(event);
  return !!(user?.uid && creatorId && user.uid === creatorId);
};

/**
 * @param {Object|null} user
 * @param {Object} event
 * @returns {boolean} true if the user is on the event's guest-streamer list
 */
export const isInvitedStreamer = (user, event) =>
  !!(user?.uid && Array.isArray(event?.allowedStreamers) && event.allowedStreamers.includes(user.uid));

/**
 * Can this user broadcast into this event?
 *
 * @param {Object|null} user - Firebase user object, or null when signed out
 * @param {Object|null} event - Event document (must include its owner field)
 * @param {Object} [options]
 * @param {boolean} [options.isAdmin] - platform admin override
 * @returns {{canStream: boolean, role: 'creator'|'guest'|'open'|'admin'|'viewer',
 *            permission: string, reason: string, message: string}}
 */
export const checkStreamPermission = (user, event, options = {}) => {
  const permission = getEventStreamPermission(event);
  const base = { canStream: false, role: 'viewer', permission };

  if (!event) {
    return { ...base, reason: 'event_missing', message: 'Event not found.' };
  }

  if (!user || user.isAnonymous) {
    return {
      ...base,
      reason: 'sign_in_required',
      message: 'Sign in to broadcast into an event.'
    };
  }

  if (isEventCreator(user, event)) {
    return {
      ...base,
      canStream: true,
      role: 'creator',
      reason: 'creator',
      message: 'You created this event.'
    };
  }

  if (options.isAdmin === true) {
    return {
      ...base,
      canStream: true,
      role: 'admin',
      reason: 'admin_override',
      message: 'Admin override.'
    };
  }

  if (permission === STREAM_PERMISSION_TYPES.ANYONE) {
    return {
      ...base,
      canStream: true,
      role: 'open',
      reason: 'open_stage',
      message: 'The host opened this event to anyone.'
    };
  }

  if (permission === STREAM_PERMISSION_TYPES.INVITED && isInvitedStreamer(user, event)) {
    return {
      ...base,
      canStream: true,
      role: 'guest',
      reason: 'invited',
      message: 'The host invited you to stream.'
    };
  }

  return {
    ...base,
    reason: 'not_permitted',
    message: 'Only the host can stream to this event. Ask them for an invite.'
  };
};

/**
 * Convenience wrapper for call sites that only need the boolean.
 */
export const canUserStreamToEvent = (user, event, options = {}) =>
  checkStreamPermission(user, event, options).canStream;

/**
 * Short label for a badge, e.g. "Host" / "Guest streamer" / "Viewer".
 */
export const getStreamRoleLabel = (role) => {
  switch (role) {
    case 'creator': return 'Host';
    case 'admin': return 'Admin';
    case 'guest': return 'Guest streamer';
    case 'open': return 'Open stage';
    default: return 'Viewer';
  }
};

/**
 * The event fields that describe streaming permission. Used when persisting a
 * host's choice so every writer stays consistent.
 * @param {string} permission - one of STREAM_PERMISSION_TYPES
 * @param {string[]} [allowedStreamers]
 */
export const buildStreamPermissionUpdate = (permission, allowedStreamers = null) => {
  const safePermission = STREAM_PERMISSION_DESCRIPTIONS[permission]
    ? permission
    : DEFAULT_STREAM_PERMISSION;

  const update = {
    streamPermission: safePermission,
    // Keep the legacy flag in sync so older screens still reading it agree.
    allowRegisteredToStream: safePermission === STREAM_PERMISSION_TYPES.ANYONE
  };

  if (Array.isArray(allowedStreamers)) {
    update.allowedStreamers = allowedStreamers;
  }

  return update;
};
