import { Trophy, Medal, Award, TrendingUp } from 'lucide-react'
import { mockUsers } from '../utils/mockData'
import Card from '../components/common/Card'

const medals = ['text-yellow-400', 'text-gray-400', 'text-amber-600']

export default function Leaderboard() {
  const users = [...mockUsers].sort((a, b) => b.accuracy - a.accuracy)

  return (
    <div className="space-y-6 max-w-3xl">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Leaderboard</h1>
        <p className="text-sm text-gray-500 mt-1">Top predictors ranked by accuracy</p>
      </div>

      <div className="grid grid-cols-3 gap-3">
        {users.slice(0, 3).map((user, i) => (
          <Card key={user.id} className="p-4 text-center" hover={false}>
            <div className={`w-12 h-12 mx-auto rounded-full bg-gradient-to-br ${
              i === 0 ? 'from-yellow-500 to-amber-500' :
              i === 1 ? 'from-gray-400 to-gray-500' :
              'from-amber-600 to-amber-700'
            } flex items-center justify-center text-lg font-bold mb-2`}>
              {user.username.charAt(0)}
            </div>
            <Trophy size={16} className={`mx-auto mb-1 ${medals[i]}`} />
            <p className="font-semibold text-sm text-gray-200">{user.username}</p>
            <p className="font-mono text-xl font-bold text-emerald-400 mt-1">{user.accuracy}%</p>
            <p className="text-xs text-gray-500">{user.totalPredictions} predictions</p>
          </Card>
        ))}
      </div>

      <Card className="overflow-hidden" hover={false}>
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-gray-800 text-xs text-gray-500 uppercase tracking-wider">
              <th className="text-left py-3 px-4">Rank</th>
              <th className="text-left py-3 px-4">User</th>
              <th className="text-right py-3 px-4">Accuracy</th>
              <th className="text-right py-3 px-4 hidden sm:table-cell">Predictions</th>
              <th className="text-right py-3 px-4 hidden sm:table-cell">Streak</th>
            </tr>
          </thead>
          <tbody>
            {users.map((user, i) => (
              <tr key={user.id} className="border-b border-gray-800/50 hover:bg-gray-800/30 transition-colors">
                <td className="py-3 px-4 font-mono text-gray-400">#{i + 1}</td>
                <td className="py-3 px-4">
                  <div className="flex items-center gap-2">
                    <div className="w-7 h-7 rounded-full bg-gray-700 flex items-center justify-center text-xs font-bold">
                      {user.username.charAt(0)}
                    </div>
                    <span className="font-medium text-gray-200">{user.username}</span>
                  </div>
                </td>
                <td className="py-3 px-4 text-right">
                  <span className={`font-mono font-semibold ${
                    user.accuracy >= 70 ? 'text-emerald-400' :
                    user.accuracy >= 60 ? 'text-amber-400' :
                    'text-red-400'
                  }`}>{user.accuracy}%</span>
                </td>
                <td className="py-3 px-4 text-right font-mono text-gray-400 hidden sm:table-cell">{user.totalPredictions}</td>
                <td className="py-3 px-4 text-right hidden sm:table-cell">
                  <span className="inline-flex items-center gap-1 text-emerald-400 font-mono">
                    <TrendingUp size={12} /> {user.streak}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </Card>
    </div>
  )
}
