// src/components/debug/ChatPerformanceMonitor.jsx
import React, { useState, useEffect } from 'react';
import { startTiming, endTiming } from '../../utils/performance-monitor';
import { analyzeChatPerformance } from '../../utils/chat-performance';

/**
 * Component to monitor and display chat performance metrics in real-time
 * Only visible in development mode
 */
const ChatPerformanceMonitor = () => {
  // Don't render in production
  if (import.meta.env.PROD) {
    return null;
  }
  
  const [performanceData, setPerformanceData] = useState({
    metrics: {},
    averages: {
      initialization: 0,
      fetch: 0,
      write: 0
    },
    slowOperations: []
  });
  
  const [expanded, setExpanded] = useState(true);
  const [updateCounter, setUpdateCounter] = useState(0);
  const [showAllOperations, setShowAllOperations] = useState(false);
  
  // Update the performance data periodically
  useEffect(() => {
    const traceId = startTiming('monitorUpdate');
    
    const interval = setInterval(() => {
      const currentData = analyzeChatPerformance();
      setPerformanceData(currentData);
      setUpdateCounter(prev => prev + 1);
    }, 1000);
    
    return () => {
      clearInterval(interval);
      endTiming(traceId);
    };
  }, []);
  
  const toggleExpanded = () => {
    setExpanded(!expanded);
  };
  
  const toggleShowAllOperations = () => {
    setShowAllOperations(!showAllOperations);
  };
  
  // Check if there are any slow operations
  const hasSlow = performanceData.slowOperations.length > 0;
  
  // Style improvements for better readability
  const styles = {
    container: {
      position: 'fixed',
      bottom: '10px',
      right: '10px',
      width: expanded ? '400px' : '180px',
      maxHeight: expanded ? '500px' : '30px',
      backgroundColor: 'rgba(0, 0, 0, 0.85)',
      color: 'white',
      zIndex: 9998,
      borderRadius: '4px',
      overflow: 'hidden',
      transition: 'all 0.3s ease',
      boxShadow: '0 0 10px rgba(0,0,0,0.5)',
      fontFamily: 'system-ui, -apple-system, sans-serif',
      fontSize: '14px'
    },
    header: {
      padding: '8px 12px',
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      backgroundColor: hasSlow ? '#782222' : '#333',
      cursor: 'pointer',
      borderBottom: '1px solid rgba(255,255,255,0.1)'
    },
    content: {
      overflowY: 'auto',
      maxHeight: '470px',
      padding: '10px'
    },
    metric: {
      display: 'flex',
      justifyContent: 'space-between',
      padding: '5px 8px',
      marginBottom: '3px',
      backgroundColor: 'rgba(255,255,255,0.05)',
      borderRadius: '3px'
    },
    button: {
      background: 'none',
      border: '1px solid rgba(255,255,255,0.3)',
      color: 'white',
      padding: '4px 8px',
      marginRight: '5px',
      borderRadius: '3px',
      cursor: 'pointer',
      fontSize: '12px'
    },
    summaryItem: {
      padding: '8px',
      backgroundColor: 'rgba(255,255,255,0.08)',
      marginBottom: '8px',
      borderRadius: '3px'
    }
  };
  
  // Get color based on duration
  const getDurationColor = (duration) => {
    if (!duration) return '#9E9E9E';
    if (duration > 1000) return '#F44336';
    if (duration > 500) return '#FF9800';
    if (duration > 100) return '#FFEB3B';
    return '#4CAF50';
  };
  
  // Get emoji marker based on duration
  const getDurationMarker = (duration) => {
    if (!duration) return '⚪';
    if (duration > 1000) return '🔴';
    if (duration > 500) return '🟠';
    if (duration > 100) return '🟡';
    return '🟢';
  };
  
  return (
    <div style={styles.container}>
      <div style={styles.header} onClick={toggleExpanded}>
        <span>
          {hasSlow ? '🐢' : '⚡'} Chat Performance
          {hasSlow && ' (Slow operations detected)'}
        </span>
        <div>
          <span>{expanded ? '▼' : '▲'}</span>
        </div>
      </div>
      
      {expanded && (
        <div style={styles.content}>
          {/* Summary Section */}
          <div style={{ marginBottom: '15px' }}>
            <h4 style={{ margin: '0 0 10px 0', borderBottom: '1px solid rgba(255,255,255,0.2)', paddingBottom: '5px' }}>
              Performance Summary
            </h4>
            
            <div style={styles.summaryItem}>
              <div style={{ marginBottom: '5px', fontWeight: 'bold' }}>Initialization</div>
              <div style={{ 
                display: 'flex', 
                justifyContent: 'space-between',
                color: getDurationColor(performanceData.averages.initialization)
              }}>
                <span>Average Time:</span>
                <span>{performanceData.averages.initialization.toFixed(2)}ms</span>
              </div>
            </div>
            
            <div style={styles.summaryItem}>
              <div style={{ marginBottom: '5px', fontWeight: 'bold' }}>Firebase Operations</div>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '3px', color: getDurationColor(performanceData.averages.fetch) }}>
                <span>Fetch Operations:</span>
                <span>{performanceData.averages.fetch.toFixed(2)}ms</span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', color: getDurationColor(performanceData.averages.write) }}>
                <span>Write Operations:</span>
                <span>{performanceData.averages.write.toFixed(2)}ms</span>
              </div>
            </div>
          </div>
          
          {/* Slow Operations Section */}
          {performanceData.slowOperations.length > 0 && (
            <div style={{ marginBottom: '15px' }}>
              <h4 style={{ 
                margin: '0 0 10px 0', 
                borderBottom: '1px solid rgba(255,255,255,0.2)', 
                paddingBottom: '5px',
                color: '#F44336'
              }}>
                Slow Operations (&gt;1000ms)
              </h4>
              
              {performanceData.slowOperations.map((op, index) => (
                <div key={index} style={styles.metric}>
                  <div>{getDurationMarker(op.duration)} {op.operation}</div>
                  <div style={{ color: getDurationColor(op.duration) }}>
                    {op.duration.toFixed(2)}ms
                  </div>
                </div>
              ))}
            </div>
          )}
          
          {/* All Operations Toggle */}
          <div style={{ marginBottom: '10px' }}>
            <button 
              style={styles.button}
              onClick={toggleShowAllOperations}
            >
              {showAllOperations ? 'Hide Details' : 'Show All Operations'}
            </button>
          </div>
          
          {/* All Operations Section */}
          {showAllOperations && Object.keys(performanceData.metrics).length > 0 && (
            <div>
              <h4 style={{ margin: '0 0 10px 0', borderBottom: '1px solid rgba(255,255,255,0.2)', paddingBottom: '5px' }}>
                All Operations
              </h4>
              
              {Object.entries(performanceData.metrics)
                .sort((a, b) => (b[1].duration || 0) - (a[1].duration || 0))
                .map(([key, value], index) => (
                  <div key={index} style={styles.metric}>
                    <div>{getDurationMarker(value.duration)} {key}</div>
                    <div style={{ color: getDurationColor(value.duration) }}>
                      {value.duration ? `${value.duration.toFixed(2)}ms` : 'In progress...'}
                    </div>
                  </div>
                ))
              }
            </div>
          )}
          
          {/* Recommendations Section */}
          <div style={{ marginTop: '15px', padding: '10px', backgroundColor: 'rgba(0,0,0,0.2)', borderRadius: '3px' }}>
            <h4 style={{ margin: '0 0 8px 0', fontSize: '14px' }}>Recommendations</h4>
            
            {performanceData.slowOperations.length > 0 ? (
              <div>
                <p style={{ margin: '0 0 8px 0', fontSize: '13px' }}>
                  Detected slow operations in chat room. Consider:
                </p>
                <ul style={{ margin: '0', paddingLeft: '20px', fontSize: '12px' }}>
                  <li>Reducing listener count or setting stricter query limits</li>
                  <li>Using lazy loading for Firebase services</li>
                  <li>Implementing pagination for message history</li>
                  <li>Optimizing participant updates (less frequent)</li>
                </ul>
              </div>
            ) : (
              <p style={{ margin: '0', fontSize: '13px', color: '#4CAF50' }}>
                Performance is within acceptable limits. No slow operations detected.
              </p>
            )}
          </div>
          
          <div style={{ marginTop: '10px', fontSize: '11px', color: '#999', textAlign: 'right' }}>
            Updated: {new Date().toLocaleTimeString()} (#{updateCounter})
          </div>
        </div>
      )}
    </div>
  );
};

export default ChatPerformanceMonitor;