import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Mic, 
  MicOff,
  Search, 
  MessageCircle,
  Loader,
  Plus,
  Users,
  Radio,
  Check,
  X,
  ChevronRight,
  Volume2
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { db, rtdb } from '../../firebase';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  doc, 
  setDoc, 
  addDoc,
  serverTimestamp 
} from 'firebase/firestore';
import { 
  ref as rtdbRef, 
  push as rtdbPush, 
  set as rtdbSet 
} from 'firebase/database';
import './AudioMatcherImproved.css';
import { debugAudioMatchFirebase } from './debugAudioMatch.js';

const AudioMatcherImproved = () => {
  const [currentStep, setCurrentStep] = useState('idle');
  const [isListening, setIsListening] = useState(false);
  const [listeningTime, setListeningTime] = useState(0);
  const [audioFingerprint, setAudioFingerprint] = useState(null);
  const [matches, setMatches] = useState([]);
  const [error, setError] = useState(null);
  const [roomKeyword, setRoomKeyword] = useState('');
  const [roomName, setRoomName] = useState('');
  const [isCreatingRoom, setIsCreatingRoom] = useState(false);
  
  const mediaRecorderRef = useRef(null);
  const audioContextRef = useRef(null);
  const analyserRef = useRef(null);
  const streamRef = useRef(null);
  const timerRef = useRef(null);
  const canvasRef = useRef(null);
  const animationFrameRef = useRef(null);
  
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  
  // Debug function to check Firebase structure
  const debugFirebase = async () => {
    try {
      await debugAudioMatchFirebase();
    } catch (error) {
      console.error('Debug error:', error);
    }
  };
  
  useEffect(() => {
    return () => {
      stopListening();
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
    };
  }, []);
  
  const startListening = async () => {
    try {
      setError(null);
      setCurrentStep('listening');
      setIsListening(true);
      setListeningTime(0);
      
      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: {
          echoCancellation: false,
          noiseSuppression: false,
          autoGainControl: false,
          sampleRate: 44100
        } 
      });
      
      streamRef.current = stream;
      
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      audioContextRef.current = new AudioContext();
      analyserRef.current = audioContextRef.current.createAnalyser();
      analyserRef.current.fftSize = 2048;
      analyserRef.current.smoothingTimeConstant = 0.8;
      
      const source = audioContextRef.current.createMediaStreamSource(stream);
      source.connect(analyserRef.current);
      
      mediaRecorderRef.current = new MediaRecorder(stream, {
        mimeType: 'audio/webm;codecs=opus'
      });
      
      const chunks = [];
      mediaRecorderRef.current.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunks.push(e.data);
        }
      };
      
      mediaRecorderRef.current.onstop = () => {
        const audioBlob = new Blob(chunks, { type: 'audio/webm' });
        processAudio(audioBlob);
      };
      
      mediaRecorderRef.current.start();
      drawWaveform();
      
      timerRef.current = setInterval(() => {
        setListeningTime(prev => {
          if (prev >= 9) {
            stopListening();
            return prev;
          }
          return prev + 1;
        });
      }, 1000);
      
    } catch (err) {
      console.error('Error starting audio capture:', err);
      setError('Could not access microphone. Please check permissions.');
      setCurrentStep('idle');
      setIsListening(false);
    }
  };
  
  const stopListening = () => {
    setIsListening(false);
    
    if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
      mediaRecorderRef.current.stop();
    }
    
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    
    if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
      audioContextRef.current.close();
    }
    
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
      animationFrameRef.current = null;
    }
    
    if (currentStep === 'listening') {
      setCurrentStep('processing');
    }
  };
  
  const processAudio = async (audioBlob) => {
    try {
      setCurrentStep('processing');
      
      // Show processing feedback
      console.log('Processing audio blob:', audioBlob.size, 'bytes');
      
      const arrayBuffer = await audioBlob.arrayBuffer();
      const audioBuffer = await audioContextRef.current.decodeAudioData(arrayBuffer);
      
      console.log('Audio buffer decoded:', {
        numberOfChannels: audioBuffer.numberOfChannels,
        sampleRate: audioBuffer.sampleRate,
        duration: audioBuffer.duration,
        length: audioBuffer.length
      });
      
      const channelData = audioBuffer.getChannelData(0);
      const fingerprint = createAudioFingerprint(channelData);
      
      console.log('Audio fingerprint created:', fingerprint);
      
      setAudioFingerprint(fingerprint);
      await searchForMatches(fingerprint);
      
    } catch (err) {
      console.error('Error processing audio:', err);
      setError('Error processing audio. Please try again.');
      setCurrentStep('idle');
    }
  };
  
  const createAudioFingerprint = (audioData) => {
    console.log('Creating fingerprint from audio data:', {
      length: audioData.length,
      sampleRate: audioContextRef.current?.sampleRate,
      duration: audioData.length / (audioContextRef.current?.sampleRate || 44100) + ' seconds'
    });
    
    const fftSize = 2048;
    const hopSize = 512;
    const peaks = [];
    
    // Check if we have valid audio data
    let maxAmplitude = 0;
    for (let i = 0; i < audioData.length; i++) {
      maxAmplitude = Math.max(maxAmplitude, Math.abs(audioData[i]));
    }
    console.log('Max audio amplitude:', maxAmplitude);
    
    if (maxAmplitude < 0.001) {
      console.warn('Audio signal too quiet or no audio detected');
    }
    
    for (let i = 0; i < audioData.length - fftSize; i += hopSize) {
      const chunk = audioData.slice(i, i + fftSize);
      const spectrum = performFFT(chunk);
      const peakFreqs = findPeaks(spectrum);
      peaks.push(...peakFreqs);
    }
    
    console.log('Total peaks found:', peaks.length);
    
    return {
      peaks: peaks.slice(0, 100),
      duration: audioData.length,
      timestamp: Date.now()
    };
  };
  
  const performFFT = (audioData) => {
    const N = audioData.length;
    const spectrum = new Float32Array(N / 2);
    
    // Apply Hann window to reduce spectral leakage
    const windowedData = new Float32Array(N);
    for (let i = 0; i < N; i++) {
      const window = 0.5 - 0.5 * Math.cos(2 * Math.PI * i / (N - 1));
      windowedData[i] = audioData[i] * window;
    }
    
    // Compute magnitude spectrum using DFT (only positive frequencies)
    for (let k = 0; k < N / 2; k++) {
      let real = 0;
      let imag = 0;
      
      for (let n = 0; n < N; n++) {
        const angle = -2 * Math.PI * k * n / N;
        real += windowedData[n] * Math.cos(angle);
        imag += windowedData[n] * Math.sin(angle);
      }
      
      spectrum[k] = Math.sqrt(real * real + imag * imag) / N;
    }
    
    return spectrum;
  };
  
  const findPeaks = (spectrum) => {
    const peaks = [];
    
    // Calculate mean amplitude for dynamic thresholding
    let sum = 0;
    let maxValue = 0;
    for (let i = 0; i < spectrum.length; i++) {
      sum += spectrum[i];
      maxValue = Math.max(maxValue, spectrum[i]);
    }
    const meanAmplitude = sum / spectrum.length;
    const threshold = meanAmplitude * 2; // Peaks should be at least 2x the mean
    
    // Debug first spectrum
    if (Math.random() < 0.01) { // Log 1% of the time to avoid spam
      console.log('Spectrum analysis:', {
        length: spectrum.length,
        mean: meanAmplitude,
        max: maxValue,
        threshold: threshold,
        first10Values: Array.from(spectrum.slice(0, 10))
      });
    }
    
    // Find local maxima
    for (let i = 1; i < spectrum.length - 1; i++) {
      if (spectrum[i] > spectrum[i - 1] && 
          spectrum[i] > spectrum[i + 1] && 
          spectrum[i] > threshold) {
        peaks.push({ frequency: i, amplitude: spectrum[i] });
      }
    }
    
    // Sort by amplitude and return top peaks
    return peaks.sort((a, b) => b.amplitude - a.amplitude).slice(0, 10);
  };
  
  const searchForMatches = async (fingerprint) => {
    try {
      const matchedRooms = [];
      const threshold = 0.5; // 50% similarity threshold

      console.log('Searching for audio matches...');

      // Search in audioSignatures collection (primary)
      const audioSigsRef = collection(db, 'audioSignatures');
      const audioSigsSnapshot = await getDocs(audioSigsRef);

      console.log('Found', audioSigsSnapshot.docs.length, 'audio signatures');

      audioSigsSnapshot.docs.forEach(signatureDoc => {
        const signature = signatureDoc.data();
        if (signature.fingerprint && signature.fingerprint.peaks) {
          const similarity = calculateSimilarity(fingerprint, signature.fingerprint);

          console.log('Comparing with', signature.roomName, '- similarity:', (similarity * 100).toFixed(1) + '%');

          if (similarity > threshold) {
            matchedRooms.push({
              id: signatureDoc.id,
              roomId: signature.roomId,
              roomName: signature.roomName || 'Unknown Room',
              similarity,
              keywords: signature.keywords || [],
              createdAt: signature.createdAt
            });
          }
        }
      });

      // Also search in audioFingerprints collection (legacy)
      const audioFpsRef = collection(db, 'audioFingerprints');
      const audioFpsSnapshot = await getDocs(audioFpsRef);

      console.log('Found', audioFpsSnapshot.docs.length, 'legacy fingerprints');

      audioFpsSnapshot.docs.forEach(fpDoc => {
        const fp = fpDoc.data();
        if (fp.fingerprint && fp.fingerprint.peaks) {
          const similarity = calculateSimilarity(fingerprint, fp.fingerprint);

          if (similarity > threshold) {
            // Avoid duplicates
            if (!matchedRooms.some(m => m.roomId === fp.roomId)) {
              matchedRooms.push({
                id: fpDoc.id,
                roomId: fp.roomId,
                roomName: fp.metadata?.roomName || fp.roomId,
                similarity,
                keywords: fp.metadata?.keywords || [],
                createdAt: fp.timestamp
              });
            }
          }
        }
      });

      matchedRooms.sort((a, b) => b.similarity - a.similarity);

      console.log('Found', matchedRooms.length, 'matching rooms');

      setMatches(matchedRooms);
      setCurrentStep('results');

    } catch (err) {
      console.error('Error searching for matches:', err);
      setError('Error searching for matches. Please try again.');
      setCurrentStep('idle');
    }
  };
  
  const calculateSimilarity = (fp1, fp2) => {
    if (!fp1.peaks || !fp2.peaks) return 0;
    
    let matches = 0;
    const tolerance = 2;
    
    fp1.peaks.forEach(peak1 => {
      fp2.peaks.forEach(peak2 => {
        if (Math.abs(peak1.frequency - peak2.frequency) <= tolerance) {
          matches++;
        }
      });
    });
    
    return matches / Math.max(fp1.peaks.length, fp2.peaks.length);
  };
  
  const drawWaveform = () => {
    if (!analyserRef.current || !canvasRef.current) return;
    
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;
    
    const bufferLength = analyserRef.current.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    
    const draw = () => {
      if (!isListening) return;
      
      animationFrameRef.current = requestAnimationFrame(draw);
      
      analyserRef.current.getByteFrequencyData(dataArray);
      
      ctx.fillStyle = '#1f2937';
      ctx.fillRect(0, 0, width, height);
      
      const barWidth = width / bufferLength * 5;
      let x = 0;
      
      for (let i = 0; i < bufferLength; i += 5) {
        const barHeight = (dataArray[i] / 255) * height * 0.8;
        
        const gradient = ctx.createLinearGradient(0, height, 0, height - barHeight);
        gradient.addColorStop(0, '#3b82f6');
        gradient.addColorStop(1, '#8b5cf6');
        
        ctx.fillStyle = gradient;
        ctx.fillRect(x, height - barHeight, barWidth, barHeight);
        
        x += barWidth + 2;
      }
    };
    
    draw();
  };
  
  const selectRoom = (room) => {
    // Navigate to chat room (RTDB public rooms use /room/ route)
    navigate(`/room/${room.roomId}`);
  };
  
  const startRoomCreation = () => {
    setCurrentStep('create-room');
  };
  
  const createRoom = async () => {
    if (!roomName.trim() || !roomKeyword.trim()) {
      setError('Please fill in both room name and keyword');
      return;
    }
    
    if (!currentUser) {
      setError('Please log in to create a room');
      return;
    }
    
    if (!audioFingerprint) {
      setError('No audio fingerprint available. Please try recording again.');
      return;
    }
    
    try {
      setIsCreatingRoom(true);
      
      console.log('Creating room with data:', {
        name: roomName,
        keyword: roomKeyword,
        userId: currentUser.uid,
        userAuth: !!currentUser,
        isAnonymous: currentUser.isAnonymous
      });
      
      // Check user authentication status
      if (currentUser.isAnonymous) {
        setError('Anonymous users cannot create rooms. Please sign up or log in.');
        return;
      }
      
      // Create the room in RTDB at chats/public
      const roomsRef = rtdbRef(rtdb, 'chats/public');
      const newRoomRef = rtdbPush(roomsRef);
      const timestamp = Date.now();
      
      // Create room data structure matching other rooms
      const roomData = {
        name: roomName,
        description: `Audio Match Room: ${roomKeyword}`,
        nameLower: roomName.toLowerCase(),
        descriptionLower: `audio match room: ${roomKeyword.toLowerCase()}`,
        createdAt: timestamp,
        createdBy: currentUser.uid,
        creatorName: currentUser.displayName || 'User',
        lastActivityTimestamp: timestamp,
        messageCount: 0,
        isPublic: true,
        type: 'audio-match',
        status: 'active',
        keywords: [roomKeyword.toLowerCase()],
        activeUserTimestamps: {
          [currentUser.uid]: timestamp
        }
      };
      
      // Save the room to RTDB
      await rtdbSet(newRoomRef, roomData);

      console.log('Room created with ID:', newRoomRef.key);

      // Store audio signature in Firestore audioSignatures collection
      try {
        const signatureId = `${newRoomRef.key}_${Date.now()}`;
        await setDoc(doc(db, 'audioSignatures', signatureId), {
          roomId: newRoomRef.key,
          roomName: roomName,
          fingerprint: audioFingerprint,
          keywords: [roomKeyword.toLowerCase()],
          createdBy: currentUser.uid,
          createdAt: serverTimestamp()
        });
        console.log('Audio signature stored:', signatureId);
      } catch (sigErr) {
        console.warn('Could not store audio signature:', sigErr.message);
        // Continue anyway - room was created successfully
      }

      // Navigate to the new room using the room route
      console.log('Navigating to room:', newRoomRef.key);
      navigate(`/room/${newRoomRef.key}`);
      
    } catch (err) {
      console.error('Error creating room:', err);
      if (err.code === 'permission-denied') {
        setError('Permission denied. Please check if you are properly logged in and try again.');
      } else if (err.code === 'unauthenticated') {
        setError('Please log in to create a room.');
      } else {
        setError(`Error creating room: ${err.message}`);
      }
    } finally {
      setIsCreatingRoom(false);
    }
  };
  
  const reset = () => {
    setCurrentStep('idle');
    setMatches([]);
    setAudioFingerprint(null);
    setRoomKeyword('');
    setRoomName('');
    setError(null);
  };
  
  const renderMainInterface = () => {
    switch (currentStep) {
      case 'idle':
        return (
          <div className="listen-interface">
            <div className="shazam-button-container">
              <button 
                className="shazam-button"
                onClick={startListening}
                disabled={!currentUser}
              >
                <div className="shazam-button-inner">
                  <Mic size={48} className="mic-icon" />
                </div>
              </button>
              <p className="listen-instruction">
                {currentUser ? 'Tap to listen' : 'Please log in to use Audio Match'}
              </p>
              {process.env.NODE_ENV === 'development' && (
                <button 
                  onClick={debugFirebase}
                  style={{ 
                    marginTop: '10px', 
                    padding: '8px 16px', 
                    background: '#f3f4f6', 
                    border: '1px solid #d1d5db', 
                    borderRadius: '6px', 
                    fontSize: '12px'
                  }}
                >
                  Debug Firebase Structure
                </button>
              )}
            </div>
          </div>
        );
        
      case 'listening':
        return (
          <div className="listening-interface">
            <div className="listening-animation">
              <div className="pulse-circle pulse-1"></div>
              <div className="pulse-circle pulse-2"></div>
              <div className="pulse-circle pulse-3"></div>
              <button 
                className="shazam-button listening"
                onClick={stopListening}
              >
                <div className="shazam-button-inner">
                  <MicOff size={48} className="mic-icon" />
                </div>
              </button>
            </div>
            <div className="listening-info">
              <p className="listening-text">Listening...</p>
              <p className="listening-timer">{10 - listeningTime}s remaining</p>
              <p className="recording-status">🎤 Recording audio...</p>
            </div>
            <div className="waveform-container">
              <canvas 
                ref={canvasRef} 
                width={400} 
                height={100} 
                className="waveform-canvas"
              />
            </div>
            <button className="stop-button" onClick={stopListening}>
              Stop Listening
            </button>
          </div>
        );
        
      case 'processing':
        return (
          <div className="processing-interface">
            <div className="processing-animation">
              <Loader size={48} className="processing-spinner" />
            </div>
            <p className="processing-text">Processing audio...</p>
            <p className="processing-subtext">Creating fingerprint and searching for matches</p>
            <div className="processing-details">
              <p>✓ Audio captured successfully</p>
              <p>• Analyzing audio patterns...</p>
            </div>
          </div>
        );
        
      case 'results':
        return (
          <div className="results-interface">
            <h2 className="results-title">
              {matches.length === 0 ? 'No matches found' : 
               matches.length === 1 ? '1 match found' : 
               `${matches.length} matches found`}
            </h2>
            
            {matches.length > 0 ? (
              <div className="matches-list">
                {matches.map((match, index) => (
                  <div key={match.id} className="match-item" onClick={() => selectRoom(match)}>
                    <div className="match-info">
                      <h3 className="match-name">{match.roomName}</h3>
                      <div className="match-keywords">
                        {match.keywords.map((keyword, i) => (
                          <span key={i} className="keyword-tag">{keyword}</span>
                        ))}
                      </div>
                      <div className="match-similarity">
                        {Math.round(match.similarity * 100)}% match
                      </div>
                    </div>
                    <ChevronRight size={20} className="match-arrow" />
                  </div>
                ))}
              </div>
            ) : (
              <div className="no-matches">
                <div className="no-matches-icon">
                  <Search size={48} />
                </div>
                <p className="no-matches-text">
                  No matching conversations found for this audio.
                </p>
                <p className="no-matches-subtext">
                  Would you like to start a new conversation?
                </p>
                <button className="create-room-button" onClick={startRoomCreation}>
                  <Plus size={20} />
                  Create New Room
                </button>
              </div>
            )}
            
            <div className="results-actions">
              <button className="secondary-button" onClick={reset}>
                Try Again
              </button>
              {matches.length > 0 && (
                <button className="create-room-button" onClick={startRoomCreation}>
                  <Plus size={20} />
                  Create New Room
                </button>
              )}
            </div>
          </div>
        );
        
      case 'create-room':
        return (
          <div className="create-room-interface">
            <h2 className="create-room-title">Create New Room</h2>
            <p className="create-room-subtitle">
              Start a new conversation about what you're listening to
            </p>
            
            <div className="create-room-form">
              <div className="form-group">
                <label htmlFor="room-keyword">Keyword or Topic</label>
                <input
                  id="room-keyword"
                  type="text"
                  value={roomKeyword}
                  onChange={(e) => setRoomKeyword(e.target.value)}
                  placeholder="e.g., Breaking News, Song Title, Show Name"
                  className="form-input"
                />
              </div>
              
              <div className="form-group">
                <label htmlFor="room-name">Room Name</label>
                <input
                  id="room-name"
                  type="text"
                  value={roomName}
                  onChange={(e) => setRoomName(e.target.value)}
                  placeholder="e.g., Discussing Breaking News, Song Discussion"
                  className="form-input"
                />
              </div>
              
              <div className="form-actions">
                <button 
                  className="secondary-button" 
                  onClick={() => setCurrentStep('results')}
                >
                  Back
                </button>
                <button 
                  className="primary-button" 
                  onClick={createRoom}
                  disabled={isCreatingRoom || !roomName.trim() || !roomKeyword.trim()}
                >
                  {isCreatingRoom ? (
                    <>
                      <Loader size={16} className="spinning" />
                      Creating...
                    </>
                  ) : (
                    <>
                      <Plus size={16} />
                      Create Room
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        );
        
      default:
        return null;
    }
  };
  
  return (
    <div className="audio-matcher-improved">
      {error && (
        <div className="error-banner">
          <div className="error-content">
            <span className="error-text">{error}</span>
            <button className="error-close" onClick={() => setError(null)}>
              <X size={16} />
            </button>
          </div>
        </div>
      )}
      
      <div className="audio-matcher-content">
        {renderMainInterface()}
      </div>
      
      {currentStep !== 'idle' && (
        <div className="progress-indicator">
          <div className={`progress-step ${['listening', 'processing', 'results', 'create-room'].includes(currentStep) ? 'active' : ''}`}>
            <div className="step-icon">
              {currentStep === 'listening' ? <Radio size={16} /> : 
               currentStep === 'processing' ? <Search size={16} /> :
               currentStep === 'results' ? <Users size={16} /> :
               <Plus size={16} />}
            </div>
            <span className="step-label">
              {currentStep === 'listening' ? 'Listening' :
               currentStep === 'processing' ? 'Processing' :
               currentStep === 'results' ? 'Results' :
               'Create Room'}
            </span>
          </div>
        </div>
      )}
    </div>
  );
};

export default AudioMatcherImproved;