import React, { useState, useEffect } from 'react';
import { isProxyRunning } from '../../utils/patchStorage';
import { ref, listAll, getStorage } from 'firebase/storage';

/**
 * Component that checks and displays Firebase Storage proxy status
 */
const ProxyStatusCheck = () => {
  const [proxyStatus, setProxyStatus] = useState('checking');
  const [firebasePath, setFirebasePath] = useState('backgrounds/');
  const [listResults, setListResults] = useState(null);
  const [listError, setListError] = useState(null);
  const [loading, setLoading] = useState(false);

  // Check if proxy is running on mount
  useEffect(() => {
    const checkProxy = async () => {
      try {
        const isRunning = await isProxyRunning();
        setProxyStatus(isRunning ? 'running' : 'not-running');
      } catch (error) {
        console.error('Error checking proxy status:', error);
        setProxyStatus('error');
      }
    };

    checkProxy();
  }, []);

  // Function to list files
  const handleListFiles = async () => {
    setLoading(true);
    setListResults(null);
    setListError(null);

    try {
      const storage = getStorage();
      const storageRef = ref(storage, firebasePath);
      
      console.log('Listing files at:', firebasePath);
      const result = await listAll(storageRef);
      
      console.log('List operation results:', result);
      setListResults({
        items: result.items.map(item => ({
          name: item.name,
          fullPath: item.fullPath
        })),
        prefixes: result.prefixes.map(prefix => ({
          name: prefix.name,
          fullPath: prefix.fullPath
        }))
      });
    } catch (error) {
      console.error('Error listing files:', error);
      setListError(error.message || 'Unknown error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-lg shadow p-4 max-w-lg mx-auto my-4">
      <h2 className="text-lg font-semibold mb-4">Firebase Storage Proxy Status</h2>
      
      {/* Status display */}
      <div className="mb-4">
        <div className="flex items-center gap-2">
          <span className="text-sm font-medium">Proxy Server:</span>
          <span 
            className={`px-2 py-1 text-xs font-medium rounded-full ${
              proxyStatus === 'running' ? 'bg-green-100 text-green-800' : 
              proxyStatus === 'not-running' ? 'bg-red-100 text-red-800' : 
              'bg-gray-100 text-gray-800'
            }`}
          >
            {proxyStatus === 'running' ? 'Running' : 
             proxyStatus === 'not-running' ? 'Not Running' : 
             proxyStatus === 'error' ? 'Error Checking' : 'Checking...'}
          </span>
        </div>
        
        {proxyStatus === 'not-running' && (
          <div className="mt-2 p-3 bg-yellow-50 text-sm rounded border border-yellow-200">
            <strong>Proxy server is not running!</strong>
            <p className="text-xs mt-1">
              In a terminal, run: <code className="bg-gray-100 px-1 py-0.5 rounded">npm run simple-proxy</code>
            </p>
          </div>
        )}
      </div>
      
      {/* File listing tester */}
      <div className="mt-6">
        <h3 className="text-md font-medium mb-2">Test Firebase Storage Access</h3>
        
        <div className="flex gap-2 mb-3">
          <input
            type="text"
            value={firebasePath}
            onChange={(e) => setFirebasePath(e.target.value)}
            placeholder="Firebase path (e.g. backgrounds/)"
            className="flex-1 px-3 py-2 border rounded text-sm"
          />
          <button
            onClick={handleListFiles}
            disabled={loading || proxyStatus !== 'running'}
            className={`px-4 py-2 text-sm font-medium rounded ${
              loading || proxyStatus !== 'running' 
                ? 'bg-gray-200 text-gray-500 cursor-not-allowed' 
                : 'bg-blue-600 text-white hover:bg-blue-700'
            }`}
          >
            {loading ? 'Listing...' : 'List Files'}
          </button>
        </div>
        
        {/* Error message */}
        {listError && (
          <div className="mb-3 p-3 bg-red-50 text-sm text-red-700 rounded border border-red-200">
            <strong>Error:</strong> {listError}
          </div>
        )}
        
        {/* Results display */}
        {listResults && (
          <div className="border rounded p-3 bg-gray-50">
            <div className="mb-2">
              <h4 className="font-medium text-sm">Folders ({listResults.prefixes.length})</h4>
              {listResults.prefixes.length > 0 ? (
                <ul className="text-sm">
                  {listResults.prefixes.map((prefix, idx) => (
                    <li key={idx} className="flex items-center gap-1">
                      <span className="text-yellow-600">📁</span>
                      <span>{prefix.fullPath}</span>
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="text-sm text-gray-500">No folders found</p>
              )}
            </div>
            
            <div>
              <h4 className="font-medium text-sm">Files ({listResults.items.length})</h4>
              {listResults.items.length > 0 ? (
                <ul className="text-sm">
                  {listResults.items.map((item, idx) => (
                    <li key={idx} className="flex items-center gap-1">
                      <span className="text-blue-600">📄</span>
                      <span>{item.fullPath}</span>
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="text-sm text-gray-500">No files found</p>
              )}
            </div>
          </div>
        )}
      </div>
      
      {/* Instructions */}
      <div className="mt-6 text-xs text-gray-600 bg-gray-50 p-3 rounded border">
        <p className="font-medium mb-1">Instructions:</p>
        <ol className="list-decimal pl-5 space-y-1">
          <li>Start the proxy server with <code className="bg-gray-100 px-1 py-0.5 rounded">npm run simple-proxy</code></li>
          <li>Refresh this page to verify the proxy is running</li>
          <li>Use the form above to test listing files from Firebase Storage</li>
        </ol>
        <p className="mt-2">If successful, you should see files and folders without CORS errors.</p>
      </div>
    </div>
  );
};

export default ProxyStatusCheck;
