// src/admin/SiteSettings.js
import React from 'react';
import { useSiteConfig } from '../contexts/SiteConfigContext';

const SiteSettings = () => {
  const { config, setConfig } = useSiteConfig();

  // Update a simple text field in the config
  const handleTextChange = (e) => {
    const { name, value } = e.target;
    setConfig({
      ...config,
      [name]: value,
    });
  };

  // Update color fields
  const handleColorChange = (e) => {
    const { name, value } = e.target;
    setConfig({
      ...config,
      [name]: value,
    });
  };

  // Update video settings
  const handleVideoSettingChange = (e) => {
    const { name, checked, type, value } = e.target;
    const newValue = type === 'checkbox' ? checked : value;
    
    setConfig({
      ...config,
      videoSettings: {
        ...config.videoSettings,
        [name]: newValue,
      }
    });
  };

  return (
    <div>
      <h2 className="text-xl font-semibold mb-4">Site Settings</h2>
      
      {/* General Settings */}
      <div className="mb-8 p-4 bg-gray-50 rounded-lg">
        <h3 className="text-lg font-medium mb-3">General Settings</h3>
        
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Site Name
            </label>
            <input
              type="text"
              name="siteName"
              value={config?.siteName || 'TalkStudio'}
              onChange={handleTextChange}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
          </div>
          
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Header Tagline
            </label>
            <input
              type="text"
              name="headerTagline"
              value={config?.headerTagline || 'Welcome to TalkStudio'}
              onChange={handleTextChange}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
          </div>
          
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Search Bar Text
            </label>
            <input
              type="text"
              name="searchBarText"
              value={config?.searchBarText || 'Search for topics...'}
              onChange={handleTextChange}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
          </div>
          
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Footer Text
            </label>
            <input
              type="text"
              name="footerText"
              value={config?.footerText || '© 2025 TalkStudio. All rights reserved.'}
              onChange={handleTextChange}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
          </div>
        </div>
      </div>
      
      {/* Theme Settings */}
      <div className="mb-8 p-4 bg-gray-50 rounded-lg">
        <h3 className="text-lg font-medium mb-3">Theme Settings</h3>
        
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Primary Color
            </label>
            <div className="flex">
              <input
                type="color"
                name="primaryColor"
                value={config?.primaryColor || '#4F46E5'}
                onChange={handleColorChange}
                className="h-10 w-10 border border-gray-300 rounded-md mr-2"
              />
              <input
                type="text"
                value={config?.primaryColor || '#4F46E5'}
                onChange={handleColorChange}
                name="primaryColor"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>
          </div>
          
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Secondary Color
            </label>
            <div className="flex">
              <input
                type="color"
                name="secondaryColor"
                value={config?.secondaryColor || '#1E40AF'}
                onChange={handleColorChange}
                className="h-10 w-10 border border-gray-300 rounded-md mr-2"
              />
              <input
                type="text"
                value={config?.secondaryColor || '#1E40AF'}
                onChange={handleColorChange}
                name="secondaryColor"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>
          </div>
        </div>
      </div>
      
      {/* Video Settings */}
      <div className="mb-8 p-4 bg-gray-50 rounded-lg">
        <h3 className="text-lg font-medium mb-3">Video Background Settings</h3>
        
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="flex items-center">
            <input
              type="checkbox"
              id="autoplay"
              name="autoplay"
              checked={config?.videoSettings?.autoplay !== false}
              onChange={handleVideoSettingChange}
              className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
            />
            <label htmlFor="autoplay" className="ml-2 block text-sm text-gray-700">
              Autoplay Videos (recommended)
            </label>
          </div>
          
          <div className="flex items-center">
            <input
              type="checkbox"
              id="loop"
              name="loop"
              checked={config?.videoSettings?.loop !== false}
              onChange={handleVideoSettingChange}
              className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
            />
            <label htmlFor="loop" className="ml-2 block text-sm text-gray-700">
              Loop Videos
            </label>
          </div>
          
          <div className="flex items-center">
            <input
              type="checkbox"
              id="muted"
              name="muted"
              checked={config?.videoSettings?.muted !== false}
              onChange={handleVideoSettingChange}
              className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
            />
            <label htmlFor="muted" className="ml-2 block text-sm text-gray-700">
              Mute Videos (recommended)
            </label>
          </div>
          
          <div className="flex items-center">
            <input
              type="checkbox"
              id="controls"
              name="controls"
              checked={config?.videoSettings?.controls === true}
              onChange={handleVideoSettingChange}
              className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
            />
            <label htmlFor="controls" className="ml-2 block text-sm text-gray-700">
              Show Video Controls
            </label>
          </div>
          
          <div>
            <label htmlFor="playbackRate" className="block text-sm font-medium text-gray-700 mb-1">
              Playback Speed
            </label>
            <select
              id="playbackRate"
              name="playbackRate"
              value={config?.videoSettings?.playbackRate || 1}
              onChange={handleVideoSettingChange}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            >
              <option value={0.5}>0.5x (Slow)</option>
              <option value={0.75}>0.75x</option>
              <option value={1}>1x (Normal)</option>
              <option value={1.25}>1.25x</option>
              <option value={1.5}>1.5x (Fast)</option>
            </select>
          </div>
        </div>
      </div>
      
      <div className="text-sm text-gray-500 mt-4">
        <p>Note: Changes will not be applied until you click "Save Changes" in the header.</p>
      </div>
    </div>
  );
};

export default SiteSettings;