// src/components/premium/PremiumGuard.jsx
import React from 'react';
import { useSubscription } from '../../hooks/useSubscription';
import { useAuth } from '../../contexts/AuthContext';
import { Link } from 'react-router-dom';
import { Crown, Lock } from 'lucide-react';
import './PremiumGuard.css';

/**
 * Tier labels for upgrade CTAs.
 */
const TIER_LABELS = {
  data: 'Data ($20/mo)',
  crm: 'CRM ($99/mo)',
  elite: 'Elite ($999/mo)',
};

/**
 * Component that wraps tiered content. Renders children if the user meets
 * `minTier`, otherwise shows an upgrade prompt. Falls back to legacy
 * isActive-based gating when no minTier is provided.
 *
 * Props:
 *   minTier?: 'data' | 'crm' | 'elite'   — required subscription tier
 *   children                              — gated content
 *   showUpgrade?: boolean                 — show CTA when gated (default true)
 *   fallback?: ReactNode                  — custom fallback (overrides CTA)
 *   featureName?: string                  — used in CTA copy
 *   allowAnonymous?: boolean              — when true, anonymous visitors (not
 *                                           signed in, or Firebase anonymous
 *                                           auth) get access; signed-in
 *                                           accounts still gated by tier
 */
const PremiumGuard = ({
  children,
  minTier,
  showUpgrade = true,
  fallback = null,
  className = '',
  featureName = 'this feature',
  allowAnonymous = false
}) => {
  const { isActive, loading, meetsTier } = useSubscription();
  const { currentUser } = useAuth();
  // "Anonymous" = a not-signed-in visitor or a Firebase anonymous-auth user.
  // A signed-in real account (even on the free tier) is not anonymous.
  const isAnonymous = !currentUser || currentUser.isAnonymous;

  // Show loading state
  if (loading) {
    return (
      <div className={`premium-guard loading ${className}`}>
        <div className="premium-guard-spinner"></div>
      </div>
    );
  }

  // Access check: minTier (new tier system) or isActive (legacy binary gate),
  // with an opt-in bypass for anonymous visitors.
  const hasAccess = (minTier ? meetsTier(minTier) : isActive) || (allowAnonymous && isAnonymous);

  if (hasAccess) {
    return <>{children}</>;
  }

  // User doesn't have access
  if (fallback) {
    return fallback;
  }

  if (!showUpgrade) {
    return null;
  }

  const tierLabel = minTier ? TIER_LABELS[minTier] : 'Premium';

  // Show upgrade prompt
  return (
    <div className={`premium-guard upgrade-required ${className}`}>
      <div className="premium-guard-content">
        <div className="premium-guard-icon">
          <Crown />
          <Lock className="lock-overlay" />
        </div>
        <h3>{tierLabel} required</h3>
        <p>Upgrade to {tierLabel} to access {featureName}</p>
        <Link to="/premium-membership" className="upgrade-button">
          <Crown size={16} />
          See plans
        </Link>
      </div>
    </div>
  );
};

/**
 * Hook version for conditional rendering.
 */
export const usePremiumGuard = (minTier) => {
  const { isActive, loading, meetsTier, tier, features } = useSubscription();
  const hasAccess = minTier ? meetsTier(minTier) : isActive;

  return {
    hasAccess,
    hasPremiumAccess: isActive,
    loading,
    isActive,
    tier,
    features,
  };
};

export default PremiumGuard;
