import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import IdeaService from '../services/IdeaService';
import TopicService from '../services/TopicService';
import './IdeasPage.css';

const IdeasPage = () => {
  const { topicId } = useParams();
  const [topic, setTopic] = useState(null);
  const [ideas, setIdeas] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    // Load topic
    TopicService.getTopic(topicId).then(setTopic);

    // Subscribe to real-time idea updates for this topic
    const unsubscribe = IdeaService.streamIdeasByTopic(topicId, (updatedIdeas) => {
      setIdeas(updatedIdeas);
      setLoading(false);
    });

    // Cleanup subscription on unmount
    return () => unsubscribe();
  }, [topicId]);

  const formatDate = (timestamp) => {
    const date = new Date(timestamp);
    const now = new Date();
    const diffInSeconds = Math.floor((now - date) / 1000);

    if (diffInSeconds < 60) return 'just now';
    if (diffInSeconds < 3600) return `${Math.floor(diffInSeconds / 60)}m ago`;
    if (diffInSeconds < 86400) return `${Math.floor(diffInSeconds / 3600)}h ago`;
    if (diffInSeconds < 604800) return `${Math.floor(diffInSeconds / 86400)}d ago`;

    return date.toLocaleDateString();
  };

  if (loading || !topic) {
    return (
      <div className="ideas-page">
        <div className="loading">Loading ideas...</div>
      </div>
    );
  }

  return (
    <div className="ideas-page">
      <div className="ideas-header">
        <button className="back-button" onClick={() => navigate(`/categories/${topic.categoryId}/topics`)}>
          ← Back to Topics
        </button>
        <div className="topic-title">
          <h1 style={{ color: topic.colorHex }}>{topic.name}</h1>
          <p>{topic.description}</p>
          <div className="topic-meta">
            <span className="meta-item">💡 {ideas.length} ideas</span>
          </div>
        </div>
      </div>

      {ideas.length === 0 ? (
        <div className="empty-state">
          <div className="empty-icon">💡</div>
          <h2>No Ideas Yet</h2>
          <p>Be the first to share an idea in this topic!</p>
        </div>
      ) : (
        <div className="ideas-list">
          {ideas.map((idea) => (
            <div
              key={idea.id}
              className="idea-card"
              style={{
                borderLeft: `4px solid ${topic.colorHex}`,
              }}
            >
              <div className="idea-votes">
                <button className="vote-button upvote">▲</button>
                <span className="vote-count">{idea.upvoteCount || 0}</span>
                <button className="vote-button downvote">▼</button>
              </div>
              <div className="idea-content">
                <h3 className="idea-title">{idea.title}</h3>
                <p className="idea-description">{idea.description}</p>
                <div className="idea-meta">
                  <span className="meta-item">
                    👤 {idea.creatorName}
                  </span>
                  <span className="meta-item">
                    📅 {formatDate(idea.createdAt)}
                  </span>
                  <span className="meta-item">
                    💬 {idea.commentCount || 0} comments
                  </span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default IdeasPage;
