// src/components/deals/DealCard.jsx
import React from 'react';
import { MapPin, DollarSign, CheckCircle2, FileSignature, Home, Tag } from 'lucide-react';
import './DealCard.css';

const STATUS_META = {
  listed:         { label: 'Listed',         color: '#64748b', Icon: Tag },
  under_contract: { label: 'Under contract', color: '#0891b2', Icon: FileSignature },
  closed:         { label: 'Closed',         color: '#16a34a', Icon: CheckCircle2 },
  cancelled:      { label: 'Cancelled',      color: '#9ca3af', Icon: Tag },
};

function formatPrice(price) {
  const n = Number(price);
  if (!Number.isFinite(n) || n <= 0) return '—';
  if (n >= 1_000_000) return `$${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}M`;
  if (n >= 1_000) return `$${Math.round(n / 1_000)}K`;
  return `$${n.toLocaleString()}`;
}

function formatLocation(address, publicView) {
  if (!address) return '';
  if (publicView) {
    return [address.city, address.state].filter(Boolean).join(', ');
  }
  return [
    address.line1,
    address.line2,
    [address.city, address.state].filter(Boolean).join(', '),
    address.postalCode,
  ].filter(Boolean).join(' · ');
}

/**
 * Renders a single deal as a card.
 *
 * @param {object} props
 * @param {object} props.deal - firestore deals/{dealId} doc
 * @param {boolean} [props.publicView=true] - if true, hide full street address
 */
const DealCard = ({ deal, publicView = true }) => {
  if (!deal) return null;
  const status = STAR_STATUS(deal.status);
  const StatusIcon = status.Icon;

  return (
    <div className="deal-card">
      <div className="deal-card__header">
        <div className="deal-card__status" style={{ color: status.color, borderColor: status.color }}>
          <StatusIcon size={14} />
          <span>{status.label}</span>
        </div>
        <div className="deal-card__price">
          <DollarSign size={14} />
          <span>{formatPrice(deal.price)}</span>
        </div>
      </div>

      {deal.note && <div className="deal-card__note">{deal.note}</div>}

      <div className="deal-card__meta">
        <div className="deal-card__meta-item">
          <MapPin size={14} />
          <span>{formatLocation(deal.address, publicView) || 'Location hidden'}</span>
        </div>
        {deal.propertyType && (
          <div className="deal-card__meta-item">
            <Home size={14} />
            <span>{deal.propertyType.replace('_', ' ')}</span>
          </div>
        )}
      </div>
    </div>
  );
};

// Local helper with safe fallback for unknown status values.
function STAR_STATUS(status) {
  return STATUS_META[status] || STATUS_META.listed;
}

export default DealCard;
