import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import WatchReplaysPage from '../../pages/WatchReplaysPage';

const QuickVideoTest = () => {
  const [searchParams] = useSearchParams();
  const [testStatus, setTestStatus] = useState('Starting test...');
  const [showPlayer, setShowPlayer] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    const runTest = async () => {
      try {
        setTestStatus('Testing URL parameters...');
        
        // Test if event ID is properly passed
        const eventId = searchParams.get('event') || '4S5WjB6vHRSqfoVc6lGK';
        setTestStatus(`Event ID: ${eventId}`);
        
        // Test component loading
        setTestStatus('Loading WatchReplaysPage component...');
        
        setTimeout(() => {
          setTestStatus('Component loaded successfully!');
          setShowPlayer(true);
        }, 1000);
        
      } catch (err) {
        setError(err.message);
        setTestStatus('Test failed');
      }
    };
    
    runTest();
  }, [searchParams]);

  if (error) {
    return (
      <div className="p-6 max-w-4xl mx-auto">
        <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded">
          <h2 className="font-bold">Test Error</h2>
          <p>{error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <div className="bg-white rounded-lg shadow-md p-6 mb-6">
        <h2 className="text-2xl font-bold mb-4">Quick Video Test</h2>
        <div className="mb-4">
          <p className="text-gray-600">Status: <span className="font-medium">{testStatus}</span></p>
        </div>
        
        {!showPlayer && (
          <div className="flex items-center justify-center p-8">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
            <span className="ml-2 text-blue-600">Loading...</span>
          </div>
        )}
      </div>
      
      {showPlayer && (
        <div className="bg-gray-50 rounded-lg p-4">
          <h3 className="text-lg font-semibold mb-4">Loading WatchReplaysPage Component</h3>
          <div className="border-2 border-dashed border-gray-300 rounded-lg p-4">
            <WatchReplaysPage />
          </div>
        </div>
      )}
    </div>
  );
};

export default QuickVideoTest;