// src/utils/debug-utils.js

/**
 * Debug utility to log room data and user status
 * @param {Array} rooms - Array of room objects
 * @param {Object} user - Current user object
 * @param {string} source - Source component name
 */
export const debugRoomData = (rooms, user, source) => {
  console.group(`Debug Room Data from ${source}`);
  console.log('Current User:', user ? {
    uid: user.uid,
    isAnonymous: user.isAnonymous,
    displayName: user.displayName || 'Anonymous'
  } : 'No user');
  
  console.log('Total Rooms:', rooms.length);
  console.log('Public Rooms:', rooms.filter(room => room.type === 'public' || !room.type).length);
  
  if (rooms.length > 0) {
    console.log('First 3 rooms:', rooms.slice(0, 3).map(room => ({
      id: room.id,
      name: room.name,
      type: room.type || 'public',
      participants: room.participants || room.activeUsers || 0
    })));
  }
  
  console.groupEnd();
};

/**
 * Debug utility to check for common issues
 * @param {Array} rooms - Array of room objects
 */
export const debugRoomIssues = (rooms) => {
  const issues = [];
  
  // Check for rooms without type
  const roomsWithoutType = rooms.filter(room => !room.type);
  if (roomsWithoutType.length > 0) {
    issues.push(`Found ${roomsWithoutType.length} rooms without a type`);
  }
  
  // Check for rooms with invalid types
  const validTypes = ['public', 'private', 'registered', 'vip'];
  const roomsWithInvalidType = rooms.filter(room => room.type && !validTypes.includes(room.type));
  if (roomsWithInvalidType.length > 0) {
    issues.push(`Found ${roomsWithInvalidType.length} rooms with invalid types: ${roomsWithInvalidType.map(r => r.type).join(', ')}`);
  }
  
  // Report findings
  if (issues.length > 0) {
    console.warn('Room data issues found:');
    issues.forEach(issue => console.warn(`- ${issue}`));
  } else {
    console.log('No common room data issues found');
  }
};
