import { usePredictions } from '../contexts/PredictionContext'
import SearchBar from '../components/common/SearchBar'
import FilterBar from '../components/common/FilterBar'
import PredictionList from '../components/predictions/PredictionList'

export default function Predictions() {
  const { predictions, loading, filters, setCategory, setSort, setSearch } = usePredictions()

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">All Predictions</h1>
        <p className="text-sm text-gray-500 mt-1">{predictions.length} predictions across all categories</p>
      </div>

      <SearchBar value={filters.search} onChange={setSearch} />

      <FilterBar
        activeCategory={filters.category}
        sortBy={filters.sort}
        onCategoryChange={setCategory}
        onSortChange={setSort}
      />

      <PredictionList predictions={predictions} loading={loading} />
    </div>
  )
}
