import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import CategoryService from '../services/CategoryService';
import './CategoriesPage.css';

const CategoriesPage = () => {
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    // Subscribe to real-time category updates
    const unsubscribe = CategoryService.streamAllCategories((updatedCategories) => {
      setCategories(updatedCategories);
      setLoading(false);
    });

    // Cleanup subscription on unmount
    return () => unsubscribe();
  }, []);

  const handleCategoryClick = (category) => {
    navigate(`/categories/${category.id}/topics`);
  };

  const getCategoryIcon = (iconName) => {
    // Map icon names to emoji or use a default
    const iconMap = {
      music: '🎵',
      music_note: '🎵',
      art: '🎨',
      palette: '🎨',
      gaming: '🎮',
      games: '🎮',
      gamepad: '🎮',
      education: '📚',
      school: '📚',
      fitness: '💪',
      sports: '⚽',
      talk: '💬',
      chat: '💬',
      performance: '🎭',
      theater: '🎭',
      category: '📁',
    };

    return iconMap[iconName?.toLowerCase()] || '📁';
  };

  if (loading) {
    return (
      <div className="categories-page">
        <div className="categories-header">
          <h1>Discover Categories</h1>
          <p>Explore topics and interests</p>
        </div>
        <div className="loading">Loading categories...</div>
      </div>
    );
  }

  if (categories.length === 0) {
    return (
      <div className="categories-page">
        <div className="categories-header">
          <h1>Discover Categories</h1>
          <p>Explore topics and interests</p>
        </div>
        <div className="empty-state">
          <div className="empty-icon">📂</div>
          <h2>No Categories Available</h2>
          <p>Check back later for new categories!</p>
        </div>
      </div>
    );
  }

  return (
    <div className="categories-page">
      <div className="categories-header">
        <h1>Discover Categories</h1>
        <p>Explore topics and interests across the platform</p>
      </div>

      <div className="categories-grid">
        {categories.map((category) => (
          <div
            key={category.id}
            className="category-card"
            onClick={() => handleCategoryClick(category)}
            style={{
              borderLeft: `4px solid ${category.colorHex}`,
            }}
          >
            <div className="category-icon" style={{ color: category.colorHex }}>
              {getCategoryIcon(category.iconName)}
            </div>
            <div className="category-content">
              <h3>{category.name}</h3>
              <p>{category.description}</p>
              <div className="category-stats">
                <span className="stat">
                  <span className="stat-icon">🏷️</span>
                  {category.topicCount} topics
                </span>
                <span className="stat">
                  <span className="stat-icon">👥</span>
                  {category.followerCount} followers
                </span>
              </div>
            </div>
            <div className="category-arrow">→</div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default CategoriesPage;
