// SignupDebugger.jsx - Debug component for signup issues
// Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\components\debug\SignupDebugger.jsx

import React, { useState, useEffect } from 'react';
import { createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';
import { setDoc, doc } from 'firebase/firestore';
import { auth, db } from '../../firebase';

const SignupDebugger = () => {
  const [debugInfo, setDebugInfo] = useState([]);
  const [testData, setTestData] = useState({
    email: 'test@example.com',
    password: 'testpass123',
    displayName: 'Test User',
    username: 'testuser123'
  });
  const [isTestRunning, setIsTestRunning] = useState(false);

  const addDebugLog = (message, type = 'info') => {
    const timestamp = new Date().toISOString().split('T')[1].split('.')[0];
    setDebugInfo(prev => [...prev, { 
      timestamp, 
      message, 
      type,
      id: Date.now() + Math.random()
    }]);
  };

  const runSignupTest = async () => {
    setIsTestRunning(true);
    setDebugInfo([]);
    
    addDebugLog('🔧 Starting signup test...', 'info');
    
    try {
      // Test 1: Check Firebase config
      addDebugLog('✅ Firebase auth object exists', 'success');
      addDebugLog(`Auth currentUser: ${auth.currentUser ? 'logged in' : 'null'}`, 'info');
      
      // Test 2: Check Firestore connection
      addDebugLog('Testing Firestore connection...', 'info');
      try {
        const testDoc = doc(db, 'test', 'connection');
        addDebugLog('✅ Firestore connection successful', 'success');
      } catch (firestoreError) {
        addDebugLog(`❌ Firestore error: ${firestoreError.message}`, 'error');
      }
      
      // Test 3: Try to create user
      addDebugLog('Attempting user creation...', 'info');
      
      const userCredential = await createUserWithEmailAndPassword(
        auth, 
        testData.email + Date.now(), // Make email unique
        testData.password
      );
      
      addDebugLog('✅ User created successfully', 'success');
      addDebugLog(`User UID: ${userCredential.user.uid}`, 'info');
      
      // Test 4: Update profile
      await updateProfile(userCredential.user, {
        displayName: testData.displayName
      });
      addDebugLog('✅ Profile updated successfully', 'success');
      
      // Test 5: Create Firestore document
      await setDoc(doc(db, 'users', userCredential.user.uid), {
        uid: userCredential.user.uid,
        displayName: testData.displayName,
        username: testData.username + Date.now(),
        email: userCredential.user.email,
        createdAt: new Date(),
        isAdmin: false,
        isArtist: false
      });
      addDebugLog('✅ Firestore document created successfully', 'success');
      
      // Test 6: Clean up test user
      await userCredential.user.delete();
      addDebugLog('✅ Test user cleaned up', 'success');
      
      addDebugLog('🎉 All signup tests passed!', 'success');
      
    } catch (error) {
      addDebugLog(`❌ Signup test failed: ${error.message}`, 'error');
      addDebugLog(`Error code: ${error.code}`, 'error');
      console.error('Full error object:', error);
    }
    
    setIsTestRunning(false);
  };

  const checkBrowserEnvironment = () => {
    addDebugLog('🔧 Checking browser environment...', 'info');
    
    // Check if running in secure context
    if (window.isSecureContext) {
      addDebugLog('✅ Running in secure context (HTTPS/localhost)', 'success');
    } else {
      addDebugLog('❌ Not running in secure context - Firebase may not work', 'error');
    }
    
    // Check localStorage
    try {
      localStorage.setItem('test', 'test');
      localStorage.removeItem('test');
      addDebugLog('✅ localStorage working', 'success');
    } catch (e) {
      addDebugLog('❌ localStorage not available', 'error');
    }
    
    // Check indexedDB
    if (window.indexedDB) {
      addDebugLog('✅ IndexedDB available', 'success');
    } else {
      addDebugLog('❌ IndexedDB not available', 'error');
    }
    
    // Check network connectivity
    if (navigator.onLine) {
      addDebugLog('✅ Browser shows online', 'success');
    } else {
      addDebugLog('❌ Browser shows offline', 'error');
    }
    
    // Check current URL
    addDebugLog(`Current URL: ${window.location.href}`, 'info');
    addDebugLog(`Origin: ${window.location.origin}`, 'info');
  };

  const checkFirebaseConfig = () => {
    addDebugLog('🔧 Checking Firebase configuration...', 'info');
    
    try {
      if (auth) {
        addDebugLog('✅ Firebase Auth initialized', 'success');
        addDebugLog(`Auth app name: ${auth.app.name}`, 'info');
      }
      
      if (db) {
        addDebugLog('✅ Firestore initialized', 'success');
        addDebugLog(`Firestore app name: ${db.app.name}`, 'info');
      }
      
      // Check environment variables.
      //
      // Each var is read by literal property access. A computed lookup
      // (import.meta.env[someVar]) can't be resolved at build time, so Vite
      // falls back to inlining the ENTIRE env object into the bundle --
      // shipping every VITE_ var on the build machine to every visitor.
      const envVars = [
        ['VITE_FIREBASE_API_KEY', import.meta.env.VITE_FIREBASE_API_KEY],
        ['VITE_FIREBASE_AUTH_DOMAIN', import.meta.env.VITE_FIREBASE_AUTH_DOMAIN],
        ['VITE_FIREBASE_PROJECT_ID', import.meta.env.VITE_FIREBASE_PROJECT_ID]
      ];
      
      envVars.forEach(([envVar, value]) => {
        if (value) {
          addDebugLog(`✅ ${envVar}: ${value.substring(0, 10)}...`, 'success');
        } else {
          addDebugLog(`❌ ${envVar}: not set`, 'error');
        }
      });
      
    } catch (error) {
      addDebugLog(`❌ Firebase config error: ${error.message}`, 'error');
    }
  };

  useEffect(() => {
    checkBrowserEnvironment();
    checkFirebaseConfig();
  }, []);

  const getLogColor = (type) => {
    switch (type) {
      case 'success': return '#10b981';
      case 'error': return '#ef4444';
      case 'warning': return '#f59e0b';
      default: return '#6b7280';
    }
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'monospace' }}>
      <h2>🔧 Signup Debugger</h2>
      
      <div style={{ marginBottom: '20px' }}>
        <button 
          onClick={runSignupTest}
          disabled={isTestRunning}
          style={{
            padding: '10px 20px',
            backgroundColor: isTestRunning ? '#9ca3af' : '#3b82f6',
            color: 'white',
            border: 'none',
            borderRadius: '5px',
            cursor: isTestRunning ? 'not-allowed' : 'pointer'
          }}
        >
          {isTestRunning ? 'Running Test...' : 'Run Signup Test'}
        </button>
      </div>
      
      <div style={{
        backgroundColor: '#1f2937',
        color: '#f9fafb',
        padding: '15px',
        borderRadius: '5px',
        maxHeight: '500px',
        overflowY: 'auto',
        fontSize: '14px'
      }}>
        <h3 style={{ color: '#60a5fa', marginTop: 0 }}>Debug Log:</h3>
        {debugInfo.map(log => (
          <div key={log.id} style={{ marginBottom: '5px' }}>
            <span style={{ color: '#9ca3af' }}>[{log.timestamp}]</span>
            <span style={{ color: getLogColor(log.type), marginLeft: '10px' }}>
              {log.message}
            </span>
          </div>
        ))}
        {debugInfo.length === 0 && (
          <div style={{ color: '#9ca3af', fontStyle: 'italic' }}>
            Environment checks completed. Click "Run Signup Test" to test account creation.
          </div>
        )}
      </div>
      
      <div style={{ marginTop: '20px', fontSize: '12px', color: '#6b7280' }}>
        <p><strong>Instructions:</strong></p>
        <ol>
          <li>Check the debug log above for any Firebase configuration issues</li>
          <li>Click "Run Signup Test" to test the full signup flow</li>
          <li>If errors appear, note the error codes and messages</li>
          <li>This test will create and immediately delete a test user</li>
        </ol>
      </div>
    </div>
  );
};

export default SignupDebugger;