// src/models/ChatRoom.js
// Functions for managing chat rooms and VIP access

import { db } from '../firebase';
import { 
  collection, 
  doc, 
  getDoc, 
  getDocs, 
  setDoc, 
  updateDoc, 
  addDoc, 
  serverTimestamp, 
  query, 
  where 
} from 'firebase/firestore';
import { hasVipAccess } from './UserMembership';

/**
 * Room access levels enum
 */
export const RoomAccessLevel = {
  PUBLIC: 'public',   // Any user can access
  BASIC: 'basic',     // Only registered (non-anonymous) users can access
  VIP: 'vip'          // Only VIP members can access
};

/**
 * Create a new chat room
 * 
 * @param {Object} roomData - The chat room data
 * @param {string} roomData.name - The name of the chat room
 * @param {string} roomData.description - The description of the chat room
 * @param {string} roomData.accessLevel - The access level of the room (from RoomAccessLevel)
 * @param {string} roomData.createdBy - The user ID of the creator
 * @param {string} roomData.creatorName - The display name of the creator
 * @returns {Promise<string>} - The new room ID
 */
export const createChatRoom = async (roomData) => {
  try {
    // If trying to create a VIP room, check if user has VIP access
    if (roomData.accessLevel === RoomAccessLevel.VIP) {
      const creatorId = roomData.createdBy;
      if (!creatorId) {
        throw new Error("Creator ID required for VIP room creation");
      }
      
      // Check if creator exists and has VIP access
      const creatorRef = doc(db, 'users', creatorId);
      const creatorSnap = await getDoc(creatorRef);
      
      if (!creatorSnap.exists()) {
        throw new Error("Creator not found");
      }
      
      const creatorData = creatorSnap.data();
      
      // Check for isVIP flag or fallback to legacy VIP check
      if (creatorData.isVIP !== true) {
        const hasVip = await hasVipAccess(creatorId);
        if (!hasVip) {
          throw new Error("VIP access required to create VIP chat rooms");
        }
      }
    }
    
    // Set up the room document data
    const roomDocData = {
      name: roomData.name,
      description: roomData.description || '',
      accessLevel: roomData.accessLevel || RoomAccessLevel.PUBLIC,
      createdBy: roomData.createdBy,
      creatorName: roomData.creatorName || 'Unknown',
      createdAt: serverTimestamp(),
      updatedAt: serverTimestamp(),
      memberCount: 0,
      messageCount: 0,
      isActive: true
    };
    
    // Add VIP badge to room name if it's a VIP room
    if (roomData.accessLevel === RoomAccessLevel.VIP) {
      roomDocData.name = `${roomData.name} 👑 VIP`;
      roomDocData.isVip = true;
    }
    
    // Add the room to the chat rooms collection
    const roomRef = await addDoc(collection(db, 'chatRooms'), roomDocData);
    
    return roomRef.id;
  } catch (error) {
    console.error('Error creating chat room:', error);
    throw error;
  }
};

/**
 * Get a chat room by ID
 * 
 * @param {string} roomId - The room ID to fetch
 * @returns {Promise<Object|null>} - The room data or null if not found
 */
export const getChatRoom = async (roomId) => {
  try {
    const roomRef = doc(db, 'chatRooms', roomId);
    const roomSnap = await getDoc(roomRef);
    
    if (!roomSnap.exists()) {
      return null;
    }
    
    return {
      id: roomSnap.id,
      ...roomSnap.data()
    };
  } catch (error) {
    console.error('Error getting chat room:', error);
    return null;
  }
};

/**
 * Get all VIP chat rooms
 * 
 * @returns {Promise<Array>} - An array of VIP chat rooms
 */
export const getVipChatRooms = async () => {
  try {
    const roomsQuery = query(
      collection(db, 'chatRooms'), 
      where('accessLevel', '==', RoomAccessLevel.VIP),
      where('isActive', '==', true)
    );
    
    const roomsSnap = await getDocs(roomsQuery);
    
    return roomsSnap.docs.map(doc => ({
      id: doc.id,
      ...doc.data()
    }));
  } catch (error) {
    console.error('Error getting VIP chat rooms:', error);
    return [];
  }
};

/**
 * Check if a user has access to a specific chat room
 * 
 * @param {string} userId - The user ID to check
 * @param {Object} room - The room object to check access for
 * @returns {Promise<boolean>} - Whether the user has access
 */
export const checkRoomAccess = async (userId, room) => {
  // If room doesn't exist or is inactive, no access
  if (!room || !room.isActive) {
    return false;
  }
  
  // Check access level
  switch (room.accessLevel) {
    case RoomAccessLevel.PUBLIC:
      // Anyone can access public rooms
      return true;
      
    case RoomAccessLevel.BASIC:
      // Only registered (non-anonymous) users can access basic rooms
      if (!userId) return false;
      
      // Check if user is anonymous
      const userRef = doc(db, 'users', userId);
      const userSnap = await getDoc(userRef);
      
      if (!userSnap.exists()) return false;
      
      return !userSnap.data().isAnonymous;
      
    case RoomAccessLevel.VIP:
      // Only VIP members can access VIP rooms
      if (!userId) return false;
      
      // Check if user exists
      const vipUserRef = doc(db, 'users', userId);
      const vipUserSnap = await getDoc(vipUserRef);
      
      if (!vipUserSnap.exists()) return false;
      
      const userData = vipUserSnap.data();
      
      // Check directly for isVIP flag first (new implementation)
      if (userData.isVIP === true) {
        return true;
      }
      
      // Otherwise, fall back to legacy VIP access check
      return await hasVipAccess(userId);
      
    default:
      return false;
  }
};

/**
 * Join a chat room
 * 
 * @param {string} roomId - The room ID to join
 * @param {string} userId - The user ID joining the room
 * @param {Object} userData - Additional user data
 * @returns {Promise<boolean>} - Success status
 */
export const joinChatRoom = async (roomId, userId, userData) => {
  if (!roomId || !userId) return false;
  
  try {
    // Get the room
    const room = await getChatRoom(roomId);
    
    // Check if user has access
    const hasAccess = await checkRoomAccess(userId, room);
    
    if (!hasAccess) {
      throw new Error('Access denied');
    }
    
    // Add user to room participants
    const participantRef = doc(db, 'chatRooms', roomId, 'participants', userId);
    
    await setDoc(participantRef, {
      userId,
      displayName: userData.displayName || 'Anonymous',
      photoURL: userData.photoURL || null,
      joinedAt: serverTimestamp(),
      lastActive: serverTimestamp()
    });
    
    // Update room member count
    await updateDoc(doc(db, 'chatRooms', roomId), {
      memberCount: (room.memberCount || 0) + 1,
      updatedAt: serverTimestamp()
    });
    
    return true;
  } catch (error) {
    console.error('Error joining chat room:', error);
    return false;
  }
};

/**
 * Send a message to a chat room
 * 
 * @param {string} roomId - The room ID
 * @param {string} userId - The user ID sending the message
 * @param {string} message - The message content
 * @param {Object} userData - Additional user data
 * @returns {Promise<boolean>} - Success status
 */
export const sendChatMessage = async (roomId, userId, message, userData) => {
  if (!roomId || !userId || !message) return false;
  
  try {
    // Get the room
    const room = await getChatRoom(roomId);
    
    // Check if user has access
    const hasAccess = await checkRoomAccess(userId, room);
    
    if (!hasAccess) {
      throw new Error('Access denied');
    }
    
    // Add message to room
    const messageRef = collection(db, 'chatRooms', roomId, 'messages');
    
    await addDoc(messageRef, {
      userId,
      displayName: userData.displayName || 'Anonymous',
      photoURL: userData.photoURL || null,
      content: message,
      timestamp: serverTimestamp()
    });
    
    // Update room stats
    await updateDoc(doc(db, 'chatRooms', roomId), {
      messageCount: (room.messageCount || 0) + 1,
      lastActivity: serverTimestamp(),
      updatedAt: serverTimestamp()
    });
    
    return true;
  } catch (error) {
    console.error('Error sending chat message:', error);
    return false;
  }
};