// src/pages/UserProfilePage.jsx
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { doc, getDoc, collection, query, where, getDocs, setDoc, deleteDoc, updateDoc, increment } from 'firebase/firestore';
import { db } from '../firebase';
import { useAuth } from '../contexts/AuthContext';
import ActivityFeed from '../components/activity/ActivityFeed';
import ActivityComposer from '../components/activity/ActivityComposer';
import { Users, MessageSquare, Heart, Clock, MapPin, Calendar, Share2, Copy, Settings, Music, QrCode } from 'lucide-react';
import ProfileQRCode from '../components/profile/ProfileQRCode';

const UserProfilePage = () => {
  const { userId } = useParams();
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [userProfile, setUserProfile] = useState(null);
  const [isOwner, setIsOwner] = useState(false);
  const [activityReloadToken, setActivityReloadToken] = useState(0);
  const [isFollowing, setIsFollowing] = useState(false);
  const [followLoading, setFollowLoading] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const [showQRCode, setShowQRCode] = useState(false);
  const [selectedTab, setSelectedTab] = useState('profile');
  const [followersCount, setFollowersCount] = useState(0);
  const [followingCount, setFollowingCount] = useState(0);
  const [activityData, setActivityData] = useState({
    postsCount: 0,
    commentsCount: 0,
    likesGiven: 0,
    likesReceived: 0
  });

  // Fetch user data
  useEffect(() => {
    const fetchUserData = async () => {
      try {
        setLoading(true);
        console.log('Starting to fetch user data...');
        
        // Check if db is initialized
        if (!db) {
          throw new Error('Firebase database not initialized');
        }
        
        // Determine which user to load
        const targetUserId = userId || currentUser?.uid;
        console.log('Target user ID:', targetUserId);
        
        if (!targetUserId) {
          setError("No user ID provided");
          setLoading(false);
          return;
        }
        
        // Fetch user document
        const userRef = doc(db, 'users', targetUserId);
        console.log('Fetching user document...');
        const userDoc = await getDoc(userRef);
        
        if (!userDoc.exists()) {
          console.log('User document does not exist');
          setError("User not found");
          setLoading(false);
          return;
        }
        
        const userData = userDoc.data();
        console.log('User data:', userData);
        
        // Check if the user is an artist - if so, redirect to artist profile
        if (userData.isArtist === true) {
          navigate(`/artist/${targetUserId}`);
          return;
        }
        
        // Create user profile from data
        const profileData = {
          id: userDoc.id,
          uid: userDoc.id,
          displayName: userData.displayName || userData.username || 'User',
          email: userData.email || '',
          profileImageUrl: userData.photoURL || '',
          coverImageUrl: userData.coverImageUrl || '',
          bio: userData.bio || '',
          location: userData.location || '',
          joinedDate: userData.createdAt || null,
          followerCount: userData.followerCount || 0,
          followingCount: userData.followingCount || 0,
          ...userData
        };
        
        console.log('User profile data created:', profileData);
        setUserProfile(profileData);
        setFollowersCount(profileData.followerCount);
        setFollowingCount(profileData.followingCount);
        
        // Check if current user is the profile owner
        if (currentUser && currentUser.uid === profileData.uid) {
          setIsOwner(true);
          
          // Fetch activity data for the owner
          try {
            // This is placeholder - you'd implement actual activity tracking
            setActivityData({
              postsCount: userData.postsCount || 0,
              commentsCount: userData.commentsCount || 0,
              likesGiven: userData.likesGiven || 0,
              likesReceived: userData.likesReceived || 0
            });
          } catch (activityError) {
            console.error('Error fetching activity data:', activityError);
          }
        } else if (currentUser && currentUser.uid !== profileData.uid) {
          // Check if current user is following this user
          const followRef = doc(db, 'follows', `${currentUser.uid}_${profileData.uid}`);
          const followDoc = await getDoc(followRef);
          setIsFollowing(followDoc.exists());
        }
        
        setLoading(false);
      } catch (err) {
        console.error("Error fetching user data:", err);
        console.error("Error details:", err.message);
        console.error("Error stack:", err.stack);
        setError("Failed to load user profile. Please try again.");
        setLoading(false);
      }
    };
    
    fetchUserData();
  }, [userId, currentUser, navigate]);
  
  // Handle follow/unfollow
  const handleFollowToggle = async () => {
    if (!currentUser) {
      navigate('/login', { state: { from: `/people/${userProfile.uid}` } });
      return;
    }
    
    setFollowLoading(true);
    try {
      const followId = `${currentUser.uid}_${userProfile.uid}`;
      const followRef = doc(db, 'follows', followId);
      const userRef = doc(db, 'users', userProfile.uid);
      const currentUserRef = doc(db, 'users', currentUser.uid);
      
      if (isFollowing) {
        // Unfollow
        await deleteDoc(followRef);
        
        // Update follower counts
        await updateDoc(userRef, {
          followerCount: increment(-1)
        });
        await updateDoc(currentUserRef, {
          followingCount: increment(-1)
        });
        
        setIsFollowing(false);
        setFollowersCount(prev => Math.max(0, prev - 1));
      } else {
        // Follow
        await setDoc(followRef, {
          followerId: currentUser.uid,
          followingId: userProfile.uid,
          followerName: currentUser.displayName || currentUser.email,
          followingName: userProfile.displayName,
          createdAt: new Date(),
          type: 'user'
        });
        
        // Update follower counts
        await updateDoc(userRef, {
          followerCount: increment(1)
        });
        await updateDoc(currentUserRef, {
          followingCount: increment(1)
        });
        
        setIsFollowing(true);
        setFollowersCount(prev => prev + 1);
      }
    } catch (err) {
      console.error('Error toggling follow:', err);
      alert('Failed to update follow status. Please try again.');
    } finally {
      setFollowLoading(false);
    }
  };
  
  // Handle share profile
  const handleShareProfile = async () => {
    const profileUrl = `${window.location.origin}/people/${userProfile.uid}`;
    try {
      await navigator.clipboard.writeText(profileUrl);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch (err) {
      console.error('Failed to copy URL:', err);
    }
  };
  
  // Format date
  const formatDate = (timestamp) => {
    if (!timestamp) return 'Unknown';
    const date = timestamp.toDate ? timestamp.toDate() : new Date(timestamp);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };
  
  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading user profile...</p>
      </div>
    );
  }
  
  if (error) {
    return (
      <div className="error-container">
        <h2>Error</h2>
        <p>{error}</p>
        <button onClick={() => navigate('/')} className="back-button">
          Back to Home
        </button>
      </div>
    );
  }
  
  return (
    <div className="user-profile-page">
      {showQRCode && (
        <ProfileQRCode
          url={`${window.location.origin}/people/${userProfile.uid}`}
          name={userProfile.displayName}
          onClose={() => setShowQRCode(false)}
        />
      )}
      {/* Cover Image and Profile Header */}
      <div className="profile-header" style={{ 
        backgroundImage: userProfile.coverImageUrl ? 
          `url(${userProfile.coverImageUrl})` : 
          'linear-gradient(to right, #6366f1, #8b5cf6)' 
      }}>
        <div className="profile-header-content">
          <div className="profile-avatar">
            {userProfile.profileImageUrl ? (
              <img src={userProfile.profileImageUrl} alt={userProfile.displayName} />
            ) : (
              <div className="default-avatar">
                <Users size={48} />
              </div>
            )}
          </div>
          
          <div className="profile-info">
            <h1>{userProfile.displayName}</h1>
            <div className="profile-id-container">
              <p className="profile-id" title={`Share URL: ${window.location.origin}/people/${userProfile.uid}`}>
                User ID: {userProfile.uid}
              </p>
            </div>
            
            {userProfile.location && (
              <p className="profile-location">
                <MapPin size={16} />
                {userProfile.location}
              </p>
            )}
            
            <div className="profile-stats">
              <div className="stat">
                <Users size={16} />
                <span>{followersCount} followers</span>
              </div>
              <div className="stat">
                <Heart size={16} />
                <span>{followingCount} following</span>
              </div>
              <div className="stat">
                <Calendar size={16} />
                <span>Joined {formatDate(userProfile.joinedDate)}</span>
              </div>
            </div>
            
            <div className="profile-actions">
              {!isOwner && (
                <button 
                  className={`follow-button ${isFollowing ? 'following' : ''}`}
                  onClick={handleFollowToggle}
                  disabled={followLoading}
                >
                  {followLoading ? (
                    <span>Loading...</span>
                  ) : isFollowing ? (
                    <>
                      <Users size={16} />
                      Following
                    </>
                  ) : (
                    <>
                      <Users size={16} />
                      Follow
                    </>
                  )}
                </button>
              )}
              <button className="share-button" onClick={handleShareProfile}>
                {copySuccess ? (
                  <>
                    <Copy size={16} />
                    Copied!
                  </>
                ) : (
                  <>
                    <Share2 size={16} />
                    Share Profile
                  </>
                )}
              </button>
              <button className="share-button" onClick={() => setShowQRCode(true)}>
                <QrCode size={16} />
                QR Code
              </button>
            </div>
            
            {isOwner && (
              <div className="owner-actions">
                <Link to="/edit-profile" className="edit-profile-button">
                  <Settings size={16} />
                  Edit Profile
                </Link>
              </div>
            )}
          </div>
        </div>
      </div>
      
      {/* Navigation Tabs */}
      <div className="profile-tabs">
        <button 
          className={`tab-button ${selectedTab === 'profile' ? 'active' : ''}`}
          onClick={() => setSelectedTab('profile')}
        >
          Profile
        </button>
        <button 
          className={`tab-button ${selectedTab === 'activity' ? 'active' : ''}`}
          onClick={() => setSelectedTab('activity')}
        >
          Activity
        </button>
        <button 
          className={`tab-button ${selectedTab === 'followers' ? 'active' : ''}`}
          onClick={() => setSelectedTab('followers')}
        >
          Connections
        </button>
      </div>
      
      {/* Tab Content */}
      <div className="tab-content">
        {/* Profile Tab */}
        {selectedTab === 'profile' && (
          <div className="profile-content">
            <div className="profile-section">
              <h2>About</h2>
              <p className="user-bio">{userProfile.bio || 'This user hasn\'t added a bio yet.'}</p>
            </div>
            
            {userProfile.interests && userProfile.interests.length > 0 && (
              <div className="profile-section">
                <h2>Interests</h2>
                <div className="interests-list">
                  {userProfile.interests.map((interest, index) => (
                    <span key={index} className="interest-tag">{interest}</span>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
        
        {/* Activity Tab */}
        {selectedTab === 'activity' && (
          <div className="activity-content">
            <h2>Recent Activity</h2>
            
            <div className="activity-cards">
              <div className="activity-card">
                <div className="activity-icon">
                  <MessageSquare size={24} />
                </div>
                <div className="activity-data">
                  <span className="activity-value">{activityData.postsCount}</span>
                  <span className="activity-label">Posts</span>
                </div>
              </div>
              
              <div className="activity-card">
                <div className="activity-icon">
                  <MessageSquare size={24} />
                </div>
                <div className="activity-data">
                  <span className="activity-value">{activityData.commentsCount}</span>
                  <span className="activity-label">Comments</span>
                </div>
              </div>
              
              <div className="activity-card">
                <div className="activity-icon">
                  <Heart size={24} />
                </div>
                <div className="activity-data">
                  <span className="activity-value">{activityData.likesGiven}</span>
                  <span className="activity-label">Likes Given</span>
                </div>
              </div>
              
              <div className="activity-card">
                <div className="activity-icon">
                  <Heart size={24} />
                </div>
                <div className="activity-data">
                  <span className="activity-value">{activityData.likesReceived}</span>
                  <span className="activity-label">Likes Received</span>
                </div>
              </div>
            </div>
            
            <div className="activity-section">
              {isOwner && (
                <ActivityComposer onPosted={() => setActivityReloadToken(t => t + 1)} />
              )}
              <ActivityFeed
                userId={userProfile.uid}
                isOwner={isOwner}
                reloadToken={activityReloadToken}
              />
            </div>
          </div>
        )}
        
        {/* Followers Tab */}
        {selectedTab === 'followers' && (
          <div className="followers-content">
            <h2>Connections</h2>
            <p className="coming-soon">Followers and following lists coming soon...</p>
          </div>
        )}
      </div>
      
      <style jsx>{`
        .user-profile-page {
          max-width: 1200px;
          margin: 0 auto;
          padding-bottom: 3rem;
        }
        
        .profile-header {
          width: 100%;
          height: 300px;
          background-size: cover;
          background-position: center;
          position: relative;
          color: white;
        }
        
        .profile-header::before {
          content: '';
          position: absolute;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: linear-gradient(to bottom, rgba(0,0,0,0.1), rgba(0,0,0,0.7));
        }
        
        .profile-header-content {
          position: relative;
          z-index: 1;
          display: flex;
          align-items: flex-end;
          padding: 2rem;
          height: 100%;
        }
        
        .profile-avatar {
          width: 150px;
          height: 150px;
          border-radius: 50%;
          overflow: hidden;
          border: 4px solid white;
          margin-right: 2rem;
          flex-shrink: 0;
          background-color: #6366f1;
          display: flex;
          align-items: center;
          justify-content: center;
        }
        
        .profile-avatar img {
          width: 100%;
          height: 100%;
          object-fit: cover;
        }
        
        .default-avatar {
          color: white;
        }
        
        .profile-info {
          flex-grow: 1;
        }
        
        .profile-info h1 {
          font-size: 2.5rem;
          margin: 0 0 0.5rem 0;
          text-shadow: 1px 1px 3px rgba(0,0,0,0.5);
        }
        
        .profile-id-container {
          margin: 0 0 0.5rem 0;
        }
        
        .profile-id {
          font-size: 0.9rem;
          opacity: 0.7;
          font-family: monospace;
          display: inline-block;
          cursor: help;
        }
        
        .profile-id:hover {
          opacity: 0.9;
        }
        
        .profile-location {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          font-size: 1.1rem;
          margin: 0 0 1rem 0;
          opacity: 0.9;
        }
        
        .profile-stats {
          display: flex;
          gap: 1.5rem;
          margin-bottom: 1.5rem;
        }
        
        .stat {
          display: flex;
          align-items: center;
          gap: 0.5rem;
        }
        
        .profile-actions {
          display: flex;
          gap: 1rem;
          margin-bottom: 1rem;
        }
        
        .follow-button,
        .share-button {
          display: inline-flex;
          align-items: center;
          gap: 0.5rem;
          padding: 0.75rem 1.5rem;
          border-radius: 50px;
          font-weight: 600;
          cursor: pointer;
          transition: all 0.2s;
          border: none;
        }
        
        .follow-button {
          background-color: #6366f1;
          color: white;
        }
        
        .follow-button:hover:not(:disabled) {
          background-color: #4f46e5;
        }
        
        .follow-button.following {
          background-color: #059669;
        }
        
        .follow-button.following:hover:not(:disabled) {
          background-color: #dc2626;
        }
        
        .follow-button:disabled {
          opacity: 0.5;
          cursor: not-allowed;
        }
        
        .share-button {
          background-color: rgba(255, 255, 255, 0.2);
          color: white;
          border: 1px solid white;
        }
        
        .share-button:hover {
          background-color: rgba(255, 255, 255, 0.3);
        }
        
        .owner-actions {
          display: flex;
          gap: 1rem;
        }
        
        .edit-profile-button {
          display: inline-flex;
          align-items: center;
          gap: 0.5rem;
          padding: 0.75rem 1.5rem;
          border-radius: 50px;
          font-weight: 600;
          text-decoration: none;
          transition: all 0.2s;
          background-color: rgba(255, 255, 255, 0.2);
          color: white;
          border: 1px solid white;
        }
        
        .edit-profile-button:hover {
          background-color: rgba(255, 255, 255, 0.3);
        }
        
        .profile-tabs {
          display: flex;
          border-bottom: 1px solid #e5e7eb;
          background-color: white;
          position: sticky;
          top: 60px;
          z-index: 10;
        }
        
        .tab-button {
          padding: 1rem 1.5rem;
          background: none;
          border: none;
          font-weight: 500;
          color: #4b5563;
          cursor: pointer;
          border-bottom: 2px solid transparent;
        }
        
        .tab-button.active {
          color: #6366f1;
          border-bottom-color: #6366f1;
        }
        
        .tab-content {
          padding: 2rem;
          background-color: white;
          min-height: 400px;
        }
        
        /* Profile Tab Styles */
        .profile-content {
          max-width: 800px;
        }
        
        .profile-section {
          margin-bottom: 2.5rem;
        }
        
        .profile-section h2 {
          font-size: 1.5rem;
          margin-bottom: 1rem;
          color: #111827;
        }
        
        .user-bio {
          font-size: 1.05rem;
          line-height: 1.6;
          color: #4b5563;
        }
        
        .interests-list {
          display: flex;
          flex-wrap: wrap;
          gap: 0.75rem;
        }
        
        .interest-tag {
          background-color: #eff6ff;
          color: #3730a3;
          padding: 0.5rem 1rem;
          border-radius: 20px;
          font-size: 0.9rem;
        }
        
        /* Activity Tab Styles */
        .activity-content h2 {
          font-size: 1.5rem;
          margin-bottom: 1.5rem;
          color: #111827;
        }
        
        .activity-cards {
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
          gap: 1.5rem;
          margin-bottom: 2.5rem;
        }
        
        .activity-card {
          background-color: #f9fafb;
          border-radius: 8px;
          padding: 1.5rem;
          display: flex;
          align-items: center;
          gap: 1rem;
        }
        
        .activity-icon {
          width: 48px;
          height: 48px;
          background-color: #e0e7ff;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          color: #6366f1;
          flex-shrink: 0;
        }
        
        .activity-data {
          display: flex;
          flex-direction: column;
        }
        
        .activity-value {
          font-size: 1.5rem;
          font-weight: 700;
          color: #111827;
        }
        
        .activity-label {
          font-size: 0.9rem;
          color: #6b7280;
        }
        
        .activity-section {
          margin-top: 2rem;
        }
        
        .no-activity {
          text-align: center;
          color: #6b7280;
          padding: 3rem;
          background-color: #f9fafb;
          border-radius: 8px;
        }
        
        /* Followers Tab Styles */
        .followers-content h2 {
          font-size: 1.5rem;
          margin-bottom: 1.5rem;
          color: #111827;
        }
        
        .coming-soon {
          text-align: center;
          color: #6b7280;
          padding: 3rem;
          background-color: #f9fafb;
          border-radius: 8px;
        }
        
        /* Loading and Error Styles */
        .loading-container {
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          min-height: 400px;
          text-align: center;
          color: #6b7280;
        }
        
        .loading-spinner {
          width: 40px;
          height: 40px;
          border: 4px solid rgba(99, 102, 241, 0.2);
          border-radius: 50%;
          border-top-color: #6366f1;
          animation: spin 1s linear infinite;
          margin-bottom: 1rem;
        }
        
        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
        
        .error-container {
          padding: 2rem;
          max-width: 600px;
          margin: 2rem auto;
          text-align: center;
          background-color: #fee2e2;
          border-radius: 8px;
          color: #b91c1c;
        }
        
        .error-container h2 {
          margin-bottom: 1rem;
        }
        
        .back-button {
          background-color: #ef4444;
          color: white;
          border: none;
          padding: 0.75rem 1.5rem;
          border-radius: 6px;
          font-weight: 500;
          cursor: pointer;
          margin-top: 1.5rem;
          transition: all 0.2s;
        }
        
        .back-button:hover {
          background-color: #dc2626;
        }
        
        /* Responsive Styles */
        @media (max-width: 768px) {
          .profile-header-content {
            flex-direction: column;
            align-items: center;
            text-align: center;
          }
          
          .profile-avatar {
            margin-right: 0;
            margin-bottom: 1.5rem;
          }
          
          .profile-tabs {
            overflow-x: auto;
          }
          
          .tab-button {
            padding: 1rem;
            white-space: nowrap;
          }
          
          .tab-content {
            padding: 1.5rem;
          }
          
          .activity-cards {
            grid-template-columns: 1fr;
          }
        }
      `}</style>
    </div>
  );
};

export default UserProfilePage;