// src/services/cutStore.js
//
// Saved "cuts" — the recipe for a sketch you liked, so you can bring it back
// note for note.
//
// This works because the composer is fully deterministic: the same seeds and
// settings always yield the same song. So a cut doesn't store any audio or
// even any notes, just the handful of values that produced them. A saved cut
// is a few dozen bytes and recalls exactly, including the melody.
//
//   saveCut(recipeFromSong(song));
//   listCuts().forEach(c => ...);   // newest first

const STORAGE_KEY = 'jamstudio:cuts';
const MAX_CUTS = 24;

/** The complete set of inputs that determine a song. */
export function recipeFromSong(song) {
  return {
    style: song.style,
    keyName: song.keyName,
    scaleName: song.scaleName,
    tempo: song.tempo,
    bars: song.bars,
    seed: song.seed,
    melodySeed: song.melodySeed,
    lead: song.lead,
    arrangement: song.arrangement || 'loop',
  };
}

function read() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch (_) {
    return [];
  }
}

function write(cuts) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(cuts.slice(0, MAX_CUTS)));
  } catch (_) { /* storage full or blocked — the studio still works */ }
}

/** Saved cuts, newest first. */
export function listCuts() {
  return read();
}

/** A short label that says what the cut is at a glance. */
export function describeCut(recipe, styleLabel) {
  const minor = /minor|dorian|phrygian|harmonic/.test(recipe.scaleName) ? 'm' : '';
  return `${styleLabel || recipe.style} · ${recipe.keyName}${minor} · ${recipe.tempo}`;
}

export function saveCut(recipe, name) {
  const cuts = read();
  const cut = {
    id: `cut-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
    name: name || '',
    savedAt: Date.now(),
    ...recipe,
  };
  // Saving the same recipe twice is a no-op rather than a duplicate button.
  const same = cuts.find(c =>
    c.style === cut.style && c.keyName === cut.keyName && c.scaleName === cut.scaleName &&
    c.tempo === cut.tempo && c.bars === cut.bars &&
    c.seed === cut.seed && c.melodySeed === cut.melodySeed);
  if (same) return same;

  const next = [cut, ...cuts];
  write(next);
  return cut;
}

export function deleteCut(id) {
  write(read().filter(c => c.id !== id));
}

export function renameCut(id, name) {
  write(read().map(c => (c.id === id ? { ...c, name } : c)));
}

export default { listCuts, saveCut, deleteCut, renameCut, recipeFromSong, describeCut };
