// Context signal taxonomy — tailored to real-estate dealmaker focus.
//
// A context signal is a slow-moving reference datum (weekly/monthly/yearly)
// displayed on PredictionDetail's Context panel. Unlike `inputs[]`, these are
// NOT sentiment-weighted into outcome probabilities in v1 — they're for
// grounding the reader in objective indicators.
//
// Tag format: 'category.metric[.scope]'
//   category = one of CONTEXT_CATEGORIES keys
//   metric   = snake_case metric slug
//   scope    = optional — 'national' or a metro slug matching mockData marketTags
//
// Examples:
//   rates.ten_year
//   labor.unemployment.national
//   labor.unemployment.denver
//   demographics.population.phoenix
//
// Predictions opt in via Prediction.contextTags = [...].

import {
  TrendingUp, Briefcase, Users, Home, HardHat, Wind, HeartPulse, ShieldAlert,
} from 'lucide-react'

export const CONTEXT_CATEGORIES = {
  rates: {
    id: 'rates',
    label: 'Rates & Inflation',
    icon: TrendingUp,
    color: 'emerald',
    description: 'Treasury yields, Fed funds, CPI, SOFR — the cost of capital.',
  },
  labor: {
    id: 'labor',
    label: 'Labor',
    icon: Briefcase,
    color: 'sky',
    description: 'Employment, unemployment, wage growth by metro (BLS).',
  },
  demographics: {
    id: 'demographics',
    label: 'Demographics',
    icon: Users,
    color: 'violet',
    description: 'Population, households, migration (Census ACS).',
  },
  housing: {
    id: 'housing',
    label: 'Housing',
    icon: Home,
    color: 'amber',
    description: 'Cap rates, rents, vacancy, homeownership (CoStar/Census).',
  },
  construction: {
    id: 'construction',
    label: 'Construction',
    icon: HardHat,
    color: 'orange',
    description: 'Starts, completions, cost indices (Census/BLS/ENR).',
  },
  climate: {
    id: 'climate',
    label: 'Climate & Environment',
    icon: Wind,
    color: 'cyan',
    description: 'Air quality, disaster declarations, insurance risk (EPA/FEMA).',
  },
  health: {
    id: 'health',
    label: 'Public Health',
    icon: HeartPulse,
    color: 'rose',
    description: 'Chronic disease prevalence, mental health, access to care (CDC PLACES).',
  },
  safety: {
    id: 'safety',
    label: 'Safety & Crime',
    icon: ShieldAlert,
    color: 'yellow',
    description: 'Violent and property crime rates (FBI Crime Data Explorer).',
  },
}

// Parse a tag string into its parts. Returns null if malformed.
export function parseContextTag(tag) {
  if (typeof tag !== 'string' || !tag.includes('.')) return null
  const [category, metric, scope = null] = tag.split('.')
  if (!CONTEXT_CATEGORIES[category]) return null
  return { category, metric, scope, raw: tag }
}

// Group an array of ContextSignal objects by their category.
// Returns { [categoryId]: ContextSignal[] } in CONTEXT_CATEGORIES key order.
export function groupSignalsByCategory(signals) {
  const groups = {}
  for (const id of Object.keys(CONTEXT_CATEGORIES)) groups[id] = []
  for (const s of signals) {
    if (groups[s.category]) groups[s.category].push(s)
  }
  // Strip empty categories so consumers can just iterate entries
  return Object.fromEntries(Object.entries(groups).filter(([, v]) => v.length > 0))
}

export function getCategory(categoryId) {
  return CONTEXT_CATEGORIES[categoryId] || null
}
