// src/components/debug/FirebasePerformanceDebugger.jsx
import React, { useState, useEffect } from 'react';
import { getAllTimings, clearTimings, createTimingContext } from '../../firebase/performance-init';

/**
 * Component for debugging Firebase Performance issues
 * Displays active traces and provides controls to manage them
 */
const FirebasePerformanceDebugger = () => {
  const [activeTraces, setActiveTraces] = useState([]);
  const [showDebugger, setShowDebugger] = useState(false);
  const [testStatus, setTestStatus] = useState(null);

  // Refresh the list of active traces
  const refreshTraces = () => {
    setActiveTraces(getAllTimings());
  };

  // Clear all active traces
  const handleClearTraces = () => {
    clearTimings();
    refreshTraces();
  };

  // Run a test trace
  const runTestTrace = async () => {
    setTestStatus('running');
    
    // Create a timing context for the test
    const timing = createTimingContext('debugger-test-trace');
    
    try {
      // Simulate some async work
      await new Promise(resolve => setTimeout(resolve, 2000));
      
      // End the trace
      const elapsed = timing.done();
      
      setTestStatus(`completed in ${elapsed}ms`);
      refreshTraces();
    } catch (error) {
      setTestStatus(`error: ${error.message}`);
    }
  };

  // Toggle the debugger visibility
  const toggleDebugger = () => {
    setShowDebugger(prev => !prev);
    if (!showDebugger) {
      refreshTraces();
    }
  };

  // Refresh traces when the debugger is shown
  useEffect(() => {
    if (showDebugger) {
      refreshTraces();
      
      // Set up periodic refresh
      const interval = setInterval(refreshTraces, 5000);
      
      return () => clearInterval(interval);
    }
  }, [showDebugger]);

  // Render a minimal button when collapsed
  if (!showDebugger) {
    return (
      <button
        onClick={toggleDebugger}
        className="fixed bottom-4 right-4 bg-indigo-600 text-white px-4 py-2 rounded-md shadow-md hover:bg-indigo-700 transition-colors"
      >
        Debug Performance
      </button>
    );
  }

  return (
    <div className="fixed bottom-4 right-4 w-96 max-h-96 bg-white rounded-md shadow-lg border border-gray-200 overflow-hidden">
      <div className="bg-indigo-600 text-white px-4 py-2 flex justify-between items-center">
        <h3 className="font-medium">Firebase Performance Debugger</h3>
        <button 
          onClick={toggleDebugger}
          className="text-white hover:text-gray-200"
        >
          ✕
        </button>
      </div>
      
      <div className="p-4 overflow-y-auto max-h-72">
        <div className="flex space-x-2 mb-4">
          <button
            onClick={refreshTraces}
            className="bg-gray-100 hover:bg-gray-200 text-gray-800 px-3 py-1 rounded text-sm"
          >
            Refresh
          </button>
          <button
            onClick={handleClearTraces}
            className="bg-red-100 hover:bg-red-200 text-red-800 px-3 py-1 rounded text-sm"
          >
            Clear All
          </button>
          <button
            onClick={runTestTrace}
            className="bg-green-100 hover:bg-green-200 text-green-800 px-3 py-1 rounded text-sm"
          >
            Test Trace
          </button>
        </div>
        
        {testStatus && (
          <div className={`mb-4 p-2 rounded text-sm ${
            testStatus === 'running' 
              ? 'bg-yellow-100 text-yellow-800' 
              : testStatus.startsWith('error') 
                ? 'bg-red-100 text-red-800'
                : 'bg-green-100 text-green-800'
          }`}>
            Test trace: {testStatus}
          </div>
        )}
        
        <h4 className="font-medium mb-2">Active Traces ({activeTraces.length})</h4>
        
        {activeTraces.length === 0 ? (
          <p className="text-gray-500 text-sm">No active traces</p>
        ) : (
          <ul className="bg-gray-50 rounded p-2">
            {activeTraces.map((traceName, index) => (
              <li key={index} className="text-sm py-1 border-b border-gray-100 last:border-0">
                {traceName}
              </li>
            ))}
          </ul>
        )}
        
        <div className="mt-4">
          <h4 className="font-medium mb-2">Troubleshooting</h4>
          <ul className="text-xs text-gray-600 list-disc pl-4">
            <li>If traces are not stopping, use "Clear All"</li>
            <li>Run "Test Trace" to verify monitoring works</li>
            <li>Check console for Firebase Performance errors</li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default FirebasePerformanceDebugger;
