// src/services/CreditsService.js
//
// Thin client wrapper for buying Credit Packs and reading the user's balance.
// Subscriptions live in StripeService.js; this module is credits-only to keep
// the one-time purchase flow architecturally distinct from recurring billing.

import { getFunctions, httpsCallable } from 'firebase/functions';
import { doc, onSnapshot, getDoc, getFirestore } from 'firebase/firestore';

/** Raised by spendCredits when the user can't cover the cost. */
export class InsufficientCreditsError extends Error {
  constructor(required, available) {
    super(`Need ${required} credits but only ${available} available.`);
    this.name = 'InsufficientCreditsError';
    this.code = 'insufficient-credits';
    this.required = required;
    this.available = available;
  }
}

/**
 * Available credit packs — keep in sync with scripts/stripe-bootstrap.sh
 * CREDIT_PACKS and src/cloud-functions/stripe/priceMap.js KNOWN_CREDIT_PACKS.
 * `creditsGranted` and `amountCents` are display-only here; the backend
 * re-resolves them from Stripe to prevent tampering.
 */
export const CREDIT_PACKS = [
  { id: 'credits_10',  label: '$10',  priceUsd: 10,  creditsGranted: 1000,  bonusPct: 0,  tagline: 'Try it out' },
  { id: 'credits_25',  label: '$25',  priceUsd: 25,  creditsGranted: 2750,  bonusPct: 10, tagline: '+10% bonus' },
  { id: 'credits_50',  label: '$50',  priceUsd: 50,  creditsGranted: 6000,  bonusPct: 20, tagline: '+20% bonus · most popular' },
  { id: 'credits_100', label: '$100', priceUsd: 100, creditsGranted: 13000, bonusPct: 30, tagline: '+30% bonus · best value' },
];

/**
 * Start a Stripe Checkout session for a one-time Credits pack purchase.
 * Redirects the current page to Stripe on success.
 * @param {'credits_10'|'credits_25'|'credits_50'|'credits_100'} packId
 */
export async function buyCreditPack(packId) {
  const fn = httpsCallable(getFunctions(), 'createCreditCheckoutSession');
  const { data } = await fn({ packId });
  if (!data?.url) throw new Error('Checkout session missing URL');
  window.location.href = data.url;
}

/**
 * Subscribe to the user's credit balance. Returns the unsubscribe function.
 * @param {string} userId
 * @param {(balance: number) => void} onChange
 */
export function watchCreditBalance(userId, onChange) {
  if (!userId) return () => {};
  const db = getFirestore();
  return onSnapshot(doc(db, 'users', userId), (snap) => {
    const balance = snap.exists() ? (snap.data()?.credits?.balance ?? 0) : 0;
    onChange(balance);
  });
}

/**
 * One-shot read of the current balance.
 */
export async function getCreditBalance(userId) {
  if (!userId) return 0;
  const db = getFirestore();
  const snap = await getDoc(doc(db, 'users', userId));
  return snap.exists() ? (snap.data()?.credits?.balance ?? 0) : 0;
}

/**
 * Spend credits from the user's balance via the `spendCredits` Cloud Function.
 *
 * The debit is performed server-side: the callable resolves the cost from its
 * own authoritative SPEND_ACTIONS table (the client only names an action — it
 * cannot choose the amount) and decrements the same
 * `users/{uid}.credits.balance` the Stripe webhook grants into, inside a
 * Firestore transaction. This is tamper-resistant: Firestore security rules
 * can forbid clients from writing `credits.*` directly, leaving this function
 * (which runs with admin privileges) as the only debit path.
 *
 * @param {string} action            Action key, e.g. 'predict.submit' | 'predict.vote'.
 * @param {object} [meta]            Optional context stored on the ledger entry.
 * @param {string|null} [idempotencyKey]  Optional stable key (e.g. a prediction
 *                                   id) so a double-click can't double-charge.
 * @returns {Promise<number>} The new balance after the deduction.
 * @throws {InsufficientCreditsError} when the balance can't cover the cost.
 */
export async function spendCredits(action, meta = {}, idempotencyKey = null) {
  if (!action) throw new Error('spendCredits: missing action');
  const fn = httpsCallable(getFunctions(), 'spendCredits');
  try {
    const { data } = await fn({ action, meta, idempotencyKey });
    return data?.balance ?? null;
  } catch (err) {
    // The callable throws HttpsError('resource-exhausted', ..., { required, available })
    // when the balance is too low; surface it as our typed error.
    const code = err?.code || '';
    const details = err?.details || null;
    if (code === 'functions/resource-exhausted' || (details && details.required != null)) {
      throw new InsufficientCreditsError(details?.required, details?.available);
    }
    throw err;
  }
}

export default {
  CREDIT_PACKS,
  buyCreditPack,
  watchCreditBalance,
  getCreditBalance,
  spendCredits,
  InsufficientCreditsError,
};
