// src/components/widgets/AnnouncementsWidget.jsx
import React, { useState, useEffect } from 'react';
import { 
  getDB, 
  collection, 
  query, 
  orderBy, 
  limit, 
  onSnapshot 
} from '../../utils/firebase-utils';
import { useAuth } from '../../contexts/AuthContext';
import { Heart, MessageCircle } from 'lucide-react';
import LikeService from '../../services/LikeService';
import './AnnouncementsWidget.css';

const AnnouncementsWidget = ({ onAnnouncementClick, limit: itemLimit = 5 }) => {
  const [announcements, setAnnouncements] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [likedAnnouncements, setLikedAnnouncements] = useState({});
  const [processingLikes, setProcessingLikes] = useState({});
  const [showCommentModal, setShowCommentModal] = useState(false);
  const [selectedAnnouncementForComment, setSelectedAnnouncementForComment] = useState(null);
  const [commentText, setCommentText] = useState('');
  const [submittingComment, setSubmittingComment] = useState(false);
  const { currentUser } = useAuth();
  
  useEffect(() => {
    // Get db instance using the utility function to ensure proper region handling
    const db = getDB();
    if (!db) {
      console.error('Firestore database not available');
      setError('Database connection failed. Please try again later.');
      setLoading(false);
      return () => {};
    }
    
    console.log('Setting up announcements subscription');
    
    try {
      // Create a query for the 'announcements' collection directly at the root
      // This path matches what's seen in the Firebase console
      const announcementsCollection = collection(db, 'announcements');
      const announcementsQuery = query(
        announcementsCollection,
        orderBy('createdAt', 'desc'),
        limit(itemLimit)
      );
      
      // Set up real-time listener with error handling
      const unsubscribe = onSnapshot(
        announcementsQuery,
        (querySnapshot) => {
          const announcementsList = [];
          querySnapshot.forEach((doc) => {
            announcementsList.push({
              id: doc.id,
              ...doc.data(),
              // Handle potential missing or invalid dates
              createdAt: doc.data().createdAt ? 
                (doc.data().createdAt.toDate ? doc.data().createdAt.toDate() : doc.data().createdAt) : 
                new Date(),
              // Include image URLs if they exist
              imageUrls: doc.data().imageUrls || [],
              likesCount: doc.data().likesCount || 0,
              commentCount: doc.data().commentCount || 0
            });
          });
          
          console.log('Announcements loaded:', announcementsList.length);
          setAnnouncements(announcementsList);
          setLoading(false);
          setError(null);
        },
        (err) => {
          console.error('Error getting announcements:', err);
          
          // Provide fallback data for permission issues
          const fallbackAnnouncements = [
            {
              id: 'welcome-1',
              title: 'Welcome to TalkStudio',
              content: 'Join our community and start conversations with others. Explore chat rooms, create posts, and connect with users around the world.',
              createdAt: new Date(),
              authorName: 'System',
              imageUrls: [],
              likesCount: 0,
              commentCount: 0
            },
            {
              id: 'getting-started-1',
              title: 'Getting Started Guide',
              content: 'Check out our quick start guide to learn how to create your first post, join a chat room, and customize your profile settings.',
              createdAt: new Date(Date.now() - 86400000), // 1 day ago
              authorName: 'System',
              imageUrls: [],
              likesCount: 0,
              commentCount: 0
            },
            {
              id: 'launch-announce',
              title: 'Launch Announce',
              content: 'We are officially launching on April 24th. This will be our launch date here at talkStudio, I hope you enjoy the platform!',
              createdAt: new Date('2023-04-21T11:34:09'),
              authorName: 'Tom Bermbroeder',
              imageUrls: [],
              likesCount: 0,
              commentCount: 0
            }
          ];
          
          setAnnouncements(fallbackAnnouncements);
          setError(null); // Don't show error to user since we have fallback data
          setLoading(false);
        }
      );
      
      // Clean up the subscription when the component unmounts
      return () => unsubscribe();
    } catch (err) {
      console.error('Error setting up announcements subscription:', err);
      setError(`Failed to set up announcements subscription: ${err.message}`);
      setLoading(false);
      return () => {};
    }
  }, [itemLimit]);
  
  // Check liked status for all announcements when user or announcements change
  useEffect(() => {
    const checkLikedStatus = async () => {
      if (!currentUser || announcements.length === 0) return;
      
      const likedStatus = {};
      for (const announcement of announcements) {
        try {
          // Using the same service but with announcement ID
          const isLiked = await LikeService.isPostLiked(announcement.id);
          likedStatus[announcement.id] = isLiked;
        } catch (error) {
          console.error('Error checking like status for announcement:', announcement.id, error);
          likedStatus[announcement.id] = false;
        }
      }
      setLikedAnnouncements(likedStatus);
    };
    
    checkLikedStatus();
  }, [currentUser, announcements]);
  
  // Function to format dates
  const formatDate = (date) => {
    if (!date) return 'Unknown date';
    
    try {
      // Handle both Date objects and Firestore timestamps
      const dateObj = date instanceof Date ? date : 
                     (date.toDate ? date.toDate() : new Date(date));
      
      return new Intl.DateTimeFormat('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric'
      }).format(dateObj);
    } catch (err) {
      console.error('Error formatting date:', err);
      return 'Invalid date';
    }
  };
  
  // Function to handle announcement click
  const handleAnnouncementClick = (announcement) => {
    if (onAnnouncementClick) {
      onAnnouncementClick(announcement);
    }
  };
  
  // Function to handle like toggle
  const handleLikeToggle = async (e, announcementId) => {
    e.stopPropagation(); // Prevent triggering announcement click
    
    if (!currentUser) {
      alert('Please log in to like announcements');
      return;
    }
    
    if (processingLikes[announcementId]) return;
    
    try {
      setProcessingLikes(prev => ({ ...prev, [announcementId]: true }));
      
      // Optimistic UI update
      const currentlyLiked = likedAnnouncements[announcementId];
      setLikedAnnouncements(prev => ({ ...prev, [announcementId]: !currentlyLiked }));
      
      // Update likes count optimistically
      setAnnouncements(prevAnnouncements => 
        prevAnnouncements.map(announcement => 
          announcement.id === announcementId 
            ? { ...announcement, likesCount: currentlyLiked ? announcement.likesCount - 1 : announcement.likesCount + 1 }
            : announcement
        )
      );
      
      // Call the like service (it works for both posts and announcements)
      const result = await LikeService.togglePostLike(announcementId);
      
      // Update with actual result from server
      setLikedAnnouncements(prev => ({ ...prev, [announcementId]: result.liked }));
      setAnnouncements(prevAnnouncements => 
        prevAnnouncements.map(announcement => 
          announcement.id === announcementId 
            ? { ...announcement, likesCount: result.likesCount }
            : announcement
        )
      );
    } catch (error) {
      console.error('Error toggling like:', error);
      // Revert on error
      setLikedAnnouncements(prev => ({ ...prev, [announcementId]: !likedAnnouncements[announcementId] }));
      alert('Failed to update like status. Please try again.');
    } finally {
      setProcessingLikes(prev => ({ ...prev, [announcementId]: false }));
    }
  };
  
  // Function to handle comment button click
  const handleCommentClick = (e, announcement) => {
    e.stopPropagation();
    
    if (!currentUser) {
      alert('Please log in to comment on announcements');
      return;
    }
    
    setSelectedAnnouncementForComment(announcement);
    setShowCommentModal(true);
    setCommentText('');
  };
  
  // Function to submit comment
  const handleCommentSubmit = async () => {
    if (!commentText.trim() || !selectedAnnouncementForComment || submittingComment) return;
    
    try {
      setSubmittingComment(true);
      
      // Import CommentService dynamically
      const CommentService = (await import('../../services/CommentService')).default;
      
      // Add comment (using the same service as posts)
      await CommentService.addComment(selectedAnnouncementForComment.id, commentText.trim());
      
      // Update comment count
      setAnnouncements(prevAnnouncements => 
        prevAnnouncements.map(announcement => 
          announcement.id === selectedAnnouncementForComment.id 
            ? { ...announcement, commentCount: (announcement.commentCount || 0) + 1 }
            : announcement
        )
      );
      
      // Close modal and reset
      setShowCommentModal(false);
      setSelectedAnnouncementForComment(null);
      setCommentText('');
    } catch (error) {
      console.error('Error adding comment:', error);
      alert('Failed to add comment. Please try again.');
    } finally {
      setSubmittingComment(false);
    }
  };
  
  // Function to truncate text
  const truncateText = (text, maxLength = 100) => {
    if (!text) return '';
    if (text.length <= maxLength) return text;
    return text.substring(0, maxLength) + '...';
  };
  
  if (loading) {
    return (
      <div className="announcements-widget">
        <div className="loading-indicator">
          Loading announcements...
        </div>
      </div>
    );
  }
  
  if (error) {
    return (
      <div className="announcements-widget error">
        <div className="error-message">
          {error}
        </div>
      </div>
    );
  }
  
  if (announcements.length === 0) {
    return (
      <div className="announcements-widget empty">
        <p>No announcements available.</p>
      </div>
    );
  }
  
  return (
    <div className="announcements-widget">
      <ul className="announcements-list">
        {announcements.map((announcement) => (
          <li 
            key={announcement.id} 
            className="announcement-item"
            onClick={() => handleAnnouncementClick(announcement)}
          >
            <div className="announcement-header">
              <h3 className="announcement-title">{announcement.title}</h3>
              <span className="announcement-date">
                {formatDate(announcement.createdAt)}
              </span>
            </div>
            <div className="announcement-preview">
              {announcement.content && announcement.content.length > 100 
                ? `${announcement.content.substring(0, 100)}...` 
                : announcement.content}
            </div>
            
            {/* Display images if available */}
            {announcement.imageUrls && announcement.imageUrls.length > 0 && (
              <div className="announcement-images">
                {announcement.imageUrls.slice(0, 2).map((imageUrl, index) => (
                  <img 
                    key={index}
                    src={imageUrl} 
                    alt={`Announcement image ${index + 1}`}
                    className="announcement-image-thumbnail"
                    onClick={(e) => e.stopPropagation()}
                  />
                ))}
                {announcement.imageUrls.length > 2 && (
                  <div className="more-images">+{announcement.imageUrls.length - 2}</div>
                )}
              </div>
            )}
            
            <div className="announcement-meta">
              <button 
                className={`like-button ${likedAnnouncements[announcement.id] ? 'liked' : ''}`}
                onClick={(e) => handleLikeToggle(e, announcement.id)}
                disabled={processingLikes[announcement.id]}
              >
                <Heart 
                  size={16} 
                  fill={likedAnnouncements[announcement.id] ? '#ef4444' : 'none'}
                  color={likedAnnouncements[announcement.id] ? '#ef4444' : '#6b7280'}
                />
                <span>{announcement.likesCount || 0}</span>
              </button>
              <button 
                className="comment-button"
                onClick={(e) => handleCommentClick(e, announcement)}
              >
                <MessageCircle size={16} />
                <span>{announcement.commentCount || 0}</span>
              </button>
            </div>
          </li>
        ))}
      </ul>
      
      {/* Comment Modal */}
      {showCommentModal && selectedAnnouncementForComment && (
        <div className="comment-modal-overlay" onClick={() => setShowCommentModal(false)}>
          <div className="comment-modal" onClick={(e) => e.stopPropagation()}>
            <div className="comment-modal-header">
              <h3>Add a comment</h3>
              <button 
                className="close-button" 
                onClick={() => setShowCommentModal(false)}
              >
                ×
              </button>
            </div>
            <div className="comment-modal-body">
              <div className="announcement-info">
                <strong>{selectedAnnouncementForComment.title}</strong>
                <p>{truncateText(selectedAnnouncementForComment.content, 100)}</p>
              </div>
              <textarea
                className="comment-input"
                placeholder="Write your comment..."
                value={commentText}
                onChange={(e) => setCommentText(e.target.value)}
                rows={4}
                maxLength={500}
              />
              <div className="comment-actions">
                <span className="char-count">{commentText.length}/500</span>
                <button 
                  className="submit-comment-button"
                  onClick={handleCommentSubmit}
                  disabled={!commentText.trim() || submittingComment}
                >
                  {submittingComment ? 'Posting...' : 'Post Comment'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AnnouncementsWidget;