// src/utils/firebaseTracingToggle.js
// Utility to toggle between regular and traced Firebase

let isTracingEnabled = false;

// Function to enable Firebase tracing
export const enableFirebaseTracing = () => {
  if (!isTracingEnabled) {
    isTracingEnabled = true;
    console.log('%c🔍 Firebase path tracing ENABLED', 'font-weight: bold; color: green; font-size: 14px');
    console.log('Any Firebase operations should now be traced');
    return true;
  }
  return false;
};

// Function to disable Firebase tracing
export const disableFirebaseTracing = () => {
  if (isTracingEnabled) {
    isTracingEnabled = false;
    console.log('%c🔍 Firebase path tracing DISABLED', 'font-weight: bold; color: red; font-size: 14px');
    return true;
  }
  return false;
};

// Function to check if tracing is enabled
export const isFirebaseTracingEnabled = () => {
  return isTracingEnabled;
};

/**
 * Helper function to import the appropriate Firebase module
 * This should be used in components that need to dynamically switch between
 * regular and traced Firebase operations
 * 
 * @returns {Promise<Object>} Firebase module (either regular or traced)
 */
export const getFirebaseModule = async () => {
  if (isTracingEnabled) {
    console.log('Using traced Firebase module');
    return await import('../firebase/traced-firebase');
  } else {
    console.log('Using regular Firebase module');
    return await import('../firebase/firebase');
  }
};

/**
 * Helper function to get the appropriate Firebase path for importing
 * This is useful when you need to statically import Firebase in a component
 * 
 * @returns {string} Path to the Firebase module to use
 */
export const getFirebaseImportPath = () => {
  return isTracingEnabled 
    ? '../firebase/traced-firebase'
    : '../firebase/firebase';
};
