import apiKeyService from './apiKeyService'

const CACHE_KEY = 'predict_news_cache'
const CACHE_TTL = 15 * 60 * 1000 // 15 minutes

function getCache() {
  try {
    const raw = localStorage.getItem(CACHE_KEY)
    if (!raw) return null
    const cached = JSON.parse(raw)
    if (Date.now() - cached.timestamp > CACHE_TTL) return null
    return cached.data
  } catch {
    return null
  }
}

function setCache(data) {
  localStorage.setItem(CACHE_KEY, JSON.stringify({ data, timestamp: Date.now() }))
}

const CATEGORY_KEYWORDS = {
  politics: ['election', 'congress', 'senate', 'vote', 'political', 'democrat', 'republican', 'legislation', 'president', 'governor', 'campaign'],
  economics: ['economy', 'inflation', 'gdp', 'federal reserve', 'interest rate', 'stock market', 'trade', 'recession', 'jobs', 'unemployment', 'bitcoin', 'crypto', 'currency'],
  sports: ['nba', 'nfl', 'mlb', 'premier league', 'champions league', 'fifa', 'olympics', 'tennis', 'golf', 'championship', 'playoffs', 'tournament'],
  entertainment: ['movie', 'film', 'oscar', 'grammy', 'emmy', 'netflix', 'box office', 'album', 'concert', 'celebrity', 'award'],
  tech: ['ai', 'artificial intelligence', 'apple', 'google', 'microsoft', 'tesla', 'spacex', 'startup', 'software', 'chip', 'semiconductor', 'robot', 'tiktok', 'meta'],
  science: ['nasa', 'climate', 'research', 'study', 'discovery', 'vaccine', 'space', 'mars', 'pandemic', 'medical', 'gene', 'quantum'],
  weather: ['hurricane', 'storm', 'drought', 'flood', 'tornado', 'earthquake', 'el nino', 'la nina', 'wildfire', 'heatwave', 'climate change'],
  geopolitics: ['war', 'nato', 'ukraine', 'russia', 'china', 'sanctions', 'military', 'treaty', 'diplomacy', 'conflict', 'nuclear', 'middle east'],
}

function categorizeArticle(article) {
  const text = `${article.title} ${article.description || ''}`.toLowerCase()
  let bestCategory = 'geopolitics'
  let bestScore = 0

  for (const [category, keywords] of Object.entries(CATEGORY_KEYWORDS)) {
    const score = keywords.reduce((sum, kw) => sum + (text.includes(kw) ? 1 : 0), 0)
    if (score > bestScore) {
      bestScore = score
      bestCategory = category
    }
  }

  return bestCategory
}

function extractSentiment(article) {
  const text = `${article.title} ${article.description || ''}`.toLowerCase()
  const positive = ['success', 'growth', 'win', 'gain', 'rise', 'surge', 'boost', 'record', 'breakthrough', 'agreement', 'peace', 'strong']
  const negative = ['fail', 'crisis', 'loss', 'drop', 'fall', 'decline', 'crash', 'threat', 'war', 'conflict', 'risk', 'weak', 'concern']

  let score = 0.5
  for (const w of positive) if (text.includes(w)) score += 0.05
  for (const w of negative) if (text.includes(w)) score -= 0.05
  return Math.max(0.05, Math.min(0.95, score))
}

function matchArticleToPredictions(article, predictions) {
  const text = `${article.title} ${article.description || ''}`.toLowerCase()
  const matches = []

  for (const prediction of predictions) {
    const titleWords = prediction.title.toLowerCase().split(/\W+/).filter(w => w.length > 3)
    const matchCount = titleWords.filter(w => text.includes(w)).length
    const matchRatio = matchCount / titleWords.length

    if (matchRatio >= 0.3 || matchCount >= 3) {
      matches.push({
        predictionId: prediction.id,
        relevance: matchRatio,
        matchedKeywords: matchCount,
      })
    }
  }

  return matches.sort((a, b) => b.relevance - a.relevance)
}

const newsService = {
  async fetchHeadlines(query = null) {
    const apiKey = apiKeyService.getNewsApiKey()
    if (!apiKey) return { articles: [], error: 'No NewsAPI key configured' }

    const cached = getCache()
    if (cached && !query) return { articles: cached, error: null }

    try {
      const params = new URLSearchParams({
        apiKey,
        language: 'en',
        pageSize: '50',
        sortBy: 'publishedAt',
      })

      let url
      if (query) {
        params.set('q', query)
        url = `https://newsapi.org/v2/everything?${params}`
      } else {
        url = `https://newsapi.org/v2/top-headlines?${params}&country=us`
      }

      const res = await fetch(url)
      if (!res.ok) {
        const err = await res.json().catch(() => ({}))
        throw new Error(err.message || `HTTP ${res.status}`)
      }

      const data = await res.json()
      const articles = (data.articles || []).map(a => ({
        title: a.title,
        description: a.description,
        url: a.url,
        source: a.source?.name || 'Unknown',
        publishedAt: a.publishedAt,
        imageUrl: a.urlToImage,
        category: categorizeArticle(a),
        sentiment: extractSentiment(a),
      }))

      if (!query) setCache(articles)
      return { articles, error: null }
    } catch (err) {
      return { articles: [], error: err.message }
    }
  },

  async fetchForPrediction(prediction) {
    const keywords = prediction.title.split(/\W+/).filter(w => w.length > 3).slice(0, 5).join(' ')
    return this.fetchHeadlines(keywords)
  },

  generateInputsFromArticles(articles, predictions) {
    const inputs = []

    for (const article of articles) {
      const matches = matchArticleToPredictions(article, predictions)
      for (const match of matches) {
        inputs.push({
          predictionId: match.predictionId,
          source: article.source,
          sourceUrl: article.url,
          type: 'news',
          weight: 0.6 + (match.relevance * 0.3),
          sentiment: article.sentiment,
          reliability: 0.75,
          timestamp: article.publishedAt || new Date().toISOString(),
          title: article.title,
          category: article.category,
          isLive: true,
        })
      }
    }

    return inputs
  },

  categorizeArticle,
  extractSentiment,
}

export default newsService
