// Environment variable debugging
const debugEnvVars = () => {
  const vars = {
    serverUrl: import.meta.env.VITE_LIVEKIT_SERVER_URL,
    apiKey: import.meta.env.VITE_LIVEKIT_API_KEY,
    apiSecret: import.meta.env.VITE_LIVEKIT_API_SECRET,
    enableSimulcast: import.meta.env.VITE_LIVEKIT_ENABLE_SIMULCAST,
    enableDynacast: import.meta.env.VITE_LIVEKIT_ENABLE_DYNACAST,
    maxBitrate: import.meta.env.VITE_LIVEKIT_MAX_BITRATE,
    videoCodec: import.meta.env.VITE_LIVEKIT_VIDEO_CODEC,
    nodeEnv: import.meta.env.NODE_ENV,
    mode: import.meta.env.MODE,
    dev: import.meta.env.DEV,
    prod: import.meta.env.PROD
  };
  
  console.group('🔧 LiveKit Environment Variables Debug');
  console.log('Raw environment variables:', {
    ...vars,
    apiSecret: vars.apiSecret ? `${vars.apiSecret.substring(0, 8)}...` : 'Not set'
  });
  console.log('Environment detection:', {
    nodeEnv: import.meta.env.NODE_ENV,
    mode: import.meta.env.MODE,
    isDev: import.meta.env.DEV,
    isProd: import.meta.env.PROD
  });
  console.groupEnd();
  
  return vars;
};

// Get environment variables with debugging
const getEnvVars = () => {
  const vars = debugEnvVars();
  
  // Only the public server URL is required in the browser — the API key/secret
  // are intentionally blank here, since tokens are minted server-side by the
  // backend (see isConfigValid below). Warning about them was noise.
  if (!vars.serverUrl) {
    console.group('❌ LiveKit Configuration Missing');
    console.error('- VITE_LIVEKIT_SERVER_URL is not set');
    console.error('Check your .env file and ensure VITE_LIVEKIT_SERVER_URL is properly set');
    console.groupEnd();
  }
  
  return vars;
};

export const LiveKitConfig = {
  // Development Configuration
  development: {
    get serverUrl() {
      return import.meta.env.VITE_LIVEKIT_SERVER_URL || 'wss://talkstudio-2c55dh9q.livekit.cloud';
    },
    get apiKey() {
      return import.meta.env.VITE_LIVEKIT_API_KEY || '';
    },
    get apiSecret() {
      return import.meta.env.VITE_LIVEKIT_API_SECRET || '';
    },
    get enableSimulcast() {
      return import.meta.env.VITE_LIVEKIT_ENABLE_SIMULCAST === 'true';
    },
    get enableDynacast() {
      return import.meta.env.VITE_LIVEKIT_ENABLE_DYNACAST === 'true';
    },
    get maxBitrate() {
      return parseInt(import.meta.env.VITE_LIVEKIT_MAX_BITRATE) || 2000000;
    },
    get videoCodec() {
      return import.meta.env.VITE_LIVEKIT_VIDEO_CODEC || 'vp9';
    },
  },

  // Production Configuration
  production: {
    get serverUrl() {
      return import.meta.env.VITE_LIVEKIT_SERVER_URL || '';
    },
    get apiKey() {
      return import.meta.env.VITE_LIVEKIT_API_KEY || '';
    },
    get apiSecret() {
      return import.meta.env.VITE_LIVEKIT_API_SECRET || '';
    },
    get enableSimulcast() {
      return import.meta.env.VITE_LIVEKIT_ENABLE_SIMULCAST === 'true';
    },
    get enableDynacast() {
      return import.meta.env.VITE_LIVEKIT_ENABLE_DYNACAST === 'true';
    },
    get maxBitrate() {
      return parseInt(import.meta.env.VITE_LIVEKIT_MAX_BITRATE) || 3000000;
    },
    get videoCodec() {
      return import.meta.env.VITE_LIVEKIT_VIDEO_CODEC || 'h264';
    },
  },

  // Default room settings
  defaultRoomConfig: {
    // Adaptive Stream settings for optimal performance
    adaptiveStream: true,

    // Video settings
    video: {
      resolution: {
        width: 1280,
        height: 720,
      },
      frameRate: 30,
      // Multiple quality layers for adaptive streaming
      simulcast: true,
    },

    // Audio settings
    audio: {
      autoGainControl: true,
      echoCancellation: true,
      noiseSuppression: true,
      highQualityVoice: true,
    },

    // Connection settings - Improved for stability
    reconnectPolicy: {
      nextRetryDelayInMs: 1000,  // Start quickly for first retry
      maxRetryDelayInMs: 15000,  // Max 15 seconds between retries
      maxAttempts: 10,  // More attempts for better recovery
      backoffFactor: 1.5,  // Gradual backoff
    },

    // Publishing settings with environment-based configuration
    publishDefaults: {
      audioCodec: 'opus',
      audioBitrate: 128000,  // 128 kbps
      dtx: true, // Discontinuous transmission for audio
      red: true, // Redundant encoding for reliability
      stopMicTrackOnMute: false,  // Keep track alive when muted
    },

    // WebRTC configuration for better NAT traversal
    rtcConfig: {
      iceTransportPolicy: 'all',
      iceCandidatePoolSize: 10,
    },
  },

  // Get current environment config with enhanced debugging
  getCurrentConfig() {
    // Force refresh of environment variables
    const envVars = getEnvVars();

    // Detect environment based on hostname and env variables
    const hostname = typeof window !== 'undefined' ? window.location.hostname : '';
    const isProductionDomain = hostname === 'talkstud.io' || hostname === 'talkstudio.space';

    let env = import.meta.env.NODE_ENV || import.meta.env.MODE || 'development';

    // Override to production if on production domain
    if (isProductionDomain) {
      env = 'production';
    }

    const config = this[env] || this.development;
    
    // Create a resolved config object
    const resolvedConfig = {
      serverUrl: config.serverUrl,
      apiKey: config.apiKey,
      apiSecret: config.apiSecret,
      enableSimulcast: config.enableSimulcast,
      enableDynacast: config.enableDynacast,
      maxBitrate: config.maxBitrate,
      videoCodec: config.videoCodec,
      publishDefaults: {
        ...this.defaultRoomConfig.publishDefaults,
        videoCodec: config.videoCodec,
        videoBitrate: config.maxBitrate,
        simulcast: config.enableSimulcast,
      }
    };
    
    // Log the resolved configuration
    console.log('🔧 LiveKit resolved configuration:', {
      environment: env,
      hostname: hostname || 'N/A',
      isProductionDomain,
      serverUrl: resolvedConfig.serverUrl,
      apiKey: resolvedConfig.apiKey ? `${resolvedConfig.apiKey.substring(0, 8)}...` : 'Not set',
      hasApiSecret: !!resolvedConfig.apiSecret,
      enableSimulcast: resolvedConfig.enableSimulcast,
      enableDynacast: resolvedConfig.enableDynacast,
      maxBitrate: resolvedConfig.maxBitrate,
      videoCodec: resolvedConfig.videoCodec
    });
    
    return resolvedConfig;
  },

  // Generate room URL
  getRoomUrl(roomName) {
    const config = this.getCurrentConfig();
    return `${config.serverUrl}?room=${encodeURIComponent(roomName)}`;
  },

  // Validate configuration with enhanced logging
  isConfigValid() {
    const config = this.getCurrentConfig();
    
    // Access tokens are minted server-side (the generateLiveKitToken Cloud
    // Function), so the browser only needs the public server URL to be valid.
    // The API key/secret live on the server and are intentionally absent here.
    const validationResults = {
      hasServerUrl: !!config.serverUrl,
      serverUrlFormat: config.serverUrl ? config.serverUrl.startsWith('wss://') || config.serverUrl.startsWith('ws://') : false
    };

    const isValid = validationResults.hasServerUrl && validationResults.serverUrlFormat;

    if (!isValid) {
      console.group('❌ LiveKit configuration validation failed');
      console.warn('Configuration issues found:', {
        serverUrl: config.serverUrl || 'MISSING',
        validationResults
      });
      console.warn('Set the public server URL for the client:');
      console.warn('- VITE_LIVEKIT_SERVER_URL=wss://your-livekit-server-url');
      console.warn('(API key/secret are configured on the server, not here.)');
      console.groupEnd();
    } else {
      console.log('✅ LiveKit configuration is valid:', {
        serverUrl: config.serverUrl,
        apiKey: config.apiKey ? `${config.apiKey.substring(0, 8)}...` : null,
        enableSimulcast: config.enableSimulcast,
        enableDynacast: config.enableDynacast,
        videoCodec: config.videoCodec
      });
    }
    
    return isValid;
  },

  // Get room connection options
  getRoomOptions(customOptions = {}) {
    const config = this.getCurrentConfig();

    return {
      adaptiveStream: config.enableDynacast,
      dynacast: config.enableDynacast,
      publishDefaults: {
        ...this.defaultRoomConfig.publishDefaults,
        ...config.publishDefaults,
        simulcast: config.enableSimulcast,
      },
      videoCaptureDefaults: {
        resolution: this.defaultRoomConfig.video.resolution,
        frameRate: this.defaultRoomConfig.video.frameRate,
      },
      audioCaptureDefaults: this.defaultRoomConfig.audio,
      reconnectPolicy: this.defaultRoomConfig.reconnectPolicy,
      rtcConfig: this.defaultRoomConfig.rtcConfig,
      // Connection timeout settings
      disconnectOnPageLeave: false,  // Don't auto-disconnect when page loses focus
      // Reduce reconnection thrashing
      e2ee: undefined,  // Disable E2EE if not needed to reduce complexity
      // Timeouts
      peerConnectionTimeout: 15000,  // 15 seconds to establish peer connection
      connectionQualityCallbackDelay: 2000,  // Delay before reporting quality changes
      ...customOptions
    };
  },

  // Debug configuration with enhanced output
  debugConfig() {
    const config = this.getCurrentConfig();
    console.group('🔧 LiveKit Configuration Debug');
    console.log('Environment:', import.meta.env.NODE_ENV || import.meta.env.MODE || 'unknown');
    console.log('Server URL:', config.serverUrl);
    console.log('API Key:', config.apiKey ? `${config.apiKey.substring(0, 8)}...` : 'Not set');
    console.log('API Secret:', config.apiSecret ? 'Set' : 'Not set');
    console.log('Enable Simulcast:', config.enableSimulcast);
    console.log('Enable Dynacast:', config.enableDynacast);
    console.log('Max Bitrate:', config.maxBitrate);
    console.log('Video Codec:', config.videoCodec);
    console.log('Is Valid:', this.isConfigValid());
    
    // Test environment variable access
    console.log('Raw env access test:', {
      serverUrl: import.meta.env.VITE_LIVEKIT_SERVER_URL,
      hasApiKey: !!import.meta.env.VITE_LIVEKIT_API_KEY,
      hasApiSecret: !!import.meta.env.VITE_LIVEKIT_API_SECRET
    });
    
    console.groupEnd();
    
    return config;
  },

  // Force reload configuration (useful for debugging)
  reloadConfig() {
    console.log('🔄 Reloading LiveKit configuration...');
    const config = this.getCurrentConfig();
    this.debugConfig();
    return config;
  }
};

