// Fixed Firebase configuration with proper RTDB URL handling for production
// Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\firebase.fixed.js

import { initializeApp } from "firebase/app";
import { getFirestore as _getFirestore, connectFirestoreEmulator, collection, getDocs, query, limit } from "firebase/firestore";
import { getAuth as _getAuth, GoogleAuthProvider, connectAuthEmulator } from "firebase/auth";
import { getStorage as _getStorage, connectStorageEmulator } from "firebase/storage"; 
import { getDatabase as _getDatabase, connectDatabaseEmulator, ref, onValue } from "firebase/database";
import { getFunctions as _getFunctions, connectFunctionsEmulator } from "firebase/functions";

// Safe performance monitoring wrapper
const createSafeTimingContext = (name) => {
  return {
    start: (operationName) => {
      console.log(`[Safe Performance] Started: ${name} - ${operationName || ''}`);
    },
    end: (operationName) => {
      console.log(`[Safe Performance] Completed: ${name} - ${operationName || ''}`);
    }
  };
};

// Initialize performance monitoring for Firebase with safe wrapper
const firebasePerformance = createSafeTimingContext('firebase');

// Cached service instances
let _db = null;
let _auth = null;
let _storage = null;
let _rtdb = null;
let _functions = null;
let _googleProvider = null;

// Debug logger that works in both dev and production
const logDebug = (message) => {
  console.log(message);
};

// FIXED: Proper environment detection
const getEnvironment = () => {
  const hostname = window.location.hostname;
  const isLocalhost = hostname === 'localhost' || hostname === '127.0.0.1';
  const isProduction = hostname === 'talkstudio.space' || hostname === 'talkstud.io';

  return {
    isDev: isLocalhost,
    isProduction: isProduction,
    hostname: hostname
  };
};

const env = getEnvironment();

// FIXED: Your Firebase configuration with proper fallbacks
const firebaseConfig = {
  apiKey: import.meta.env.VITE_FIREBASE_API_KEY || "REDACTED_FIREBASE_API_KEY",
  authDomain: import.meta.env.VITE_FIREBASE_AUTH_DOMAIN || "talkstudio-fb.firebaseapp.com",
  projectId: import.meta.env.VITE_FIREBASE_PROJECT_ID || "talkstudio-fb",
  // Firebase Storage lives on the modern default bucket (talkstudio-fb.firebasestorage.app).
  // The legacy "...appspot.com" bucket was never activated for Storage and returns
  // HTTP 400 "bucket has not been set up properly for Firebase Storage" on upload.
  storageBucket: import.meta.env.VITE_FIREBASE_STORAGE_BUCKET || "talkstudio-fb.firebasestorage.app",
  messagingSenderId: import.meta.env.VITE_FIREBASE_MESSAGING_SENDER_ID || "274213809869",
  appId: import.meta.env.VITE_FIREBASE_APP_ID || "1:274213809869:web:a44c96eee3de1282978384",
  // FIXED: Ensure RTDB URL is always defined
  databaseURL: import.meta.env.VITE_FIREBASE_DATABASE_URL || "https://talkstudio-fb-default-rtdb.firebaseio.com/"
};

// IMPORTANT: Validate the configuration before using it
const validateFirebaseConfig = () => {
  const required = ['apiKey', 'authDomain', 'projectId', 'storageBucket', 'messagingSenderId', 'appId', 'databaseURL'];
  const missing = required.filter(key => !firebaseConfig[key]);
  
  if (missing.length > 0) {
    console.error('❌ Missing Firebase configuration:', missing);
    throw new Error(`Missing Firebase configuration: ${missing.join(', ')}`);
  }
  
  // Validate RTDB URL format
  if (!firebaseConfig.databaseURL.includes('firebaseio.com')) {
    console.error('❌ Invalid Firebase RTDB URL:', firebaseConfig.databaseURL);
    throw new Error('Invalid Firebase Realtime Database URL format');
  }
  
  console.log('✅ Firebase configuration validated successfully');
  return true;
};

// Validate before initializing
validateFirebaseConfig();

// Initialize Firebase app
const app = initializeApp(firebaseConfig);

// Log configuration
logDebug(`Firebase initialized for environment: ${env.isProduction ? 'production' : env.isDev ? 'development' : 'other'}`);
logDebug(`RTDB URL: ${firebaseConfig.databaseURL}`);
if (env.isDev) {
  logDebug('Using normal RTDB connections (without proxy) for WebSocket support.');
}

// Lazy initialization of Firestore
const initFirestore = () => {
  if (!_db) {
    firebasePerformance.start('initializeFirestore');
    
    try {
      _db = _getFirestore(app);
      
      if (env.isDev && import.meta.env.VITE_USE_FIRESTORE_EMULATOR === 'true') {
        connectFirestoreEmulator(_db, "localhost", 8080);
      }
      
      // Test Firestore connection
      const testFirestore = async () => {
        try {
          const testRef = collection(_db, '_test_');
          const testQuery = query(testRef, limit(1));
          await getDocs(testQuery);
          console.log('✅ Firestore connection successful - can query test collection');
          firebaseStatus.firestoreInitialized = true;
        } catch (testError) {
          console.error('❌ Firestore test query failed:', testError);
          firebaseStatus.errors.push({
            component: 'Firestore',
            error: testError.message || 'Could not query test collection'
          });
        }
      };
      
      testFirestore();
      logDebug('Firestore initialized successfully');
    } catch (error) {
      console.error('❌ Error initializing Firestore:', error);
      firebaseStatus.errors.push({
        component: 'Firestore',
        error: error.message || 'Initialization error'
      });
      _db = {}; // Placeholder
    }
    
    firebasePerformance.end('initializeFirestore');
  }
  return _db;
};

// Lazy initialization of Auth
const initAuth = () => {
  if (!_auth) {
    firebasePerformance.start('initializeAuth');
    _auth = _getAuth(app);
    
    if (env.isDev && import.meta.env.VITE_USE_AUTH_EMULATOR === 'true') {
      connectAuthEmulator(_auth, "http://localhost:9099");
    }
    
    logDebug('Firebase Auth initialized successfully');
    firebasePerformance.end('initializeAuth');
  }
  return _auth;
};

// Lazy initialization of Storage
const initStorage = () => {
  if (!_storage) {
    firebasePerformance.start('initializeStorage');
    _storage = _getStorage(app);
    
    if (env.isDev && import.meta.env.VITE_USE_STORAGE_EMULATOR === 'true') {
      connectStorageEmulator(_storage, "localhost", 9199);
    }
    
    if (env.isDev) {
      logDebug('Firebase Storage initialized in development mode');
      logDebug('The application will use a proxy server to avoid CORS issues with Firebase Storage.');
      logDebug('Make sure to run the combined server: node combined-server.js');
    }
    
    logDebug('Firebase Storage initialized successfully');
    firebasePerformance.end('initializeStorage');
  }
  return _storage;
};

// FIXED: Enhanced RTDB initialization with better error handling
const initRtdb = () => {
  if (!_rtdb) {
    firebasePerformance.start('initializeRTDB');
    
    // IMPORTANT: Log the database URL being used
    console.log('Initializing RTDB with URL:', firebaseConfig.databaseURL);
    
    // Validate RTDB URL before attempting connection
    if (!firebaseConfig.databaseURL || firebaseConfig.databaseURL === 'undefined') {
      console.error('❌ RTDB URL is undefined or empty');
      firebaseStatus.errors.push({
        component: 'RTDB',
        error: 'Database URL is undefined or empty'
      });
      firebasePerformance.end('initializeRTDB');
      return {};
    }
    
    try {
      _rtdb = _getDatabase(app);
      
      if (env.isDev && import.meta.env.VITE_USE_DATABASE_EMULATOR === 'true') {
        connectDatabaseEmulator(_rtdb, "localhost", 9000);
      }
      
      // Enhanced connection monitoring
      const connectedRef = ref(_rtdb, '.info/connected');
      onValue(connectedRef, (snap) => {
        if (snap.val() === true) {
          console.log('✅ Connected to Firebase Realtime Database');
          firebaseStatus.rtdbInitialized = true;
          firebaseStatus.rtdbConnected = true;
        } else {
          console.warn('❌ Disconnected from Firebase Realtime Database');
          firebaseStatus.rtdbConnected = false;
          
          // Provide troubleshooting info
          if (env.isDev) {
            console.log('If chat rooms are not loading, ensure:');
            console.log('1. Your Firebase project has the Realtime Database enabled');
            console.log('2. Your Firestore security rules allow the necessary access');
          } else {
            console.log('RTDB connection lost in production - this may affect real-time features');
          }
        }
      }, (error) => {
        console.error('❌ Firebase RTDB connection error:', error);
        
        // Enhanced error handling for different environments
        if (env.isDev) {
          console.log('RTDB Connection Troubleshooting:');
          console.log('- Check Firebase Console to ensure RTDB is enabled');
          console.log('- Verify security rules in Firebase Console');
          console.log('- Check if Authentication is working properly');
          console.log('- Verify the RTDB URL in your .env file');
        } else {
          console.log('RTDB connection failed in production. Please check:');
          console.log('- Firebase project configuration');
          console.log('- Network connectivity');
          console.log('- Security rules');
        }
        
        firebaseStatus.errors.push({
          component: 'RTDB',
          error: error.message || 'Connection error',
          code: error.code || 'unknown',
          timestamp: new Date().toISOString()
        });
      });
      
      logDebug('Firebase Realtime Database initialization attempted');
      
    } catch (error) {
      console.error('❌ Error setting up RTDB connection:', error);
      
      firebaseStatus.errors.push({
        component: 'RTDB',
        error: error.message || 'Setup error',
        code: error.code || 'unknown'
      });
      
      // Return empty object as fallback
      _rtdb = {};
    }
    
    firebasePerformance.end('initializeRTDB');
  }
  return _rtdb;
};

// Lazy initialization of Functions
const initFunctions = () => {
  if (!_functions) {
    firebasePerformance.start('initializeFunctions');
    _functions = _getFunctions(app);
    
    if (env.isDev && import.meta.env.VITE_USE_FUNCTIONS_EMULATOR === 'true') {
      connectFunctionsEmulator(_functions, "localhost", 5001);
    }
    
    if (env.isDev) {
      logDebug('Firebase Functions initialized in development mode');
      logDebug('Functions calls via HTTP can use the combined server proxy for CORS handling');
    }
    
    logDebug('Firebase Functions initialized successfully');
    firebasePerformance.end('initializeFunctions');
  }
  return _functions;
};

// Lazy initialization of Google Provider
const initGoogleProvider = () => {
  if (!_googleProvider) {
    _googleProvider = new GoogleAuthProvider();
    _googleProvider.setCustomParameters({
      prompt: 'select_account'
    });
    
    logDebug('Google Auth Provider initialized');
  }
  return _googleProvider;
};

// Enhanced status tracking
const firebaseStatus = {
  initialized: true,
  rtdbInitialized: false,
  rtdbConnected: false,
  firestoreInitialized: false,
  storageInitialized: false,
  functionsInitialized: false,
  errors: [],
  environment: env.isProduction ? 'production' : env.isDev ? 'development' : 'other',
  config: {
    hasApiKey: !!firebaseConfig.apiKey,
    hasAuthDomain: !!firebaseConfig.authDomain,
    hasProjectId: !!firebaseConfig.projectId,
    hasDatabaseUrl: !!firebaseConfig.databaseURL,
    databaseUrl: firebaseConfig.databaseURL
  }
};

// Export enhanced status check functions
export const checkRtdbStatus = () => {
  if (!_rtdb) {
    _rtdb = initRtdb();
    firebaseStatus.rtdbInitialized = Boolean(_rtdb && _rtdb.app);
  }
  
  return {
    initialized: firebaseStatus.rtdbInitialized,
    connected: firebaseStatus.rtdbConnected,
    url: firebaseConfig.databaseURL,
    errors: firebaseStatus.errors.filter(e => e.component === 'RTDB')
  };
};

export const checkStorageStatus = () => {
  if (!_storage) {
    _storage = initStorage();
    firebaseStatus.storageInitialized = Boolean(_storage && _storage.app);
  }
  
  return {
    initialized: firebaseStatus.storageInitialized,
    errors: firebaseStatus.errors.filter(e => e.component === 'Storage')
  };
};

// Enhanced diagnostic function
export const getFirebaseStatus = () => {
  return {
    ...firebaseStatus,
    rtdb: checkRtdbStatus(),
    storage: checkStorageStatus(),
    timestamp: new Date().toISOString()
  };
};

// Helper function to get the current Firestore region
export const getFirestoreRegion = () => {
  return 'us-central1';
};

// Getter functions for Firebase services
export const getDb = () => initFirestore();
export const getRtdb = () => initRtdb();
export const getAuthInstance = () => initAuth();
export const getStorageInstance = () => initStorage();
export const getFunctionsInstance = () => initFunctions();
export const getGoogleProviderInstance = () => initGoogleProvider();
// Export Firebase services for use throughout the application
export { firebaseStatus, app };

// For backward compatibility - existing parts of the app still use these
export const db = initFirestore();
export const rtdb = initRtdb();
export const auth = initAuth();
export const storage = initStorage();
export const functions = initFunctions();
export const googleProvider = initGoogleProvider();

// Export configuration for debugging
export const firebaseConfigExport = firebaseConfig;
