// src/components/posts/CommentSection.jsx
import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { 
  collection, 
  query, 
  orderBy, 
  onSnapshot,
  addDoc,
  deleteDoc,
  doc,
  serverTimestamp,
  updateDoc,
  increment
} from 'firebase/firestore';
import { db } from '../../firebase';
import { Send, Trash2, Music } from 'lucide-react';
import { getDoc } from 'firebase/firestore';
import './CommentSection.css';

const CommentSection = ({ postId, onCommentAdd, onCommentDelete }) => {
  const { currentUser } = useAuth();
  const [comments, setComments] = useState([]);
  const [newComment, setNewComment] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');

  // Listen for comments
  useEffect(() => {
    const commentsRef = collection(db, 'posts', postId, 'comments');
    const q = query(commentsRef, orderBy('createdAt', 'asc'));
    
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const commentsData = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setComments(commentsData);
    });

    return () => unsubscribe();
  }, [postId]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!currentUser || currentUser.isAnonymous) {
      alert('Please log in to comment');
      return;
    }

    if (!newComment.trim()) return;

    setIsSubmitting(true);
    setError('');

    try {
      // Check if user is an artist
      const userRef = doc(db, 'users', currentUser.uid);
      const userDoc = await getDoc(userRef);
      const isArtist = userDoc.exists() && userDoc.data().isArtist === true;

      const commentData = {
        content: newComment.trim(),
        authorId: currentUser.uid,
        authorName: currentUser.displayName || 'Anonymous',
        authorPhoto: currentUser.photoURL || '',
        isArtist: isArtist,
        createdAt: serverTimestamp()
      };

      const commentsRef = collection(db, 'posts', postId, 'comments');
      await addDoc(commentsRef, commentData);

      // Update comment count on the post
      const postRef = doc(db, 'posts', postId);
      await updateDoc(postRef, {
        commentsCount: increment(1)
      });

      setNewComment('');
      if (onCommentAdd) onCommentAdd();
    } catch (err) {
      console.error('Error adding comment:', err);
      setError('Failed to add comment');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async (commentId) => {
    if (!window.confirm('Delete this comment?')) return;

    try {
      await deleteDoc(doc(db, 'posts', postId, 'comments', commentId));
      
      // Update comment count on the post
      const postRef = doc(db, 'posts', postId);
      await updateDoc(postRef, {
        commentsCount: increment(-1)
      });
      
      if (onCommentDelete) onCommentDelete();
    } catch (err) {
      console.error('Error deleting comment:', err);
      setError('Failed to delete comment');
    }
  };

  const formatDate = (timestamp) => {
    if (!timestamp) return '';
    const date = timestamp.toDate ? timestamp.toDate() : new Date(timestamp);
    const now = new Date();
    const diff = now - date;
    
    if (diff < 60000) return 'just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    if (diff < 86400000) return `${Math.floor(diff / 3600000)}h ago`;
    
    return date.toLocaleDateString();
  };

  const getProfileUrl = (comment) => {
    if (comment.isArtist) {
      return `/artist/${comment.authorId}`;
    }
    return `/people/${comment.authorId}`;
  };

  return (
    <div className="comment-section">
      <div className="comments-list">
        {comments.map(comment => (
          <div key={comment.id} className="comment">
            <Link to={getProfileUrl(comment)} className="comment-author">
              <div className="comment-avatar">
                {comment.authorPhoto ? (
                  <img src={comment.authorPhoto} alt={comment.authorName} />
                ) : (
                  <div className="avatar-placeholder">
                    {comment.authorName?.charAt(0) || 'U'}
                  </div>
                )}
              </div>
            </Link>
            
            <div className="comment-content">
              <div className="comment-header">
                <Link to={getProfileUrl(comment)} className="author-name">
                  {comment.authorName}
                  {comment.isArtist && (
                    <span className="artist-badge" title="Artist">
                      <Music size={10} />
                    </span>
                  )}
                </Link>
                <span className="comment-time">{formatDate(comment.createdAt)}</span>
              </div>
              <p>{comment.content}</p>
            </div>
            
            {currentUser && comment.authorId === currentUser.uid && (
              <button
                className="delete-comment"
                onClick={() => handleDelete(comment.id)}
                title="Delete comment"
              >
                <Trash2 size={14} />
              </button>
            )}
          </div>
        ))}
        
        {comments.length === 0 && (
          <p className="no-comments">No comments yet. Be the first to comment!</p>
        )}
      </div>

      {error && <div className="error-message">{error}</div>}

      {currentUser && !currentUser.isAnonymous ? (
        <form onSubmit={handleSubmit} className="comment-form">
          <div className="comment-input-wrapper">
            <div className="user-avatar">
              {currentUser.photoURL ? (
                <img src={currentUser.photoURL} alt={currentUser.displayName} />
              ) : (
                <div className="avatar-placeholder">
                  {currentUser.displayName?.charAt(0) || 'U'}
                </div>
              )}
            </div>
            
            <input
              type="text"
              value={newComment}
              onChange={(e) => setNewComment(e.target.value)}
              placeholder="Write a comment..."
              disabled={isSubmitting}
              maxLength={300}
            />
            
            <button
              type="submit"
              disabled={isSubmitting || !newComment.trim()}
              className="send-button"
            >
              <Send size={18} />
            </button>
          </div>
        </form>
      ) : (
        <div className="comment-login-prompt">
          <Link to="/login">Log in to comment</Link>
        </div>
      )}
    </div>
  );
};

export default CommentSection;