// src/components/chat/ChatRoomsList.jsx
import React, { useState, useEffect } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { getDatabase, ref, query, orderByChild, limitToLast, onValue } from 'firebase/database';
import { getFirestore, collection, getDocs, where } from 'firebase/firestore';
import { useAuth } from '../../contexts/AuthContext';
import { MessageSquare, Plus, Users, Clock, Video } from 'lucide-react';
import { debugRoomData, debugRoomIssues } from '../../utils/debug-utils';

const ChatRoomsList = () => {
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  const { roomId: currentRoomId } = useParams();
  
  const [rooms, setRooms] = useState([]);
  const [streamingRooms, setStreamingRooms] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  
  // Check if user is anonymous
  const isAnonymous = !currentUser || currentUser.isAnonymous;
  
  // Log authentication status
  useEffect(() => {
    console.log('ChatRoomsList - Auth Status:', { 
      isLoggedIn: !!currentUser,
      isAnonymous: isAnonymous,
      userId: currentUser?.uid
    });
  }, [currentUser, isAnonymous]);
  
  // Fetch rooms from Realtime Database
  useEffect(() => {
    const fetchRooms = async () => {
      try {
        setLoading(true);
        
        const db = getDatabase();
        // Query for public rooms, ordered by last activity
        const roomsRef = ref(db, 'chats/public');
        const roomsQuery = query(roomsRef, orderByChild('lastActivityTimestamp'));
        
        // Set up real-time listener
        const unsubscribe = onValue(roomsQuery, (snapshot) => {
          if (snapshot.exists()) {
            const roomsData = snapshot.val();
            console.log('Firebase returned rooms data:', roomsData);
            
            const roomsList = Object.keys(roomsData)
              .map(key => ({
                id: key,
                ...roomsData[key],
                // Ensure room type is set properly for filtering
                type: roomsData[key].type || 'public'
              }));
              
            console.log('Raw rooms before filtering:', roomsList.length);
            console.log('Room types distribution:', roomsList.reduce((acc, room) => {
              const type = room.type || 'public';
              acc[type] = (acc[type] || 0) + 1;
              return acc;
            }, {}));
              
            // Filter rooms: ensure public rooms are always visible to everyone
            // and only filter other room types
            const filteredRooms = roomsList.filter(room => {
                // Log each room being evaluated
                const roomType = room.type || 'public';
                const isPublic = roomType === 'public';
                const userCanSee = isPublic || (currentUser && !currentUser.isAnonymous);
                
                if (!userCanSee) {
                  console.log(`Filtering out room ${room.id} (${room.name}) - type: ${roomType}, user is anonymous: ${currentUser?.isAnonymous}`);
                }
                
                return userCanSee;
              })
              .sort((a, b) => {
                // Sort by lastActivityTimestamp in descending order
                const aTime = a.lastActivityTimestamp || 0;
                const bTime = b.lastActivityTimestamp || 0;
                return bTime - aTime;
              });
              
            console.log('Filtered rooms for ' + (currentUser?.isAnonymous ? 'anonymous' : 'logged in') + ' user:', filteredRooms.length);
            console.log('Filtered room names:', filteredRooms.map(r => `${r.name} (${r.type || 'public'})`));
            debugRoomData(filteredRooms, currentUser, 'ChatRoomsList');
            
            setRooms(filteredRooms);
          } else {
            // No rooms found
            console.log('No rooms found in Firebase at path chats/public');
            setRooms([]);
          }
          setLoading(false);
        }, (err) => {
          console.error('Error fetching rooms:', err);
          setError('Failed to load rooms');
          setLoading(false);
        });
        
        return () => unsubscribe();
      } catch (err) {
        console.error('Error setting up rooms subscription:', err);
        setError('Failed to load rooms');
        setLoading(false);
        return () => {};
      }
    };
    
    // Fetch rooms with active streams
    const fetchStreamingRooms = async () => {
      try {
        const firestore = getFirestore();
        const streamsQuery = collection(firestore, 'streams');
        
        // Get all active streams
        const streamSnapshot = await getDocs(streamsQuery);
        
        if (!streamSnapshot.empty) {
          const activeStreams = [];
          
          streamSnapshot.forEach(doc => {
            const streamData = doc.data();
            // Only include streams that are currently live
            if (streamData.isLive && streamData.roomId) {
              activeStreams.push({
                id: doc.id,
                ...streamData
              });
            }
          });
          
          // Get room details for each streaming room
          const rtdb = getDatabase();
          const streamingRoomIds = activeStreams.map(stream => stream.roomId);
          const streamingRoomsData = [];
          
          for (const roomId of streamingRoomIds) {
            const roomRef = ref(rtdb, `chats/public/${roomId}`);
            
            // Get room data
            const roomSnapshot = await new Promise((resolve, reject) => {
              onValue(roomRef, resolve, { onlyOnce: true });
            });
            
            if (roomSnapshot.exists()) {
              const roomData = roomSnapshot.val();
              const matchingStream = activeStreams.find(stream => stream.roomId === roomId);
              
              streamingRoomsData.push({
                id: roomId,
                ...roomData,
                type: roomData.type || 'public',
                hasActiveStream: true,
                streamId: matchingStream.id,
                streamTitle: matchingStream.title,
                viewerCount: matchingStream.viewerCount || 0
              });
            }
          }
          
          setStreamingRooms(streamingRoomsData);
        } else {
          setStreamingRooms([]);
        }
      } catch (err) {
        console.error('Error fetching streaming rooms:', err);
        // Don't set error state here to not disrupt the main rooms list
      }
    };
    
    fetchRooms();
    fetchStreamingRooms();
  }, [currentUser, isAnonymous]);
  
  // Handle create room button click
  const handleCreateRoom = () => {
    navigate('/create-room');
  };
  
  // Format last activity time
  const formatLastActivity = (timestamp) => {
    if (!timestamp) return 'No activity';
    
    const now = new Date();
    const lastActivity = new Date(timestamp);
    const diffInMinutes = Math.floor((now - lastActivity) / (1000 * 60));
    
    if (diffInMinutes < 1) return 'Just now';
    if (diffInMinutes === 1) return '1 minute ago';
    if (diffInMinutes < 60) return `${diffInMinutes} minutes ago`;
    
    const diffInHours = Math.floor(diffInMinutes / 60);
    if (diffInHours === 1) return '1 hour ago';
    if (diffInHours < 24) return `${diffInHours} hours ago`;
    
    const diffInDays = Math.floor(diffInHours / 24);
    if (diffInDays === 1) return 'Yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    
    return lastActivity.toLocaleDateString();
  };
  
  if (loading) {
    return (
      <div className="rooms-list-loading">
        <div className="spinner"></div>
        <p>Loading rooms...</p>
      </div>
    );
  }
  
  if (error) {
    return (
      <div className="rooms-list-error">
        <p>{error}</p>
      </div>
    );
  }
  
  return (
    <div className="rooms-list">
      {/* Debug info */}
      <div style={{ padding: '8px', backgroundColor: '#f0f8ff', fontSize: '12px', marginBottom: '8px' }}>
        <div><strong>User:</strong> {currentUser ? (isAnonymous ? 'Anonymous' : 'Logged in') : 'Not logged in'}</div>
        <div><strong>Rooms:</strong> {rooms.length} total</div>
        <div><strong>Public rooms:</strong> {rooms.filter(r => r.type === 'public' || !r.type).length}</div>
        <div><strong>Streaming rooms:</strong> {streamingRooms.length}</div>
      </div>
      
      {/* Live Streaming Rooms Section */}
      {streamingRooms.length > 0 && (
        <div className="streaming-rooms-section">
          <div className="section-header">
            <h2>Live Streaming Rooms</h2>
            <Video size={16} />
          </div>
          
          <div className="rooms-items streaming-rooms">
            {streamingRooms.map((room) => (
              <Link
                key={room.id}
                to={`/stream-room/${room.id}`}
                className={`room-item streaming-room ${room.id === currentRoomId ? 'active' : ''}`}
              >
                <div className="room-icon streaming">
                  <Video size={18} />
                </div>
                
                <div className="room-info">
                  <div className="room-name">{room.eventTitle || room.name || 'Untitled Room'}</div>
                  <div className="stream-title">{room.streamTitle || 'Live Stream'}</div>
                  
                  <div className="room-meta">
                    <div className="room-users">
                      <Users size={12} />
                      <span>{room.viewerCount || 0} watching</span>
                    </div>
                    
                    <div className="stream-badge">
                      LIVE
                    </div>
                  </div>
                </div>
              </Link>
            ))}
          </div>
        </div>
      )}
      
      {/* Regular Chat Rooms Section */}
      <div className="chat-rooms-section">
        <div className="rooms-list-header">
          <h2>Chat Rooms</h2>
          <button 
            className="create-room-button"
            onClick={handleCreateRoom}
            title="Create new room"
          >
            <Plus size={16} />
            <span>Create Room</span>
          </button>
        </div>
        
        <div className="rooms-items">
          {rooms.length === 0 ? (
            <div className="no-rooms">
              <p>No chat rooms available</p>
            </div>
          ) : (
            rooms.map((room) => (
              <Link
                key={room.id}
                to={`/room/${room.id}`}
                className={`room-item ${room.id === currentRoomId ? 'active' : ''}`}
              >
                <div className="room-icon">
                  <MessageSquare size={18} />
                </div>
                
                <div className="room-info">
                  <div className="room-name">{room.eventTitle || room.name || 'Untitled Room'}</div>
                  
                  <div className="room-meta">
                    <div className="room-users">
                      <Users size={12} />
                      <span>{room.activeUsers ? Object.keys(room.activeUsers).length : 0}</span>
                    </div>
                    
                    <div className="room-activity">
                      <Clock size={12} />
                      <span>{formatLastActivity(room.lastActivityTimestamp)}</span>
                    </div>
                  </div>
                </div>
              </Link>
            ))
          )}
        </div>
      </div>
      
      <style jsx="true">{`
        .rooms-list {
          display: flex;
          flex-direction: column;
          height: 100%;
          overflow-y: auto;
        }
        
        .section-header,
        .rooms-list-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          padding: 0.75rem 1rem;
          background-color: #f3f4f6;
          border-bottom: 1px solid #e5e7eb;
        }
        
        .section-header {
          background-color: #4f46e5;
          color: white;
        }
        
        .section-header h2,
        .rooms-list-header h2 {
          margin: 0;
          font-size: 1rem;
          font-weight: 600;
        }
        
        .create-room-button {
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 6px;
          padding: 6px 12px;
          background-color: #10b981;
          color: white;
          border: none;
          border-radius: 8px;
          cursor: pointer;
          transition: all 0.2s;
          font-size: 14px;
          font-weight: 600;
          white-space: nowrap;
        }
        
        .create-room-button:hover {
          background-color: #059669;
          transform: translateY(-1px);
          box-shadow: 0 2px 4px rgba(16, 185, 129, 0.2);
        }
        
        .create-room-button span {
          margin-left: 2px;
        }
        
        .streaming-rooms-section,
        .chat-rooms-section {
          display: flex;
          flex-direction: column;
        }
        
        .streaming-rooms-section {
          margin-bottom: 1rem;
        }
        
        .rooms-items {
          flex-grow: 1;
          overflow-y: auto;
          padding: 0.5rem 0;
          max-height: calc(100vh - 200px);
        }
        
        .streaming-rooms {
          max-height: 300px;
          overflow-y: auto;
        }
        
        .room-item {
          display: flex;
          align-items: center;
          padding: 0.75rem 1rem;
          border-bottom: 1px solid #f3f4f6;
          color: #111827;
          text-decoration: none;
          transition: background-color 0.2s;
        }
        
        .room-item:hover {
          background-color: #f9fafb;
        }
        
        .room-item.active {
          background-color: #f3f4f6;
          border-left: 3px solid #4f46e5;
        }
        
        .streaming-room {
          background-color: #f0f4ff;
        }
        
        .streaming-room:hover {
          background-color: #e0e7ff;
        }
        
        .streaming-room.active {
          background-color: #e0e7ff;
          border-left: 3px solid #4f46e5;
        }
        
        .room-icon {
          margin-right: 0.75rem;
          color: #6b7280;
        }
        
        .room-icon.streaming {
          color: #ef4444;
        }
        
        .room-info {
          flex-grow: 1;
          min-width: 0;
        }
        
        .room-name {
          font-weight: 500;
          margin-bottom: 0.25rem;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }
        
        .stream-title {
          font-size: 0.75rem;
          color: #6b7280;
          margin-bottom: 0.25rem;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }
        
        .room-meta {
          display: flex;
          gap: 0.75rem;
          font-size: 0.75rem;
          color: #6b7280;
        }
        
        .room-users,
        .room-activity {
          display: flex;
          align-items: center;
          gap: 0.25rem;
        }
        
        .stream-badge {
          background-color: #ef4444;
          color: white;
          font-size: 0.625rem;
          font-weight: 600;
          padding: 0.125rem 0.375rem;
          border-radius: 1rem;
          animation: pulse 2s infinite;
        }
        
        @keyframes pulse {
          0% { opacity: 1; }
          50% { opacity: 0.8; }
          100% { opacity: 1; }
        }
        
        .rooms-list-loading,
        .rooms-list-error,
        .no-rooms {
          padding: 1rem;
          text-align: center;
          color: #6b7280;
          font-size: 0.875rem;
        }
        
        .spinner {
          width: 1.5rem;
          height: 1.5rem;
          border: 2px solid rgba(79, 70, 229, 0.25);
          border-top-color: #4f46e5;
          border-radius: 50%;
          animation: spin 1s linear infinite;
          margin: 0 auto 0.5rem;
        }
        
        @keyframes spin {
          to {
            transform: rotate(360deg);
          }
        }
      `}</style>
    </div>
  );
};

export default ChatRoomsList;