// src/pages/ProductsPage.jsx
//
// Talk Studio the company, rather than Talk Studio the streaming app: one
// card per product (this platform, SmartInvestor CRM, the Store), reading
// from the same list the nav's product switcher uses (config/products).

import React from 'react';
import { Link } from 'react-router-dom';
import { ArrowRight, ExternalLink } from 'lucide-react';
import TalkStudioNav from '../components/layout/TalkStudioNav';
import { PRODUCTS, COMPANY_NAME, CURRENT_PRODUCT_ID } from '../config/products';
import './ProductsPage.css';

const hostOf = (url) => {
  try {
    return new URL(url).host.replace(/^www\./, '');
  } catch {
    return url;
  }
};

const ProductCard = ({ product }) => {
  const isCurrent = product.id === CURRENT_PRODUCT_ID;
  const cta = isCurrent ? 'Open Discover' : `Go to ${product.name}`;

  return (
    <article className="ts-card products-card" style={{ '--card-accent': product.accent }}>
      <div className="products-card-head">
        <span className="products-kind">{product.kind}</span>
        {isCurrent && <span className="ts-chip ts-chip--neutral">You're here</span>}
      </div>

      <h2 className="products-card-title">{product.name}</h2>
      <p className="products-card-tagline">{product.tagline}</p>
      <p className="products-card-body">{product.description}</p>

      <ul className="products-highlights">
        {product.highlights.map(item => (
          <li key={item}>{item}</li>
        ))}
      </ul>

      <div className="products-card-foot">
        {product.external ? (
          <a
            href={product.href}
            target="_blank"
            rel="noopener noreferrer"
            className="ts-btn ts-btn--primary ts-btn--md"
          >
            {cta} <ExternalLink size={14} />
          </a>
        ) : (
          <Link to={product.to} className="ts-btn ts-btn--indigo-soft ts-btn--md">
            {cta} <ArrowRight size={14} />
          </Link>
        )}
        <span className="ts-mono products-card-url">
          {product.external ? hostOf(product.href) : `talkstudio.space${product.to}`}
        </span>
      </div>
    </article>
  );
};

const ProductsPage = () => (
  <div className="ts-app ts-app--glow products-page">
    <TalkStudioNav active="products" />

    <div className="ts-page">
      <header className="products-hero">
        <span className="ts-mono products-eyebrow">{COMPANY_NAME}</span>
        <h1 className="products-title">One company, three products.</h1>
        <p className="products-sub">
          {COMPANY_NAME} builds the live audio platform you're on, the CRM investors run their
          deals through, and the store everything ships from. Same account, same login — pick
          the one you need.
        </p>
      </header>

      <div className="products-grid">
        {PRODUCTS.map(product => (
          <ProductCard key={product.id} product={product} />
        ))}
      </div>

      <footer className="ts-card ts-card--quiet products-note">
        <div className="products-note-title">Looking for something else?</div>
        <div className="products-note-body">
          Every product signs in with your {COMPANY_NAME} account. Questions about billing or
          access — <Link to="/settings">check your account settings</Link>.
        </div>
      </footer>
    </div>
  </div>
);

export default ProductsPage;
