// src/components/posts/Feed.jsx
import React, { useState, useEffect } from 'react';
import { collection, query, where, orderBy, limit, onSnapshot } from 'firebase/firestore';
import { db } from '../../firebase';
import PostCard from './PostCard';
import CreatePost from './CreatePost';
import './Feed.css';

const Feed = ({ authorId = null, showCreatePost = true }) => {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const postsRef = collection(db, 'posts');
    let q;
    
    if (authorId) {
      // Show posts from specific user
      q = query(
        postsRef,
        where('authorId', '==', authorId),
        orderBy('createdAt', 'desc'),
        limit(20)
      );
    } else {
      // Show all posts (feed)
      q = query(
        postsRef,
        orderBy('createdAt', 'desc'),
        limit(50)
      );
    }

    const unsubscribe = onSnapshot(q, 
      (snapshot) => {
        const postsData = snapshot.docs.map(doc => {
          const data = doc.data();
          return {
            id: doc.id,
            ...data,
            likes: Array.isArray(data.likes) ? data.likes : []
          };
        });
        setPosts(postsData);
        setLoading(false);
      },
      (err) => {
        console.error('Error fetching posts:', err);
        setError('Failed to load posts');
        setLoading(false);
      }
    );

    return () => unsubscribe();
  }, [authorId]);

  const handlePostDelete = (postId) => {
    setPosts(posts.filter(post => post.id !== postId));
  };

  if (loading) {
    return <div className="feed-loading">Loading posts...</div>;
  }

  if (error) {
    return <div className="feed-error">{error}</div>;
  }

  return (
    <div className="feed">
      {showCreatePost && <CreatePost />}
      
      <div className="posts-list">
        {posts.length === 0 ? (
          <div className="no-posts">
            {authorId ? "No posts yet" : "No posts to show. Be the first to share something!"}
          </div>
        ) : (
          posts.map(post => (
            <PostCard 
              key={post.id} 
              post={post} 
              onDelete={handlePostDelete}
            />
          ))
        )}
      </div>
    </div>
  );
};

export default Feed;