import React from 'react';
import { Routes } from 'react-router-dom';
import { usePageTracking } from '../hooks/useAnalytics';
import useRouteSeo from '../seo/useRouteSeo';

// Wrapper component to enable page tracking within Router context
const TrackedRoutes = ({ children }) => {
  // Keeps <title>, description, canonical and robots in step with the route.
  // The build pre-bakes these into each generated page; this covers what
  // happens after the SPA takes over navigation.
  //
  // Runs before usePageTracking: effects fire in hook-call order, and the
  // page_view below reports document.title -- so the title has to be the new
  // route's before the event is sent, not the previous page's.
  useRouteSeo();

  // This hook tracks page views as users navigate
  usePageTracking();

  return <Routes>{children}</Routes>;
};

export default TrackedRoutes;
