// Multi-Stream Video Player Component
// Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\components\video\MultiStreamPlayer.jsx

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  Users, 
  Crown, 
  Video, 
  VideoOff, 
  Volume2, 
  VolumeX, 
  Maximize2, 
  Minimize2, 
  Settings,
  Monitor,
  User,
  Eye,
  Mic,
  MicOff,
  Play,
  Square
} from 'lucide-react';
import './MultiStreamPlayer.css';

const MultiStreamPlayer = ({ 
  roomId, 
  streamConfig, 
  onStreamChange, 
  currentUser,
  userCanStream = false 
}) => {
  // Video state
  const [artistStream, setArtistStream] = useState(null);
  const [userStreams, setUserStreams] = useState([]);
  const [audioMixerStream, setAudioMixerStream] = useState(null);
  const [primaryStreamIndex, setPrimaryStreamIndex] = useState(0); // 0 = artist, 1+ = user streams
  
  // Player state
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [volume, setVolume] = useState(0.8);
  const [isMuted, setIsMuted] = useState(false);
  const [showControls, setShowControls] = useState(true);
  
  // User streaming state
  const [isUserStreaming, setIsUserStreaming] = useState(false);
  const [userStreamSlot, setUserStreamSlot] = useState(null);
  const [streamingConfig, setStreamingConfig] = useState({
    video: true,
    audio: true
  });
  
  // Refs
  const primaryVideoRef = useRef(null);
  const secondaryVideoRefs = useRef({});
  const audioMixerRef = useRef(null);
  const localVideoRef = useRef(null);
  const containerRef = useRef(null);
  const controlsTimeoutRef = useRef(null);
  
  // Initialize stream configuration
  useEffect(() => {
    if (streamConfig) {
      console.log('🎬 MultiStreamPlayer initialized for room:', roomId);
      console.log('📺 Stream config received:', streamConfig);
      
      setArtistStream(streamConfig.artistStream);
      setUserStreams(streamConfig.userStreams || []);
      setAudioMixerStream(streamConfig.audioMixer);
    }
  }, [streamConfig, roomId]);

  // Handle stream changes from parent
  useEffect(() => {
    if (onStreamChange && streamConfig) {
      const activeStreams = userStreams.filter(s => s.active);
      const totalActiveStreams = (artistStream?.active ? 1 : 0) + activeStreams.length;
      
      onStreamChange({
        totalStreams: totalActiveStreams,
        artistActive: artistStream?.active || false,
        userStreamsActive: activeStreams.length,
        audioMixerActive: audioMixerStream?.active || false
      });
    }
  }, [artistStream, userStreams, audioMixerStream, onStreamChange, streamConfig]);

  // Auto-hide controls
  const resetControlsTimeout = useCallback(() => {
    if (controlsTimeoutRef.current) {
      clearTimeout(controlsTimeoutRef.current);
    }
    
    setShowControls(true);
    
    controlsTimeoutRef.current = setTimeout(() => {
      if (!isFullscreen) return; // Only auto-hide in fullscreen
      setShowControls(false);
    }, 3000);
  }, [isFullscreen]);

  // Mouse movement handler for controls
  const handleMouseMove = useCallback(() => {
    resetControlsTimeout();
  }, [resetControlsTimeout]);

  // Get primary stream (artist or first active user stream)
  const getPrimaryStream = () => {
    if (primaryStreamIndex === 0 && artistStream?.active) {
      return artistStream;
    }
    
    const activeUserStreams = userStreams.filter(s => s.active);
    const userIndex = primaryStreamIndex - 1;
    
    if (userIndex >= 0 && userIndex < activeUserStreams.length) {
      return activeUserStreams[userIndex];
    }
    
    // Fallback to first available stream
    if (artistStream?.active) return artistStream;
    if (activeUserStreams.length > 0) return activeUserStreams[0];
    
    return null;
  };

  // Get secondary streams (all except primary)
  const getSecondaryStreams = () => {
    const allActiveStreams = [];
    
    if (artistStream?.active) {
      allActiveStreams.push({ ...artistStream, type: 'artist', index: 0 });
    }
    
    userStreams.filter(s => s.active).forEach((stream, index) => {
      allActiveStreams.push({ ...stream, type: 'user', index: index + 1 });
    });
    
    // Remove primary stream from secondary list
    return allActiveStreams.filter((_, index) => index !== primaryStreamIndex);
  };

  // Switch primary stream
  const switchPrimaryStream = (streamIndex) => {
    setPrimaryStreamIndex(streamIndex);
    console.log('🔄 Switched primary stream to index:', streamIndex);
  };

  // Toggle fullscreen
  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      containerRef.current?.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  // Start user streaming
  const startUserStreaming = async () => {
    if (!currentUser || !userCanStream) {
      alert('You do not have permission to stream in this room.');
      return;
    }

    try {
      console.log('🎥 Starting user stream for:', currentUser.uid);
      
      // Get user media
      const stream = await navigator.mediaDevices.getUserMedia({
        video: streamingConfig.video,
        audio: streamingConfig.audio
      });
      
      if (localVideoRef.current) {
        localVideoRef.current.srcObject = stream;
      }
      
      // TODO: Connect to assigned RTMP endpoint
      // This would require integration with the user's assigned stream slot
      
      setIsUserStreaming(true);
      console.log('✅ User streaming started');
      
    } catch (error) {
      console.error('❌ Failed to start user streaming:', error);
      alert('Failed to start streaming. Please check camera and microphone permissions.');
    }
  };

  // Stop user streaming
  const stopUserStreaming = () => {
    if (localVideoRef.current && localVideoRef.current.srcObject) {
      const tracks = localVideoRef.current.srcObject.getTracks();
      tracks.forEach(track => track.stop());
      localVideoRef.current.srcObject = null;
    }
    
    setIsUserStreaming(false);
    console.log('🛑 User streaming stopped');
  };

  // Toggle user video/audio
  const toggleUserVideo = () => {
    setStreamingConfig(prev => ({ ...prev, video: !prev.video }));
  };

  const toggleUserAudio = () => {
    setStreamingConfig(prev => ({ ...prev, audio: !prev.audio }));
  };

  const primaryStream = getPrimaryStream();
  const secondaryStreams = getSecondaryStreams();
  const activeStreamCount = (artistStream?.active ? 1 : 0) + userStreams.filter(s => s.active).length;

  return (
    <div 
      className={`multi-stream-player ${isFullscreen ? 'fullscreen' : ''}`}
      ref={containerRef}
      onMouseMove={handleMouseMove}
    >
      {/* Primary Video Area */}
      <div className="primary-video-area">
        {primaryStream ? (
          <div className="primary-video-container">
            <iframe
              ref={primaryVideoRef}
              src={primaryStream.streamUrl}
              className="primary-video"
              allow="autoplay; camera; microphone; fullscreen"
              allowFullScreen
              title={`${primaryStream.type === 'artist' ? 'Artist' : primaryStream.userName} Stream`}
            />
            
            {/* Stream Info Overlay */}
            <div className="stream-info-overlay">
              <div className="stream-badge">
                {primaryStream.type === 'artist' ? (
                  <>
                    <Crown size={16} />
                    <span>Artist</span>
                  </>
                ) : (
                  <>
                    <User size={16} />
                    <span>{primaryStream.userName}</span>
                  </>
                )}
              </div>
              
              <div className="stream-stats">
                <Eye size={14} />
                <span>{activeStreamCount} streaming</span>
              </div>
            </div>
          </div>
        ) : (
          <div className="no-primary-stream">
            <Monitor size={64} />
            <h3>No Active Streams</h3>
            <p>Waiting for someone to start streaming...</p>
            
            {userCanStream && !isUserStreaming && (
              <button 
                className="start-streaming-btn"
                onClick={startUserStreaming}
              >
                <Video size={20} />
                Start Streaming
              </button>
            )}
          </div>
        )}
      </div>

      {/* Secondary Streams Grid */}
      {secondaryStreams.length > 0 && (
        <div className="secondary-streams-grid">
          {secondaryStreams.map((stream, index) => (
            <div 
              key={`${stream.type}-${stream.index}`}
              className="secondary-stream-container"
              onClick={() => switchPrimaryStream(stream.index)}
            >
              <iframe
                ref={el => secondaryVideoRefs.current[`${stream.type}-${stream.index}`] = el}
                src={stream.streamUrl}
                className="secondary-video"
                allow="autoplay; camera; microphone"
                title={`${stream.type === 'artist' ? 'Artist' : stream.userName} Stream`}
              />
              
              <div className="secondary-stream-overlay">
                {stream.type === 'artist' ? (
                  <Crown size={12} />
                ) : (
                  <span className="user-name">{stream.userName}</span>
                )}
              </div>
            </div>
          ))}
          
          {/* Show empty slots */}
          {userStreams.filter(s => s.available).slice(0, 3).map((slot, index) => (
            <div key={`empty-${slot.slot}`} className="empty-stream-slot">
              <User size={24} />
              <span>Available</span>
            </div>
          ))}
        </div>
      )}

      {/* User Streaming Controls */}
      {userCanStream && (
        <div className="user-streaming-controls">
          {!isUserStreaming ? (
            <button 
              className="start-stream-btn"
              onClick={startUserStreaming}
            >
              <Video size={16} />
              Start Streaming
            </button>
          ) : (
            <div className="streaming-controls-active">
              <button 
                className="stop-stream-btn"
                onClick={stopUserStreaming}
              >
                <Square size={16} />
                Stop
              </button>
              
              <button 
                className={`control-btn ${streamingConfig.video ? 'active' : ''}`}
                onClick={toggleUserVideo}
              >
                {streamingConfig.video ? <Video size={16} /> : <VideoOff size={16} />}
              </button>
              
              <button 
                className={`control-btn ${streamingConfig.audio ? 'active' : ''}`}
                onClick={toggleUserAudio}
              >
                {streamingConfig.audio ? <Mic size={16} /> : <MicOff size={16} />}
              </button>
            </div>
          )}
          
          {/* Local Video Preview */}
          {isUserStreaming && (
            <div className="local-video-preview">
              <video 
                ref={localVideoRef}
                autoPlay
                muted
                className="local-video"
              />
              <span className="preview-label">You</span>
            </div>
          )}
        </div>
      )}

      {/* Audio Mixer (Hidden but playing) */}
      {audioMixerStream?.active && (
        <audio
          ref={audioMixerRef}
          src={audioMixerStream.streamUrl}
          autoPlay
          volume={volume}
          muted={isMuted}
          style={{ display: 'none' }}
        />
      )}

      {/* Video Controls */}
      <div className={`video-controls ${showControls ? 'visible' : 'hidden'}`}>
        <div className="controls-left">
          <button onClick={() => setIsMuted(!isMuted)}>
            {isMuted ? <VolumeX size={20} /> : <Volume2 size={20} />}
          </button>
          
          <input
            type="range"
            min="0"
            max="1"
            step="0.1"
            value={volume}
            onChange={(e) => setVolume(parseFloat(e.target.value))}
            className="volume-slider"
          />
          
          <div className="stream-count">
            <Users size={16} />
            <span>{activeStreamCount}</span>
          </div>
        </div>
        
        <div className="controls-center">
          {/* Stream switching buttons */}
          {artistStream?.active && (
            <button 
              className={`stream-switch-btn ${primaryStreamIndex === 0 ? 'active' : ''}`}
              onClick={() => switchPrimaryStream(0)}
            >
              <Crown size={16} />
              Artist
            </button>
          )}
          
          {userStreams.filter(s => s.active).map((stream, index) => (
            <button
              key={stream.slot}
              className={`stream-switch-btn ${primaryStreamIndex === index + 1 ? 'active' : ''}`}
              onClick={() => switchPrimaryStream(index + 1)}
            >
              <User size={16} />
              {stream.userName}
            </button>
          ))}
        </div>
        
        <div className="controls-right">
          <button onClick={toggleFullscreen}>
            {isFullscreen ? <Minimize2 size={20} /> : <Maximize2 size={20} />}
          </button>
          
          <button>
            <Settings size={20} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default MultiStreamPlayer;
