import React, { useState, useEffect, useRef } from 'react';
import { Trash, Plus, Eye, EyeOff, Upload, Link, AlertTriangle, Info, ExternalLink, ImagePlus } from 'lucide-react';
import { useSiteConfig } from '../contexts/SiteConfigContext';
import { storage } from '../firebase';
import { ref, uploadBytes, getDownloadURL, deleteObject } from 'firebase/storage';
import { runStorageDiagnostic } from '../utils/storageDebugger';
import { testStorageConnection } from '../utils/storageTester';
import { validateImageUrl, isAdobeStockUrl, fixAdobeStockUrl } from '../utils/imageValidator';

// Component for testing Storage connectivity
const StorageStatusTester = () => {
  const [status, setStatus] = useState('checking');
  const [rulesStatus, setRulesStatus] = useState(null);
  const [testUrl, setTestUrl] = useState(null);
  
  useEffect(() => {
    const checkStorage = async () => {
      try {
        if (!storage || !storage.app) {
          setStatus('unavailable');
          return;
        }
        
        // Try to get the storage bucket
        const bucket = storage.app.options?.storageBucket;
        console.log('Storage bucket from component:', bucket);
        
        if (bucket) {
          setStatus('available');
          
          // Test write access to backgrounds folder
          try {
            // Test connection by uploading a small file
            const testResult = await testStorageConnection();
            
            if (testResult.success) {
              setRulesStatus('writable');
              setTestUrl(testResult.url);
            } else {
              if (testResult.error?.code === 'storage/unauthorized') {
                setRulesStatus('unauthorized');
              } else {
                setRulesStatus('error');
              }
            }
          } catch (rulesError) {
            console.error('Storage permissions test failed:', rulesError);
            if (rulesError.code === 'storage/unauthorized') {
              setRulesStatus('unauthorized');
            } else {
              setRulesStatus('error');
            }
          }
        } else {
          setStatus('no-bucket');
        }
      } catch (error) {
        console.error('Storage test error:', error);
        setStatus('error');
      }
    };
    
    checkStorage();
  }, []);
  
  if (status === 'checking') return (
    <div className="text-xs text-gray-500">Checking storage...</div>
  );
  
  if (status === 'available') {
    if (rulesStatus === 'writable') {
      return (
        <div>
          <div className="text-xs text-green-500 mb-1">Storage ready and writable ✓</div>
          {testUrl && (
            <div className="text-xs flex items-center">
              <span className="mr-1">Test URL:</span>
              <a href={testUrl} target="_blank" rel="noopener noreferrer" className="text-blue-500 flex items-center">
                View test file <ExternalLink size={12} className="ml-1" />
              </a>
            </div>
          )}
        </div>
      );
    } else if (rulesStatus === 'unauthorized') {
      return (
        <div className="text-xs text-red-500">
          Storage ready but you don't have permission to upload ❌
          <div className="mt-1 text-xs text-amber-500">
            Please check Firebase Storage rules for backgrounds/ folder.
          </div>
        </div>
      );
    } else if (rulesStatus === 'error') {
      return <div className="text-xs text-amber-500">Storage ready but encountered errors testing write access ⚠️</div>;
    } else {
      return <div className="text-xs text-blue-500">Storage ready, checking write access...</div>;
    }
  }
  
  if (status === 'no-bucket') return <div className="text-xs text-yellow-500">Storage missing bucket ⚠️</div>;
  if (status === 'error') return <div className="text-xs text-red-500">Storage error ⚠️</div>;
  return <div className="text-xs text-red-500">Storage unavailable ✗</div>;
};

const BackgroundManager = () => {
  const { config, updateConfig } = useSiteConfig();
  const [uploading, setUploading] = useState(false);
  const [showUrlInput, setShowUrlInput] = useState(false);
  const [urlInput, setUrlInput] = useState('');
  const [errorMessage, setErrorMessage] = useState(''); // Added for better error display
  const [successMessage, setSuccessMessage] = useState('');
  const fileInputRef = useRef(null);
  
  // Clear messages after some time
  useEffect(() => {
    if (errorMessage) {
      const timer = setTimeout(() => setErrorMessage(''), 7000);
      return () => clearTimeout(timer);
    }
  }, [errorMessage]);
  
  useEffect(() => {
    if (successMessage) {
      const timer = setTimeout(() => setSuccessMessage(''), 5000);
      return () => clearTimeout(timer);
    }
  }, [successMessage]);
  
  // Handle file upload
  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    
    // Clear previous messages
    setErrorMessage('');
    setSuccessMessage('');
    setUploading(true);
    
    console.log('File selected for upload:', file.name, file.type, Math.round(file.size / 1024), 'KB');
    
    try {
      // Validate file size (max 5MB)
      if (file.size > 5 * 1024 * 1024) {
        throw new Error('File size exceeds 5MB limit. Please choose a smaller file.');
      }
      
      // Validate file type
      const validTypes = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
      if (!validTypes.includes(file.type)) {
        throw new Error('Invalid file type. Please use JPEG, PNG, GIF, or WEBP formats.');
      }
      
      // Create a new background object with a unique ID
      const timestamp = Date.now();
      const newBg = {
        id: `bg_${timestamp}`,
        name: file.name.split('.')[0] || `Background ${config.backgrounds?.length + 1 || 1}`,
        isActive: false,
        type: 'image'
      };
      
      // Sanitize the filename to avoid storage path issues
      const sanitizedFileName = file.name.replace(/[^a-zA-Z0-9.]/g, '_').toLowerCase();
      
      // Check if storage is properly initialized
      if (!storage || !storage.app) {
        throw new Error('Firebase Storage is not properly initialized. Please refresh the page and try again.');
      }
      
      console.log('Initializing Storage...', storage.app.options.storageBucket);
      
      // Create storage reference with sanitized path including timestamp to avoid caching issues
      const fullPath = `backgrounds/bg_${timestamp}_${sanitizedFileName}`;
      const storageRef = ref(storage, fullPath);
      console.log('Storage reference created:', storageRef.fullPath);
      
      // Upload the file with better error handling
      console.log('Uploading file to path:', fullPath);
      const metadata = {
        contentType: file.type,
        customMetadata: {
          uploadedBy: 'BackgroundManager',
          originalName: file.name,
          timestamp: new Date().toISOString()
        }
      };
      
      const snapshot = await uploadBytes(storageRef, file, metadata);
      console.log('Upload completed successfully:', snapshot);
      
      // Get the download URL
      console.log('Getting download URL...');
      const downloadURL = await getDownloadURL(snapshot.ref);
      console.log('Download URL obtained:', downloadURL);
      
      // Add the URL to the background object
      const uploadedBg = {
        ...newBg,
        url: downloadURL,
        storagePath: snapshot.ref.fullPath
      };
      
      // Update the config
      const updatedConfig = {
        ...config,
        backgrounds: [...(config.backgrounds || []), uploadedBg]
      };
      
      // Update in context (but don't save to Firebase yet)
      console.log('Saving to configuration...');
      const success = await updateConfig(updatedConfig);
      
      if (!success) {
        throw new Error('Failed to save updated configuration. The image was uploaded but couldn\'t be saved to the application settings.');
      }
      
      setSuccessMessage('Background image uploaded and added successfully!');
      console.log('Background successfully added to configuration');
      
    } catch (error) {
      console.error('Error uploading background:', error);
      
      // Improved error message with more detail
      let errorMsg = 'Failed to upload background image';
      
      if (error.code) {
        // Handle specific Firebase error codes
        switch (error.code) {
          case 'storage/unauthorized':
            errorMsg = 'You don\'t have permission to upload images. Firebase Storage rules may be restricting uploads.';
            break;
          case 'storage/canceled':
            errorMsg = 'Upload was canceled.';
            break;
          case 'storage/unknown':
            errorMsg = 'An unknown Firebase Storage error occurred. Check your Firebase Storage configuration and permissions.';
            break;
          case 'storage/quota-exceeded':
            errorMsg = 'Firebase Storage quota exceeded. You may need to upgrade your Firebase plan or delete some existing files.';
            break;
          default:
            errorMsg = `Upload failed: ${error.message || error.code}`;
            break;
        }
      } else {
        errorMsg = error.message || 'Unknown error';
      }
      
      setErrorMessage(errorMsg);
      
      // Log additional error details
      if (error.serverResponse) {
        console.error('Server response:', error.serverResponse);
      }
    } finally {
      setUploading(false);
      // Reset file input
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  // Test an image URL
  const testImageUrl = async (urlToTest) => {
    setErrorMessage('');
    setSuccessMessage('');
    setUploading(true);
    
    try {
      if (!urlToTest.trim()) {
        throw new Error('Please enter a URL to test');
      }
      
      console.log('Testing image URL:', urlToTest);
      
      // Check if it's an Adobe Stock URL
      if (isAdobeStockUrl(urlToTest)) {
        console.log('Detected Adobe Stock/Fotolia URL');
      }
      
      // Validate the image
      const result = await validateImageUrl(urlToTest);
      
      if (result.success) {
        setSuccessMessage(`Image URL is valid! Size: ${result.width}x${result.height}`);
      } else {
        setErrorMessage(`Image URL test failed: ${result.error}`);
      }
    } catch (error) {
      console.error('Error testing image URL:', error);
      setErrorMessage(`Error testing image: ${error.message}`);
    } finally {
      setUploading(false);
    }
  };
  
  // Handle URL input submission
  const handleUrlSubmit = async (e) => {
    e.preventDefault();
    
    setErrorMessage('');
    setSuccessMessage('');
    setUploading(true); // Set uploading to true to show loading state
    
    try {
      if (!urlInput.trim()) {
        throw new Error('Please enter a valid URL');
      }
      
      // Validate URL format
      let url;
      try {
        url = new URL(urlInput.trim());
      } catch (urlError) {
        throw new Error('Invalid URL format. Please enter a complete URL including http:// or https://');
      }
      
      // Check if it's an Adobe Stock URL and fix if needed
      let finalUrl = url.href;
      if (isAdobeStockUrl(finalUrl)) {
        console.log('Detected Adobe Stock/Fotolia URL, applying special handling');
      }
      
      // Test if the image can actually be loaded
      console.log('Testing URL image loading:', finalUrl);
      const validationResult = await validateImageUrl(finalUrl);
      
      if (!validationResult.success) {
        throw new Error(`Could not load image: ${validationResult.error}`);
      }
      
      // Create a new background object
      const timestamp = Date.now();
      const newBg = {
        id: `bg_${timestamp}`,
        name: `Background ${config.backgrounds?.length + 1 || 1}`,
        url: finalUrl, // Use the potentially fixed URL
        type: 'image',
        isActive: false
      };
      
      // Update the config
      const updatedConfig = {
        ...config,
        backgrounds: [...(config.backgrounds || []), newBg]
      };
      
      // Update in context with await to catch any errors
      const success = await updateConfig(updatedConfig);
      
      if (!success) {
        throw new Error('Failed to save configuration. Please try again.');
      }
      
      setSuccessMessage('Background URL successfully added!');
      console.log('Background URL successfully added:', finalUrl);
      
      // Reset form
      setUrlInput('');
      setShowUrlInput(false);
    } catch (error) {
      console.error('Error adding URL background:', error);
      setErrorMessage(`Failed to add background: ${error.message}`);
    } finally {
      setUploading(false);
    }
  };
  
  // Toggle background active state
  const toggleBackgroundActive = (id) => {
    if (!config) return;
    
    const updatedBackgrounds = (config.backgrounds || []).map(bg => ({
      ...bg,
      isActive: bg.id === id
    }));
    
    updateConfig({
      ...config,
      backgrounds: updatedBackgrounds
    });
    
    setSuccessMessage('Background set as active');
  };
  
  // Remove background
  const removeBackground = async (id) => {
    if (!config) return;
    
    setErrorMessage('');
    setSuccessMessage('');
    
    // Find the background to remove
    const bgToRemove = (config.backgrounds || []).find(bg => bg.id === id);
    
    // Don't allow removing the active background
    if (bgToRemove && bgToRemove.isActive) {
      setErrorMessage('Cannot remove the active background. Set another background as active first.');
      return;
    }
    
    if (!window.confirm('Are you sure you want to remove this background?')) {
      return;
    }
    
    try {
      // Delete from Firebase Storage if there's a storage path
      if (bgToRemove && bgToRemove.storagePath) {
        try {
          const fileRef = ref(storage, bgToRemove.storagePath);
          await deleteObject(fileRef);
          console.log('Background file deleted from storage');
        } catch (storageError) {
          console.warn('Error deleting storage file:', storageError.message);
          // Continue with removal from config even if storage delete fails
        }
      }
      
      // Update the config
      const updatedConfig = {
        ...config,
        backgrounds: (config.backgrounds || []).filter(bg => bg.id !== id)
      };
      
      // Update in context
      await updateConfig(updatedConfig);
      setSuccessMessage('Background removed successfully');
    } catch (error) {
      console.error('Error removing background:', error);
      setErrorMessage(`Failed to remove background image: ${error.message}`);
    }
  };
  
  if (!config) {
    return <div>Loading...</div>;
  }
  
  return (
    <div>
      <div>
        <div className="flex justify-between items-center mb-6">
          <div>
            <h2 className="text-xl font-bold text-gray-800">Manage Background Images</h2>
            <StorageStatusTester />
          </div>
          <div className="flex gap-2">
            <button
              onClick={() => fileInputRef.current.click()}
              className="bg-indigo-600 text-white px-4 py-2 rounded-md flex items-center hover:bg-indigo-700"
              disabled={uploading}
            >
              <Upload className="mr-2" size={18} />
              {uploading ? 'Uploading...' : 'Upload Image'}
              <input 
                ref={fileInputRef}
                type="file" 
                accept="image/jpeg,image/png,image/gif,image/webp" 
                className="hidden" 
                onChange={handleFileUpload}
                disabled={uploading}
              />
            </button>
            <button
              onClick={() => setShowUrlInput(!showUrlInput)}
              className="bg-gray-100 text-gray-700 px-4 py-2 rounded-md flex items-center hover:bg-gray-200"
              disabled={uploading}
            >
              <Link className="mr-2" size={18} />
              Add from URL
            </button>
            <button
              onClick={() => {
                runStorageDiagnostic();
                alert('Running Firebase Storage diagnostic. Check browser console for results.');
              }}
              className="bg-amber-100 text-amber-700 px-3 py-2 rounded-md flex items-center hover:bg-amber-200"
              title="Run Firebase Storage diagnostic"
            >
              <AlertTriangle className="mr-1" size={16} />
              Diagnose
            </button>
          </div>
        </div>
      </div>
      
      {/* Error Message Display */}
      {errorMessage && (
        <div className="mb-4 p-4 bg-red-50 text-red-700 rounded-md">
          {errorMessage}
        </div>
      )}
      
      {/* Success Message Display */}
      {successMessage && (
        <div className="mb-4 p-4 bg-green-50 text-green-700 rounded-md">
          {successMessage}
        </div>
      )}
      
      {/* URL Input Form */}
      {showUrlInput && (
        <div className="mb-6 p-4 bg-gray-50 rounded-lg border border-gray-200">
          <form onSubmit={handleUrlSubmit} className="flex items-end gap-2">
            <div className="flex-grow">
              <label htmlFor="url-input" className="block text-sm font-medium text-gray-700 mb-1">
                Image URL
              </label>
              <div className="relative">
                <input
                  id="url-input"
                  type="url"
                  placeholder="https://example.com/image.jpg"
                  value={urlInput}
                  onChange={(e) => setUrlInput(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
                  required
                />
                {isAdobeStockUrl(urlInput) && (
                  <div className="absolute right-2 top-2 bg-amber-100 text-amber-700 text-xs px-2 py-1 rounded">
                    Adobe Stock URL
                  </div>
                )}
              </div>
            </div>
            <button
              type="button"
              onClick={() => testImageUrl(urlInput)}
              className="px-3 py-2 bg-blue-100 text-blue-700 rounded-md hover:bg-blue-200 flex items-center"
              disabled={uploading || !urlInput.trim()}
            >
              <ImagePlus className="mr-1" size={16} />
              Test URL
            </button>
            <button
              type="submit"
              className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700"
              disabled={uploading}
            >
              Add
            </button>
            <button
              type="button"
              onClick={() => setShowUrlInput(false)}
              className="px-4 py-2 border border-gray-300 text-gray-700 rounded-md hover:bg-gray-100"
              disabled={uploading}
            >
              Cancel
            </button>
          </form>
        </div>
      )}
      
      {/* Loading indicator */}
      {uploading && (
        <div className="mb-4 p-4 bg-indigo-50 text-indigo-700 rounded-md flex items-center">
          <div className="animate-spin rounded-full h-4 w-4 border-t-2 border-b-2 border-indigo-700 mr-2"></div>
          Uploading background image...
        </div>
      )}
      
      {/* Backgrounds Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {(config.backgrounds?.length || 0) > 0 ? (
          (config.backgrounds || []).map(bg => (
            <div key={bg.id} className="border rounded-lg overflow-hidden bg-white shadow-sm">
              {bg.type === 'color' ? (
                <div 
                  className="h-48"
                  style={{ backgroundColor: bg.color }}
                />
              ) : (
                <div className="relative h-48">
                  <div 
                    className="h-48 bg-cover bg-center absolute inset-0"
                    style={{ backgroundImage: `url(${bg.url})` }}
                  />
                  <div className="absolute bottom-0 right-0 p-1 bg-black bg-opacity-50 text-white text-xs">
                    {bg.url && bg.url.substring(0, 25)}...
                  </div>
                </div>
              )}
              <div className="p-4">
                <div className="flex justify-between items-center mb-2">
                  <h3 className="font-medium text-gray-800">{bg.name}</h3>
                  <div className="flex space-x-2">
                    {bg.type === 'image' && (
                      <button
                        onClick={() => testImageUrl(bg.url)}
                        className="p-2 rounded-full bg-blue-100 text-blue-600"
                        title="Test URL"
                      >
                        <ImagePlus size={18} />
                      </button>
                    )}
                    <button
                      onClick={() => toggleBackgroundActive(bg.id)}
                      className={`p-2 rounded-full ${
                        bg.isActive 
                          ? 'bg-green-100 text-green-600' 
                          : 'bg-gray-100 text-gray-600'
                      }`}
                      title={bg.isActive ? 'Active' : 'Set as active'}
                    >
                      {bg.isActive ? <Eye size={18} /> : <EyeOff size={18} />}
                    </button>
                    <button
                      onClick={() => removeBackground(bg.id)}
                      className={`p-2 rounded-full ${
                        bg.isActive 
                          ? 'bg-gray-200 text-gray-400' 
                          : 'bg-red-100 text-red-600'
                      }`}
                      title="Delete background"
                      disabled={bg.isActive}
                    >
                      <Trash size={18} />
                    </button>
                  </div>
                </div>
                
                {/* Adobe Stock Indicator */}
                {bg.type === 'image' && isAdobeStockUrl(bg.url) && (
                  <div className="mb-2 py-1 px-2 bg-amber-50 text-amber-700 text-xs rounded inline-block">
                    Adobe Stock URL
                  </div>
                )}
                
                {bg.type === 'color' ? (
                  <p className="text-xs text-gray-500">{bg.color}</p>
                ) : (
                  <p className="text-xs text-gray-500 truncate">{bg.url}</p>
                )}
                
                {bg.storagePath && (
                  <p className="text-xs text-gray-400 truncate">
                    Storage path: {bg.storagePath}
                  </p>
                )}
                
                {bg.isActive && (
                  <div className="mt-2 text-sm text-green-600 font-medium">
                    Currently active
                  </div>
                )}
              </div>
            </div>
          ))
        ) : (
          <div className="col-span-2 bg-gray-50 p-8 text-center rounded-lg border border-dashed border-gray-300">
            <p className="text-gray-500">No background images added yet. Upload an image or add from URL.</p>
          </div>
        )}
      </div>
      
      {/* Firebase Storage Rules Reference */}
      <div className="mt-8 p-4 bg-gray-50 rounded-lg border border-gray-200">
        <h3 className="text-md font-medium mb-2 text-gray-800">Firebase Storage Rules Reference</h3>
        <pre className="bg-gray-100 p-3 rounded-md text-xs overflow-auto">
{`rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    // Allow development access (CHANGE FOR PRODUCTION!)
    match /backgrounds/{fileName} {
      allow read: if true; // Anyone can view backgrounds
      allow write: if true; // For development - CHANGE THIS FOR PRODUCTION!
    }
    
    // Users directory
    match /users/{userId}/{fileName} {
      allow read: if true;
      allow write: if true; // For development - CHANGE THIS FOR PRODUCTION!
    }
    
    // Posts directory
    match /posts/{postId}/{fileName} {
      allow read: if true;
      allow write: if true; // For development - CHANGE THIS FOR PRODUCTION!
    }
    
    // Test directory for connectivity tests
    match /test/{fileName} {
      allow read, write: if true;
    }
  }
}`}
        </pre>
        <p className="mt-2 text-xs text-gray-600">
          Your current Firebase Storage rules should match the above. If you're having issues with uploads or access,
          please verify your rules in the Firebase Console.
        </p>
      </div>
    </div>
  );
};

export default BackgroundManager;