// src/pages/ArtistShowcasePage.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getFirestore, collection, getDocs, query, where, limit, orderBy, onSnapshot } from 'firebase/firestore';
import { Calendar, Music, Users, Clock, MapPin, Search, Star, Crown, DollarSign, Eye } from 'lucide-react';

const ArtistShowcasePage = () => {
  const [upcomingEvents, setUpcomingEvents] = useState([]);
  const [featuredArtists, setFeaturedArtists] = useState([]);
  const [artistsWithEvents, setArtistsWithEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [isSearching, setIsSearching] = useState(false);
  const [showSearchResults, setShowSearchResults] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const db = getFirestore();
        
        // Get current timestamp for filtering upcoming events
        const now = Date.now();
        
        // Fetch upcoming events from our events system
        const eventsQuery = query(
          collection(db, 'events'),
          where('startTime', '>', now),
          where('status', '==', 'scheduled'),
          orderBy('startTime', 'asc'),
          limit(12)
        );
        
        const eventsSnapshot = await getDocs(eventsQuery);
        const eventsData = eventsSnapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        }));
        
        setUpcomingEvents(eventsData);
        
        // Get unique artists with upcoming events
        const artistIds = [...new Set(eventsData.map(event => event.artistId))];
        const artistsWithEventsData = [];
        
        for (const artistId of artistIds.slice(0, 8)) {
          try {
            // Get artist user data
            const userQuery = query(
              collection(db, 'users'),
              where('__name__', '==', artistId)
            );
            const userSnapshot = await getDocs(userQuery);
            
            if (!userSnapshot.empty) {
              const userData = userSnapshot.docs[0].data();
              
              // Get artist profile data if exists
              const artistQuery = query(
                collection(db, 'artists'),
                where('__name__', '==', artistId)
              );
              const artistSnapshot = await getDocs(artistQuery);
              const artistData = artistSnapshot.empty ? {} : artistSnapshot.docs[0].data();
              
              // Count upcoming events for this artist
              const artistEventsCount = eventsData.filter(event => event.artistId === artistId).length;
              
              artistsWithEventsData.push({
                id: artistId,
                ...userData,
                ...artistData,
                upcomingEventsCount: artistEventsCount
              });
            }
          } catch (err) {
            console.error(`Error fetching artist ${artistId}:`, err);
          }
        }
        
        setArtistsWithEvents(artistsWithEventsData);
        
        // Fetch featured artists (those marked as featured by admin)
        const featuredUsersQuery = query(
          collection(db, 'users'),
          where('isArtist', '==', true),
          where('isFeatured', '==', true),
          limit(8)
        );
        
        const featuredUsersSnapshot = await getDocs(featuredUsersQuery);
        const featuredArtistsData = [];
        
        for (const doc of featuredUsersSnapshot.docs) {
          const userData = doc.data();

          // Get artist profile data if exists
          try {
            const artistQuery = query(
              collection(db, 'artists'),
              where('__name__', '==', doc.id)
            );
            const artistSnapshot = await getDocs(artistQuery);
            const artistData = artistSnapshot.empty ? {} : artistSnapshot.docs[0].data();

            // Count upcoming events for this featured artist
            const artistEventsCount = eventsData.filter(event => event.artistId === doc.id).length;

            // Query for all upcoming events if not in current events list
            let totalEventsCount = artistEventsCount;
            if (artistEventsCount === 0) {
              try {
                const artistEventsQuery = query(
                  collection(db, 'events'),
                  where('artistId', '==', doc.id),
                  where('startTime', '>', now),
                  where('status', '==', 'scheduled')
                );
                const artistEventsSnapshot = await getDocs(artistEventsQuery);
                totalEventsCount = artistEventsSnapshot.size;
              } catch (err) {
                console.error(`Error counting events for artist ${doc.id}:`, err);
              }
            }

            featuredArtistsData.push({
              id: doc.id,
              ...userData,
              ...artistData,
              upcomingEventsCount: totalEventsCount
            });
          } catch (err) {
            console.error(`Error fetching featured artist ${doc.id}:`, err);
            // Add user data even if artist profile fails
            featuredArtistsData.push({
              id: doc.id,
              ...userData,
              upcomingEventsCount: 0
            });
          }
        }
        
        setFeaturedArtists(featuredArtistsData);
        
      } catch (err) {
        console.error('Error fetching showcase data:', err);
        setError('Failed to load showcase. Please try again later.');
      } finally {
        setLoading(false);
      }
    };
    
    fetchData();
  }, []);

  // Format date for display
  const formatDate = (timestamp) => {
    const date = new Date(timestamp);
    return new Intl.DateTimeFormat('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit'
    }).format(date);
  };

  // Get access level display info
  const getAccessLevelInfo = (event) => {
    switch (event.accessLevel) {
      case 'vip':
        return { icon: <Crown className="text-yellow-500" />, text: 'VIP Only', color: 'text-yellow-600' };
      case 'premium':
        return { icon: <Crown className="text-purple-500" />, text: 'Premium', color: 'text-purple-600' };
      case 'ticket':
        return { icon: <DollarSign className="text-green-500" />, text: `${event.ticketPrice}`, color: 'text-green-600' };
      case 'free':
        return { icon: <Users className="text-gray-500" />, text: 'Free', color: 'text-gray-600' };
      default:
        return { icon: <Crown className="text-purple-500" />, text: 'Premium', color: 'text-purple-600' };
    }
  };

  // Search for artists
  const searchArtists = async () => {
    if (!searchQuery.trim()) {
      setSearchResults([]);
      setShowSearchResults(false);
      return;
    }

    setIsSearching(true);
    try {
      const db = getFirestore();
      
      // Search in users collection for artists
      const usersQuery = query(
        collection(db, 'users'),
        where('isArtist', '==', true)
      );
      
      const usersSnapshot = await getDocs(usersQuery);
      const artists = [];
      
      usersSnapshot.docs.forEach(doc => {
        const userData = doc.data();
        const searchLower = searchQuery.toLowerCase();
        
        // Search by displayName, username, or email
        if ((userData.displayName && userData.displayName.toLowerCase().includes(searchLower)) ||
            (userData.username && userData.username.toLowerCase().includes(searchLower)) ||
            (userData.email && userData.email.toLowerCase().includes(searchLower))) {
          artists.push({
            id: doc.id,
            ...userData
          });
        }
      });
      
      setSearchResults(artists);
      setShowSearchResults(true);
    } catch (err) {
      console.error('Error searching artists:', err);
      setError('Failed to search artists. Please try again.');
    } finally {
      setIsSearching(false);
    }
  };

  // Handle search form submission
  const handleSearchSubmit = (e) => {
    e.preventDefault();
    searchArtists();
  };

  // Handle search input change
  const handleSearchChange = (e) => {
    setSearchQuery(e.target.value);
    if (!e.target.value.trim()) {
      setSearchResults([]);
      setShowSearchResults(false);
    }
  };

  return (
    <div className="artist-showcase-page">
      <div className="showcase-header">
        <h1>Artist Showcase</h1>
        <p className="subtitle">Discover upcoming events and featured artists</p>
        
        {/* Search Bar */}
        <div className="search-section">
          <form onSubmit={handleSearchSubmit} className="search-form">
            <div className="search-input-wrapper">
              <Search size={20} className="search-icon" />
              <input
                type="text"
                placeholder="Search for artists by name or username..."
                value={searchQuery}
                onChange={handleSearchChange}
                className="search-input"
              />
              <button type="submit" className="search-button" disabled={isSearching}>
                {isSearching ? 'Searching...' : 'Search'}
              </button>
            </div>
          </form>
        </div>
      </div>
      
      {error && <div className="error-message">{error}</div>}
      
      {/* Search Results Section */}
      {showSearchResults && (
        <section className="search-results-section">
          <div className="section-header">
            <h2>Search Results ({searchResults.length})</h2>
            <button 
              className="clear-search-button"
              onClick={() => {
                setSearchQuery('');
                setSearchResults([]);
                setShowSearchResults(false);
              }}
            >
              Clear Search
            </button>
          </div>
          
          {searchResults.length > 0 ? (
            <div className="search-results-grid">
              {searchResults.map(artist => (
                <div className="artist-search-card" key={artist.id}>
                  <div 
                    className="artist-avatar" 
                    style={{ 
                      backgroundImage: artist.photoURL 
                        ? `url(${artist.photoURL})` 
                        : 'linear-gradient(45deg, #7c3aed, #ec4899)'
                    }}
                  >
                    {!artist.photoURL && (
                      <span className="avatar-placeholder">
                        {artist.displayName?.charAt(0) || artist.username?.charAt(0) || 'A'}
                      </span>
                    )}
                  </div>
                  <div className="artist-search-content">
                    <h3>{artist.displayName || artist.username || 'Artist'}</h3>
                    <p className="artist-username">@{artist.username || 'unknown'}</p>
                    {artist.location && (
                      <div className="artist-detail">
                        <MapPin size={16} />
                        <span>{artist.location}</span>
                      </div>
                    )}
                    <button 
                      className="view-artist-profile-button"
                      onClick={() => navigate(`/artist/${artist.id}`)}
                    >
                      View Profile
                    </button>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="no-search-results">
              <p>No artists found matching "{searchQuery}"</p>
            </div>
          )}
        </section>
      )}
      
      {/* Only show other sections if not showing search results */}
      {!showSearchResults && (
        <>
          {/* Upcoming Events Section */}
          <section className="events-section">
            <div className="section-header">
              <h2>Upcoming Events</h2>
              <button 
                className="view-all-button"
                onClick={() => navigate('/events')}
              >
                View All
              </button>
            </div>
            
            {loading ? (
              <div className="loading-indicator">Loading events...</div>
            ) : upcomingEvents.length > 0 ? (
              <div className="events-grid">
                {upcomingEvents.map(event => {
                  const accessInfo = getAccessLevelInfo(event);
                  return (
                    <div className="event-card" key={event.id}>
                      <div className="event-header">
                        <div className="event-badge">
                          {accessInfo.icon}
                          <span className={accessInfo.color}>{accessInfo.text}</span>
                        </div>
                        {event.viewerCount > 0 && (
                          <div className="viewer-count">
                            <Eye size={14} />
                            <span>{event.viewerCount}</span>
                          </div>
                        )}
                      </div>
                      <div className="event-content">
                        <h3>{event.title}</h3>
                        {event.description && (
                          <p className="event-description">{event.description}</p>
                        )}
                        <div className="event-details">
                          <div className="event-detail">
                            <Calendar size={16} />
                            <span>{formatDate(event.startTime)}</span>
                          </div>
                          <div className="event-detail">
                            <Clock size={16} />
                            <span>{event.duration} minutes</span>
                          </div>
                          <div className="event-detail">
                            <Music size={16} />
                            <span>{event.artistName}</span>
                          </div>
                          <div className="event-detail">
                            <Users size={16} />
                            <span>Max {event.maxViewers} viewers</span>
                          </div>
                        </div>
                        <button 
                          className="view-event-button"
                          onClick={() => navigate(`/events/${event.id}`)}
                        >
                          View Event Details
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            ) : (
              <div className="no-events-message">
                <p>No upcoming events found. Check back soon!</p>
              </div>
            )}
          </section>
          
          {/* Artists with Upcoming Events Section */}
          <section className="artists-section">
            <div className="section-header">
              <h2>Artists with Upcoming Events</h2>
              <button 
                className="view-all-button"
                onClick={() => navigate('/events')}
              >
                View All Events
              </button>
            </div>
            
            {loading ? (
              <div className="loading-indicator">Loading artists...</div>
            ) : artistsWithEvents.length > 0 ? (
              <div className="artists-grid">
                {artistsWithEvents.map(artist => (
                  <div className="artist-card" key={artist.id}>
                    <div 
                      className="artist-image" 
                      style={{ 
                        backgroundImage: artist.photoURL || artist.profileImage
                          ? `url(${artist.photoURL || artist.profileImage})` 
                          : 'linear-gradient(45deg, #7c3aed, #ec4899)'
                      }}
                    >
                      {(!artist.photoURL && !artist.profileImage) && (
                        <div className="artist-placeholder">
                          {(artist.displayName || artist.artistName || 'A').charAt(0)}
                        </div>
                      )}
                    </div>
                    <div className="artist-content">
                      <h3>{artist.displayName || artist.artistName || 'Unknown Artist'}</h3>
                      <div className="artist-detail">
                        <Calendar size={16} />
                        <span>{artist.upcomingEventsCount} upcoming event{artist.upcomingEventsCount !== 1 ? 's' : ''}</span>
                      </div>
                      {artist.genres && artist.genres.length > 0 && (
                        <div className="artist-detail">
                          <Music size={16} />
                          <span>{artist.genres.join(', ')}</span>
                        </div>
                      )}
                      <button 
                        className="view-artist-button"
                        onClick={() => navigate(`/artist/${artist.id}`)}
                      >
                        View Profile
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="no-artists-message">
                <p>No artists with upcoming events found.</p>
              </div>
            )}
          </section>
          
          {/* Featured Artists Section */}
          <section className="artists-section">
            <div className="section-header">
              <h2>
                <Star size={24} className="text-yellow-500" style={{ marginRight: '8px' }} />
                Featured Artists
              </h2>
              <button 
                className="view-all-button"
                onClick={() => navigate('/artists')}
              >
                View All
              </button>
            </div>
            
            {loading ? (
              <div className="loading-indicator">Loading featured artists...</div>
            ) : featuredArtists.length > 0 ? (
              <div className="artists-grid">
                {featuredArtists.map(artist => (
                  <div className="artist-card featured-artist" key={artist.id}>
                    <div className="featured-badge">
                      <Star size={16} />
                      <span>Featured</span>
                    </div>
                    <div 
                      className="artist-image" 
                      style={{ 
                        backgroundImage: artist.photoURL || artist.profileImage
                          ? `url(${artist.photoURL || artist.profileImage})` 
                          : 'linear-gradient(45deg, #7c3aed, #ec4899)'
                      }}
                    >
                      {(!artist.photoURL && !artist.profileImage) && (
                        <div className="artist-placeholder">
                          {(artist.displayName || artist.artistName || 'A').charAt(0)}
                        </div>
                      )}
                    </div>
                    <div className="artist-content">
                      <h3>{artist.displayName || artist.artistName || 'Featured Artist'}</h3>
                      {artist.bio && (
                        <p className="artist-bio">{artist.bio}</p>
                      )}
                      <div className="artist-detail">
                        <Calendar size={16} />
                        <span>{artist.upcomingEventsCount || 0} upcoming event{artist.upcomingEventsCount !== 1 ? 's' : ''}</span>
                      </div>
                      {artist.genres && artist.genres.length > 0 && (
                        <div className="artist-detail">
                          <Music size={16} />
                          <span>{artist.genres.slice(0, 2).join(', ')}</span>
                        </div>
                      )}
                      <button
                        className="view-artist-button featured"
                        onClick={() => navigate(`/artist/${artist.id}`)}
                      >
                        View Profile
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="no-artists-message">
                <p>No featured artists found. Check back soon!</p>
              </div>
            )}
          </section>
          
          {/* CTA Section */}
          <section className="cta-section">
            <div className="cta-content">
              <h2>Are you an artist?</h2>
              <p>Join our platform and showcase your talent to the world</p>
              <button 
                className="cta-button"
                onClick={() => navigate('/artist-signup')}
              >
                Register as an Artist
              </button>
            </div>
          </section>
        </>
      )}
      
      <style jsx="true">{`
        .artist-showcase-page {
          max-width: 1200px;
          margin: 0 auto;
          padding: 2rem 1rem;
        }
        
        .showcase-header {
          text-align: center;
          margin-bottom: 3rem;
        }
        
        .showcase-header h1 {
          font-size: 2.5rem;
          margin-bottom: 0.5rem;
          color: #2d3748;
        }
        
        .subtitle {
          font-size: 1.25rem;
          color: #4a5568;
        }
        
        .search-section {
          margin-top: 2rem;
          max-width: 600px;
          margin-left: auto;
          margin-right: auto;
        }
        
        .search-form {
          width: 100%;
        }
        
        .search-input-wrapper {
          position: relative;
          display: flex;
          align-items: center;
          background-color: white;
          border: 2px solid #e5e7eb;
          border-radius: 50px;
          overflow: hidden;
          transition: border-color 0.2s;
        }
        
        .search-input-wrapper:focus-within {
          border-color: #7c3aed;
        }
        
        .search-icon {
          position: absolute;
          left: 1rem;
          color: #6b7280;
        }
        
        .search-input {
          flex: 1;
          padding: 0.875rem 1rem 0.875rem 3rem;
          border: none;
          outline: none;
          font-size: 1rem;
        }
        
        .search-button {
          padding: 0.875rem 1.5rem;
          background-color: #7c3aed;
          color: white;
          border: none;
          font-weight: 500;
          cursor: pointer;
          transition: background-color 0.2s;
        }
        
        .search-button:hover:not(:disabled) {
          background-color: #6d28d9;
        }
        
        .search-button:disabled {
          background-color: #cbd5e1;
          cursor: not-allowed;
        }
        
        .search-results-section {
          margin-bottom: 3rem;
          padding: 2rem;
          background-color: #f8f9fa;
          border-radius: 12px;
        }
        
        .clear-search-button {
          background: none;
          border: 2px solid #dc2626;
          color: #dc2626;
          padding: 0.5rem 1rem;
          border-radius: 6px;
          font-weight: 500;
          cursor: pointer;
          transition: all 0.2s;
        }
        
        .clear-search-button:hover {
          background-color: #dc2626;
          color: white;
        }
        
        .search-results-grid {
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
          gap: 1.5rem;
          margin-top: 1.5rem;
        }
        
        .artist-search-card {
          background-color: white;
          border-radius: 12px;
          overflow: hidden;
          box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
          transition: transform 0.2s, box-shadow 0.2s;
          display: flex;
          padding: 1.5rem;
          gap: 1rem;
        }
        
        .artist-search-card:hover {
          transform: translateY(-3px);
          box-shadow: 0 6px 20px rgba(0, 0, 0, 0.15);
        }
        
        .artist-avatar {
          width: 80px;
          height: 80px;
          border-radius: 50%;
          background-size: cover;
          background-position: center;
          display: flex;
          align-items: center;
          justify-content: center;
          flex-shrink: 0;
        }
        
        .avatar-placeholder {
          font-size: 2rem;
          font-weight: 700;
          color: white;
          text-transform: uppercase;
        }
        
        .artist-search-content {
          flex: 1;
          display: flex;
          flex-direction: column;
          gap: 0.5rem;
        }
        
        .artist-search-content h3 {
          font-size: 1.25rem;
          margin: 0;
          color: #1a202c;
        }
        
        .artist-username {
          font-size: 0.875rem;
          color: #6b7280;
          margin: 0;
        }
        
        .view-artist-profile-button {
          margin-top: auto;
          padding: 0.5rem 1rem;
          background-color: #7c3aed;
          color: white;
          border: none;
          border-radius: 6px;
          font-weight: 500;
          cursor: pointer;
          transition: background-color 0.2s;
          text-align: center;
        }
        
        .view-artist-profile-button:hover {
          background-color: #6d28d9;
        }
        
        .no-search-results {
          text-align: center;
          padding: 3rem;
          color: #6b7280;
          font-size: 1.125rem;
        }
        
        .section-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 1.5rem;
        }
        
        .section-header h2 {
          font-size: 1.75rem;
          color: #2d3748;
        }
        
        .view-all-button {
          background: none;
          border: none;
          color: #4f46e5;
          font-weight: 500;
          cursor: pointer;
          padding: 0.5rem;
          font-size: 1rem;
        }
        
        .view-all-button:hover {
          text-decoration: underline;
        }
        
        .events-section,
        .artists-section {
          margin-bottom: 4rem;
        }
        
        .events-grid,
        .artists-grid {
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
          gap: 1.5rem;
        }
        
        .event-card,
        .artist-card {
          background-color: white;
          border-radius: 12px;
          overflow: hidden;
          box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
          transition: transform 0.2s, box-shadow 0.2s;
          position: relative;
        }
        
        .event-card:hover,
        .artist-card:hover {
          transform: translateY(-5px);
          box-shadow: 0 10px 15px rgba(0, 0, 0, 0.1);
        }
        
        .event-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          padding: 1rem 1.25rem 0;
        }
        
        .event-badge {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          padding: 0.25rem 0.75rem;
          background-color: #f8f9fa;
          border-radius: 1rem;
          font-size: 0.875rem;
          font-weight: 500;
        }
        
        .viewer-count {
          display: flex;
          align-items: center;
          gap: 0.25rem;
          color: #6b7280;
          font-size: 0.875rem;
        }
        
        .event-description {
          color: #6b7280;
          font-size: 0.875rem;
          line-height: 1.4;
          margin: 0.5rem 0;
          display: -webkit-box;
          -webkit-line-clamp: 2;
          -webkit-box-orient: vertical;
          overflow: hidden;
        }
        
        .featured-artist {
          border: 2px solid #fbbf24;
        }
        
        .featured-badge {
          position: absolute;
          top: 1rem;
          right: 1rem;
          background: linear-gradient(45deg, #fbbf24, #f59e0b);
          color: white;
          padding: 0.25rem 0.75rem;
          border-radius: 1rem;
          font-size: 0.75rem;
          font-weight: 600;
          display: flex;
          align-items: center;
          gap: 0.25rem;
          z-index: 1;
        }
        
        .artist-placeholder {
          width: 100%;
          height: 100%;
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 3rem;
          font-weight: 700;
          color: white;
          text-transform: uppercase;
        }
        
        .artist-bio {
          color: #6b7280;
          font-size: 0.875rem;
          line-height: 1.4;
          margin: 0.5rem 0;
          display: -webkit-box;
          -webkit-line-clamp: 2;
          -webkit-box-orient: vertical;
          overflow: hidden;
        }
        
        .view-artist-button.featured {
          background: linear-gradient(45deg, #fbbf24, #f59e0b);
        }
        
        .view-artist-button.featured:hover {
          background: linear-gradient(45deg, #f59e0b, #d97706);
        }
        
        .event-image,
        .artist-image {
          height: 180px;
          background-size: cover;
          background-position: center;
        }
        
        .event-content,
        .artist-content {
          padding: 1.25rem;
        }
        
        .event-content h3,
        .artist-content h3 {
          font-size: 1.25rem;
          margin: 0 0 1rem;
          color: #1a202c;
        }
        
        .event-details,
        .artist-details {
          margin-bottom: 1.25rem;
        }
        
        .event-detail,
        .artist-detail {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          margin-bottom: 0.75rem;
          color: #4a5568;
        }
        
        .view-event-button,
        .view-artist-button {
          width: 100%;
          padding: 0.75rem;
          background-color: #4f46e5;
          color: white;
          border: none;
          border-radius: 4px;
          font-weight: 500;
          cursor: pointer;
          transition: background-color 0.2s;
        }
        
        .view-event-button:hover,
        .view-artist-button:hover {
          background-color: #4338ca;
        }
        
        .loading-indicator {
          text-align: center;
          padding: 2rem;
          color: #4a5568;
        }
        
        .no-events-message,
        .no-artists-message {
          text-align: center;
          padding: 2rem;
          background-color: #f7fafc;
          border-radius: 8px;
          color: #4a5568;
        }
        
        .error-message {
          background-color: #fee2e2;
          border-left: 4px solid #ef4444;
          padding: 1rem;
          margin-bottom: 2rem;
          color: #b91c1c;
          border-radius: 4px;
        }
        
        .cta-section {
          background-color: #f0f9ff;
          border-radius: 12px;
          padding: 3rem 2rem;
          text-align: center;
        }
        
        .cta-content h2 {
          font-size: 2rem;
          margin-bottom: 1rem;
          color: #0c4a6e;
        }
        
        .cta-content p {
          font-size: 1.25rem;
          margin-bottom: 2rem;
          color: #0e7490;
          max-width: 600px;
          margin-left: auto;
          margin-right: auto;
        }
        
        .cta-button {
          background-color: #8b5cf6;
          color: white;
          border: none;
          padding: 0.875rem 2rem;
          font-size: 1.125rem;
          font-weight: 500;
          border-radius: 6px;
          cursor: pointer;
          transition: background-color 0.2s;
        }
        
        .cta-button:hover {
          background-color: #7c3aed;
        }
        
        @media (max-width: 768px) {
          .search-input-wrapper {
            flex-direction: column;
            border-radius: 8px;
          }
          
          .search-input {
            width: 100%;
            padding: 0.875rem 3rem 0.875rem 3rem;
          }
          
          .search-button {
            width: 100%;
            border-radius: 0 0 8px 8px;
          }
          
          .artist-search-card {
            flex-direction: column;
            align-items: center;
            text-align: center;
          }
          
          .artist-avatar {
            margin-bottom: 1rem;
          }
          
          .events-grid,
          .artists-grid {
            grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
          }
          
          .showcase-header h1 {
            font-size: 2rem;
          }
          
          .section-header h2 {
            font-size: 1.5rem;
          }
          
          .cta-section {
            padding: 2rem 1rem;
          }
          
          .cta-content h2 {
            font-size: 1.75rem;
          }
        }
      `}</style>
    </div>
  );
};

export default ArtistShowcasePage;
