// src/main.jsx
import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import './index.css';

// Import Firebase Performance fix
import './utils/firebase-performance-fix';

// Import Firebase Performance (only initializes in development)
import { initializePerformance } from './utils/firebase-performance';

// Import the audit integration system
import { initAuditSystem, auditFile } from './utils/auditIntegration';

// Import LiveKit Config for environment testing
import LiveKitConfig from './services/livekit/LiveKitConfig';

// Register this file for auditing
auditFile('src/main.jsx');

// Initialize the audit system at the application entry point
initAuditSystem();

// Run LiveKit environment test in development
if (import.meta.env.DEV || import.meta.env.MODE === 'development') {
  setTimeout(() => {
    console.log('🎬 Testing LiveKit environment configuration...');
    try {
      if (LiveKitConfig.isConfigValid()) {
        console.log('✅ LiveKit environment is properly configured!');
      } else {
        console.error('❌ LiveKit environment configuration failed!');
        console.error('Check your .env file and restart the development server');
      }
    } catch (error) {
      console.error('❌ Error testing LiveKit environment:', error);
    }
  }, 500);
  
  // Make LiveKit functions globally available for debugging
  if (typeof window !== 'undefined') {
    window.LiveKitConfig = LiveKitConfig;
    window.debugLiveKitConfig = () => LiveKitConfig.debugConfig();
    console.log('🔧 LiveKit functions available: window.LiveKitConfig, window.debugLiveKitConfig()');
  }
}

// Initialize Firebase Performance if in development mode
if (import.meta.env.DEV) {
  initializePerformance();
}

// Create the Root and render the app
const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);