// src/components/chat/ChatMessageList.jsx
import React, { useState, useEffect, useRef } from 'react';
import { getDatabase, ref, onValue, query, orderByChild, limitToLast } from 'firebase/database';
import { useAuth } from '../../contexts/AuthContext';
import { AlertCircle, Clock } from 'lucide-react';

const ChatMessageList = ({ roomId }) => {
  const { currentUser } = useAuth();
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const messagesEndRef = useRef(null);
  
  // Scroll to bottom of the message list
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };
  
  // Fetch messages from Realtime Database
  useEffect(() => {
    if (!roomId) return;
    
    setLoading(true);
    setError(null);
    
    try {
      const db = getDatabase();
      const messagesRef = ref(db, `chats/public/${roomId}/messages`);
      
      // Create a query to get the last 100 messages
      const messagesQuery = query(
        messagesRef,
        orderByChild('timestamp'),
        limitToLast(100)
      );
      
      // Set up realtime listener for messages
      const unsubscribe = onValue(messagesQuery, (snapshot) => {
        if (snapshot.exists()) {
          const messagesData = snapshot.val();
          const messagesList = Object.entries(messagesData).map(([id, data]) => ({
            id,
            ...data
          }));
          
          // Sort by timestamp (oldest first)
          messagesList.sort((a, b) => {
            if (!a.timestamp) return -1;
            if (!b.timestamp) return 1;
            return a.timestamp - b.timestamp;
          });
          
          setMessages(messagesList);
        } else {
          setMessages([]);
        }
        
        setLoading(false);
        
        // Scroll to bottom when new messages are loaded
        setTimeout(scrollToBottom, 100);
      }, (err) => {
        console.error('Error fetching messages:', err);
        setError(`Failed to load messages: ${err.message}`);
        setLoading(false);
      });
      
      return () => {
        // Clean up the listener when the component unmounts
        unsubscribe();
      };
    } catch (err) {
      console.error('Setting up messages listener:', err);
      setError(`Failed to set up messages listener: ${err.message}`);
      setLoading(false);
    }
  }, [roomId]);
  
  // Format timestamp
  const formatTimestamp = (timestamp) => {
    if (!timestamp) return '';
    
    const date = new Date(timestamp);
    const now = new Date();
    const isToday = date.toDateString() === now.toDateString();
    
    if (isToday) {
      return date.toLocaleTimeString([], { 
        hour: '2-digit', 
        minute: '2-digit'
      });
    } else {
      return date.toLocaleDateString([], { 
        month: 'short', 
        day: 'numeric' 
      }) + ' ' + date.toLocaleTimeString([], { 
        hour: '2-digit', 
        minute: '2-digit'
      });
    }
  };
  
  // Group messages by sender and time
  const groupMessages = (messages) => {
    if (!messages.length) return [];
    
    const groups = [];
    let currentGroup = [messages[0]];
    
    for (let i = 1; i < messages.length; i++) {
      const currentMessage = messages[i];
      const previousMessage = messages[i - 1];
      
      // Check if messages are from the same sender and within 5 minutes of each other
      const sameSender = currentMessage.userId === previousMessage.userId;
      const timeGap = !currentMessage.timestamp || !previousMessage.timestamp 
        ? false 
        : (currentMessage.timestamp - previousMessage.timestamp) < 5 * 60 * 1000;
      
      if (sameSender && timeGap) {
        // Add to current group
        currentGroup.push(currentMessage);
      } else {
        // Start a new group
        groups.push(currentGroup);
        currentGroup = [currentMessage];
      }
    }
    
    // Add the last group
    groups.push(currentGroup);
    
    return groups;
  };
  
  // Determine if message is from current user
  const isCurrentUser = (userId) => {
    return currentUser && userId === currentUser.uid;
  };
  
  if (loading) {
    return (
      <div className="chat-messages-loading">
        <div className="spinner-sm"></div>
        <p>Loading messages...</p>
      </div>
    );
  }
  
  if (error) {
    return (
      <div className="chat-messages-error">
        <AlertCircle size={20} />
        <p>{error}</p>
      </div>
    );
  }
  
  const messageGroups = groupMessages(messages);
  
  return (
    <div className="chat-messages-container">
      {messages.length === 0 ? (
        <div className="chat-no-messages">
          <p>No messages yet. Be the first to say hello!</p>
        </div>
      ) : (
        messageGroups.map((group, groupIndex) => {
          const fromCurrentUser = isCurrentUser(group[0].userId);
          return (
            <div 
              key={`group-${groupIndex}`} 
              className={`chat-message-group ${fromCurrentUser ? 'chat-message-outgoing' : 'chat-message-incoming'}`}
            >
              {!fromCurrentUser && (
                <div className="chat-message-avatar">
                  {group[0].photoURL ? (
                    <img src={group[0].photoURL} alt={group[0].displayName || 'User'} />
                  ) : (
                    <div className="chat-avatar-placeholder">
                      {(group[0].displayName || 'U').charAt(0).toUpperCase()}
                    </div>
                  )}
                </div>
              )}
              
              <div className="chat-message-content">
                {!fromCurrentUser && (
                  <div className="chat-message-sender">
                    {group[0].displayName || 'Anonymous'}
                  </div>
                )}
                
                {group.map((message, messageIndex) => (
                  <div key={message.id} className="chat-message-bubble-wrapper">
                    <div className={`chat-message-bubble ${fromCurrentUser ? 'outgoing' : 'incoming'}`}>
                      <p>{message.text}</p>
                    </div>
                    
                    {messageIndex === group.length - 1 && (
                      <div className={`chat-message-time ${fromCurrentUser ? 'outgoing' : 'incoming'}`}>
                        <Clock size={12} />
                        <span>{formatTimestamp(message.timestamp)}</span>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          );
        })
      )}
      <div ref={messagesEndRef} />
      
      <style jsx>{`
        .chat-messages-container {
          flex-grow: 1;
          display: flex;
          flex-direction: column;
          padding: 16px;
          overflow-y: auto;
          background-color: #f9fafb;
          scrollbar-width: thin;
          scrollbar-color: #d1d5db #f3f4f6;
        }
        
        .chat-messages-container::-webkit-scrollbar {
          width: 6px;
        }
        
        .chat-messages-container::-webkit-scrollbar-track {
          background: #f3f4f6;
        }
        
        .chat-messages-container::-webkit-scrollbar-thumb {
          background-color: #d1d5db;
          border-radius: 3px;
        }
        
        .chat-message-group {
          display: flex;
          margin-bottom: 20px;
          max-width: 80%;
        }
        
        .chat-message-outgoing {
          align-self: flex-end;
          flex-direction: row-reverse;
        }
        
        .chat-message-incoming {
          align-self: flex-start;
        }
        
        .chat-message-avatar {
          margin-right: 8px;
          flex-shrink: 0;
          align-self: flex-end;
        }
        
        .chat-message-avatar img {
          width: 36px;
          height: 36px;
          border-radius: 50%;
          object-fit: cover;
          box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
        }
        
        .chat-avatar-placeholder {
          width: 36px;
          height: 36px;
          background-color: #e5e7eb;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          color: #6b7280;
          font-weight: 600;
          box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
        }
        
        .chat-message-content {
          display: flex;
          flex-direction: column;
        }
        
        .chat-message-outgoing .chat-message-content {
          align-items: flex-end;
        }
        
        .chat-message-incoming .chat-message-content {
          align-items: flex-start;
        }
        
        .chat-message-sender {
          font-size: 0.75rem;
          color: #6b7280;
          margin-bottom: 4px;
          font-weight: 500;
        }
        
        .chat-message-bubble-wrapper {
          display: flex;
          flex-direction: column;
          margin-bottom: 2px;
        }
        
        .chat-message-bubble {
          padding: 8px 12px;
          border-radius: 16px;
          max-width: 100%;
          word-break: break-word;
        }
        
        .chat-message-bubble.outgoing {
          background-color: #4f46e5;
          color: white;
          border-bottom-right-radius: 4px;
        }
        
        .chat-message-bubble.incoming {
          background-color: white;
          color: #1f2937;
          border-bottom-left-radius: 4px;
          box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
        }
        
        .chat-message-bubble p {
          margin: 0;
          line-height: 1.4;
        }
        
        .chat-message-time {
          display: flex;
          align-items: center;
          gap: 4px;
          font-size: 0.7rem;
          margin-top: 4px;
        }
        
        .chat-message-time.incoming {
          color: #6b7280;
        }
        
        .chat-message-time.outgoing {
          color: rgba(255, 255, 255, 0.9);
        }
        
        .chat-messages-loading,
        .chat-messages-error,
        .chat-no-messages {
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          height: 100%;
          padding: 24px;
          text-align: center;
          color: #6b7280;
        }
        
        .spinner-sm {
          width: 24px;
          height: 24px;
          border: 2px solid rgba(79, 70, 229, 0.25);
          border-top-color: #4f46e5;
          border-radius: 50%;
          animation: spin 1s linear infinite;
          margin-bottom: 8px;
        }
        
        .chat-messages-error {
          color: #ef4444;
        }
        
        @keyframes spin {
          to {
            transform: rotate(360deg);
          }
        }
        
        @media (max-width: 768px) {
          .chat-message-group {
            max-width: 90%;
          }
        }
        
        @media (max-width: 480px) {
          .chat-message-group {
            max-width: 95%;
          }
        }
      `}</style>
    </div>
  );
};

export default ChatMessageList;