// src/components/navigation/MainNavigation.jsx
import React, { useState, useEffect, useRef } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { useWallet } from '../../contexts/WalletContext';
import TipWallet from '../monetization/TipWallet';
import SearchBar from '../search/SearchBar';
import {
  Home,
  MessageCircle,
  LogIn,
  LogOut,
  Menu,
  X,
  User,
  Settings,
  PlayCircle,
  MessageSquare,
  Crown,
  Shield,
  Mic, // Using Mic icon instead of AudioWaveform
  Calendar, // Icon for Events
  Users, // Icon for People tab
  FileText, // Icon for Home Feed tab
  Wallet, // Icon for Wallet
  Volume2, // Icon for Audio Matcher
  Search, // Icon for Search
  Building2, // Icon for Venue Portal
  Radio, // Icon for Unified DJ Studio
  Compass, // Icon for Discover/Categories
  LayoutGrid // Icon for the Talk Studio product family
} from 'lucide-react';
import { getFirestore, doc, getDoc, onSnapshot, collection, query, where } from 'firebase/firestore';
import './MainNavigation.css';

const MainNavigation = ({ developerMode, isMobile }) => {
  const authContext = useAuth();
  console.log('Auth context available functions:', Object.keys(authContext || {}));
  const { currentUser, logout } = authContext || {};
  const { balance, formatCurrency, canSendTips } = useWallet();

  // Debug check
  useEffect(() => {
    console.log('MainNavigation - currentUser:', currentUser);
    console.log('MainNavigation - logout function:', typeof logout);
    if (!logout) {
      console.error('LOGOUT FUNCTION NOT AVAILABLE - Auth context:', authContext);
    }
  }, [currentUser, logout, authContext]);
  const navigate = useNavigate();
  const location = useLocation();
  const [menuOpen, setMenuOpen] = useState(false);
  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const menuRef = useRef(null);
  const userMenuRef = useRef(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isArtist, setIsArtist] = useState(false);
  const [isVenueUser, setIsVenueUser] = useState(false);
  const [hasLiveRooms, setHasLiveRooms] = useState(false);
  const [hasUnreadMessages, setHasUnreadMessages] = useState(false);
  const [loggingOut, setLoggingOut] = useState(false);
  const [showWallet, setShowWallet] = useState(false);
  
  // Check if user is anonymous
  const isAnonymous = currentUser?.isAnonymous || false;
  
  // Check if current user is an admin or artist
  useEffect(() => {
    const checkUserStatus = async () => {
      if (!currentUser || currentUser.isAnonymous) {
        setIsAdmin(false);
        setIsArtist(false);
        return;
      }
      
      try {
        const db = getFirestore();
        const userDocRef = doc(db, 'users', currentUser.uid);
        const userDoc = await getDoc(userDocRef);
        
        if (userDoc.exists()) {
          const userData = userDoc.data();
          setIsAdmin(userData.isAdmin === true);
          setIsArtist(userData.isArtist === true);
          setIsVenueUser(userData.isVenueUser === true);
        } else {
          // Check if user has flags on the user object directly (from auth context)
          setIsAdmin(currentUser.isAdmin === true);
          setIsArtist(currentUser.isArtist === true);
          setIsVenueUser(currentUser.isVenueUser === true);
        }
      } catch (error) {
        console.error('Error checking user status:', error);
        setIsAdmin(false);
        setIsArtist(false);
        setIsVenueUser(false);
      }
    };
    
    checkUserStatus();
  }, [currentUser]);
  
  // Check for live rooms
  useEffect(() => {
    const db = getFirestore();
    const streamRef = doc(db, 'streams', 'currentStream');
    
    const unsubscribe = onSnapshot(streamRef, (docSnapshot) => {
      if (docSnapshot.exists()) {
        const streamData = docSnapshot.data();
        setHasLiveRooms(streamData.isLive === true);
      } else {
        setHasLiveRooms(false);
      }
    }, (error) => {
      console.error('Error getting stream status:', error);
      setHasLiveRooms(false);
    });
    
    return () => unsubscribe();
  }, []);

  // Check for unread messages - Only for non-anonymous users
  useEffect(() => {
    if (!currentUser || currentUser.isAnonymous) {
      setHasUnreadMessages(false);
      return () => {};
    }

    const db = getFirestore();
    const userConversationsQuery = query(
      collection(db, "conversations"),
      where("participants", "array-contains", currentUser.uid)
    );

    const unsubscribe = onSnapshot(userConversationsQuery, (snapshot) => {
      let hasUnread = false;
      snapshot.docs.forEach(doc => {
        const conversation = doc.data();
        // Check if the conversation has unread field for the current user
        if (conversation.unreadCounts && 
            conversation.unreadCounts[currentUser.uid] && 
            conversation.unreadCounts[currentUser.uid] > 0) {
          hasUnread = true;
        }
      });
      
      setHasUnreadMessages(hasUnread);
    }, (error) => {
      console.error('Error checking for unread messages:', error);
      setHasUnreadMessages(false);
    });
    
    return () => unsubscribe();
  }, [currentUser]);
  
  // Close menu when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        setMenuOpen(false);
      }
      if (userMenuRef.current && !userMenuRef.current.contains(event.target)) {
        setUserMenuOpen(false);
      }
    };
    
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);
  
  // Handle logout with fallback
  const handleLogout = async () => {
    try {
      console.log('handleLogout called - logout function type:', typeof logout);
      
      // Show loading state
      setLoggingOut(true);
      
      // Close all menus first
      setMenuOpen(false);
      setUserMenuOpen(false);
      
      // Try the context logout function first
      if (logout && typeof logout === 'function') {
        console.log('Using context logout function');
        await logout();
      } else {
        console.log('Context logout not available, using direct Firebase logout');
        // Fallback to direct Firebase logout
        const { getAuth, signOut } = await import('firebase/auth');
        const auth = getAuth();
        await signOut(auth);
        
        // Clear storage manually
        localStorage.clear();
        sessionStorage.clear();
        console.log('Direct Firebase logout completed');
      }
      
      // Clear any app-specific state
      localStorage.removeItem('developerMode');
      
      // Navigate to home page after successful logout
      navigate('/');
      
      // Force a page reload to clear any cached state
      setTimeout(() => {
        window.location.reload();
      }, 100);
    } catch (error) {
      console.error('Failed to log out:', error);
      
      // Emergency logout procedure
      try {
        console.log('Attempting emergency logout...');
        localStorage.clear();
        sessionStorage.clear();
        window.location.href = '/';
      } catch (emergencyError) {
        console.error('Emergency logout failed:', emergencyError);
        alert('Logout failed. Please refresh the page manually.');
      }
    } finally {
      setLoggingOut(false);
    }
  };

  // Toggle menu
  const toggleMenu = () => {
    setMenuOpen(!menuOpen);
    if (userMenuOpen) setUserMenuOpen(false);
  };
  
  // Toggle user menu
  const toggleUserMenu = () => {
    setUserMenuOpen(!userMenuOpen);
    if (menuOpen) setMenuOpen(false);
  };
  
  // Close menu
  const closeMenu = () => {
    setMenuOpen(false);
  };
  
  // Close user menu
  const closeUserMenu = () => {
    setUserMenuOpen(false);
  };
  
  // Check if the route is active
  const isActive = (path) => {
    return location.pathname.startsWith(path);
  };

  // Navigate to settings
  const goToSettings = () => {
    navigate('/settings');
    setUserMenuOpen(false);
  };

  // Navigate to admin panel
  const goToAdmin = () => {
    navigate('/admin');
    setUserMenuOpen(false);
  };

  // Screens rebuilt on the TalkStudio design system draw their own 60px bar
  // (components/layout/TalkStudioNav). Stand down there so the two navs don't
  // stack — this legacy bar still serves every screen that hasn't moved yet.
  const TALKSTUDIO_NAV_ROUTES = [
    /^\/$/,
    /^\/discover$/,
    /^\/products$/,
    /^\/schedule(\/.*)?$/,
    /^\/following$/,
    /^\/replays$/,
    /^\/r\//,
    /^\/artist(\/|$)/,
    /^\/artist-profile$/,
  ];
  if (TALKSTUDIO_NAV_ROUTES.some(pattern => pattern.test(location.pathname))) {
    return null;
  }

  return (
    <nav className="main-navigation">
      <div className="nav-container">
        {/* Logo and Title */}
        <div className="nav-logo">
          <Link to="/" className="logo-link" onClick={closeMenu}>
            {/* Use a hardcoded base64 logo image to ensure it always renders */}
            <img 
              src="data:image/svg+xml;base64," 
              alt="TalkStudio" 
              className="logo-image" 
            />
            <span className="site-title">TalkStudio</span>
          </Link>
        </div>
        
        {/* Main Navigation Links - Desktop */}
        <div className={`nav-links desktop-only ${menuOpen ? 'menu-open' : ''}`}>
          {/* Home Feed and Discover hidden from primary nav for the
              dealmaker pivot — routes still accessible directly. */}

          <Link to="/rooms" className={`nav-link ${isActive('/room') ? 'active' : ''}`}>
            <MessageCircle size={20} className="link-icon" />
            <span>Rooms</span>
            {hasLiveRooms && <span className="live-indicator-badge"></span>}
          </Link>

          {/* Messages Link - Desktop Menu - Hidden for anonymous users */}
          {!isAnonymous && (
            <Link to="/messages" className={`nav-link ${isActive('/messages') ? 'active' : ''}`}>
              <MessageSquare size={20} className="link-icon" />
              <span>Messages</span>
              {hasUnreadMessages && <span className="live-indicator-badge"></span>}
            </Link>
          )}
          
          {/* People Link - Desktop Menu */}
          <Link to="/people" className={`nav-link ${isActive('/people') ? 'active' : ''}`}>
            <Users size={20} className="link-icon" />
            <span>People</span>
          </Link>
        </div>
        
        {/* Search Bar */}
        <div className="search-section">
          <SearchBar 
            compact={true}
            showSearchButton={true}
            placeholder="Search rooms, artists, people..."
            className="nav-search-bar"
          />
        </div>
        
        {/* User Menu */}
        <div className="user-section">
          {currentUser ? (
            <div className="user-menu-container" ref={userMenuRef}>
              <button 
                className="user-menu-button" 
                onClick={toggleUserMenu}
                aria-label="User menu"
              >
                {currentUser.photoURL && !isAnonymous ? (
                  <div className="user-avatar">
                    <img 
                      src={currentUser.photoURL} 
                      alt={currentUser.displayName || 'User'} 
                      className="avatar-img"
                    />
                  </div>
                ) : (
                  <div className="user-avatar-placeholder">
                    <User size={20} />
                  </div>
                )}
                <span className="user-name-display">
                  {isAnonymous ? 'Anonymous' : (currentUser.displayName || 'User')}
                </span>
              </button>
              
              {userMenuOpen && (
                <div className="user-dropdown">
                  <div className="user-info">
                    <div className="user-avatar-large">
                      {currentUser.photoURL && !isAnonymous ? (
                        <img 
                          src={currentUser.photoURL} 
                          alt={currentUser.displayName || 'User'} 
                          className="avatar-img"
                        />
                      ) : (
                        <div className="avatar-placeholder-large">
                          <User size={32} />
                        </div>
                      )}
                    </div>
                    <div className="user-details">
                      <div className="user-display-name">
                        {isAnonymous ? 'Anonymous User' : (currentUser.displayName || 'User')}
                      </div>
                      {currentUser.email && !isAnonymous && (
                        <div className="user-email">{currentUser.email}</div>
                      )}
                    </div>
                  </div>
                  
                  <div className="dropdown-divider"></div>
                  
                  <div className="dropdown-menu">
                    {/* My Profile option for registered users */}
                    {!isAnonymous && (
                      <Link to={isArtist ? `/artist/${currentUser.uid}` : `/people/${currentUser.uid}`} className="dropdown-item" onClick={closeUserMenu}>
                        <User size={18} className="item-icon" />
                        <span>My Profile</span>
                      </Link>
                    )}
                    
                    {/* Log in as registered user option for anonymous users */}
                    {isAnonymous && (
                      <Link to="/login" className="dropdown-item" onClick={closeUserMenu}>
                        <LogIn size={18} className="item-icon" />
                        <span>Sign Up / Log In</span>
                      </Link>
                    )}
                    
                    {/* Wallet option - For registered users only */}
                    {canSendTips() && (
                      <button className="dropdown-item" onClick={() => { setShowWallet(true); closeUserMenu(); }}>
                        <Wallet size={18} className="item-icon" />
                        <span>Tip Wallet ({formatCurrency(balance)})</span>
                      </button>
                    )}
                    
                    {/* Premium option */}
                    <Link to="/premium-membership" className="dropdown-item" onClick={closeUserMenu}>
                      <Crown size={18} className="item-icon" />
                      <span>Upgrade to Premium</span>
                    </Link>
                    
                    {/* Settings option - Hidden for anonymous users */}
                    {!isAnonymous && (
                      <button className="dropdown-item" onClick={goToSettings}>
                        <Settings size={18} className="item-icon" />
                        <span>Settings</span>
                      </button>
                    )}
                    
                    {/* DJ Studio option - available for all registered users */}
                    {!isAnonymous && (
                      <Link to="/events/studio" className="dropdown-item" onClick={closeUserMenu}>
                        <Radio size={18} className="item-icon" />
                        <span>DJ Studio</span>
                      </Link>
                    )}
                    
                    {/* Venue Portal option - available for venue users */}
                    {isVenueUser && !isAnonymous && (
                      <Link to="/venue-portal" className="dropdown-item" onClick={closeUserMenu}>
                        <Building2 size={18} className="item-icon" />
                        <span>Venue Portal</span>
                      </Link>
                    )}
                
                    {/* Admin Panel option - available for users with isAdmin flag */}
                    {isAdmin && !isAnonymous && (
                      <button className="dropdown-item admin-menu-item" onClick={goToAdmin}>
                        <Shield size={18} className="item-icon" />
                        <span>Admin Panel</span>
                      </button>
                    )}
                    
                    <div className="dropdown-divider"></div>
                    
                    {/* Terms of Service option */}
                    <Link to="/terms-of-service" className="dropdown-item" onClick={closeUserMenu}>
                      <FileText size={18} className="item-icon" />
                      <span>Terms of Service</span>
                    </Link>
                    
                    {/* Logout option */}
                    <button className="dropdown-item logout-item" onClick={handleLogout} disabled={loggingOut}>
                      <LogOut size={18} className="item-icon" />
                      <span>{loggingOut ? "Logging out..." : "Log Out"}</span>
                    </button>
                  </div>
                </div>
              )}
            </div>
          ) : (
            <Link to="/login" className="login-button">
              <LogIn size={20} className="button-icon" />
              <span className="button-text">Log In</span>
            </Link>
          )}
        </div>
        
        {/* Hamburger Menu Toggle - Mobile and Desktop */}
        <button 
          className="menu-toggle" 
          onClick={toggleMenu}
          aria-label={menuOpen ? "Close menu" : "Open menu"}
        >
          {menuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
        
        {/* Mobile Menu */}
        {menuOpen && (
          <div className="menu-overlay" onClick={closeMenu}>
            <div 
              ref={menuRef}
              className="side-menu" 
              onClick={e => e.stopPropagation()}
            >
              <div className="menu-header">
                <div className="menu-title">TalkStudio</div>
                <button className="close-menu" onClick={closeMenu}>
                  <X size={24} />
                </button>
              </div>
              
              {/* User Info if logged in - Mobile */}
              {currentUser && (
                <div className="menu-user-info">
                  <div className="user-avatar">
                    {currentUser.photoURL && !isAnonymous ? (
                      <img 
                        src={currentUser.photoURL} 
                        alt={currentUser.displayName || 'User'} 
                        className="avatar-img"
                      />
                    ) : (
                      <div className="avatar-placeholder">
                        <User size={24} />
                      </div>
                    )}
                  </div>
                  <div className="user-details">
                    <div className="user-name">
                      {isAnonymous ? 'Anonymous User' : (currentUser.displayName || 'User')}
                    </div>
                    {currentUser.email && !isAnonymous && (
                      <div className="user-email">{currentUser.email}</div>
                    )}
                  </div>
                </div>
              )}
              
              {/* Menu Items */}
              <div className="menu-items">
                
                {/* Search Item - Mobile Only */}
                <Link to="/search" className={`menu-item ${isActive('/search') ? 'active' : ''}`} onClick={closeMenu}>
                  <Search size={20} className="item-icon" />
                  <span>Search</span>
                </Link>
                
                {/* Home Feed hidden in dealmaker pivot — route still works at /home-feed */}

                {/* The rest of the Talk Studio family — SmartInvestor CRM, Store */}
                <Link to="/products" className={`menu-item ${isActive('/products') ? 'active' : ''}`} onClick={closeMenu}>
                  <LayoutGrid size={20} className="item-icon" />
                  <span>Products</span>
                </Link>

                {/* My Profile link for mobile - registered users only */}
                {currentUser && !isAnonymous && (
                  <Link to={isArtist ? `/artist/${currentUser.uid}` : `/people/${currentUser.uid}`} className={`menu-item ${isActive(isArtist ? '/artist' : '/people') ? 'active' : ''}`} onClick={closeMenu}>
                    <User size={20} className="item-icon" />
                    <span>My Profile</span>
                  </Link>
                )}
                
                <Link to="/rooms" className={`menu-item ${isActive('/room') ? 'active' : ''}`} onClick={closeMenu}>
                  <MessageCircle size={20} className="item-icon" />
                  <span>Rooms</span>
                  {hasLiveRooms && <span className="live-indicator-badge mobile"></span>}
                </Link>
                
                {/* Events Link - Mobile Menu */}
                <Link to="/events" className={`menu-item ${isActive('/events') ? 'active' : ''}`} onClick={closeMenu}>
                  <Calendar size={20} className="item-icon" />
                  <span>Events</span>
                </Link>
                
                {/* Audio Matcher link - Mobile Menu */}
                <Link to="/audio-match" className={`menu-item ${isActive('/audio-match') ? 'active' : ''}`} onClick={closeMenu}>
                  <Volume2 size={20} className="item-icon" />
                  <span>Audio Match</span>
                </Link>
                
                {/* Wallet link - mobile - Hidden for anonymous users */}
                {canSendTips() && (
                  <button className="menu-item" onClick={() => { setShowWallet(true); closeMenu(); }}>
                    <Wallet size={20} className="item-icon" />
                    <span>Tip Wallet ({formatCurrency(balance)})</span>
                  </button>
                )}
                
                {/* Add Premium Link to mobile menu */}
                <Link to="/premium-membership" className={`menu-item ${isActive('/premium-membership') ? 'active' : ''}`} onClick={closeMenu}>
                  <Crown size={20} className="item-icon" />
                  <span>Premium Membership</span>
                </Link>
                
                {/* Messages link - Hidden for anonymous users */}
                {!isAnonymous && (
                  <Link to="/messages" className={`menu-item ${isActive('/messages') ? 'active' : ''}`} onClick={closeMenu}>
                    <MessageSquare size={20} className="item-icon" />
                    <span>Messages</span>
                    {hasUnreadMessages && <span className="live-indicator-badge mobile"></span>}
                  </Link>
                )}
                
                {/* People link */}
                <Link to="/people" className={`menu-item ${isActive('/people') ? 'active' : ''}`} onClick={closeMenu}>
                  <Users size={20} className="item-icon" />
                  <span>People</span>
                </Link>
                
                {/* DJ Studio link - mobile - Available for all registered users */}
                {!isAnonymous && (
                  <Link to="/events/studio" className={`menu-item ${isActive('/events/studio') ? 'active' : ''}`} onClick={closeMenu}>
                    <Radio size={20} className="item-icon" />
                    <span>DJ Studio</span>
                  </Link>
                )}
                
                {/* Settings link for logged in users - Hidden for anonymous users */}
                {currentUser && !isAnonymous && (
                  <Link to="/settings" className={`menu-item ${isActive('/settings') ? 'active' : ''}`} onClick={closeMenu}>
                    <Settings size={20} className="item-icon" />
                    <span>Settings</span>
                  </Link>
                )}
                
                {/* Terms of Service link */}
                <Link to="/terms-of-service" className={`menu-item ${isActive('/terms-of-service') ? 'active' : ''}`} onClick={closeMenu}>
                  <FileText size={20} className="item-icon" />
                  <span>Terms of Service</span>
                </Link>
                
                {/* Auth options */}
                {currentUser ? (
                  <>
                    {/* Login option for anonymous users */}
                    {isAnonymous && (
                      <Link to="/login" className="menu-item" onClick={closeMenu}>
                        <LogIn size={20} className="item-icon" />
                        <span>Sign Up / Log In</span>
                      </Link>
                    )}
                    
                    {/* Logout for all users */}
                    <button className="menu-item logout-button" onClick={handleLogout} disabled={loggingOut}>
                      <LogOut size={20} className="item-icon" />
                      <span>{loggingOut ? "Logging out..." : "Log Out"}</span>
                    </button>
                  </>
                ) : (
                  <Link to="/login" className="menu-item" onClick={closeMenu}>
                    <LogIn size={20} className="item-icon" />
                    <span>Log In</span>
                  </Link>
                )}
              </div>
              
              {/* Developer Mode Notice */}
              {developerMode && (
                <div className="dev-mode-notice">
                  Developer Mode Active
                </div>
              )}
            </div>
          </div>
        )}
      </div>
      
      {/* Wallet Modal */}
      <TipWallet 
        isOpen={showWallet}
        onClose={() => setShowWallet(false)}
      />
    </nav>
  );
};

export default MainNavigation;