// src/components/auth/ConvertAccount.jsx
import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../../firebase';
import { FcGoogle } from 'react-icons/fc';
import './ConvertAccount.css'; // Assuming you have this CSS file

const ConvertAccount = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [username, setUsername] = useState('');
  const [existingUsername, setExistingUsername] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [initialLoading, setInitialLoading] = useState(true);
  const { currentUser, signup, googleLogin } = useAuth();
  const navigate = useNavigate();

  // Fetch existing user data (including username) if available
  useEffect(() => {
    const fetchUserData = async () => {
      if (!currentUser) {
        setInitialLoading(false);
        return;
      }

      try {
        const userDocRef = doc(db, 'users', currentUser.uid);
        const userDoc = await getDoc(userDocRef);
        
        if (userDoc.exists()) {
          const userData = userDoc.data();
          
          if (userData.username) {
            setExistingUsername(userData.username);
            setUsername(userData.username);
          }
          
          if (currentUser.displayName) {
            setDisplayName(currentUser.displayName);
          }
        }
        
        setInitialLoading(false);
      } catch (err) {
        console.error('Error fetching user data:', err);
        setInitialLoading(false);
      }
    };

    fetchUserData();
  }, [currentUser]);

  // Redirect if not an anonymous user
  useEffect(() => {
    if (currentUser && !currentUser.isAnonymous) {
      navigate('/');
    }
  }, [currentUser, navigate]);

  // Handle email/password signup
  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (password !== confirmPassword) {
      setError('Passwords do not match');
      return;
    }
    
    try {
      setError('');
      setLoading(true);
      
      // Convert anonymous account to email/password account using the existing username
      await signup(email, password, displayName, existingUsername);
      
      navigate('/');
    } catch (err) {
      console.error('Conversion error:', err);
      if (err.code === 'auth/email-already-in-use') {
        setError('An account with this email already exists');
      } else if (err.code === 'auth/weak-password') {
        setError('Password is too weak. Please use at least 6 characters');
      } else {
        setError('Failed to convert account: ' + err.message);
      }
    } finally {
      setLoading(false);
    }
  };

  // Handle Google account conversion
  const handleGoogleConversion = async () => {
    try {
      setError('');
      setLoading(true);
      
      // Use the googleLogin function, which now handles preserving usernames
      const { usernameRequired, result } = await googleLogin();
      
      // If username setup required, go to setup page
      if (usernameRequired) {
        navigate('/setup-username');
      } else {
        navigate('/');
      }
    } catch (err) {
      console.error('Google conversion error:', err);
      setError('Failed to convert account with Google: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  if (initialLoading) {
    return <div className="loading">Loading...</div>;
  }

  if (!currentUser || !currentUser.isAnonymous) {
    return (
      <div className="convert-account-container">
        <div className="convert-card">
          <h2>Account Conversion</h2>
          <p>You need to be signed in as an anonymous user to convert your account.</p>
          <Link to="/login" className="login-link">Go to Login</Link>
        </div>
      </div>
    );
  }

  return (
    <div className="convert-account-container">
      <div className="convert-card">
        <h2>Convert Your Account</h2>
        <p className="convert-intro">
          You're currently using TalkStudio anonymously. Convert to a permanent account to save your data and access all features.
        </p>
        
        {existingUsername && (
          <div className="username-notice">
            <strong>Your current username:</strong> @{existingUsername}
            <p className="username-help">
              This username will be preserved when you convert your account.
            </p>
          </div>
        )}
        
        {error && <div className="error-message">{error}</div>}
        
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="displayName">Display Name</label>
            <input
              type="text"
              id="displayName"
              value={displayName}
              onChange={(e) => setDisplayName(e.target.value)}
              placeholder="Enter your name"
            />
          </div>
          
          <div className="form-group">
            <label htmlFor="email">Email</label>
            <input
              type="email"
              id="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="Enter your email"
              required
            />
          </div>
          
          <div className="form-group">
            <label htmlFor="password">Password</label>
            <input
              type="password"
              id="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Create a password"
              required
            />
          </div>
          
          <div className="form-group">
            <label htmlFor="confirmPassword">Confirm Password</label>
            <input
              type="password"
              id="confirmPassword"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              placeholder="Confirm your password"
              required
            />
          </div>
          
          <button 
            type="submit" 
            className="convert-button" 
            disabled={loading}
          >
            {loading ? 'Converting...' : 'Convert with Email & Password'}
          </button>
        </form>
        
        <div className="divider">
          <span>OR</span>
        </div>
        
        <button 
          className="google-button" 
          onClick={handleGoogleConversion}
          disabled={loading}
        >
          <FcGoogle className="google-icon" />
          <span>Convert with Google</span>
        </button>
        
        <p className="login-prompt">
          Already have an account? <Link to="/login">Log in</Link>
        </p>
      </div>
    </div>
  );
};

export default ConvertAccount;