import React, { useState, useEffect } from 'react';

const DeviceDebugger = () => {
  const [devices, setDevices] = useState([]);
  const [selectedDevice, setSelectedDevice] = useState('');
  const [testResult, setTestResult] = useState('');
  const [stream, setStream] = useState(null);

  useEffect(() => {
    listAllDevices();
  }, []);

  const listAllDevices = async () => {
    try {
      console.log('🔍 Starting device enumeration...');
      
      // First try without requesting permission
      let allDevices = await navigator.mediaDevices.enumerateDevices();
      console.log('📱 Initial scan (no permission):', allDevices.length, 'devices');
      
      // Check if we have labels
      const hasLabels = allDevices.some(device => device.label && device.label !== '');
      console.log('🏷️ Has device labels:', hasLabels);
      
      if (!hasLabels) {
        try {
          console.log('🔑 Requesting permissions to get device labels...');
          const tempStream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
          console.log('✅ Got temporary stream');
          tempStream.getTracks().forEach(track => {
            console.log(`🛑 Stopping ${track.kind} track: ${track.label}`);
            track.stop();
          });
          
          // Re-scan with labels
          allDevices = await navigator.mediaDevices.enumerateDevices();
          console.log('📱 Re-scan (with permission):', allDevices.length, 'devices');
        } catch (permError) {
          console.warn('⚠️ Permission request failed:', permError);
          setTestResult(`Permission failed: ${permError.message}`);
          return;
        }
      }
      
      setDevices(allDevices);
      
      console.log('🔍 All detected devices:');
      allDevices.forEach((device, index) => {
        console.log(`${index + 1}. ${device.kind}: "${device.label || 'No Label'}" (ID: ${device.deviceId.substring(0, 20)}...)`);
      });
      
      const videoDevices = allDevices.filter(d => d.kind === 'videoinput');
      const audioDevices = allDevices.filter(d => d.kind === 'audioinput');
      
      console.log(`📷 Found ${videoDevices.length} video devices`);
      console.log(`🎤 Found ${audioDevices.length} audio devices`);
      
      if (videoDevices.length === 0) {
        setTestResult('❌ No video devices found');
      } else {
        setTestResult(`✅ Found ${videoDevices.length} video device(s) and ${audioDevices.length} audio device(s)`);
      }
      
    } catch (error) {
      console.error('❌ Failed to list devices:', error);
      setTestResult(`Error: ${error.message}`);
    }
  };

  const testSpecificDevice = async (deviceId, deviceLabel) => {
    try {
      setTestResult(`Testing: ${deviceLabel || 'Unnamed Device'}...`);
      console.log(`🧪 Testing device: "${deviceLabel}" with ID: ${deviceId}`);
      
      // Try different constraint approaches
      const constraintOptions = [
        // Option 1: Exact device ID
        {
          video: { deviceId: { exact: deviceId } },
          audio: false
        },
        // Option 2: Ideal device ID (more forgiving)
        {
          video: { deviceId: { ideal: deviceId } },
          audio: false
        },
        // Option 3: Just video with basic settings
        {
          video: {
            deviceId: { ideal: deviceId },
            width: { ideal: 640 },
            height: { ideal: 480 }
          },
          audio: false
        },
        // Option 4: Very basic - just any video
        {
          video: true,
          audio: false
        }
      ];
      
      let testStream = null;
      let successfulConstraint = null;
      
      for (let i = 0; i < constraintOptions.length; i++) {
        const constraints = constraintOptions[i];
        console.log(`🔄 Trying constraint option ${i + 1}:`, constraints);
        
        try {
          testStream = await navigator.mediaDevices.getUserMedia(constraints);
          successfulConstraint = i + 1;
          console.log(`✅ Success with constraint option ${i + 1}`);
          break;
        } catch (constraintError) {
          console.log(`❌ Constraint option ${i + 1} failed:`, constraintError.name, constraintError.message);
        }
      }
      
      if (testStream) {
        setTestResult(`✅ SUCCESS: ${deviceLabel} is working! (Used constraint option ${successfulConstraint})`);
        setStream(testStream);
        
        // Display video
        const video = document.getElementById('testVideo');
        if (video) {
          video.srcObject = testStream;
        }
        
        // Log stream details
        console.log('📊 Stream details:');
        testStream.getTracks().forEach(track => {
          console.log(`  ${track.kind}: ${track.label} (${track.readyState})`);
          const settings = track.getSettings();
          console.log(`  Settings:`, settings);
        });
        
      } else {
        setTestResult(`❌ FAILED: ${deviceLabel} - Could not access with any constraints`);
      }
      
    } catch (error) {
      console.error(`❌ Failed to access ${deviceLabel}:`, error);
      setTestResult(`❌ FAILED: ${deviceLabel} - ${error.name}: ${error.message}`);
    }
  };

  const stopTest = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
      const video = document.getElementById('testVideo');
      if (video) {
        video.srcObject = null;
      }
    }
    setTestResult('Test stopped');
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
      <h2>🔧 Device Debugger</h2>
      
      <div style={{ marginBottom: '20px' }}>
        <button onClick={listAllDevices} style={{ padding: '10px', marginRight: '10px', background: '#007bff', color: 'white', border: 'none', borderRadius: '5px' }}>
          🔄 Refresh Device List
        </button>
        <button onClick={stopTest} style={{ padding: '10px', background: '#dc3545', color: 'white', border: 'none', borderRadius: '5px' }}>
          🛑 Stop Test
        </button>
      </div>

      <div style={{ marginBottom: '20px', padding: '15px', background: '#f8f9fa', border: '1px solid #dee2e6', borderRadius: '5px' }}>
        <strong>Test Result:</strong> {testResult || 'Click "Refresh Device List" to start'}
      </div>

      <h3>📱 Available Video Devices:</h3>
      {devices.filter(d => d.kind === 'videoinput').map((device, index) => (
        <div key={device.deviceId} style={{ margin: '10px 0', padding: '10px', border: '1px solid #ccc', borderRadius: '5px' }}>
          <div><strong>Device {index + 1}:</strong> {device.label || 'Unnamed Device'}</div>
          <div><strong>ID:</strong> {device.deviceId.substring(0, 40)}...</div>
          <button 
            onClick={() => testSpecificDevice(device.deviceId, device.label)} 
            style={{ padding: '5px 10px', margin: '5px 0', background: '#28a745', color: 'white', border: 'none', borderRadius: '3px' }}
          >
            🧪 Test This Device
          </button>
        </div>
      ))}

      <h3>🎤 Available Audio Devices:</h3>
      {devices.filter(d => d.kind === 'audioinput').map((device, index) => (
        <div key={device.deviceId} style={{ margin: '5px 0', padding: '10px', border: '1px solid #ccc', borderRadius: '5px' }}>
          <div><strong>Mic {index + 1}:</strong> {device.label || 'Unnamed Microphone'}</div>
        </div>
      ))}

      <h3>📺 Video Test:</h3>
      <video 
        id="testVideo" 
        autoPlay 
        muted 
        style={{ width: '400px', height: '300px', background: '#000', border: '2px solid #ccc' }}
      />
      
      <div style={{ marginTop: '20px', fontSize: '14px', color: '#666' }}>
        <h4>📋 Instructions:</h4>
        <ol>
          <li>Click "Refresh Device List" to scan for cameras</li>
          <li>Test each video device individually</li>
          <li>See which one actually works</li>
          <li>Check the console for detailed logs</li>
        </ol>
      </div>
    </div>
  );
};

export default DeviceDebugger;