// src/utils/imageValidator.js

/**
 * Tests if an image URL is valid and can be loaded
 * @param {string} url - The image URL to test
 * @param {number} timeout - Timeout in milliseconds
 * @returns {Promise<{success: boolean, error: string|null}>} - Result object
 */
export const validateImageUrl = (url, timeout = 10000) => {
  console.log(`Testing image URL: ${url}`);
  
  if (!url) {
    return Promise.resolve({ 
      success: false, 
      error: 'No URL provided' 
    });
  }
  
  return new Promise((resolve) => {
    // Create an image element to test loading
    const img = new Image();
    let timeoutId;
    
    // Handle successful load
    img.onload = () => {
      console.log(`Image loaded successfully: ${url}`);
      clearTimeout(timeoutId);
      resolve({ 
        success: true, 
        error: null,
        width: img.width,
        height: img.height
      });
    };
    
    // Handle load errors
    img.onerror = (error) => {
      console.error(`Image failed to load: ${url}`, error);
      clearTimeout(timeoutId);
      resolve({ 
        success: false, 
        error: `Failed to load image: ${error.message || 'Unknown error'}` 
      });
    };
    
    // Set timeout in case the image hangs
    timeoutId = setTimeout(() => {
      console.warn(`Image load timed out after ${timeout}ms: ${url}`);
      resolve({ 
        success: false, 
        error: `Image load timed out after ${timeout}ms` 
      });
      
      // Cleanup
      img.src = ''; // Cancel the image request
    }, timeout);
    
    // Add cache buster to avoid cached errors
    const cacheBuster = `_cb=${Date.now()}`;
    const imageUrl = url.includes('?') ? `${url}&${cacheBuster}` : `${url}?${cacheBuster}`;
    
    // Start loading the image
    img.crossOrigin = 'anonymous'; // Try to handle CORS issues
    img.src = imageUrl;
  });
};

/**
 * Tests an Adobe Stock/Fotolia URL format
 * Often these URLs need special handling for CORS
 * @param {string} url - The URL to test
 * @returns {boolean} - True if it's likely an Adobe Stock URL
 */
export const isAdobeStockUrl = (url) => {
  if (!url) return false;
  
  // Common patterns for Adobe Stock/Fotolia URLs
  const patterns = [
    'ftcdn.net',
    'stock.adobe.com',
    't4.ftcdn.net',
    'as1.ftcdn.net',
    'as2.ftcdn.net',
    't3.ftcdn.net'
  ];
  
  return patterns.some(pattern => url.includes(pattern));
};

/**
 * Attempts to fix an Adobe Stock URL to make it more compatible
 * @param {string} url - The original URL
 * @returns {string} - A potentially fixed URL
 */
export const fixAdobeStockUrl = (url) => {
  if (!isAdobeStockUrl(url)) return url;
  
  console.log('Attempting to fix Adobe Stock URL:', url);
  
  // Remove tracking parameters that might cause issues
  let fixedUrl = url;
  
  // Replace HTTPS with HTTP if needed for testing
  // NOTE: This is only for troubleshooting - in production you should use HTTPS
  if (fixedUrl.startsWith('https://')) {
    // Uncomment the line below ONLY for testing - not for production
    // fixedUrl = fixedUrl.replace('https://', 'http://');
  }
  
  console.log('Fixed URL:', fixedUrl);
  return fixedUrl;
};

// Add to window for console debugging
window.validateImageUrl = validateImageUrl;
window.isAdobeStockUrl = isAdobeStockUrl;
window.fixAdobeStockUrl = fixAdobeStockUrl;

export default {
  validateImageUrl,
  isAdobeStockUrl,
  fixAdobeStockUrl
};