// Production-Ready Camera Detection System
// File: src/utils/productionCameraTest.js

class ProductionCameraSystem {
  constructor() {
    this.devices = [];
    this.permissionState = 'unknown';
    this.retryCount = 0;
    this.maxRetries = 3;
    this.debug = process.env.NODE_ENV === 'development';
  }

  log(message, ...args) {
    if (this.debug) {
      console.log(`[CameraSystem] ${message}`, ...args);
    }
  }

  error(message, ...args) {
    console.error(`[CameraSystem] ERROR: ${message}`, ...args);
  }

  // Main initialization method
  async initialize() {
    this.log('Starting production camera system initialization...');
    
    try {
      // Step 1: Environment validation
      await this.validateEnvironment();
      
      // Step 2: Permission check with retry logic
      const permissionResult = await this.requestPermissionsWithRetry();
      if (!permissionResult.success) {
        return permissionResult;
      }
      
      // Step 3: Enhanced device enumeration
      const devices = await this.enumerateDevicesEnhanced();
      
      // Step 4: Device validation
      const validatedDevices = await this.validateDevices(devices);
      
      this.log('✅ Camera system initialized successfully', {
        cameras: validatedDevices.cameras.length,
        microphones: validatedDevices.microphones.length
      });
      
      return {
        success: true,
        cameras: validatedDevices.cameras,
        microphones: validatedDevices.microphones,
        speakers: validatedDevices.speakers,
        permissionState: this.permissionState
      };
      
    } catch (error) {
      this.error('Fatal initialization error:', error);
      return {
        success: false,
        error: error,
        retry: this.retryCount < this.maxRetries
      };
    }
  }

  // Validate environment for camera access
  async validateEnvironment() {
    this.log('Validating environment...');
    
    // Check secure context
    if (!window.isSecureContext) {
      throw new Error('Camera access requires HTTPS in production');
    }
    
    // Check API availability
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      throw new Error('MediaDevices API not supported');
    }
    
    // Check for WebRTC support
    if (!window.RTCPeerConnection) {
      this.log('⚠️ Warning: WebRTC not fully supported');
    }
    
    this.log('Environment validation passed');
  }

  // Enhanced permission request with retry logic
  async requestPermissionsWithRetry() {
    for (let attempt = 1; attempt <= this.maxRetries; attempt++) {
      try {
        this.log(`Permission attempt ${attempt}/${this.maxRetries}...`);
        
        // Progressive permission strategy
        const result = await this.requestPermissions(attempt);
        
        if (result.success) {
          this.permissionState = 'granted';
          return result;
        }
        
        if (attempt < this.maxRetries) {
          this.log(`Attempt ${attempt} failed, waiting before retry...`);
          await this.delay(1000 * attempt); // Progressive delay
        }
        
      } catch (error) {
        this.log(`Attempt ${attempt} error:`, error.name, error.message);
        
        if (error.name === 'NotAllowedError' && attempt === this.maxRetries) {
          this.permissionState = 'denied';
          return {
            success: false,
            error: error,
            message: 'Camera permission denied. Please allow camera access and refresh the page.',
            retryable: false
          };
        }
      }
    }
    
    return {
      success: false,
      error: new Error('Permission request failed after retries'),
      retryable: true
    };
  }

  // Smart permission request strategy
  async requestPermissions(attempt) {
    const constraints = this.getPermissionConstraints(attempt);
    this.log('Requesting permissions with constraints:', constraints);
    
    const stream = await navigator.mediaDevices.getUserMedia(constraints);
    
    // Immediately release resources
    stream.getTracks().forEach(track => {
      track.stop();
      this.log(`Released ${track.kind} track`);
    });
    
    return { success: true };
  }

  // Progressive permission constraints
  getPermissionConstraints(attempt) {
    switch (attempt) {
      case 1:
        // First attempt: Standard request
        return { video: true, audio: true };
      
      case 2:
        // Second attempt: Video only
        return { video: { width: 640, height: 480 }, audio: false };
      
      case 3:
        // Final attempt: Minimal constraints
        return { 
          video: { 
            width: { min: 320 },
            height: { min: 240 },
            frameRate: { max: 30 }
          }, 
          audio: false 
        };
      
      default:
        return { video: true, audio: true };
    }
  }

  // Enhanced device enumeration with timing fixes
  async enumerateDevicesEnhanced() {
    this.log('Starting enhanced device enumeration...');
    
    // Multiple enumeration attempts to handle timing issues
    let devices = [];
    let attempts = 0;
    const maxAttempts = 3;
    
    while (attempts < maxAttempts) {
      try {
        attempts++;
        devices = await navigator.mediaDevices.enumerateDevices();
        
        const hasLabels = devices.some(d => d.label && d.label.trim() !== '');
        const videoCount = devices.filter(d => d.kind === 'videoinput').length;
        
        this.log(`Enumeration attempt ${attempts}:`, {
          totalDevices: devices.length,
          videoDevices: videoCount,
          hasLabels: hasLabels
        });
        
        // If we have video devices with labels, we're good
        if (videoCount > 0 && hasLabels) {
          break;
        }
        
        // Wait before retry
        if (attempts < maxAttempts) {
          await this.delay(500);
        }
        
      } catch (error) {
        this.error(`Device enumeration attempt ${attempts} failed:`, error);
        if (attempts === maxAttempts) throw error;
      }
    }
    
    return devices;
  }

  // Device validation and filtering
  async validateDevices(devices) {
    this.log('Validating devices...');
    
    const cameras = [];
    const microphones = [];
    const speakers = [];
    
    for (const device of devices) {
      try {
        const validatedDevice = await this.validateSingleDevice(device);
        
        if (validatedDevice) {
          switch (device.kind) {
            case 'videoinput':
              cameras.push(validatedDevice);
              break;
            case 'audioinput':
              microphones.push(validatedDevice);
              break;
            case 'audiooutput':
              speakers.push(validatedDevice);
              break;
          }
        }
      } catch (error) {
        this.log(`Device validation failed for ${device.label}:`, error.message);
      }
    }
    
    // Sort cameras to prioritize virtual cameras
    cameras.sort((a, b) => {
      const aIsVirtual = this.isVirtualCamera(a);
      const bIsVirtual = this.isVirtualCamera(b);
      
      if (aIsVirtual && !bIsVirtual) return -1;
      if (!aIsVirtual && bIsVirtual) return 1;
      return 0;
    });
    
    this.log('Device validation complete:', {
      cameras: cameras.length,
      microphones: microphones.length,
      speakers: speakers.length
    });
    
    return { cameras, microphones, speakers };
  }

  // Validate individual device
  async validateSingleDevice(device) {
    if (!device.deviceId || device.deviceId === 'default') {
      return null;
    }
    
    // Enhanced device info
    const enhancedDevice = {
      ...device,
      isVirtual: this.isVirtualCamera(device),
      priority: this.getDevicePriority(device),
      displayLabel: this.getDisplayLabel(device)
    };
    
    return enhancedDevice;
  }

  // Check if device is a virtual camera
  isVirtualCamera(device) {
    const label = (device.label || '').toLowerCase();
    const virtualKeywords = [
      'virtual', 'obs', 'streamlabs', 'xsplit', 'camera2', 
      'webcam', 'capture', 'broadcast', 'live'
    ];
    
    return virtualKeywords.some(keyword => label.includes(keyword));
  }

  // Get device priority for sorting
  getDevicePriority(device) {
    if (this.isVirtualCamera(device)) return 1;
    if (device.label && device.label.toLowerCase().includes('usb')) return 2;
    return 3;
  }

  // Get user-friendly display label
  getDisplayLabel(device) {
    if (!device.label || device.label.trim() === '') {
      const kind = device.kind.replace('input', '').replace('output', '');
      return `${kind.charAt(0).toUpperCase() + kind.slice(1)} Device`;
    }
    
    return device.label;
  }

  // Test camera access
  async testCameraAccess(deviceId = null) {
    this.log('Testing camera access...', deviceId ? `Device: ${deviceId}` : 'Default device');
    
    try {
      const constraints = {
        video: deviceId ? 
          { deviceId: { exact: deviceId }, width: 640, height: 480 } : 
          { width: 640, height: 480 },
        audio: false
      };
      
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      
      // Get actual track settings
      const videoTrack = stream.getVideoTracks()[0];
      const settings = videoTrack ? videoTrack.getSettings() : null;
      
      this.log('Camera test successful:', settings);
      
      // Clean up
      stream.getTracks().forEach(track => track.stop());
      
      return {
        success: true,
        settings: settings
      };
      
    } catch (error) {
      this.error('Camera test failed:', error);
      return {
        success: false,
        error: error
      };
    }
  }

  // Production-specific camera creation
  async createCameraStream(options = {}) {
    const {
      deviceId = null,
      width = 1280,
      height = 720,
      frameRate = 30,
      facingMode = 'user'
    } = options;
    
    this.log('Creating camera stream with options:', options);
    
    const constraints = {
      video: {
        width: { ideal: width },
        height: { ideal: height },
        frameRate: { ideal: frameRate }
      },
      audio: false
    };
    
    if (deviceId && deviceId !== 'default') {
      constraints.video.deviceId = { exact: deviceId };
    } else if (facingMode) {
      constraints.video.facingMode = facingMode;
    }
    
    try {
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      this.log('✅ Camera stream created successfully');
      return stream;
    } catch (error) {
      this.error('Failed to create camera stream:', error);
      
      // Fallback attempt with reduced constraints
      if (error.name === 'OverconstrainedError') {
        this.log('Attempting fallback with reduced constraints...');
        
        const fallbackConstraints = {
          video: deviceId ? { deviceId: { exact: deviceId } } : true,
          audio: false
        };
        
        return await navigator.mediaDevices.getUserMedia(fallbackConstraints);
      }
      
      throw error;
    }
  }

  // Utility delay function
  delay(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  // Get diagnostic info
  getDiagnosticInfo() {
    return {
      protocol: window.location.protocol,
      hostname: window.location.hostname,
      isSecureContext: window.isSecureContext,
      userAgent: navigator.userAgent.substring(0, 100),
      permissionState: this.permissionState,
      retryCount: this.retryCount,
      timestamp: new Date().toISOString()
    };
  }
}

// Singleton instance
const productionCameraSystem = new ProductionCameraSystem();

export default productionCameraSystem;
export { ProductionCameraSystem };
