// src/contexts/LiveDJSessionContext.jsx
//
// Persistent "live DJ session" controller. This provider is mounted ABOVE the
// router (see App.jsx), so a DJ's live broadcast and set recording survive
// navigation — clicking Home / opening another page no longer tears down the
// stream, because the LiveKit connection lives in the module-level
// `liveKitService` singleton and the published track / MediaRecorder are held
// here at app level rather than inside a route component that unmounts.
//
// Audio source is the persistent DJ mixer master output
// (DJMixerContext.getDJAudioStream()), so the same mixed audio is what viewers
// hear and what the recorder captures.

import React, { createContext, useContext, useState, useRef, useCallback } from 'react';
import { getFirestore, doc, updateDoc, addDoc, collection, serverTimestamp } from 'firebase/firestore';
import { generateLiveKitRoomName } from '../utils/roomNaming';
import {
  bindOccurrenceToLiveRoom,
  markOccurrenceEnded,
} from '../services/scheduledRoomsService';
import liveKitService from '../services/livekit/LiveKitService';
import {
  startReplayRecording,
  stopReplayRecording,
} from '../services/recording/replayEgressService';

const LiveDJSessionContext = createContext(null);

export const useLiveDJSession = () => {
  const ctx = useContext(LiveDJSessionContext);
  if (!ctx) {
    throw new Error('useLiveDJSession must be used within a LiveDJSessionProvider');
  }
  return ctx;
};

// Build the public watch URL a DJ can share with an audience.
const buildWatchUrl = (eventId) => {
  if (!eventId) return null;
  const origin = (typeof window !== 'undefined' && window.location?.origin) || '';
  return `${origin}/events/${eventId}`;
};

export const LiveDJSessionProvider = ({ children }) => {
  // --- Broadcast state (persists across navigation) ---
  const [isLive, setIsLive] = useState(false);
  const [liveEvent, setLiveEvent] = useState(null); // { id, title }
  const [liveStartedAt, setLiveStartedAt] = useState(null);
  const [connecting, setConnecting] = useState(false);
  const [error, setError] = useState(null);

  // --- Recording state (also persists across navigation) ---
  const [isRecording, setIsRecording] = useState(false);
  const [recordingStartedAt, setRecordingStartedAt] = useState(null);

  const publishedTrackRef = useRef(null);
  const roomNameRef = useRef(null);
  // The scheduled airing this broadcast is fulfilling, when there is one.
  const boundOccurrenceRef = useRef(null);
  const [boundOccurrence, setBoundOccurrence] = useState(null);
  const mediaRecorderRef = useRef(null);
  const recordedChunksRef = useRef([]);
  // The server-side egress recording this broadcast for replay, if one started.
  const replayEgressRef = useRef(null);

  const clearError = useCallback(() => setError(null), []);

  /**
   * Start broadcasting the DJ mixer audio into the event's LiveKit room.
   * @param {{ event: {id:string, title?:string}, user: object, audioStream: MediaStream }} args
   * The room name is `event-<id>` — the exact room viewers join at /events/:id,
   * so the mixed audio reaches the audience.
   */
  const goLive = useCallback(async ({ event, user, audioStream }) => {
    setError(null);

    if (!event?.id) {
      setError('No event to broadcast to.');
      return { success: false, error: 'no-event' };
    }
    if (isLive) {
      return { success: true, alreadyLive: true, watchUrl: buildWatchUrl(event.id) };
    }

    const audioTrack = audioStream?.getAudioTracks?.()[0];
    if (!audioTrack) {
      setError('No DJ audio available yet. Load a track into a deck first, then go live.');
      return { success: false, error: 'no-audio' };
    }

    setConnecting(true);
    try {
      const roomName = generateLiveKitRoomName(event.id);
      // Distinct identity so this audio broadcast can coexist with any camera
      // participant in the same room without a duplicate-identity conflict.
      const base = user?.displayName || user?.email || user?.uid || 'DJ';
      const participantName = `${base} (DJ Mix)`;

      const result = await liveKitService.connect(roomName, participantName, {
        autoSubscribe: false, // the DJ doesn't need to receive audience media
        roomOptions: { publishDefaults: { simulcast: false } },
      });

      if (!result?.success || !result.room) {
        throw new Error(result?.error || 'Failed to connect to the streaming room.');
      }

      const { LocalAudioTrack } = await import('livekit-client');
      // Signature: (mediaTrack, constraints, userProvidedTrack, audioContext).
      // The publication name is set on publishTrack below — passing it here
      // would land in the audioContext slot.
      const localAudioTrack = new LocalAudioTrack(audioTrack, undefined, true, undefined);

      await result.room.localParticipant.publishTrack(localAudioTrack, {
        name: 'dj-mixer-audio',
        source: 'microphone', // published as an audio source; RoomAudioRenderer plays it
      });

      publishedTrackRef.current = localAudioTrack;
      roomNameRef.current = roomName;
      setLiveEvent({ id: event.id, title: event.title || 'DJ Set' });
      setLiveStartedAt(Date.now());
      setIsLive(true);

      // Mark the event live/discoverable so it surfaces in the events + home lists.
      try {
        const db = getFirestore();
        await updateDoc(doc(db, 'events', event.id), {
          status: 'live',
          isLive: true,
          liveKitRoom: roomName,
          streamStartedAt: serverTimestamp(),
        });
      } catch (e) {
        console.warn('Could not update event status to live:', e);
      }

      // If the host has a scheduled room starting about now, point it at this
      // LiveKit room so /r/:slug plays the broadcast instead of counting down.
      const occurrence = await bindOccurrenceToLiveRoom({
        user,
        roomKey: roomName,
        eventId: event.id,
      });
      boundOccurrenceRef.current = occurrence;
      setBoundOccurrence(occurrence);

      // Record the broadcast into the replay bucket. The egress runs on
      // LiveKit's side, so it keeps recording even if this tab goes away, and a
      // failure here never stops the broadcast.
      const shouldRecord = !occurrence || occurrence.publishReplay !== false;
      replayEgressRef.current = shouldRecord
        ? await startReplayRecording({
            roomName,
            occurrenceId: occurrence ? occurrence.id : null,
            eventId: event.id,
            title: event.title || 'DJ Set',
            audioOnly: true,
          })
        : null;

      return {
        success: true,
        watchUrl: occurrence ? `/r/${occurrence.slug}` : buildWatchUrl(event.id),
        occurrence,
      };
    } catch (e) {
      console.error('❌ Failed to go live:', e);
      setError(e.message || 'Failed to go live.');
      // Best-effort cleanup of a half-open connection.
      try {
        if (roomNameRef.current) await liveKitService.disconnect(roomNameRef.current);
      } catch (_) { /* ignore */ }
      roomNameRef.current = null;
      publishedTrackRef.current = null;
      replayEgressRef.current = null;
      return { success: false, error: e.message };
    } finally {
      setConnecting(false);
    }
  }, [isLive]);

  /** Stop broadcasting and mark the event ended. */
  const endSet = useCallback(async () => {
    const eventId = liveEvent?.id;
    try {
      // Close the recording first so the file is uploaded and its URL is known
      // by the time the airing is turned into a replay.
      const egress = replayEgressRef.current;
      replayEgressRef.current = null;
      let replay = null;
      if (egress?.egressId) {
        replay = await stopReplayRecording(egress.egressId);
        if (replay && !replay.replayUrl) replay.replayUrl = egress.videoUrl || null;
        if (replay && !replay.durationMs && liveStartedAt) {
          replay.durationMs = Date.now() - liveStartedAt;
        }
      }

      if (publishedTrackRef.current) {
        try {
          if (liveKitService.currentRoom?.localParticipant) {
            liveKitService.currentRoom.localParticipant.unpublishTrack(publishedTrackRef.current);
          }
        } catch (_) { /* ignore */ }
        try { publishedTrackRef.current.stop(); } catch (_) { /* ignore */ }
        publishedTrackRef.current = null;
      }
      if (roomNameRef.current) {
        try { await liveKitService.disconnect(roomNameRef.current); } catch (_) { /* ignore */ }
        roomNameRef.current = null;
      }
      if (eventId) {
        try {
          const db = getFirestore();
          await updateDoc(doc(db, 'events', eventId), {
            status: 'ended',
            isLive: false,
            streamEndedAt: serverTimestamp(),
          });
        } catch (e) {
          console.warn('Could not update event status to ended:', e);
        }
      }
      // Close out the scheduled airing this broadcast was fulfilling: with
      // replays on it becomes a replay, otherwise it is simply ended.
      const occurrence = boundOccurrenceRef.current;
      if (occurrence) {
        try {
          await markOccurrenceEnded(occurrence, {
            publishReplay: occurrence.publishReplay !== false,
            replayId: replay ? replay.replayId : null,
            replayUrl: replay ? replay.replayUrl : null,
            durationMs: replay ? replay.durationMs : 0,
          });
        } catch (e) {
          console.warn('Could not close out the scheduled room:', e);
        }
      }
    } finally {
      boundOccurrenceRef.current = null;
      setBoundOccurrence(null);
      setIsLive(false);
      setLiveEvent(null);
      setLiveStartedAt(null);
    }
  }, [liveEvent, liveStartedAt]);

  /**
   * Record the DJ mixer master output to a file. Independent of broadcasting —
   * a DJ can record without going live. Persists across navigation.
   * @param {MediaStream} audioStream master output from DJMixerContext
   */
  const startRecording = useCallback((audioStream) => {
    setError(null);
    if (isRecording) return { success: true, alreadyRecording: true };

    if (!audioStream || typeof window.MediaRecorder === 'undefined') {
      setError('Recording is not supported in this browser.');
      return { success: false, error: 'unsupported' };
    }
    const audioTrack = audioStream.getAudioTracks?.()[0];
    if (!audioTrack) {
      setError('No DJ audio available yet. Load a track into a deck first, then record.');
      return { success: false, error: 'no-audio' };
    }

    try {
      // Pick a widely-supported container/codec.
      const mimeType = ['audio/webm;codecs=opus', 'audio/webm', 'audio/ogg']
        .find((t) => window.MediaRecorder.isTypeSupported?.(t)) || '';
      const recorder = new window.MediaRecorder(audioStream, mimeType ? { mimeType } : undefined);

      recordedChunksRef.current = [];
      recorder.ondataavailable = (e) => {
        if (e.data && e.data.size > 0) recordedChunksRef.current.push(e.data);
      };
      recorder.start(1000); // gather data every second so a long set isn't lost
      mediaRecorderRef.current = recorder;
      setRecordingStartedAt(Date.now());
      setIsRecording(true);
      return { success: true };
    } catch (e) {
      console.error('❌ Failed to start recording:', e);
      setError(e.message || 'Failed to start recording.');
      return { success: false, error: e.message };
    }
  }, [isRecording]);

  /**
   * Stop recording, download the file, and return the blob so callers can also
   * upload it. Resolves to { blob, fileName, durationMs } or null.
   */
  const stopRecording = useCallback(() => {
    return new Promise((resolve) => {
      const recorder = mediaRecorderRef.current;
      if (!recorder) {
        setIsRecording(false);
        resolve(null);
        return;
      }
      const startedAt = recordingStartedAt;
      recorder.onstop = () => {
        const type = recorder.mimeType || 'audio/webm';
        const blob = new Blob(recordedChunksRef.current, { type });
        recordedChunksRef.current = [];
        mediaRecorderRef.current = null;
        setIsRecording(false);
        setRecordingStartedAt(null);

        const ext = type.includes('ogg') ? 'ogg' : 'webm';
        const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
        const fileName = `dj-set-${stamp}.${ext}`;

        // Trigger a download so the DJ always gets their file.
        try {
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = fileName;
          document.body.appendChild(a);
          a.click();
          document.body.removeChild(a);
          setTimeout(() => URL.revokeObjectURL(url), 1000);
        } catch (e) {
          console.warn('Could not auto-download recording:', e);
        }

        resolve({ blob, fileName, durationMs: startedAt ? Date.now() - startedAt : 0 });
      };
      try {
        recorder.stop();
      } catch (e) {
        console.error('❌ Failed to stop recording:', e);
        setIsRecording(false);
        resolve(null);
      }
    });
  }, [recordingStartedAt]);

  const value = {
    // broadcast
    isLive,
    liveEvent,
    liveStartedAt,
    connecting,
    error,
    // A scheduled room's permanent link is the one worth sharing; fall back to
    // the event URL for ad-hoc sets.
    watchUrl: boundOccurrence
      ? `${window.location.origin}/r/${boundOccurrence.slug}`
      : (liveEvent ? buildWatchUrl(liveEvent.id) : null),
    boundOccurrence,
    goLive,
    endSet,
    clearError,
    // recording
    isRecording,
    recordingStartedAt,
    startRecording,
    stopRecording,
  };

  return (
    <LiveDJSessionContext.Provider value={value}>
      {children}
    </LiveDJSessionContext.Provider>
  );
};

export default LiveDJSessionContext;
