// src/components/monetization/PaymentForm.jsx
import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { createPaymentIntent, processSubscription } from '../../services/StripeService';
import { CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../../firebase';
import { AlertTriangle, CreditCard, Check } from 'lucide-react';

const PaymentForm = ({ streamId, accessLevel, accessDuration, initialAmount, onSuccess, onError, clientSecret: propClientSecret }) => {
  const { currentUser } = useAuth();
  const stripe = useStripe();
  const elements = useElements();
  const [isProcessing, setIsProcessing] = useState(false);
  const [cardError, setCardError] = useState(null);
  const [paymentSuccess, setPaymentSuccess] = useState(false);
  const [clientSecret, setClientSecret] = useState('');
  const [formData, setFormData] = useState({
    cardHolder: currentUser?.displayName || '',
    amount: initialAmount || 9.99
  });

  // Create payment intent when component mounts
  useEffect(() => {
    // If client secret is passed directly, use it
    if (propClientSecret) {
      console.log('Using client secret from props');
      setClientSecret(propClientSecret);
      return;
    }
    
    const initializePayment = async () => {
      if (!stripe || !currentUser) return;
      
      try {
        const intentAmount = formData.amount;
        
        // Create a payment intent
        const intent = await createPaymentIntent(intentAmount, 'usd', {
          streamId: streamId,
          accessLevel: accessLevel,
          accessDuration: accessDuration
        });
        
        if (intent && intent.client_secret) {
          setClientSecret(intent.client_secret);
        }
      } catch (error) {
        console.error('Error initializing payment:', error);
        setCardError('Failed to initialize payment system. Please try again.');
        if (onError) onError('Failed to initialize payment system. Please try again.');
      }
    };
    
    initializePayment();
  }, [stripe, currentUser, streamId, accessLevel, accessDuration, formData.amount, propClientSecret]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!stripe || !elements || !currentUser) {
      const errorMessage = 'Payment system not ready. Please try again in a moment.';
      setCardError(errorMessage);
      if (onError) onError(errorMessage);
      return;
    }
    
    setIsProcessing(true);
    setCardError(null);
    
    try {
      // Get card element
      const cardElement = elements.getElement(CardElement);
      
      if (!cardElement) {
        throw new Error('Card element not found. Please refresh the page and try again.');
      }
      
      // Create payment method
      const { error, paymentMethod } = await stripe.createPaymentMethod({
        type: 'card',
        card: cardElement,
        billing_details: {
          name: formData.cardHolder,
          email: currentUser.email || ''
        }
      });
      
      if (error) {
        throw new Error(error.message);
      }
      
      // Process subscription
      const result = await processSubscription(
        { ...formData, paymentMethodId: paymentMethod.id }, 
        currentUser.uid, 
        streamId || 'premium_membership', 
        accessLevel, 
        accessDuration
      );
      
      if (result.success) {
        setPaymentSuccess(true);
        if (onSuccess) onSuccess(result);
      } else {
        throw new Error(result.message || 'Payment processing failed');
      }
    } catch (error) {
      console.error('Payment error:', error);
      setCardError(error.message);
      if (onError) onError(error.message);
    } finally {
      setIsProcessing(false);
    }
  };

  if (paymentSuccess && !onSuccess) {
    return (
      <div className="payment-success">
        <div className="success-icon">
          <Check size={24} />
        </div>
        <h3>Payment Successful!</h3>
        <p>Your subscription has been activated. Thank you for your purchase!</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="payment-form">
      <div className="form-group">
        <label htmlFor="cardHolder">Cardholder Name</label>
        <input
          type="text"
          id="cardHolder"
          name="cardHolder"
          value={formData.cardHolder}
          onChange={handleInputChange}
          placeholder="Name on card"
          required
        />
      </div>
      
      <div className="form-group">
        <label>Card Information</label>
        <div className="card-element-container">
          <CardElement 
            options={{
              style: {
                base: {
                  fontSize: '16px',
                  color: '#111827',
                  '::placeholder': {
                    color: '#9CA3AF',
                  },
                },
                invalid: {
                  color: '#EF4444',
                },
              },
              hidePostalCode: true
            }}
          />
        </div>
      </div>
      
      {cardError && (
        <div className="error-message">
          <AlertTriangle size={16} />
          <span>{cardError}</span>
        </div>
      )}
      
      <div className="form-help-text">
        <p>This is a test mode integration. No real payments will be processed.</p>
        <p>Use test card number: 4242 4242 4242 4242 with any future expiration date and any CVC.</p>
      </div>
      
      <div className="form-actions">
        <button 
          type="submit" 
          className="payment-button" 
          disabled={isProcessing || !stripe}
        >
          {isProcessing ? 'Processing...' : `Pay $${formData.amount}`}
        </button>
      </div>
    </form>
  );
};

export default PaymentForm;