// src/components/deals/CreateDealModal.jsx
import React, { useState } from 'react';
import { X } from 'lucide-react';
import {
  getFirestore,
  collection,
  addDoc,
  serverTimestamp,
} from 'firebase/firestore';
import { useAuth } from '../../contexts/AuthContext';
import './CreateDealModal.css';

const PROPERTY_TYPES = ['residential', 'commercial', 'land', 'rental', 'other'];
const SIDES = ['buy', 'sell', 'both'];
const STATUSES = ['listed', 'under_contract', 'closed', 'cancelled'];

const emptyForm = {
  line1: '',
  line2: '',
  city: '',
  state: '',
  postalCode: '',
  propertyType: 'residential',
  price: '',
  side: 'sell',
  status: 'listed',
  note: '',
  visibility: 'public',
};

/**
 * Modal to log a new deal against the signed-in user.
 * Writes to firestore `deals` collection. Agent star tier is recomputed by
 * the `onDealWrite` Cloud Function (see REAL_ESTATE_PIVOT_PLAN.md §7).
 */
const CreateDealModal = ({ open, onClose, onCreated }) => {
  const { currentUser } = useAuth();
  const [form, setForm] = useState(emptyForm);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');

  if (!open) return null;

  const update = (field) => (e) =>
    setForm((prev) => ({ ...prev, [field]: e.target.value }));

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (!currentUser) {
      setError('You must be signed in to log a deal.');
      return;
    }
    if (!form.city || !form.state) {
      setError('City and state are required.');
      return;
    }
    const priceNumber = Number(form.price);
    if (!Number.isFinite(priceNumber) || priceNumber <= 0) {
      setError('Price must be a positive number.');
      return;
    }

    setSubmitting(true);
    try {
      const db = getFirestore();
      const now = serverTimestamp();
      const closedAt = form.status === 'closed' ? now : null;
      const contractAt = form.status === 'under_contract' ? now : null;

      const docRef = await addDoc(collection(db, 'deals'), {
        agentId: currentUser.uid,
        address: {
          line1: form.line1.trim(),
          line2: form.line2.trim(),
          city: form.city.trim(),
          state: form.state.trim(),
          postalCode: form.postalCode.trim(),
        },
        propertyType: form.propertyType,
        price: priceNumber,
        currency: 'USD',
        status: form.status,
        side: form.side,
        listedAt: now,
        contractAt,
        closedAt,
        visibility: form.visibility,
        note: form.note.trim() || null,
        createdAt: now,
        updatedAt: now,
      });

      setForm(emptyForm);
      onCreated && onCreated(docRef.id);
      onClose && onClose();
    } catch (err) {
      console.error('Failed to create deal:', err);
      setError(err.message || 'Failed to create deal.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="create-deal__overlay" onClick={onClose}>
      <div className="create-deal__modal" onClick={(e) => e.stopPropagation()}>
        <div className="create-deal__header">
          <h2>Log a deal</h2>
          <button className="create-deal__close" onClick={onClose} aria-label="Close">
            <X size={20} />
          </button>
        </div>

        <form className="create-deal__form" onSubmit={handleSubmit}>
          <label>
            Street address
            <input value={form.line1} onChange={update('line1')} placeholder="123 Main St" />
          </label>

          <div className="create-deal__row">
            <label>
              City *
              <input value={form.city} onChange={update('city')} required />
            </label>
            <label>
              State *
              <input value={form.state} onChange={update('state')} required />
            </label>
            <label>
              Postal code
              <input value={form.postalCode} onChange={update('postalCode')} />
            </label>
          </div>

          <div className="create-deal__row">
            <label>
              Property type
              <select value={form.propertyType} onChange={update('propertyType')}>
                {PROPERTY_TYPES.map((t) => (
                  <option key={t} value={t}>{t}</option>
                ))}
              </select>
            </label>
            <label>
              Side
              <select value={form.side} onChange={update('side')}>
                {SIDES.map((s) => <option key={s} value={s}>{s}</option>)}
              </select>
            </label>
            <label>
              Status
              <select value={form.status} onChange={update('status')}>
                {STATUSES.map((s) => (
                  <option key={s} value={s}>{s.replace('_', ' ')}</option>
                ))}
              </select>
            </label>
          </div>

          <div className="create-deal__row">
            <label>
              Price (USD) *
              <input
                type="number"
                min="0"
                step="1"
                value={form.price}
                onChange={update('price')}
                required
              />
            </label>
            <label>
              Visibility
              <select value={form.visibility} onChange={update('visibility')}>
                <option value="public">Public — show on feed</option>
                <option value="unlisted">Unlisted — only on my profile</option>
              </select>
            </label>
          </div>

          <label>
            Headline note
            <input
              value={form.note}
              onChange={update('note')}
              placeholder="e.g. First condo in Brooklyn"
              maxLength={140}
            />
          </label>

          {error && <div className="create-deal__error">{error}</div>}

          <div className="create-deal__actions">
            <button type="button" className="create-deal__btn ghost" onClick={onClose}>
              Cancel
            </button>
            <button type="submit" className="create-deal__btn primary" disabled={submitting}>
              {submitting ? 'Saving…' : 'Log deal'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default CreateDealModal;
