// src/predict/components/PredictWrapper.jsx
//
// Route-level wrapper for Predict pages. Scopes Predict's design tokens
// and keyframes under .predict-app, and provides Predict's React contexts
// (PredictionProvider, LiveDataProvider) only within this subtree —
// keeping them out of TalkStudio's global provider stack.

import React from 'react';
import { PredictionProvider } from '../contexts/PredictionContext.jsx';
import { LiveDataProvider } from '../contexts/LiveDataContext.jsx';
import FreeTierBanner from '../../components/premium/FreeTierBanner';
import '../predict.css';

const PredictWrapper = ({ children }) => {
  return (
    <div className="predict-app" style={{ padding: '16px 24px' }}>
      <FreeTierBanner section="Markets" />
      <PredictionProvider>
        <LiveDataProvider>
          {children}
        </LiveDataProvider>
      </PredictionProvider>
    </div>
  );
};

export default PredictWrapper;
