// src/admin/TipAdminPanel.jsx
import React, { useState, useEffect } from 'react';
import { 
  DollarSign, 
  Settings, 
  Percent, 
  Users, 
  Building2, 
  TrendingUp,
  Save,
  RefreshCw,
  AlertCircle,
  CheckCircle,
  Edit,
  Plus,
  Trash2
} from 'lucide-react';
import { 
  getFirestore, 
  doc, 
  getDoc, 
  setDoc, 
  collection, 
  query, 
  where, 
  orderBy, 
  onSnapshot,
  updateDoc,
  deleteDoc,
  addDoc,
  serverTimestamp 
} from 'firebase/firestore';
import './TipAdminPanel.css';
import TipManager from '../services/TipManager.js';
import { getCurrentTipConfig } from '../config/tipConfig.js';

const TipAdminPanel = () => {
  const [tipSettings, setTipSettings] = useState({
    enabled: true,
    minimumTip: 1.00,
    maximumTip: 500.00,
    defaultSplits: {
      artist: 50,
      platform: 30,
      venue: 20
    },
    platformFee: 5, // Percentage fee for platform
    processingFee: 0.30 // Fixed processing fee
  });

  const [venueSettings, setVenueSettings] = useState([]);
  const [tipStats, setTipStats] = useState({
    totalTips: 0,
    totalVolume: 0,
    platformRevenue: 0,
    artistRevenue: 0,
    venueRevenue: 0,
    todayTips: 0,
    todayVolume: 0
  });

  const [eventOverrides, setEventOverrides] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState({ type: '', text: '' });
  const [showAddVenue, setShowAddVenue] = useState(false);
  const [newVenue, setNewVenue] = useState({ name: '', defaultSplit: 20 });
  
  // Enhanced tipping data
  const [recentTips, setRecentTips] = useState([]);
  const [topEvents, setTopEvents] = useState([]);
  const [topArtists, setTopArtists] = useState([]);
  const [environmentConfig, setEnvironmentConfig] = useState(null);
  const [selectedTimeRange, setSelectedTimeRange] = useState('7d'); // 1d, 7d, 30d, all

  useEffect(() => {
    loadTipSettings();
    loadVenueSettings();
    loadTipStats();
    setupRealtimeListeners();
    loadEnvironmentConfig();
    loadEnhancedTipData();
  }, []);

  const loadTipSettings = async () => {
    try {
      const db = getFirestore();
      const settingsDoc = await getDoc(doc(db, 'admin', 'tipSettings'));
      
      if (settingsDoc.exists()) {
        setTipSettings(prev => ({ ...prev, ...settingsDoc.data() }));
      }
    } catch (error) {
      console.error('Error loading tip settings:', error);
      showMessage('error', 'Failed to load tip settings');
    }
  };

  const loadVenueSettings = async () => {
    try {
      const db = getFirestore();
      const venuesDoc = await getDoc(doc(db, 'admin', 'venues'));
      
      if (venuesDoc.exists()) {
        setVenueSettings(venuesDoc.data().venues || []);
      }
    } catch (error) {
      console.error('Error loading venue settings:', error);
      showMessage('error', 'Failed to load venue settings');
    }
  };

  const loadTipStats = async () => {
    try {
      const db = getFirestore();
      const statsDoc = await getDoc(doc(db, 'admin', 'tipStats'));
      
      if (statsDoc.exists()) {
        setTipStats(prev => ({ ...prev, ...statsDoc.data() }));
      }
    } catch (error) {
      console.error('Error loading tip stats:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadEnvironmentConfig = () => {
    try {
      const config = getCurrentTipConfig();
      setEnvironmentConfig(config);
      console.log('🌍 Environment config loaded:', config);
    } catch (error) {
      console.error('Error loading environment config:', error);
    }
  };

  const loadEnhancedTipData = async () => {
    try {
      const db = getFirestore();
      
      // Load recent tips
      const recentTipsQuery = query(
        collection(db, 'tips'),
        orderBy('createdAt', 'desc'),
        where('status', '==', 'completed')
      );
      
      const unsubscribeTips = onSnapshot(recentTipsQuery, (snapshot) => {
        const tips = snapshot.docs.slice(0, 20).map(doc => ({
          id: doc.id,
          ...doc.data()
        }));
        setRecentTips(tips);
        
        // Calculate top events and artists from recent tips
        calculateTopStats(tips);
      });
      
      return () => {
        unsubscribeTips();
      };
    } catch (error) {
      console.error('Error loading enhanced tip data:', error);
    }
  };

  const calculateTopStats = (tips) => {
    // Group by events
    const eventStats = {};
    const artistStats = {};
    
    tips.forEach(tip => {
      // Event stats
      if (tip.eventId) {
        if (!eventStats[tip.eventId]) {
          eventStats[tip.eventId] = {
            eventId: tip.eventId,
            eventTitle: tip.eventTitle || 'Unknown Event',
            totalAmount: 0,
            tipCount: 0
          };
        }
        eventStats[tip.eventId].totalAmount += tip.amount;
        eventStats[tip.eventId].tipCount += 1;
      }
      
      // Artist stats
      if (tip.artistId) {
        if (!artistStats[tip.artistId]) {
          artistStats[tip.artistId] = {
            artistId: tip.artistId,
            artistName: tip.artistName || 'Unknown Artist',
            totalAmount: 0,
            tipCount: 0,
            eventCount: new Set()
          };
        }
        artistStats[tip.artistId].totalAmount += tip.amount;
        artistStats[tip.artistId].tipCount += 1;
        if (tip.eventId) {
          artistStats[tip.artistId].eventCount.add(tip.eventId);
        }
      }
    });
    
    // Sort and set top events
    const sortedEvents = Object.values(eventStats)
      .sort((a, b) => b.totalAmount - a.totalAmount)
      .slice(0, 10);
    setTopEvents(sortedEvents);
    
    // Sort and set top artists
    const sortedArtists = Object.values(artistStats)
      .map(artist => ({
        ...artist,
        eventCount: artist.eventCount.size
      }))
      .sort((a, b) => b.totalAmount - a.totalAmount)
      .slice(0, 10);
    setTopArtists(sortedArtists);
  };

  const setupRealtimeListeners = () => {
    const db = getFirestore();
    
    // Listen for tip statistics updates
    const unsubscribeStats = onSnapshot(doc(db, 'admin', 'tipStats'), (doc) => {
      if (doc.exists()) {
        setTipStats(prev => ({ ...prev, ...doc.data() }));
      }
    });

    // Listen for event overrides
    const unsubscribeOverrides = onSnapshot(
      query(collection(db, 'tipOverrides'), orderBy('createdAt', 'desc')), 
      (snapshot) => {
        const overrides = snapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        }));
        setEventOverrides(overrides);
      }
    );

    // Setup enhanced tip data listener
    const unsubscribeEnhanced = loadEnhancedTipData();

    return () => {
      unsubscribeStats();
      unsubscribeOverrides();
      if (unsubscribeEnhanced) {
        unsubscribeEnhanced();
      }
    };
  };

  const saveTipSettings = async () => {
    setSaving(true);
    try {
      const db = getFirestore();
      await setDoc(doc(db, 'admin', 'tipSettings'), {
        ...tipSettings,
        updatedAt: serverTimestamp()
      });

      showMessage('success', 'Tip settings saved successfully');
    } catch (error) {
      console.error('Error saving tip settings:', error);
      showMessage('error', 'Failed to save tip settings');
    } finally {
      setSaving(false);
    }
  };

  const saveVenueSettings = async () => {
    setSaving(true);
    try {
      const db = getFirestore();
      await setDoc(doc(db, 'admin', 'venues'), {
        venues: venueSettings,
        updatedAt: serverTimestamp()
      });

      showMessage('success', 'Venue settings saved successfully');
    } catch (error) {
      console.error('Error saving venue settings:', error);
      showMessage('error', 'Failed to save venue settings');
    } finally {
      setSaving(false);
    }
  };

  const addVenue = async () => {
    if (!newVenue.name.trim()) {
      showMessage('error', 'Venue name is required');
      return;
    }

    const venue = {
      id: Date.now().toString(),
      name: newVenue.name.trim(),
      defaultSplit: newVenue.defaultSplit,
      createdAt: Date.now()
    };

    setVenueSettings(prev => [...prev, venue]);
    setNewVenue({ name: '', defaultSplit: 20 });
    setShowAddVenue(false);
    
    await saveVenueSettings();
  };

  const removeVenue = async (venueId) => {
    if (!confirm('Are you sure you want to remove this venue?')) return;

    setVenueSettings(prev => prev.filter(v => v.id !== venueId));
    await saveVenueSettings();
  };

  const updateSplit = (type, value) => {
    const newValue = Math.max(0, Math.min(100, parseInt(value) || 0));
    
    setTipSettings(prev => ({
      ...prev,
      defaultSplits: {
        ...prev.defaultSplits,
        [type]: newValue
      }
    }));
  };

  const validateSplits = () => {
    const total = Object.values(tipSettings.defaultSplits).reduce((sum, val) => sum + val, 0);
    return Math.abs(total - 100) < 0.01; // Allow for small floating point errors
  };

  const showMessage = (type, text) => {
    setMessage({ type, text });
    setTimeout(() => setMessage({ type: '', text: '' }), 5000);
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD'
    }).format(amount || 0);
  };

  if (loading) {
    return (
      <div className="tip-admin-loading">
        <RefreshCw size={32} className="spinning" />
        <p>Loading tip administration...</p>
      </div>
    );
  }

  const splitsValid = validateSplits();
  const totalSplit = Object.values(tipSettings.defaultSplits).reduce((sum, val) => sum + val, 0);

  return (
    <div className="tip-admin-panel">
      <div className="admin-header">
        <div className="header-content">
          <DollarSign size={28} />
          <div>
            <h1>Tip Administration</h1>
            <p>Manage tip settings, revenue splits, and venue partnerships</p>
          </div>
        </div>
        
        {message.text && (
          <div className={`admin-message ${message.type}`}>
            {message.type === 'success' ? <CheckCircle size={16} /> : <AlertCircle size={16} />}
            <span>{message.text}</span>
          </div>
        )}
      </div>

      <div className="admin-grid">
        {/* Environment Configuration */}
        {environmentConfig && (
          <div className="admin-card environment-card">
            <div className="card-header">
              <Settings size={20} />
              <h2>Environment Configuration</h2>
              <div className={`env-badge ${environmentConfig.useSandbox ? 'sandbox' : 'production'}`}>
                {environmentConfig.name}
              </div>
            </div>
            
            <div className="environment-details">
              <div className="env-info">
                <div className="info-item">
                  <span className="label">Environment:</span>
                  <span className="value">{environmentConfig.name}</span>
                </div>
                <div className="info-item">
                  <span className="label">Sandbox Mode:</span>
                  <span className={`value ${environmentConfig.useSandbox ? 'sandbox' : 'production'}`}>
                    {environmentConfig.useSandbox ? 'Yes' : 'No'}
                  </span>
                </div>
                <div className="info-item">
                  <span className="label">Enabled:</span>
                  <span className={`value ${environmentConfig.enabled ? 'enabled' : 'disabled'}`}>
                    {environmentConfig.enabled ? 'Yes' : 'No'}
                  </span>
                </div>
              </div>
              
              <div className="stripe-urls">
                <h4>Stripe Payment URLs:</h4>
                <div className="url-list">
                  <div className="url-item">
                    <span className="amount">$20:</span>
                    <span className="url">{environmentConfig.stripeUrls.tip20}</span>
                  </div>
                  <div className="url-item">
                    <span className="amount">$50:</span>
                    <span className="url">{environmentConfig.stripeUrls.tip50}</span>
                  </div>
                  <div className="url-item">
                    <span className="amount">$100:</span>
                    <span className="url">{environmentConfig.stripeUrls.tip100}</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Tip Statistics */}
        <div className="admin-card stats-card">
          <div className="card-header">
            <TrendingUp size={20} />
            <h2>Tip Statistics</h2>
          </div>
          
          <div className="stats-grid">
            <div className="stat-item">
              <div className="stat-value">{formatCurrency(tipStats.totalVolume)}</div>
              <div className="stat-label">Total Volume</div>
            </div>
            <div className="stat-item">
              <div className="stat-value">{tipStats.totalTips}</div>
              <div className="stat-label">Total Tips</div>
            </div>
            <div className="stat-item">
              <div className="stat-value">{formatCurrency(tipStats.platformRevenue)}</div>
              <div className="stat-label">Platform Revenue</div>
            </div>
            <div className="stat-item">
              <div className="stat-value">{formatCurrency(tipStats.artistRevenue)}</div>
              <div className="stat-label">Artist Revenue</div>
            </div>
            <div className="stat-item">
              <div className="stat-value">{formatCurrency(tipStats.venueRevenue)}</div>
              <div className="stat-label">Venue Revenue</div>
            </div>
            <div className="stat-item">
              <div className="stat-value">{formatCurrency(tipStats.todayVolume)}</div>
              <div className="stat-label">Today's Volume</div>
            </div>
          </div>
        </div>

        {/* Global Tip Settings */}
        <div className="admin-card">
          <div className="card-header">
            <Settings size={20} />
            <h2>Global Tip Settings</h2>
          </div>
          
          <div className="settings-form">
            <div className="form-group">
              <label>
                <input
                  type="checkbox"
                  checked={tipSettings.enabled}
                  onChange={(e) => setTipSettings(prev => ({ ...prev, enabled: e.target.checked }))}
                />
                Enable Tipping System
              </label>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label>Minimum Tip Amount</label>
                <div className="input-with-currency">
                  <span>$</span>
                  <input
                    type="number"
                    min="0.01"
                    step="0.01"
                    value={tipSettings.minimumTip}
                    onChange={(e) => setTipSettings(prev => ({ ...prev, minimumTip: parseFloat(e.target.value) || 0 }))}
                  />
                </div>
              </div>
              
              <div className="form-group">
                <label>Maximum Tip Amount</label>
                <div className="input-with-currency">
                  <span>$</span>
                  <input
                    type="number"
                    min="1"
                    value={tipSettings.maximumTip}
                    onChange={(e) => setTipSettings(prev => ({ ...prev, maximumTip: parseFloat(e.target.value) || 0 }))}
                  />
                </div>
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label>Platform Fee (%)</label>
                <div className="input-with-symbol">
                  <input
                    type="number"
                    min="0"
                    max="100"
                    step="0.1"
                    value={tipSettings.platformFee}
                    onChange={(e) => setTipSettings(prev => ({ ...prev, platformFee: parseFloat(e.target.value) || 0 }))}
                  />
                  <span>%</span>
                </div>
              </div>
              
              <div className="form-group">
                <label>Processing Fee</label>
                <div className="input-with-currency">
                  <span>$</span>
                  <input
                    type="number"
                    min="0"
                    step="0.01"
                    value={tipSettings.processingFee}
                    onChange={(e) => setTipSettings(prev => ({ ...prev, processingFee: parseFloat(e.target.value) || 0 }))}
                  />
                </div>
              </div>
            </div>

            <button 
              className="save-btn"
              onClick={saveTipSettings}
              disabled={saving}
            >
              {saving ? <RefreshCw size={16} className="spinning" /> : <Save size={16} />}
              Save Settings
            </button>
          </div>
        </div>

        {/* Revenue Split Settings */}
        <div className="admin-card">
          <div className="card-header">
            <Percent size={20} />
            <h2>Default Revenue Splits</h2>
          </div>
          
          <div className="splits-form">
            <div className="split-item">
              <Users size={16} />
              <label>Artist/Creator</label>
              <div className="split-input">
                <input
                  type="number"
                  min="0"
                  max="100"
                  value={tipSettings.defaultSplits.artist}
                  onChange={(e) => updateSplit('artist', e.target.value)}
                />
                <span>%</span>
              </div>
            </div>

            <div className="split-item">
              <DollarSign size={16} />
              <label>TalkStudio</label>
              <div className="split-input">
                <input
                  type="number"
                  min="0"
                  max="100"
                  value={tipSettings.defaultSplits.platform}
                  onChange={(e) => updateSplit('platform', e.target.value)}
                />
                <span>%</span>
              </div>
            </div>

            <div className="split-item">
              <Building2 size={16} />
              <label>Venue</label>
              <div className="split-input">
                <input
                  type="number"
                  min="0"
                  max="100"
                  value={tipSettings.defaultSplits.venue}
                  onChange={(e) => updateSplit('venue', e.target.value)}
                />
                <span>%</span>
              </div>
            </div>

            <div className={`split-total ${splitsValid ? 'valid' : 'invalid'}`}>
              <strong>Total: {totalSplit}%</strong>
              {!splitsValid && <span className="error-text">Must equal 100%</span>}
            </div>

            <button 
              className="save-btn"
              onClick={saveTipSettings}
              disabled={saving || !splitsValid}
            >
              {saving ? <RefreshCw size={16} className="spinning" /> : <Save size={16} />}
              Save Splits
            </button>
          </div>
        </div>

        {/* Venue Management */}
        <div className="admin-card">
          <div className="card-header">
            <Building2 size={20} />
            <h2>Venue Management</h2>
            <button 
              className="add-btn"
              onClick={() => setShowAddVenue(true)}
            >
              <Plus size={16} />
              Add Venue
            </button>
          </div>
          
          {showAddVenue && (
            <div className="add-venue-form">
              <div className="form-row">
                <input
                  type="text"
                  placeholder="Venue name"
                  value={newVenue.name}
                  onChange={(e) => setNewVenue(prev => ({ ...prev, name: e.target.value }))}
                />
                <div className="input-with-symbol">
                  <input
                    type="number"
                    min="0"
                    max="100"
                    value={newVenue.defaultSplit}
                    onChange={(e) => setNewVenue(prev => ({ ...prev, defaultSplit: parseInt(e.target.value) || 0 }))}
                  />
                  <span>%</span>
                </div>
              </div>
              <div className="form-actions">
                <button onClick={addVenue} className="primary-btn">Add</button>
                <button onClick={() => setShowAddVenue(false)} className="secondary-btn">Cancel</button>
              </div>
            </div>
          )}

          <div className="venues-list">
            {venueSettings.map((venue) => (
              <div key={venue.id} className="venue-item">
                <div className="venue-info">
                  <Building2 size={16} />
                  <span className="venue-name">{venue.name}</span>
                  <span className="venue-split">{venue.defaultSplit}%</span>
                </div>
                <button 
                  className="delete-btn"
                  onClick={() => removeVenue(venue.id)}
                >
                  <Trash2 size={14} />
                </button>
              </div>
            ))}
            
            {venueSettings.length === 0 && (
              <div className="empty-state">
                <Building2 size={32} />
                <p>No venues configured</p>
                <p className="empty-subtitle">Add venues to enable venue revenue sharing</p>
              </div>
            )}
          </div>
        </div>

        {/* Recent Tips Activity */}
        <div className="admin-card full-width">
          <div className="card-header">
            <DollarSign size={20} />
            <h2>Recent Tips Activity</h2>
            <div className="tip-count-badge">
              {recentTips.length} recent tips
            </div>
          </div>
          
          <div className="recent-tips-table">
            <div className="table-header">
              <div>Time</div>
              <div>Event</div>
              <div>Artist</div>
              <div>Amount</div>
              <div>Tipper</div>
              <div>Environment</div>
            </div>
            
            {recentTips.map((tip) => (
              <div key={tip.id} className="table-row">
                <div>{new Date(tip.createdAt?.seconds * 1000 || tip.createdAt).toLocaleString()}</div>
                <div>{tip.eventTitle || 'Unknown Event'}</div>
                <div>{tip.artistName || 'Unknown Artist'}</div>
                <div className="amount">{formatCurrency(tip.amount)}</div>
                <div>{tip.userName || 'Anonymous'}</div>
                <div className={`env-badge ${tip.useSandbox ? 'sandbox' : 'production'}`}>
                  {tip.environment || (tip.useSandbox ? 'Sandbox' : 'Production')}
                </div>
              </div>
            ))}
            
            {recentTips.length === 0 && (
              <div className="empty-table">
                <DollarSign size={32} />
                <p>No recent tips found</p>
                <p className="empty-subtitle">Recent tip activity will appear here</p>
              </div>
            )}
          </div>
        </div>

        {/* Top Events */}
        <div className="admin-card">
          <div className="card-header">
            <TrendingUp size={20} />
            <h2>Top Events by Tips</h2>
          </div>
          
          <div className="top-stats-list">
            {topEvents.map((event, index) => (
              <div key={event.eventId} className="stat-item-detailed">
                <div className="rank">#{index + 1}</div>
                <div className="details">
                  <div className="name">{event.eventTitle}</div>
                  <div className="stats">
                    {formatCurrency(event.totalAmount)} • {event.tipCount} tips
                  </div>
                </div>
              </div>
            ))}
            
            {topEvents.length === 0 && (
              <div className="empty-state">
                <TrendingUp size={32} />
                <p>No event data available</p>
              </div>
            )}
          </div>
        </div>

        {/* Top Artists */}
        <div className="admin-card">
          <div className="card-header">
            <Users size={20} />
            <h2>Top Artists by Tips</h2>
          </div>
          
          <div className="top-stats-list">
            {topArtists.map((artist, index) => (
              <div key={artist.artistId} className="stat-item-detailed">
                <div className="rank">#{index + 1}</div>
                <div className="details">
                  <div className="name">{artist.artistName}</div>
                  <div className="stats">
                    {formatCurrency(artist.totalAmount)} • {artist.tipCount} tips • {artist.eventCount} events
                  </div>
                </div>
              </div>
            ))}
            
            {topArtists.length === 0 && (
              <div className="empty-state">
                <Users size={32} />
                <p>No artist data available</p>
              </div>
            )}
          </div>
        </div>

        {/* Event Overrides */}
        <div className="admin-card full-width">
          <div className="card-header">
            <Edit size={20} />
            <h2>Event-Specific Overrides</h2>
          </div>
          
          <div className="overrides-table">
            <div className="table-header">
              <div>Event</div>
              <div>Artist Split</div>
              <div>Platform Split</div>
              <div>Venue Split</div>
              <div>Venue</div>
              <div>Status</div>
            </div>
            
            {eventOverrides.map((override) => (
              <div key={override.id} className="table-row">
                <div>{override.eventTitle}</div>
                <div>{override.artistSplit}%</div>
                <div>{override.platformSplit}%</div>
                <div>{override.venueSplit}%</div>
                <div>{override.venueName || 'None'}</div>
                <div className={`status ${override.active ? 'active' : 'inactive'}`}>
                  {override.active ? 'Active' : 'Inactive'}
                </div>
              </div>
            ))}
            
            {eventOverrides.length === 0 && (
              <div className="empty-table">
                <Edit size={32} />
                <p>No event overrides configured</p>
                <p className="empty-subtitle">Event-specific revenue splits will appear here</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TipAdminPanel;