// src/components/widgets/CreateChatWidget.jsx
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ref, push, set, serverTimestamp } from 'firebase/database';
import { rtdb } from '../../firebase';
import { useAuth } from '../../contexts/AuthContext';
import { Plus } from 'lucide-react';
import './CreateChatWidget.css';

/**
 * CreateChatWidget - A simple button that creates a new chat room with a temporary name
 * Users can rename the room once they enter it
 */
const CreateChatWidget = ({ onRoomCreated }) => {
  const [isCreating, setIsCreating] = useState(false);
  const navigate = useNavigate();
  const { currentUser } = useAuth();

  // Handle creating a new room
  const handleCreateRoom = async () => {
    // Check if user is logged in
    if (!currentUser || currentUser.isAnonymous) {
      if (window.confirm('You need to be logged in to create a room. Would you like to login?')) {
        navigate('/login', { state: { from: '/create-room' } });
      }
      return;
    }

    try {
      setIsCreating(true);
      console.log('Creating new chat room...');
      
      // Create a new room in the database
      const roomsRef = ref(rtdb, 'chats/public');
      const newRoomRef = push(roomsRef);
      
      // Generate a temporary name
      const tempName = `New Room (${new Date().toLocaleTimeString()})`;
      
      // Default room data
      const roomData = {
        name: tempName,
        description: 'Click to edit room details',
        type: 'public',
        createdAt: serverTimestamp(),
        createdBy: currentUser.uid,
        creatorName: currentUser.displayName || 'Anonymous',
        isNewRoom: true, // Flag to indicate this is a new room that needs renaming
        active: true,
        activeUsers: 0
      };
      
      // Save the room data
      await set(newRoomRef, roomData);
      console.log('Room created with ID:', newRoomRef.key);
      
      // Call the callback or navigate to the new room
      if (onRoomCreated) {
        onRoomCreated(newRoomRef.key);
      } else {
        navigate(`/room/${newRoomRef.key}`);
      }
    } catch (error) {
      console.error('Error creating room:', error);
      alert('Failed to create room. Please try again.');
    } finally {
      setIsCreating(false);
    }
  };

  return (
    <button 
      className="create-room-button" 
      onClick={handleCreateRoom}
      disabled={isCreating}
    >
      <Plus size={16} />
      {isCreating ? 'Creating...' : 'Create Room'}
    </button>
  );
};

export default CreateChatWidget;