// Debug panel to monitor streaming status and connections

import React, { useState, useEffect } from 'react';
import { Activity, Wifi, WifiOff, Video, VideoOff, AlertTriangle, CheckCircle } from 'lucide-react';

const StreamingDebugPanel = ({ 
  webrtcProducer, 
  userStreamData, 
  isStreaming, 
  localStream,
  className = '' 
}) => {
  const [debugInfo, setDebugInfo] = useState({});
  const [isExpanded, setIsExpanded] = useState(false);

  useEffect(() => {
    const updateDebugInfo = () => {
      const info = {
        timestamp: new Date().toLocaleTimeString(),
        streaming: {
          isActive: isStreaming,
          streamName: userStreamData?.streamName || 'none',
          streamUrl: userStreamData?.streamUrl || 'none'
        },
        localMedia: {
          hasStream: !!localStream,
          videoTracks: localStream?.getVideoTracks()?.length || 0,
          audioTracks: localStream?.getAudioTracks()?.length || 0,
          videoEnabled: localStream?.getVideoTracks()?.[0]?.enabled || false,
          audioEnabled: localStream?.getAudioTracks()?.[0]?.enabled || false
        },
        producer: webrtcProducer ? {
          type: webrtcProducer.constructor.name,
          status: webrtcProducer.getStatus ? webrtcProducer.getStatus() : 'unknown',
          isProducing: webrtcProducer.isProducing || false
        } : null
      };
      
      setDebugInfo(info);
    };

    updateDebugInfo();
    const interval = setInterval(updateDebugInfo, 1000);
    
    return () => clearInterval(interval);
  }, [webrtcProducer, userStreamData, isStreaming, localStream]);

  const getStatusIcon = (condition) => {
    return condition ? <CheckCircle size={14} className="text-green-500" /> : <AlertTriangle size={14} className="text-red-500" />;
  };

  if (!isExpanded) {
    return (
      <div className={`fixed bottom-4 right-4 z-50 ${className}`}>
        <button
          onClick={() => setIsExpanded(true)}
          className="bg-black bg-opacity-80 text-white p-3 rounded-lg border border-purple-500 hover:bg-opacity-90 transition-all"
          title="Show streaming debug info"
        >
          <Activity size={20} />
        </button>
      </div>
    );
  }

  return (
    <div className={`fixed bottom-4 right-4 z-50 ${className}`}>
      <div className="bg-black bg-opacity-95 text-white p-4 rounded-lg border border-purple-500 max-w-md">
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-sm font-bold text-purple-400 flex items-center gap-2">
            <Activity size={16} />
            Streaming Debug
          </h3>
          <button
            onClick={() => setIsExpanded(false)}
            className="text-gray-400 hover:text-white text-sm"
          >
            ✕
          </button>
        </div>

        <div className="space-y-3 text-xs">
          {/* Streaming Status */}
          <div className="border border-gray-700 rounded p-2">
            <div className="font-semibold text-blue-400 mb-1">Stream Status</div>
            <div className="flex items-center gap-2">
              {getStatusIcon(debugInfo.streaming?.isActive)}
              <span>{debugInfo.streaming?.isActive ? 'ACTIVE' : 'INACTIVE'}</span>
            </div>
            {debugInfo.streaming?.streamName !== 'none' && (
              <div className="mt-1 text-gray-300">
                <div>Stream: {debugInfo.streaming?.streamName}</div>
              </div>
            )}
          </div>

          {/* Local Media */}
          <div className="border border-gray-700 rounded p-2">
            <div className="font-semibold text-green-400 mb-1">Local Media</div>
            <div className="space-y-1">
              <div className="flex items-center gap-2">
                {getStatusIcon(debugInfo.localMedia?.hasStream)}
                <span>Stream: {debugInfo.localMedia?.hasStream ? 'Available' : 'None'}</span>
              </div>
              {debugInfo.localMedia?.hasStream && (
                <>
                  <div className="flex items-center gap-2">
                    {debugInfo.localMedia?.videoEnabled ? <Video size={12} className="text-green-500" /> : <VideoOff size={12} className="text-red-500" />}
                    <span>Video: {debugInfo.localMedia?.videoTracks} tracks</span>
                  </div>
                  <div className="flex items-center gap-2">
                    {debugInfo.localMedia?.audioEnabled ? <Wifi size={12} className="text-green-500" /> : <WifiOff size={12} className="text-red-500" />}
                    <span>Audio: {debugInfo.localMedia?.audioTracks} tracks</span>
                  </div>
                </>
              )}
            </div>
          </div>

          {/* Producer Status */}
          <div className="border border-gray-700 rounded p-2">
            <div className="font-semibold text-yellow-400 mb-1">Producer</div>
            {debugInfo.producer ? (
              <div className="space-y-1">
                <div className="flex items-center gap-2">
                  {getStatusIcon(debugInfo.producer?.isProducing)}
                  <span>{debugInfo.producer?.type}</span>
                </div>
                {debugInfo.producer?.status && typeof debugInfo.producer.status === 'object' && (
                  <div className="text-gray-300 text-xs">
                    {Object.entries(debugInfo.producer.status).map(([key, value]) => (
                      <div key={key}>{key}: {String(value)}</div>
                    ))}
                  </div>
                )}
              </div>
            ) : (
              <div className="flex items-center gap-2">
                <AlertTriangle size={14} className="text-orange-500" />
                <span>No producer active</span>
              </div>
            )}
          </div>

          {/* Timestamp */}
          <div className="text-center text-gray-500 text-xs border-t border-gray-700 pt-2">
            Last update: {debugInfo.timestamp}
          </div>
        </div>
      </div>
    </div>
  );
};

export default StreamingDebugPanel;