// src/pages/JamFeedPage.jsx
//
// Public feed of published jams. Each card plays inline (the engine
// re-renders from the stored note events — no audio files), shows the
// remix attribution chain, and a Remix button opens the Jam Studio
// preloaded with the jam's layers.

import React, { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Play,
  Square,
  Heart,
  GitBranch,
  ChevronLeft,
  Music2,
  Loader,
} from 'lucide-react';

import { createSketchEngine } from '../services/sketchEngine';
import { listJams, likeJam, countPlay } from '../services/jamService';

const JamFeedPage = () => {
  const navigate = useNavigate();
  const [jams, setJams] = useState(null); // null = loading
  const [error, setError] = useState(null);
  const [playingId, setPlayingId] = useState(null);
  const [progress, setProgress] = useState(0);
  const [liked, setLiked] = useState(new Set()); // session-local dedupe
  const engineRef = useRef(null);

  useEffect(() => {
    (async () => {
      try {
        setJams(await listJams({ max: 30 }));
      } catch (e) {
        setError(e.message || 'Could not load jams');
      }
    })();
    return () => {
      if (engineRef.current) {
        engineRef.current.dispose();
        engineRef.current = null;
      }
    };
  }, []);

  const ensureEngine = async () => {
    if (engineRef.current) return engineRef.current;
    const eng = await createSketchEngine();
    eng.setOnTick(({ pct, ended }) => {
      setProgress(pct);
      if (ended) setPlayingId(null);
    });
    engineRef.current = eng;
    return eng;
  };

  const playJam = async (jam) => {
    const eng = await ensureEngine();
    if (playingId === jam.id) {
      eng.stop();
      setPlayingId(null);
      return;
    }
    eng.loadLayers(jam.layers || [], jam.theory);
    await eng.playLayers();
    setPlayingId(jam.id);
    setProgress(0);
    countPlay(jam.id);
  };

  const like = async (jam) => {
    if (liked.has(jam.id)) return;
    setLiked(prev => new Set(prev).add(jam.id));
    setJams(prev => prev.map(j => (j.id === jam.id ? { ...j, likes: (j.likes || 0) + 1 } : j)));
    try { await likeJam(jam.id); } catch (_) { /* keep optimistic */ }
  };

  return (
    <div
      style={{
        minHeight: '100vh',
        background:
          'radial-gradient(circle at 20% 0%, rgba(127, 119, 221, 0.18), transparent 55%),' +
          'radial-gradient(circle at 80% 100%, rgba(93, 202, 165, 0.10), transparent 60%),' +
          '#0a0a12',
        color: '#e8e8f0',
        fontFamily: '-apple-system, BlinkMacSystemFont, system-ui, sans-serif',
        padding: '1rem',
      }}
    >
      <div style={{ maxWidth: 640, margin: '0 auto' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <button
            onClick={() => navigate(-1)}
            style={{
              background: 'transparent', border: 'none', color: '#8b8b9a',
              display: 'inline-flex', alignItems: 'center', gap: 4,
              padding: '0.5rem 0', cursor: 'pointer', fontSize: '0.85rem',
            }}
          >
            <ChevronLeft size={16} /> Back
          </button>
          <button
            onClick={() => navigate('/sketch')}
            style={{
              background: '#534AB7', border: 'none', color: 'white',
              display: 'inline-flex', alignItems: 'center', gap: 6,
              padding: '8px 14px', borderRadius: 8, cursor: 'pointer', fontSize: 12, fontWeight: 500,
            }}
          >
            <Music2 size={14} /> New jam
          </button>
        </div>

        <h1 style={{ fontSize: '1.4rem', fontWeight: 600, margin: '0.5rem 0 0.25rem' }}>
          Jam Feed
        </h1>
        <p style={{ color: '#8b8b9a', fontSize: '0.9rem', margin: '0 0 1.25rem' }}>
          Jams from the community. Play them, like them, remix them.
        </p>

        {jams === null && !error && (
          <div style={{ textAlign: 'center', color: '#6b6b7a', padding: '3rem 0' }}>
            <Loader size={24} className="jamfeed-spin" />
            <style>{`.jamfeed-spin { animation: jamfeed-spin 1s linear infinite; } @keyframes jamfeed-spin { from { transform: rotate(0); } to { transform: rotate(360deg); } }`}</style>
          </div>
        )}
        {error && <div style={{ color: '#fca5a5', fontSize: 13 }}>{error}</div>}
        {jams && jams.length === 0 && (
          <div style={{ textAlign: 'center', color: '#6b6b7a', padding: '3rem 0', fontSize: 14 }}>
            No jams yet — be the first to publish one.
          </div>
        )}

        {jams && jams.map(jam => {
          const isPlaying = playingId === jam.id;
          const chain = (jam.attribution || []).map(a => a.name).join(' → ');
          return (
            <div
              key={jam.id}
              style={{
                background: '#15151e',
                border: '0.5px solid ' + (isPlaying ? '#3C3489' : '#25252e'),
                borderRadius: 12,
                padding: 14,
                marginBottom: 10,
              }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <button
                  onClick={() => playJam(jam)}
                  title={isPlaying ? 'Stop' : 'Play'}
                  style={{
                    background: isPlaying ? '#E24B4A' : '#534AB7',
                    color: 'white', border: 'none',
                    width: 42, height: 42, borderRadius: '50%',
                    cursor: 'pointer', flexShrink: 0,
                    display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                  }}
                >
                  {isPlaying ? <Square size={16} fill="white" /> : <Play size={18} />}
                </button>

                <div style={{ flex: 1, minWidth: 0 }}>
                  <div
                    onClick={() => navigate(`/track/${jam.id}`)}
                    title="Open track page"
                    style={{ fontSize: 14, fontWeight: 500, cursor: 'pointer', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}
                  >
                    {jam.title}
                  </div>
                  <div style={{ fontSize: 11, color: '#6b6b7a', marginTop: 2 }}>
                    {jam.theory ? `${jam.theory.keyName} ${jam.theory.scaleName} · ${jam.theory.tempo} bpm · ` : ''}
                    {(jam.layers || []).length} layers
                    {jam.parentJamId ? ' · remix' : ''}
                  </div>
                  {chain && (
                    <div style={{ fontSize: 11, color: '#5DCAA5', marginTop: 2, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                      {chain}
                    </div>
                  )}
                </div>

                <div style={{ display: 'flex', gap: 6, flexShrink: 0 }}>
                  <button
                    onClick={() => like(jam)}
                    title="Like"
                    style={{
                      background: 'transparent',
                      border: '1px solid #25252e',
                      color: liked.has(jam.id) ? '#F0999A' : '#8b8b9a',
                      padding: '6px 10px', borderRadius: 8, cursor: 'pointer',
                      display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: 12,
                    }}
                  >
                    <Heart size={13} fill={liked.has(jam.id) ? 'currentColor' : 'none'} />
                    {jam.likes || 0}
                  </button>
                  <button
                    onClick={() => navigate(`/sketch?remix=${jam.id}`)}
                    title="Remix this jam"
                    style={{
                      background: '#0d1f1a', border: '1px solid #1D9E75', color: '#5DCAA5',
                      padding: '6px 10px', borderRadius: 8, cursor: 'pointer',
                      display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: 12,
                    }}
                  >
                    <GitBranch size={13} />
                    {jam.remixCount || 0}
                  </button>
                </div>
              </div>

              {isPlaying && (
                <div style={{ height: 3, background: '#0a0a12', borderRadius: 2, overflow: 'hidden', marginTop: 10 }}>
                  <div
                    style={{
                      width: `${Math.round(progress * 100)}%`, height: '100%',
                      background: 'linear-gradient(90deg, #7F77DD, #5DCAA5)',
                      transition: 'width 0.1s linear',
                    }}
                  />
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default JamFeedPage;
