import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';
import { getFirestore, collection, query, where, orderBy, onSnapshot, doc, getDoc } from 'firebase/firestore';
import {
Calendar, 
Clock, 
Users, 
DollarSign, 
Star, 
Crown, 
Play, 
Lock,
TrendingUp,
Music,
Mic,
Video,
Plus,
  History,
  Activity,
  Wifi,
  WifiOff
} from 'lucide-react';
import CreateEventModal from './CreateEventModal';
import { checkEventAccess, getEventButtonText, EVENT_ACCESS_TYPES } from '../../utils/eventAccessTypes';
import eventLiveStatusManager from '../../services/events/EventLiveStatusManager';
import './EventsList.css';

const EventsList = () => {
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all'); // all, live, upcoming, past
  const [userSubscription, setUserSubscription] = useState(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [liveEventStatus, setLiveEventStatus] = useState(new Map()); // eventId -> live status

  useEffect(() => {
    setLoading(true);
    
    // Set a timeout to prevent infinite loading
    const loadingTimeout = setTimeout(() => {
      console.warn('Events loading timeout');
      setLoading(false);
    }, 10000); // 10 second timeout
    
    const unsubscribe = loadEvents();
    
    if (currentUser) {
      checkUserSubscription();
    }
    
    // Check live status of events every 2 minutes
    const liveStatusInterval = setInterval(() => {
      updateLiveEventStatus();
    }, 2 * 60 * 1000); // Every 2 minutes
    
    // Initial live status check
    updateLiveEventStatus();
    
    // Cleanup timeout when component unmounts or dependencies change
    return () => {
      clearTimeout(loadingTimeout);
      clearInterval(liveStatusInterval);
      if (unsubscribe && typeof unsubscribe === 'function') {
        unsubscribe();
      }
    };
  }, [currentUser, filter]);

  const updateLiveEventStatus = async () => {
    try {
      // Get all events marked as 'live' and check their actual status
      const actuallyLiveEvents = await eventLiveStatusManager.getActuallyLiveEvents();
      
      const statusMap = new Map();
      actuallyLiveEvents.forEach(liveEvent => {
        statusMap.set(liveEvent.eventId, {
          isActuallyLive: true,
          ...liveEvent
        });
      });
      
      // Update events that should show as live but aren't marked as such
      events.forEach(event => {
        if (event.status === 'live' && !statusMap.has(event.id)) {
          statusMap.set(event.id, {
            isActuallyLive: false,
            reason: 'stale_or_inactive',
            status: 'inactive'
          });
        }
      });
      
      setLiveEventStatus(statusMap);
      
      console.log(`📊 Live status updated for ${statusMap.size} events`, {
        actuallyLive: actuallyLiveEvents.length,
        totalChecked: statusMap.size
      });
      
    } catch (error) {
      console.error('❌ Failed to update live event status:', error);
    }
  };

  const loadEvents = () => {
    try {
      const db = getFirestore();
      let eventsQuery;
      
      // Create base query without filters first
      if (filter === 'live') {
        eventsQuery = query(
          collection(db, 'events'),
          where('status', '==', 'live'),
          orderBy('startTime', 'desc')
        );
      } else if (filter === 'upcoming') {
        const now = Date.now();
        eventsQuery = query(
          collection(db, 'events'),
          where('status', '==', 'scheduled'),
          where('startTime', '>', now),
          orderBy('startTime', 'asc') // Upcoming events: earliest first
        );
      } else if (filter === 'past') {
        eventsQuery = query(
          collection(db, 'events'),
          where('status', '==', 'ended'),
          orderBy('startTime', 'desc')
        );
      } else {
        // For 'all' filter, get all events and sort them client-side
        eventsQuery = query(
          collection(db, 'events'),
          orderBy('startTime', 'asc')
        );
      }
      
      const unsubscribe = onSnapshot(eventsQuery, 
        (snapshot) => {
          let eventsList = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
          }));
          
          // For 'all' filter, separate and sort events
          if (filter === 'all') {
            const now = Date.now();
            const liveEvents = eventsList.filter(e => e.status === 'live');
            const upcomingEvents = eventsList
              .filter(e => e.status === 'scheduled' && e.startTime > now)
              .sort((a, b) => a.startTime - b.startTime);
            const pastEvents = eventsList
              .filter(e => e.status === 'ended' || (e.status === 'scheduled' && e.startTime <= now))
              .sort((a, b) => b.startTime - a.startTime);
            
            // Combine: live first, then upcoming, then past
            eventsList = [...liveEvents, ...upcomingEvents, ...pastEvents];
          }
          
          setEvents(eventsList);
          setLoading(false);
          
          // Update live status after events are loaded
          if (eventsList.length > 0) {
            updateLiveEventStatus();
          }
        },
        (error) => {
          console.error('Error loading events:', error);
          setLoading(false);
          setEvents([]);
        }
      );
      
      return unsubscribe;
    } catch (error) {
      console.error('Error setting up events listener:', error);
      setLoading(false);
      setEvents([]);
    }
  };

  const checkUserSubscription = async () => {
    try {
      if (!currentUser) {
        setUserSubscription(null);
        return;
      }
      
      const db = getFirestore();
      const userDoc = await getDoc(doc(db, 'users', currentUser.uid));
      const userData = userDoc.data();
      
      setUserSubscription({
        isPremium: userData?.isPremium === true,
        isVIP: userData?.isVIP === true,
        eventTickets: userData?.eventTickets || []
      });
    } catch (error) {
      console.error('Failed to check subscription:', error);
    }
  };

  const hasAccess = (event) => {
    // Create user object for access checking
    // Handle completely unauthenticated users (null currentUser)
    const user = currentUser ? {
      isAnonymous: currentUser.isAnonymous || false,
      isPremium: userSubscription?.isPremium || false,
      isVIP: userSubscription?.isVIP || false
    } : null; // null means completely unauthenticated
    
    // Normalize event access level (use Firebase field name)
    const accessLevel = event.accessLevel || EVENT_ACCESS_TYPES.REGISTRATION_REQUIRED;
    
    const accessResult = checkEventAccess(user, accessLevel);
    return accessResult.canAccess;
  };
  
  const isAnonymousUser = () => {
    // Treat null currentUser as anonymous for UI purposes
    return !currentUser || currentUser.isAnonymous;
  };

  const joinEvent = (eventId) => {
    const event = events.find(e => e.id === eventId);
    if (!event) return;
    
    // If event is ended (past event), navigate to watch-replays with event ID
    if (event.status === 'ended') {
      navigate(`/watch-replays?event=${eventId}`);
      return;
    }
    
    // For live/scheduled events, handle access checking
    const user = currentUser ? {
      isAnonymous: currentUser.isAnonymous || false,
      isPremium: userSubscription?.isPremium || false,
      isVIP: userSubscription?.isVIP || false
    } : null; // null means completely unauthenticated
    
    const accessLevel = event.accessLevel || EVENT_ACCESS_TYPES.REGISTRATION_REQUIRED;
    const accessResult = checkEventAccess(user, accessLevel);
    
    if (accessResult.canAccess) {
      // User has access, go to live event
      navigate(`/events/${eventId}`);
      return;
    }
    
    // Handle access denial based on reason
    switch (accessResult.reason) {
      case 'registration_required':
        navigate('/signup', { state: { returnTo: `/events/${eventId}` } });
        break;
      case 'upgrade_required':
      case 'vip_required':
        navigate('/premium-membership', { state: { returnTo: `/events/${eventId}` } });
        break;
      default:
        // Fallback - redirect to signup
        navigate('/signup', { state: { returnTo: `/events/${eventId}` } });
    }
  };

  const formatEventTime = (startTime, status, eventId) => {
    const eventDate = new Date(startTime);
    const now = new Date();
    const diffMs = eventDate.getTime() - now.getTime();
    const diffMins = Math.round(diffMs / (1000 * 60));
    
    // Check actual live status for events marked as 'live'
    if (status === 'live') {
      const liveStatus = liveEventStatus.get(eventId);
      
      if (liveStatus?.isActuallyLive) {
        return 'LIVE NOW';
      } else if (liveStatus && !liveStatus.isActuallyLive) {
        // Event is marked live but not actually streaming
        switch (liveStatus.reason) {
          case 'stale_or_inactive':
          case 'inactive_too_long':
            return 'OFFLINE';
          case 'expired':
            return 'ENDED';
          default:
            return 'CHECKING';
        }
      } else {
        // Status unknown, show checking
        return 'CHECKING';
      }
    } else if (diffMins < 0) {
      return 'Started';
    } else if (diffMins === 0) {
      return 'Starting now';
    } else if (diffMins < 60) {
      return `Starts in ${diffMins}m`;
    } else if (diffMins < 1440) {
      const hours = Math.round(diffMins / 60);
      return `Starts in ${hours}h`;
    } else {
      const days = Math.round(diffMins / 1440);
      return `Starts in ${days}d`;
    }
  };

  const getEventTypeIcon = (type) => {
    switch (type) {
      case 'music': return <Music size={20} />;
      case 'talk': return <Mic size={20} />;
      case 'performance': return <Video size={20} />;
      default: return <Play size={20} />;
    }
  };

  const getStatusColor = (status, eventId) => {
    if (status === 'live') {
      const liveStatus = liveEventStatus.get(eventId);
      if (liveStatus?.isActuallyLive) {
        return '#ef4444'; // Red for actually live
      } else if (liveStatus && !liveStatus.isActuallyLive) {
        return '#6b7280'; // Gray for inactive/offline
      } else {
        return '#f59e0b'; // Yellow for checking
      }
    }
    
    switch (status) {
      case 'scheduled': return '#3b82f6';
      case 'ended': return '#6b7280';
      default: return '#6b7280';
    }
  };

  const getLiveStatusIcon = (status, eventId) => {
    if (status === 'live') {
      const liveStatus = liveEventStatus.get(eventId);
      if (liveStatus?.isActuallyLive) {
        return <Wifi size={16} className="text-green-500" title="Actually streaming" />;
      } else if (liveStatus && !liveStatus.isActuallyLive) {
        return <WifiOff size={16} className="text-red-500" title="Not streaming" />;
      } else {
        return <Activity size={16} className="text-yellow-500 animate-pulse" title="Checking status" />;
      }
    }
    return null;
  };

  if (loading) {
    return (
      <div className="events-loading">
        <div className="loading-spinner"></div>
        <p>Loading events...</p>
      </div>
    );
  }

  return (
    <div className="events-list">
      {/* Header */}
      <div className="events-header">
        <div className="header-content">
          <h1>Events Theatre</h1>
          <p>{isAnonymousUser() ? 'Live events and interactive experiences' : 'Exclusive live events for premium members'}</p>
        </div>
        
        <div className="header-actions">
          {/* Create Event Button - Available for all registered users */}
          {!isAnonymousUser() && (
            <button 
              className="create-event-btn"
              onClick={() => setShowCreateModal(true)}
            >
              <Plus size={16} />
              Create Event
            </button>
          )}
          
          {isAnonymousUser() ? (
            <button 
              className="upgrade-btn"
              onClick={() => navigate('/signup')}
            >
              <Crown size={16} />
              Join Now
            </button>
          ) : !userSubscription?.isPremium && !userSubscription?.isVIP ? (
            <button 
              className="upgrade-btn"
              onClick={() => navigate('/premium-membership')}
            >
              <Crown size={16} />
              Upgrade to Premium
            </button>
          ) : null}
        </div>
      </div>

      {/* Filters */}
      <div className="events-filters">
        <button 
          className={`filter-btn ${filter === 'all' ? 'active' : ''}`}
          onClick={() => setFilter('all')}
        >
          All Events
        </button>
        <button 
          className={`filter-btn ${filter === 'live' ? 'active' : ''}`}
          onClick={() => setFilter('live')}
        >
          <div className="live-dot"></div>
          Live Now
        </button>
        <button 
          className={`filter-btn ${filter === 'upcoming' ? 'active' : ''}`}
          onClick={() => setFilter('upcoming')}
        >
          Upcoming
        </button>
        <button 
          className={`filter-btn ${filter === 'past' ? 'active' : ''}`}
          onClick={() => setFilter('past')}
        >
          Past Events
        </button>
      </div>

      {/* Events List - Row Format */}
      <div className="events-list-container">
        {events.length > 0 ? (
          <div className="events-rows">
            {events.map((event) => {
              const eventDate = new Date(event.startTime);
              const isToday = eventDate.toDateString() === new Date().toDateString();
              const isTomorrow = eventDate.toDateString() === new Date(Date.now() + 86400000).toDateString();
              const liveStatus = liveEventStatus.get(event.id);
              const isActuallyLive = event.status === 'live' && liveStatus?.isActuallyLive;
              
              let dateLabel;
              if (isActuallyLive) {
                dateLabel = 'LIVE NOW';
              } else if (event.status === 'live' && !isActuallyLive) {
                dateLabel = 'OFFLINE';
              } else if (isToday) {
                dateLabel = 'Today';
              } else if (isTomorrow) {
                dateLabel = 'Tomorrow';
              } else {
                dateLabel = eventDate.toLocaleDateString('en-US', {
                  weekday: 'long',
                  month: 'short',
                  day: 'numeric'
                });
              }
              
              return (
                <div key={event.id} className="event-row">
                  {/* Date Column */}
                  <div className="event-date-column">
                    <div className={`event-date-label ${
                      isActuallyLive ? 'live' :
                      (event.status === 'live' && !isActuallyLive) ? 'offline' :
                      isToday ? 'today' :
                      isTomorrow ? 'tomorrow' : 'future'
                    }`}>
                      {dateLabel}
                    </div>
                    <div className="event-time">
                      <Clock size={14} style={{ display: 'inline', marginRight: '4px' }} />
                      {eventDate.toLocaleTimeString('en-US', {
                        hour: '2-digit',
                        minute: '2-digit',
                        hour12: true
                      })}
                      {event.endTime && (
                        <>
                          {' - '}
                          {new Date(event.endTime).toLocaleTimeString('en-US', {
                            hour: '2-digit',
                            minute: '2-digit',
                            hour12: true
                          })}
                        </>
                      )}
                    </div>
                    <div className="event-duration" style={{ fontSize: '12px', color: '#888', marginTop: '2px' }}>
                      Duration: {event.duration || 60} min
                    </div>
                    <div className={`event-time-status ${
                      isActuallyLive ? 'live' :
                      (event.status === 'live' && !isActuallyLive) ? 'offline' :
                      formatEventTime(event.startTime, event.status, event.id).includes('Starting') ? 'starting' :
                      formatEventTime(event.startTime, event.status, event.id).includes('Starts in') ? 'upcoming' :
                      'default'
                    }`}>
                      {formatEventTime(event.startTime, event.status, event.id)}
                    </div>
                  </div>
                  
                  {/* Event Info Column */}
                  <div className="event-info-column">
                    <div className="event-main-info">
                      <div className="event-thumbnail-small">
                        {event.thumbnailUrl ? (
                          <img src={event.thumbnailUrl} alt={event.title} />
                        ) : (
                          <div className="thumbnail-placeholder-small">
                            {getEventTypeIcon(event.category || event.type)}
                          </div>
                        )}
                        
                        {/* Enhanced status indicator with activity tracking */}
                        {event.status === 'live' && (
                          <div className="live-indicator">
                            {isActuallyLive ? (
                              <div className="live-dot-small pulsing" title="Actually live"></div>
                            ) : liveStatus && !liveStatus.isActuallyLive ? (
                              <div className="offline-dot-small" title="Marked live but not streaming"></div>
                            ) : (
                              <div className="checking-dot-small" title="Checking status"></div>
                            )}
                          </div>
                        )}
                      </div>
                      
                      <div className="event-details">
                        <h3 className="event-title-row">{event.title}</h3>
                        <p className="event-description-row">{event.description}</p>
                        
                        <div className="event-meta-row">
                          <div className="artist-info-row">
                            {event.artistAvatar ? (
                              <img src={event.artistAvatar} alt={event.artistName} className="artist-avatar-small" />
                            ) : (
                              <div className="artist-avatar-small placeholder">
                                {event.artistName?.charAt(0) || 'A'}
                              </div>
                            )}
                            <span className="artist-name-small">{event.artistName}</span>
                            {event.artistVerified && <Star size={12} className="verified-small" />}
                          </div>
                          
                          <div className="event-stats">
                            <span className="viewer-count">
                              <Users size={14} />
                              {event.viewerCount || 0}
                            </span>
                            <span className="event-category">{event.category}</span>
                            
                            {/* Live status indicator */}
                            {event.status === 'live' && (
                              <span className="live-status-indicator" title="Stream status">
                                {getLiveStatusIcon(event.status, event.id)}
                              </span>
                            )}
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                  
                  {/* Actions Column */}
                  <div className="event-actions-column">
                    <div className="member-actions-row">
                      <button 
                        className="join-btn-row primary"
                        onClick={() => joinEvent(event.id)}
                      >
                        <Play size={16} />
                        {isActuallyLive ? 'Join Live' : 
                         event.status === 'live' && !isActuallyLive ? 'Stream Offline' :
                         event.status === 'scheduled' ? 'Join Event' : 'Watch Replay'}
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="events-empty">
            <TrendingUp size={64} />
            <h3>No Events Found</h3>
            <p>There are no events matching your current filter. Check back soon for upcoming events!</p>
          </div>
        )}
      </div>

      {/* Create Event Modal */}
      <CreateEventModal 
        isOpen={showCreateModal}
        onClose={() => setShowCreateModal(false)}
        onEventCreated={(eventId) => {
          // The event will automatically appear in the list due to the real-time listener
        }}
      />

      {/* Premium CTA - Only show for non-premium users, hide for anonymous */}
      {!isAnonymousUser() && !userSubscription?.isPremium && !userSubscription?.isVIP && (
        <div className="premium-cta">
          <div className="cta-content">
            <Crown size={48} />
            <h2>Unlock All Events</h2>
            <p>Get unlimited access to all live events, exclusive content, and premium features.</p>
            <div className="cta-features">
              <div className="feature-item">
                <Star size={16} />
                <span>Unlimited event access</span>
              </div>
              <div className="feature-item">
                <Video size={16} />
                <span>HD streaming quality</span>
              </div>
              <div className="feature-item">
                <Users size={16} />
                <span>VIP chat privileges</span>
              </div>
            </div>
            <button 
              className="cta-button"
              onClick={() => navigate('/premium-membership')}
            >
              <Crown size={16} />
              Upgrade to Premium
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default EventsList;