// src/components/chat/PublicChatsPage.jsx
import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { ref, onValue, off, push, set, serverTimestamp } from 'firebase/database';
import { rtdb, auth } from '../../firebase';
import { searchPublicChatRooms } from '../../utils/firebase-search-utils';
import { useAuth } from '../../contexts/AuthContext';
import { useSiteConfig } from '../../contexts/SiteConfigContext';
import { usePayment } from '../../contexts/PaymentContext';
import { debugRoomData, debugRoomIssues } from '../../utils/debug-utils';
import UserStatusBadge from '../common/UserStatusBadge';
import './PublicChatsPage.css';
import { MessageSquare, Plus, Search, X, Lock, Users, Globe, Star, Edit } from 'lucide-react';
import VipChatRooms from './VipChatRooms';
import { sortRoomsByTypeAndActivity, sortRoomsByActivity, ROOM_FILTER_ORDER, getRoomTypeDisplayName } from '../../utils/roomSortingUtils';

// Helper component to render markdown-style bold text
const MarkdownText = ({ text }) => {
  // Replace **text** with <strong>text</strong>
  if (!text) return null;
  
  const parts = text.split(/(\*\*.*?\*\*)/g);
  
  return (
    <>
      {parts.map((part, index) => {
        if (part.startsWith('**') && part.endsWith('**')) {
          // Extract text between ** and make it bold
          const boldText = part.substring(2, part.length - 2);
          return <strong key={index}>{boldText}</strong>;
        }
        return part;
      })}
    </>
  );
};

const PublicChatsPage = () => {
  const [rooms, setRooms] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [showResults, setShowResults] = useState(false);
  const [loading, setLoading] = useState(true);
  const [searchLoading, setSearchLoading] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newRoomName, setNewRoomName] = useState('');
  const [newRoomDescription, setNewRoomDescription] = useState('');
  const [editingRoomId, setEditingRoomId] = useState(null);
  const [error, setError] = useState(null);
  
  // New state variables for room type
  const [roomType, setRoomType] = useState('public');
  const [accessCode, setAccessCode] = useState('');
  const [roomFilter, setRoomFilter] = useState('all'); // 'all', 'public', 'registered', 'private'
  
  const searchTimeoutRef = useRef(null);
  const searchInputRef = useRef(null);
  const searchResultsRef = useRef(null);
  const navigate = useNavigate();
  const { config } = useSiteConfig();
  const { currentUser } = useAuth();
  const { isPremium } = usePayment();
  
  // Check if user is anonymous
  const isAnonymous = currentUser?.isAnonymous || false;
  const [anonymousUsername, setAnonymousUsername] = useState('');
  
  // Get or generate anonymous username
  useEffect(() => {
    if (isAnonymous || !currentUser) {
      const storedUsername = localStorage.getItem('anonymousUsername');
      
      if (storedUsername) {
        setAnonymousUsername(storedUsername);
      } else {
        // Generate a random username with format: Word + Number
        const adjectives = ['Solar', 'Cosmic', 'Lunar', 'Stellar', 'Quantum', 'Cyber', 'Digital', 'Mystic', 'Astro', 'Neon'];
        const nouns = ['Fox', 'Wolf', 'Eagle', 'Tiger', 'Dragon', 'Lion', 'Hawk', 'Bear', 'Panther', 'Phoenix'];
        
        const randomAdjective = adjectives[Math.floor(Math.random() * adjectives.length)];
        const randomNoun = nouns[Math.floor(Math.random() * nouns.length)];
        const randomNumber = Math.floor(1000 + Math.random() * 9000); // 4 digit number
        
        const username = `${randomAdjective}${randomNoun}${randomNumber}`;
        localStorage.setItem('anonymousUsername', username);
        setAnonymousUsername(username);
      }
    }
  }, [isAnonymous, currentUser]);

  // Generate room icon based on type
  const getRoomIcon = (roomType) => {
    switch (roomType) {
      case 'private':
        return <Lock size={16} className="room-icon private" />;
      case 'registered':
        return <Users size={16} className="room-icon registered" />;
      case 'vip':
        return <Star size={16} className="room-icon vip" />;
      case 'event':
        return <MessageSquare size={16} className="room-icon event" />;
      case 'public':
      default:
        return <Globe size={16} className="room-icon public" />;
    }
  };

  // Subscribe to rooms from Realtime Database
  useEffect(() => {
    console.log('🔍 [PublicChatsPage] Setting up rooms subscription with user:', 
      currentUser ? `${currentUser.uid} (${currentUser.isAnonymous ? 'anonymous' : 'logged-in'})` : 'no user');
      
    const roomsRef = ref(rtdb, 'chats/public');
    
    setLoading(true);
    setError(null);
    
    // Set up real-time listener
    const unsubscribe = onValue(roomsRef, (snapshot) => {
      try {
        console.log('📡 [PublicChatsPage] Firebase snapshot received, exists:', snapshot.exists());
        
        if (snapshot.exists()) {
          const roomsData = [];
          
          console.log('📊 [PublicChatsPage] Processing rooms from Firebase...');
          
          // Convert snapshot to array of room objects
          snapshot.forEach((childSnapshot) => {
            const id = childSnapshot.key;
            const roomData = childSnapshot.val();
            
            console.log(`🏠 [PublicChatsPage] Processing room ${id}:`, {
              name: roomData.name,
              type: roomData.type,
              active: roomData.active
            });
            
            // Skip entries without a name or eventTitle
            if (!roomData.name && !roomData.eventTitle) {
              console.log(`⚠️  [PublicChatsPage] Skipping room ${id} - no name or eventTitle`);
              return;
            }
            
            // For event chat rooms, use eventTitle as name
            const roomName = roomData.name || roomData.eventTitle;
            const roomDescription = roomData.description || 
              (roomData.type === 'event' ? `Event by ${roomData.artistName}` : '');
            
            // Filter out messages from the room data to avoid huge objects
            const { messages, ...roomWithoutMessages } = roomData;
            
            const processedRoom = { 
              id, 
              ...roomWithoutMessages,
              name: roomName,
              description: roomDescription,
              // Handle active status and participant count
              active: roomData.active !== false, // Default to true if not specified
              participants: typeof roomData.activeUsers === 'object' 
                ? Object.keys(roomData.activeUsers || {}).length 
                : roomData.activeUsers || roomData.participantCount || 0,
              // Set default room type if not specified
              type: roomData.type || 'public'
            };
            
            console.log(`✅ [PublicChatsPage] Added room:`, processedRoom);
            roomsData.push(processedRoom);
          });
          
          // Sort rooms using the custom sorting utility
          const sortedRoomsData = sortRoomsByTypeAndActivity(roomsData);
          
          console.log(`🎯 [PublicChatsPage] Fetched ${roomsData.length} rooms from database:`, 
            roomsData.map(r => ({ id: r.id, name: r.name, type: r.type })));
          setRooms(sortedRoomsData);
          
          // Debug room data
          if (typeof debugRoomData === 'function') {
            debugRoomData(roomsData, currentUser, 'PublicChatsPage');
          }
          if (typeof debugRoomIssues === 'function') {
            debugRoomIssues(roomsData);
          }
        } else {
          console.log("🔄 [PublicChatsPage] No rooms found in database, using fallback data");
          // Fallback data if no rooms exist
          const fallbackRooms = [
            { id: "general", name: 'General Chat', description: 'General discussion about any topic', participants: 45, active: true, type: 'public' },
            { id: "tech", name: 'Tech Talk', description: 'Discussion about technology and programming', participants: 32, active: true, type: 'public' },
            { id: "design", name: 'Design & UX', description: 'Talk about design, UI/UX and user experience', participants: 28, active: true, type: 'public' },
            { id: "gaming", name: 'Gaming', description: 'All things gaming related', participants: 53, active: true, type: 'public' }
          ];
          console.log('🎯 [PublicChatsPage] Setting fallback rooms:', fallbackRooms.map(r => ({ id: r.id, name: r.name, type: r.type })));
          setRooms(fallbackRooms);
        }
      } catch (error) {
        console.error("❌ [PublicChatsPage] Firebase error:", error);
        setError("Error loading chat rooms. Please try again later.");
        
        // Fallback data
        const fallbackRooms = [
          { id: "general", name: 'General Chat', description: 'General discussion about any topic', participants: 45, active: true, type: 'public' },
          { id: "tech", name: 'Tech Talk', description: 'Discussion about technology and programming', participants: 32, active: true, type: 'public' },
          { id: "design", name: 'Design & UX', description: 'Talk about design, UI/UX and user experience', participants: 28, active: true, type: 'public' },
          { id: "gaming", name: 'Gaming', description: 'All things gaming related', participants: 53, active: true, type: 'public' }
        ];
        console.log('🔄 [PublicChatsPage] Setting error fallback rooms:', fallbackRooms.map(r => ({ id: r.id, name: r.name, type: r.type })));
        setRooms(fallbackRooms);
      } finally {
        setLoading(false);
      }
    }, (error) => {
      console.error("❌ [PublicChatsPage] Firebase connection error:", error);
      setError("Error connecting to chat service. Please try again later.");
      setLoading(false);
    });
    
    // Clean up listener
    return () => unsubscribe();
  }, [currentUser, isAnonymous]);

  // Handle clicks outside of the search component to close results
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (
        searchInputRef.current && 
        !searchInputRef.current.contains(event.target) &&
        searchResultsRef.current && 
        !searchResultsRef.current.contains(event.target)
      ) {
        setShowResults(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  // Perform search when query changes
  useEffect(() => {
    if (searchQuery.trim() === '') {
      setSearchResults([]);
      setSearchLoading(false);
      return;
    }

    // Clear previous timeout
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    setSearchLoading(true);

    // Debounce search to avoid too many requests
    searchTimeoutRef.current = setTimeout(async () => {
      try {
        console.log("Searching for:", searchQuery);
        
        // Simple client-side search on the loaded rooms
        const filteredRooms = rooms.filter(room => 
          (room.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
           room.description?.toLowerCase().includes(searchQuery.toLowerCase())) &&
          // For anonymous users, make sure they can see public rooms in search results
          (currentUser && !currentUser.isAnonymous ? true : (room.type === 'public' || !room.type))
        );
        
        // Format the filtered rooms
        const chatRooms = filteredRooms.map(room => ({
          id: room.id,
          type: 'chat',
          roomType: room.type || 'public',
          title: room.name || 'Untitled Room',
          description: room.description || '',
          metadata: `${room.activeUsers || room.participants || 0} online`,
          path: `/room/${room.id}`,
          matchType: 'name'
        }));
        
        setSearchResults([{
          category: 'Chat Rooms',
          items: chatRooms
        }]);
      } catch (error) {
        console.error('Search error:', error);
        setSearchResults([]);
      } finally {
        setSearchLoading(false);
      }
    }, 300);

    return () => {
      if (searchTimeoutRef.current) {
        clearTimeout(searchTimeoutRef.current);
      }
    };
  }, [searchQuery, rooms, currentUser]);

  // Handle input changes
  const handleInputChange = (e) => {
    const value = e.target.value;
    setSearchQuery(value);
    setShowResults(value.trim() !== '');
    setActiveIndex(-1);
  };

  // Handle clearing the search
  const handleClearSearch = () => {
    setSearchQuery('');
    setSearchResults([]);
    setShowResults(false);
    searchInputRef.current.focus();
  };

  // Handle result selection
  const handleSelectResult = (path, roomType) => {
    setSearchQuery('');
    setShowResults(false);
    
    // Check if user can access the room type
    if (roomType === 'private' || (roomType === 'registered' && (!currentUser || currentUser.isAnonymous))) {
      // Redirect to login for private or registered rooms
      navigate('/login', { state: { from: path } });
      return;
    }
    
    navigate(path);
  };

  // Handle keyboard navigation for accessibility
  const handleKeyDown = (e) => {
    // Calculate total number of results
    const totalItems = searchResults.reduce((count, category) => count + category.items.length, 0);
    
    if (totalItems === 0) return;

    // Down arrow
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setActiveIndex(prev => (prev + 1) % totalItems);
    }
    // Up arrow
    else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setActiveIndex(prev => (prev - 1 + totalItems) % totalItems);
    }
    // Enter key
    else if (e.key === 'Enter') {
      e.preventDefault();
      if (activeIndex >= 0) {
        // Find the selected item
        let itemCount = 0;
        let selectedItem = null;

        for (const category of searchResults) {
          for (const item of category.items) {
            if (itemCount === activeIndex) {
              selectedItem = item;
              break;
            }
            itemCount++;
          }
          if (selectedItem) break;
        }

        if (selectedItem) {
          handleSelectResult(selectedItem.path, selectedItem.roomType);
        }
      } else if (searchResults.length > 0 && searchResults[0].items.length > 0) {
        // If no item is selected, select the first one
        const firstItem = searchResults[0].items[0];
        handleSelectResult(firstItem.path, firstItem.roomType);
      }
    }
    // Escape key
    else if (e.key === 'Escape') {
      setShowResults(false);
    }
  };

  const handleJoinRoom = (roomId, roomType, roomData) => {
    const type = roomType || 'public';  // Default to public if type not specified
    
    // Special handling for event chat rooms
    if (type === 'event') {
      // Navigate to event chat room instead of regular room
      const eventId = roomData?.eventId || roomId.replace('event_', '');
      navigate(`/events/${eventId}/chat`);
      return;
    }
    
    // If user is not logged in or is anonymous and room requires registration
    if ((!currentUser || isAnonymous) && (type === 'registered' || type === 'private')) {
      // Store the room id in session storage so we can redirect after login
      sessionStorage.setItem('redirectRoom', roomId);
      // Navigate to login with return path
      navigate(`/login`, { state: { from: `/room/${roomId}` } });
      return;
    }
    
    // For private rooms, check if user has access
    if (type === 'private') {
      // Implementation for access code can be added here
      // For now, just navigate to the room (actual check will be in the room page)
    }
    
    // Otherwise, navigate directly to the room
    navigate(`/room/${roomId}`);
  };

  const handleCreateRoom = () => {
    if (!currentUser || isAnonymous) {
      // Prompt anonymous users to login
      if (window.confirm('You need to be logged in to create a room. Would you like to login?')) {
        navigate('/login', { state: { from: '/create-room' } });
      }
      return;
    }
    
    // Reset room creation form
    setNewRoomName('');
    setNewRoomDescription('');
    setRoomType('public');
    setAccessCode('');
    setShowCreateModal(true);
  };

  const handleCloseModal = () => {
    setShowCreateModal(false);
    setEditingRoomId(null); // Clear editing state
  };

  const handleCreateRoomSubmit = async (e) => {
    e.preventDefault();
    
    if (!newRoomName.trim()) {
      alert('Please enter a room name');
      return;
    }
    
    try {
      const roomsRef = ref(rtdb, 'chats/public');
      
      // Check if we're editing an existing room
      if (editingRoomId) {
        console.log('Updating room:', editingRoomId);
        // Update existing room
        const roomRef = ref(rtdb, `chats/public/${editingRoomId}`);
        
        // Generate access code for private rooms if not provided
        let finalAccessCode = accessCode;
        if (roomType === 'private' && !accessCode.trim()) {
          // Generate a random 6-character code
          finalAccessCode = Math.random().toString(36).substring(2, 8).toUpperCase();
        }
        
        // Update the room data
        await set(roomRef, {
          name: newRoomName.trim(),
          description: newRoomDescription.trim(),
          type: roomType,
          // Preserve other fields
          createdAt: rooms.find(r => r.id === editingRoomId)?.createdAt || serverTimestamp(),
          createdBy: currentUser?.uid || 'anonymous',
          active: true,
          // Add access code for private rooms
          ...(roomType === 'private' ? { accessCode: finalAccessCode } : {})
        });
        
        console.log('Room updated successfully');
      } else {
        // Create a new room with a unique ID
        const newRoomRef = push(roomsRef);
        
        // Generate access code for private rooms if not provided
        let finalAccessCode = accessCode;
        if (roomType === 'private' && !accessCode.trim()) {
          // Generate a random 6-character code
          finalAccessCode = Math.random().toString(36).substring(2, 8).toUpperCase();
        }
        
        await set(newRoomRef, {
          name: newRoomName.trim(),
          description: newRoomDescription.trim(),
          type: roomType,
          createdAt: serverTimestamp(),
          createdBy: currentUser?.uid || 'anonymous',
          active: true,
          activeUsers: 0,
          ...(roomType === 'private' ? { accessCode: finalAccessCode } : {})
        });
        
        // Close modal and navigate to the new room
        setShowCreateModal(false);
        
        // Navigate to the new room
        navigate(`/room/${newRoomRef.key}`);
        return; // Exit early to avoid closing modal twice
      }
      
      // Close modal
      setShowCreateModal(false);
      setEditingRoomId(null); // Clear editing state
    } catch (error) {
      console.error('Error creating/updating room:', error);
      alert('Failed to create/update room. Please try again.');
    }
  };

  // Toggle room filter
  const handleFilterChange = (filter) => {
    setRoomFilter(filter);
  };

  // Filter rooms based on search query and room type
  const getFilteredRooms = () => {
    // Apply search filter if there's a search query
    let filtered = searchQuery.trim() === '' 
      ? rooms 
      : rooms.filter(room => 
          room.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
          room.description?.toLowerCase().includes(searchQuery.toLowerCase())
        );
    
    // Remove VIP rooms (they'll be shown in a separate section)
    filtered = filtered.filter(room => room.type !== 'vip');
    
    // For logged-in, non-anonymous users, apply room type filter if set
    if (currentUser && !currentUser.isAnonymous && roomFilter !== 'all') {
      filtered = filtered.filter(room => room.type === roomFilter);
    }
    
    // For anonymous users, only show public rooms (but always show them)
    if (!currentUser || currentUser.isAnonymous) {
      const beforeFilter = filtered.length;
      filtered = filtered.filter(room => room.type === 'public' || !room.type);
      console.log(`🔐 [PublicChatsPage] Anonymous user filter applied - ${beforeFilter} -> ${filtered.length} rooms:`, 
        filtered.map(room => ({ id: room.id, name: room.name, type: room.type || 'public' })));
    }
    
    console.log(`🎯 [PublicChatsPage] Final filtered rooms for display: ${filtered.length}`);
    console.log('📋 [PublicChatsPage] Rooms to display:', filtered.map(r => ({ id: r.id, name: r.name, type: r.type })));
    return filtered;
  };

  // Get VIP rooms
  const getVipRooms = () => {
    return rooms.filter(room => room.type === 'vip');
  };

  const filteredRooms = getFilteredRooms();
  const vipRooms = getVipRooms();

  return (
    <div className="public-chats-page">
      <div className="page-header">
        <div className="page-title-and-status">
          <h1>Chat Rooms</h1>
          <UserStatusBadge />
        </div>
        <button className="create-room-button" onClick={handleCreateRoom}>
          <Plus size={18} />
          Create Room
        </button>
      </div>

      {/* Display error message if there's an actual error AND no fallback rooms */}
      {error && rooms.length === 0 && (
        <div className="error-message">
          {error}
        </div>
      )}
      
      {/* Login notice for anonymous users - but don't hide rooms */}
      {(!currentUser || isAnonymous) && (
        <div className="login-notice">
          <MarkdownText text="**Log in**" /> to create rooms in chats.
          <div className="login-actions">
            <Link to="/login" className="login-link">Log In</Link>
            <Link to="/signup" className="signup-link">Sign Up</Link>
          </div>
        </div>
      )}

      <div className="search-and-filter">
        <div className="search-bar-container" ref={searchInputRef}>
          <div className="search-input-wrapper">
            <Search className="search-icon" size={18} />
            <input
              type="text"
              className="search-input"
              placeholder={config?.searchBarText || "Search rooms..."}
              value={searchQuery}
              onChange={handleInputChange}
              onFocus={() => searchQuery.trim() !== '' && setShowResults(true)}
              onKeyDown={handleKeyDown}
            />
            {searchQuery.trim() !== '' && (
              <button className="clear-button" onClick={handleClearSearch}>
                <X size={16} />
              </button>
            )}
            {searchLoading && <div className="search-spinner"></div>}
          </div>

          {showResults && (
            <div className="search-results" ref={searchResultsRef}>
              {searchResults.length === 0 || searchResults.every(category => category.items.length === 0) ? (
                <div className="no-results">
                  {searchLoading ? 'Searching...' : 'No results found'}
                </div>
              ) : (
                <div className="results-content">
                  {searchResults.map((category, categoryIndex) => (
                    <div key={categoryIndex} className="result-category">
                      <div className="category-header">{category.category}</div>
                      {category.items.map((item, itemIndex) => {
                        // Calculate the overall index for this item
                        let overallIndex = 0;
                        for (let i = 0; i < categoryIndex; i++) {
                          overallIndex += searchResults[i].items.length;
                        }
                        overallIndex += itemIndex;

                        return (
                          <div
                            key={`${item.type}-${item.id}`}
                            className={`result-item ${overallIndex === activeIndex ? 'active' : ''}`}
                            onClick={() => handleSelectResult(item.path, item.roomType)}
                            onMouseEnter={() => setActiveIndex(overallIndex)}
                          >
                            <div className="result-icon">
                              {item.type === 'chat' && getRoomIcon(item.roomType)}
                            </div>
                            <div className="result-content">
                              <div className="result-title">{item.title}</div>
                              {item.description && (
                                <div className="result-description">{item.description}</div>
                              )}
                              {item.metadata && (
                                <div className="result-metadata">{item.metadata}</div>
                              )}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        {/* Room Type Filter - Only show if user is logged in and not anonymous */}
        {currentUser && !isAnonymous && (
          <div className="room-type-filter">
            {ROOM_FILTER_ORDER.map(filterType => {
              if (filterType === 'all') {
                return (
                  <button
                    key={filterType}
                    className={`filter-button ${roomFilter === 'all' ? 'active' : ''}`}
                    onClick={() => handleFilterChange('all')}
                  >
                    ALL
                  </button>
                );
              }
              
              const IconComponent = {
                'public': Globe,
                'registered': Users,
                'private': Lock,
                'vip': Star
              }[filterType];
              
              return (
                <button
                  key={filterType}
                  className={`filter-button ${roomFilter === filterType ? 'active' : ''}`}
                  onClick={() => handleFilterChange(filterType)}
                >
                  {IconComponent && <IconComponent size={14} />}
                  {getRoomTypeDisplayName(filterType)}
                </button>
              );
            })}
          </div>
        )}
      </div>

      {loading ? (
        <div className="loading-container">
          <div className="spinner"></div>
          <p>Loading rooms...</p>
        </div>
      ) : (
        <>
          <div className="rooms-grid">
            {filteredRooms.length > 0 ? (
              filteredRooms.map(room => (
                <div key={room.id} className={`room-card ${room.type}`}>
                  <div className="room-info">
                    <div className="room-header">
                      <div className={`room-status ${room.active ? 'active' : 'inactive'}`} />
                      <h3>{room.name}</h3>
                      {getRoomIcon(room.type)}
                      {/* Only show edit button for rooms created by current user */}
                      {currentUser && room.createdBy === currentUser.uid && (
                        <button 
                          className="edit-room-button"
                          onClick={(e) => {
                            e.stopPropagation();
                            // Populate form with room data
                            setNewRoomName(room.name);
                            setNewRoomDescription(room.description || '');
                            setRoomType(room.type || 'public');
                            setAccessCode(room.accessCode || '');
                            setEditingRoomId(room.id); // Set editing room ID
                            setShowCreateModal(true);
                          }}
                          title="Edit room"
                        >
                          <Edit size={16} />
                          Edit
                        </button>
                      )}
                    </div>
                    <p className="room-description">{room.description}</p>
                  </div>
                  <div className="room-stats">
                    <span className="participants">
                      <MessageSquare size={16} />
                      {typeof room.activeUsers === 'object' 
                        ? Object.keys(room.activeUsers || {}).length 
                        : room.activeUsers || room.participants || 0} online
                    </span>
                    <button 
                      className="join-button"
                      onClick={() => handleJoinRoom(room.id, room.type, room)}
                    >
                      {room.type === 'event' ? 'Join Event Chat' : 
                       room.type === 'private' ? 'Request Access' : 'Join Room'}
                    </button>
                  </div>
                </div>
              ))
            ) : (
              <div className="no-rooms-message">
                <MessageSquare size={32} className="no-rooms-icon" />
                <h3>No chat rooms available</h3>
                <p>Create a new room to get started</p>
              </div>
            )}
          </div>
          
          {/* VIP Chat Rooms Section - only show for logged in users */}
          {currentUser && !isAnonymous && (
            <VipChatRooms externalVipRooms={vipRooms} />
          )}
        </>
      )}

      {/* Create Room Modal */}
      {showCreateModal && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h2>{editingRoomId ? 'Edit Chat Room' : 'Create New Chat Room'}</h2>
            <form onSubmit={handleCreateRoomSubmit}>
            <div className="form-group">
              <label htmlFor="room-name">Room Name</label>
              <input
                type="text"
                id="room-name"
                value={newRoomName}
                onChange={(e) => setNewRoomName(e.target.value)}
                placeholder="Enter room name"
                className="form-input"
                required
              />
            </div>
            
            <div className="form-group">
              <label htmlFor="room-description">Description (optional)</label>
              <textarea
                id="room-description"
                value={newRoomDescription}
                onChange={(e) => setNewRoomDescription(e.target.value)}
                placeholder="What's this room about?"
                className="form-textarea"
                rows="3"
              />
            </div>
            
            <div className="form-group">
              <label>Room Type</label>
              <div className="room-type-options">
                <label className="room-type-option">
                  <input
                    type="radio"
                    name="roomType"
                    value="public"
                    checked={roomType === "public"}
                    onChange={() => setRoomType("public")}
                  />
                  <div className="option-content">
                    <span className="option-title">Public</span>
                    <span className="option-description">Anyone can view and join the room, including anonymous users</span>
                  </div>
                </label>
                
                <label className="room-type-option">
                  <input
                    type="radio"
                    name="roomType"
                    value="registered"
                    checked={roomType === "registered"}
                    onChange={() => setRoomType("registered")}
                  />
                  <div className="option-content">
                    <span className="option-title">Registered Users</span>
                    <span className="option-description">Only logged-in users can view and join the room</span>
                  </div>
                </label>
                
                <label className="room-type-option">
                  <input
                    type="radio"
                    name="roomType"
                    value="private"
                    checked={roomType === "private"}
                    onChange={() => setRoomType("private")}
                  />
                  <div className="option-content">
                    <span className="option-title">Private</span>
                    <span className="option-description">Invite-only room, requires access code to join</span>
                  </div>
                </label>
                
                <label className="room-type-option">
                  <input
                    type="radio"
                    name="roomType"
                    value="vip"
                    checked={roomType === "vip"}
                    onChange={() => setRoomType("vip")}
                  />
                  <div className="option-content">
                    <span className="option-title">V.I.P.</span>
                    <span className="option-description">Premium members only. Requires active membership to join</span>
                  </div>
                </label>
              </div>
            </div>
            
            {/* Show access code field only for private rooms */}
            {roomType === "private" && (
              <div className="form-group">
                <label htmlFor="access-code">Access Code (Optional)</label>
                <input
                  type="text"
                  id="access-code"
                  value={accessCode}
                  onChange={(e) => setAccessCode(e.target.value)}
                  placeholder="Leave blank to auto-generate"
                />
                <small className="form-hint">
                  Share this code with people you want to invite to the room
                </small>
              </div>
            )}
            
            <div className="modal-actions">
              <button type="button" className="cancel-button" onClick={handleCloseModal}>
                Cancel
              </button>
              <button type="submit" className="submit-button">
                {editingRoomId ? 'Save Changes' : 'Create Room'}
              </button>
            </div>
          </form>
          </div>
        </div>
      )}

      {/* Add user status notice for anonymous users */}
      {(!currentUser || isAnonymous) && (
        <div className="anonymous-user-notice">
          <p>You're browsing as <strong>Anonymous ({anonymousUsername})</strong>. You can view and join public chat rooms. <a href="/login">Log in</a> to create rooms and access more features.</p>
        </div>
      )}
    </div>
  );
};

export default PublicChatsPage;