// src/services/StripeInitializer.js
import { loadStripe } from '@stripe/stripe-js';

// Initialize Stripe with your publishable key
let stripePromise = null;
let currentEnv = null;

// Detect current environment
const getCurrentEnvironment = () => {
  const hostname = window.location.hostname;
  
  console.log('getCurrentEnvironment - hostname:', hostname);
  
  if (hostname.includes('localhost') || hostname.includes('127.0.0.1')) {
    return 'development';
  } else if (hostname.includes('ondigitalocean.app')) {
    return 'testing';
  } else if (hostname === 'talkstudio.space' || hostname === 'talkstud.io') {
    return 'production';
  }
  
  return 'unknown';
};

// Stripe publishable keys - only check test key in development/testing
const getStripeKeys = () => {
  const environment = getCurrentEnvironment();
  
  const keys = {
    test: null,
    live: null
  };
  
  // Only check for test key in non-production environments
  if (environment !== 'production') {
    keys.test = import.meta.env.VITE_STRIPE_TEST_PUBLIC_KEY || 
      'pk_test_REDACTED';
  }
  
  // Always check for live key (may be needed in all environments)
  keys.live = import.meta.env.VITE_STRIPE_LIVE_PUBLIC_KEY || 
    import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY || 
    'pk_live_REDACTED';
  
  console.log('getStripeKeys - Current environment:', environment);
  console.log('getStripeKeys - Keys:', { 
    test: keys.test ? `${keys.test.substring(0, 12)}...` : 'null',
    live: keys.live ? `${keys.live.substring(0, 12)}...` : 'null'
  });
  
  return keys;
};

/**
 * Get the appropriate Stripe publishable key based on environment
 * @param {string} environment - Environment to use ('production', 'test', 'sandbox')
 * @returns {string} Stripe publishable key
 */
export const getStripePublishableKey = (environment = null) => {
  const currentEnvironment = getCurrentEnvironment();
  const keys = getStripeKeys();
  
  // Check environment variables for payment mode
  const paymentMode = import.meta.env.VITE_PAYMENT_MODE || 'test';
  const appEnv = import.meta.env.VITE_APP_ENV || 'development';
  
  // Determine which key to use based on the requested environment
  let useTestMode = currentEnvironment !== 'production'; // Default to test mode unless in production

  if (environment === 'production') {
    useTestMode = false; // Use live mode for production
    console.log('StripeInitializer: Using LIVE keys for Production environment');
  } else if (environment === 'test') {
    useTestMode = true; // Use test mode for production test environment
    console.log('StripeInitializer: Using TEST keys for Production Test Mode');
  } else if (environment === 'sandbox') {
    useTestMode = true; // Use test mode for sandbox
    console.log('StripeInitializer: Using TEST keys for Sandbox environment');
  } else if (currentEnvironment === 'production') {
    // On a live domain, always use LIVE keys. getStripeKeys() deliberately
    // leaves keys.test null in production, so deferring to VITE_PAYMENT_MODE /
    // VITE_APP_ENV here (both of which default to test) would select a key
    // that can never exist and throw.
    useTestMode = false;
    console.log('StripeInitializer: Production domain detected, using LIVE keys');
  } else {
    // Fall back to environment variables if environment not explicitly specified
    useTestMode = paymentMode === 'test' || appEnv === 'development' || appEnv === 'test';
    console.log(`StripeInitializer: Environment not specified, defaulting based on app env: ${appEnv}, payment mode: ${paymentMode}`);
  }
                     
  console.log(`StripeInitializer: Using Stripe in ${useTestMode ? 'TEST' : 'LIVE'} mode for environment: ${environment || appEnv}`);
  
  // Get the key based on mode
  let key = useTestMode ? keys.test : keys.live;
  
  // Special handling for test environment - use the specific key provided
  if (environment === 'test' && keys.test) {
    key = keys.test;
    console.log('StripeInitializer: Using explicitly configured TEST key for Production Test Mode');
  }
  
  // Validate key format
  if (!key || key.trim() === '') {
    console.error(`Stripe ${useTestMode ? 'TEST' : 'LIVE'} key is missing or empty`);
    if (currentEnvironment !== 'production') {
      console.log('Available environment variables:', {
        VITE_STRIPE_LIVE_PUBLIC_KEY: import.meta.env.VITE_STRIPE_LIVE_PUBLIC_KEY ? 'Set' : 'Not set',
        VITE_STRIPE_PUBLISHABLE_KEY: import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY ? 'Set' : 'Not set',
        VITE_STRIPE_TEST_PUBLIC_KEY: import.meta.env.VITE_STRIPE_TEST_PUBLIC_KEY ? 'Set' : 'Not set',
        VITE_PAYMENT_MODE: import.meta.env.VITE_PAYMENT_MODE,
        VITE_APP_ENV: import.meta.env.VITE_APP_ENV
      });
    }
  } else if (!/^pk_(test|live)_[a-zA-Z0-9]{10,}$/.test(key)) {
    console.error(`Invalid Stripe ${useTestMode ? 'TEST' : 'LIVE'} key format:`, 
      `${key.substring(0, 12)}...${key.substring(key.length - 4)}`);
  } else {
    // Success - log partial key for debugging (only in non-production)
    if (currentEnvironment !== 'production') {
      console.log(`Using Stripe ${useTestMode ? 'TEST' : 'LIVE'} key:`, 
        `${key.substring(0, 12)}...${key.substring(key.length - 4)}`);
    }
  }
  
  // Return the appropriate key
  return key;
};

/**
 * Initialize Stripe and return the instance
 * @param {string} environment - Environment to use ('production', 'test', 'sandbox')
 * @returns {Promise<Object>} Stripe instance
 */
export const initializeStripe = async (environment = null) => {
  const publishableKey = getStripePublishableKey(environment);
  
  // Check if publishableKey is null or empty
  if (!publishableKey) {
    const currentEnvironment = getCurrentEnvironment();
    const errorMsg = `Stripe publishable key is null or empty. Current environment: ${currentEnvironment}, Requested environment: ${environment}`;
    console.error(errorMsg);
    throw new Error(errorMsg);
  }
  
  try {
    const newStripePromise = await loadStripe(publishableKey);
    // Update global variables
    stripePromise = newStripePromise;
    currentEnv = environment;
    
    console.log(`Stripe initialized successfully for environment: ${environment || 'default'}`);
    return stripePromise;
  } catch (error) {
    console.error('Error initializing Stripe:', error);
    stripePromise = null;
    currentEnv = null;
    throw error;
  }
};

/**
 * Get the current Stripe instance or initialize a new one
 * @param {string} environment - Environment to use ('production', 'test', 'sandbox')
 * @returns {Promise<Object>} Stripe instance
 */
export const getStripeInstance = async (environment = null) => {
  // If environment changed or no instance exists, initialize a new one
  if (!stripePromise || (environment !== null && environment !== currentEnv)) {
    console.log(`Creating new Stripe instance for environment: ${environment || 'default'}`);
    return await initializeStripe(environment);
  }
  
  return stripePromise;
};

/**
 * Reset the Stripe instance (useful for testing or switching API keys)
 */
export const resetStripeInstance = () => {
  stripePromise = null;
  currentEnv = null;
};