import apiKeyService from './apiKeyService'

const AI_CACHE_KEY = 'predict_ai_cache'
const AI_CACHE_TTL = 60 * 60 * 1000 // 1 hour

function getCached(predictionId) {
  try {
    const raw = localStorage.getItem(`${AI_CACHE_KEY}_${predictionId}`)
    if (!raw) return null
    const cached = JSON.parse(raw)
    if (Date.now() - cached.timestamp > AI_CACHE_TTL) return null
    return cached.data
  } catch {
    return null
  }
}

function setCache(predictionId, data) {
  localStorage.setItem(`${AI_CACHE_KEY}_${predictionId}`, JSON.stringify({ data, timestamp: Date.now() }))
}

const aiService = {
  async analyzePrediction(prediction, recentArticles = []) {
    const apiKey = apiKeyService.getClaudeApiKey()
    if (!apiKey) return { analysis: null, error: 'No Claude API key configured' }

    const cached = getCached(prediction.id)
    if (cached) return { analysis: cached, error: null, fromCache: true }

    const articleContext = recentArticles.slice(0, 10).map(a =>
      `- ${a.title} (${a.source}, ${new Date(a.publishedAt || a.pubDate || Date.now()).toLocaleDateString()})`
    ).join('\n')

    const prompt = `You are a prediction analyst. Analyze the following prediction and provide your assessment.

PREDICTION: ${prediction.title}
DESCRIPTION: ${prediction.description}
CATEGORY: ${prediction.category}
DEADLINE: ${prediction.deadline}
CURRENT OUTCOMES:
${prediction.outcomes.map(o => `- ${o.label}: ${o.probability}% (${o.trend})`).join('\n')}

${articleContext ? `RECENT RELEVANT NEWS:\n${articleContext}\n` : ''}
Respond with ONLY valid JSON in this exact format:
{
  "confidence": <number 0-100 representing overall confidence in the leading outcome>,
  "sentiment": <number 0.0-1.0 representing positive sentiment>,
  "analysis": "<2-3 sentence analysis of the prediction>",
  "adjustedOutcomes": [${prediction.outcomes.map(o => `{"label": "${o.label}", "probability": <adjusted number>, "trend": "<up|down|stable>"}`).join(', ')}],
  "keyFactors": ["<factor 1>", "<factor 2>", "<factor 3>"],
  "riskLevel": "<low|moderate|high>"
}`

    try {
      const res = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-api-key': apiKey,
          'anthropic-version': '2023-06-01',
          'anthropic-dangerous-direct-browser-access': 'true',
        },
        body: JSON.stringify({
          model: 'claude-sonnet-4-20250514',
          max_tokens: 1024,
          messages: [{ role: 'user', content: prompt }],
        }),
      })

      if (!res.ok) {
        const err = await res.json().catch(() => ({}))
        throw new Error(err.error?.message || `HTTP ${res.status}`)
      }

      const data = await res.json()
      const text = data.content?.[0]?.text || ''

      const jsonMatch = text.match(/\{[\s\S]*\}/)
      if (!jsonMatch) throw new Error('No JSON in response')

      const analysis = JSON.parse(jsonMatch[0])
      setCache(prediction.id, analysis)

      return { analysis, error: null, fromCache: false }
    } catch (err) {
      return { analysis: null, error: err.message }
    }
  },

  generateInputFromAnalysis(analysis, predictionId) {
    if (!analysis) return null

    return {
      predictionId,
      source: 'Claude AI',
      sourceUrl: null,
      type: 'ai',
      weight: 0.85,
      sentiment: analysis.sentiment || 0.5,
      reliability: 0.85,
      timestamp: new Date().toISOString(),
      title: analysis.analysis || 'AI Analysis',
      category: 'ai',
      isLive: true,
      aiDetails: {
        confidence: analysis.confidence,
        keyFactors: analysis.keyFactors,
        riskLevel: analysis.riskLevel,
        adjustedOutcomes: analysis.adjustedOutcomes,
      },
    }
  },

  clearCache(predictionId) {
    if (predictionId) {
      localStorage.removeItem(`${AI_CACHE_KEY}_${predictionId}`)
    } else {
      for (const key of Object.keys(localStorage)) {
        if (key.startsWith(AI_CACHE_KEY)) localStorage.removeItem(key)
      }
    }
  },
}

export default aiService
