import { categories } from '../../utils/categories'
import { ChevronDown } from 'lucide-react'

const sortOptions = [
  { value: 'confidence', label: 'Confidence' },
  { value: 'trending', label: 'Trending' },
  { value: 'deadline', label: 'Deadline' },
  { value: 'newest', label: 'Newest' },
]

export default function FilterBar({ activeCategory, sortBy, onCategoryChange, onSortChange }) {
  return (
    <div className="flex items-center justify-between gap-4 flex-wrap">
      <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-none">
        <button
          onClick={() => onCategoryChange('all')}
          className={`px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap transition-colors ${
            activeCategory === 'all'
              ? 'bg-blue-500/20 text-blue-400 border border-blue-500/30'
              : 'bg-gray-800/50 text-gray-400 border border-gray-700 hover:border-gray-600'
          }`}
        >
          All
        </button>
        {categories.map(cat => {
          const Icon = cat.icon
          return (
            <button
              key={cat.id}
              onClick={() => onCategoryChange(cat.id)}
              className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap transition-colors ${
                activeCategory === cat.id
                  ? `${cat.color}/20 ${cat.textColor} border ${cat.borderColor}/30`
                  : 'bg-gray-800/50 text-gray-400 border border-gray-700 hover:border-gray-600'
              }`}
            >
              <Icon size={12} />
              {cat.label}
            </button>
          )
        })}
      </div>

      <div className="relative">
        <select
          value={sortBy}
          onChange={e => onSortChange(e.target.value)}
          className="appearance-none bg-gray-800/50 border border-gray-700 rounded-lg text-xs text-gray-300 pl-3 pr-8 py-1.5 focus:outline-none focus:border-blue-500 cursor-pointer"
        >
          {sortOptions.map(opt => (
            <option key={opt.value} value={opt.value}>Sort: {opt.label}</option>
          ))}
        </select>
        <ChevronDown size={12} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-gray-500 pointer-events-none" />
      </div>
    </div>
  )
}
