// src/admin/userUtils.js

/**
 * Exports user data to CSV format
 * @param {Array} users - Array of user objects to export
 * @param {Array} fields - Array of field names to include (optional)
 * @returns {void} - Triggers a CSV download
 */
export const exportUsersToCSV = (users, fields = null) => {
  if (!users || users.length === 0) {
    console.error('No users to export');
    return;
  }
  
  const defaultFields = [
    { key: 'id', label: 'User ID' },
    { key: 'displayName', label: 'Name' },
    { key: 'email', label: 'Email' },
    { key: 'isAdmin', label: 'Role', formatter: val => val ? 'Admin' : 'User' },
    { key: 'isPremium', label: 'Premium Status', formatter: val => val ? 'Premium' : 'Free' },
    { key: 'createdAt', label: 'Created Date', formatter: val => val ? val.toISOString() : '' },
    { key: 'lastLogin', label: 'Last Login', formatter: val => val ? val.toISOString() : '' },
    { key: 'provider', label: 'Provider' },
    { key: 'postCount', label: 'Posts', formatter: val => val || 0 },
    { key: 'commentCount', label: 'Comments', formatter: val => val || 0 },
    { key: 'emailVerified', label: 'Email Verified', formatter: val => val ? 'Yes' : 'No' }
  ];
  
  const fieldsToExport = fields || defaultFields;
  
  // Add headers
  const headers = fieldsToExport.map(field => field.label);
  const csvRows = [headers.join(',')];
  
  // Add user data
  users.forEach(user => {
    const values = fieldsToExport.map(field => {
      const value = user[field.key];
      // Format the value if a formatter is provided
      const formattedValue = field.formatter ? field.formatter(value) : value;
      
      // Handle strings that might contain commas
      if (typeof formattedValue === 'string' && formattedValue.includes(',')) {
        return `"${formattedValue.replace(/"/g, '""')}"`; // Escape quotes by doubling them
      }
      
      return formattedValue === null || formattedValue === undefined ? '' : formattedValue;
    });
    
    csvRows.push(values.join(','));
  });
  
  // Create and download the CSV file
  const csvContent = csvRows.join('\n');
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  
  const link = document.createElement('a');
  const fileName = `users-export-${new Date().toISOString().split('T')[0]}.csv`;
  
  link.setAttribute('href', url);
  link.setAttribute('download', fileName);
  link.style.visibility = 'hidden';
  
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

/**
 * Formats a date for display
 * @param {Date} date - Date to format
 * @returns {string} - Formatted date string or 'Never' if date is null
 */
export const formatDate = (date) => {
  if (!date) return 'Never';
  return date.toLocaleString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
};

/**
 * Gets a relative time string for a date
 * @param {Date} date - Date to get relative time for
 * @returns {string} - Relative time string (e.g. "2 days ago")
 */
export const getRelativeTime = (date) => {
  if (!date) return '';
  
  const now = new Date();
  const diffMs = now - date;
  const diffSec = Math.floor(diffMs / 1000);
  const diffMin = Math.floor(diffSec / 60);
  const diffHour = Math.floor(diffMin / 60);
  const diffDay = Math.floor(diffHour / 24);
  
  if (diffDay > 30) {
    return formatDate(date);
  } else if (diffDay > 0) {
    return `${diffDay} day${diffDay > 1 ? 's' : ''} ago`;
  } else if (diffHour > 0) {
    return `${diffHour} hour${diffHour > 1 ? 's' : ''} ago`;
  } else if (diffMin > 0) {
    return `${diffMin} minute${diffMin > 1 ? 's' : ''} ago`;
  } else {
    return 'Just now';
  }
};
