import React, { useState, useEffect } from 'react';
import { Send } from 'lucide-react';
import { db } from '../../firebase';
import { collection, query, getDocs, orderBy } from 'firebase/firestore';
import './Messages.css';

const NewMessageForm = ({ 
  onSendMessage, 
  showRecipientField = false, 
  placeholder = "Type your message...", 
  buttonText = "Send" 
}) => {
  const [recipient, setRecipient] = useState('');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [users, setUsers] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [filteredUsers, setFilteredUsers] = useState([]);
  const [showDropdown, setShowDropdown] = useState(false);

  // Auto-resize textarea
  const handleTextareaChange = (e) => {
    setMessage(e.target.value);
    // Auto-resize textarea
    e.target.style.height = 'auto';
    e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px';
  };

  // Fetch all users
  useEffect(() => {
    if (!showRecipientField) return;

    const fetchUsers = async () => {
      setIsLoading(true);
      try {
        const usersRef = collection(db, "users");
        const q = query(usersRef, orderBy("username"));
        const querySnapshot = await getDocs(q);
        
        const userList = querySnapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        })).filter(user => user.username); // Only include users with usernames
        
        setUsers(userList);
        setIsLoading(false);
      } catch (err) {
        console.error("Error fetching users:", err);
        setIsLoading(false);
      }
    };

    fetchUsers();
  }, [showRecipientField]);

  // Filter users based on input
  useEffect(() => {
    if (recipient.trim() === '') {
      setFilteredUsers([]);
      return;
    }

    const filtered = users.filter(user => 
      user.username?.toLowerCase().includes(recipient.toLowerCase()) ||
      (user.displayName && user.displayName.toLowerCase().includes(recipient.toLowerCase()))
    ).slice(0, 5); // Limit to 5 results for performance
    
    setFilteredUsers(filtered);
  }, [recipient, users]);

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Form submitted', { 
      recipient, 
      message, 
      messageLength: message.length, 
      showRecipientField 
    });
    
    if (showRecipientField && !recipient.trim()) {
      console.log('Missing recipient', { recipient });
      setError('Please select a recipient');
      return;
    }
    
    if (!message.trim()) {
      console.log('Missing message', { message });
      setError('Please enter a message');
      return;
    }
    
    setError('');
    console.log('Sending message', { recipient, message });
    
    // Important: Handle the parameters differently based on whether this form
    // is for a new conversation or an existing one
    if (showRecipientField) {
      // For new conversations, pass both recipient and message
      onSendMessage(recipient, message);
    } else {
      // For existing conversations, just pass the message content
      onSendMessage(message);
    }
    
    setMessage('');
    // Reset textarea height
    const textarea = document.querySelector('.message-input-group textarea');
    if (textarea) {
      textarea.style.height = 'auto';
    }
  };

  const handleUserSelect = (username) => {
    console.log('User selected', { username });
    setRecipient(username);
    setShowDropdown(false);
  };

  // Handle Enter key to send message (Shift+Enter for new line)
  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit(e);
    }
  };

  // Handle clicks outside the dropdown to close it
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (showDropdown && !event.target.closest('.recipient-input-wrapper')) {
        setShowDropdown(false);
      }
    };

    document.addEventListener('click', handleClickOutside);
    return () => {
      document.removeEventListener('click', handleClickOutside);
    };
  }, [showDropdown]);

  return (
    <form className="new-message-form" onSubmit={handleSubmit}>
      {error && <div className="form-error">{error}</div>}
      
      {showRecipientField && (
        <div className="form-group recipient-input-container">
          <label htmlFor="recipient">To:</label>
          <div className="recipient-input-wrapper">
            <input
              type="text"
              id="recipient"
              value={recipient}
              onChange={(e) => {
                setRecipient(e.target.value);
                setShowDropdown(true);
              }}
              onFocus={() => setShowDropdown(true)}
              placeholder="Type username..."
              autoComplete="off"
            />
            
            {showDropdown && (filteredUsers.length > 0 || isLoading) && (
              <ul className="recipient-dropdown">
                {isLoading ? (
                  <li className="dropdown-loading">Loading users...</li>
                ) : (
                  filteredUsers.map(user => (
                    <li 
                      key={user.id} 
                      className="recipient-option"
                      onClick={() => handleUserSelect(user.username)}
                    >
                      {user.photoURL ? (
                        <img 
                          src={user.photoURL} 
                          alt={user.displayName || user.username} 
                          className="recipient-avatar" 
                        />
                      ) : (
                        <div className="recipient-avatar recipient-avatar-placeholder">
                          {(user.username || 'U').charAt(0).toUpperCase()}
                        </div>
                      )}
                      <div className="recipient-info">
                        <span className="recipient-name">
                          @{user.username}
                        </span>
                        {user.displayName && user.displayName !== user.username && (
                          <span className="recipient-display-name">{user.displayName}</span>
                        )}
                      </div>
                    </li>
                  ))
                )}
              </ul>
            )}
          </div>
        </div>
      )}
      
      <div className="message-input-container">
        <div className="message-input-group">
          <textarea
            id="message"
            value={message}
            onChange={handleTextareaChange}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            rows={1}
            style={{ minHeight: '20px', maxHeight: '120px' }}
          />
          
          <button 
            type="submit" 
            className="send-button"
            disabled={!message.trim()}
            title="Send message (Enter)"
          >
            <Send size={16} />
          </button>
        </div>
      </div>
    </form>
  );
};

export default NewMessageForm;