// Enhanced EventsTheatre with LiveKit Integration for Artist Streams
// Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\components\events\EventsTheatre.jsx

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useWallet } from '../../contexts/WalletContext';
import { useNavigate, useParams } from 'react-router-dom';
import { getFirestore, doc, getDoc, collection, query, where, onSnapshot, addDoc, updateDoc, serverTimestamp } from 'firebase/firestore';
import TipButton from '../monetization/TipButton';
import { 
  Play, 
  Users, 
  Heart, 
  MessageCircle, 
  Share2, 
  Settings, 
  Maximize2, 
  Minimize2,
  Volume2,
  VolumeX,
  Star,
  Gift,
  Crown,
  Zap,
  TrendingUp,
  Eye,
  Clock,
  DollarSign,
  Radio,
  Video,
  Wifi,
  WifiOff,
  RefreshCw,
  AlertCircle,
  CheckCircle,
  Activity
} from 'lucide-react';

// LiveKit Components
import LiveKitRoom from '../livekit/LiveKitRoom.jsx';
import liveKitService from '../../services/livekit/LiveKitService.js';
import EnhancedTipButton from '../monetization/EnhancedTipButton.jsx';

import './EventsTheatre.css';

const EventsTheatre = () => {
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  const { eventId } = useParams();
  
  // Event state
  const [isLoading, setIsLoading] = useState(true);
  const [hasAccess, setHasAccess] = useState(false);
  const [event, setEvent] = useState(null);
  const [isLive, setIsLive] = useState(false);
  const [isEventCreator, setIsEventCreator] = useState(false);
  const [canStreamNow, setCanStreamNow] = useState(false);
  
  // LiveKit state
  const [liveKitToken, setLiveKitToken] = useState(null);
  const [liveKitConnected, setLiveKitConnected] = useState(false);
  const [liveKitError, setLiveKitError] = useState(null);
  const [roomName, setRoomName] = useState('');
  const [participantName, setParticipantName] = useState('');
  const [isGeneratingToken, setIsGeneratingToken] = useState(false);
  const [streamStatus, setStreamStatus] = useState('checking');
  
  // Viewing state
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [volume, setVolume] = useState(0.8);
  const [viewerCount, setViewerCount] = useState(0);
  
  // Chat state
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [showChat, setShowChat] = useState(true);
  
  // Premium features state
  const [reactions, setReactions] = useState({ hearts: 0, stars: 0, fire: 0 });
  const [tips, setTips] = useState({ total: 0, recent: [] });
  const [userSubscription, setUserSubscription] = useState(null);
  
  // Refs
  const chatRef = useRef(null);
  const componentMountedRef = useRef(true);

  // Generate LiveKit viewer token to watch artist stream
  const generateViewerToken = async () => {
    if (!currentUser || !eventId) {
      console.log('❌ Cannot generate token: missing user or eventId');
      return null;
    }

    try {
      setIsGeneratingToken(true);
      setLiveKitError(null);
      
      const roomNameForEvent = `event-${eventId}`;
      const participantNameForUser = currentUser?.displayName || currentUser?.email || 'Viewer';
      
      console.log('🔑 Generating LiveKit viewer token for EventsTheatre:', {
        roomName: roomNameForEvent,
        participantName: participantNameForUser,
        userId: currentUser.uid
      });

      const token = await liveKitService.generateAccessToken(
        roomNameForEvent,
        participantNameForUser,
        {
          canPublish: false,  // Viewers cannot publish (only watch artist)
          canSubscribe: true, // Viewers can subscribe to artist's stream
        }
      );

      if (token) {
        setLiveKitToken(token);
        setRoomName(roomNameForEvent);
        setParticipantName(participantNameForUser);
        setStreamStatus('connected');
        console.log('✅ LiveKit viewer token generated successfully for EventsTheatre');
        return token;
      } else {
        throw new Error('Token generation returned null');
      }
    } catch (error) {
      console.error('❌ Failed to generate LiveKit viewer token:', error);
      setLiveKitError(`Token generation failed: ${error.message}`);
      setStreamStatus('error');
      return null;
    } finally {
      setIsGeneratingToken(false);
    }
  };

  useEffect(() => {
    componentMountedRef.current = true;
    
    if (!currentUser) {
      navigate('/login');
      return;
    }
    
    initializeTheatre();
    
    // Cleanup on unmount
    return () => {
      console.log('🧹 EventsTheatre cleanup');
      componentMountedRef.current = false;
    };
  }, [currentUser, eventId]);

  // Monitor access changes and connect to LiveKit stream when access is granted
  useEffect(() => {
    if (hasAccess && !liveKitToken) {
      generateViewerToken();
    }
  }, [hasAccess, liveKitToken]);

  const initializeTheatre = async () => {
    try {
      setIsLoading(true);
      setStreamStatus('checking');
      
      // Load event details
      await loadEventDetails();
      
      // Verify user access
      await verifyUserAccess();
      
      // Set up real-time listeners
      setupRealtimeListeners();
      
    } catch (error) {
      console.error('Failed to initialize theatre:', error);
      setStreamStatus('error');
    } finally {
      setIsLoading(false);
    }
  };

  const loadEventDetails = async () => {
    try {
      const db = getFirestore();
      const eventDoc = await getDoc(doc(db, 'events', eventId));
      
      if (eventDoc.exists()) {
        const eventData = eventDoc.data();
        setEvent(eventData);
        
        const isScheduledLive = eventData.status === 'live';
        setIsLive(isScheduledLive);
        
        const creatorCheck = currentUser && eventData.artistId === currentUser.uid;
        setIsEventCreator(creatorCheck);
        setCanStreamNow(creatorCheck && eventData.status === 'scheduled');
        
        console.log('🎭 Event loaded for LiveKit theatre:', {
          title: eventData.title,
          status: eventData.status,
          isScheduledLive: isScheduledLive,
          isCreator: creatorCheck,
          canStream: creatorCheck && eventData.status === 'scheduled'
        });
      } else {
        throw new Error('Event not found');
      }
    } catch (error) {
      console.error('Failed to load event:', error);
      navigate('/events');
    }
  };

  const verifyUserAccess = async () => {
    try {
      const db = getFirestore();
      const userDoc = await getDoc(doc(db, 'users', currentUser.uid));
      
      if (!userDoc.exists()) {
        console.log('🚫 User document not found');
        setHasAccess(false);
        return;
      }
      
      const userData = userDoc.data();
      console.log('👤 User data:', userData);
      
      const hasPremium = userData?.isPremium === true;
      const hasEventTicket = userData?.eventTickets?.includes(eventId);
      const hasUnlimitedAccess = userData?.isVIP === true;
      
      console.log('🔍 Access check:', {
        isPremium: hasPremium,
        hasEventTicket: hasEventTicket,
        isVIP: hasUnlimitedAccess,
        eventId: eventId,
        eventTickets: userData?.eventTickets
      });
      
      const accessGranted = hasPremium || hasEventTicket || hasUnlimitedAccess;
      
      setHasAccess(accessGranted);
      setUserSubscription({
        isPremium: hasPremium,
        hasTicket: hasEventTicket,
        isVIP: hasUnlimitedAccess,
        type: hasUnlimitedAccess ? 'VIP' : hasPremium ? 'Premium' : hasEventTicket ? 'Ticket' : 'Free'
      });
      
      console.log('🎟️ Access verification result:', {
        granted: accessGranted,
        premium: hasPremium,
        ticket: hasEventTicket,
        vip: hasUnlimitedAccess,
        userType: hasUnlimitedAccess ? 'VIP' : hasPremium ? 'Premium' : hasEventTicket ? 'Ticket' : 'Free'
      });
      
    } catch (error) {
      console.error('❌ Access verification failed:', error);
      setHasAccess(false);
    }
  };

  const loadTipStats = async () => {
    if (!eventId) return;
    
    try {
      // This will be implemented with TipManager later
      // For now, just a placeholder
      console.log('📊 Loading tip stats for event:', eventId);
    } catch (error) {
      console.error('❌ Failed to load tip stats:', error);
    }
  };

  const setupRealtimeListeners = () => {
    if (!hasAccess) return;
    
    const db = getFirestore();
    
    // Listen for chat messages
    const chatQuery = query(
      collection(db, 'eventChats'),
      where('eventId', '==', eventId)
    );
    
    const unsubscribeChat = onSnapshot(chatQuery, (snapshot) => {
      const newMessages = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setMessages(newMessages.sort((a, b) => a.timestamp - b.timestamp));
    });
    
    // Listen for reactions and tips
    const reactionsQuery = query(
      collection(db, 'eventReactions'),
      where('eventId', '==', eventId)
    );
    
    const unsubscribeReactions = onSnapshot(reactionsQuery, (snapshot) => {
      const reactionData = { hearts: 0, stars: 0, fire: 0 };
      snapshot.docs.forEach(doc => {
        const data = doc.data();
        reactionData[data.type] = (reactionData[data.type] || 0) + 1;
      });
      setReactions(reactionData);
    });
    
    return () => {
      unsubscribeChat();
      unsubscribeReactions();
    };
  };

  const sendMessage = async () => {
    if (!newMessage.trim() || !hasAccess) return;
    
    try {
      const db = getFirestore();
      await addDoc(collection(db, 'eventChats'), {
        eventId,
        userId: currentUser.uid,
        username: currentUser.displayName || 'Anonymous',
        message: newMessage.trim(),
        timestamp: Date.now(),
        userType: userSubscription?.type || 'Free'
      });
      
      setNewMessage('');
    } catch (error) {
      console.error('Failed to send message:', error);
    }
  };

  const sendReaction = async (type) => {
    if (!hasAccess) return;
    
    try {
      const db = getFirestore();
      await addDoc(collection(db, 'eventReactions'), {
        eventId,
        userId: currentUser.uid,
        type,
        timestamp: Date.now()
      });
    } catch (error) {
      console.error('Failed to send reaction:', error);
    }
  };

  const upgradeMembership = () => {
    navigate('/premium-membership');
  };

  const purchaseTicket = () => {
    navigate(`/events/${eventId}/purchase`);
  };

  const startStreamingNow = async () => {
    const confirmed = window.confirm(
      `Are you sure you want to start streaming "${event?.title}" now?\n\n` +
      'This will change the event status to LIVE and notify all viewers.'
    );
    
    if (!confirmed) return;
    
    try {
      const db = getFirestore();
      const eventRef = doc(db, 'events', eventId);
      
      await updateDoc(eventRef, {
        status: 'live',
        actualStartTime: Date.now(),
        updatedAt: serverTimestamp()
      });
      
      setIsLive(true);
      setCanStreamNow(false);
      
      console.log('🔴 Event set to live:', eventId);
      alert('🎉 Your event is now LIVE! Viewers can join the stream.');

      // Redirect to artist studio
      navigate('/events/studio');

    } catch (error) {
      console.error('Failed to start streaming:', error);
      alert('Failed to start streaming. Please try again.');
    }
  };

  // Stop event and trigger video assembly
  const stopEvent = async () => {
    if (!eventId || !isEventCreator) {
      console.error('Cannot stop event: not authorized or missing eventId');
      return;
    }

    const confirmed = window.confirm(
      'Are you sure you want to stop this event? This will end the stream and begin assembling the recording.'
    );

    if (!confirmed) return;

    try {
      setIsLoading(true);
      const db = getFirestore();
      const eventRef = doc(db, 'events', eventId);

      // Update event status to completed
      await updateDoc(eventRef, {
        status: 'completed',
        endedAt: serverTimestamp(),
        actualEndTime: Date.now()
      });

      console.log('🛑 Event stopped:', eventId);

      // Trigger video assembly - try auto-recorder first, then fall back to Cloud Run
      const RECORDER_SERVICE_URL = process.env.REACT_APP_RECORDER_SERVICE_URL || 'http://localhost:3004';
      const ASSEMBLY_SERVICE_URL = 'https://recording-assembly-service-274213809869.us-central1.run.app';

      let assemblyTriggered = false;

      // Try auto-recorder service first (if running locally)
      try {
        const response = await fetch(`${RECORDER_SERVICE_URL}/api/events/${eventId}/complete`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' }
        });

        if (response.ok) {
          const result = await response.json();
          console.log('✅ Video assembly triggered via auto-recorder:', result);
          assemblyTriggered = true;
        }
      } catch (fetchError) {
        console.log('⚠️ Auto-recorder not available, trying Cloud Run assembly service...');
      }

      // If auto-recorder failed, call Cloud Run assembly service directly
      if (!assemblyTriggered) {
        try {
          const response = await fetch(`${ASSEMBLY_SERVICE_URL}/api/webhook/event/complete/${eventId}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' }
          });

          if (response.ok) {
            const result = await response.json();
            console.log('✅ Video assembly triggered via Cloud Run:', result);
            assemblyTriggered = true;
          } else {
            console.error('Failed to trigger video assembly via Cloud Run:', await response.text());
          }
        } catch (cloudError) {
          console.error('Error triggering Cloud Run assembly:', cloudError);
        }
      }

      if (assemblyTriggered) {
        alert('Event stopped successfully! Your recording will be assembled and available shortly.');
      } else {
        alert('Event stopped, but video assembly may need to be triggered manually. Check the console for details.');
      }

      // Redirect to events page
      setTimeout(() => navigate('/events'), 1500);

    } catch (error) {
      console.error('Failed to stop event:', error);
      alert('Failed to stop event. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  // LiveKit event handlers
  const handleLiveKitConnected = (room) => {
    setLiveKitConnected(true);
    setLiveKitError(null);
    setStreamStatus('live');
    console.log('✅ LiveKit room connected as theatre viewer:', {
      roomName: room?.name,
      participants: room?.participants?.size || 0
    });
  };

  const handleLiveKitDisconnected = () => {
    setLiveKitConnected(false);
    setStreamStatus('offline');
    console.log('❌ LiveKit room disconnected in theatre');
  };

  const handleLiveKitError = (error) => {
    setLiveKitError(`Connection error: ${error.message}`);
    setLiveKitConnected(false);
    setStreamStatus('error');
    console.error('❌ LiveKit room error in theatre:', error);
  };

  const retryLiveKitConnection = async () => {
    console.log('🔄 Retrying LiveKit connection in theatre...');
    await generateViewerToken();
  };

  // Enhanced stream status determination
  const getFinalStreamStatus = () => {
    if (isGeneratingToken) return 'checking';
    if (liveKitError) return 'error';
    if (liveKitConnected) return 'live';
    if (liveKitToken && !liveKitConnected) return 'connecting';
    if (isLive) return 'scheduled';
    return 'offline';
  };

  const finalStreamStatus = getFinalStreamStatus();

  if (isLoading) {
    return (
      <div className="theatre-loading">
        <div className="loading-spinner"></div>
        <p>Loading Events Theatre...</p>
      </div>
    );
  }

  if (!hasAccess) {
    return (
      <div className="theatre-access-denied">
        <div className="access-denied-content">
          <Crown size={64} className="access-icon" />
          <h1>Premium Access Required</h1>
          <p>This is an exclusive event for premium members and ticket holders.</p>
          
          {event && (
            <div className="event-preview">
              <h2>{event.title}</h2>
              <p className="event-description">{event.description}</p>
              <div className="event-details">
                <div className="detail-item">
                  <Clock size={16} />
                  <span>{new Date(event.startTime).toLocaleString()}</span>
                </div>
                <div className="detail-item">
                  <Users size={16} />
                  <span>{event.expectedViewers || 0} expected viewers</span>
                </div>
                <div className="detail-item">
                  <DollarSign size={16} />
                  <span>${event.ticketPrice || 29.99} per ticket</span>
                </div>
              </div>
            </div>
          )}
          
          <div className="access-options">
            <button className="primary-btn" onClick={purchaseTicket}>
              <Gift size={20} />
              Purchase Event Ticket
            </button>
            <button className="secondary-btn" onClick={upgradeMembership}>
              <Crown size={20} />
              Upgrade to Premium
            </button>
          </div>
          
          <p className="access-note">
            Premium members get unlimited access to all events plus exclusive perks!
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="events-theatre">
      {/* Theatre Header */}
      <div className="theatre-header">
        <div className="event-info">
          <h1>{event?.title || 'Live Event'}</h1>
          <div className="event-meta">
            <div className="meta-item">
              <Eye size={16} />
              <span>{viewerCount} watching</span>
            </div>
            
            {/* LiveKit stream status indicator */}
            <div className={`stream-status-indicator ${finalStreamStatus}`}>
              {finalStreamStatus === 'checking' && (
                <>
                  <Wifi size={16} className="checking-icon rotating" />
                  <span>Connecting...</span>
                </>
              )}
              {finalStreamStatus === 'live' && (
                <>
                  <div className="live-dot pulsing"></div>
                  <span>LIVE</span>
                </>
              )}
              {finalStreamStatus === 'connecting' && (
                <>
                  <Wifi size={16} className="connecting-icon" />
                  <span>Connecting</span>
                </>
              )}
              {finalStreamStatus === 'scheduled' && (
                <>
                  <Clock size={16} />
                  <span>Scheduled</span>
                </>
              )}
              {finalStreamStatus === 'offline' && (
                <>
                  <WifiOff size={16} />
                  <span>Offline</span>
                </>
              )}
              {finalStreamStatus === 'error' && (
                <>
                  <AlertCircle size={16} />
                  <span>Error</span>
                </>
              )}
            </div>
            
            {/* LiveKit connection status */}
            <div className="livekit-status-badge" title={liveKitConnected ? 'LiveKit Connected' : 'LiveKit Disconnected'}>
              <Zap size={16} className={liveKitConnected ? 'text-green-500' : 'text-gray-400'} />
              <span>{liveKitConnected ? 'Connected' : 'Disconnected'}</span>
            </div>
            
            <div className="user-badge">
              {isEventCreator && <Video size={16} className="creator-icon" />}
              {userSubscription?.type === 'VIP' && <Crown size={16} className="vip-icon" />}
              {userSubscription?.type === 'Premium' && <Star size={16} className="premium-icon" />}
              <span className={`badge ${
                isEventCreator ? 'creator' : userSubscription?.type?.toLowerCase()
              }`}>
                {isEventCreator ? 'Creator' : userSubscription?.type}
              </span>
            </div>
          </div>
        </div>
        
        <div className="theatre-controls">
          {/* Stream Now button for event creators */}
          {canStreamNow && (
            <button
              className="stream-now-btn"
              onClick={startStreamingNow}
              style={{
                backgroundColor: '#ef4444',
                color: 'white',
                border: 'none',
                borderRadius: '8px',
                padding: '10px 16px',
                fontSize: '14px',
                fontWeight: '600',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '8px',
                marginRight: '12px',
                transition: 'all 0.2s ease',
                animation: 'pulse 2s infinite',
                boxShadow: '0 4px 12px rgba(239, 68, 68, 0.3)'
              }}
            >
              <Radio size={18} />
              Stream Now
            </button>
          )}

          {/* Stop Event button for event creators when event is live */}
          {isEventCreator && (
            <button
              className="stop-event-btn"
              onClick={stopEvent}
              disabled={isLoading}
              style={{
                backgroundColor: '#dc2626',
                color: 'white',
                border: 'none',
                borderRadius: '8px',
                padding: '10px 16px',
                fontSize: '14px',
                fontWeight: '600',
                cursor: isLoading ? 'not-allowed' : 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '8px',
                marginRight: '12px',
                transition: 'all 0.2s ease',
                opacity: isLoading ? 0.6 : 1,
                boxShadow: '0 4px 12px rgba(220, 38, 38, 0.3)'
              }}
            >
              <Activity size={18} />
              {isLoading ? 'Stopping...' : 'Stop Event'}
            </button>
          )}
          
          <button onClick={() => setShowChat(!showChat)}>
            <MessageCircle size={20} />
            Chat
          </button>
          <button onClick={() => setIsFullscreen(!isFullscreen)}>
            {isFullscreen ? <Minimize2 size={20} /> : <Maximize2 size={20} />}
            {isFullscreen ? 'Exit' : 'Fullscreen'}
          </button>
          
          {/* LiveKit connection retry button */}
          <button 
            onClick={retryLiveKitConnection}
            disabled={isGeneratingToken}
            title="Retry LiveKit connection"
            style={{
              backgroundColor: 'transparent',
              border: '1px solid rgba(255,255,255,0.3)',
              borderRadius: '6px',
              padding: '8px',
              color: 'white',
              cursor: isGeneratingToken ? 'not-allowed' : 'pointer',
              display: 'flex',
              alignItems: 'center',
              opacity: isGeneratingToken ? 0.6 : 1
            }}
          >
            <RefreshCw size={16} className={isGeneratingToken ? 'rotating' : ''} />
          </button>
        </div>
      </div>

      <div className="theatre-main">
        {/* Video Player - LiveKit Artist Stream */}
        <div className={`video-container ${isFullscreen ? 'fullscreen' : ''}`} style={{
          position: 'relative',
          width: '100%',
          height: '400px',
          background: '#000',
          borderRadius: '8px',
          overflow: 'hidden'
        }}>
          {liveKitToken && roomName ? (
            <div className="livekit-theatre-viewer">
              <LiveKitRoom
                roomName={roomName}
                participantName={participantName}
                token={liveKitToken}
                onConnected={handleLiveKitConnected}
                onDisconnected={handleLiveKitDisconnected}
                onError={handleLiveKitError}
                className="theatre-stream-viewer"
                creatorIdentity={event?.artistName || event?.artistId} // Pass creator identity for multi-participant display
                options={{
                  video: true,
                  audio: true,
                  // Theatre viewer options
                  adaptiveStream: true,
                  dynacast: true,
                }}
              />
              
              {/* Artist Badge Overlay */}
              <div className="video-overlay">
                <div className="artist-badge">
                  <Crown size={16} />
                  <span>{event?.artistName}</span>
                  <span className="livekit-badge">⚡ LiveKit</span>
                </div>
                
                {/* Connection Status */}
                <div className="connection-status-overlay">
                  {liveKitConnected ? (
                    <div className="status-connected">
                      <CheckCircle size={14} />
                      <span>Live</span>
                    </div>
                  ) : (
                    <div className="status-connecting">
                      <Wifi size={14} />
                      <span>Connecting...</span>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ) : (
            <div className="stream-offline" style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              height: '100%',
              color: 'white',
              textAlign: 'center',
              padding: '2rem'
            }}>
              {finalStreamStatus === 'checking' ? (
                <>
                  <Wifi size={48} className="checking-icon rotating" />
                  <h3 style={{ margin: '1rem 0 0.5rem 0', fontSize: '1.5rem' }}>Connecting to LiveKit...</h3>
                  <p style={{ margin: '0.5rem 0', opacity: 0.8 }}>Preparing ultra-low latency stream</p>
                </>
              ) : finalStreamStatus === 'scheduled' ? (
                <>
                  <Clock size={48} />
                  <h3 style={{ margin: '1rem 0 0.5rem 0', fontSize: '1.5rem' }}>Event Scheduled</h3>
                  <p style={{ margin: '0.5rem 0', opacity: 0.8 }}>Waiting for artist to start streaming</p>
                </>
              ) : finalStreamStatus === 'error' ? (
                <>
                  <AlertCircle size={48} />
                  <h3 style={{ margin: '1rem 0 0.5rem 0', fontSize: '1.5rem' }}>Connection Error</h3>
                  <p style={{ margin: '0.5rem 0', opacity: 0.8 }}>
                    {liveKitError || 'Unable to connect to stream'}
                  </p>
                  <button 
                    onClick={retryLiveKitConnection}
                    style={{
                      backgroundColor: 'rgba(255,255,255,0.2)',
                      border: '1px solid rgba(255,255,255,0.3)',
                      color: 'white',
                      borderRadius: '6px',
                      padding: '8px 16px',
                      fontSize: '0.9rem',
                      cursor: 'pointer',
                      marginTop: '1rem'
                    }}
                  >
                    Try Again
                  </button>
                </>
              ) : (
                <>
                  <Play size={48} />
                  <h3 style={{ margin: '1rem 0 0.5rem 0', fontSize: '1.5rem' }}>Stream Offline</h3>
                  <p style={{ margin: '0.5rem 0', opacity: 0.8 }}>
                    {event?.startTime ? `Event starts at ${new Date(event.startTime).toLocaleString()}` : 'Waiting for live broadcast'}
                  </p>
                </>
              )}
              
              {/* Debug info */}
              <div style={{ 
                marginTop: '2rem', 
                fontSize: '0.7rem', 
                opacity: 0.5, 
                textAlign: 'left',
                backgroundColor: 'rgba(0,0,0,0.3)',
                padding: '1rem',
                borderRadius: '4px',
                maxWidth: '400px'
              }}>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.5rem' }}>
                  <p><strong>Status:</strong> {finalStreamStatus}</p>
                  <p><strong>LiveKit:</strong> {liveKitConnected ? 'Connected' : 'Disconnected'}</p>
                  <p><strong>Token:</strong> {liveKitToken ? 'Available' : 'None'}</p>
                  <p><strong>Room:</strong> {roomName || 'Not set'}</p>
                  <p><strong>Error:</strong> {liveKitError ? 'Yes' : 'None'}</p>
                  <p><strong>Event Status:</strong> {event?.status}</p>
                </div>
              </div>
            </div>
          )}
          
          {/* Video Controls Overlay */}
          <div className="video-controls">
            <div className="controls-left">
              <button onClick={() => setIsMuted(!isMuted)}>
                {isMuted ? <VolumeX size={20} /> : <Volume2 size={20} />}
              </button>
              <input
                type="range"
                min="0"
                max="1"
                step="0.1"
                value={volume}
                onChange={(e) => setVolume(parseFloat(e.target.value))}
                className="volume-slider"
              />
            </div>
            
            <div className="controls-right">
              <div className="viewer-count">
                <Eye size={16} />
                <span>{viewerCount}</span>
              </div>
              
              {/* LiveKit indicator */}
              <div className="livekit-indicator">
                <Zap size={16} className={liveKitConnected ? 'text-green-500' : 'text-gray-400'} />
                <span className="livekit-text">LiveKit</span>
              </div>
            </div>
          </div>
          
          {/* Reactions Overlay */}
          <div className="reactions-overlay">
            <button className="reaction-btn hearts" onClick={() => sendReaction('hearts')}>
              <Heart size={20} />
              <span>{reactions.hearts}</span>
            </button>
            <button className="reaction-btn stars" onClick={() => sendReaction('stars')}>
              <Star size={20} />
              <span>{reactions.stars}</span>
            </button>
            <button className="reaction-btn fire" onClick={() => sendReaction('fire')}>
              <Zap size={20} />
              <span>{reactions.fire}</span>
            </button>
          </div>
        </div>

        {/* Chat Panel */}
        {showChat && (
          <div className="chat-panel">
            <div className="chat-header">
              <h3>Live Chat</h3>
              <div className="chat-stats">
                <TrendingUp size={16} />
                <span>{messages.length} messages</span>
              </div>
            </div>
            
            <div className="chat-messages" ref={chatRef}>
              {messages.map((message) => (
                <div key={message.id} className={`chat-message ${message.userType?.toLowerCase()}`}>
                  <div className="message-header">
                    <span className="username">{message.username}</span>
                    {message.userType === 'VIP' && <Crown size={12} />}
                    {message.userType === 'Premium' && <Star size={12} />}
                    <span className="timestamp">
                      {new Date(message.timestamp).toLocaleTimeString()}
                    </span>
                  </div>
                  <div className="message-content">{message.message}</div>
                </div>
              ))}
            </div>
            
            <div className="chat-input">
              <input
                type="text"
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
                placeholder="Send a message..."
                maxLength={200}
              />
              <button onClick={sendMessage} disabled={!newMessage.trim()}>
                <MessageCircle size={16} />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Premium Features Bar */}
      <div className="premium-features">
        <div className="feature-stats">
          <div className="stat-item">
            <Heart size={16} className="hearts" />
            <span>{reactions.hearts}</span>
          </div>
          <div className="stat-item">
            <Star size={16} className="stars" />
            <span>{reactions.stars}</span>
          </div>
          <div className="stat-item">
            <Zap size={16} className="fire" />
            <span>{reactions.fire}</span>
          </div>
          {/* LiveKit connection status */}
          <div className="stat-item livekit-stat" title="LiveKit connection status">
            <div className={`livekit-dot ${liveKitConnected ? 'connected' : 'disconnected'}`}></div>
            <span>LiveKit</span>
          </div>
        </div>
        
        {(userSubscription?.isPremium || userSubscription?.hasTicket || userSubscription?.isVIP || isEventCreator) && (
          <div className="premium-actions">
            <EnhancedTipButton 
              event={event}
              artistId={event?.artistId}
              venueId={event?.venueId}
              size="medium"
              showAmountSelector={true}
              onTipStart={(tipRecord) => {
                console.log('🎁 Tip started in EventsTheatre:', tipRecord);
                // Optional: Show tip animation or notification
              }}
              onTipComplete={(tipRecord) => {
                console.log('✅ Tip completed in EventsTheatre:', tipRecord);
                // Reload tip stats or show success animation
                loadTipStats();
              }}
            />
            <button className="share-btn">
              <Share2 size={16} />
              Share
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default EventsTheatre;