// src/pages/ScheduleRoomPage.jsx
//
// Screen B: a host defines a recurring show once — name, start, duration,
// repeat, genre, visibility, replay — and never touches room creation again.
// The right column previews exactly what a listener will see on Discover and
// re-renders on every keystroke.

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { ImagePlus } from 'lucide-react';
import TalkStudioNav, { initialsOf } from '../components/layout/TalkStudioNav';
import { useAuth } from '../contexts/AuthContext';
import { uploadMedia } from '../services/mediaLibraryService';
import {
  saveScheduledRoom,
  getRoom,
  slugify,
  uniqueSlug,
  REPEAT_RULES,
  GENRES,
  MIN_DURATION_MIN,
  MAX_DURATION_MIN,
  formatDuration,
  formatLeadTime,
  cadenceLabel,
  occurrenceDate,
} from '../services/scheduledRoomsService';
import './ScheduleRoomPage.css';

const DURATIONS = [30, 45, 60, 90, 120, 180, 240, 360];

/** <input type="datetime-local"> wants local wall-clock, not an ISO instant. */
const toLocalInput = (date) => {
  const pad = (n) => String(n).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
};

const defaultStart = () => {
  const date = new Date();
  date.setDate(date.getDate() + 1);
  date.setHours(21, 0, 0, 0);
  return date;
};

const shortZone = () => {
  const parts = new Intl.DateTimeFormat([], { timeZoneName: 'short' }).formatToParts(new Date());
  return (parts.find(p => p.type === 'timeZoneName') || {}).value || '';
};

const ScheduleRoomPage = () => {
  const { roomId } = useParams();
  const { currentUser } = useAuth();
  const navigate = useNavigate();

  const [form, setForm] = useState({
    title: '',
    slug: '',
    startAt: toLocalInput(defaultStart()),
    durationMin: 120,
    repeat: 'weekly',
    genres: [],
    visibility: 'public',
    accessCode: '',
    publishReplay: true,
    emailReplay: false,
    artworkUrl: null,
  });
  const [slugTouched, setSlugTouched] = useState(false);
  const [errors, setErrors] = useState({});
  const [saving, setSaving] = useState(null); // 'published' | 'draft'
  const [formError, setFormError] = useState(null);
  const [artworkBusy, setArtworkBusy] = useState(false);
  const artworkInputRef = useRef(null);

  useEffect(() => {
    if (!currentUser) navigate(`/login?next=${encodeURIComponent('/schedule')}`);
  }, [currentUser, navigate]);

  // Editing an existing show.
  useEffect(() => {
    if (!roomId) return;
    getRoom(roomId)
      .then(room => {
        if (!room) return;
        setSlugTouched(true);
        setForm({
          title: room.title || '',
          slug: room.slug || '',
          startAt: toLocalInput(occurrenceDate(room.startAt) || defaultStart()),
          durationMin: room.durationMin || 120,
          repeat: room.repeat || 'weekly',
          genres: room.genres || [],
          visibility: room.visibility || 'public',
          accessCode: room.accessCode || '',
          publishReplay: room.publishReplay !== false,
          emailReplay: Boolean(room.emailReplay),
          artworkUrl: room.artworkUrl || null,
        });
      })
      .catch(err => setFormError(err.message));
  }, [roomId]);

  const set = (patch) => setForm(prev => ({ ...prev, ...patch }));

  // The slug follows the name until the host edits it themselves.
  const effectiveSlug = slugTouched ? slugify(form.slug) : slugify(form.title);

  const toggleGenre = (genre) =>
    set({
      genres: form.genres.includes(genre)
        ? form.genres.filter(g => g !== genre)
        : [...form.genres, genre],
    });

  const startDate = useMemo(() => {
    const date = new Date(form.startAt);
    return Number.isNaN(date.getTime()) ? null : date;
  }, [form.startAt]);

  const validate = useCallback(() => {
    const next = {};
    if (!form.title.trim()) next.title = 'Give the show a name';
    if (!effectiveSlug) next.slug = 'The link needs at least one letter or number';
    if (!startDate) next.startAt = 'Pick a start time';
    else if (form.repeat === 'once' && startDate <= new Date()) {
      next.startAt = 'A one-off show has to start in the future';
    }
    if (form.durationMin < MIN_DURATION_MIN || form.durationMin > MAX_DURATION_MIN) {
      next.durationMin = 'Shows run between 15 minutes and 6 hours';
    }
    if (!form.genres.length) next.genres = 'Pick at least one genre';
    if (form.visibility === 'invite' && !form.accessCode.trim()) {
      next.accessCode = 'Invite-only rooms need an access code';
    }
    setErrors(next);
    return Object.keys(next).length === 0;
  }, [form, effectiveSlug, startDate]);

  const handleArtwork = async (file) => {
    if (!file) return;
    setArtworkBusy(true);
    setFormError(null);
    try {
      // Show art lands in the creator's media library, so it can be reused.
      const media = await uploadMedia({ file, user: currentUser, title: `${form.title} art` });
      set({ artworkUrl: media.url });
    } catch (err) {
      setFormError(err.message || 'Could not upload that image');
    } finally {
      setArtworkBusy(false);
      if (artworkInputRef.current) artworkInputRef.current.value = '';
    }
  };

  const submit = async (status) => {
    setFormError(null);
    if (status === 'published' && !validate()) return;
    setSaving(status);
    try {
      const slug = slugTouched
        ? effectiveSlug
        : await uniqueSlug(form.title, { ignoreRoomId: roomId || null });

      const { slug: savedSlug } = await saveScheduledRoom({
        id: roomId || null,
        user: currentUser,
        status,
        data: {
          ...form,
          slug,
          startAt: startDate,
          durationMin: Number(form.durationMin),
        },
      });

      navigate(status === 'published' ? `/r/${savedSlug}` : '/schedule/all');
    } catch (err) {
      setFormError(err.message || 'Could not save the schedule');
    } finally {
      setSaving(null);
    }
  };

  const previewBadge = startDate
    ? startDate.toLocaleDateString([], { weekday: 'short' }).toUpperCase() +
      ' ' +
      startDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false })
    : 'TBC';

  return (
    <div className="ts-app schedule-page">
      <TalkStudioNav
        active="schedule"
        rightNote={
          currentUser ? (
            <span className="schedule-hosting-as">
              Hosting as {currentUser.displayName || currentUser.email}
            </span>
          ) : null
        }
      />

      <div className="ts-page schedule-grid">
        {/* ------------- form ------------- */}
        <div className="schedule-form">
          <h1 className="schedule-title">{roomId ? 'Edit show' : 'Schedule a room'}</h1>
          <p className="schedule-sub">
            Set it once. The room keeps the same link every week, and listeners who
            RSVP get a ping ten minutes before you go on.
          </p>

          <div className="schedule-fields">
            <div className="ts-field">
              <label className="ts-label" htmlFor="show-name">Show name</label>
              <input
                id="show-name"
                className={`ts-input ${errors.title ? 'ts-input--error' : ''}`}
                value={form.title}
                onChange={e => set({ title: e.target.value })}
                placeholder="Late Shift Radio"
              />
              {errors.title && <div className="ts-field-error">{errors.title}</div>}
              <input
                className="schedule-slug-input ts-mono"
                value={effectiveSlug}
                onChange={e => { setSlugTouched(true); set({ slug: e.target.value }); }}
                aria-label="Room link"
              />
              <div className="ts-field-help">
                talkstudio.space/r/{effectiveSlug || '…'} · permanent link, safe to post anywhere
              </div>
              {errors.slug && <div className="ts-field-error">{errors.slug}</div>}
            </div>

            <div className="schedule-field-row">
              <div className="ts-field">
                <label className="ts-label" htmlFor="show-start">Starts</label>
                <div className="schedule-start">
                  <input
                    id="show-start"
                    type="datetime-local"
                    className={`ts-input ts-mono ${errors.startAt ? 'ts-input--error' : ''}`}
                    value={form.startAt}
                    onChange={e => set({ startAt: e.target.value })}
                  />
                  <span className="schedule-zone">{shortZone()}</span>
                </div>
                {errors.startAt && <div className="ts-field-error">{errors.startAt}</div>}
              </div>

              <div className="ts-field">
                <label className="ts-label" htmlFor="show-duration">Runs for</label>
                <select
                  id="show-duration"
                  className={`ts-select ${errors.durationMin ? 'ts-input--error' : ''}`}
                  value={form.durationMin}
                  onChange={e => set({ durationMin: Number(e.target.value) })}
                >
                  {DURATIONS.map(min => (
                    <option key={min} value={min}>{formatDuration(min)}</option>
                  ))}
                </select>
                {errors.durationMin && <div className="ts-field-error">{errors.durationMin}</div>}
              </div>
            </div>

            <div className="ts-field">
              <span className="ts-label">Repeat</span>
              <div className="schedule-pills">
                {REPEAT_RULES.map(rule => (
                  <button
                    key={rule.id}
                    type="button"
                    className={`ts-pill ${form.repeat === rule.id ? 'selected' : ''}`}
                    onClick={() => set({ repeat: rule.id })}
                  >
                    {rule.label}
                  </button>
                ))}
              </div>
            </div>

            <div className="ts-field">
              <span className="ts-label">Genre — how listeners filter</span>
              <div className="schedule-pills">
                {GENRES.map(genre => {
                  const on = form.genres.includes(genre);
                  return (
                    <button
                      key={genre}
                      type="button"
                      className={`ts-chip-toggle ${on ? 'selected' : ''}`}
                      onClick={() => toggleGenre(genre)}
                    >
                      {genre}{on ? ' ✓' : ''}
                    </button>
                  );
                })}
              </div>
              {errors.genres && <div className="ts-field-error">{errors.genres}</div>}
            </div>

            <div className="ts-field">
              <span className="ts-label">Who can join</span>
              <div className="schedule-radios">
                <button
                  type="button"
                  className={`ts-radio-card ${form.visibility === 'public' ? 'selected' : ''}`}
                  onClick={() => set({ visibility: 'public' })}
                >
                  <span className={`ts-radio ${form.visibility === 'public' ? 'selected' : ''}`} />
                  <span>
                    <span className="schedule-radio-title">Public — anyone with the link</span>
                    <span className="schedule-radio-sub">
                      Listed on Discover and the schedule. No account needed to listen.
                    </span>
                  </span>
                </button>

                <button
                  type="button"
                  className={`ts-radio-card ${form.visibility === 'invite' ? 'selected' : ''}`}
                  onClick={() => set({ visibility: 'invite' })}
                >
                  <span className={`ts-radio ${form.visibility === 'invite' ? 'selected' : ''}`} />
                  <span>
                    <span className="schedule-radio-title">Invite only</span>
                    <span className="schedule-radio-sub">
                      Hidden from Discover. Access code required.
                    </span>
                  </span>
                </button>

                {form.visibility === 'invite' && (
                  <>
                    <input
                      className={`ts-input ${errors.accessCode ? 'ts-input--error' : ''}`}
                      value={form.accessCode}
                      onChange={e => set({ accessCode: e.target.value })}
                      placeholder="Access code"
                      aria-label="Access code"
                    />
                    {errors.accessCode && <div className="ts-field-error">{errors.accessCode}</div>}
                  </>
                )}
              </div>
            </div>

            <div className="ts-field">
              <span className="ts-label">After the show</span>
              <div className="schedule-toggles">
                <div className="ts-toggle-row">
                  <div className="schedule-toggle-label">
                    Publish a replay <span className="schedule-toggle-note">— stays up 30 days</span>
                  </div>
                  <button
                    type="button"
                    className={`ts-toggle ${form.publishReplay ? 'on' : ''}`}
                    onClick={() => set({ publishReplay: !form.publishReplay })}
                    aria-pressed={form.publishReplay}
                    aria-label="Publish a replay"
                  >
                    <span className="ts-toggle-knob" />
                  </button>
                </div>

                <div className="ts-toggle-row">
                  <div className="schedule-toggle-label">
                    Email the RSVP list a link to the replay
                  </div>
                  <button
                    type="button"
                    className={`ts-toggle ${form.emailReplay ? 'on' : ''}`}
                    onClick={() => set({ emailReplay: !form.emailReplay })}
                    aria-pressed={form.emailReplay}
                    aria-label="Email the RSVP list a link to the replay"
                  >
                    <span className="ts-toggle-knob" />
                  </button>
                </div>
              </div>
            </div>

            {formError && <div className="ts-field-error">{formError}</div>}

            <div className="schedule-actions">
              <button
                type="button"
                className="ts-btn ts-btn--primary ts-btn--lg"
                onClick={() => submit('published')}
                disabled={Boolean(saving)}
              >
                {saving === 'published' ? 'Publishing…' : 'Publish schedule'}
              </button>
              <button
                type="button"
                className="ts-btn ts-btn--neutral ts-btn--lg"
                onClick={() => submit('draft')}
                disabled={Boolean(saving)}
              >
                {saving === 'draft' ? 'Saving…' : 'Save draft'}
              </button>
            </div>
          </div>
        </div>

        {/* ------------- live preview ------------- */}
        <div className="schedule-preview-col">
          <div className="ts-label">What listeners will see</div>

          <div className="ts-card schedule-preview">
            <button
              type="button"
              className="ts-art schedule-preview-art"
              style={form.artworkUrl ? { backgroundImage: `url(${form.artworkUrl})` } : undefined}
              onClick={() => artworkInputRef.current?.click()}
              disabled={artworkBusy}
            >
              {!form.artworkUrl && (
                <span className="schedule-art-hint">
                  <ImagePlus size={16} />
                  {artworkBusy ? 'Uploading…' : 'show art — drop an image'}
                </span>
              )}
            </button>
            <input
              ref={artworkInputRef}
              type="file"
              accept="image/*"
              style={{ display: 'none' }}
              onChange={e => handleArtwork(e.target.files?.[0])}
            />

            <div className="schedule-preview-body">
              <div className="schedule-preview-badges">
                <span className="ts-badge-when">{previewBadge}</span>
                <span className="ts-mono schedule-preview-lead">
                  {startDate ? formatLeadTime(startDate) : ''} · {formatDuration(Number(form.durationMin))}
                </span>
              </div>
              <div className="schedule-preview-title">{form.title || 'Your show'}</div>
              <div className="schedule-preview-host">
                {currentUser?.displayName || currentUser?.email || 'you'}
                {form.genres.length ? ` · ${form.genres.join(', ')}` : ''} · {cadenceLabel(form.repeat)}
              </div>
              <button type="button" className="ts-btn ts-btn--primary ts-btn--md ts-btn--block" disabled>
                Notify me
              </button>
              <div className="schedule-preview-going">0 going</div>
            </div>
          </div>

          <div className="ts-tile schedule-explainer">
            <div className="schedule-explainer-title">Going live is two clicks</div>
            <p className="schedule-explainer-body">
              Ten minutes before showtime the Studio opens with this room already
              loaded. Hit <span className="schedule-explainer-accent">Go live</span> — no room
              to create, no link to copy, no stream key.
            </p>
          </div>

          {currentUser && (
            <div className="schedule-avatar-row">
              <span className="ts-avatar">{initialsOf(currentUser)}</span>
              <span className="schedule-avatar-note">
                Published shows appear on your profile and on Discover.
              </span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ScheduleRoomPage;
