import React, { useRef, useEffect, useState } from 'react';

const WorkingReplayPlayer = ({ 
  eventId, 
  autoPlay = false, 
  showControls = true, 
  className = '',
  onEventLoad,
  onPlayerReady,
  onError 
}) => {
  const videoRef = useRef(null);
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [videoUrl, setVideoUrl] = useState('');

  useEffect(() => {
    console.log('WorkingReplayPlayer: Mounted with eventId:', eventId);
    
    if (eventId) {
      // Construct the video URL directly
      const url = `https://storage.googleapis.com/talkstudio-fb.appspot.com/finished-events/${eventId}/${eventId}.mp4`;
      setVideoUrl(url);
      console.log('WorkingReplayPlayer: Video URL:', url);
      
      // Simulate event load callback
      if (onEventLoad) {
        onEventLoad({
          id: eventId,
          title: `Event ${eventId}`,
          videos: {
            combined: {
              standard: { url }
            }
          }
        });
      }
    }
  }, [eventId, onEventLoad]);

  const handleLoadStart = () => {
    console.log('WorkingReplayPlayer: Video load started');
    setIsLoading(true);
    setHasError(false);
  };

  const handleLoadedMetadata = (e) => {
    console.log('WorkingReplayPlayer: Metadata loaded', {
      duration: e.target.duration,
      width: e.target.videoWidth,
      height: e.target.videoHeight
    });
    setIsLoading(false);
    
    if (onPlayerReady) {
      onPlayerReady();
    }
  };

  const handleCanPlay = () => {
    console.log('WorkingReplayPlayer: Can play');
    
    if (autoPlay && videoRef.current) {
      videoRef.current.play().catch(err => {
        console.error('WorkingReplayPlayer: Autoplay failed:', err);
      });
    }
  };

  const handleError = (e) => {
    console.error('WorkingReplayPlayer: Video error', e);
    const video = e.target;
    
    setIsLoading(false);
    setHasError(true);
    
    if (video.error) {
      let errorMsg = 'Unknown error';
      switch(video.error.code) {
        case 1: errorMsg = 'MEDIA_ERR_ABORTED - The fetching process was aborted'; break;
        case 2: errorMsg = 'MEDIA_ERR_NETWORK - A network error occurred'; break;
        case 3: errorMsg = 'MEDIA_ERR_DECODE - An error occurred while decoding'; break;
        case 4: errorMsg = 'MEDIA_ERR_SRC_NOT_SUPPORTED - The video format is not supported'; break;
      }
      setErrorMessage(`${errorMsg} (${video.error.message || 'No additional info'})`);
      
      if (onError) {
        onError(new Error(errorMsg));
      }
    }
  };

  if (!eventId) {
    return (
      <div className={`relative bg-black aspect-video flex items-center justify-center ${className}`}>
        <div className="text-white">No event ID provided</div>
      </div>
    );
  }

  if (hasError) {
    return (
      <div className={`relative bg-black aspect-video flex items-center justify-center ${className}`}>
        <div className="text-center text-white">
          <div className="text-red-400 text-6xl mb-4">⚠️</div>
          <div className="text-xl font-medium mb-2">Playback Error</div>
          <div className="text-gray-300 mb-4">{errorMessage}</div>
          <button 
            onClick={() => window.location.reload()}
            className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 rounded-lg transition-colors"
          >
            Reload Player
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className={`relative bg-black aspect-video group ${className}`}>
      {/* Loading Spinner */}
      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-10">
          <div className="text-center text-white">
            <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4 mx-auto"></div>
            <div className="text-lg font-medium">Loading Video...</div>
          </div>
        </div>
      )}

      {/* Video Element */}
      <video
        ref={videoRef}
        className="w-full h-full object-contain"
        controls={showControls}
        src={videoUrl}
        preload="metadata"
        playsInline
        onLoadStart={handleLoadStart}
        onLoadedMetadata={handleLoadedMetadata}
        onCanPlay={handleCanPlay}
        onError={handleError}
        onPlay={() => console.log('WorkingReplayPlayer: Playing')}
        onPause={() => console.log('WorkingReplayPlayer: Paused')}
        onEnded={() => console.log('WorkingReplayPlayer: Ended')}
      />

      {/* Debug Info Overlay (only in development) */}
      {process.env.NODE_ENV === 'development' && (
        <div className="absolute bottom-2 left-2 bg-black bg-opacity-75 text-white text-xs px-2 py-1 rounded pointer-events-none">
          Event: {eventId}
        </div>
      )}
    </div>
  );
};

export default WorkingReplayPlayer;