import { getDatabase, ref, push, set, get, update, onValue, query, orderByChild, equalTo } from 'firebase/database';
import { getAuth } from 'firebase/auth';
import CategoryService from './CategoryService';

class TopicService {
  constructor() {
    this.database = getDatabase();
    this.auth = getAuth();
    this.topicsPath = 'topics';
  }

  /**
   * Get current user ID
   */
  getCurrentUserId() {
    return this.auth.currentUser?.uid;
  }

  /**
   * Create a new topic
   */
  async createTopic({ categoryId, name, description, iconName = null, colorHex = null, sortOrder = 0 }) {
    try {
      const userId = this.getCurrentUserId();
      if (!userId) {
        throw new Error('No authenticated user');
      }

      console.log('🏷️ Creating topic:', name);

      const now = Date.now();
      const topicData = {
        categoryId,
        name,
        description,
        iconName,
        colorHex,
        sortOrder,
        isActive: true,
        eventCount: 0,
        ideaCount: 0,
        followerCount: 0,
        createdAt: now,
        updatedAt: now,
      };

      const topicRef = push(ref(this.database, this.topicsPath));
      await set(topicRef, topicData);

      // Increment topic count in parent category
      await CategoryService.incrementTopicCount(categoryId);

      console.log('✅ Topic created with ID:', topicRef.key);
      return topicRef.key;
    } catch (error) {
      console.error('❌ Failed to create topic:', error);
      throw error;
    }
  }

  /**
   * Get a topic by ID
   */
  async getTopic(topicId) {
    try {
      console.log('🔍 Loading topic:', topicId);

      const topicRef = ref(this.database, `${this.topicsPath}/${topicId}`);
      const snapshot = await get(topicRef);

      if (!snapshot.exists()) {
        console.log('🚫 Topic not found:', topicId);
        return null;
      }

      const data = snapshot.val();
      return {
        id: topicId,
        ...data,
      };
    } catch (error) {
      console.error('❌ Failed to load topic:', error);
      throw error;
    }
  }

  /**
   * Stream all topics (real-time)
   */
  streamAllTopics(callback) {
    const topicsRef = query(
      ref(this.database, this.topicsPath),
      orderByChild('sortOrder')
    );

    const unsubscribe = onValue(topicsRef, (snapshot) => {
      const topics = [];

      if (snapshot.exists()) {
        const data = snapshot.val();

        Object.entries(data).forEach(([key, value]) => {
          // Only include active topics
          if (value.isActive) {
            topics.push({
              id: key,
              ...value,
            });
          }
        });

        // Sort by sortOrder
        topics.sort((a, b) => a.sortOrder - b.sortOrder);
      }

      callback(topics);
    });

    return unsubscribe;
  }

  /**
   * Stream topics by category (real-time)
   */
  streamTopicsByCategory(categoryId, callback) {
    const topicsRef = query(
      ref(this.database, this.topicsPath),
      orderByChild('categoryId'),
      equalTo(categoryId)
    );

    const unsubscribe = onValue(topicsRef, (snapshot) => {
      const topics = [];

      if (snapshot.exists()) {
        const data = snapshot.val();

        Object.entries(data).forEach(([key, value]) => {
          // Only include active topics
          if (value.isActive) {
            topics.push({
              id: key,
              ...value,
            });
          }
        });

        // Sort by sortOrder
        topics.sort((a, b) => a.sortOrder - b.sortOrder);
      }

      callback(topics);
    });

    return unsubscribe;
  }

  /**
   * Get all topics (one-time fetch)
   */
  async getAllTopics() {
    try {
      console.log('🔍 Loading all topics');

      const topicsRef = query(
        ref(this.database, this.topicsPath),
        orderByChild('sortOrder')
      );
      const snapshot = await get(topicsRef);

      const topics = [];

      if (snapshot.exists()) {
        const data = snapshot.val();

        Object.entries(data).forEach(([key, value]) => {
          // Only include active topics
          if (value.isActive) {
            topics.push({
              id: key,
              ...value,
            });
          }
        });

        topics.sort((a, b) => a.sortOrder - b.sortOrder);
      }

      return topics;
    } catch (error) {
      console.error('❌ Failed to load topics:', error);
      return [];
    }
  }

  /**
   * Get topics by category (one-time fetch)
   */
  async getTopicsByCategory(categoryId) {
    try {
      console.log('🔍 Loading topics for category:', categoryId);

      const topicsRef = query(
        ref(this.database, this.topicsPath),
        orderByChild('categoryId'),
        equalTo(categoryId)
      );
      const snapshot = await get(topicsRef);

      const topics = [];

      if (snapshot.exists()) {
        const data = snapshot.val();

        Object.entries(data).forEach(([key, value]) => {
          // Only include active topics
          if (value.isActive) {
            topics.push({
              id: key,
              ...value,
            });
          }
        });

        topics.sort((a, b) => a.sortOrder - b.sortOrder);
      }

      return topics;
    } catch (error) {
      console.error('❌ Failed to load topics:', error);
      return [];
    }
  }

  /**
   * Update a topic
   */
  async updateTopic(topicId, updates) {
    try {
      const userId = this.getCurrentUserId();
      if (!userId) {
        throw new Error('No authenticated user');
      }

      console.log('📝 Updating topic:', topicId);

      updates.updatedAt = Date.now();

      const topicRef = ref(this.database, `${this.topicsPath}/${topicId}`);
      await update(topicRef, updates);

      console.log('✅ Topic updated');
      return true;
    } catch (error) {
      console.error('❌ Failed to update topic:', error);
      throw error;
    }
  }

  /**
   * Delete/deactivate a topic
   */
  async deleteTopic(topicId) {
    try {
      const userId = this.getCurrentUserId();
      if (!userId) {
        throw new Error('No authenticated user');
      }

      console.log('🗑️ Deactivating topic:', topicId);

      // Get the topic to find its category
      const topic = await this.getTopic(topicId);
      if (!topic) return false;

      const topicRef = ref(this.database, `${this.topicsPath}/${topicId}`);
      await update(topicRef, {
        isActive: false,
        updatedAt: Date.now(),
      });

      // Decrement topic count in parent category
      await CategoryService.decrementTopicCount(topic.categoryId);

      console.log('✅ Topic deactivated');
      return true;
    } catch (error) {
      console.error('❌ Failed to deactivate topic:', error);
      throw error;
    }
  }

  /**
   * Increment follower count
   */
  async incrementFollowerCount(topicId) {
    try {
      const topic = await this.getTopic(topicId);
      if (!topic) return;

      await this.updateTopic(topicId, {
        followerCount: (topic.followerCount || 0) + 1,
      });
    } catch (error) {
      console.error('❌ Failed to increment follower count:', error);
    }
  }

  /**
   * Decrement follower count
   */
  async decrementFollowerCount(topicId) {
    try {
      const topic = await this.getTopic(topicId);
      if (!topic) return;

      const newCount = Math.max(0, (topic.followerCount || 0) - 1);
      await this.updateTopic(topicId, {
        followerCount: newCount,
      });
    } catch (error) {
      console.error('❌ Failed to decrement follower count:', error);
    }
  }

  /**
   * Increment event count
   */
  async incrementEventCount(topicId) {
    try {
      const topic = await this.getTopic(topicId);
      if (!topic) return;

      await this.updateTopic(topicId, {
        eventCount: (topic.eventCount || 0) + 1,
      });
    } catch (error) {
      console.error('❌ Failed to increment event count:', error);
    }
  }

  /**
   * Decrement event count
   */
  async decrementEventCount(topicId) {
    try {
      const topic = await this.getTopic(topicId);
      if (!topic) return;

      const newCount = Math.max(0, (topic.eventCount || 0) - 1);
      await this.updateTopic(topicId, {
        eventCount: newCount,
      });
    } catch (error) {
      console.error('❌ Failed to decrement event count:', error);
    }
  }

  /**
   * Increment idea count
   */
  async incrementIdeaCount(topicId) {
    try {
      const topic = await this.getTopic(topicId);
      if (!topic) return;

      await this.updateTopic(topicId, {
        ideaCount: (topic.ideaCount || 0) + 1,
      });
    } catch (error) {
      console.error('❌ Failed to increment idea count:', error);
    }
  }

  /**
   * Decrement idea count
   */
  async decrementIdeaCount(topicId) {
    try {
      const topic = await this.getTopic(topicId);
      if (!topic) return;

      const newCount = Math.max(0, (topic.ideaCount || 0) - 1);
      await this.updateTopic(topicId, {
        ideaCount: newCount,
      });
    } catch (error) {
      console.error('❌ Failed to decrement idea count:', error);
    }
  }
}

export default new TopicService();
