// src/components/profile/ProfileQRCode.jsx
import React, { useRef, useState } from 'react';
import { QRCodeCanvas } from 'qrcode.react';
import { X, Download, Copy, Check, Share2 } from 'lucide-react';

const ProfileQRCode = ({ url, name, onClose }) => {
  const canvasWrapperRef = useRef(null);
  const [copied, setCopied] = useState(false);

  const handleCopyUrl = async () => {
    try {
      await navigator.clipboard.writeText(url);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy URL:', err);
    }
  };

  const handleDownload = () => {
    const canvas = canvasWrapperRef.current?.querySelector('canvas');
    if (!canvas) return;
    const dataUrl = canvas.toDataURL('image/png');
    const link = document.createElement('a');
    const safeName = (name || 'profile').replace(/[^a-z0-9]+/gi, '-').toLowerCase();
    link.download = `${safeName}-qr.png`;
    link.href = dataUrl;
    link.click();
  };

  const handleNativeShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: name ? `${name} on Presence` : 'Profile on Presence',
          text: name ? `Check out ${name}'s profile` : 'Check out this profile',
          url,
        });
      } catch (err) {
        if (err.name !== 'AbortError') {
          console.error('Share failed:', err);
        }
      }
    } else {
      handleCopyUrl();
    }
  };

  const handleBackdropClick = (e) => {
    if (e.target === e.currentTarget) onClose();
  };

  return (
    <div className="qr-modal-backdrop" onClick={handleBackdropClick} role="dialog" aria-modal="true">
      <div className="qr-modal">
        <button className="qr-close" onClick={onClose} aria-label="Close">
          <X size={20} />
        </button>

        <h2 className="qr-title">Share Profile</h2>
        {name && <p className="qr-subtitle">{name}</p>}

        <div className="qr-canvas-wrapper" ref={canvasWrapperRef}>
          <QRCodeCanvas
            value={url}
            size={240}
            level="M"
            includeMargin
            bgColor="#ffffff"
            fgColor="#111827"
          />
        </div>

        <div className="qr-url" title={url}>{url}</div>

        <div className="qr-actions">
          <button className="qr-btn qr-btn-primary" onClick={handleDownload}>
            <Download size={16} />
            Download
          </button>
          <button className="qr-btn" onClick={handleCopyUrl}>
            {copied ? <Check size={16} /> : <Copy size={16} />}
            {copied ? 'Copied' : 'Copy link'}
          </button>
          <button className="qr-btn" onClick={handleNativeShare}>
            <Share2 size={16} />
            Share
          </button>
        </div>

        <p className="qr-hint">Scan this code to open the profile on any device.</p>
      </div>

      <style jsx>{`
        .qr-modal-backdrop {
          position: fixed;
          inset: 0;
          background: rgba(0, 0, 0, 0.6);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 1000;
          padding: 1rem;
        }
        .qr-modal {
          background: #ffffff;
          border-radius: 16px;
          padding: 2rem;
          width: 100%;
          max-width: 360px;
          position: relative;
          text-align: center;
          box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
        }
        .qr-close {
          position: absolute;
          top: 0.75rem;
          right: 0.75rem;
          background: transparent;
          border: none;
          color: #6b7280;
          cursor: pointer;
          padding: 0.25rem;
          border-radius: 6px;
        }
        .qr-close:hover { background: #f3f4f6; color: #111827; }
        .qr-title {
          font-size: 1.25rem;
          font-weight: 600;
          margin: 0 0 0.25rem 0;
          color: #111827;
        }
        .qr-subtitle {
          font-size: 0.95rem;
          color: #6b7280;
          margin: 0 0 1.25rem 0;
        }
        .qr-canvas-wrapper {
          display: inline-block;
          padding: 0.75rem;
          background: #ffffff;
          border: 1px solid #e5e7eb;
          border-radius: 12px;
          margin-bottom: 1rem;
        }
        .qr-url {
          font-size: 0.8rem;
          color: #4b5563;
          background: #f9fafb;
          padding: 0.5rem 0.75rem;
          border-radius: 8px;
          margin-bottom: 1rem;
          word-break: break-all;
          font-family: monospace;
        }
        .qr-actions {
          display: flex;
          gap: 0.5rem;
          justify-content: center;
          flex-wrap: wrap;
          margin-bottom: 0.75rem;
        }
        .qr-btn {
          display: inline-flex;
          align-items: center;
          gap: 0.35rem;
          padding: 0.55rem 0.9rem;
          border-radius: 8px;
          border: 1px solid #e5e7eb;
          background: #ffffff;
          color: #111827;
          font-size: 0.85rem;
          font-weight: 500;
          cursor: pointer;
          transition: background 0.15s;
        }
        .qr-btn:hover { background: #f3f4f6; }
        .qr-btn-primary {
          background: #6366f1;
          border-color: #6366f1;
          color: #ffffff;
        }
        .qr-btn-primary:hover { background: #4f46e5; }
        .qr-hint {
          font-size: 0.8rem;
          color: #6b7280;
          margin: 0;
        }
      `}</style>
    </div>
  );
};

export default ProfileQRCode;
