import { useState } from 'react'
import { useParams, Link } from 'react-router-dom'
import { ArrowLeft, Clock, ExternalLink, Loader2, Brain, Newspaper, Rss, Sparkles } from 'lucide-react'
import { usePredictions } from '../contexts/PredictionContext'
import { useLiveData } from '../contexts/LiveDataContext'
import Card from '../components/common/Card'
import Badge from '../components/common/Badge'
import ConfidenceBar from '../components/common/ConfidenceBar'
import TrendIndicator from '../components/common/TrendIndicator'
import TrendSparkline from '../components/charts/TrendSparkline'
import VoteButtons from '../components/common/VoteButtons'
import { useCountdown } from '../hooks/useCountdown'
import { getConfidenceColor, getConfidenceLabel } from '../utils/weights'
import { mockSources } from '../utils/mockData'
import inputPipeline from '../services/inputPipeline'
import ContextPanel from '../components/context/ContextPanel'
import PremiumGuard from '../../components/premium/PremiumGuard'

export default function PredictionDetail() {
  const { id } = useParams()
  const { allPredictions } = usePredictions()
  const prediction = allPredictions.find(p => p.id === id)
  const { label: timeLeft, isExpired } = useCountdown(prediction?.deadline || '2099-01-01')
  const { getLiveInputs, getAiAnalysis, runAiAnalysis, newsArticles, rssItems } = useLiveData()
  const [aiLoading, setAiLoading] = useState(false)

  if (!prediction) {
    return (
      <div className="text-center py-20">
        <p className="text-gray-500 text-lg">Prediction not found</p>
        <Link to="/" className="text-blue-400 text-sm mt-2 inline-block">Back to Dashboard</Link>
      </div>
    )
  }

  const liveInputs = getLiveInputs(prediction.id)
  const aiAnalysis = getAiAnalysis(prediction.id)
  const allInputs = inputPipeline.mergeInputsWithPrediction(prediction, liveInputs)
  const adjustedOutcomes = aiAnalysis
    ? inputPipeline.recalculateOutcomes(prediction, liveInputs, aiAnalysis)
    : liveInputs.length > 0
      ? inputPipeline.recalculateOutcomes(prediction, liveInputs)
      : prediction.outcomes

  const topOutcome = adjustedOutcomes[0]
  const { text: confColor } = getConfidenceColor(topOutcome.probability)
  const liveNewsInputs = allInputs.filter(i => i.isLive && i.type === 'news')
  const liveRssInputs = allInputs.filter(i => i.isLive && i.type === 'rss')
  const staticInputs = allInputs.filter(i => !i.isLive)

  async function handleAiAnalysis() {
    setAiLoading(true)
    const relevantArticles = [...newsArticles, ...rssItems]
      .filter(a => {
        const text = `${a.title} ${a.description || ''}`.toLowerCase()
        const words = prediction.title.toLowerCase().split(/\W+/).filter(w => w.length > 3)
        return words.some(w => text.includes(w))
      })
    await runAiAnalysis(prediction, relevantArticles)
    setAiLoading(false)
  }

  return (
    <div className="space-y-6 max-w-4xl">
      <Link to="/" className="inline-flex items-center gap-1.5 text-sm text-gray-400 hover:text-gray-200 transition-colors">
        <ArrowLeft size={16} /> Back to Dashboard
      </Link>

      <div>
        <div className="flex items-center gap-3 mb-2">
          <Badge category={prediction.category} size="md" />
          <span className={`flex items-center gap-1 text-sm ${isExpired ? 'text-red-400' : 'text-gray-500'}`}>
            <Clock size={14} /> {timeLeft}
          </span>
          {liveInputs.length > 0 && (
            <span className="flex items-center gap-1 text-xs text-emerald-400">
              <span className="relative flex h-1.5 w-1.5">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75" />
                <span className="relative inline-flex rounded-full h-1.5 w-1.5 bg-emerald-500" />
              </span>
              {liveInputs.length} live inputs
            </span>
          )}
        </div>
        <h1 className="text-2xl font-bold tracking-tight">{prediction.title}</h1>
        <p className="text-gray-400 mt-2">{prediction.description}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card className="p-5 md:col-span-2" hover={false}>
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-sm font-semibold text-gray-300">Outcomes</h2>
            {liveInputs.length > 0 && (
              <span className="text-[10px] text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded-full">
                Adjusted by live data
              </span>
            )}
          </div>
          <div className="space-y-4">
            {adjustedOutcomes.map((outcome, i) => {
              const original = prediction.outcomes[i]
              const diff = original ? outcome.probability - original.probability : 0
              return (
                <div key={i} className="space-y-1">
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-300 font-medium">{outcome.label}</span>
                    <div className="flex items-center gap-2">
                      {diff !== 0 && (
                        <span className={`text-[10px] font-mono ${diff > 0 ? 'text-emerald-400' : 'text-red-400'}`}>
                          {diff > 0 ? '+' : ''}{diff}%
                        </span>
                      )}
                      <span className={`font-mono text-lg font-bold ${i === 0 ? confColor : 'text-gray-400'}`}>
                        {outcome.probability}%
                      </span>
                      <TrendIndicator trend={outcome.trend} showLabel />
                    </div>
                  </div>
                  <ConfidenceBar value={outcome.probability} showLabel={false} />
                </div>
              )
            })}
          </div>
        </Card>

        <div className="space-y-4">
          <Card className="p-5" hover={false}>
            <h2 className="text-sm font-semibold text-gray-300 mb-3">Trend (7 days)</h2>
            <div className="h-20">
              <TrendSparkline data={prediction.trendData} trend={topOutcome.trend} />
            </div>
            <p className="text-xs text-gray-500 mt-2 text-center">
              {getConfidenceLabel(topOutcome.probability)} confidence — {topOutcome.trend === 'up' ? 'Rising' : topOutcome.trend === 'down' ? 'Falling' : 'Stable'}
            </p>
          </Card>

          <Card className="p-5" hover={false}>
            <h2 className="text-sm font-semibold text-gray-300 mb-3">Community Vote</h2>
            <VoteButtons predictionId={prediction.id} initialVotes={prediction.communityVotes} />
          </Card>
        </div>
      </div>

      {/* Context panel — slow-moving reference indicators (rates, labor,
          demographics, etc.) keyed off prediction.contextTags. Phase 1
          uses mock signals; Phase 2+ swaps in live data from contextService. */}
      <ContextPanel tags={prediction.contextTags || []} />

      {/* AI Analysis Section — full feature requires Data tier or higher.
          Anonymous visitors get full access; signed-in free users see the
          section header so they know it exists, with a single upgrade CTA
          inside. PremiumGuard returns its own card when the user is below
          tier so we don't render the AI body at all. */}
      <Card className="p-5" hover={false}>
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <Brain size={16} className="text-violet-400" />
            <h2 className="text-sm font-semibold text-gray-300">AI Analysis</h2>
          </div>
          <PremiumGuard minTier="data" showUpgrade={false} allowAnonymous>
            <button
              onClick={handleAiAnalysis}
              disabled={aiLoading}
              className="flex items-center gap-1.5 px-3 py-1.5 bg-violet-500/15 text-violet-400 border border-violet-500/20 rounded-lg text-xs font-medium hover:bg-violet-500/25 transition-colors disabled:opacity-50"
            >
              {aiLoading ? <Loader2 size={12} className="animate-spin" /> : <Sparkles size={12} />}
              {aiLoading ? 'Analyzing...' : aiAnalysis ? 'Re-analyze' : 'Run AI Analysis'}
            </button>
          </PremiumGuard>
        </div>

        <PremiumGuard minTier="data" featureName="AI analysis" allowAnonymous>
          {aiAnalysis ? (
            <div className="space-y-4">
              <p className="text-sm text-gray-300 leading-relaxed">{aiAnalysis.analysis}</p>
              {aiAnalysis.keyFactors && (
                <div>
                  <p className="text-xs text-gray-500 mb-2">Key Factors:</p>
                  <div className="flex flex-wrap gap-2">
                    {aiAnalysis.keyFactors.map((f, i) => (
                      <span key={i} className="text-xs bg-gray-800 text-gray-400 px-2 py-1 rounded">
                        {f}
                      </span>
                    ))}
                  </div>
                </div>
              )}
              <div className="flex items-center gap-4 text-xs">
                <span className="text-gray-500">
                  Confidence: <span className="font-mono text-violet-400">{aiAnalysis.confidence}%</span>
                </span>
                <span className="text-gray-500">
                  Risk Level: <span className={`font-mono ${
                    aiAnalysis.riskLevel === 'low' ? 'text-emerald-400' :
                    aiAnalysis.riskLevel === 'moderate' ? 'text-amber-400' : 'text-red-400'
                  }`}>{aiAnalysis.riskLevel}</span>
                </span>
              </div>
            </div>
          ) : (
            <p className="text-xs text-gray-600 italic">
              Click "Run AI Analysis" to get Claude's assessment of this prediction based on available data.
              {' Configure a Claude API key in Data Sources to enable.'}
            </p>
          )}
        </PremiumGuard>
      </Card>

      {/* Live News Sources */}
      {liveNewsInputs.length > 0 && (
        <Card className="p-5" hover={false}>
          <div className="flex items-center gap-2 mb-4">
            <Newspaper size={16} className="text-blue-400" />
            <h2 className="text-sm font-semibold text-gray-300">Live News ({liveNewsInputs.length})</h2>
            <span className="relative flex h-1.5 w-1.5 ml-1">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-75" />
              <span className="relative inline-flex rounded-full h-1.5 w-1.5 bg-blue-500" />
            </span>
          </div>
          <div className="space-y-2">
            {liveNewsInputs.slice(0, 8).map((input, i) => (
              <div key={i} className="flex items-start justify-between py-2 border-b border-gray-800/50 last:border-0 gap-3">
                <div className="min-w-0 flex-1">
                  <a href={input.sourceUrl} target="_blank" rel="noopener noreferrer"
                    className="text-sm text-gray-300 hover:text-blue-400 transition-colors flex items-center gap-1">
                    {input.title}
                    <ExternalLink size={10} className="shrink-0" />
                  </a>
                  <p className="text-[10px] text-gray-600 mt-0.5">{input.source} — {new Date(input.timestamp).toLocaleDateString()}</p>
                </div>
                <span className="text-xs font-mono text-gray-500 shrink-0">
                  {Math.round(input.sentiment * 100)}% sentiment
                </span>
              </div>
            ))}
          </div>
        </Card>
      )}

      {/* Live RSS Sources */}
      {liveRssInputs.length > 0 && (
        <Card className="p-5" hover={false}>
          <div className="flex items-center gap-2 mb-4">
            <Rss size={16} className="text-amber-400" />
            <h2 className="text-sm font-semibold text-gray-300">RSS Feeds ({liveRssInputs.length})</h2>
          </div>
          <div className="space-y-2">
            {liveRssInputs.slice(0, 8).map((input, i) => (
              <div key={i} className="flex items-start justify-between py-2 border-b border-gray-800/50 last:border-0 gap-3">
                <div className="min-w-0 flex-1">
                  <a href={input.sourceUrl} target="_blank" rel="noopener noreferrer"
                    className="text-sm text-gray-300 hover:text-amber-400 transition-colors flex items-center gap-1">
                    {input.title}
                    <ExternalLink size={10} className="shrink-0" />
                  </a>
                  <p className="text-[10px] text-gray-600 mt-0.5">{input.source} — {new Date(input.timestamp).toLocaleDateString()}</p>
                </div>
                <span className="text-xs font-mono text-gray-500 shrink-0">
                  {Math.round(input.sentiment * 100)}% sentiment
                </span>
              </div>
            ))}
          </div>
        </Card>
      )}

      {/* Static Data Sources */}
      <Card className="p-5" hover={false}>
        <h2 className="text-sm font-semibold text-gray-300 mb-4">Base Data Sources ({staticInputs.length})</h2>
        <div className="space-y-3">
          {staticInputs.map((input, i) => {
            const source = mockSources.find(s => s.id === input.source)
            return (
              <div key={i} className="flex items-center justify-between py-2 border-b border-gray-800/50 last:border-0">
                <div className="flex items-center gap-3">
                  <span className={`w-2 h-2 rounded-full ${
                    input.type === 'news' ? 'bg-blue-400' :
                    input.type === 'ai' ? 'bg-violet-400' :
                    input.type === 'community' ? 'bg-amber-400' :
                    input.type === 'expert' ? 'bg-emerald-400' :
                    'bg-cyan-400'
                  }`} />
                  <div>
                    <p className="text-sm text-gray-300">{source?.name || input.source}</p>
                    <p className="text-xs text-gray-600 capitalize">{input.type} source</p>
                  </div>
                </div>
                <div className="flex items-center gap-4 text-xs">
                  <span className="text-gray-500">Weight: <span className="font-mono text-gray-400">{input.weight}</span></span>
                  <span className="text-gray-500">Reliability: <span className="font-mono text-gray-400">{Math.round(input.reliability * 100)}%</span></span>
                  <span className="text-gray-500">Sentiment: <span className="font-mono text-gray-400">{Math.round(input.sentiment * 100)}%</span></span>
                </div>
              </div>
            )
          })}
        </div>
      </Card>
    </div>
  )
}
