// src/services/mediaLibraryService.js
//
// Creator media library: the pictures and short clips an artist uploads once
// and then reuses — attached to an activity post, or used as the visuals
// behind a set in the Set Studio.
//
// Files live in Storage under creator-media/{uid}/…; browsable metadata lives
// in Firestore so a picker can list a user's media without walking Storage.
// Clips are capped at MAX_CLIP_SECONDS: this is a library of SHORT clips for
// visuals, not a video host (long-form uploads already use VideoUploadService).
//
// Media document shape:
// {
//   ownerId, ownerName, type: 'image'|'clip', title,
//   url, storagePath, thumbUrl, thumbPath,
//   mimeType, size, width, height, durationMs,
//   createdAt
// }

import {
  getFirestore,
  collection,
  doc,
  setDoc,
  getDoc,
  getDocs,
  query,
  where,
  orderBy,
  limit as fsLimit,
  deleteDoc,
  serverTimestamp,
} from 'firebase/firestore';
import {
  getStorage,
  ref as storageRef,
  uploadBytesResumable,
  getDownloadURL,
  deleteObject,
} from 'firebase/storage';
import { app } from '../firebase';

const COLLECTION = 'creatorMedia';
const STORAGE_ROOT = 'creator-media';

export const MAX_IMAGE_BYTES = 15 * 1024 * 1024;   // 15MB
export const MAX_CLIP_BYTES = 200 * 1024 * 1024;   // 200MB
export const MAX_CLIP_SECONDS = 90;                // "short clip"

export const IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
export const CLIP_TYPES = ['video/mp4', 'video/webm', 'video/ogg', 'video/quicktime'];

const db = () => getFirestore(app);
const store = () => getStorage(app);

/** 'image' | 'clip' | null for anything we don't accept. */
export function mediaKindOf(file) {
  if (!file || !file.type) return null;
  if (IMAGE_TYPES.includes(file.type)) return 'image';
  if (CLIP_TYPES.includes(file.type)) return 'clip';
  return null;
}

/** Cheap, synchronous checks. Duration is validated later, after probing. */
export function validateMediaFile(file) {
  const kind = mediaKindOf(file);
  if (!kind) {
    return { valid: false, error: 'Only JPEG/PNG/GIF/WebP pictures and MP4/WebM/MOV clips are supported' };
  }
  if (!file.size) return { valid: false, error: 'That file is empty' };
  if (kind === 'image' && file.size > MAX_IMAGE_BYTES) {
    return { valid: false, error: `Pictures must be under ${Math.round(MAX_IMAGE_BYTES / 1048576)}MB` };
  }
  if (kind === 'clip' && file.size > MAX_CLIP_BYTES) {
    return { valid: false, error: `Clips must be under ${Math.round(MAX_CLIP_BYTES / 1048576)}MB` };
  }
  return { valid: true, error: null, kind };
}

/** Read dimensions (and, for clips, duration) without uploading anything. */
export function probeMedia(file, kind) {
  return new Promise((resolve) => {
    const url = URL.createObjectURL(file);
    const done = (info) => { URL.revokeObjectURL(url); resolve(info); };

    if (kind === 'image') {
      const img = new Image();
      img.onload = () => done({ width: img.naturalWidth, height: img.naturalHeight, durationMs: 0 });
      img.onerror = () => done({ width: 0, height: 0, durationMs: 0 });
      img.src = url;
      return;
    }

    const video = document.createElement('video');
    video.preload = 'metadata';
    video.onloadedmetadata = () => done({
      width: video.videoWidth,
      height: video.videoHeight,
      durationMs: Number.isFinite(video.duration) ? Math.round(video.duration * 1000) : 0,
    });
    video.onerror = () => done({ width: 0, height: 0, durationMs: 0 });
    video.src = url;
  });
}

/**
 * Grab a poster frame from a clip so the library grid doesn't have to load
 * every video. Returns null if the browser won't decode the file — a missing
 * thumbnail is cosmetic, so callers keep going.
 */
export function captureClipThumbnail(file) {
  return new Promise((resolve) => {
    const url = URL.createObjectURL(file);
    const video = document.createElement('video');
    let settled = false;

    const finish = (blob) => {
      if (settled) return;
      settled = true;
      URL.revokeObjectURL(url);
      resolve(blob);
    };

    video.preload = 'metadata';
    video.muted = true;
    video.playsInline = true;
    video.onloadeddata = () => {
      // A frame at the very start is often black; sample just inside the clip.
      const target = Math.min(1, (video.duration || 1) / 2);
      video.currentTime = Number.isFinite(target) ? target : 0;
    };
    video.onseeked = () => {
      try {
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth || 640;
        canvas.height = video.videoHeight || 360;
        canvas.getContext('2d').drawImage(video, 0, 0, canvas.width, canvas.height);
        canvas.toBlob((blob) => finish(blob), 'image/jpeg', 0.72);
      } catch (_) {
        finish(null); // tainted canvas / codec the browser can't paint
      }
    };
    video.onerror = () => finish(null);
    setTimeout(() => finish(null), 10000);
    video.src = url;
  });
}

const extensionFor = (file) => {
  const fromName = (file.name || '').split('.').pop();
  if (fromName && fromName.length <= 5 && !fromName.includes('/')) return fromName.toLowerCase();
  return (file.type.split('/')[1] || 'bin').toLowerCase();
};

/**
 * Upload one picture or clip into the user's library.
 * `onProgress` receives 0–100. Resolves with the stored media document.
 */
export async function uploadMedia({ file, user, title = '', onProgress = null }) {
  if (!user || !user.uid) throw new Error('Must be signed in to upload media');

  const { valid, error, kind } = validateMediaFile(file);
  if (!valid) throw new Error(error);

  const probe = await probeMedia(file, kind);
  if (kind === 'clip' && probe.durationMs > MAX_CLIP_SECONDS * 1000) {
    throw new Error(`Clips must be ${MAX_CLIP_SECONDS} seconds or shorter`);
  }

  const mediaRef = doc(collection(db(), COLLECTION));
  const mediaId = mediaRef.id;
  const storagePath = `${STORAGE_ROOT}/${user.uid}/${mediaId}.${extensionFor(file)}`;

  const url = await new Promise((resolve, reject) => {
    const task = uploadBytesResumable(storageRef(store(), storagePath), file, {
      contentType: file.type,
    });
    task.on(
      'state_changed',
      (snap) => {
        if (onProgress && snap.totalBytes) {
          onProgress(Math.round((snap.bytesTransferred / snap.totalBytes) * 100));
        }
      },
      reject,
      async () => {
        try {
          resolve(await getDownloadURL(task.snapshot.ref));
        } catch (err) {
          reject(err);
        }
      },
    );
  });

  // Poster frame for clips — best effort, never blocks the upload.
  let thumbUrl = kind === 'image' ? url : null;
  let thumbPath = null;
  if (kind === 'clip') {
    try {
      const blob = await captureClipThumbnail(file);
      if (blob) {
        thumbPath = `${STORAGE_ROOT}/${user.uid}/thumbs/${mediaId}.jpg`;
        const thumbTask = uploadBytesResumable(storageRef(store(), thumbPath), blob, {
          contentType: 'image/jpeg',
        });
        await thumbTask;
        thumbUrl = await getDownloadURL(thumbTask.snapshot.ref);
      }
    } catch (err) {
      console.warn('[mediaLibrary] could not store clip thumbnail:', err.message);
      thumbPath = null;
    }
  }

  const media = {
    ownerId: user.uid,
    ownerName: user.displayName || user.email || 'artist',
    type: kind,
    title: title || file.name || (kind === 'clip' ? 'Clip' : 'Picture'),
    url,
    storagePath,
    thumbUrl,
    thumbPath,
    mimeType: file.type,
    size: file.size,
    width: probe.width,
    height: probe.height,
    durationMs: probe.durationMs,
    createdAt: serverTimestamp(),
  };

  await setDoc(mediaRef, media);
  return { id: mediaId, ...media, createdAt: new Date() };
}

/**
 * A user's library, newest first. The ordered query needs a composite index;
 * if it hasn't been deployed yet we fall back to an unordered read and sort
 * client-side rather than showing the user an error.
 */
export async function listMediaByUser(uid, { type = null, max = 60 } = {}) {
  if (!uid) return [];
  const filters = [where('ownerId', '==', uid)];
  if (type) filters.push(where('type', '==', type));

  const sortNewestFirst = (docs) =>
    docs.sort((a, b) => (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0));

  try {
    const snap = await getDocs(
      query(collection(db(), COLLECTION), ...filters, orderBy('createdAt', 'desc'), fsLimit(max)),
    );
    return snap.docs.map((d) => ({ id: d.id, ...d.data() }));
  } catch (err) {
    console.warn('[mediaLibrary] ordered query unavailable, sorting client-side:', err.message);
    const snap = await getDocs(query(collection(db(), COLLECTION), ...filters, fsLimit(max)));
    return sortNewestFirst(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
  }
}

export async function getMedia(id) {
  const snap = await getDoc(doc(db(), COLLECTION, id));
  return snap.exists() ? { id: snap.id, ...snap.data() } : null;
}

/** Remove a library item and the files behind it. */
export async function deleteMedia(media) {
  if (!media || !media.id) return;
  for (const path of [media.storagePath, media.thumbPath]) {
    if (!path) continue;
    try {
      await deleteObject(storageRef(store(), path));
    } catch (err) {
      // Already gone, or written before storagePath was recorded.
      console.warn('[mediaLibrary] could not delete file:', err.message);
    }
  }
  await deleteDoc(doc(db(), COLLECTION, media.id));
}

/** Compact shape stored on activity posts and sets. */
export const mediaRefOf = (m) => ({
  id: m.id,
  type: m.type,
  url: m.url,
  thumbUrl: m.thumbUrl || m.url,
  title: m.title || '',
});

export default {
  uploadMedia,
  listMediaByUser,
  getMedia,
  deleteMedia,
  validateMediaFile,
  mediaKindOf,
  mediaRefOf,
  MAX_CLIP_SECONDS,
};
