// src/components/premium/PremiumMembershipPage.jsx
import React, { useState, useEffect } from 'react';
import { getAuth } from 'firebase/auth';
import premiumStatusService from '../../services/PremiumStatusService';
import { useNavigate } from 'react-router-dom';
import { Shield, Check, Star, Crown, MessageCircle, Users, Headphones } from 'lucide-react';
import StripeBuyButton from './StripeBuyButton';
import './PremiumMembership.css';

// Simplified environment detection for display only
const getCurrentEnvironment = () => {
  const hostname = window.location.hostname;
  
  if (hostname.includes("localhost") || hostname.includes("127.0.0.1")) {
    return "Development";
  } else if (hostname.includes("ondigitalocean.app")) {
    return "Testing";
  } else {
    return "Production";
  }
};

const PremiumMembershipPage = () => {
  const [subscription, setSubscription] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [debugInfo, setDebugInfo] = useState({});
  const [showDebugPanel, setShowDebugPanel] = useState(false);
  const navigate = useNavigate();
  
  // Get the environment for display
  const [environment, setEnvironment] = useState(getCurrentEnvironment());

  // Premium plans with pricing details
  const premiumPlans = [
    { 
      id: 'plan_monthly', 
      name: 'Monthly', 
      displayPrice: '$9.99/month', 
      description: 'Full access to all premium features',
      priceInCents: 999,
      currency: 'usd',
      interval: 'month'
    },
    { 
      id: 'plan_yearly', 
      name: 'Yearly', 
      displayPrice: '$99.99/year', 
      description: 'Save $19.89 compared to monthly',
      priceInCents: 9999,
      currency: 'usd',
      interval: 'year'
    }
  ];

  const premiumFeatures = [
    {
      icon: <Crown className="feature-icon" />,
      title: 'Premium Badge',
      description: 'Show off your premium status with an exclusive badge'
    },
    {
      icon: <MessageCircle className="feature-icon" />,
      title: 'Priority Support',
      description: 'Get faster response times and priority customer support'
    },
    {
      icon: <Users className="feature-icon" />,
      title: 'Exclusive Communities',
      description: 'Access premium-only chat rooms and communities'
    },
    {
      icon: <Headphones className="feature-icon" />,
      title: 'Enhanced Audio Features',
      description: 'Advanced audio profiles and matching capabilities'
    },
    {
      icon: <Star className="feature-icon" />,
      title: 'Advanced Features',
      description: 'Early access to new features and enhanced functionality'
    }
  ];

  // Load subscription status when component mounts
  useEffect(() => {
    loadSubscriptionStatus();
  }, []);

  const loadSubscriptionStatus = async () => {
    try {
      setLoading(true);
      setError(null);
      
      const auth = getAuth();
      const user = auth.currentUser;
      
      // Add user info to debug
      setDebugInfo(prevInfo => ({
        ...prevInfo,
        user: user ? {
          uid: user.uid,
          email: user.email,
          isLoggedIn: true
        } : {
          isLoggedIn: false
        },
        environment: environment
      }));
      
      if (!user) {
        setError('You must be logged in to view membership status');
        setLoading(false);
        return;
      }
      
      // Check Firebase for premium status
      const firebaseStatus = await premiumStatusService.checkPremiumStatus(user.uid);
      console.log('Firebase premium status:', firebaseStatus);
      
      // If user has premium in Firebase, show that
      if (firebaseStatus.isPremium) {
        const subscriptionData = {
          status: 'active',
          plan: firebaseStatus.plan,
          isPremium: true,
          current_period_start: firebaseStatus.subscribedAt ? Math.floor(new Date(firebaseStatus.subscribedAt).getTime() / 1000) : null,
          current_period_end: firebaseStatus.expiresAt ? Math.floor(new Date(firebaseStatus.expiresAt).getTime() / 1000) : null
        };

        setSubscription(subscriptionData);
        
        setDebugInfo(prevInfo => ({
          ...prevInfo,
          firebaseStatus
        }));
      } else {
        // No premium subscription found
        setSubscription(null);
        setDebugInfo(prevInfo => ({
          ...prevInfo,
          firebaseStatus,
          message: 'No premium subscription found'
        }));
      }
    } catch (err) {
      console.error('Error loading subscription status:', err);
      setDebugInfo(prevInfo => ({
        ...prevInfo,
        statusError: {
          message: err.message,
          stack: err.stack
        }
      }));
      
      setError('Could not load subscription status. Please try again later.');
    } finally {
      setLoading(false);
    }
  };

  // Helper function to get environment color class
  const getEnvironmentColorClass = () => {
    switch (environment.toLowerCase()) {
      case 'development':
        return 'bg-blue-100 text-blue-800';
      case 'testing':
        return 'bg-yellow-100 text-yellow-800';
      case 'production':
        return 'bg-green-100 text-green-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  // Safe date handling to prevent toLocaleDateString errors
  const formatDate = (timestamp) => {
    if (!timestamp) return 'N/A';
    
    try {
      // Handle both timestamp and Date objects
      const date = typeof timestamp === 'number' ? new Date(timestamp * 1000) : new Date(timestamp);
      
      // Check if date is valid
      if (isNaN(date.getTime())) {
        return 'Invalid Date';
      }
      
      return date.toLocaleDateString();
    } catch (error) {
      console.error('Date formatting error:', error);
      return 'Invalid Date';
    }
  };

  // Handle successful payment
  const handlePaymentSuccess = async (paymentData) => {
    console.log('Payment successful:', paymentData);
    
    try {
      // Redirect to success page or refresh subscription status
      navigate('/subscription-success');
    } catch (error) {
      console.error('Error handling payment success:', error);
      alert('Payment successful! Please refresh the page to see your updated membership status.');
    }
  };

  // Handle payment cancellation
  const handlePaymentCancel = (cancelData) => {
    console.log('Payment cancelled:', cancelData);
    // You can show a message or handle cancellation as needed
  };

  const renderSubscriptionStatus = () => {
    if (!subscription) {
      return (
        <div className="text-center p-8 bg-gray-50 rounded-lg mb-8">
          <p className="text-gray-600">You don't have an active premium subscription.</p>
        </div>
      );
    }

    const startDate = subscription.current_period_start;
    const endDate = subscription.current_period_end;
    const planName = subscription.plan?.nickname || subscription.plan?.name || subscription.tier || 'Premium';
    const status = subscription.status || (subscription.isPremium ? 'active' : 'inactive');

    return (
      <div className="subscription-status-card mb-8">
        <div className="status-header">
          <Shield className="status-icon active" />
          <h2>Premium Membership Active</h2>
          <div className="status-badge active">✓ Premium Member</div>
        </div>
        
        <div className="subscription-details">
          <div className="detail-item">
            <span className="label">Plan:</span>
            <span className="value">{planName}</span>
          </div>
          <div className="detail-item">
            <span className="label">Status:</span>
            <span className="value">{status}</span>
          </div>
          {startDate && endDate && (
            <div className="detail-item">
              <span className="label">Current period:</span>
              <span className="value">{formatDate(startDate)} to {formatDate(endDate)}</span>
            </div>
          )}
          {subscription.cancel_at_period_end && (
            <p className="text-amber-600 mt-2">
              Your subscription will end at the current billing period.
            </p>
          )}
          {(subscription.isPremium || status === 'active') && (
            <p className="text-green-600 mt-2 font-semibold">
              ✓ Premium membership active
            </p>
          )}
        </div>
      </div>
    );
  };

  const renderPlanOptions = () => {
    if (subscription && !subscription.cancel_at_period_end) {
      return null; // Don't show plans if user is already subscribed
    }

    return (
      <div className="mt-8">
        <h2 className="text-2xl font-bold mb-6 text-center">Choose Your Premium Plan</h2>
        
        {/* Side by Side Pricing Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-w-6xl mx-auto mb-8">
          {/* Monthly Plan */}
          <div className="pricing-card bg-white border border-gray-200 rounded-lg p-6 shadow-sm hover:shadow-lg transition-shadow relative">
            <div className="pricing-header text-center mb-6">
              <h3 className="text-xl font-semibold text-gray-900 mb-2">Monthly</h3>
              <div className="price mb-2">
                <span className="text-3xl font-bold text-blue-600">$9.99</span>
                <span className="text-gray-500 text-lg">/month</span>
              </div>
              <p className="text-gray-600">Full access to all premium features</p>
            </div>
            
            <div className="pricing-features mb-6">
              <ul className="space-y-2">
                <li className="flex items-start">
                  <Check className="w-4 h-4 text-green-500 mt-1 mr-3 flex-shrink-0" />
                  <span className="text-sm text-gray-600">Unlimited premium features</span>
                </li>
                <li className="flex items-start">
                  <Check className="w-4 h-4 text-green-500 mt-1 mr-3 flex-shrink-0" />
                  <span className="text-sm text-gray-600">Priority customer support</span>
                </li>
                <li className="flex items-start">
                  <Check className="w-4 h-4 text-green-500 mt-1 mr-3 flex-shrink-0" />
                  <span className="text-sm text-gray-600">Cancel anytime</span>
                </li>
              </ul>
            </div>

            <div className="pricing-button">
              <StripeBuyButton
                planType="monthly"
                onSuccess={handlePaymentSuccess}
                onCancel={handlePaymentCancel}
                className="w-full"
              />
            </div>
          </div>
          
          {/* Yearly Plan */}
          <div className="pricing-card bg-blue-50 border border-blue-200 rounded-lg p-6 shadow-sm hover:shadow-lg transition-shadow relative">
            {/* Save Badge */}
            <div className="absolute -top-3 left-1/2 transform -translate-x-1/2">
              <span className="bg-blue-500 text-white px-3 py-1 rounded-full text-sm font-medium">
                Save $19.89

              </span>
            </div>
            
            <div className="pricing-header text-center mb-6" style={{ marginTop: '8px' }}>
              <h3 className="text-xl font-semibold text-gray-900 mb-2">Yearly</h3>
              <div className="price mb-2">
                <span className="text-3xl font-bold text-blue-600">$99.99</span>
                <span className="text-gray-500 text-lg">/year</span>
              </div>
              <p className="text-gray-600">Save $19.89 compared to monthly</p>
            </div>
            
            <div className="pricing-features mb-6">
              <ul className="space-y-2">
                <li className="flex items-start">
                  <Check className="w-4 h-4 text-green-500 mt-1 mr-3 flex-shrink-0" />
                  <span className="text-sm text-gray-600">Unlimited premium features</span>
                </li>
                <li className="flex items-start">
                  <Check className="w-4 h-4 text-green-500 mt-1 mr-3 flex-shrink-0" />
                  <span className="text-sm text-gray-600">Priority customer support</span>
                </li>
                <li className="flex items-start">
                  <Check className="w-4 h-4 text-green-500 mt-1 mr-3 flex-shrink-0" />
                  <span className="text-sm text-gray-600">2 months free</span>
                </li>
                <li className="flex items-start">
                  <Check className="w-4 h-4 text-green-500 mt-1 mr-3 flex-shrink-0" />
                  <span className="text-sm text-gray-600">Cancel anytime</span>
                </li>
              </ul>
            </div>

            <div className="pricing-button">
              <StripeBuyButton
                planType="yearly"
                onSuccess={handlePaymentSuccess}
                onCancel={handlePaymentCancel}
                className="w-full"
              />
            </div>
          </div>
        </div>
        
        <div className="text-center">
          <p className="text-sm text-gray-500">
            🔒 Secure payment processing • Cancel anytime
          </p>
        </div>
      </div>
    );
  };

  // Debug panel (only show in development)
  const renderDebugPanel = () => {
    if (!showDebugPanel || environment !== 'Development') return null;
    
    return (
      <div className="mt-8 border border-gray-300 rounded-lg p-4 bg-gray-50">
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-lg font-bold">Developer Information</h3>
          <button 
            className="px-3 py-1 bg-gray-200 hover:bg-gray-300 rounded text-sm transition-colors"
            onClick={() => setShowDebugPanel(false)}
          >
            Hide Debug
          </button>
        </div>
        
        <div className="mb-4 p-3 bg-blue-50 text-blue-800 rounded">
          <div className="font-medium">Environment: {environment}</div>
        </div>
        
        <div className="bg-white p-4 rounded border overflow-auto max-h-96 font-mono text-sm">
          <pre>{JSON.stringify(debugInfo, null, 2)}</pre>
        </div>
        
        <div className="mt-4 flex space-x-4">
          <button 
            className="px-3 py-1 bg-blue-100 hover:bg-blue-200 text-blue-800 rounded transition-colors"
            onClick={loadSubscriptionStatus}
          >
            Refresh Status
          </button>
        </div>
      </div>
    );
  };

  if (loading) {
    return (
      <div className="premium-membership-page loading">
        <div className="flex justify-center items-center h-64">
          <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-blue-500 mr-3"></div>
          <p className="text-gray-600">Loading subscription status...</p>
        </div>
      </div>
    );
  }

  // If user already has active subscription
  if (subscription && (subscription.isPremium || subscription.status === 'active')) {
    return (
      <div className="premium-membership-page active-subscription">
        <div className="max-w-4xl mx-auto p-6">
          <div className="mb-6 flex items-center justify-between">
            {/* Only show environment badge in development/testing */}
            {environment !== 'Production' && (
              <div className={`inline-block px-3 py-1 rounded-full text-sm font-semibold ${getEnvironmentColorClass()}`}>
                {environment.toUpperCase()} ENVIRONMENT
              </div>
            )}
            {environment === 'Development' && (
              <button 
                onClick={() => setShowDebugPanel(!showDebugPanel)}
                className="px-3 py-1 bg-gray-100 hover:bg-gray-200 rounded text-sm transition-colors"
              >
                {showDebugPanel ? 'Hide Debug' : 'Show Debug'}
              </button>
            )}
          </div>

          {renderSubscriptionStatus()}

          <div className="active-features">
            <h3 className="text-xl font-bold mb-6">Your Premium Features</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {premiumFeatures.map((feature, index) => (
                <div key={index} className="feature-card bg-white border border-green-200 rounded-lg p-6 shadow-sm">
                  <div className="flex items-center justify-center w-12 h-12 bg-green-100 rounded-lg mb-4">
                    {feature.icon}
                  </div>
                  <h4 className="font-semibold text-gray-900 mb-2">{feature.title}</h4>
                  <p className="text-gray-600 text-sm mb-4">{feature.description}</p>
                  <div className="flex items-center text-green-600">
                    <Check className="w-4 h-4 mr-2" />
                    <span className="text-sm font-medium">Active</span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="mt-8 flex justify-center space-x-4">
            <button 
              onClick={() => navigate('/settings')} 
              className="px-6 py-3 bg-gray-100 hover:bg-gray-200 text-gray-700 font-semibold rounded-lg transition-colors"
            >
              Manage Account
            </button>
            <button 
              onClick={() => navigate('/')} 
              className="px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-lg transition-colors"
            >
              Continue Using App
            </button>
          </div>

          {renderDebugPanel()}
        </div>
      </div>
    );
  }

  // Premium membership purchase page
  return (
    <div className="premium-membership-page">
      <div className="max-w-6xl mx-auto p-6">
        <div className="mb-6 flex items-center justify-between">
          {/* Only show environment badge in development/testing */}
          {environment !== 'Production' && (
            <div className={`inline-block px-3 py-1 rounded-full text-sm font-semibold ${getEnvironmentColorClass()}`}>
              {environment.toUpperCase()} ENVIRONMENT
            </div>
          )}
          {environment === 'Development' && (
            <button 
              onClick={() => setShowDebugPanel(!showDebugPanel)}
              className="px-3 py-1 bg-gray-100 hover:bg-gray-200 rounded text-sm transition-colors"
            >
              {showDebugPanel ? 'Hide Debug' : 'Show Debug'}
            </button>
          )}
        </div>

        {error && (
          <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-6">
            {error}
          </div>
        )}

        {/* Hero Section */}
        <div className="text-center mb-12">
          <Crown className="w-16 h-16 mx-auto text-blue-600 mb-4" />
          <h1 className="text-4xl font-bold text-gray-900 mb-4">Upgrade to Premium</h1>
          <p className="text-xl text-gray-600 max-w-2xl mx-auto">
            Unlock exclusive features and enhance your experience with our premium membership
          </p>
        </div>

        {/* Features Section */}
        <div className="mb-12">
          <h2 className="text-2xl font-bold text-center mb-8">Premium Features</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {premiumFeatures.map((feature, index) => (
              <div key={index} className="feature-card bg-white border border-gray-200 rounded-lg p-6 shadow-sm hover:shadow-lg transition-shadow">
                <div className="flex items-center justify-center w-12 h-12 bg-blue-100 rounded-lg mb-4">
                  {feature.icon}
                </div>
                <h3 className="font-semibold text-gray-900 mb-2">{feature.title}</h3>
                <p className="text-gray-600 text-sm">{feature.description}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Pricing Section - Shows both plans side by side */}
        {renderPlanOptions()}

        {/* FAQ Section */}
        <div className="mt-12">
          <h2 className="text-2xl font-bold text-center mb-8">Frequently Asked Questions</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="faq-item bg-white border border-gray-200 rounded-lg p-6">
              <h4 className="font-semibold text-gray-900 mb-3">What happens after I subscribe?</h4>
              <p className="text-gray-600 text-sm">
                Your premium features will be activated immediately after successful payment. 
                You'll see a premium badge on your profile and gain access to all exclusive features.
              </p>
            </div>
            <div className="faq-item bg-white border border-gray-200 rounded-lg p-6">
              <h4 className="font-semibold text-gray-900 mb-3">Can I cancel anytime?</h4>
              <p className="text-gray-600 text-sm">
                Yes, you can cancel your subscription at any time. You'll continue to have 
                premium access until the end of your current billing period.
              </p>
            </div>
            <div className="faq-item bg-white border border-gray-200 rounded-lg p-6">
              <h4 className="font-semibold text-gray-900 mb-3">Is my payment secure?</h4>
              <p className="text-gray-600 text-sm">
                Absolutely! All payments are processed securely through Stripe, 
                a trusted payment processor used by millions of businesses worldwide.
              </p>
            </div>
          </div>
        </div>

        {renderDebugPanel()}
      </div>
    </div>
  );
};

export default PremiumMembershipPage;