// LiveKit Token Generation Service
// Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\services\livekit\LiveKitTokenService.js
//
// Tokens are now minted SERVER-SIDE by the `generateLiveKitToken` Cloud
// Function (see src/services/livekit/liveKitTokenClient.js). The LiveKit API
// secret no longer lives in the browser. Only the public server URL
// (VITE_LIVEKIT_SERVER_URL) is read client-side, for connecting to the room.

import { requestLiveKitToken } from './liveKitTokenClient.js';

class LiveKitTokenService {
  constructor() {
    // Public, safe to expose. Signing credentials live only on the server.
    this.serverUrl = import.meta.env.VITE_LIVEKIT_SERVER_URL;
  }

  // Request a LiveKit access token. Signing happens server-side in the
  // `generateLiveKitToken` Cloud Function; this just forwards the request and
  // returns the same shape the old client-side signer produced:
  //   { token, serverUrl, roomName, participantName, expiresAt, grants }
  async generateAccessToken(roomName, participantName, options = {}) {
    try {
      return await requestLiveKitToken(roomName, participantName, options);
    } catch (error) {
      console.error('❌ Failed to obtain LiveKit token from server:', error);
      throw error;
    }
  }

  // Whether tokens can be obtained. The API key/secret live on the server, so
  // from the client's perspective it's "configured" as long as we know the
  // public server URL to connect to. If the server is actually missing
  // credentials, the Cloud Function returns a clear failed-precondition error.
  isConfigured() {
    return !!this.serverUrl;
  }

  // Get configuration status. hasApiKey/hasApiSecret are reported true because
  // signing is handled server-side (callers use these flags only to decide
  // whether a token can be requested at all).
  getConfigStatus() {
    return {
      hasApiKey: true,
      hasApiSecret: true,
      hasServerUrl: !!this.serverUrl,
      serverUrl: this.serverUrl,
      minting: 'server',
      isConfigured: this.isConfigured()
    };
  }

  // Generate token for room viewer (read-only)
  async generateViewerToken(roomName, participantName = 'Viewer') {
    return this.generateAccessToken(roomName, participantName, {
      canPublish: false,
      canSubscribe: true,
      canPublishData: false,
      canPublishSources: [],
      metadata: JSON.stringify({ role: 'viewer' })
    });
  }

  // Generate token for room publisher
  async generatePublisherToken(roomName, participantName, options = {}) {
    return this.generateAccessToken(roomName, participantName, {
      canPublish: true,
      canSubscribe: true,
      canPublishData: true,
      canPublishSources: ['camera', 'microphone', 'screen_share'],
      metadata: JSON.stringify({ role: 'publisher', ...options.metadata }),
      ...options
    });
  }

  // Generate token for event creator (with isArtistFeed metadata for recording)
  async generateCreatorToken(roomName, participantName, eventId, options = {}) {
    return this.generateAccessToken(roomName, participantName, {
      canPublish: true,
      canSubscribe: true,
      canPublishData: true,
      canPublishSources: ['camera', 'microphone', 'screen_share'],
      metadata: JSON.stringify({
        role: 'creator',
        isCreator: true,
        isArtistFeed: true,
        eventId: eventId,
        ...options.metadata
      }),
      ...options
    });
  }

  // Generate token for moderator (full permissions)
  async generateModeratorToken(roomName, participantName, options = {}) {
    return this.generateAccessToken(roomName, participantName, {
      canPublish: true,
      canSubscribe: true,
      canPublishData: true,
      canUpdateOwnMetadata: true,
      canPublishSources: ['camera', 'microphone', 'screen_share'],
      metadata: JSON.stringify({ role: 'moderator', ...options.metadata }),
      ...options
    });
  }

  // Test token generation (for debugging)
  async testTokenGeneration() {
    console.group('🧪 Testing LiveKit Token Generation');
    
    try {
      const testRoomName = `test-room-${Date.now()}`;
      const testParticipantName = 'TestUser';
      
      console.log('🔧 Configuration status:', this.getConfigStatus());
      
      if (!this.isConfigured()) {
        console.error('❌ Configuration incomplete - cannot test token generation');
        console.groupEnd();
        return false;
      }
      
      const tokenData = await this.generatePublisherToken(testRoomName, testParticipantName);
      
      console.log('✅ Test token generated successfully');
      console.log('📊 Token data:', {
        roomName: tokenData.roomName,
        participantName: tokenData.participantName,
        tokenLength: tokenData.token.length,
        expiresAt: new Date(tokenData.expiresAt).toISOString(),
        grants: tokenData.grants
      });
      
      console.groupEnd();
      return true;
      
    } catch (error) {
      console.error('❌ Token generation test failed:', error);
      console.groupEnd();
      return false;
    }
  }
}

// Export singleton instance
export const liveKitTokenService = new LiveKitTokenService();
export default liveKitTokenService;

// Make available globally for debugging
if (typeof window !== 'undefined') {
  window.liveKitTokenService = liveKitTokenService;
}