// EPA AirNow API client — current national air quality snapshot.
//
// Endpoint: https://www.airnowapi.org/aq/observation/zipCode/current/
// Auth: requires a free API key (set in ApiSettings).
// CORS: AirNow ships CORS headers — direct fetch works, no proxy needed.
//
// AirNow has no true "national" endpoint, so we aggregate a geographically
// diverse set of anchor metro zips and report the average of their
// worst-pollutant AQI readings. Explicitly label the panel so readers
// know it's an aggregate and not a true national index.

import apiKeyService from '../apiKeyService'

// Five large metros spread across regions. Chosen purely to spread
// geography, not to be statistically representative.
const ANCHOR_ZIPS = [
  { zip: '10001', name: 'NYC' },
  { zip: '60601', name: 'Chicago' },
  { zip: '90001', name: 'Los Angeles' },
  { zip: '77001', name: 'Houston' },
  { zip: '85001', name: 'Phoenix' },
]

function aqiCategory(aqi) {
  if (aqi <= 50) return 'Good'
  if (aqi <= 100) return 'Moderate'
  if (aqi <= 150) return 'Unhealthy for sensitive'
  if (aqi <= 200) return 'Unhealthy'
  if (aqi <= 300) return 'Very unhealthy'
  return 'Hazardous'
}

async function fetchZipMaxAQI(zip, key) {
  const url = `https://www.airnowapi.org/aq/observation/zipCode/current/` +
    `?format=application/json&zipCode=${zip}&distance=25&API_KEY=${encodeURIComponent(key)}`
  try {
    const res = await fetch(url, { signal: AbortSignal.timeout(10000) })
    if (!res.ok) return null
    const data = await res.json()
    if (!Array.isArray(data) || data.length === 0) return null
    // A given zip returns one observation per pollutant (Ozone, PM2.5, PM10).
    // The reported AQI is the max across pollutants.
    return data.reduce((max, obs) => Math.max(max, obs.AQI || 0), 0)
  } catch {
    return null
  }
}

const epaService = {
  async fetchNationalAQI() {
    const key = apiKeyService.getEpaApiKey()
    if (!key) return { signals: [], error: 'No EPA AirNow key configured' }

    const results = await Promise.all(
      ANCHOR_ZIPS.map(m => fetchZipMaxAQI(m.zip, key))
    )
    const valid = results.filter(v => typeof v === 'number')
    if (valid.length === 0) {
      return { signals: [], error: 'AirNow returned no AQI data for any anchor zip' }
    }

    const avgAqi = Math.round(valid.reduce((a, b) => a + b, 0) / valid.length)
    const category = aqiCategory(avgAqi)

    const signal = {
      id: 'epa.national_avg_aqi',
      tag: 'environment.aqi.national',
      category: 'climate',
      label: `US Avg AQI (${valid.length}-metro)`,
      value: avgAqi,
      unit: '',
      trend: 'stable', // no prior period cached yet — phase 3 adds trend tracking
      delta: null,
      deltaLabel: category,
      period: new Date().toISOString().slice(0, 10),
      asOf: new Date().toISOString(),
      source: 'EPA AirNow',
      sourceUrl: 'https://www.airnow.gov/',
      reliability: 0.90,
      sentimentHint: avgAqi > 100 ? 'negative' : 'neutral',
    }
    return { signals: [signal], error: null }
  },
}

export default epaService
