import React, { useEffect, useRef, useState } from 'react';
import { ADROLL_CONFIG } from '../../config/adroll';

const VideoAdContainer = ({ isVisible, onAdComplete, adType = 'video' }) => {
  const containerRef = useRef(null);
  const [adLoaded, setAdLoaded] = useState(false);
  const [adError, setAdError] = useState(false);
  
  useEffect(() => {
    if (isVisible && containerRef.current && !adLoaded) {
      // Create AdRoll ad unit
      const adUnit = document.createElement('div');
      adUnit.id = ADROLL_CONFIG.videoAd.containerId + '-unit';
      adUnit.className = 'adroll-ad-unit';
      
      // Add AdRoll ad script
      const script = document.createElement('script');
      script.type = 'text/javascript';
      script.async = true;
      
      if (adType === 'video') {
        script.src = `https://s.adroll.com/j/${window.adroll_adv_id}/ad.js?ad_type=video&width=${ADROLL_CONFIG.videoAd.width}&height=${ADROLL_CONFIG.videoAd.height}`;
      } else {
        script.src = `https://s.adroll.com/j/${window.adroll_adv_id}/ad.js?ad_type=text&width=${ADROLL_CONFIG.textAd.width}&height=${ADROLL_CONFIG.textAd.height}`;
      }
      
      script.onload = () => {
        setAdLoaded(true);
        // Auto-dismiss after configured duration
        if (onAdComplete) {
          setTimeout(() => {
            onAdComplete();
          }, ADROLL_CONFIG.adDisplayDuration);
        }
      };
      
      script.onerror = () => {
        setAdError(true);
        console.error('Failed to load AdRoll ad');
        if (onAdComplete) {
          onAdComplete();
        }
      };
      
      containerRef.current.appendChild(adUnit);
      adUnit.appendChild(script);
    }
    
    return () => {
      // Cleanup
      if (containerRef.current) {
        containerRef.current.innerHTML = '';
      }
    };
  }, [isVisible, adLoaded, onAdComplete, adType]);
  
  if (!isVisible) return null;
  
  const styles = adType === 'video' ? {
    position: 'fixed',
    top: '70px', // Below the navigation bar
    right: ADROLL_CONFIG.videoAd.marginRight,
    width: `${ADROLL_CONFIG.videoAd.width}px`,
    height: `${ADROLL_CONFIG.videoAd.height}px`,
    zIndex: ADROLL_CONFIG.videoAd.zIndex,
    backgroundColor: '#f0f0f0',
    border: '1px solid #ddd',
    borderRadius: '8px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
    overflow: 'hidden'
  } : {
    position: 'fixed',
    bottom: '20px',
    left: '50%',
    transform: 'translateX(-50%)',
    width: `${ADROLL_CONFIG.textAd.width}px`,
    height: `${ADROLL_CONFIG.textAd.height}px`,
    zIndex: ADROLL_CONFIG.videoAd.zIndex,
    backgroundColor: '#f0f0f0',
    border: '1px solid #ddd',
    borderRadius: '4px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
    overflow: 'hidden'
  };
  
  return (
    <div 
      ref={containerRef}
      id={ADROLL_CONFIG.videoAd.containerId}
      style={styles}
      className="adroll-video-container"
    >
      {!adLoaded && !adError && (
        <div style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          height: '100%',
          color: '#666'
        }}>
          Loading ad...
        </div>
      )}
      {adError && (
        <div style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          height: '100%',
          color: '#999',
          fontSize: '14px'
        }}>
          Ad unavailable
        </div>
      )}
    </div>
  );
};

export default VideoAdContainer;