import { Link } from 'react-router-dom'
import { Zap, Clock, Target } from 'lucide-react'
import Card from '../common/Card'
import Badge from '../common/Badge'
import ConfidenceBar from '../common/ConfidenceBar'
import TrendIndicator from '../common/TrendIndicator'
import TrendSparkline from '../charts/TrendSparkline'
import { useCountdown } from '../../hooks/useCountdown'
import { getConfidenceColor, getConfidenceLabel } from '../../utils/weights'
import DataMask from '../../../components/premium/DataMask'

function HeroCard({ prediction, label, icon: Icon }) {
  const { label: timeLeft } = useCountdown(prediction.deadline)
  const top = prediction.outcomes[0]
  const { text } = getConfidenceColor(top.probability)

  return (
    <Link to={`/predict/${prediction.id}`}>
      <Card className="p-5 h-full hover:scale-[1.02] transition-transform duration-200 animate-pulse-glow">
        <div className="flex items-center justify-between mb-3">
          <span className="flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-wider text-gray-500">
            <Icon size={12} className="text-blue-400" />
            {label}
          </span>
          <Badge category={prediction.category} />
        </div>

        <h3 className="font-semibold text-gray-100 leading-snug line-clamp-2 mb-3">
          {prediction.title}
        </h3>

        <div className="flex items-end justify-between gap-4">
          <div className="flex-1">
            <div className="flex items-baseline gap-2 mb-1">
              {/* Hero probability is the most-actionable single number on
                  the page — consistent with the rest of /predict, gate
                  it to Data tier for signed-in free users; anonymous
                  visitors see the real value. upgradeLink=false here
                  because the parent <Link> already wraps the card. */}
              <span className={`font-mono text-2xl font-bold ${text}`}>
                <DataMask minTier="data" mode="blur" inline upgradeLink={false} allowAnonymous>
                  {top.probability}%
                </DataMask>
              </span>
              <TrendIndicator trend={top.trend} showLabel />
            </div>
            <p className="text-xs text-gray-500">{top.label}</p>
            <ConfidenceBar value={top.probability} size="sm" showLabel={false} />
            <p className="text-xs text-gray-600 mt-2 flex items-center gap-1">
              <Clock size={10} /> {timeLeft}
            </p>
          </div>
          <div style={{ width: 96, height: 48, minWidth: 96 }}>
            <TrendSparkline data={prediction.trendData} trend={top.trend} />
          </div>
        </div>
      </Card>
    </Link>
  )
}

export default function PredictionHero({ predictions }) {
  const active = predictions.filter(p => p.status === 'active')
  if (active.length === 0) return null

  const byConf = [...active].sort((a, b) => b.outcomes[0].probability - a.outcomes[0].probability)
  const byTrend = [...active].filter(p => p.outcomes[0].trend === 'up').sort((a, b) => {
    const aChange = (a.trendData?.at(-1) || 0) - (a.trendData?.[0] || 0)
    const bChange = (b.trendData?.at(-1) || 0) - (b.trendData?.[0] || 0)
    return bChange - aChange
  })
  const byDeadline = [...active].sort((a, b) => new Date(a.deadline) - new Date(b.deadline))

  const picks = [
    { prediction: byConf[0], label: 'Highest Confidence', icon: Target },
    { prediction: byTrend[0] || byConf[1], label: 'Most Trending', icon: Zap },
    { prediction: byDeadline[0], label: 'Soonest Deadline', icon: Clock },
  ]

  const unique = []
  const seen = new Set()
  for (const f of picks) {
    if (f.prediction && !seen.has(f.prediction.id)) {
      seen.add(f.prediction.id)
      unique.push(f)
    }
  }
  // Backfill if duplicates removed
  for (const p of byConf) {
    if (unique.length >= 3) break
    if (!seen.has(p.id)) {
      seen.add(p.id)
      unique.push({ prediction: p, label: 'Featured', icon: Target })
    }
  }

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
      {unique.map(f => (
        <HeroCard key={f.prediction.id} {...f} />
      ))}
    </div>
  )
}
