import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDJMixer } from '../../contexts/DJMixerContext';
import WaveformVisualizer from './WaveformVisualizer';
import { detectBPM } from '../../utils/bpmDetector';
import { RTMPStreamer, AudioRecorder, StreamConfig } from '../../utils/rtmpStreamer';
import {
  Play,
  Pause,
  Square,
  Volume2,
  VolumeX,
  Headphones,
  Radio,
  Upload,
  FolderOpen,
  SkipBack,
  SkipForward,
  RotateCcw,
  Settings,
  Disc, // Using Disc instead of Record - more appropriate for DJ context
  Mic,
  Music,
  Shuffle,
  Repeat,
  Download,
  ExternalLink,
  Wifi,
  WifiOff,
  ChevronLeft,
  ChevronRight
} from 'lucide-react';

// How each AudioContext state reads on the mixer status bar. 'none' is the
// state before an AudioContext exists at all, which is not the same thing as a
// context that exists but is suspended.
const AUDIO_STATUS = {
  running: { label: 'ON', tone: 'ok' },
  suspended: { label: 'IDLE', tone: 'warn' },
  interrupted: { label: 'IDLE', tone: 'warn' },
  closed: { label: 'OFF', tone: 'off' },
  none: { label: 'OFF', tone: 'off' }
};

// Default per-deck state. Used for a fresh deck and to seed from a persisted
// snapshot when the mixer remounts after navigation.
const makeDefaultDeck = () => ({
  track: null,
  isPlaying: false,
  isLoading: false,
  volume: 80,
  gain: 0, // 0 dB = unity gain
  eqHigh: 0,
  eqMid: 0,
  eqLow: 0,
  bpm: null,
  position: 0,
  duration: 0,
  cuePoint: 0,
  pitchBend: 0,
  tempoSlider: 0,
  keyLock: false,
  sync: false,
  loop: null,
  hotCues: [],
  effectsRack: {
    reverb: 0,
    delay: 0,
    filter: 0,
    flanger: 0
  }
});

const DJStudioMixerEnhanced = ({
  artistProfile,
  currentEvent,
  isStreaming,
  integrationMode = false,
  settings = {},
  onEvent = () => {},
  onStatsUpdate = () => {},
  streamingService,
  onAudioStreamReady = null, // NEW: Callback when DJ audio stream is ready
  className = ""
}) => {
  const { currentUser } = useAuth();

  // Use persistent DJ mixer context
  const djMixer = useDJMixer();

  // Core state
  const [isRecording, setIsRecording] = useState(false);
  const [cueVolume, setCueVolume] = useState(70);
  // 'none' until an AudioContext actually exists - starting at 'suspended'
  // made the status bar claim a suspended context before one was created.
  const [audioContextState, setAudioContextState] = useState('none');

  const audioStatus = AUDIO_STATUS[audioContextState] || {
    label: String(audioContextState).toUpperCase(),
    tone: 'warn'
  };

  // Use streaming state from parent (isStreaming prop) instead of internal RTMP streaming
  const isStreamingDJ = !!isStreaming; // Show streaming indicator when parent is streaming

  // Use persistent state from context
  const masterVolume = djMixer.masterVolume;
  const setMasterVolume = djMixer.setMasterVolume;
  const crossfaderPosition = djMixer.crossfaderPosition;
  const setCrossfaderPosition = djMixer.setCrossfaderPosition;

  // Deck state with enhanced features.
  // Seed from the persistent context snapshot so a loaded/playing deck is
  // restored when the mixer remounts after navigation (falls back to a fresh
  // deck on first mount).
  const [deckA, setDeckA] = useState(() => djMixer.deckAState || makeDefaultDeck());
  const [deckB, setDeckB] = useState(() => djMixer.deckBState || makeDefaultDeck());

  // Library and UI state - use persistent library from context
  const library = djMixer.library;
  const setLibrary = djMixer.setLibrary;
  const [searchQuery, setSearchQuery] = useState('');
  const [showLibrary, setShowLibrary] = useState(true);
  const [showSettings, setShowSettings] = useState(false);
  const [selectedTrack, setSelectedTrack] = useState(null);
  const [draggedTrack, setDraggedTrack] = useState(null);
  const [viewMode, setViewMode] = useState('mix'); // 'mix', 'library', 'effects'

  // Audio processing refs - use persistent refs from context
  const audioContextRef = djMixer.audioContextRef;
  const masterNodesRef = djMixer.masterNodesRef;
  const deckANodesRef = djMixer.deckANodesRef;
  const deckBNodesRef = djMixer.deckBNodesRef;
  const mediaStreamDestinationRef = djMixer.mediaStreamDestinationRef;

  // Playback source + start-time refs come from the persistent context so a
  // playing deck survives navigation (the mixer re-attaches to the still-playing
  // source on remount instead of orphaning it).
  const deckASourceRef = djMixer.deckASourceRef;
  const deckBSourceRef = djMixer.deckBSourceRef;
  const deckAStartTimeRef = djMixer.deckAStartTimeRef;
  const deckBStartTimeRef = djMixer.deckBStartTimeRef;
  // Local refs (recomputed on mount)
  const analyserARef = useRef(null);
  const analyserBRef = useRef(null);
  const positionUpdateIntervalRef = useRef(null);
  

  // Streaming and recording refs
  const rtmpStreamerRef = useRef(null);
  const audioRecorderRef = useRef(null);
  const streamConfigRef = useRef(null);
  const liveKitAudioTrackRef = useRef(null);

  // File input refs
  const fileInputRef = useRef(null);

  // Animation refs
  const animationFrameRef = useRef(null);

  // State refs for accessing latest state in callbacks
  const deckARef = useRef(deckA);
  const deckBRef = useRef(deckB);

  // Update refs when state changes
  useEffect(() => {
    deckARef.current = deckA;
  }, [deckA]);

  useEffect(() => {
    deckBRef.current = deckB;
  }, [deckB]);

  // Initialize audio context and setup - now handled by context, just resume if needed
  useEffect(() => {
    const initAudio = async () => {
      // Resume audio context if suspended (handled by persistent context)
      await djMixer.resumeAudioContext();

      // Initialize streaming and recording services
      rtmpStreamerRef.current = new RTMPStreamer(audioContextRef.current);
      audioRecorderRef.current = new AudioRecorder(audioContextRef.current);
      streamConfigRef.current = new StreamConfig();

      // Notify parent that audio stream is ready
      if (onAudioStreamReady && mediaStreamDestinationRef.current) {
        const audioStream = mediaStreamDestinationRef.current.stream;
        console.log('🎛️ DJ audio stream ready for LiveKit integration:', audioStream);
        onAudioStreamReady(audioStream);
      }

      console.log('✅ DJ Studio initialized with persistent context');
    };

    initAudio();

    return () => {
      // Don't cleanup audio context on unmount - it's persistent!
      // Snapshot the current deck state into the persistent context so the
      // loaded tracks / playback position are restored when the mixer remounts
      // after navigation. deckARef/deckBRef hold the latest committed state.
      try {
        djMixer.setDeckAState(deckARef.current);
        djMixer.setDeckBState(deckBRef.current);
      } catch (e) {
        console.warn('Could not persist deck state on unmount:', e);
      }
      console.log('🎛️ DJ Studio component unmounting - deck state persisted');
    };
  }, []);

  // Keep the status bar in sync with the real audio context and recorder.
  // Both can change without going through a React setter (the browser suspends
  // a context on its own, and MediaRecorder can stop when its stream ends), so
  // the indicators are polled from the source of truth rather than assumed.
  const checkStatusRef = useRef(() => {});
  useEffect(() => {
    const checkAudioContextState = () => {
      const state = audioContextRef.current ? audioContextRef.current.state : 'none';
      setAudioContextState(prev => (prev === state ? prev : state));
      if (state === 'suspended') {
        console.warn('AudioContext is suspended! User interaction required.');
      }

      // MediaRecorder.state flips synchronously on start()/stop(), while the
      // recorder's own isRecording flag only updates in its async onstart
      // handler - reading the flag here would blink the light off right after
      // recording starts.
      const recorder = audioRecorderRef.current;
      const mediaRecorder = recorder?.mediaRecorder;
      const recording = mediaRecorder
        ? mediaRecorder.state !== 'inactive'
        : !!recorder?.isRecording;
      setIsRecording(prev => (prev === recording ? prev : recording));
    };
    checkStatusRef.current = checkAudioContextState;

    // Check immediately and then periodically
    checkAudioContextState();
    const interval = setInterval(checkAudioContextState, 1000);

    // Also check on state change events if supported
    if (audioContextRef.current) {
      audioContextRef.current.addEventListener('statechange', checkAudioContextState);
    }

    return () => {
      clearInterval(interval);
      if (audioContextRef.current) {
        audioContextRef.current.removeEventListener('statechange', checkAudioContextState);
      }
    };
  }, []);

  // Update master volume
  useEffect(() => {
    if (masterNodesRef.current.gain && audioContextRef.current) {
      const currentTime = audioContextRef.current.currentTime;
      const transitionTime = 0.05; // 50ms smooth transition
      masterNodesRef.current.gain.gain.linearRampToValueAtTime(masterVolume / 100, currentTime + transitionTime);
      console.log('Master volume updated to:', masterVolume);
    }
  }, [masterVolume]);

  // Update deck volumes and crossfader
  useEffect(() => {
    if (!deckANodesRef.current.gain || !deckBNodesRef.current.gain || !audioContextRef.current) return;
    
    // Calculate crossfader gains
    const crossfaderValue = crossfaderPosition / 100;
    const deckAGain = Math.cos(crossfaderValue * Math.PI / 2);
    const deckBGain = Math.sin(crossfaderValue * Math.PI / 2);
    
    // Apply deck volumes with crossfader and gain adjustment
    // Include both volume and gain controls in the calculation
    const deckAFinalGain = (deckA.volume / 100) * deckAGain * Math.pow(10, deckA.gain / 20); // Convert dB to linear
    const deckBFinalGain = (deckB.volume / 100) * deckBGain * Math.pow(10, deckB.gain / 20); // Convert dB to linear
    
    // Use smooth transitions to prevent audio interruptions
    const currentTime = audioContextRef.current.currentTime;
    const transitionTime = 0.05; // 50ms smooth transition
    
    deckANodesRef.current.gain.gain.linearRampToValueAtTime(deckAFinalGain, currentTime + transitionTime);
    deckBNodesRef.current.gain.gain.linearRampToValueAtTime(deckBFinalGain, currentTime + transitionTime);
    
    console.log('Deck volumes updated - A:', deckA.volume, 'B:', deckB.volume, 'Crossfader:', crossfaderPosition);
  }, [deckA.volume, deckB.volume, deckA.gain, deckB.gain, crossfaderPosition]);

  // Update playback positions
  useEffect(() => {
    if (positionUpdateIntervalRef.current) {
      clearInterval(positionUpdateIntervalRef.current);
    }
    
    // Only set up interval if at least one deck is playing
    if (deckA.isPlaying || deckB.isPlaying) {
      positionUpdateIntervalRef.current = setInterval(() => {
        if (audioContextRef.current) {
          const currentTime = audioContextRef.current.currentTime;
          
          // Update deck A position
          if (deckA.isPlaying && deckAStartTimeRef.current !== null) {
            const newPosition = currentTime - deckAStartTimeRef.current;
            if (newPosition <= deckA.duration) {
              setDeckA(prev => ({ ...prev, position: newPosition }));
            } else {
              // Track ended
              setDeckA(prev => ({ ...prev, isPlaying: false, position: 0 }));
              deckAStartTimeRef.current = null;
            }
          }
          
          // Update deck B position
          if (deckB.isPlaying && deckBStartTimeRef.current !== null) {
            const newPosition = currentTime - deckBStartTimeRef.current;
            if (newPosition <= deckB.duration) {
              setDeckB(prev => ({ ...prev, position: newPosition }));
            } else {
              // Track ended
              setDeckB(prev => ({ ...prev, isPlaying: false, position: 0 }));
              deckBStartTimeRef.current = null;
            }
          }
        }
      }, 50); // Update every 50ms for smooth progress
    }
    
    return () => {
      if (positionUpdateIntervalRef.current) {
        clearInterval(positionUpdateIntervalRef.current);
      }
    };
  }, [deckA.isPlaying, deckB.isPlaying, deckA.duration, deckB.duration]);

  // Audio system initialization is now handled by DJMixerContext
  // Analysers are set up on first use
  useEffect(() => {
    if (deckANodesRef.current.analyser) {
      analyserARef.current = deckANodesRef.current.analyser;
    }
    if (deckBNodesRef.current.analyser) {
      analyserBRef.current = deckBNodesRef.current.analyser;
    }
  }, []);

  // Enhanced BPM detection with better accuracy
  const detectTrackBPM = async (audioBuffer) => {
    try {
      const bpm = await detectBPM(audioBuffer, audioContextRef.current);
      return bpm;
    } catch (error) {
      console.error('BPM detection failed:', error);
      return null;
    }
  };

  // Load track with enhanced audio processing
  const loadTrackToDeck = async (track, deck) => {
    try {
      console.log(`Loading track to deck ${deck}:`, track.name, track.url);
      const response = await fetch(track.url);
      if (!response.ok) {
        throw new Error(`Failed to fetch track: ${response.status} ${response.statusText}`);
      }
      const arrayBuffer = await response.arrayBuffer();
      console.log(`Fetched ${arrayBuffer.byteLength} bytes, decoding audio...`);
      const audioBuffer = await audioContextRef.current.decodeAudioData(arrayBuffer);

      // Detect BPM with enhanced algorithm
      const bpm = await detectTrackBPM(audioBuffer);

      // Analyze track for additional metadata
      const trackData = {
        ...track,
        audioBuffer,
        bpm: bpm || 'Unknown',
        duration: audioBuffer.duration,
        key: null, // TODO: Implement key detection
        energy: calculateTrackEnergy(audioBuffer),
        peaks: findTrackPeaks(audioBuffer)
      };

      if (deck === 'A') {
        setDeckA(prev => ({
          ...prev,
          track: trackData,
          bpm,
          duration: audioBuffer.duration,
          position: 0,
          cuePoint: 0
        }));
      } else {
        setDeckB(prev => ({
          ...prev,
          track: trackData,
          bpm,
          duration: audioBuffer.duration,
          position: 0,
          cuePoint: 0
        }));
      }

      // Notify integration mode
      if (integrationMode && onEvent) {
        onEvent('track_loaded', { deck, track: trackData });
      }

      console.log(`Track loaded to deck ${deck}:`, trackData.name, `BPM: ${bpm}, Duration: ${audioBuffer.duration}s`);
    } catch (error) {
      console.error('Error loading track:', error);

      // Check if it's a CORS error
      if (error.message.includes('Failed to fetch') || error.message.includes('CORS')) {
        throw new Error('CORS: External audio file cannot be loaded. Using basic playback mode.');
      } else {
        throw error;
      }
    }
  };

  // Calculate track energy for auto-mixing features
  const calculateTrackEnergy = (audioBuffer) => {
    const channelData = audioBuffer.getChannelData(0);
    let totalEnergy = 0;

    for (let i = 0; i < channelData.length; i++) {
      totalEnergy += Math.abs(channelData[i]);
    }

    return totalEnergy / channelData.length;
  };

  // Find significant peaks in track for auto-cueing
  const findTrackPeaks = (audioBuffer) => {
    const channelData = audioBuffer.getChannelData(0);
    const peaks = [];
    const sampleRate = audioBuffer.sampleRate;
    const threshold = 0.8;
    const minDistance = sampleRate * 4; // 4 seconds minimum between peaks

    for (let i = minDistance; i < channelData.length - minDistance; i += minDistance) {
      let maxInWindow = 0;
      let maxIndex = i;

      for (let j = i; j < i + minDistance; j++) {
        if (Math.abs(channelData[j]) > maxInWindow) {
          maxInWindow = Math.abs(channelData[j]);
          maxIndex = j;
        }
      }

      if (maxInWindow > threshold) {
        peaks.push({
          time: maxIndex / sampleRate,
          intensity: maxInWindow
        });
      }
    }

    return peaks;
  };

  // Enhanced file upload with metadata extraction
  const handleFileUpload = async (event) => {
    const files = Array.from(event.target.files);

    for (const file of files) {
      const supportedFormats = ['audio/mpeg', 'audio/aac', 'audio/wav', 'audio/flac', 'audio/aiff'];

      if (!supportedFormats.includes(file.type)) {
        console.warn(`Unsupported format: ${file.type}`);
        continue;
      }

      const url = URL.createObjectURL(file);

      // Extract metadata from filename (basic implementation)
      const nameParts = file.name.replace(/\.[^/.]+$/, '').split(' - ');
      const artist = nameParts.length > 1 ? nameParts[0] : 'Unknown Artist';
      const trackName = nameParts.length > 1 ? nameParts[1] : nameParts[0];

      const track = {
        id: Date.now() + Math.random(),
        name: trackName,
        artist: artist,
        album: 'Unknown Album',
        url: url,
        format: file.type,
        size: file.size,
        artwork: null,
        dateAdded: new Date(),
        playCount: 0,
        rating: 0
      };

      setLibrary(prev => [track, ...prev]);
    }

    // Reset file input
    event.target.value = '';
  };

  // Enhanced deck controls with audio node management
  const playPauseDeck = async (deck) => {
    const deckState = deck === 'A' ? deckA : deckB;
    const setDeckState = deck === 'A' ? setDeckA : setDeckB;

    if (!deckState.track) return;

    console.log(`playPauseDeck called for deck ${deck}, current state:`, {
      isPlaying: deckState.isPlaying,
      hasAudioBuffer: !!deckState.track?.audioBuffer,
      audioContextState: audioContextRef.current?.state
    });

    // Ensure AudioContext is resumed (Chrome autoplay policy)
    if (audioContextRef.current && audioContextRef.current.state === 'suspended') {
      console.log('Resuming suspended AudioContext');
      try {
        await audioContextRef.current.resume();
        console.log('AudioContext resumed, new state:', audioContextRef.current.state);
        checkStatusRef.current();
      } catch (error) {
        console.error('Failed to resume AudioContext:', error);
        return; // Exit early if we can't resume
      }
    }

    // Prevent double-clicks during loading
    if (deckState.isLoading) {
      console.log('Track is already loading, please wait...');
      return;
    }

    // If track doesn't have audioBuffer, load it first
    if (!deckState.track.audioBuffer && deckState.track.url) {
      console.log(`Loading track before playback: ${deckState.track.name}`);

      // Set loading state
      setDeckState(prev => ({ ...prev, isLoading: true }));

      // Try to load the track
      try {
        await loadTrackToDeck(deckState.track, deck);
        // After loading, get fresh state and try to play
        // Use refs to get the latest state
        const checkAndPlay = async () => {
          const currentDeckState = deck === 'A' ? deckARef.current : deckBRef.current;
          if (currentDeckState.track?.audioBuffer) {
            // Don't call playPauseDeck again, just start playback directly
            const success = await startDeckPlayback(deck);
            if (success) {
              const setDeckState = deck === 'A' ? setDeckA : setDeckB;
              setDeckState(prev => ({ ...prev, isPlaying: true, isLoading: false }));

              // Notify integration
              if (integrationMode && onEvent) {
                onEvent('deck_playing', { deck, track: currentDeckState.track });
              }
            } else {
              console.error('Failed to start playback after loading');
              const setDeckState = deck === 'A' ? setDeckA : setDeckB;
              setDeckState(prev => ({ ...prev, isLoading: false }));
              // Try HTML5 fallback
              playWithHTML5Audio(deck, currentDeckState.track);
            }
          } else {
            console.error('Failed to load track audio buffer');
            const setDeckState = deck === 'A' ? setDeckA : setDeckB;
            setDeckState(prev => ({ ...prev, isLoading: false }));
          }
        };

        // Use setTimeout with 0 to defer execution to next tick
        setTimeout(checkAndPlay, 0);

      } catch (error) {
        console.error('Error loading track, trying HTML5 audio fallback:', error);

        // Clear loading state on error
        setDeckState(prev => ({ ...prev, isLoading: false }));

        // Show user-friendly message for CORS errors
        if (error.message.includes('CORS')) {
          console.warn('⚠️ External audio file - using basic playback mode. For full DJ features, use local files.');
          if (integrationMode && onEvent) {
            onEvent('cors_fallback', {
              deck,
              track: deckState.track,
              message: 'Limited features: BPM detection and effects not available for external files'
            });
          }
        }

        // Fallback to HTML5 audio for immediate playback
        playWithHTML5Audio(deck, deckState.track);
      }
      return;
    }

    if (deckState.isPlaying) {
      // Pause
      setDeckState(prev => ({ ...prev, isPlaying: false }));
      // Stop audio source
      const sourceRef = deck === 'A' ? deckASourceRef : deckBSourceRef;
      const startTimeRef = deck === 'A' ? deckAStartTimeRef : deckBStartTimeRef;
      if (sourceRef.current) {
        try {
          sourceRef.current.stop();
        } catch (error) {
          console.error('Error stopping audio source:', error);
        }
        sourceRef.current = null;
      }
      startTimeRef.current = null;

      // Also stop HTML5 audio fallback if exists
      const fallbackAudio = deck === 'A' ? window._deckAAudioFallback : window._deckBAudioFallback;
      if (fallbackAudio) {
        fallbackAudio.pause();
        fallbackAudio.currentTime = 0;
        if (deck === 'A') {
          window._deckAAudioFallback = null;
        } else {
          window._deckBAudioFallback = null;
        }
      }

      // Notify integration
      if (integrationMode && onEvent) {
        onEvent('deck_paused', { deck, track: deckState.track });
      }
    } else {
      // Play
      try {
        const success = await startDeckPlayback(deck);
        if (success) {
          setDeckState(prev => ({ ...prev, isPlaying: true }));

          // Notify integration
          if (integrationMode && onEvent) {
            onEvent('deck_playing', { deck, track: deckState.track });
          }
        } else {
          console.error('Failed to start playback');
          // Try HTML5 fallback
          playWithHTML5Audio(deck, deckState.track);
        }
      } catch (error) {
        console.error('Error starting playback:', error);
        // Try HTML5 fallback
        playWithHTML5Audio(deck, deckState.track);
      }
    }
  };

  // HTML5 Audio fallback for immediate playback
  const playWithHTML5Audio = (deck, track) => {
    console.log(`Using HTML5 audio fallback for deck ${deck}`);
    const audioElement = new Audio(track.url);
    const setDeckState = deck === 'A' ? setDeckA : setDeckB;

    audioElement.volume = (deck === 'A' ? deckA.volume : deckB.volume) / 100;

    audioElement.play().then(() => {
      setDeckState(prev => ({ ...prev, isPlaying: true }));
      console.log(`HTML5 audio playing on deck ${deck}`);

      // Store reference for stopping
      if (deck === 'A') {
        window._deckAAudioFallback = audioElement;
      } else {
        window._deckBAudioFallback = audioElement;
      }

      audioElement.addEventListener('ended', () => {
        setDeckState(prev => ({ ...prev, isPlaying: false }));
      });
    }).catch(error => {
      console.error(`HTML5 audio playback failed:`, error);
      alert(`Failed to play track: ${error.message}`);
    });
  };

  const startDeckPlayback = async (deck) => {
    const deckState = deck === 'A' ? deckARef.current : deckBRef.current;
    const nodes = deck === 'A' ? deckANodesRef.current : deckBNodesRef.current;
    const sourceRef = deck === 'A' ? deckASourceRef : deckBSourceRef;

    if (!deckState.track || !deckState.track.audioBuffer) {
      console.error(`Cannot start playback: track or audioBuffer missing for deck ${deck}`);
      return false;
    }

    // Stop any existing source
    if (sourceRef.current) {
      try {
        sourceRef.current.stop();
        sourceRef.current.disconnect();
      } catch (e) {
        // Already stopped
      }
      sourceRef.current = null;
    }

    try {
      // Ensure audio context is not suspended - this is critical!
      if (audioContextRef.current.state === 'suspended') {
        console.log('AudioContext is suspended, attempting to resume...');
        await audioContextRef.current.resume();
        console.log('AudioContext resumed successfully, state:', audioContextRef.current.state);
        checkStatusRef.current();
      }

      // Double-check the state after resume
      if (audioContextRef.current.state !== 'running') {
        console.error('AudioContext is not running after resume attempt, state:', audioContextRef.current.state);
        return false;
      }

      // Create and configure audio source
      const source = audioContextRef.current.createBufferSource();
      source.buffer = deckState.track.audioBuffer;

      // Connect through audio chain
      source.connect(nodes.eqHigh);
      nodes.eqHigh.connect(nodes.eqMid);
      nodes.eqMid.connect(nodes.eqLow);
      nodes.eqLow.connect(nodes.filter);
      nodes.filter.connect(nodes.gain);
      nodes.gain.connect(nodes.analyser);
      nodes.analyser.connect(masterNodesRef.current.gain);

      // Handle playback end
      source.onended = () => {
        const setDeckState = deck === 'A' ? setDeckA : setDeckB;
        setDeckState(prev => ({ ...prev, isPlaying: false, position: 0 }));
        sourceRef.current = null;
      };

      // Start playback from current position
      const startTime = audioContextRef.current.currentTime;
      source.start(0, deckState.position);
      sourceRef.current = source;
      // Store start time for position calculation
      if (deck === 'A') {
        deckAStartTimeRef.current = startTime - deckState.position;
      } else {
        deckBStartTimeRef.current = startTime - deckState.position;
      }
      
      console.log(`Started playback on deck ${deck}, AudioContext state: ${audioContextRef.current.state}`);
      return true;

    } catch (error) {
      console.error(`Failed to start deck ${deck} playback:`, error);
      return false;
    }
  };

  // RTMP Streaming controls (disabled in integration mode, use parent streaming)
  const toggleStreaming = async () => {
    if (integrationMode) {
      console.log('⚠️ RTMP streaming disabled in integration mode - use parent streaming controls');
      return;
    }

    // Legacy RTMP streaming for standalone mode
    if (isStreamingDJ) {
      rtmpStreamerRef.current.stopStream();

      if (onEvent) {
        onEvent('streaming_stopped', {});
      }
    } else {
      const config = streamConfigRef.current.getConfig();
      if (!config.rtmpUrl || !config.streamKey) {
        alert('Please configure RTMP settings first');
        setShowSettings(true);
        return;
      }

      const success = await rtmpStreamerRef.current.initializeStream(
        config.rtmpUrl + config.streamKey,
        config.streamKey
      );

      if (success) {
        await rtmpStreamerRef.current.startStream();

        if (onEvent) {
          onEvent('streaming_started', { config });
        }
      }
    }
  };

  // Recording controls
  const toggleRecording = async () => {
    if (isRecording) {
      const recording = await audioRecorderRef.current.stopRecording();
      if (recording) {
        const filename = `dj-mix-${new Date().toISOString().split('T')[0]}.webm`;
        await audioRecorderRef.current.saveToStorage(recording.blob, filename);

        if (integrationMode && onEvent) {
          onEvent('recording_completed', { recording, filename });
        }
      }
      checkStatusRef.current();
    } else {
      // Create stream from master output
      const destination = audioContextRef.current.createMediaStreamDestination();
      masterNodesRef.current.analyser.connect(destination);

      const success = await audioRecorderRef.current.startRecording(destination.stream);
      if (success) {
        checkStatusRef.current();

        if (integrationMode && onEvent) {
          onEvent('recording_started', {});
        }
      }
    }
  };

  // Update audio nodes when deck parameters change
  useEffect(() => {
    updateDeckAudioNodes('A', deckA);
  }, [deckA.volume, deckA.eqHigh, deckA.eqMid, deckA.eqLow, deckA.gain]);

  useEffect(() => {
    updateDeckAudioNodes('B', deckB);
  }, [deckB.volume, deckB.eqHigh, deckB.eqMid, deckB.eqLow, deckB.gain]);

  const updateDeckAudioNodes = (deck, deckState) => {
    const nodes = deck === 'A' ? deckANodesRef.current : deckBNodesRef.current;

    if (!nodes.gain || !nodes.eqHigh || !nodes.eqMid || !nodes.eqLow) return;

    // Update EQ with smooth transitions
    const currentTime = audioContextRef.current?.currentTime || 0;
    const transitionTime = 0.05; // 50ms smooth transition

    // Update EQ with linear ramp to prevent clicks
    nodes.eqHigh.gain.linearRampToValueAtTime(deckState.eqHigh, currentTime + transitionTime);
    nodes.eqMid.gain.linearRampToValueAtTime(deckState.eqMid, currentTime + transitionTime);
    nodes.eqLow.gain.linearRampToValueAtTime(deckState.eqLow, currentTime + transitionTime);

    // Note: Volume is handled separately in the crossfader effect
    // Don't update gain node here to avoid double multiplication
  };


  // Cleanup function - don't close audio context (it's persistent!)
  const cleanup = () => {
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
    }

    // Don't close audio context - it's managed by DJMixerContext now

    if (rtmpStreamerRef.current) {
      rtmpStreamerRef.current.stopStream();
    }

    if (audioRecorderRef.current && audioRecorderRef.current.isRecording) {
      audioRecorderRef.current.stopRecording();
    }
  };

  // Drag and drop handlers
  const handleDragStart = (track) => {
    setDraggedTrack(track);
  };

  const handleDragOver = (event) => {
    event.preventDefault();
  };

  const handleDrop = (event, deck) => {
    event.preventDefault();
    if (draggedTrack) {
      loadTrackToDeck(draggedTrack, deck);
      setDraggedTrack(null);
    }
  };

  // Filter library
  const filteredLibrary = library.filter(track =>
    track.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    track.artist.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // Format time display
  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // Render deck component
  const renderDeck = (deck, deckState, setDeckState) => (
    <div
      className={`deck deck-${deck.toLowerCase()}`}
      onDragOver={handleDragOver}
      onDrop={(e) => handleDrop(e, deck)}
    >
      <div className="deck-header">
        <h3>DECK {deck}</h3>
        <div className="deck-info">
          {deckState.track ? (
            <>
              <span className="track-name">{deckState.track.name}</span>
              <span className="track-artist">{deckState.track.artist}</span>
              {deckState.bpm && <span className="bpm">{deckState.bpm} BPM</span>}
            </>
          ) : (
            <span className="no-track">Drop track here</span>
          )}
        </div>
      </div>

      <div className="deck-display">
        <WaveformVisualizer
          audioBuffer={deckState.track?.audioBuffer}
          isPlaying={deckState.isPlaying}
          currentTime={deckState.position}
          duration={deckState.duration}
          onSeek={(time) => setDeckState(prev => ({ ...prev, position: time }))}
          color={deck === 'A' ? '#ff6b6b' : '#4ecdc4'}
        />
        <div className="position-info">
          <span>{formatTime(deckState.position)}</span>
          <span>/</span>
          <span>{formatTime(deckState.duration)}</span>
        </div>
      </div>

      <div className="deck-controls">
        <div className="transport-controls">
          <button
            onClick={() => setDeckState(prev => ({ ...prev, position: prev.cuePoint }))}
            className="cue-btn"
          >
            <SkipBack size={16} />
          </button>
          <button
            onClick={() => {
              console.log(`Play button clicked for deck ${deck}, isPlaying: ${deckState.isPlaying}, track: ${deckState.track?.name}, isLoading: ${deckState.isLoading}`);
              playPauseDeck(deck);
            }}
            className="play-pause-btn"
            disabled={!deckState.track || deckState.isLoading}
          >
            {deckState.isLoading ? (
              <span>...</span>
            ) : deckState.isPlaying ? (
              <Pause size={20} />
            ) : (
              <Play size={20} />
            )}
          </button>
          <button
            onClick={() => {
              // Stop button - properly stop playback
              const sourceRef = deck === 'A' ? deckASourceRef : deckBSourceRef;
              const startTimeRef = deck === 'A' ? deckAStartTimeRef : deckBStartTimeRef;
              if (sourceRef.current) {
                try {
                  sourceRef.current.stop();
                } catch (e) {
                  // Already stopped
                }
                sourceRef.current = null;
              }
              startTimeRef.current = null;

              // Stop HTML5 audio fallback if exists
              const fallbackAudio = deck === 'A' ? window._deckAAudioFallback : window._deckBAudioFallback;
              if (fallbackAudio) {
                fallbackAudio.pause();
                fallbackAudio.currentTime = 0;
                if (deck === 'A') {
                  window._deckAAudioFallback = null;
                } else {
                  window._deckBAudioFallback = null;
                }
              }

              setDeckState(prev => ({ ...prev, isPlaying: false, isLoading: false, position: 0 }));
            }}
            className="stop-btn"
          >
            <Square size={16} />
          </button>
        </div>

        <div className="eq-controls">
          <div className="eq-knob">
            <label>HIGH</label>
            <input
              type="range"
              min="-20"
              max="20"
              value={deckState.eqHigh}
              onChange={(e) => setDeckState(prev => ({ ...prev, eqHigh: parseInt(e.target.value) }))}
            />
            <span>{deckState.eqHigh}</span>
          </div>
          <div className="eq-knob">
            <label>MID</label>
            <input
              type="range"
              min="-20"
              max="20"
              value={deckState.eqMid}
              onChange={(e) => setDeckState(prev => ({ ...prev, eqMid: parseInt(e.target.value) }))}
            />
            <span>{deckState.eqMid}</span>
          </div>
          <div className="eq-knob">
            <label>LOW</label>
            <input
              type="range"
              min="-20"
              max="20"
              value={deckState.eqLow}
              onChange={(e) => setDeckState(prev => ({ ...prev, eqLow: parseInt(e.target.value) }))}
            />
            <span>{deckState.eqLow}</span>
          </div>
        </div>

        <div className="volume-control">
          <label>VOLUME</label>
          <input
            type="range"
            min="0"
            max="100"
            value={deckState.volume}
            onChange={(e) => setDeckState(prev => ({ ...prev, volume: parseInt(e.target.value) }))}
            className="volume-slider"
          />
          <span>{deckState.volume}%</span>
        </div>

        <div className="advanced-controls">
          <div className="gain-control">
            <label>GAIN</label>
            <input
              type="range"
              min="-20"
              max="20"
              value={deckState.gain}
              onChange={(e) => setDeckState(prev => ({ ...prev, gain: parseInt(e.target.value) }))}
            />
            <span>{deckState.gain}</span>
          </div>

          <div className="tempo-control">
            <label>TEMPO</label>
            <input
              type="range"
              min="-20"
              max="20"
              value={deckState.tempoSlider}
              onChange={(e) => setDeckState(prev => ({ ...prev, tempoSlider: parseInt(e.target.value) }))}
            />
            <span>{deckState.tempoSlider}%</span>
          </div>
        </div>

        <div className="deck-options">
          <button
            className={`option-btn ${deckState.keyLock ? 'active' : ''}`}
            onClick={() => setDeckState(prev => ({ ...prev, keyLock: !prev.keyLock }))}
          >
            KEY
          </button>
          <button
            className={`option-btn ${deckState.sync ? 'active' : ''}`}
            onClick={() => setDeckState(prev => ({ ...prev, sync: !prev.sync }))}
          >
            SYNC
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <div className={`dj-studio-mixer-enhanced ${className}`}>
      {/* Header - conditionally render based on integration mode */}
      {!integrationMode && (
        <div className="mixer-header">
          <div className="logo-section">
            <Music size={24} />
            <h1>TalkStudio DJ Pro</h1>
            <div className="connection-status">
              {isStreamingDJ ? <Wifi size={16} className="streaming" /> : <WifiOff size={16} />}
            </div>
          </div>

          <div className="stream-controls">
            <button
              onClick={toggleRecording}
              className={`record-btn ${isRecording ? 'recording' : ''}`}
            >
              <Disc size={16} />
              {isRecording ? 'Stop Recording' : 'Record Set'}
            </button>

            <button
              onClick={toggleStreaming}
              className={`stream-btn ${isStreamingDJ ? 'streaming' : ''}`}
            >
              <Radio size={16} />
              {isStreamingDJ ? 'Stop Stream' : 'Go Live'}
            </button>

            <button
              onClick={() => setShowSettings(!showSettings)}
              className="settings-btn"
            >
              <Settings size={16} />
            </button>
          </div>
        </div>
      )}

      <div className="mixer-layout">
        {/* Library Toggle Button */}
        {!showLibrary && (
          <button 
            className="library-toggle-btn"
            onClick={() => setShowLibrary(true)}
            title="Show Library"
          >
            <ChevronRight size={20} />
          </button>
        )}
        
        {/* Library Panel */}
        {showLibrary && (
          <div className="library-panel">
            <div className="library-header">
              <div className="library-title">
                <h3>Library ({library.length})</h3>
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="upload-btn"
                  title="Upload Tracks"
                >
                  <Upload size={16} />
                </button>
              </div>
              <button 
                onClick={() => setShowLibrary(false)}
                className="minimize-btn"
                title="Hide Library"

              >
                <ChevronLeft size={16} />
              </button>
            </div>

            <div className="search-bar">
              <input
                type="text"
                placeholder="Search tracks, artists..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>

            <div className="track-list">
              {filteredLibrary.map(track => (
                <div
                  key={track.id}
                  className="track-item"
                  draggable
                  onDragStart={() => handleDragStart(track)}
                  onClick={() => setSelectedTrack(track)}
                >
                  <div className="track-artwork">
                    {track.artwork ? (
                      <img src={track.artwork} alt="" />
                    ) : (
                      <Music size={16} />
                    )}
                  </div>

                  <div className="track-info">
                    <div className="track-name">{track.name}</div>
                    <div className="track-artist">{track.artist}</div>
                    <div className="track-meta">
                      {track.bpm && <span className="bpm">{track.bpm} BPM</span>}
                      <span className="format">{track.format.split('/')[1].toUpperCase()}</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>

            <input
              ref={fileInputRef}
              type="file"
              multiple
              accept=".mp3,.aac,.wav,.flac,.aiff"
              onChange={handleFileUpload}
              style={{ display: 'none' }}
            />
          </div>
        )}

        {/* Main Mixer */}
        <div className="mixer-main">
          <div className="decks-container">
            {/* Deck A */}
            {renderDeck('A', deckA, setDeckA)}

            {/* Crossfader Section */}
            <div className="crossfader-section">
            <div className="master-controls">
              <div className="master-volume">
                <label>MASTER</label>
                <input
                  type="range"
                  min="0"
                  max="100"
                  value={masterVolume}
                  onChange={(e) => setMasterVolume(parseInt(e.target.value))}
                  className="master-volume-slider"
                />
                <span>{masterVolume}%</span>
              </div>

              <div className="cue-volume">
                <label>CUE</label>
                <input
                  type="range"
                  min="0"
                  max="100"
                  value={cueVolume}
                  onChange={(e) => setCueVolume(parseInt(e.target.value))}
                />
                <span>{cueVolume}%</span>
              </div>
            </div>

            <div className="crossfader">
              <label>CROSSFADER</label>
              <input
                type="range"
                min="0"
                max="100"
                value={crossfaderPosition}
                onChange={(e) => setCrossfaderPosition(parseInt(e.target.value))}
                className="crossfader-slider"
              />
              <div className="crossfader-labels">
                <span>A</span>
                <span>B</span>
              </div>
            </div>

            <div className="mixer-stats">
              <div
                className={`stat ${isRecording ? 'live' : 'off'}`}
                title={isRecording ? 'Recording the master output' : 'Not recording'}
              >
                <span className="stat-label">RECORDING</span>
                <span className="stat-value">
                  <span className="indicator" />
                  {isRecording ? 'REC' : 'OFF'}
                </span>
              </div>
              <div
                className={`stat ${isStreamingDJ ? 'live' : 'off'}`}
                title={isStreamingDJ ? 'Streaming to the live event' : 'Not streaming'}
              >
                <span className="stat-label">STREAMING</span>
                <span className="stat-value">
                  <span className="indicator" />
                  {isStreamingDJ ? 'LIVE' : 'OFF'}
                </span>
              </div>
              <div
                className={`stat ${audioStatus.tone}`}
                title={`AudioContext: ${audioContextState}`}
              >
                <span className="stat-label">AUDIO</span>
                <span className="stat-value">
                  <span className="indicator" />
                  {audioStatus.label}
                </span>
              </div>
            </div>
          </div>

          {/* Deck B */}
            {/* Deck B */}
            {renderDeck('B', deckB, setDeckB)}
          </div>
        </div>
      </div>

      {/* Settings Modal */}
      {showSettings && (
        <div className="settings-modal">
          <div className="settings-content">
            <div className="settings-header">
              <h3>Streaming Settings</h3>
              <button onClick={() => setShowSettings(false)}>×</button>
            </div>

            <div className="settings-form">
              <div className="form-group">
                <label>Platform</label>
                <select
                  onChange={(e) => {
                    if (e.target.value !== 'custom') {
                      streamConfigRef.current.setPlatform(e.target.value, '');
                    }
                  }}
                >
                  <option value="custom">Custom RTMP</option>
                  <option value="twitch">Twitch</option>
                  <option value="youtube">YouTube</option>
                  <option value="facebook">Facebook</option>
                </select>
              </div>

              <div className="form-group">
                <label>RTMP URL</label>
                <input
                  type="text"
                  placeholder="rtmp://live.example.com/live/"
                  onChange={(e) => {
                    const config = streamConfigRef.current.getConfig();
                    streamConfigRef.current.setCustomEndpoint(e.target.value, config.streamKey);
                  }}
                />
              </div>

              <div className="form-group">
                <label>Stream Key</label>
                <input
                  type="password"
                  placeholder="Your stream key"
                  onChange={(e) => {
                    const config = streamConfigRef.current.getConfig();
                    streamConfigRef.current.setCustomEndpoint(config.rtmpUrl, e.target.value);
                  }}
                />
              </div>

              <div className="form-group">
                <label>Bitrate</label>
                <select
                  onChange={(e) => {
                    streamConfigRef.current.updateQuality({ bitrate: parseInt(e.target.value) });
                  }}
                >
                  <option value="96000">96 kbps</option>
                  <option value="128000">128 kbps</option>
                  <option value="192000">192 kbps</option>
                  <option value="320000">320 kbps</option>
                </select>
              </div>
            </div>
          </div>
        </div>
      )}

      <style jsx>{`
        .dj-studio-mixer-enhanced {
          height: 100vh;
          background: linear-gradient(135deg, #1a1a1a 0%, #2d2d2d 100%);
          color: #ffffff;
          font-family: 'Arial', sans-serif;
          overflow: hidden;
        }

        .mixer-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          padding: 1rem 2rem;
          background: rgba(0, 0, 0, 0.3);
          border-bottom: 1px solid #444;
        }

        .logo-section {
          display: flex;
          align-items: center;
          gap: 0.5rem;
        }

        .logo-section h1 {
          margin: 0;
          font-size: 1.5rem;
          font-weight: 600;
          background: linear-gradient(45deg, #ff6b6b, #4ecdc4);
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          background-clip: text;
        }

        .connection-status {
          margin-left: 1rem;
        }

        .connection-status .streaming {
          color: #4ecdc4;
          animation: pulse 2s infinite;
        }

        .stream-controls {
          display: flex;
          gap: 1rem;
        }

        .record-btn, .stream-btn, .settings-btn {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          padding: 0.5rem 1rem;
          border: 1px solid #666;
          border-radius: 6px;
          background: rgba(255, 255, 255, 0.1);
          color: white;
          cursor: pointer;
          transition: all 0.3s;
        }

        .record-btn:hover, .stream-btn:hover, .settings-btn:hover {
          background: rgba(255, 255, 255, 0.2);
          border-color: #4ecdc4;
        }

        .record-btn.recording {
          background: #ff6b6b;
          border-color: #ff6b6b;
          animation: pulse 2s infinite;
        }

        .stream-btn.streaming {
          background: #4ecdc4;
          border-color: #4ecdc4;
        }

        .mixer-layout {
          display: flex;
          height: calc(100vh - 70px);
        }

        .library-panel {
          width: 300px;
          background: rgba(0, 0, 0, 0.3);
          border-right: 1px solid #444;
          display: flex;
          flex-direction: column;
        }

        .library-toggle-btn {
          position: absolute;
          left: 0;
          top: 50%;
          transform: translateY(-50%);
          background: rgba(0, 0, 0, 0.8);
          border: 1px solid #444;
          border-left: none;
          border-radius: 0 8px 8px 0;
          padding: 1rem 0.5rem;
          color: white;
          cursor: pointer;
          transition: all 0.3s;
          z-index: 10;
        }

        .library-toggle-btn:hover {
          background: rgba(78, 205, 196, 0.2);
          border-color: #4ecdc4;
        }

        .library-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          padding: 1rem;
          border-bottom: 1px solid #444;
        }

        .library-title {
          display: flex;
          align-items: center;
          gap: 1rem;
        }

        .library-header h3 {
          margin: 0;
          font-size: 1.2rem;
        }

        .minimize-btn {
          background: transparent;
          border: none;
          color: #aaa;
          cursor: pointer;
          padding: 0.5rem;
          border-radius: 4px;
          transition: all 0.3s;
        }

        .minimize-btn:hover {
          background: rgba(255, 255, 255, 0.1);
          color: white;
        }

        .upload-btn {
          background: rgba(255, 255, 255, 0.1);
          border: none;
          border-radius: 4px;
          padding: 0.5rem;
          cursor: pointer;
          color: white;
          transition: all 0.3s;
        }

        .upload-btn:hover {
          background: rgba(255, 255, 255, 0.2);
        }

        .search-bar {
          padding: 1rem;
        }

        .search-bar input {
          width: 100%;
          padding: 0.5rem;
          border: 1px solid #444;
          border-radius: 4px;
          background: rgba(255, 255, 255, 0.05);
          color: white;
        }

        .track-list {
          flex: 1;
          overflow-y: auto;
          padding: 0.5rem;
        }

        .track-item {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          padding: 0.5rem;
          border-radius: 4px;
          cursor: pointer;
          transition: all 0.2s;
        }

        .track-item:hover {
          background: rgba(255, 255, 255, 0.1);
        }

        .track-artwork {
          width: 40px;
          height: 40px;
          background: rgba(255, 255, 255, 0.1);
          border-radius: 4px;
          display: flex;
          align-items: center;
          justify-content: center;
        }

        .track-artwork img {
          width: 100%;
          height: 100%;
          object-fit: cover;
          border-radius: 4px;
        }

        .track-info {
          flex: 1;
          min-width: 0;
        }

        .track-name {
          font-weight: 600;
          font-size: 0.9rem;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }

        .track-artist {
          font-size: 0.8rem;
          color: #aaa;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }

        .track-meta {
          display: flex;
          gap: 0.5rem;
          font-size: 0.7rem;
          color: #888;
        }

        .bpm {
          background: rgba(78, 205, 196, 0.2);
          padding: 0.1rem 0.3rem;
          border-radius: 3px;
          color: #4ecdc4;
        }

        .format {
          background: rgba(255, 255, 255, 0.1);
          padding: 0.1rem 0.3rem;
          border-radius: 3px;
        }

        .mixer-main {
          flex: 1;
          padding: 2rem;
          display: flex;
          align-items: center;
          justify-content: center;
        }

        .decks-container {
          display: flex;
          gap: 2rem;
          align-items: stretch;
          width: 100%;
          max-width: 1400px;
        }

        .deck {
          flex: 1;
          background: rgba(255, 255, 255, 0.05);
          border-radius: 12px;
          padding: 2rem;
          border: 2px solid transparent;
          transition: all 0.3s;
        }

        .deck.deck-a {
          border-color: #ff6b6b;
        }

        .deck.deck-b {
          border-color: #4ecdc4;
        }

        .deck-header {
          margin-bottom: 1.5rem;
        }

        .deck-header h3 {
          margin: 0 0 0.5rem;
          font-size: 1.2rem;
          font-weight: 600;
        }

        .deck.deck-a h3 {
          color: #ff6b6b;
        }

        .deck.deck-b h3 {
          color: #4ecdc4;
        }

        .deck-info .track-name {
          display: block;
          font-weight: 600;
          font-size: 1rem;
          margin-bottom: 0.25rem;
        }

        .deck-info .track-artist {
          display: block;
          color: #aaa;
          font-size: 0.9rem;
          margin-bottom: 0.5rem;
        }

        .deck-info .bpm {
          background: rgba(255, 255, 255, 0.1);
          padding: 0.2rem 0.5rem;
          border-radius: 4px;
          font-size: 0.8rem;
          font-weight: 500;
        }

        .deck-info .no-track {
          color: #999;
          font-style: italic;
        }

        .deck-display {
          margin-bottom: 2rem;
        }

        .position-info {
          display: flex;
          justify-content: center;
          gap: 0.5rem;
          font-family: 'Courier New', monospace;
          font-size: 1rem;
          margin-top: 0.5rem;
        }

        .deck-controls {
          display: flex;
          flex-direction: column;
          gap: 1.5rem;
        }

        .transport-controls {
          display: flex;
          justify-content: center;
          gap: 1rem;
        }

        .transport-controls button {
          background: rgba(255, 255, 255, 0.1);
          border: none;
          border-radius: 50%;
          width: 48px;
          height: 48px;
          display: flex;
          align-items: center;
          justify-content: center;
          cursor: pointer;
          transition: all 0.2s;
          color: white;
        }

        .transport-controls button:hover {
          background: rgba(255, 255, 255, 0.2);
          transform: scale(1.05);
        }

        .transport-controls button:disabled {
          opacity: 0.3;
          cursor: not-allowed;
        }

        .play-pause-btn {
          background: linear-gradient(45deg, #ff6b6b, #4ecdc4) !important;
          width: 56px !important;
          height: 56px !important;
        }

        .eq-controls {
          display: flex;
          justify-content: center;
          gap: 1.5rem;
        }

        .eq-knob {
          text-align: center;
        }

        .eq-knob label {
          display: block;
          font-size: 0.7rem;
          font-weight: 600;
          margin-bottom: 0.5rem;
          color: #aaa;
        }

        .eq-knob input[type="range"] {
          writing-mode: bt-lr;
          -webkit-appearance: slider-vertical;
          width: 30px;
          height: 80px;
          background: rgba(255, 255, 255, 0.1);
          outline: none;
        }

        .volume-control {
          text-align: center;
        }

        .volume-control label {
          display: block;
          font-size: 0.8rem;
          font-weight: 600;
          margin-bottom: 0.5rem;
          color: #aaa;
        }

        .volume-slider {
          width: 100%;
          margin-bottom: 0.5rem;
        }

        .crossfader-section {
          width: 200px;
          display: flex;
          flex-direction: column;
          justify-content: center;
          align-items: center;
          gap: 2rem;
          background: rgba(0, 0, 0, 0.2);
          border-radius: 12px;
          padding: 2rem 1rem;
        }

        .master-controls {
          display: flex;
          flex-direction: column;
          gap: 1.5rem;
          width: 100%;
        }

        .master-volume, .cue-volume {
          text-align: center;
        }

        .master-volume label, .cue-volume label {
          display: block;
          font-size: 0.8rem;
          font-weight: 600;
          margin-bottom: 0.5rem;
          color: #aaa;
        }

        .master-volume-slider {
          writing-mode: bt-lr;
          -webkit-appearance: slider-vertical;
          width: 30px;
          height: 100px;
          background: rgba(255, 255, 255, 0.1);
          outline: none;
          margin-bottom: 0.5rem;
        }

        .crossfader {
          text-align: center;
          width: 100%;
        }

        .crossfader label {
          display: block;
          font-size: 0.8rem;
          font-weight: 600;
          margin-bottom: 1rem;
          color: #aaa;
        }

        .crossfader-slider {
          width: 100%;
          margin-bottom: 0.5rem;
          background: linear-gradient(90deg, #ff6b6b 0%, #4ecdc4 100%);
          height: 8px;
          border-radius: 4px;
          outline: none;
          -webkit-appearance: none;
        }

        .crossfader-slider::-webkit-slider-thumb {
          -webkit-appearance: none;
          width: 20px;
          height: 20px;
          border-radius: 50%;
          background: white;
          box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
          cursor: pointer;
        }

        .crossfader-labels {
          display: flex;
          justify-content: space-between;
          font-weight: 600;
          font-size: 0.9rem;
        }

        .crossfader-labels span:first-child {
          color: #ff6b6b;
        }

        .crossfader-labels span:last-child {
          color: #4ecdc4;
        }

        .mixer-stats {
          width: 100%;
          display: flex;
          flex-direction: column;
          gap: 0.5rem;
          padding: 0.75rem;
          background: rgba(0, 0, 0, 0.3);
          border: 1px solid rgba(255, 255, 255, 0.08);
          border-radius: 8px;
        }

        .mixer-stats .stat {
          display: flex;
          align-items: center;
          justify-content: space-between;
          gap: 0.75rem;
          font-size: 0.7rem;
          font-weight: 600;
          letter-spacing: 0.04em;
        }

        .mixer-stats .stat-label {
          color: #aaa;
        }

        .mixer-stats .stat-value {
          display: flex;
          align-items: center;
          gap: 0.4rem;
          font-family: 'JetBrains Mono', monospace;
          color: #6b7280;
        }

        .mixer-stats .indicator {
          width: 8px;
          height: 8px;
          border-radius: 50%;
          background: #4a5568;
          flex-shrink: 0;
          transition: background 0.2s ease, box-shadow 0.2s ease;
        }

        /* Row tone drives both the dot and its readout, so the label and the
           light can never disagree about the status. */
        .mixer-stats .stat.live .stat-value {
          color: #ef4444;
        }

        .mixer-stats .stat.live .indicator {
          background: #ef4444;
          box-shadow: 0 0 6px rgba(239, 68, 68, 0.85);
          animation: pulse 1.2s ease-in-out infinite;
        }

        .mixer-stats .stat.ok .stat-value {
          color: #22c55e;
        }

        .mixer-stats .stat.ok .indicator {
          background: #22c55e;
          box-shadow: 0 0 6px rgba(34, 197, 94, 0.85);
        }

        .mixer-stats .stat.warn .stat-value {
          color: #f59e0b;
        }

        .mixer-stats .stat.warn .indicator {
          background: #f59e0b;
          box-shadow: 0 0 6px rgba(245, 158, 11, 0.85);
        }

        @keyframes pulse {
          0%, 100% { opacity: 1; }
          50% { opacity: 0.7; }
        }

        /* Responsive Design */
        @media (max-width: 1200px) {
          .decks-container {
            flex-direction: column;
            gap: 1rem;
          }

          .crossfader-section {
            width: 100%;
            flex-direction: row;
            padding: 1rem;
          }

          .master-controls {
            flex-direction: row;
          }
        }

        @media (max-width: 768px) {
          .library-panel {
            display: none;
          }

          .mixer-main {
            padding: 1rem;
          }

          .deck {
            padding: 1rem;
          }
        }
      `}</style>
    </div>
  );
};

export default DJStudioMixerEnhanced;
