// src/components/Settings.jsx
import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { db, storage } from '../firebase';
import { doc, updateDoc, getDoc } from 'firebase/firestore';
import { ref, uploadBytesResumable, getDownloadURL } from 'firebase/storage';
import { Camera } from 'lucide-react';
import SubscriptionManager from './premium/SubscriptionManager';
import './Settings.css';

const Settings = () => {
  const { currentUser } = useAuth();
  const [displayName, setDisplayName] = useState('');
  const [bio, setBio] = useState('');
  const [photoURL, setPhotoURL] = useState('');
  const [phoneNumber, setPhoneNumber] = useState('');
  const [smsEnabled, setSmsEnabled] = useState(true);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [uploadingPhoto, setUploadingPhoto] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [success, setSuccess] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchUserData = async () => {
      if (currentUser) {
        try {
          const userDoc = await getDoc(doc(db, 'users', currentUser.uid));
          
          if (userDoc.exists()) {
            const userData = userDoc.data();
            setDisplayName(userData.displayName || currentUser.displayName || '');
            setBio(userData.bio || '');
            setPhotoURL(userData.photoURL || currentUser.photoURL || '');
            setPhoneNumber(userData.phoneNumber || '');
            setSmsEnabled(userData.botDisabled ? false : true);
          } else {
            setDisplayName(currentUser.displayName || '');
            setPhotoURL(currentUser.photoURL || '');
          }
        } catch (err) {
          console.error('Error fetching user data:', err);
          setError('Failed to load user settings');
        } finally {
          setLoading(false);
        }
      }
    };

    fetchUserData();
  }, [currentUser]);

  const handlePhotoChange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    
    // Validate file
    if (!file.type.startsWith('image/')) {
      setError('Please select an image file');
      return;
    }
    
    if (file.size > 5 * 1024 * 1024) { // 5MB limit
      setError('Image size must be less than 5MB');
      return;
    }
    
    setUploadingPhoto(true);
    setError('');
    
    try {
      // Create a storage reference
      const storageRef = ref(storage, `profilePictures/${currentUser.uid}/${Date.now()}_${file.name}`);
      
      // Upload file
      const uploadTask = uploadBytesResumable(storageRef, file);
      
      uploadTask.on('state_changed',
        (snapshot) => {
          // Handle progress
          const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
          setUploadProgress(progress);
        },
        (error) => {
          // Handle error
          console.error('Upload error:', error);
          setError('Failed to upload photo');
          setUploadingPhoto(false);
        },
        async () => {
          // Handle successful upload
          const downloadURL = await getDownloadURL(uploadTask.snapshot.ref);
          setPhotoURL(downloadURL);
          setUploadingPhoto(false);
          setUploadProgress(0);
          
          // Update user document immediately
          try {
            await updateDoc(doc(db, 'users', currentUser.uid), {
              photoURL: downloadURL
            });
            setSuccess('Profile picture updated');
          } catch (err) {
            console.error('Error updating photo:', err);
            setError('Failed to save photo');
          }
        }
      );
    } catch (err) {
      console.error('Error uploading photo:', err);
      setError('Failed to upload photo');
      setUploadingPhoto(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    setError('');
    setSuccess('');
    
    try {
      await updateDoc(doc(db, 'users', currentUser.uid), {
        displayName,
        bio,
        phoneNumber,
        botDisabled: !smsEnabled,
        updatedAt: new Date().toISOString()
      });
      
      setSuccess('Settings updated successfully');
    } catch (err) {
      console.error('Error updating settings:', err);
      setError('Failed to update settings');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return <div className="settings-loading">Loading settings...</div>;
  }

  return (
    <div className="settings-container">
      <h1>Settings</h1>
      
      {/* Subscription Management Section */}
      <div className="settings-section">
        <h2>Subscription</h2>
        <SubscriptionManager />
      </div>
      
      {success && (
        <div className="success-message">
          {success}
        </div>
      )}
      
      {error && (
        <div className="error-message">
          {error}
        </div>
      )}
      
      <div className="settings-section">
        <h2>Profile Settings</h2>
        
        <div className="profile-photo-section">
        <div className="photo-preview">
          {photoURL ? (
            <img src={photoURL} alt="Profile" />
          ) : (
            <div className="photo-placeholder">
              <Camera size={40} />
            </div>
          )}
        </div>
        
        <div className="photo-upload">
          <input
            type="file"
            id="photo-upload"
            accept="image/*"
            onChange={handlePhotoChange}
            disabled={uploadingPhoto}
            className="photo-input"
          />
          <label htmlFor="photo-upload" className="upload-label">
            {uploadingPhoto ? (
              <span>Uploading... {Math.round(uploadProgress)}%</span>
            ) : (
              <span>Change Profile Picture</span>
            )}
          </label>
        </div>
      </div>
      
      <form onSubmit={handleSubmit} className="settings-form">
        <div className="form-group">
          <label htmlFor="displayName">Display Name</label>
          <input
            id="displayName"
            type="text"
            value={displayName}
            onChange={(e) => setDisplayName(e.target.value)}
            className="form-control"
            required
          />
        </div>
        
        <div className="form-group">
          <label htmlFor="bio">Bio</label>
          <textarea
            id="bio"
            value={bio}
            onChange={(e) => setBio(e.target.value)}
            placeholder="Tell us about yourself..."
            className="form-control"
            rows="3"
            maxLength="150"
          />
          <span className="char-count">{bio.length}/150</span>
        </div>
        
        <div className="form-group">
          <label htmlFor="phoneNumber">Phone Number (for SMS notifications)</label>
          <input
            id="phoneNumber"
            type="tel"
            value={phoneNumber}
            onChange={(e) => setPhoneNumber(e.target.value)}
            placeholder="+1 (555) 123-4567"
            className="form-control"
          />
          <p className="field-help">
            Enter your phone number with country code for SMS chat notifications
          </p>
        </div>
        
        <div className="form-group">
          <label className="checkbox-label">
            <input
              type="checkbox"
              checked={smsEnabled}
              onChange={(e) => setSmsEnabled(e.target.checked)}
              className="checkbox-input"
            />
            <span>Enable SMS notifications</span>
          </label>
          <p className="field-help">
            You can also disable SMS from any chat or by texting "/bot disable" to the notification number
          </p>
        </div>
        
        <button 
          type="submit" 
          className="save-button"
          disabled={saving}
        >
          {saving ? 'Saving...' : 'Save Settings'}
        </button>
      </form>
      
      </div>
    </div>
  );
};

export default Settings;