// src/services/setService.js
//
// Sets: ordered lists of a user's tracks (jams) that can be played through
// in sequence and streamed live. Stored in Firestore as track-id references;
// jams are resolved at load time.
//
// Set document shape:
// { title, createdBy: { uid, name }, trackIds: [jamId],
//   visuals: [{ id, type, url, thumbUrl, title }],   // from the media library
//   createdAt, updatedAt }

import {
  getFirestore,
  collection,
  addDoc,
  doc,
  getDocs,
  query,
  where,
  updateDoc,
  deleteDoc,
  serverTimestamp,
} from 'firebase/firestore';
import { app } from '../firebase';

import { getJam } from './jamService';

const COLLECTION = 'sets';
const db = () => getFirestore(app);

export async function saveSet({ id = null, title, trackIds, user, visuals = [] }) {
  if (!user || !user.uid) throw new Error('Must be signed in to save a set');
  if (!trackIds || !trackIds.length) throw new Error('A set needs at least one track');

  if (id) {
    await updateDoc(doc(db(), COLLECTION, id), {
      title: title || 'untitled set',
      trackIds,
      visuals,
      updatedAt: serverTimestamp(),
    });
    return id;
  }

  const ref = await addDoc(collection(db(), COLLECTION), {
    title: title || 'untitled set',
    createdBy: { uid: user.uid, name: user.displayName || user.email || 'anonymous' },
    trackIds,
    visuals,
    createdAt: serverTimestamp(),
    updatedAt: serverTimestamp(),
  });
  return ref.id;
}

export async function listSetsByUser(uid) {
  const q = query(collection(db(), COLLECTION), where('createdBy.uid', '==', uid));
  const snap = await getDocs(q);
  return snap.docs
    .map(d => ({ id: d.id, ...d.data() }))
    .sort((a, b) => (b.updatedAt?.seconds || 0) - (a.updatedAt?.seconds || 0));
}

export async function deleteSet(id) {
  await deleteDoc(doc(db(), COLLECTION, id));
}

/** Resolve a set's trackIds into full jam documents (missing tracks skipped). */
export async function resolveSetTracks(set) {
  const jams = await Promise.all((set.trackIds || []).map(id => getJam(id).catch(() => null)));
  return jams.filter(Boolean);
}

export default { saveSet, listSetsByUser, deleteSet, resolveSetTracks };
