// src/services/recording/replayEgressService.js
//
// Starts and stops the server-side LiveKit egress that copies a broadcast into
// the Google Cloud Storage bucket the Replays pages read from.
//
// The recording is *not* made in the browser: the studio only asks the backend
// (src/server/livekit-api.js) to attach an egress to the LiveKit room, and
// LiveKit uploads the finished MP4 to finished-events/<key>/<key>.mp4 itself.
// That is what survives the host closing their laptop mid-set.
//
// Every call here is best-effort. Going live must never fail because the
// recorder is down, so callers get null back instead of an exception.

const trimBase = (value) =>
  String(value || '')
    .trim()
    .replace(/\/+$/, '')
    .replace(/\/api\/livekit$/, '');

/** The recording API origin — same one LiveKitRecordingService talks to. */
export function getRecordingApiBase() {
  const configured =
    import.meta.env.VITE_RECORDING_API_URL || import.meta.env.VITE_LIVEKIT_RECORDING_SERVER_URL;
  if (configured) return trimBase(configured);

  if (typeof window !== 'undefined') {
    const { hostname } = window.location;
    if (hostname === 'talkstudio.space' || hostname === 'www.talkstudio.space') {
      return 'https://api.talkstudio.space';
    }
  }
  return 'http://localhost:3001';
}

const endpoint = (path) => `${getRecordingApiBase()}/api/livekit/${path}`;

const post = async (path, body, { timeoutMs = 15000 } = {}) => {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(endpoint(path), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      signal: controller.signal,
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      throw new Error(data.message || data.error || `recording API ${response.status}`);
    }
    return data;
  } finally {
    clearTimeout(timer);
  }
};

/**
 * Attach a recording egress to a live room.
 *
 * @param {object} args
 * @param {string} args.roomName    LiveKit room the broadcast is publishing to
 * @param {string} [args.occurrenceId] scheduled airing this belongs to — the
 *   replay is filed under it, and its `replayUrl` is what /replays lists
 * @param {string} [args.eventId]   event id for ad-hoc broadcasts
 * @param {string} [args.title]
 * @param {boolean} [args.audioOnly] true for DJ/audio rooms — smaller files,
 *   and the room page plays replays through an <audio> element
 * @returns {Promise<{egressId:string, videoUrl:string}|null>}
 */
export async function startReplayRecording({
  roomName,
  occurrenceId = null,
  eventId = null,
  title = null,
  audioOnly = true,
}) {
  if (!roomName) return null;

  try {
    const data = await post('start-recording', {
      roomName,
      occurrenceId,
      eventId,
      title,
      audioOnly,
      recordingId: occurrenceId || eventId || roomName,
    });
    if (!data.egressId) return null;
    console.log('🎥 Replay recording started:', data.egressId, '→', data.videoUrl);
    return { egressId: data.egressId, videoUrl: data.videoUrl || null };
  } catch (error) {
    // A broadcast without a recording is still a broadcast.
    console.warn('[replayEgress] could not start the recording:', error.message);
    return null;
  }
}

/**
 * Stop the egress. Returns what the airing needs to become a replay:
 * { replayId, replayUrl, durationMs } — or null if there was nothing recording.
 */
export async function stopReplayRecording(egressId) {
  if (!egressId) return null;

  try {
    const data = await post('stop-recording', { egressId });
    const replayUrl = data.videoUrl || data.replayUrl || null;
    console.log('🎬 Replay recording stopped:', egressId, '→', replayUrl);
    return { replayId: egressId, replayUrl, durationMs: data.durationMs || 0 };
  } catch (error) {
    console.warn('[replayEgress] could not stop the recording:', error.message);
    // The file may still land — LiveKit ends the egress with the room, and the
    // egress webhook publishes it server-side.
    return { replayId: egressId, replayUrl: null, durationMs: 0 };
  }
}

export default { getRecordingApiBase, startReplayRecording, stopReplayRecording };
