// src/pages/SetStudioPage.jsx
//
// Set Studio (/set): build an ordered set from your tracks, play it through
// in sequence, save it, and STREAM IT LIVE into one of your events.
//
// The live path is real: engine audio → MediaStream tap → LiveKit publish
// via setStreamService (replaces the stubbed DJ-studio streaming service).
//
// Sets also carry visuals — pictures and short clips from the creator's media
// library — which play behind the set while it runs, and going live posts to
// the creator's activity feed.

import React, { useEffect, useRef, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import {
  Play,
  Square,
  ChevronLeft,
  ChevronUp,
  ChevronDown,
  Plus,
  X,
  Radio,
  Save,
  ListMusic,
  Loader,
  ImagePlus,
} from 'lucide-react';

import { createSketchEngine } from '../services/sketchEngine';
import { listJamsByUser } from '../services/jamService';
import { saveSet, listSetsByUser, resolveSetTracks } from '../services/setService';
import { startSetStream, stopSetStream, getSetListenerCount } from '../services/setStreamService';
import { recordStreamStarted, recordStreamEnded } from '../services/activityService';
import {
  getNextOccurrenceForHost,
  markOccurrenceLive,
  markOccurrenceEnded,
  setListenerCount,
  occurrenceRoomKey,
  occurrenceDate,
  formatClock,
  formatLeadTime,
} from '../services/scheduledRoomsService';
import MediaLibrary from '../components/media/MediaLibrary';
import { useAuth } from '../contexts/AuthContext';
import {
  getFirestore,
  collection,
  query,
  where,
  getDocs,
} from 'firebase/firestore';
import { app } from '../firebase';

const SetStudioPage = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { currentUser } = useAuth();

  // Library + sets
  const [library, setLibrary] = useState(null);
  const [savedSets, setSavedSets] = useState([]);
  const [error, setError] = useState(null);

  // The set being built
  const [queue, setQueue] = useState([]); // array of jam docs
  const [setTitle, setSetTitle] = useState('');
  const [setId, setSetId] = useState(null); // existing set being edited
  const [saving, setSaving] = useState(false);

  // Visuals: pictures/clips from the media library that play behind the set
  const [visuals, setVisuals] = useState([]);
  const [showVisualPicker, setShowVisualPicker] = useState(false);
  const [visualIdx, setVisualIdx] = useState(0);

  // Playback
  const engineRef = useRef(null);
  const queueRef = useRef([]);
  const playIndexRef = useRef(0);
  const [playingIdx, setPlayingIdx] = useState(null);
  const [progress, setProgress] = useState(0);

  // Live streaming
  const [events, setEvents] = useState([]);
  const [selectedEventId, setSelectedEventId] = useState(searchParams.get('event') || '');
  const [liveState, setLiveState] = useState(null); // null | 'connecting' | { roomName }
  const [liveError, setLiveError] = useState(null);
  const liveSessionRef = useRef(null); // { streamId, startedAt } while live

  // Tonight's scheduled room, pre-bound so going live is one button
  const [attached, setAttached] = useState(null);   // occurrence | null
  const [attachedLoaded, setAttachedLoaded] = useState(false);

  useEffect(() => { queueRef.current = queue; }, [queue]);

  useEffect(() => {
    if (!currentUser || currentUser.isAnonymous) {
      navigate(`/login?next=${encodeURIComponent('/set')}`);
      return;
    }
    (async () => {
      try {
        const [tracks, sets] = await Promise.all([
          listJamsByUser(currentUser.uid),
          listSetsByUser(currentUser.uid).catch(() => []),
        ]);
        setLibrary(tracks);
        setSavedSets(sets);
      } catch (e) {
        setError(e.message || 'Could not load your tracks');
      }
      // The Studio binds to the host's next airing when it's within two hours;
      // outside that window it falls back to the event picker.
      try {
        const occurrence = await getNextOccurrenceForHost(currentUser.uid, { withinHours: 2 });
        setAttached(occurrence);
      } catch (e) {
        // eslint-disable-next-line no-console
        console.warn('[SetStudio] could not read the schedule:', e);
      } finally {
        setAttachedLoaded(true);
      }

      // Load the user's events for the Go Live picker.
      try {
        const db = getFirestore(app);
        const snap = await getDocs(
          query(collection(db, 'events'), where('artistId', '==', currentUser.uid)),
        );
        setEvents(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      } catch (e) {
        // Events are optional until the user goes live.
        // eslint-disable-next-line no-console
        console.warn('[SetStudio] could not load events:', e);
      }
    })();
    return () => {
      stopSetStream();
      if (engineRef.current) {
        engineRef.current.dispose();
        engineRef.current = null;
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentUser]);

  // While a scheduled room is on air, publish how many people are in it.
  useEffect(() => {
    const isOnAir = liveState && liveState !== 'connecting';
    if (!isOnAir || !attached) return undefined;
    const push = () => setListenerCount(attached.id, getSetListenerCount());
    push();
    const timer = setInterval(push, 15000);
    return () => clearInterval(timer);
  }, [liveState, attached]);

  // Cycle through the set's visuals while it plays.
  useEffect(() => {
    if (playingIdx === null || visuals.length < 2) return undefined;
    const timer = setInterval(() => {
      setVisualIdx(i => (i + 1) % visuals.length);
    }, 8000);
    return () => clearInterval(timer);
  }, [playingIdx, visuals.length]);

  useEffect(() => {
    if (visualIdx >= visuals.length) setVisualIdx(0);
  }, [visuals.length, visualIdx]);

  const ensureEngine = async () => {
    if (engineRef.current) return engineRef.current;
    const eng = await createSketchEngine();
    eng.setOnTick(({ pct, ended }) => {
      setProgress(pct);
      if (ended) playFrom(playIndexRef.current + 1);
    });
    engineRef.current = eng;
    return eng;
  };

  // ---------- Sequential set playback ----------
  const playFrom = async (i) => {
    const eng = await ensureEngine();
    const q = queueRef.current;
    if (i >= q.length) {
      setPlayingIdx(null);
      setProgress(0);
      return;
    }
    playIndexRef.current = i;
    eng.loadLayers(q[i].layers || [], q[i].theory);
    await eng.playLayers();
    setPlayingIdx(i);
    setProgress(0);
  };

  const playPauseSet = async () => {
    const eng = await ensureEngine();
    if (eng.isPlaying()) {
      eng.stop();
      setPlayingIdx(null);
    } else if (queue.length) {
      await playFrom(0);
    }
  };

  // ---------- Queue management ----------
  const addToQueue = (jam) => setQueue(prev => [...prev, jam]);
  const removeFromQueue = (i) => setQueue(prev => prev.filter((_, idx) => idx !== i));
  const move = (i, dir) => {
    setQueue(prev => {
      const next = [...prev];
      const j = i + dir;
      if (j < 0 || j >= next.length) return prev;
      [next[i], next[j]] = [next[j], next[i]];
      return next;
    });
  };

  // ---------- Save / load sets ----------
  const handleSaveSet = async () => {
    if (!queue.length) return;
    setSaving(true);
    try {
      const id = await saveSet({
        id: setId,
        title: setTitle.trim() || 'untitled set',
        trackIds: queue.map(j => j.id),
        user: currentUser,
        visuals,
      });
      setSetId(id);
      setSavedSets(await listSetsByUser(currentUser.uid));
    } catch (e) {
      setError(e.message);
    } finally {
      setSaving(false);
    }
  };

  const loadSet = async (s) => {
    try {
      const tracks = await resolveSetTracks(s);
      setQueue(tracks);
      setSetTitle(s.title || '');
      setSetId(s.id);
      setVisuals(s.visuals || []);
      setVisualIdx(0);
    } catch (e) {
      setError(e.message);
    }
  };

  // ---------- Go live ----------
  const goLive = async () => {
    setLiveError(null);
    if (!queue.length) { setLiveError('Add tracks to your set first.'); return; }
    if (!attached && !selectedEventId) {
      setLiveError('Pick an event to stream to — or schedule a room.');
      return;
    }
    setLiveState('connecting');
    try {
      const eng = await ensureEngine();
      const stream = eng.getMediaStream();
      const info = await startSetStream({
        eventId: selectedEventId || null,
        roomName: attached ? occurrenceRoomKey(attached) : null,
        // The airing the recording is filed under — its replayUrl is what the
        // Replays grid and /r/:slug/replay/:id read.
        occurrenceId: attached ? attached.id : null,
        record: attached ? attached.publishReplay !== false : true,
        user: currentUser,
        mediaStream: stream,
        setTitle: attached ? attached.title : (setTitle.trim() || 'Live set'),
      });
      if (attached) await markOccurrenceLive(attached.id);
      setLiveState(info);

      // "Live now" on the creator's activity feed, closed out when the set ends.
      const streamId = `set_${attached ? attached.id : (setId || selectedEventId)}`;
      liveSessionRef.current = { streamId, startedAt: Date.now() };
      recordStreamStarted({
        user: currentUser,
        streamId,
        eventId: selectedEventId,
        title: setTitle.trim() || 'Live set',
        streamType: 'set',
      });

      // Start the set from the top if not already playing.
      if (!eng.isPlaying()) await playFrom(0);
    } catch (e) {
      setLiveState(null);
      setLiveError(e.message || 'Could not go live');
    }
  };

  const endLive = async () => {
    if (attached && !window.confirm(`Stop streaming "${attached.title}"?`)) return;
    // Stopping the stream also stops the egress; what comes back is the replay
    // LiveKit just uploaded to the bucket.
    const replay = await stopSetStream();
    if (attached) {
      // With replays on the airing becomes a replay, pointed at the recording.
      await markOccurrenceEnded(attached, {
        publishReplay: attached.publishReplay !== false,
        replayId: replay ? replay.replayId : null,
        replayUrl: replay ? replay.replayUrl : null,
        durationMs: replay ? replay.durationMs : 0,
      });
      setAttached(null);
    }
    const session = liveSessionRef.current;
    liveSessionRef.current = null;
    if (session) {
      await recordStreamEnded({
        user: currentUser,
        streamId: session.streamId,
        eventId: selectedEventId,
        title: setTitle.trim() || 'Live set',
        streamType: 'set',
        startedAt: session.startedAt,
      });
    }
    setLiveState(null);
  };

  const isLive = liveState && liveState !== 'connecting';
  const currentVisual = visuals[visualIdx] || visuals[0] || null;

  const addVisual = (media) =>
    setVisuals(prev => (prev.some(v => v.id === media.id) ? prev : [...prev, media]));
  const removeVisual = (id) => setVisuals(prev => prev.filter(v => v.id !== id));

  // ---------- Render ----------
  return (
    <div
      style={{
        minHeight: '100vh',
        background:
          'radial-gradient(circle at 20% 0%, rgba(127, 119, 221, 0.18), transparent 55%),' +
          'radial-gradient(circle at 80% 100%, rgba(93, 202, 165, 0.10), transparent 60%),' +
          '#0a0a12',
        color: '#e8e8f0',
        fontFamily: '-apple-system, BlinkMacSystemFont, system-ui, sans-serif',
        padding: '1rem',
      }}
    >
      <div style={{ maxWidth: 720, margin: '0 auto' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <button
            onClick={() => navigate(-1)}
            style={{
              background: 'transparent', border: 'none', color: '#8b8b9a',
              display: 'inline-flex', alignItems: 'center', gap: 4,
              padding: '0.5rem 0', cursor: 'pointer', fontSize: '0.85rem',
            }}
          >
            <ChevronLeft size={16} /> Back
          </button>
          <button
            onClick={() => navigate('/jams')}
            style={{
              background: 'transparent', border: '1px solid #25252e', color: '#8b8b9a',
              display: 'inline-flex', alignItems: 'center', gap: 6,
              padding: '6px 12px', borderRadius: 8, cursor: 'pointer', fontSize: 12,
            }}
          >
            <ListMusic size={14} /> Jam feed
          </button>
        </div>

        <h1 style={{ fontSize: '1.4rem', fontWeight: 600, margin: '0.5rem 0 0.25rem' }}>
          Set Studio
        </h1>
        <p style={{ color: '#8b8b9a', fontSize: '0.9rem', margin: '0 0 1rem' }}>
          Line up your tracks, play them through, and stream the set live to your event.
        </p>

        {error && <div style={{ color: '#fca5a5', fontSize: 13, marginBottom: 10 }}>{error}</div>}

        {/* ---------- LIVE BAR ---------- */}
        <div
          style={{
            display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap',
            padding: '12px 14px', marginBottom: 16,
            background: isLive ? '#1f0d0d' : '#15151e',
            border: '1px solid ' + (isLive ? '#E24B4A' : '#25252e'),
            borderRadius: 12,
          }}
        >
          <Radio size={16} color={isLive ? '#E24B4A' : '#8b8b9a'} />
          {isLive ? (
            <>
              <span style={{ fontSize: 13, color: '#F0999A', fontWeight: 600 }}>LIVE</span>
              <span style={{ fontSize: 12, color: '#8b8b9a' }}>
                {attached
                  ? `${attached.title} · talkstudio.space/r/${attached.slug}`
                  : `streaming to ${liveState.roomName}`}
              </span>
              <button
                onClick={endLive}
                style={{
                  marginLeft: 'auto', background: '#E24B4A', color: 'white', border: 'none',
                  padding: '8px 14px', borderRadius: 8, cursor: 'pointer', fontSize: 12, fontWeight: 600,
                }}
              >
                End stream
              </button>
            </>
          ) : (
            <>
              {/* Tonight's scheduled room, already attached: no room to create,
                  no link to copy, no stream key. */}
              {attached ? (
                <div
                  style={{
                    flex: 1, minWidth: 200, display: 'flex', alignItems: 'center', gap: 10,
                    padding: '6px 12px', borderRadius: 8,
                    background: 'rgba(99,102,241,0.12)',
                    boxShadow: 'inset 0 0 0 1px rgba(165,180,252,0.25)',
                  }}
                >
                  <span style={{ fontFamily: 'ui-monospace, monospace', fontSize: 11, color: '#c7d2fe', letterSpacing: '0.08em' }}>
                    {attached.state === 'live'
                      ? 'ON AIR'
                      : `${formatLeadTime(attached.startAt).toUpperCase()} · ${formatClock(attached.startAt)}`}
                  </span>
                  <span style={{ fontSize: 13 }}>{attached.title}</span>
                  <span style={{ fontSize: 12, color: '#8b8b9a' }}>
                    {attached.rsvpCount || 0} going
                  </span>
                </div>
              ) : (
                <>
                  {attachedLoaded && (
                    <span style={{ fontSize: 12, color: '#8b8b9a' }}>
                      No room scheduled ·{' '}
                      <span
                        onClick={() => navigate('/schedule')}
                        style={{ color: '#a5b4fc', cursor: 'pointer', textDecoration: 'underline' }}
                      >
                        schedule one
                      </span>
                    </span>
                  )}
                  <select
                    value={selectedEventId}
                    onChange={e => setSelectedEventId(e.target.value)}
                    style={{
                      flex: 1, minWidth: 180, padding: '8px 10px',
                      background: '#0a0a12', color: '#e8e8f0',
                      border: '1px solid #25252e', borderRadius: 8, fontSize: 13,
                    }}
                  >
                    <option value="">
                      {events.length ? 'Stream to event…' : 'No events — create one first'}
                    </option>
                    {events.map(ev => (
                      <option key={ev.id} value={ev.id}>{ev.title || ev.id}</option>
                    ))}
                  </select>
                </>
              )}
              <button
                onClick={goLive}
                disabled={liveState === 'connecting'}
                style={{
                  background: '#E24B4A', color: 'white', border: 'none',
                  padding: '8px 16px', borderRadius: 8, cursor: 'pointer',
                  fontSize: 12, fontWeight: 600, opacity: liveState === 'connecting' ? 0.6 : 1,
                  display: 'inline-flex', alignItems: 'center', gap: 6,
                }}
              >
                {liveState === 'connecting' ? <Loader size={13} /> : <Radio size={13} />}
                {liveState === 'connecting' ? 'Connecting…' : 'Go live'}
              </button>
            </>
          )}
        </div>
        {liveError && <div style={{ color: '#fca5a5', fontSize: 12, margin: '-8px 0 12px' }}>{liveError}</div>}

        {/* ---------- VISUAL STAGE ---------- */}
        {visuals.length > 0 && (
          <div
            style={{
              position: 'relative', marginBottom: 16, borderRadius: 12, overflow: 'hidden',
              background: '#000', aspectRatio: '16 / 9',
              border: '0.5px solid #25252e',
            }}
          >
            {currentVisual && (currentVisual.type === 'clip' ? (
              <video
                key={currentVisual.id}
                src={currentVisual.url}
                poster={currentVisual.thumbUrl || undefined}
                autoPlay
                muted
                loop
                playsInline
                style={{ width: '100%', height: '100%', objectFit: 'cover' }}
              />
            ) : (
              <img
                key={currentVisual.id}
                src={currentVisual.url}
                alt={currentVisual.title || 'set visual'}
                style={{ width: '100%', height: '100%', objectFit: 'cover' }}
              />
            ))}
            <div
              style={{
                position: 'absolute', left: 10, bottom: 10, fontSize: 11, color: '#e8e8f0',
                background: 'rgba(0,0,0,0.55)', padding: '3px 8px', borderRadius: 999,
              }}
            >
              {playingIdx !== null && queue[playingIdx]
                ? `Now playing · ${queue[playingIdx].title}`
                : `Visual ${visualIdx + 1} of ${visuals.length}`}
            </div>
          </div>
        )}

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
          {/* ---------- LIBRARY ---------- */}
          <div>
            <SectionLabel>Your tracks</SectionLabel>
            <div style={panelStyle}>
              {library === null && <Empty>Loading…</Empty>}
              {library && library.length === 0 && (
                <Empty>
                  No tracks yet —{' '}
                  <span
                    onClick={() => navigate('/sketch')}
                    style={{ color: '#7F77DD', cursor: 'pointer', textDecoration: 'underline' }}
                  >
                    make one in the Jam Studio
                  </span>
                </Empty>
              )}
              {library && library.map(jam => (
                <div key={jam.id} style={rowStyle}>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 13, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                      {jam.title}
                    </div>
                    <div style={{ fontSize: 10, color: '#6b6b7a' }}>
                      {(jam.layers || []).length} layers
                    </div>
                  </div>
                  <button onClick={() => addToQueue(jam)} title="Add to set" style={smallBtn}>
                    <Plus size={14} />
                  </button>
                </div>
              ))}
            </div>

            {savedSets.length > 0 && (
              <>
                <SectionLabel style={{ marginTop: 14 }}>Saved sets</SectionLabel>
                <div style={panelStyle}>
                  {savedSets.map(s => (
                    <div key={s.id} style={rowStyle}>
                      <div
                        onClick={() => loadSet(s)}
                        style={{ flex: 1, fontSize: 13, cursor: 'pointer', color: setId === s.id ? '#AFA9EC' : '#e8e8f0' }}
                        title="Load this set"
                      >
                        {s.title}
                        <span style={{ fontSize: 10, color: '#6b6b7a', marginLeft: 6 }}>
                          {(s.trackIds || []).length} tracks
                        </span>
                      </div>
                    </div>
                  ))}
                </div>
              </>
            )}
          </div>

          {/* ---------- THE SET ---------- */}
          <div>
            <SectionLabel>The set</SectionLabel>
            <div style={panelStyle}>
              {queue.length === 0 && <Empty>Add tracks from your library →</Empty>}
              {queue.map((jam, i) => (
                <div
                  key={`${jam.id}-${i}`}
                  style={{
                    ...rowStyle,
                    background: playingIdx === i ? 'rgba(127,119,221,0.12)' : 'transparent',
                    borderRadius: 6,
                  }}
                >
                  <span style={{ fontSize: 11, color: '#6b6b7a', width: 16 }}>{i + 1}</span>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 13, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                      {jam.title}
                    </div>
                    {playingIdx === i && (
                      <div style={{ height: 2, background: '#0a0a12', borderRadius: 1, marginTop: 3 }}>
                        <div style={{ width: `${Math.round(progress * 100)}%`, height: '100%', background: '#7F77DD' }} />
                      </div>
                    )}
                  </div>
                  <button onClick={() => move(i, -1)} style={smallBtn} title="Move up"><ChevronUp size={13} /></button>
                  <button onClick={() => move(i, 1)} style={smallBtn} title="Move down"><ChevronDown size={13} /></button>
                  <button onClick={() => removeFromQueue(i)} style={smallBtn} title="Remove"><X size={13} /></button>
                </div>
              ))}
            </div>

            {queue.length > 0 && (
              <div style={{ display: 'grid', gap: 8, marginTop: 10 }}>
                <button
                  onClick={playPauseSet}
                  style={{
                    padding: '12px', borderRadius: 10, border: 'none', cursor: 'pointer',
                    background: '#534AB7', color: 'white', fontSize: 13, fontWeight: 500,
                    display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
                  }}
                >
                  {playingIdx !== null ? <Square size={14} fill="white" /> : <Play size={14} />}
                  {playingIdx !== null ? 'Stop set' : 'Play set'}
                </button>
                <div style={{ display: 'flex', gap: 8 }}>
                  <input
                    value={setTitle}
                    onChange={e => setSetTitle(e.target.value)}
                    placeholder="Name your set…"
                    style={{
                      flex: 1, padding: '10px 12px', background: '#15151e',
                      border: '0.5px solid #25252e', borderRadius: 10,
                      color: '#e8e8f0', fontSize: 13, fontFamily: 'inherit',
                    }}
                  />
                  <button
                    onClick={handleSaveSet}
                    disabled={saving}
                    style={{
                      padding: '10px 14px', borderRadius: 10, cursor: 'pointer',
                      background: '#0d1f1a', color: '#5DCAA5', border: '1px solid #1D9E75',
                      fontSize: 13, display: 'inline-flex', alignItems: 'center', gap: 6,
                      opacity: saving ? 0.6 : 1,
                    }}
                  >
                    <Save size={14} /> {setId ? 'Update' : 'Save'}
                  </button>
                </div>
              </div>
            )}

            {/* ---------- VISUALS ---------- */}
            <SectionLabel style={{ marginTop: 14 }}>Visuals</SectionLabel>
            <div style={panelStyle}>
              {visuals.length === 0 && (
                <Empty>No visuals — add pictures or short clips to play behind the set.</Empty>
              )}
              {visuals.length > 0 && (
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 8 }}>
                  {visuals.map((v, i) => (
                    <div
                      key={v.id}
                      onClick={() => setVisualIdx(i)}
                      title={v.title}
                      style={{
                        position: 'relative', width: 56, height: 56, borderRadius: 8,
                        overflow: 'hidden', cursor: 'pointer',
                        border: '2px solid ' + (i === visualIdx ? '#7F77DD' : 'transparent'),
                      }}
                    >
                      <img
                        src={v.thumbUrl || v.url}
                        alt={v.title || 'visual'}
                        style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                      />
                      <button
                        onClick={e => { e.stopPropagation(); removeVisual(v.id); }}
                        title="Remove visual"
                        style={{
                          position: 'absolute', top: 1, right: 1, width: 16, height: 16,
                          border: 'none', borderRadius: '50%', background: 'rgba(0,0,0,0.65)',
                          color: '#fff', cursor: 'pointer', display: 'inline-flex',
                          alignItems: 'center', justifyContent: 'center', padding: 0,
                        }}
                      >
                        <X size={10} />
                      </button>
                    </div>
                  ))}
                </div>
              )}
              <button
                onClick={() => setShowVisualPicker(v => !v)}
                style={{
                  width: '100%', padding: '8px 10px', borderRadius: 8, cursor: 'pointer',
                  background: 'transparent', border: '1px solid #25252e', color: '#8b8b9a',
                  fontSize: 12, display: 'inline-flex', alignItems: 'center',
                  justifyContent: 'center', gap: 6,
                }}
              >
                <ImagePlus size={13} />
                {showVisualPicker ? 'Done picking' : 'Add clips & pictures'}
              </button>
              {showVisualPicker && (
                <div style={{ marginTop: 10 }}>
                  <MediaLibrary
                    mode="select"
                    selected={visuals}
                    onSelect={addVisual}
                    onDeselect={removeVisual}
                    emptyHint="Upload a picture or short clip — it stays in your library for other sets and posts."
                  />
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

/* ---------- bits ---------- */

const SectionLabel = ({ children, style }) => (
  <div style={{ fontSize: 10, color: '#6b6b7a', letterSpacing: 2, margin: '0 0 8px', textTransform: 'uppercase', ...style }}>
    {children}
  </div>
);

const Empty = ({ children }) => (
  <div style={{ fontSize: 12, color: '#6b6b7a', padding: '14px 4px', textAlign: 'center' }}>{children}</div>
);

const panelStyle = {
  background: '#15151e',
  border: '0.5px solid #25252e',
  borderRadius: 12,
  padding: 10,
  minHeight: 60,
};

const rowStyle = {
  display: 'flex',
  alignItems: 'center',
  gap: 6,
  padding: '6px 4px',
};

const smallBtn = {
  background: 'transparent',
  border: 'none',
  color: '#6b6b7a',
  cursor: 'pointer',
  padding: 2,
  display: 'inline-flex',
};

export default SetStudioPage;
