// Google Analytics utility functions
// GA Measurement ID: G-2J9T4YB9HN

// Check if gtag is available (Google Analytics loaded)
const isGtagAvailable = () => {
  return typeof window !== 'undefined' && window.gtag;
};

// Track page views (useful for single-page applications)
//
// The gtag snippet in index.html configures the stream with
// send_page_view: false, so this is the single source of page_view events --
// for the initial load as well as every client-side navigation. It sends an
// explicit event rather than re-calling gtag('config', ...): a repeat config
// call is documented as a way to change settings, and whether it also emits a
// page_view is not something to depend on.
export const trackPageView = (url) => {
  if (isGtagAvailable()) {
    window.gtag('event', 'page_view', {
      page_path: url,
      page_location: window.location.origin + url,
      page_title: document.title
    });
  }
};

// Track custom events
export const trackEvent = (action, category, label = null, value = null) => {
  if (isGtagAvailable()) {
    const eventParams = {
      event_category: category,
    };
    
    if (label) eventParams.event_label = label;
    if (value) eventParams.value = value;
    
    window.gtag('event', action, eventParams);
  }
};

// Track user properties (for user-scoped dimensions)
export const setUserProperties = (properties) => {
  if (isGtagAvailable()) {
    window.gtag('set', 'user_properties', properties);
  }
};

// Track conversions (e.g., sign-ups, purchases)
export const trackConversion = (conversionId, value = null) => {
  if (isGtagAvailable()) {
    const conversionParams = {
      'send_to': conversionId
    };
    
    if (value) conversionParams.value = value;
    
    window.gtag('event', 'conversion', conversionParams);
  }
};

// Track exceptions/errors
export const trackException = (description, fatal = false) => {
  if (isGtagAvailable()) {
    window.gtag('event', 'exception', {
      description: description,
      fatal: fatal
    });
  }
};

// Track timing (for performance monitoring)
export const trackTiming = (timingCategory, timingVar, value, label = null) => {
  if (isGtagAvailable()) {
    const timingParams = {
      name: timingVar,
      value: value,
      event_category: timingCategory
    };
    
    if (label) timingParams.event_label = label;
    
    window.gtag('event', 'timing_complete', timingParams);
  }
};

// Track social interactions
export const trackSocialInteraction = (network, action, target) => {
  if (isGtagAvailable()) {
    window.gtag('event', 'share', {
      method: network,
      content_type: action,
      item_id: target
    });
  }
};
