// src/services/jamService.js
//
// Persistence for jams (layered music sketches) in Firestore.
//
// A jam is stored as a descriptor — note events per layer, not audio — so
// payloads are tiny and the sketch engine re-renders the sound client-side.
//
// Remix chain: publishing from an existing jam sets parentJamId/rootJamId and
// carries the attribution list forward, so credit survives N generations.
//
// Jam document shape:
// {
//   title, createdBy: { uid, name }, createdAt,
//   parentJamId: string|null, rootJamId: string|null,
//   attribution: [{ uid, name }],          // everyone in the remix chain
//   theory: { keyName, scaleName, tempo, lead },
//   layers: [{ id, kind: 'generated'|'performed', label, instr, events: [...] }],
//   likes: number, remixCount: number, plays: number,
// }

import {
  getFirestore,
  collection,
  addDoc,
  doc,
  getDoc,
  getDocs,
  query,
  where,
  orderBy,
  limit as fsLimit,
  updateDoc,
  increment,
  serverTimestamp,
} from 'firebase/firestore';
import { app } from '../firebase';

const COLLECTION = 'jams';

const db = () => getFirestore(app);

/**
 * Publish a jam. If `parentJam` is provided this is a remix: the attribution
 * chain is extended and the parent's remixCount is bumped.
 * Returns the new jam id.
 */
export async function publishJam({ title, theory, layers, user, parentJam = null }) {
  if (!user || !user.uid) throw new Error('Must be signed in to publish a jam');
  if (!layers || !layers.length) throw new Error('Nothing to publish — add at least one layer');

  const author = {
    uid: user.uid,
    name: user.displayName || user.email || 'anonymous',
  };

  const attribution = parentJam
    ? [...(parentJam.attribution || []), author].filter(
        (a, i, arr) => arr.findIndex(b => b.uid === a.uid) === i,
      )
    : [author];

  const docData = {
    title: title || 'untitled jam',
    createdBy: author,
    createdAt: serverTimestamp(),
    parentJamId: parentJam ? parentJam.id : null,
    rootJamId: parentJam ? (parentJam.rootJamId || parentJam.id) : null,
    attribution,
    theory: {
      keyName: theory.keyName,
      scaleName: theory.scaleName,
      tempo: theory.tempo,
      lead: theory.lead || null,   // which patch carries the melody
    },
    layers: layers.map(l => ({
      id: l.id,
      kind: l.kind,
      label: l.label,
      instr: l.instr,
      createdBy: l.createdBy || author.uid,
      events: l.events.map(e => ({
        t: e.t,
        instr: e.instr,
        notes: e.notes || [],
        dur: e.dur,
        vel: e.vel,
      })),
    })),
    likes: 0,
    remixCount: 0,
    plays: 0,
  };

  const ref = await addDoc(collection(db(), COLLECTION), docData);

  if (parentJam && parentJam.id) {
    try {
      await updateDoc(doc(db(), COLLECTION, parentJam.id), { remixCount: increment(1) });
    } catch (e) {
      // Non-fatal — the remix still published.
      // eslint-disable-next-line no-console
      console.warn('[jamService] could not bump parent remixCount:', e);
    }
  }

  return ref.id;
}

/** Fetch the most recent jams for the feed. */
export async function listJams({ max = 30 } = {}) {
  const q = query(
    collection(db(), COLLECTION),
    orderBy('createdAt', 'desc'),
    fsLimit(max),
  );
  const snap = await getDocs(q);
  return snap.docs.map(d => ({ id: d.id, ...d.data() }));
}

/**
 * Fetch all jams published by a user — their track library.
 * Falls back to client-side sort if the composite index isn't deployed yet.
 */
export async function listJamsByUser(uid, { max = 50 } = {}) {
  try {
    const q = query(
      collection(db(), COLLECTION),
      where('createdBy.uid', '==', uid),
      orderBy('createdAt', 'desc'),
      fsLimit(max),
    );
    const snap = await getDocs(q);
    return snap.docs.map(d => ({ id: d.id, ...d.data() }));
  } catch (e) {
    // Likely a missing composite index — fetch unordered and sort locally.
    const q = query(
      collection(db(), COLLECTION),
      where('createdBy.uid', '==', uid),
      fsLimit(max),
    );
    const snap = await getDocs(q);
    return snap.docs
      .map(d => ({ id: d.id, ...d.data() }))
      .sort((a, b) => (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0));
  }
}

/** Shareable URL for a track. */
export function trackUrl(id) {
  return `${window.location.origin}/track/${id}`;
}

/** Fetch a single jam (e.g. to remix it). */
export async function getJam(id) {
  const snap = await getDoc(doc(db(), COLLECTION, id));
  if (!snap.exists()) return null;
  return { id: snap.id, ...snap.data() };
}

/** Like a jam (fire-and-forget counter; per-user dedupe is a later phase). */
export async function likeJam(id) {
  await updateDoc(doc(db(), COLLECTION, id), { likes: increment(1) });
}

/** Count a play. */
export async function countPlay(id) {
  try {
    await updateDoc(doc(db(), COLLECTION, id), { plays: increment(1) });
  } catch (_) { /* non-fatal */ }
}

export default { publishJam, listJams, listJamsByUser, getJam, likeJam, countPlay, trackUrl };
