// src/contexts/WalletContext.jsx
import React, { createContext, useContext, useState, useEffect } from 'react';
import { useAuth } from './AuthContext';
import { WalletService } from '../services/walletService';
import { tipService } from '../services/tipService';

const WalletContext = createContext();

export function useWallet() {
  const context = useContext(WalletContext);
  if (!context) {
    throw new Error('useWallet must be used within a WalletProvider');
  }
  return context;
}

export function WalletProvider({ children }) {
  const { currentUser } = useAuth();
  const [wallet, setWallet] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [tipsSent, setTipsSent] = useState([]);
  const [tipsReceived, setTipsReceived] = useState([]);

  // Initialize wallet when user changes
  useEffect(() => {
    if (!currentUser || currentUser.isAnonymous) {
      setWallet(null);
      setTransactions([]);
      setTipsSent([]);
      setTipsReceived([]);
      setLoading(false);
      return;
    }

    setLoading(true);
    setError(null);

    // Subscribe to wallet changes
    const unsubscribeWallet = WalletService.subscribeToWallet(
      currentUser.uid,
      (walletData) => {
        setWallet(walletData);
        setLoading(false);
      }
    );

    // Subscribe to wallet transactions
    const unsubscribeTransactions = WalletService.getWalletTransactions(
      currentUser.uid,
      (transactionsData) => {
        setTransactions(transactionsData);
      }
    );

    // Subscribe to tips sent
    const unsubscribeTipsSent = WalletService.getUserTipsSent(
      currentUser.uid,
      (tipsData) => {
        setTipsSent(tipsData);
      }
    );

    // Subscribe to tips received (for artists)
    const unsubscribeTipsReceived = WalletService.getUserTipsReceived(
      currentUser.uid,
      (tipsData) => {
        setTipsReceived(tipsData);
      }
    );

    return () => {
      if (unsubscribeWallet) unsubscribeWallet();
      if (unsubscribeTransactions) unsubscribeTransactions();
      if (unsubscribeTipsSent) unsubscribeTipsSent();
      if (unsubscribeTipsReceived) unsubscribeTipsReceived();
    };
  }, [currentUser]);

  // Load money into wallet
  const loadWallet = async (amount, paymentMethodId, paymentIntentId = null) => {
    try {
      if (!currentUser || currentUser.isAnonymous) {
        throw new Error('Must be logged in to load wallet');
      }

      setError(null);
      const result = await WalletService.loadWallet(
        currentUser.uid,
        amount,
        paymentMethodId,
        paymentIntentId
      );

      return result;
    } catch (err) {
      setError(err.message);
      throw err;
    }
  };

  // Send tip using wallet with revenue splits
  const sendTip = async (recipientId, amount, message = '', streamId = null, eventId = null, venueId = null) => {
    try {
      if (!currentUser || currentUser.isAnonymous) {
        throw new Error('Must be logged in to send tips');
      }

      if (!wallet || wallet.balance < amount) {
        throw new Error('Insufficient wallet balance');
      }

      setError(null);
      const result = await WalletService.processTipWithSplits(
        currentUser.uid,
        recipientId,
        amount,
        message,
        streamId,
        eventId,
        venueId
      );

      return result;
    } catch (err) {
      setError(err.message);
      throw err;
    }
  };

  // Process tip using the tip service (for tip forms)
  const processTip = async ({ eventId, creatorId, amount, tipperId, venueId = null }) => {
    try {
      if (!currentUser || currentUser.isAnonymous) {
        return {
          success: false,
          message: 'Must be logged in to send tips'
        };
      }

      if (!wallet || wallet.balance < amount) {
        return {
          success: false,
          message: 'Insufficient wallet balance'
        };
      }

      setError(null);
      const result = await tipService.processTip({
        eventId,
        creatorId,
        amount,
        tipperId: currentUser.uid,
        venueId
      });

      return result;
    } catch (err) {
      setError(err.message);
      return {
        success: false,
        message: err.message || 'Failed to process tip'
      };
    }
  };

  // Get wallet statistics
  const getWalletStats = async () => {
    try {
      if (!currentUser || currentUser.isAnonymous) {
        return null;
      }

      return await WalletService.getWalletStats(currentUser.uid);
    } catch (err) {
      setError(err.message);
      throw err;
    }
  };

  // Check if user can afford amount
  const canAfford = (amount) => {
    if (!wallet) return false;
    return wallet.balance >= amount;
  };

  // Check if user can send tips (registered users only)
  const canSendTips = () => {
    return currentUser && !currentUser.isAnonymous;
  };

  // Format currency
  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2
    }).format(amount || 0);
  };

  // Get balance
  const getBalance = () => {
    return wallet?.balance || 0;
  };

  // Get total loaded
  const getTotalLoaded = () => {
    return wallet?.totalLoaded || 0;
  };

  // Get total spent
  const getTotalSpent = () => {
    return wallet?.totalSpent || 0;
  };

  // Clear error
  const clearError = () => {
    setError(null);
  };

  const value = {
    // State
    wallet,
    loading,
    error,
    transactions,
    tipsSent,
    tipsReceived,

    // Actions
    loadWallet,
    sendTip,
    processTip,
    getWalletStats,
    clearError,

    // Getters
    canAfford,
    canSendTips,
    formatCurrency,
    getBalance,
    getTotalLoaded,
    getTotalSpent,

    // Computed values
    hasWallet: !!wallet,
    balance: getBalance(),
    totalLoaded: getTotalLoaded(),
    totalSpent: getTotalSpent(),
    isWalletEmpty: getBalance() === 0,
    
    // Stats
    totalTipsSent: tipsSent.length,
    totalTipsReceived: tipsReceived.length,
    totalTipAmountSent: tipsSent.reduce((sum, tip) => sum + (tip.amount || 0), 0),
    totalTipAmountReceived: tipsReceived.reduce((sum, tip) => sum + (tip.amount || 0), 0)
  };

  return (
    <WalletContext.Provider value={value}>
      {children}
    </WalletContext.Provider>
  );
}

export default WalletContext;