/**
 * Standardized Room Naming Utilities
 * 
 * Ensures consistent naming between:
 * - LiveKit rooms (streaming)
 * - Chat room session IDs
 * - Database references
 * - URLs and sharing
 */

// Extract event ID from various formats
export const extractEventId = (input) => {
  if (!input) return null;
  
  // Handle different input formats
  if (typeof input === 'object' && input.id) {
    return input.id;
  }
  
  const str = String(input);
  
  // Extract from LiveKit room names: "event-x4orSYpUKxSFoOWRYtxb" -> "x4orSYpUKxSFoOWRYtxb"
  if (str.startsWith('event-')) {
    return str.replace('event-', '');
  }
  
  // Extract from session IDs: "RM_x4orSYpUKxSFoOWRYtxb" -> "x4orSYpUKxSFoOWRYtxb"
  if (str.startsWith('RM_')) {
    return str.replace('RM_', '');
  }
  
  // Extract from URLs: "/events/x4orSYpUKxSFoOWRYtxb" -> "x4orSYpUKxSFoOWRYtxb"
  if (str.includes('/events/')) {
    return str.split('/events/')[1]?.split('?')[0]?.split('/')[0];
  }
  
  // Return as-is if already in correct format
  return str;
};

// Generate LiveKit room name from event ID
export const generateLiveKitRoomName = (eventId) => {
  const cleanEventId = extractEventId(eventId);
  if (!cleanEventId) {
    throw new Error('Invalid eventId provided for LiveKit room generation');
  }
  
  return `event-${cleanEventId}`;
};

// Generate session ID to match LiveKit room name
export const generateSessionId = (eventId) => {
  const cleanEventId = extractEventId(eventId);
  if (!cleanEventId) {
    throw new Error('Invalid eventId provided for session ID generation');
  }
  
  return `RM_${cleanEventId}`;
};

// Generate chat room name (for consistency)
export const generateChatRoomName = (eventId) => {
  const cleanEventId = extractEventId(eventId);
  if (!cleanEventId) {
    throw new Error('Invalid eventId provided for chat room generation');
  }
  
  return `chat-${cleanEventId}`;
};

// Validate room name consistency
export const validateRoomConsistency = (liveKitRoom, sessionId, eventId) => {
  const cleanEventId = extractEventId(eventId);
  const expectedLiveKitRoom = generateLiveKitRoomName(cleanEventId);
  const expectedSessionId = generateSessionId(cleanEventId);
  
  const issues = [];
  
  if (liveKitRoom !== expectedLiveKitRoom) {
    issues.push({
      type: 'livekit_mismatch',
      expected: expectedLiveKitRoom,
      actual: liveKitRoom,
      message: `LiveKit room should be "${expectedLiveKitRoom}" but is "${liveKitRoom}"`
    });
  }
  
  if (sessionId !== expectedSessionId) {
    issues.push({
      type: 'session_mismatch',
      expected: expectedSessionId,
      actual: sessionId,
      message: `Session ID should be "${expectedSessionId}" but is "${sessionId}"`
    });
  }
  
  return {
    isConsistent: issues.length === 0,
    issues,
    recommendations: issues.length > 0 ? [
      'Update room naming to use standardized format',
      'Migrate existing rooms to new naming convention',
      'Update database references if needed'
    ] : []
  };
};

// Generate all related names from a single event ID
export const generateAllRoomNames = (eventId) => {
  const cleanEventId = extractEventId(eventId);
  if (!cleanEventId) {
    throw new Error('Invalid eventId provided');
  }
  
  return {
    eventId: cleanEventId,
    liveKitRoom: generateLiveKitRoomName(cleanEventId),
    sessionId: generateSessionId(cleanEventId),
    chatRoom: generateChatRoomName(cleanEventId),
    // Additional formats for URLs, etc.
    urlPath: `/events/${cleanEventId}`,
    streamUrl: `/stream/${cleanEventId}`,
    apiEndpoint: `/api/events/${cleanEventId}`,
  };
};

// Migration helper - convert old naming to new
export const migrateRoomNames = (oldData) => {
  const migrations = [];
  
  if (oldData.liveKitRoom && oldData.sessionId) {
    const eventId = extractEventId(oldData.liveKitRoom);
    const newNames = generateAllRoomNames(eventId);
    
    if (oldData.sessionId !== newNames.sessionId) {
      migrations.push({
        type: 'session_id',
        from: oldData.sessionId,
        to: newNames.sessionId,
        eventId: eventId
      });
    }
  }
  
  return migrations;
};

// Debugging helper
export const debugRoomNames = (eventId, currentLiveKitRoom = null, currentSessionId = null) => {
  console.group('🏠 Room Naming Debug');
  
  try {
    const allNames = generateAllRoomNames(eventId);
    
    console.log('📋 Generated Names:', allNames);
    
    if (currentLiveKitRoom || currentSessionId) {
      const validation = validateRoomConsistency(
        currentLiveKitRoom || allNames.liveKitRoom,
        currentSessionId || allNames.sessionId,
        eventId
      );
      
      console.log('✅ Validation Results:', validation);
      
      if (!validation.isConsistent) {
        console.warn('⚠️ Room naming inconsistencies found:', validation.issues);
        console.log('💡 Recommendations:', validation.recommendations);
      }
    }
    
  } catch (error) {
    console.error('❌ Error in room naming debug:', error);
  }
  
  console.groupEnd();
};

// Export all utilities
export default {
  extractEventId,
  generateLiveKitRoomName,
  generateSessionId,
  generateChatRoomName,
  generateAllRoomNames,
  validateRoomConsistency,
  migrateRoomNames,
  debugRoomNames,
};

