// Updated LiveKit Stream Manager with Error Handling and Graceful Fallback
// Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\components\livekit\LiveKitStreamManagerUpdated.jsx

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { 
  Play, 
  Pause, 
  Users, 
  Eye,
  Monitor,
  Grid3X3,
  Video,
  Wifi,
  WifiOff,
  Upload,
  Copy,
  ExternalLink,
  AlertCircle,
  CheckCircle,
  Clock,
  Activity,
  Settings,
  Zap,
  Share2,
  Info
} from 'lucide-react';

// Dynamically import LiveKit components with error handling
let LiveKitRoom = null;
let liveKitService = null;
let LiveKitConfig = null;

// Async import with fallback
const initializeLiveKit = async () => {
  try {
    const [roomModule, serviceModule, configModule] = await Promise.all([
      import('./LiveKitRoom.jsx').catch(() => null),
      import('../../services/livekit/LiveKitService.js').catch(() => null),
      import('../../services/livekit/LiveKitConfig.js').catch(() => null)
    ]);
    
    if (roomModule) LiveKitRoom = roomModule.default;
    if (serviceModule) liveKitService = serviceModule.default;
    if (configModule) LiveKitConfig = configModule.default;
    
    return {
      available: !!(LiveKitRoom && liveKitService && LiveKitConfig),
      room: LiveKitRoom,
      service: liveKitService,
      config: LiveKitConfig
    };
  } catch (error) {
    console.warn('⚠️ LiveKit modules not available:', error.message);
    return {
      available: false,
      error: error.message
    };
  }
};

// Import room naming utilities with fallback
let generateAllRoomNames = null;
let debugRoomNames = null;

// Lazy load room naming utilities inside component
const loadRoomNamingUtilities = async () => {
  try {
    const roomNamingModule = await import('../../utils/roomNaming.js').catch(() => null);
    if (roomNamingModule) {
      generateAllRoomNames = roomNamingModule.generateAllRoomNames;
      debugRoomNames = roomNamingModule.debugRoomNames;
      return true;
    }
    return false;
  } catch (error) {
    console.warn('⚠️ Room naming utilities not available:', error.message);
    return false;
  }
};

const LiveKitStreamManagerUpdated = ({
  eventId,
  sessionId = null,
  creatorId = null, // artistId of the event creator
  eventInfo = null, // { creatorName, eventTime } for overlay display
  onStreamSelect,
  selectedStream,
  className = '',
  options = {},
  hideShareSection = false,  // Hide share section (will be rendered externally in parent)
  onStreamingStatusChange = null, // Callback when streaming status changes
  canStream: canStreamProp = null, // Permission resolved by the parent from the event document
  allowGuestStreaming = false, // Event setting: may non-creators broadcast? Creator-only by default
  onGuestStreamingChange = null, // Host flipped the in-room toggle — let the parent persist it
}) => {
  const { currentUser } = useAuth();

  // Determine if current user is the creator
  const isCreator = currentUser && creatorId && currentUser.uid === creatorId;

  // Determine if user is registered (has email, not anonymous)
  const isRegistered = currentUser && currentUser.email && !currentUser.isAnonymous;

  // Debug logging for creator detection
  useEffect(() => {
    console.log('🔑 LiveKit Stream Manager - Creator Detection:', {
      currentUserId: currentUser?.uid,
      creatorId,
      isCreator,
      isRegistered,
      calculation: `${currentUser?.uid} === ${creatorId} = ${isCreator}`
    });
  }, [currentUser, creatorId, isCreator, isRegistered]);

  // State for creator control - must be declared before canStream calculation.
  // Defaults to the event's own setting, which is creator-only unless the host
  // opened the stage. Broadcasting into someone else's event is never a default.
  const [allowRegisteredToStream, setAllowRegisteredToStream] = useState(allowGuestStreaming === true);

  // Keep the in-room toggle in sync when the event document changes underneath us.
  useEffect(() => {
    setAllowRegisteredToStream(allowGuestStreaming === true);
  }, [allowGuestStreaming]);

  // The parent (which has the event document) gets the final say when it passes
  // an explicit decision; otherwise fall back to creator + host-opened stage.
  const canStream = canStreamProp !== null
    ? canStreamProp === true
    : isCreator || (isRegistered && allowRegisteredToStream);

  // Debug logging for creator/streaming permissions
  useEffect(() => {
    console.log('🎬 Streaming Permissions Check:', {
      currentUserId: currentUser?.uid,
      creatorId,
      isCreator,
      isRegistered,
      canStream,
      userEmail: currentUser?.email,
      isAnonymous: currentUser?.isAnonymous
    });
  }, [currentUser, creatorId, isCreator, isRegistered, canStream]);

  // Determine if user is anonymous (can only view)
  const isAnonymous = !currentUser || currentUser.isAnonymous || !currentUser.email;
  const [liveKitModules, setLiveKitModules] = useState(null);
  const [initializationError, setInitializationError] = useState(null);
  const [isConnected, setIsConnected] = useState(false);
  const [connectionState, setConnectionState] = useState('disconnected');
  const [roomStats, setRoomStats] = useState(null);
  const [activeStreams, setActiveStreams] = useState(new Map());
  const [isStreaming, setIsStreaming] = useState(false); // Joined the room (viewer or broadcaster)
  const [isBroadcasting, setIsBroadcasting] = useState(false); // Actively publishing video/audio
  const [streamingError, setStreamingError] = useState(null);
  const [showRoomSetup, setShowRoomSetup] = useState(false);
  const [roomToken, setRoomToken] = useState(null);
  // canPublish the current token was minted with, so we can re-mint if the
  // user's permission resolves (or is granted) after they already joined.
  const [tokenCanPublish, setTokenCanPublish] = useState(null);
  const [shareUrl, setShareUrl] = useState('');
  const [copySuccess, setCopySuccess] = useState(false);
  const [roomNames, setRoomNames] = useState(null);
  const [namingIssues, setNamingIssues] = useState(null);

  const roomRef = useRef(null);
  // Generate unique participant name - use UID for uniqueness, fallback to timestamp for true anonymous
  const participantName = currentUser?.displayName || currentUser?.email ||
    (currentUser?.uid ? `User-${currentUser.uid.substring(0, 8)}` : `Viewer-${Date.now()}`);

  // Generate creator's participant identity if creatorId is provided
  const creatorIdentity = creatorId ? `User-${creatorId.substring(0, 8)}` : null;

  // Notify parent when streaming status changes
  useEffect(() => {
    if (onStreamingStatusChange) {
      onStreamingStatusChange(isStreaming);
    }
  }, [isStreaming, onStreamingStatusChange]);

  // Initialize LiveKit modules
  useEffect(() => {
    const init = async () => {
      try {
        // Load room naming utilities first
        await loadRoomNamingUtilities();
        
        const modules = await initializeLiveKit();
        setLiveKitModules(modules);
        
        if (!modules.available) {
          setInitializationError('LiveKit modules not available. Using fallback mode.');
        }
      } catch (error) {
        console.error('❌ Failed to initialize LiveKit modules:', error);
        setInitializationError(`Initialization failed: ${error.message}`);
        setLiveKitModules({ available: false, error: error.message });
      }
    };
    
    init();
  }, []);

  // Generate standardized room names
  useEffect(() => {
    if (eventId && generateAllRoomNames) {
      try {
        const generatedNames = generateAllRoomNames(eventId);
        setRoomNames(generatedNames);
        
        // Debug room naming in development
        if (process.env.NODE_ENV === 'development' && debugRoomNames) {
          debugRoomNames(eventId, generatedNames.liveKitRoom, sessionId);
        }
        
        // Check for naming consistency issues
        if (sessionId && sessionId !== generatedNames.sessionId) {
          setNamingIssues({
            currentSessionId: sessionId,
            recommendedSessionId: generatedNames.sessionId,
            message: `Session ID "${sessionId}" doesn't match LiveKit room pattern. Recommend changing to "${generatedNames.sessionId}"`
          });
        }
        
      } catch (error) {
        console.error('❌ Failed to generate room names:', error);
        setStreamingError(`Room naming error: ${error.message}`);
        
        // Fallback room names
        setRoomNames({
          eventId: eventId,
          liveKitRoom: `event_${eventId}`,
          sessionId: eventId,
          chatRoom: `chat_${eventId}`,
          streamUrl: `/events/${eventId}`,
          apiEndpoint: `/api/events/${eventId}`
        });
      }
    } else if (eventId) {
      // Fallback room names when utilities not available
      setRoomNames({
        eventId: eventId,
        liveKitRoom: `event_${eventId}`,
        sessionId: eventId,
        chatRoom: `chat_${eventId}`,
        streamUrl: `/events/${eventId}`,
        apiEndpoint: `/api/events/${eventId}`
      });
    }
  }, [eventId, sessionId]);

  // Generate room access token (with fallback)
  const generateRoomToken = useCallback(async () => {
    if (!roomNames) {
      throw new Error('Room names not initialized');
    }

    if (!liveKitModules?.available || !liveKitService) {
      // Fallback mode - generate a mock token
      console.log('📺 Using fallback token generation');
      const mockToken = `fallback_token_${Date.now()}`;
      setRoomToken(mockToken);
      setTokenCanPublish(canStream);
      return mockToken;
    }

    try {
      // Anonymous users get viewer tokens (can't publish), registered users get publisher tokens
      const tokenData = await liveKitService.generateAccessToken(
        roomNames.liveKitRoom,
        participantName,
        {
          canPublish: canStream, // Only registered users can publish
          canSubscribe: true,
        }
      );
      
      const jwtToken = tokenData.token;
      
      if (!jwtToken) {
        throw new Error('No JWT token received from token service');
      }
      
      if (import.meta.env.DEV) {
        console.log('✅ JWT Token generated successfully:', {
          tokenLength: jwtToken.length,
          roomName: tokenData.roomName,
          participantName: tokenData.participantName,
          expiresAt: new Date(tokenData.expiresAt).toISOString()
        });
      }
      
      setRoomToken(jwtToken);
      setTokenCanPublish(canStream);
      return jwtToken;
    } catch (error) {
      console.error('Failed to generate room token:', error);
      setStreamingError(error.message);
      return null;
    }
  }, [roomNames, participantName, liveKitModules, canStream]);

  // Join room as viewer (no video/audio publishing)
  const handleStartStreaming = useCallback(async () => {
    if (!roomNames) {
      setStreamingError('Room names not initialized');
      return;
    }

    try {
      setStreamingError(null);

      const token = await generateRoomToken();
      if (!token) {
        throw new Error('Failed to generate access token');
      }

      // Generate share URL using standardized naming
      const shareUrl = `${window.location.origin}${roomNames.streamUrl}?room=${roomNames.liveKitRoom}`;
      setShareUrl(shareUrl);

      setIsStreaming(true); // Joined the room
      setShowRoomSetup(true);

      if (import.meta.env.DEV) {
        console.log('✅ Joined room as viewer:', roomNames.liveKitRoom);
        console.log('🔗 Share URL:', shareUrl);
      }

    } catch (error) {
      console.error('❌ Failed to join room:', error);
      setStreamingError(error.message);
      setIsStreaming(false);
    }
  }, [roomNames, generateRoomToken]);

  // Start broadcasting (enable video/audio publishing)
  const handleStartBroadcasting = useCallback(async () => {
    if (!canStream) {
      setStreamingError('You do not have permission to broadcast');
      return;
    }

    if (!isStreaming) {
      // First join the room, then start broadcasting
      await handleStartStreaming();
    }

    setIsBroadcasting(true);
    console.log('🎥 Started broadcasting video/audio');
  }, [canStream, isStreaming, handleStartStreaming]);

  // Stop broadcasting (disable video/audio but stay in room as viewer)
  const handleStopBroadcasting = useCallback(() => {
    setIsBroadcasting(false);
    console.log('🛑 Stopped broadcasting (still viewing)');
  }, []);

  // Stop streaming (leave room)
  const handleStopStreaming = useCallback(async () => {
    try {
      if (liveKitModules?.available && liveKitService) {
        const result = await liveKitService.disconnect();
        if (!result.success) {
          throw new Error(result.error);
        }
      }
      
      setIsStreaming(false);
      setIsBroadcasting(false);
      setIsConnected(false);
      setConnectionState('disconnected');
      setRoomStats(null);
      setShowRoomSetup(false);
      setRoomToken(null);
      setTokenCanPublish(null);
      
      if (import.meta.env.DEV) {
        console.log('✅ Streaming stopped');
      }
    } catch (error) {
      console.error('❌ Failed to stop streaming:', error);
      setStreamingError(error.message);
    }
  }, [liveKitModules]);

  // Auto-join for viewers and creators
  useEffect(() => {
    if (roomNames && liveKitModules && !isStreaming && !roomToken) {
      if (isCreator) {
        // Creators: auto-join so they can see their control panel immediately
        console.log('🎨 Creator auto-joining to access control panel');
        handleStartStreaming();
      } else if (options.mode === 'streamer' && isRegistered) {
        // Invited guest streamers: join the room so the "Start Broadcasting"
        // control is reachable. They still start with camera/mic off.
        console.log('🎤 Guest streamer auto-joining (broadcast starts off)');
        handleStartStreaming();
      } else if (options.mode === 'viewer') {
        if (isAnonymous) {
          // Anonymous users: view-only, cannot publish/cast
          console.log('🔒 Anonymous user auto-joining as viewer (view-only, cannot publish)');
          handleStartStreaming();
        } else if (isRegistered) {
          // Registered users: auto-join as viewer with canPublish=true but video/audio OFF by default
          // They can opt-in to streaming by clicking "Start Broadcasting"
          console.log('👤 Registered user auto-joining as viewer (can publish but starts as viewer)');
          handleStartStreaming();
        }
      }
    }
  }, [roomNames, liveKitModules, isAnonymous, isRegistered, isCreator, options.mode, isStreaming, roomToken, handleStartStreaming]);

  // Permission can land after the user has already joined — the host flips the
  // "who can stream" setting, or the parent finishes resolving the event
  // document. A viewer token can't publish, so mint a fresh one.
  useEffect(() => {
    if (isStreaming && canStream && tokenCanPublish === false) {
      console.log('🔄 Broadcast permission granted after join - refreshing access token');
      generateRoomToken();
    }
  }, [isStreaming, canStream, tokenCanPublish, generateRoomToken]);

  // Handle room connection (with fallback)
  const handleRoomConnected = useCallback((room) => {
    roomRef.current = room;
    setIsConnected(true);
    setConnectionState('connected');
    setStreamingError(null);
    
    if (import.meta.env.DEV) {
      console.log('✅ Connected to room:', room?.name || 'fallback');
    }
  }, []);

  // Handle room disconnection
  const handleRoomDisconnected = useCallback(() => {
    setIsConnected(false);
    setConnectionState('disconnected');
    setIsStreaming(false);
    setShowRoomSetup(false);
    
    if (import.meta.env.DEV) {
      console.log('❌ Disconnected from room');
    }
  }, []);

  // Handle room errors
  const handleRoomError = useCallback((error) => {
    setStreamingError(error.message);
    setIsStreaming(false);
    setIsConnected(false);
    
    console.error('❌ Room error:', error);
  }, []);

  // Copy share URL
  const handleCopyShareUrl = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(shareUrl);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch (error) {
      console.error('Failed to copy share URL:', error);
    }
  }, [shareUrl]);

  // Copy recommended session ID
  const handleCopyRecommendedSessionId = useCallback(async () => {
    if (namingIssues?.recommendedSessionId) {
      try {
        await navigator.clipboard.writeText(namingIssues.recommendedSessionId);
        if (import.meta.env.DEV) {
          console.log('📋 Copied recommended session ID:', namingIssues.recommendedSessionId);
        }
      } catch (error) {
        console.error('Failed to copy session ID:', error);
      }
    }
  }, [namingIssues]);

  // Toggle registered user streaming permission
  const handleToggleRegisteredStreaming = useCallback(() => {
    const newValue = !allowRegisteredToStream;
    console.log('👥 Toggling registered user streaming:', { from: allowRegisteredToStream, to: newValue });
    setAllowRegisteredToStream(newValue);

    // Persist the host's choice on the event so it survives a reload and
    // applies to everyone, not just this tab.
    if (onGuestStreamingChange) {
      onGuestStreamingChange(newValue);
    }
  }, [allowRegisteredToStream, onGuestStreamingChange]);

  // Update room statistics
  useEffect(() => {
    if (!isConnected || !roomRef.current || !liveKitModules?.available) return;

    const updateStats = () => {
      try {
        const stats = liveKitService?.getRoomStats();
        setRoomStats(stats);
      } catch (error) {
        console.warn('Failed to get room stats:', error);
      }
    };

    updateStats();
    const interval = setInterval(updateStats, 2000);

    return () => clearInterval(interval);
  }, [isConnected, liveKitModules]);

  // Get connection status color
  const getConnectionStatusColor = () => {
    switch (connectionState) {
      case 'connected': return '#10b981';
      case 'connecting': return '#f59e0b';
      case 'reconnecting': return '#f59e0b';
      case 'disconnected': return '#6b7280';
      default: return '#6b7280';
    }
  };

  // Show loading state during initialization
  if (liveKitModules === null) {
    return (
      <div className={`livekit-stream-manager ${className}`} style={{
        backgroundColor: 'rgba(0, 0, 0, 0.8)',
        borderRadius: '12px',
        padding: '2rem',
        color: 'white',
        textAlign: 'center'
      }}>
        <Clock size={24} style={{ marginBottom: '0.5rem', color: '#f59e0b' }} />
        <p>Initializing streaming services...</p>
      </div>
    );
  }

  if (!roomNames) {
    return (
      <div className={`livekit-stream-manager ${className}`} style={{
        backgroundColor: 'rgba(0, 0, 0, 0.8)',
        borderRadius: '12px',
        padding: '1rem',
        color: 'white',
        textAlign: 'center'
      }}>
        <Clock size={24} style={{ marginBottom: '0.5rem', color: '#f59e0b' }} />
        <p>Initializing room names...</p>
      </div>
    );
  }

  return (
    <div className={`livekit-stream-manager ${className}`} style={{
      backgroundColor: 'rgba(0, 0, 0, 0.8)',
      borderRadius: '12px',
      padding: '1rem',
      color: 'white'
    }}>
      {/* Initialization Error Warning */}
      {initializationError && (
        <div style={{
          backgroundColor: 'rgba(251, 191, 36, 0.1)',
          border: '1px solid rgba(251, 191, 36, 0.3)',
          borderRadius: '8px',
          padding: '1rem',
          marginBottom: '1rem',
        }}>
          <h4 style={{
            margin: '0 0 0.5rem 0',
            display: 'flex',
            alignItems: 'center',
            gap: '0.5rem',
            color: '#f59e0b'
          }}>
            <AlertCircle size={16} />
            Streaming Service Status
          </h4>
          
          <p style={{ margin: '0', fontSize: '0.9rem' }}>
            {initializationError}
          </p>
          
          {!liveKitModules?.available && (
            <div style={{ fontSize: '0.8rem', marginTop: '0.5rem', opacity: 0.8 }}>
              Basic streaming functionality available. Install LiveKit client for full features.
            </div>
          )}
        </div>
      )}

      {/* Naming Issues Warning */}
      {namingIssues && (
        <div style={{
          backgroundColor: 'rgba(251, 191, 36, 0.1)',
          border: '1px solid rgba(251, 191, 36, 0.3)',
          borderRadius: '8px',
          padding: '1rem',
          marginBottom: '1rem',
        }}>
          <h4 style={{
            margin: '0 0 0.5rem 0',
            display: 'flex',
            alignItems: 'center',
            gap: '0.5rem',
            color: '#f59e0b'
          }}>
            <Info size={16} />
            Room Naming Inconsistency Detected
          </h4>
          
          <p style={{ margin: '0 0 1rem 0', fontSize: '0.9rem' }}>
            {namingIssues.message}
          </p>
          
          <div style={{
            display: 'grid',
            gridTemplateColumns: '1fr 1fr',
            gap: '1rem',
            fontSize: '0.85rem',
            fontFamily: 'monospace'
          }}>
            <div>
              <div style={{ opacity: 0.8 }}>Current Session ID:</div>
              <div style={{ fontWeight: 'bold', color: '#ef4444' }}>
                {namingIssues.currentSessionId}
              </div>
            </div>
            
            <div>
              <div style={{ opacity: 0.8 }}>Recommended:</div>
              <div style={{ 
                fontWeight: 'bold', 
                color: '#10b981',
                display: 'flex',
                alignItems: 'center',
                gap: '0.5rem'
              }}>
                {namingIssues.recommendedSessionId}
                <button
                  onClick={handleCopyRecommendedSessionId}
                  style={{
                    backgroundColor: 'transparent',
                    border: '1px solid #10b981',
                    borderRadius: '4px',
                    padding: '0.25rem',
                    color: '#10b981',
                    cursor: 'pointer',
                  }}
                  title="Copy recommended session ID"
                >
                  <Copy size={12} />
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Start/Stop Broadcasting - Show for registered users who can stream (not creators) */}
      {canStream && !isCreator && isStreaming && (
        <div style={{
          display: 'flex',
          justifyContent: 'center',
          marginBottom: '1rem'
        }}>
          {!isBroadcasting ? (
            <button
              onClick={handleStartBroadcasting}
              style={{
                backgroundColor: liveKitModules?.available ? '#10b981' : '#f59e0b',
                border: 'none',
                borderRadius: '8px',
                padding: '0.75rem 1.5rem',
                color: 'white',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '0.5rem',
                fontSize: '1rem',
                fontWeight: '600',
                boxShadow: '0 2px 8px rgba(0,0,0,0.2)'
              }}
            >
              <Upload size={18} />
              Start Broadcasting
            </button>
          ) : (
            <button
              onClick={handleStopBroadcasting}
              style={{
                backgroundColor: '#ef4444',
                border: 'none',
                borderRadius: '8px',
                padding: '0.75rem 1.5rem',
                color: 'white',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '0.5rem',
                fontSize: '1rem',
                fontWeight: '600',
                boxShadow: '0 2px 8px rgba(0,0,0,0.2)'
              }}
            >
              <Pause size={18} />
              Stop Broadcasting
            </button>
          )}
        </div>
      )}

      {/* Error Display */}
      {streamingError && (
        <div style={{
          backgroundColor: 'rgba(239, 68, 68, 0.2)',
          border: '1px solid rgba(239, 68, 68, 0.3)',
          borderRadius: '6px',
          padding: '0.75rem',
          marginBottom: '1rem',
          display: 'flex',
          alignItems: 'center',
          gap: '0.5rem',
          fontSize: '0.9rem'
        }}>
          <AlertCircle size={16} />
          <span>{streamingError}</span>
        </div>
      )}

      {/* LiveKit Room or Fallback */}
      {isStreaming && roomToken && (
        <div style={{
          height: '400px',
          marginBottom: '1rem',
          border: `2px solid ${liveKitModules?.available ? '#10b981' : '#f59e0b'}`,
          borderRadius: '8px',
          overflow: 'hidden',
        }}>
          {liveKitModules?.available && LiveKitRoom ? (
            <LiveKitRoom
              roomName={roomNames.liveKitRoom}
              participantName={participantName}
              token={roomToken}
              creatorIdentity={creatorIdentity}
              canStream={canStream}
              isCreator={isCreator}
              isBroadcasting={isBroadcasting}
              onStartBroadcast={handleStartBroadcasting}
              onStopBroadcast={handleStopBroadcasting}
              allowRegisteredToStream={allowRegisteredToStream}
              onToggleRegisteredStreaming={handleToggleRegisteredStreaming}
              eventInfo={eventInfo}
              onConnected={handleRoomConnected}
              onDisconnected={handleRoomDisconnected}
              onError={handleRoomError}
              options={{
                // Registered users start with video/audio OFF (viewer mode)
                // They can enable it by clicking "Start Broadcasting"
                video: isBroadcasting, // Only enable when actively broadcasting
                audio: isBroadcasting, // Only enable when actively broadcasting
                adaptiveStream: true,
                dynacast: true,
              }}
            />
          ) : (
            <div style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              height: '100%',
              backgroundColor: 'rgba(17, 24, 39, 0.8)',
              flexDirection: 'column',
              gap: '1rem'
            }}>
              <Monitor size={48} color="#f59e0b" />
              <div style={{ textAlign: 'center' }}>
                <h3 style={{ margin: '0 0 0.5rem 0', color: '#f59e0b' }}>
                  Fallback Streaming Mode
                </h3>
                <p style={{ margin: 0, fontSize: '0.9rem', opacity: 0.8 }}>
                  Basic streaming is active for room: {roomNames.liveKitRoom}
                </p>
                <p style={{ margin: '0.5rem 0 0 0', fontSize: '0.8rem', opacity: 0.6 }}>
                  Install LiveKit client for full video conferencing features
                </p>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Share Stream - Hidden if hideShareSection is true */}
      {!hideShareSection && isStreaming && shareUrl && (
        <div style={{
          backgroundColor: 'rgba(16, 185, 129, 0.1)',
          border: '1px solid rgba(16, 185, 129, 0.3)',
          borderRadius: '8px',
          padding: '1rem',
          marginBottom: '1rem',
        }}>
          <h4 style={{
            margin: '0 0 0.5rem 0',
            display: 'flex',
            alignItems: 'center',
            gap: '0.5rem',
            color: '#10b981'
          }}>
            <Share2 size={16} />
            Share Your Stream
          </h4>
          
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <input
              type="text"
              value={shareUrl}
              readOnly
              style={{
                flex: 1,
                backgroundColor: 'rgba(255, 255, 255, 0.1)',
                border: '1px solid rgba(255, 255, 255, 0.2)',
                borderRadius: '4px',
                padding: '0.5rem',
                color: 'white',
                fontSize: '0.9rem',
              }}
            />
            
            <button 
              onClick={handleCopyShareUrl}
              style={{
                backgroundColor: copySuccess ? '#10b981' : '#3b82f6',
                border: 'none',
                borderRadius: '4px',
                padding: '0.5rem 1rem',
                color: 'white',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '0.5rem',
                fontSize: '0.9rem',
                fontWeight: '600'
              }}
            >
              {copySuccess ? <CheckCircle size={16} /> : <Copy size={16} />}
              {copySuccess ? 'Copied!' : 'Copy'}
            </button>
            
            <button 
              onClick={() => window.open(shareUrl, '_blank')}
              style={{
                backgroundColor: 'rgba(107, 114, 128, 0.8)',
                border: 'none',
                borderRadius: '4px',
                padding: '0.5rem',
                color: 'white',
                cursor: 'pointer',
              }}
              title="Open in new tab"
            >
              <ExternalLink size={16} />
            </button>
          </div>
        </div>
      )}

      {/* Room Names Reference (Development) */}
      {import.meta.env.DEV && (
        <details style={{
          backgroundColor: 'rgba(59, 130, 246, 0.1)',
          border: '1px solid rgba(59, 130, 246, 0.3)',
          borderRadius: '8px',
          padding: '1rem',
          marginBottom: '1rem',
        }}>
          <summary style={{ 
            cursor: 'pointer', 
            fontWeight: 'bold',
            color: '#3b82f6',
            marginBottom: '0.5rem'
          }}>
            🔧 Room Names Reference (Dev Mode)
          </summary>
          
          <div style={{
            fontSize: '0.8rem',
            fontFamily: 'monospace',
            display: 'grid',
            gap: '0.5rem',
          }}>
            <div><strong>Event ID:</strong> {roomNames.eventId}</div>
            <div><strong>LiveKit Room:</strong> {roomNames.liveKitRoom}</div>
            <div><strong>Session ID:</strong> {roomNames.sessionId}</div>
            <div><strong>Chat Room:</strong> {roomNames.chatRoom}</div>
            <div><strong>Stream URL:</strong> {roomNames.streamUrl}</div>
            <div><strong>API Endpoint:</strong> {roomNames.apiEndpoint}</div>
            <div><strong>LiveKit Available:</strong> {String(liveKitModules?.available)}</div>
          </div>
        </details>
      )}

      {/* Performance Stats */}
      {roomStats && (
        <div style={{
          backgroundColor: 'rgba(59, 130, 246, 0.1)',
          border: '1px solid rgba(59, 130, 246, 0.3)',
          borderRadius: '8px',
          padding: '1rem',
        }}>
          <h4 style={{ 
            margin: '0 0 0.75rem 0', 
            display: 'flex', 
            alignItems: 'center', 
            gap: '0.5rem',
            color: '#3b82f6'
          }}>
            <Monitor size={16} />
            Stream Performance
          </h4>
          
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))',
            gap: '1rem',
            fontSize: '0.9rem',
          }}>
            <div>
              <div style={{ opacity: 0.8 }}>Connection State</div>
              <div style={{ fontWeight: 'bold', color: getConnectionStatusColor() }}>
                {connectionState}
              </div>
            </div>
            
            <div>
              <div style={{ opacity: 0.8 }}>Participants</div>
              <div style={{ fontWeight: 'bold' }}>
                {roomStats.participantCount}
              </div>
            </div>
            
            <div>
              <div style={{ opacity: 0.8 }}>Published Tracks</div>
              <div style={{ fontWeight: 'bold' }}>
                {roomStats.publishedTracks}
              </div>
            </div>
            
            <div>
              <div style={{ opacity: 0.8 }}>Subscribed Tracks</div>
              <div style={{ fontWeight: 'bold' }}>
                {roomStats.subscribedTracks}
              </div>
            </div>
            
            <div>
              <div style={{ opacity: 0.8 }}>Uptime</div>
              <div style={{ fontWeight: 'bold' }}>
                {Math.floor(roomStats.connectionTime / 1000)}s
              </div>
            </div>
            
            {roomStats.reconnectCount > 0 && (
              <div>
                <div style={{ opacity: 0.8 }}>Reconnects</div>
                <div style={{ fontWeight: 'bold', color: '#f59e0b' }}>
                  {roomStats.reconnectCount}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* No Stream Message */}
      {!isStreaming && (
        <div style={{
          textAlign: 'center',
          padding: '2rem 1rem',
          opacity: 0.6,
          fontSize: '0.9rem'
        }}>
          <Zap size={24} style={{ marginBottom: '0.5rem', color: liveKitModules?.available ? '#10b981' : '#f59e0b' }} />
          <p>
            {liveKitModules?.available 
              ? 'Ready to start ultra-low latency streaming'
              : 'Ready to start basic streaming'
            }
          </p>
          <p style={{ fontSize: '0.8rem', marginTop: '0.5rem' }}>
            Using room: {roomNames.liveKitRoom}
          </p>
        </div>
      )}
    </div>
  );
};

export default LiveKitStreamManagerUpdated;