// src/components/auth/GoogleRedirectHandler.fixed.jsx
import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { getAuth, getRedirectResult, GoogleAuthProvider } from 'firebase/auth';
import { getFirestore, doc, getDoc, setDoc } from 'firebase/firestore';
import { createProfile } from '../../services/profiles';

/**
 * Enhanced component that handles the redirect result from Google Authentication
 * with improved error handling and logging
 */
const GoogleRedirectHandler = () => {
  const [processing, setProcessing] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();
  const auth = getAuth();
  const db = getFirestore();

  useEffect(() => {
    const handleRedirectResult = async () => {
      try {
        // Only process if not already processing
        if (processing) return;
        
        setProcessing(true);
        console.log('Checking for Google Auth redirect result...');
        
        // Get redirect result
        const result = await getRedirectResult(auth)
          .catch(err => {
            console.error('Error getting redirect result:', err);
            throw err;
          });
        
        // If no result, user didn't come from a redirect - do nothing
        if (!result) {
          console.log('No redirect result found');
          setProcessing(false);
          return;
        }
        
        console.log('Redirect authentication successful!');
        
        // User signed in after a redirect
        const user = result.user;
        console.log('Successfully logged in user via redirect:', {
          uid: user.uid,
          email: user.email,
          displayName: user.displayName || '<no display name>'
        });
        
        try {
          // Make sure user has a document in Firestore
          const userDocRef = doc(db, 'users', user.uid);
          const userDoc = await getDoc(userDocRef);
          
          if (!userDoc.exists()) {
            console.log('Creating new user document for Google user');
            // Create new user document
            await setDoc(userDocRef, {
              email: user.email,
              displayName: user.displayName || user.email,
              photoURL: user.photoURL,
              createdAt: new Date(),
              provider: 'google',
              isAdmin: false,
              isAudit: false,
              isVIP: false
            });
            
            // Also create a profile document
            await createProfile(user.uid, {
              displayName: user.displayName || user.email,
              email: user.email,
              photoURL: user.photoURL
            });
          }
        } catch (firestoreErr) {
          // Log but continue - we don't want to block login if Firestore operations fail
          console.error('Firestore operation failed during Google redirect handling:', firestoreErr);
        }
        
        // Navigate to home or stored redirect path
        const redirectTo = sessionStorage.getItem('authRedirect') || '/';
        console.log('Redirecting user to:', redirectTo);
        sessionStorage.removeItem('authRedirect'); // Clean up
        
        // Give a slight delay for everything to complete
        setTimeout(() => {
          navigate(redirectTo);
        }, 100);
      } catch (err) {
        console.error('Error processing Google redirect result:', err);
        setError(err.message);
        
        // Add more detailed diagnostic info for specific errors
        if (err.code === 'auth/missing-oauth-client-secret') {
          console.error('Firebase OAuth configuration is missing client secret. Check Firebase Console settings.');
        } else if (err.code === 'auth/internal-error') {
          console.error('Internal Firebase authentication error. Try clearing browser cookies and cache.');
        } else if (err.code === 'auth/network-request-failed') {
          console.error('Network error during authentication. Check internet connection.');
        }
      } finally {
        setProcessing(false);
      }
    };
    
    // Run this effect once when component mounts
    handleRedirectResult();
  }, [auth, db, navigate]);
  
  // This component doesn't need to render anything visible
  // But we could display a loading indicator if needed
  if (processing) {
    return (
      <div className="google-redirect-handler">
        <div className="processing-indicator">
          <p>Processing authentication...</p>
        </div>
        
        <style dangerouslySetInnerHTML={{
          __html: `
            .google-redirect-handler {
              position: fixed;
              bottom: 20px;
              right: 20px;
              padding: 1rem;
              background: rgba(0, 0, 0, 0.7);
              color: white;
              border-radius: 8px;
              z-index: 9999;
            }
            
            .processing-indicator {
              display: flex;
              align-items: center;
              gap: 0.5rem;
            }
            
            .processing-indicator p {
              margin: 0;
              font-size: 0.875rem;
            }
          `
        }} />
      </div>
    );
  }
  
  // If there's an error, we could display it for debugging
  if (error && process.env.NODE_ENV === 'development') {
    return (
      <div className="google-redirect-handler error">
        <div className="error-message">
          <p>Authentication Error: {error}</p>
          <button onClick={() => setError(null)}>Dismiss</button>
        </div>
        
        <style dangerouslySetInnerHTML={{
          __html: `
            .google-redirect-handler.error {
              position: fixed;
              bottom: 20px;
              right: 20px;
              padding: 1rem;
              background: rgba(220, 38, 38, 0.9);
              color: white;
              border-radius: 8px;
              z-index: 9999;
            }
            
            .error-message {
              display: flex;
              flex-direction: column;
              gap: 0.5rem;
            }
            
            .error-message p {
              margin: 0;
              font-size: 0.875rem;
            }
            
            .error-message button {
              padding: 0.25rem 0.5rem;
              background: rgba(255, 255, 255, 0.2);
              border: none;
              border-radius: 4px;
              color: white;
              cursor: pointer;
            }
          `
        }} />
      </div>
    );
  }
  
  // Default: return null
  return null;
};

export default GoogleRedirectHandler;