// BLS (Bureau of Labor Statistics) Public Data API client.
//
// Endpoint: https://api.bls.gov/publicAPI/v2/timeseries/data/  (POST JSON)
// Key is OPTIONAL — without key, anonymous rate is 25 queries/day;
// with a free key, 500/day and larger batches. We batch all series into
// one POST so anonymous usage stays well within budget (one call per
// context refresh).
//
// BLS does NOT ship CORS headers, so we route through corsFetch's proxy
// fallback. corsproxy.io forwards POST+JSON bodies; allorigins only does
// GET, so it will fail on POST and we'll rely on corsproxy or direct
// (which some enterprise networks proxy through a CORS gateway anyway).
//
// Series IDs used:
//   LNS14000000            — US unemployment rate (seasonally adjusted)
//   CUUR0000SA0            — CPI-U All Urban Consumers, all items (NSA)
//   LAUMT081974000000003   — Denver-Aurora-Lakewood MSA unemployment rate
//   LAUMT043806000000003   — Phoenix-Mesa-Chandler MSA unemployment rate
//
// Output: ContextSignal[] matching tags from contextCategories.

import apiKeyService from '../apiKeyService'
import { corsFetch } from '../../utils/corsFetch'

const BLS_API_URL = 'https://api.bls.gov/publicAPI/v2/timeseries/data/'

// tag -> { seriesID, label, category, unit, isYoY }
const SERIES = {
  'labor.unemployment.national': {
    seriesID: 'LNS14000000',
    label: 'US Unemployment',
    category: 'labor',
    unit: '%',
    isYoY: false,
  },
  'labor.unemployment.denver': {
    seriesID: 'LAUMT081974000000003',
    label: 'Denver-Aurora Unemployment',
    category: 'labor',
    unit: '%',
    isYoY: false,
  },
  'labor.unemployment.phoenix': {
    seriesID: 'LAUMT043806000000003',
    label: 'Phoenix-Mesa Unemployment',
    category: 'labor',
    unit: '%',
    isYoY: false,
  },
  'inflation.cpi': {
    seriesID: 'CUUR0000SA0',
    label: 'CPI YoY (All Urban)',
    category: 'rates',
    unit: '%',
    isYoY: true, // the raw series is an index — we compute YoY % change
  },
}

// Convert BLS period code ('M03' = March) + year into 'YYYY-MM'
function periodSlug(period, year) {
  if (/^M\d{2}$/.test(period)) return `${year}-${period.slice(1)}`
  if (/^Q\d{2}$/.test(period)) return `${year}-Q${period.slice(1)}`
  return `${year} ${period}`
}

function classifyTrend(delta, threshold = 0.05) {
  if (delta === null || Number.isNaN(delta)) return 'stable'
  if (delta > threshold) return 'up'
  if (delta < -threshold) return 'down'
  return 'stable'
}

// BLS data is returned newest-first. `data[0]` = latest period,
// `data[1]` = prior period, `data[12]` ≈ one year ago.
function buildSignal(series, cfg, tag) {
  const data = (series.data || []).filter(d => d.value && d.value !== '-')
  if (data.length === 0) return null

  const latest = data[0]
  const prev = data[1] || null
  const latestVal = parseFloat(latest.value)
  const prevVal = prev ? parseFloat(prev.value) : null

  const base = {
    id: `bls.${series.seriesID.toLowerCase()}`,
    tag,
    category: cfg.category,
    label: cfg.label,
    unit: cfg.unit,
    period: periodSlug(latest.period, latest.year),
    asOf: new Date().toISOString(),
    source: `BLS (${series.seriesID})`,
    sourceUrl: `https://data.bls.gov/timeseries/${series.seriesID}`,
    reliability: 0.96,
    sentimentHint: 'neutral',
  }

  if (cfg.isYoY) {
    // Compute YoY % change for index-style series (CPI).
    const yearAgo = data[12] ? parseFloat(data[12].value) : null
    if (yearAgo === null || yearAgo === 0) return null
    const yoy = +((latestVal - yearAgo) / yearAgo * 100).toFixed(2)

    // Previous period's YoY — latest-1 vs latest-13
    let delta = null, deltaLabel = null
    if (prev && data[13]) {
      const prevYearAgo = parseFloat(data[13].value)
      if (prevYearAgo) {
        const prevYoY = (prevVal - prevYearAgo) / prevYearAgo * 100
        delta = +(yoy - prevYoY).toFixed(2)
        deltaLabel = 'MoM change'
      }
    }
    return { ...base, value: yoy, trend: classifyTrend(delta), delta, deltaLabel }
  }

  // Level series (unemployment rate): delta is absolute period-over-period
  const delta = prevVal !== null ? +(latestVal - prevVal).toFixed(2) : null
  return {
    ...base,
    value: latestVal,
    trend: classifyTrend(delta),
    delta,
    deltaLabel: delta !== null ? 'MoM change' : null,
  }
}

const blsService = {
  async fetchAll() {
    const entries = Object.entries(SERIES)
    const seriesIds = entries.map(([, cfg]) => cfg.seriesID)
    const currentYear = new Date().getFullYear()
    const key = apiKeyService.getBlsApiKey()

    const body = {
      seriesid: seriesIds,
      startyear: String(currentYear - 2), // 2 years back to ensure we have 13+ months for YoY
      endyear: String(currentYear),
      ...(key ? { registrationkey: key } : {}),
    }

    const res = await corsFetch(BLS_API_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      parse: 'json',
      timeout: 15000,
      proxyFirst: true, // BLS has no CORS headers
    })

    if (!res.ok) {
      return { signals: [], error: res.error || 'BLS fetch failed' }
    }
    const data = res.data
    if (data?.status !== 'REQUEST_SUCCEEDED') {
      const msg = Array.isArray(data?.message) && data.message.length
        ? data.message[0]
        : 'BLS rejected request'
      return { signals: [], error: msg }
    }

    const signals = []
    for (const [tag, cfg] of entries) {
      const series = data.Results.series.find(s => s.seriesID === cfg.seriesID)
      if (!series) continue
      const sig = buildSignal(series, cfg, tag)
      if (sig) signals.push(sig)
    }
    return { signals, error: null }
  },
}

export default blsService
