// src/pages/RoomPage.jsx
//
// Screen C: one permanent URL — /r/:slug — that works before the show
// (countdown + RSVP), during it (live audio + chat), and after (replay).
//
// The audio path is the app's existing LiveKit service: the Studio publishes
// into the airing's room, this page subscribes to it. Nothing here creates a
// room; the occurrence id names it (occurrenceRoomKey).

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Link, useParams, useNavigate } from 'react-router-dom';
import { doc, getDoc, setDoc, deleteDoc, updateDoc, increment } from 'firebase/firestore';
import { Play, Pause, Heart, Share2, Volume2 } from 'lucide-react';
import { db } from '../firebase';
import TalkStudioNav from '../components/layout/TalkStudioNav';
import { useAuth } from '../contexts/AuthContext';
import liveKitService from '../services/livekit/LiveKitService';
import { subscribeToRoomChat, sendRoomMessage } from '../services/roomChatService';
import {
  getRoomBySlug,
  listOccurrencesForRoom,
  pickCurrentOccurrence,
  ensureUpcomingOccurrences,
  subscribeToOccurrence,
  toggleRsvp,
  hasRsvp,
  downloadIcs,
  listenRoomKey,
  occurrenceDate,
  formatClock,
  formatDayTime,
  formatDuration,
  formatElapsed,
  cadenceLabel,
} from '../services/scheduledRoomsService';
import './RoomPage.css';

const TABS = ['Chat', 'Listeners', 'Tracklist'];

// Tipping is intentionally absent. WalletService settles a tip with client-side
// writes to wallets/walletTransactions/tips/platformRevenue, so any rule that
// lets a real tip through also lets a viewer edit their own balance. Restore
// the button once a server-side sendTip owns that transaction.

/** Counts down to `target`, formatted for the pre-show well. */
const useCountdown = (target) => {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, []);
  if (!target) return null;
  const diff = Math.max(0, target.getTime() - now);
  const hours = Math.floor(diff / 3600000);
  const minutes = Math.floor((diff % 3600000) / 60000);
  const seconds = Math.floor((diff % 60000) / 1000);
  const pad = (n) => String(n).padStart(2, '0');
  return hours > 0 ? `${hours}:${pad(minutes)}:${pad(seconds)}` : `${pad(minutes)}:${pad(seconds)}`;
};

const RoomPage = () => {
  const { slug, replayId } = useParams();
  const { currentUser } = useAuth();
  const navigate = useNavigate();

  const [room, setRoom] = useState(null);
  const [occurrence, setOccurrence] = useState(null);
  const [occurrences, setOccurrences] = useState([]);
  const [loadError, setLoadError] = useState(null);

  const [going, setGoing] = useState(false);
  const [following, setFollowing] = useState(false);
  const [likes, setLikes] = useState(0);
  const [liked, setLiked] = useState(false);
  const [copied, setCopied] = useState(false);

  const [playing, setPlaying] = useState(false);
  const [connecting, setConnecting] = useState(false);
  const [audioError, setAudioError] = useState(null);
  const [listeners, setListeners] = useState(0);
  const [volume, setVolume] = useState(0.75);

  const [tab, setTab] = useState('Chat');
  const [messages, setMessages] = useState([]);
  const [draft, setDraft] = useState('');

  const audioHostRef = useRef(null);   // <div> the LiveKit audio elements attach into
  const replayAudioRef = useRef(null);
  const roomKeyRef = useRef(null);
  const volumeRef = useRef(0.75);
  const messagesEndRef = useRef(null);

  /* ---------------- load ---------------- */

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const found = await getRoomBySlug(slug);
        if (!found) {
          if (!cancelled) setLoadError('No show lives at this link.');
          return;
        }
        if (cancelled) return;
        setRoom(found);

        const rows = await listOccurrencesForRoom(found.id);
        if (cancelled) return;
        setOccurrences(rows);
        setOccurrence(
          replayId ? rows.find(o => o.id === replayId) || null : pickCurrentOccurrence(rows),
        );

        // A room read is also when we notice the schedule has run down.
        ensureUpcomingOccurrences(found).catch(() => {});
      } catch (err) {
        console.warn('[Room] load failed:', err.message);
        if (!cancelled) setLoadError('Could not load this room.');
      }
    })();
    return () => { cancelled = true; };
  }, [slug, replayId]);

  useEffect(() => {
    if (!occurrence) return;
    setListeners(occurrence.listenerCount || 0);
    setLikes(occurrence.likeCount || 0);
  }, [occurrence?.id]); // eslint-disable-line react-hooks/exhaustive-deps

  // Watch the airing itself, so a listener sitting on the countdown sees the
  // room go live the moment the host starts broadcasting — from the Studio,
  // the DJ Studio, or anywhere else that binds to it.
  useEffect(() => {
    if (!occurrence?.id) return undefined;
    return subscribeToOccurrence(occurrence.id, (fresh) => {
      setOccurrence(prev => (prev && prev.id === fresh.id ? { ...prev, ...fresh } : prev));
    });
  }, [occurrence?.id]);

  useEffect(() => {
    if (!currentUser || !occurrence) { setGoing(false); return; }
    hasRsvp(currentUser.uid, occurrence.id).then(setGoing).catch(() => setGoing(false));
  }, [currentUser, occurrence]);

  useEffect(() => {
    if (!currentUser || !room) { setFollowing(false); return; }
    getDoc(doc(db, 'follows', `${currentUser.uid}_${room.hostId}`))
      .then(snap => setFollowing(snap.exists()))
      .catch(() => setFollowing(false));
  }, [currentUser, room]);

  /* ---------------- chat ---------------- */

  useEffect(() => {
    if (!occurrence) return undefined;
    return subscribeToRoomChat(occurrence.id, setMessages);
  }, [occurrence]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ block: 'end' });
  }, [messages.length]);

  /* ---------------- state machine ---------------- */

  const startAt = occurrenceDate(occurrence?.startAt);
  const countdown = useCountdown(startAt);

  const state = useMemo(() => {
    if (!occurrence) return 'none';
    if (occurrence.state === 'live') return 'live';
    if (occurrence.state === 'replay') return occurrence.replayUrl ? 'replay' : 'processing';
    if (occurrence.state === 'ended') return 'ended';
    return 'preshow';
  }, [occurrence]);

  /* ---------------- listening ---------------- */

  const stopListening = useCallback(async () => {
    setPlaying(false);
    if (roomKeyRef.current) {
      try {
        await liveKitService.disconnect(roomKeyRef.current);
      } catch (err) {
        console.warn('[Room] disconnect failed:', err.message);
      }
      roomKeyRef.current = null;
    }
    if (audioHostRef.current) audioHostRef.current.innerHTML = '';
  }, []);

  useEffect(() => () => { stopListening(); }, [stopListening]);

  const startListening = useCallback(async () => {
    if (!occurrence) return;
    setAudioError(null);
    setConnecting(true);
    try {
      const roomKey = listenRoomKey(occurrence);
      const listenerName = currentUser?.displayName || currentUser?.email || `listener-${Date.now().toString(36)}`;
      const result = await liveKitService.connect(roomKey, listenerName, {
        canPublish: false,
        canSubscribe: true,
        autoSubscribe: true,
      });
      if (!result.success || !result.room) {
        throw new Error(result.error || 'Could not join the stream');
      }
      roomKeyRef.current = roomKey;

      const { RoomEvent, Track } = await import('livekit-client');
      const lkRoom = result.room;

      // Mobile browsers keep LiveKit's audio muted until this runs inside a
      // user gesture — which is exactly where we are, in the play handler.
      try {
        await lkRoom.startAudio();
      } catch (err) {
        console.warn('[Room] startAudio was refused:', err.message);
      }

      const attach = (track) => {
        if (track.kind !== Track.Kind.Audio || !audioHostRef.current) return;
        const element = track.attach();
        element.autoplay = true;
        element.playsInline = true;
        element.volume = volumeRef.current;
        audioHostRef.current.appendChild(element);
        // A track that arrives after the click that started playback can still
        // be refused by a phone's autoplay policy; say so rather than sitting
        // silent, since Retry runs inside a fresh tap.
        const played = element.play();
        if (played && typeof played.catch === 'function') {
          played.catch(() => setAudioError('Tap play to start the audio.'));
        }
      };

      lkRoom.remoteParticipants?.forEach(participant => {
        participant.trackPublications?.forEach(pub => { if (pub.track) attach(pub.track); });
      });
      lkRoom.on(RoomEvent.TrackSubscribed, attach);
      lkRoom.on(RoomEvent.ParticipantConnected, () =>
        setListeners(Math.max(0, (lkRoom.remoteParticipants?.size || 1) - 1)));
      lkRoom.on(RoomEvent.ParticipantDisconnected, () =>
        setListeners(Math.max(0, (lkRoom.remoteParticipants?.size || 1) - 1)));

      setListeners(Math.max(occurrence.listenerCount || 0, Math.max(0, (result.participantCount || 1) - 1)));
      setPlaying(true);
    } catch (err) {
      console.warn('[Room] could not listen:', err.message);
      setAudioError(err.message || 'The stream did not open');
      await stopListening();
    } finally {
      setConnecting(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [occurrence?.id, occurrence?.liveRoomKey, occurrence?.state, currentUser, stopListening]);

  const togglePlayback = () => {
    if (state === 'replay') {
      const element = replayAudioRef.current;
      if (!element) return;
      if (element.paused) { element.play(); setPlaying(true); } else { element.pause(); setPlaying(false); }
      return;
    }
    if (state !== 'live') return;
    if (playing) stopListening(); else startListening();
  };

  useEffect(() => {
    volumeRef.current = volume;
    if (audioHostRef.current) {
      Array.from(audioHostRef.current.children).forEach(el => { el.volume = volume; });
    }
    if (replayAudioRef.current) replayAudioRef.current.volume = volume;
  }, [volume]);

  /* ---------------- actions ---------------- */

  const requireAuth = () => {
    if (currentUser) return true;
    navigate(`/login?next=${encodeURIComponent(`/r/${slug}`)}`);
    return false;
  };

  const handleRsvp = async () => {
    if (!requireAuth() || !occurrence) return;
    const next = !going;
    setGoing(next);
    try {
      await toggleRsvp({ user: currentUser, occurrence });
    } catch (err) {
      setGoing(!next);
      console.warn('[Room] RSVP failed:', err.message);
    }
  };

  const handleFollow = async () => {
    if (!requireAuth() || !room) return;
    const ref = doc(db, 'follows', `${currentUser.uid}_${room.hostId}`);
    const next = !following;
    setFollowing(next);
    try {
      if (next) {
        await setDoc(ref, {
          followerId: currentUser.uid,
          followingId: room.hostId,
          createdAt: new Date(),
        });
      } else {
        await deleteDoc(ref);
      }
      await updateDoc(doc(db, 'users', room.hostId), {
        followerCount: increment(next ? 1 : -1),
      }).catch(() => {});
    } catch (err) {
      setFollowing(!next);
      console.warn('[Room] follow failed:', err.message);
    }
  };

  const handleLike = async () => {
    if (!requireAuth() || !occurrence || liked) return;
    setLiked(true);
    setLikes(n => n + 1);
    await updateDoc(doc(db, 'occurrences', occurrence.id), { likeCount: increment(1) }).catch(() => {});
  };

  const handleCopyLink = async () => {
    const url = `${window.location.origin}/r/${slug}`;
    try {
      await navigator.clipboard.writeText(url);
    } catch (_) { /* clipboard blocked — the URL is on screen anyway */ }
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };

  const handleSend = async (e) => {
    e.preventDefault();
    if (!requireAuth() || !occurrence) return;
    const text = draft;
    setDraft('');
    try {
      await sendRoomMessage({
        occurrenceId: occurrence.id,
        user: currentUser,
        text,
        isHost: currentUser.uid === room?.hostId,
      });
    } catch (err) {
      setDraft(text);
      console.warn('[Room] send failed:', err.message);
    }
  };

  /* ---------------- render ---------------- */

  if (loadError) {
    return (
      <div className="ts-app room-page">
        <TalkStudioNav active="discover" compactSearch />
        <div className="ts-page">
          <div className="ts-empty">{loadError} <Link to="/">Back to Discover</Link></div>
        </div>
      </div>
    );
  }

  if (!room || !occurrence) {
    return (
      <div className="ts-app room-page">
        <TalkStudioNav active="discover" compactSearch />
        <div className="ts-page room-grid">
          <div className="ts-skeleton room-player-skeleton" />
          <div className="ts-skeleton room-rail-skeleton" />
        </div>
      </div>
    );
  }

  const nextUp = occurrences.find(
    o => o.state === 'scheduled' && o.id !== occurrence.id && (occurrenceDate(o.startAt) || 0) > new Date(),
  );
  const isLive = state === 'live';
  const endLabel = occurrenceDate(occurrence.endAt);

  return (
    <div className="ts-app room-page">
      <TalkStudioNav active="discover" compactSearch />

      <div className="ts-page room-grid">
        {/* ---------------- left ---------------- */}
        <div className="room-main">
          <section className="ts-card room-player">
            <div className={`room-well ${isLive ? 'live' : ''}`}>
              {isLive && <div className="room-wave" aria-hidden="true" />}

              {state === 'preshow' && (
                <div className="room-preshow">
                  <div className="ts-mono room-countdown">{countdown || '--:--'}</div>
                  <div className="room-preshow-label">
                    until {occurrence.title} · {formatDayTime(occurrence.startAt)}
                  </div>
                  <button
                    type="button"
                    className={`ts-btn ts-btn--md ${going ? 'ts-btn--going' : 'ts-btn--primary'}`}
                    onClick={handleRsvp}
                  >
                    {going ? 'Going ✓' : 'Notify me'}
                  </button>
                </div>
              )}

              {state === 'processing' && (
                <div className="room-preshow">
                  <div className="room-preshow-label">Replay in a few minutes.</div>
                </div>
              )}

              {state === 'ended' && (
                <div className="room-preshow">
                  <div className="room-preshow-label">
                    This one's over{nextUp ? ' — the next airing is below.' : '.'}
                  </div>
                </div>
              )}

              {audioError && (
                <div className="ts-error-banner room-audio-error">
                  {audioError}
                  <button type="button" className="ts-btn ts-btn--sm ts-btn--neutral" onClick={startListening}>
                    Retry
                  </button>
                </div>
              )}

              <div ref={audioHostRef} className="room-audio-host" />
              {state === 'replay' && (
                // eslint-disable-next-line jsx-a11y/media-has-caption
                <audio
                  ref={replayAudioRef}
                  src={occurrence.replayUrl}
                  onPlay={() => setPlaying(true)}
                  onPause={() => setPlaying(false)}
                  className="room-replay-audio"
                  controls
                />
              )}
            </div>

            <div className="room-transport">
              <button
                type="button"
                className="room-transport-play"
                onClick={togglePlayback}
                disabled={connecting || (state !== 'live' && state !== 'replay')}
                aria-label={playing ? 'Pause' : 'Play'}
              >
                {playing ? <Pause size={16} fill="currentColor" /> : <Play size={16} fill="currentColor" />}
              </button>

              <div className="room-transport-track">
                <div className="ts-meter">
                  <div className="ts-meter-fill" style={{ width: isLive && playing ? '35%' : '0%' }} />
                </div>
                <div className="room-transport-labels ts-mono">
                  <span>{isLive ? formatElapsed(occurrence.wentLiveAt || occurrence.startAt) : formatDuration(occurrence.durationMin)}</span>
                  <span>
                    {isLive
                      ? `live${endLabel ? ` · ends ${formatClock(occurrence.endAt)}` : ''}`
                      : state === 'replay' ? 'replay' : 'not started'}
                  </span>
                </div>
              </div>

              <span className="room-vol-label">VOL</span>
              <input
                type="range"
                min="0"
                max="1"
                step="0.05"
                value={volume}
                onChange={e => setVolume(Number(e.target.value))}
                className="room-vol"
                aria-label="Volume"
              />
              <Volume2 size={14} className="room-vol-icon" />
            </div>
          </section>

          <section className="room-title-row">
            <div className="room-title-block">
              <div className="room-title-badges">
                {isLive ? (
                  <>
                    <span className="ts-badge-live">LIVE</span>
                    <span className="room-title-stats">
                      {listeners} listening · {messages.length} in chat
                    </span>
                  </>
                ) : (
                  <span className="ts-badge-when">
                    {formatDayTime(occurrence.startAt)}
                  </span>
                )}
              </div>
              <h1 className="room-title">{occurrence.title}</h1>
              <div className="room-host">
                <Link to={`/artist/${room.hostId}`}>{room.hostName}</Link>
                {(room.genres || []).length ? ` · ${room.genres.join(', ')}` : ''}
                {` · ${cadenceLabel(room.repeat)} ${formatClock(room.startAt)}`}
              </div>
            </div>

            <div className="room-actions">
              <button type="button" className="ts-btn ts-btn--neutral" onClick={handleLike}>
                <Heart size={14} fill={liked ? 'currentColor' : 'none'} /> {likes}
              </button>
              <button type="button" className="ts-btn ts-btn--neutral" onClick={handleCopyLink}>
                <Share2 size={14} /> {copied ? 'Copied' : 'Copy link'}
              </button>
              <button
                type="button"
                className={`ts-btn ${following ? 'ts-btn--going' : 'ts-btn--indigo-soft'}`}
                onClick={handleFollow}
              >
                {following ? 'Following' : 'Follow show'}
              </button>
            </div>
          </section>

          <div className="room-tiles">
            <div className="ts-tile">
              <div className="room-tile-label">Now playing</div>
              <div className="room-tile-value">
                {occurrence.nowPlaying || (isLive ? 'Live from the decks' : '—')}
              </div>
            </div>
            <div className="ts-tile">
              <div className="room-tile-label">Next in this room</div>
              <div className="room-tile-value">
                {nextUp ? formatDayTime(nextUp.startAt) : 'Nothing scheduled yet'}
                {nextUp && (
                  <>
                    {' · '}
                    <button type="button" className="room-tile-link" onClick={() => downloadIcs(nextUp)}>
                      Add to calendar
                    </button>
                  </>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* ---------------- right rail ---------------- */}
        <aside className="ts-card room-rail">
          <div className="room-tabs">
            {TABS.map(name => (
              <button
                key={name}
                type="button"
                className={`room-tab ${tab === name ? 'active' : ''}`}
                onClick={() => setTab(name)}
              >
                {name}
              </button>
            ))}
          </div>

          {tab === 'Chat' && (
            <>
              <div className="room-messages">
                {messages.length === 0 && (
                  <div className="ts-empty">
                    {state === 'preshow' ? 'Nobody\'s said anything yet — say hi.' : 'No messages.'}
                  </div>
                )}
                {messages.map(message => (
                  <div key={message.id} className={`room-message ${message.system ? 'system' : ''}`}>
                    <span className={`room-message-avatar ${message.isHost ? 'host' : ''}`}>
                      {(message.authorName || '?').charAt(0).toUpperCase()}
                    </span>
                    <div className="room-message-body">
                      <div className="room-message-head">
                        <span className={`room-message-name ${message.isHost ? 'host' : ''}`}>
                          {message.authorName}
                        </span>
                        {message.isHost && <span className="room-host-tag">HOST</span>}
                      </div>
                      <div className="room-message-text">{message.body}</div>
                    </div>
                  </div>
                ))}
                <div ref={messagesEndRef} />
              </div>

              {state === 'replay' ? (
                <div className="room-composer room-composer--closed">
                  Chat closed — this is a replay.
                </div>
              ) : (
                <form className="room-composer" onSubmit={handleSend}>
                  <input
                    className="room-composer-input"
                    value={draft}
                    onChange={e => setDraft(e.target.value)}
                    placeholder="Say something…"
                    aria-label="Message"
                  />
                  <button type="submit" className="ts-btn ts-btn--primary room-composer-send">
                    Send
                  </button>
                </form>
              )}
            </>
          )}

          {tab === 'Listeners' && (
            <div className="room-rail-body">
              <div className="room-tile-label">In the room</div>
              <div className="room-listeners-count">{listeners}</div>
              <p className="room-rail-note">
                {isLive
                  ? 'Listener names show up here when they chat.'
                  : 'Nobody is listening yet — the show hasn\'t started.'}
              </p>
            </div>
          )}

          {tab === 'Tracklist' && (
            <div className="room-rail-body">
              {(occurrence.tracklist || []).length === 0 ? (
                <p className="room-rail-note">
                  The host hasn't posted a tracklist for this one.
                </p>
              ) : (
                <ol className="room-tracklist">
                  {occurrence.tracklist.map((track, i) => (
                    // eslint-disable-next-line react/no-array-index-key
                    <li key={`${track}-${i}`}>{track}</li>
                  ))}
                </ol>
              )}
            </div>
          )}
        </aside>
      </div>
    </div>
  );
};

export default RoomPage;
