// src/hooks/useSpeechSearch.js
//
// Tiny wrapper around the Web Speech API for the SmartMic's "speech" branch.
//
// Behavior:
//   const { start, stop, supported } = useSpeechSearch({ timeoutMs: 6000 });
//   const result = await start();
//   // result: { transcript: string, confidence: number } | null
//
// Returns null if:
//   - Browser doesn't support SpeechRecognition (Firefox, etc.)
//   - User denies mic permission (already granted at SmartMic level, so unlikely)
//   - Timeout elapses with no recognized speech
//   - Confidence < 0.5 (we treat anything lower as "not actually speech")
//
// IMPORTANT: SpeechRecognition opens its OWN mic stream. Calling start() while
// another mic recorder is active sometimes works in Chrome but is racy. The
// SmartMic orchestrator should call start() BEFORE starting its own
// MediaRecorder, or pass `useExistingStream: true` (TODO if needed).

import { useCallback, useEffect, useRef } from 'react';

const CONFIDENCE_FLOOR = 0.5;

export function useSpeechSearch({ timeoutMs = 6000, lang = 'en-US' } = {}) {
  const recognitionRef = useRef(null);
  const timerRef = useRef(null);

  const supported =
    typeof window !== 'undefined' &&
    (window.SpeechRecognition || window.webkitSpeechRecognition);

  const stop = useCallback(() => {
    if (recognitionRef.current) {
      try {
        recognitionRef.current.stop();
      } catch (_) {
        /* noop */
      }
      recognitionRef.current = null;
    }
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  const start = useCallback(() => {
    if (!supported) return Promise.resolve(null);

    return new Promise((resolve) => {
      try {
        const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
        const rec = new SR();
        rec.lang = lang;
        rec.interimResults = false;
        rec.maxAlternatives = 1;
        rec.continuous = false;

        let resolved = false;
        const finish = (value) => {
          if (resolved) return;
          resolved = true;
          stop();
          resolve(value);
        };

        rec.onresult = (event) => {
          const last = event.results[event.results.length - 1];
          if (!last || !last[0]) return finish(null);
          const transcript = (last[0].transcript || '').trim();
          const confidence = typeof last[0].confidence === 'number' ? last[0].confidence : 0;
          if (!transcript || confidence < CONFIDENCE_FLOOR) {
            return finish(null);
          }
          finish({ transcript, confidence });
        };

        rec.onerror = (event) => {
          // 'no-speech' is the common case where the user hummed instead of talking
          // We just resolve null and let the other branches win.
          // eslint-disable-next-line no-console
          console.debug('[useSpeechSearch] onerror:', event.error);
          finish(null);
        };

        rec.onend = () => finish(null);

        recognitionRef.current = rec;
        timerRef.current = setTimeout(() => finish(null), timeoutMs);
        rec.start();
      } catch (e) {
        // eslint-disable-next-line no-console
        console.warn('[useSpeechSearch] failed to start:', e);
        resolve(null);
      }
    });
  }, [lang, stop, supported, timeoutMs]);

  // Cleanup on unmount
  useEffect(() => () => stop(), [stop]);

  return { start, stop, supported: Boolean(supported) };
}

export default useSpeechSearch;
