import React, { useState, useEffect, useRef } from 'react';

const CameraTest = () => {
  const [status, setStatus] = useState('Testing...');
  const [devices, setDevices] = useState([]);
  const [error, setError] = useState(null);
  const videoRef = useRef(null);

  useEffect(() => {
    testCameraAccess();
  }, []);

  const testCameraAccess = async () => {
    try {
      console.log('🔍 Testing camera access...');
      
      // Step 1: Check if getUserMedia is available
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        throw new Error('getUserMedia not supported in this browser');
      }
      
      // Step 2: Request permissions
      setStatus('Requesting permissions...');
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: true, 
        audio: true 
      });
      
      console.log('✅ Got media stream:', stream);
      
      // Step 3: Show video
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      
      // Step 4: List devices
      const deviceList = await navigator.mediaDevices.enumerateDevices();
      setDevices(deviceList);
      
      console.log('📷 All devices:', deviceList);
      
      setStatus('✅ Camera access successful!');
      
      // Clean up after 5 seconds
      setTimeout(() => {
        stream.getTracks().forEach(track => track.stop());
        setStatus('Test completed - camera stopped');
      }, 5000);
      
    } catch (err) {
      console.error('❌ Camera test failed:', err);
      setError(err);
      setStatus(`❌ Failed: ${err.message}`);
      
      // Provide specific help
      if (err.name === 'NotAllowedError') {
        setStatus('❌ Permission denied - Please allow camera access in browser settings');
      } else if (err.name === 'NotFoundError') {
        setStatus('❌ No camera found - Please connect a camera or virtual camera');
      } else if (err.name === 'NotReadableError') {
        setStatus('❌ Camera in use - Please close other apps using the camera');
      }
    }
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
      <h2>🔧 Camera/Microphone Test</h2>
      
      <div style={{ 
        padding: '15px', 
        background: status.includes('✅') ? '#d4edda' : status.includes('❌') ? '#f8d7da' : '#fff3cd',
        border: '1px solid #ccc',
        borderRadius: '5px',
        marginBottom: '20px'
      }}>
        <strong>Status:</strong> {status}
      </div>
      
      {error && (
        <div style={{ 
          padding: '15px', 
          background: '#f8d7da',
          border: '1px solid #f5c6cb',
          borderRadius: '5px',
          marginBottom: '20px'
        }}>
          <strong>Error Details:</strong>
          <pre>{JSON.stringify(error, null, 2)}</pre>
        </div>
      )}
      
      <video 
        ref={videoRef}
        autoPlay 
        muted 
        style={{ 
          width: '400px', 
          height: '300px', 
          background: '#000',
          border: '2px solid #ccc',
          borderRadius: '5px'
        }}
      />
      
      <div style={{ marginTop: '20px' }}>
        <h3>Available Devices:</h3>
        {devices.length > 0 ? (
          <ul>
            {devices.map((device, index) => (
              <li key={index}>
                <strong>{device.kind}:</strong> {device.label || `Device ${index + 1}`}
              </li>
            ))}
          </ul>
        ) : (
          <p>No devices found or permissions not granted</p>
        )}
      </div>
      
      <div style={{ marginTop: '20px' }}>
        <button onClick={testCameraAccess} style={{ 
          padding: '10px 20px', 
          background: '#007bff', 
          color: 'white', 
          border: 'none', 
          borderRadius: '5px',
          cursor: 'pointer'
        }}>
          🔄 Test Again
        </button>
      </div>
      
      <div style={{ marginTop: '20px', fontSize: '14px', color: '#666' }}>
        <h4>Troubleshooting Tips:</h4>
        <ul>
          <li>Make sure you clicked "Allow" when browser asked for camera permission</li>
          <li>Check that no other apps (OBS, Zoom, Teams) are using your camera</li>
          <li>Try refreshing the page</li>
          <li>For virtual cameras: Make sure OBS Virtual Camera is started</li>
          <li>Check browser settings: chrome://settings/content/camera</li>
        </ul>
      </div>
    </div>
  );
};

export default CameraTest;