// src/components/widgets/UpcomingEventsWidget.jsx
import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import {
  getFirestore,
  collection,
  query,
  where,
  orderBy,
  limit as qLimit,
  getDocs,
  Timestamp,
} from 'firebase/firestore';
import { Calendar, MapPin } from 'lucide-react';

function formatDate(d) {
  if (!d) return '';
  try {
    return new Intl.DateTimeFormat('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
    }).format(d);
  } catch {
    return '';
  }
}

/**
 * Upcoming events across the site. Uses the same `events` collection that
 * ArtistShowcasePage already reads from — no schema change needed.
 */
const UpcomingEventsWidget = ({ limitCount = 5 }) => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const run = async () => {
      try {
        const db = getFirestore();
        const q = query(
          collection(db, 'events'),
          where('startTime', '>', Timestamp.now()),
          orderBy('startTime', 'asc'),
          qLimit(limitCount)
        );
        const snap = await getDocs(q);
        setEvents(
          snap.docs.map((d) => {
            const data = d.data();
            return {
              id: d.id,
              ...data,
              startTime: data.startTime?.toDate?.() || null,
            };
          })
        );
      } catch (err) {
        console.warn('UpcomingEventsWidget error:', err.message);
        setError('Events not available yet.');
      } finally {
        setLoading(false);
      }
    };
    run();
  }, [limitCount]);

  if (loading) return <div className="events-empty">Loading events…</div>;
  if (error) return <div className="events-empty">{error}</div>;
  if (events.length === 0) {
    return <div className="events-empty">No upcoming events scheduled.</div>;
  }

  return (
    <ul className="events-list">
      {events.map((e) => (
        <li key={e.id} className="events-row">
          <div className="events-title">
            <Link to={`/streams/events/${e.id}`}>{e.title || 'Untitled event'}</Link>
          </div>
          <div className="events-meta">
            <span className="events-meta-item"><Calendar size={12} /> {formatDate(e.startTime)}</span>
            {e.venue && (
              <span className="events-meta-item"><MapPin size={12} /> {e.venue}</span>
            )}
          </div>
        </li>
      ))}
      <style>{`
        .events-list { list-style:none; padding:0; margin:0; display:flex; flex-direction:column; gap:6px; }
        .events-row { padding:10px 0; border-bottom:1px solid #f1f5f9; }
        .events-row:last-child { border-bottom:none; }
        .events-title a { font-weight:600; color:#0f172a; text-decoration:none; }
        .events-meta { display:flex; flex-wrap:wrap; gap:8px; font-size:12px; color:#4b5563; margin-top:4px; }
        .events-meta-item { display:inline-flex; align-items:center; gap:4px; }
        .events-empty { text-align:center; color:#6b7280; padding:24px 8px; font-size:14px; }
      `}</style>
    </ul>
  );
};

export default UpcomingEventsWidget;
