import { getFirestore, doc, setDoc, getDoc, updateDoc } from 'firebase/firestore';
import { getAuth } from 'firebase/auth';

/**
 * Service to handle premium membership status updates in Firebase
 * Updated to work with existing user document structure
 */
class PremiumStatusService {
  constructor() {
    this.db = getFirestore();
  }

  /**
   * Update user's premium status after successful payment
   * Uses existing fields: isPremium, premiumStartDate, premiumEndDate, premiumTier
   */
  async updatePremiumStatus(userId, paymentIntent, planDetails) {
    try {
      console.log('Updating premium status for user:', userId);
      
      const userRef = doc(this.db, 'users', userId);
      
      // Calculate dates
      const startDate = new Date();
      const endDate = new Date();
      
      // Set end date based on plan interval
      if (planDetails.interval === 'month') {
        endDate.setMonth(endDate.getMonth() + 1);
      } else if (planDetails.interval === 'year') {
        endDate.setFullYear(endDate.getFullYear() + 1);
      }
      
      // Create the premium status data matching existing structure
      const premiumData = {
        isPremium: true,
        premiumStartDate: startDate,
        premiumEndDate: endDate,
        premiumTier: planDetails.interval === 'month' ? 'monthly' : 'yearly'
      };
      
      // Update user document with existing field names
      await updateDoc(userRef, premiumData);
      
      console.log('Premium status updated successfully');
      return { success: true, data: premiumData };
    } catch (error) {
      console.error('Error updating premium status:', error);
      throw error;
    }
  }
  
  /**
   * Check if user has active premium membership
   * Uses existing fields from user document
   */
  async checkPremiumStatus(userId) {
    try {
      if (!userId) {
        return { isPremium: false };
      }
      
      const userRef = doc(this.db, 'users', userId);
      const userDoc = await getDoc(userRef);
      
      if (!userDoc.exists()) {
        return { isPremium: false };
      }
      
      const userData = userDoc.data();
      
      // Check the isPremium flag
      if (!userData.isPremium) {
        return { isPremium: false };
      }
      
      // Check if premium is still active (not expired)
      if (userData.premiumEndDate) {
        const expirationDate = userData.premiumEndDate.toDate();
        const now = new Date();
        
        if (expirationDate < now) {
          // Premium has expired
          return { 
            isPremium: false, 
            expired: true,
            expiredAt: expirationDate
          };
        }
      }
      
      return {
        isPremium: true,
        tier: userData.premiumTier,
        startDate: userData.premiumStartDate?.toDate(),
        endDate: userData.premiumEndDate?.toDate()
      };
    } catch (error) {
      console.error('Error checking premium status:', error);
      return { isPremium: false, error: error.message };
    }
  }
  
  /**
   * Cancel premium membership
   */
  async cancelPremiumMembership(userId) {
    try {
      const userRef = doc(this.db, 'users', userId);
      
      await updateDoc(userRef, {
        isPremium: false
      });
      
      return { success: true };
    } catch (error) {
      console.error('Error cancelling premium membership:', error);
      throw error;
    }
  }
  
  /**
   * Store payment record for history
   */
  async storePaymentRecord(userId, paymentIntent, planDetails) {
    try {
      // Add to transactions subcollection
      const transactionRef = doc(this.db, 'users', userId, 'transactions', paymentIntent.id);
      
      await setDoc(transactionRef, {
        amount: paymentIntent.amount,
        date: new Date(),
        duration: planDetails.interval === 'month' ? 30 : 365,
        id: paymentIntent.id,
        plan: planDetails.name,
        type: 'premium_subscription',
        createdAt: new Date()
      });
      
      return { success: true };
    } catch (error) {
      console.error('Error storing payment record:', error);
      // Don't throw here - this is not critical for the user experience
      return { success: false, error: error.message };
    }
  }
}

// Export a singleton instance
const premiumStatusService = new PremiumStatusService();
export default premiumStatusService;

// Export class for testing
export { PremiumStatusService };
