// Context orchestrator — Track B of the data layer.
//
// Runs slow-moving reference sources (BLS, EPA, Census, CDC, FBI) in
// parallel and caches the combined result. Unlike inputPipeline (Track A),
// this does NOT match against per-prediction text or produce weighted
// sentiment inputs — its output is a flat list of ContextSignal objects
// keyed by a `tag` field (see utils/contextCategories.js).
//
// Consumers:
//   - LiveDataContext stores the result in React state and exposes
//     runContextRefresh + getContextSignalsForTags to the UI.
//   - getSignalsForTags(tags) is also exported directly here for any
//     non-React consumer.

import blsService from './blsService'
import epaService from './epaService'
import censusService from './censusService'
import cdcService from './cdcService'
import fbiCrimeService from './fbiCrimeService'
import { MOCK_CONTEXT_SIGNALS } from '../../utils/mockContextSignals'

const CACHE_KEY = 'predict_context_signals'
const CACHE_TTL = 6 * 60 * 60 * 1000 // 6 hours — balance freshness vs API budget

function readCache() {
  try {
    const raw = localStorage.getItem(CACHE_KEY)
    if (!raw) return null
    const cached = JSON.parse(raw)
    if (!cached?.fetchedAt) return null
    if (Date.now() - cached.fetchedAt > CACHE_TTL) return null
    return cached
  } catch {
    return null
  }
}

function writeCache(payload) {
  try {
    localStorage.setItem(CACHE_KEY, JSON.stringify(payload))
  } catch {
    // Swallow quota errors — context is best-effort. If storage is full,
    // the next refresh will just re-fetch.
  }
}

const contextService = {
  // Run a full refresh: fire all context sources in parallel, collect signals,
  // cache, and return the combined payload. Errors per-source are captured in
  // the returned `errors` array but don't stop other sources from succeeding.
  async runContextRefresh() {
    const sources = { bls: false, epa: false, census: false, cdc: false, fbi: false }
    const errors = []
    const signals = []

    const tasks = [
      { name: 'bls', run: () => blsService.fetchAll() },
      { name: 'epa', run: () => epaService.fetchNationalAQI() },
      { name: 'census', run: () => censusService.fetchAll() },
      { name: 'cdc', run: () => cdcService.fetchAll() },
      { name: 'fbi', run: () => fbiCrimeService.fetchAll() },
    ]

    const outcomes = await Promise.allSettled(tasks.map(t => t.run()))
    outcomes.forEach((outcome, i) => {
      const name = tasks[i].name
      if (outcome.status === 'fulfilled') {
        const { signals: sigs, error } = outcome.value
        if (Array.isArray(sigs)) signals.push(...sigs)
        if (error) {
          errors.push({ source: name.toUpperCase(), error })
        } else {
          sources[name] = true
        }
      } else {
        errors.push({
          source: name.toUpperCase(),
          error: outcome.reason?.message || 'Task failed',
        })
      }
    })

    const payload = { signals, errors, sources, fetchedAt: Date.now() }
    writeCache(payload)
    return payload
  },

  getCached() {
    return readCache()
  },

  // Return signals for the given tags. Real (cached) signals take precedence;
  // mock signals fill in for tags not yet covered by a real source.
  getSignalsForTags(tags) {
    if (!Array.isArray(tags) || tags.length === 0) return []
    const wanted = new Set(tags)
    const cached = readCache()
    const real = (cached?.signals || []).filter(s => wanted.has(s.tag))
    const realTags = new Set(real.map(s => s.tag))
    const mockFill = MOCK_CONTEXT_SIGNALS.filter(
      s => wanted.has(s.tag) && !realTags.has(s.tag)
    )
    return [...real, ...mockFill]
  },

  clearCache() {
    try {
      localStorage.removeItem(CACHE_KEY)
    } catch {
      // ignore
    }
  },
}

export default contextService
