/**
 * FirebaseTraceDirectTest.js
 * 
 * A direct test script that can be run in the browser console to verify Firebase tracing
 * Run this script by loading it in the browser console:
 * 
 * import('/src/utils/FirebaseTraceDirectTest.js').then(m => m.runTest())
 */

// Import regular Firebase for comparison
import { db as regularDb, rtdb as regularRtdb } from '../firebase/firebase';
import { collection as regularCollection, getDocs as regularGetDocs } from 'firebase/firestore';
import { ref as regularRef, get as regularGet } from 'firebase/database';

// Import tracing utilities
import { enableFirebaseTracing, disableFirebaseTracing } from './firebaseTracingToggle';
import { clearAccessedPaths, getAllAccessedPaths, addAccessedPath } from './firebaseTracer';

// Test manually adding paths (this should always work regardless of Firebase integration)
export const testManualPathTracking = () => {
  console.group('%c🔍 Testing Manual Path Tracking', 'color: blue; font-weight: bold');
  
  // Clear any existing paths
  clearAccessedPaths();
  console.log('Cleared all paths');
  
  // Add some test paths
  addAccessedPath('database', 'manual/test/path1');
  addAccessedPath('database', 'manual/test/path2');
  addAccessedPath('firestore', 'manual/collection/doc1');
  addAccessedPath('firestore', 'manual/collection/doc2');
  console.log('Added 4 manual test paths');
  
  // Get the traced paths
  const paths = getAllAccessedPaths();
  console.log('Current traced paths:', paths);
  
  // Verify the test
  if (paths.length === 4) {
    console.log('%c✓ PASS: Manual path tracking is working correctly', 'color: green; font-weight: bold');
  } else {
    console.error('%c✗ FAIL: Manual path tracking is not working correctly', 'color: red; font-weight: bold');
  }
  
  // Clean up
  clearAccessedPaths();
  console.log('Cleared all paths');
  console.groupEnd();
  
  return paths.length === 4;
};

// Test tracing regular Firebase operations
export const testRegularOperations = async () => {
  console.group('%c🔍 Testing Regular Firebase Operations (Without Tracing)', 'color: blue; font-weight: bold');
  
  // Ensure tracing is disabled
  disableFirebaseTracing();
  console.log('Tracing disabled');
  
  // Clear any existing paths
  clearAccessedPaths();
  console.log('Cleared all paths');
  
  try {
    // Access Firestore
    console.log('Accessing Firestore collection...');
    const usersCollection = regularCollection(regularDb, 'users');
    const usersSnapshot = await regularGetDocs(usersCollection);
    console.log(`Found ${usersSnapshot.size} users`);
    
    // Access Realtime Database
    console.log('Accessing Realtime Database...');
    const statusRef = regularRef(regularRtdb, 'status');
    const statusSnapshot = await regularGet(statusRef);
    console.log('Status exists:', statusSnapshot.exists());
    
    // Check if paths were tracked (they should not be)
    const paths = getAllAccessedPaths();
    console.log('Current traced paths:', paths);
    
    // Verify the test
    if (paths.length === 0) {
      console.log('%c✓ PASS: Regular operations were not traced (as expected)', 'color: green; font-weight: bold');
    } else {
      console.error('%c✗ FAIL: Regular operations were traced when they shouldn\'t be', 'color: red; font-weight: bold');
    }
    
    return paths.length === 0;
  } catch (error) {
    console.error('Error during test:', error);
    return false;
  } finally {
    console.groupEnd();
  }
};

// Test traced Firebase operations
export const testTracedOperations = async () => {
  console.group('%c🔍 Testing Traced Firebase Operations', 'color: blue; font-weight: bold');
  
  // Enable tracing
  enableFirebaseTracing();
  console.log('Tracing enabled');
  
  // Clear any existing paths
  clearAccessedPaths();
  console.log('Cleared all paths');
  
  try {
    // Import the traced Firebase module
    console.log('Importing traced Firebase module...');
    const tracedFirebase = await import('../firebase/traced-firebase');
    console.log('Traced Firebase module imported:', Object.keys(tracedFirebase));
    
    // Access Firestore
    console.log('Accessing Firestore collection with traced functions...');
    const { db, collection, getDocs, doc, getDoc } = tracedFirebase;
    
    const usersCollection = collection(db, 'users');
    const usersSnapshot = await getDocs(usersCollection);
    console.log(`Found ${usersSnapshot.size} users`);
    
    // Access a specific document
    const settingsDoc = doc(db, 'settings', 'app_config');
    const settingsSnapshot = await getDoc(settingsDoc);
    console.log('Settings exists:', settingsSnapshot.exists());
    
    // Access Realtime Database
    console.log('Accessing Realtime Database with traced functions...');
    const { rtdb, ref, get } = tracedFirebase;
    
    const statusRef = ref(rtdb, 'status');
    const statusSnapshot = await get(statusRef);
    console.log('Status exists:', statusSnapshot.exists());
    
    // Check if paths were tracked
    const paths = getAllAccessedPaths();
    console.log('Current traced paths:', paths);
    
    // Verify the test
    if (paths.length > 0) {
      console.log('%c✓ PASS: Traced operations were tracked successfully', 'color: green; font-weight: bold');
    } else {
      console.error('%c✗ FAIL: Traced operations were not tracked', 'color: red; font-weight: bold');
    }
    
    return paths.length > 0;
  } catch (error) {
    console.error('Error during test:', error);
    return false;
  } finally {
    // Disable tracing
    disableFirebaseTracing();
    console.log('Tracing disabled');
    console.groupEnd();
  }
};

// Test tracing in a real-world scenario
export const testInRealScenario = async () => {
  console.group('%c🔍 Testing Firebase Tracing in a Real-world Scenario', 'color: blue; font-weight: bold');
  
  // Clear paths and enable tracing
  clearAccessedPaths();
  enableFirebaseTracing();
  console.log('Cleared all paths and enabled tracing');
  
  try {
    // Import the traced Firebase module
    const tracedFirebase = await import('../firebase/traced-firebase');
    
    // Get the collections and documents we want to access
    const collectionsToAccess = [
      'users',
      'settings',
      'rooms',
      'messages'
    ];
    
    // Document IDs to access in each collection
    const documentsToAccess = {
      'users': ['admin', 'test_user'],
      'settings': ['app_config', 'theme'],
      'rooms': ['general', 'random'],
      'messages': ['latest']
    };
    
    // Access all these paths
    const { db, collection, doc, getDoc, getDocs } = tracedFirebase;
    
    for (const collectionName of collectionsToAccess) {
      console.log(`Accessing collection: ${collectionName}`);
      
      // Try to access the collection
      const collectionRef = collection(db, collectionName);
      try {
        const snapshot = await getDocs(collectionRef);
        console.log(`Found ${snapshot.size} documents in ${collectionName}`);
      } catch (error) {
        console.warn(`Could not access collection ${collectionName}:`, error.message);
      }
      
      // Try to access specific documents
      const docIds = documentsToAccess[collectionName] || [];
      for (const docId of docIds) {
        console.log(`Accessing document: ${collectionName}/${docId}`);
        try {
          const docRef = doc(db, collectionName, docId);
          const docSnapshot = await getDoc(docRef);
          console.log(`Document ${collectionName}/${docId} exists:`, docSnapshot.exists());
        } catch (error) {
          console.warn(`Could not access document ${collectionName}/${docId}:`, error.message);
        }
      }
    }
    
    // Get the traced paths
    const paths = getAllAccessedPaths();
    console.log('Traced paths after real-world scenario:', paths);
    
    // Verify the test
    if (paths.length > 0) {
      console.log('%c✓ PASS: Real-world scenario tracking worked', 'color: green; font-weight: bold');
    } else {
      console.error('%c✗ FAIL: No paths were tracked in real-world scenario', 'color: red; font-weight: bold');
    }
    
    return paths.length > 0;
  } catch (error) {
    console.error('Error during real-world scenario test:', error);
    return false;
  } finally {
    // Disable tracing
    disableFirebaseTracing();
    console.log('Tracing disabled');
    console.groupEnd();
  }
};

// Run all tests in sequence
export const runTest = async () => {
  console.log('%c🔥 Starting Firebase Path Tracer Tests 🔍', 'font-size: 16px; font-weight: bold; color: purple;');
  
  // Test 1: Manual path tracking
  const test1Result = await testManualPathTracking();
  
  // Test 2: Regular operations (without tracing)
  const test2Result = await testRegularOperations();
  
  // Test 3: Traced operations
  const test3Result = await testTracedOperations();
  
  // Test 4: Real-world scenario
  const test4Result = await testInRealScenario();
  
  // Report overall results
  console.log('\n%c📊 TEST RESULTS:', 'font-size: 16px; font-weight: bold; color: blue;');
  console.log(`Manual Path Tracking: ${test1Result ? '✓ PASS' : '✗ FAIL'}`);
  console.log(`Regular Operations: ${test2Result ? '✓ PASS' : '✗ FAIL'}`);
  console.log(`Traced Operations: ${test3Result ? '✓ PASS' : '✗ FAIL'}`);
  console.log(`Real-world Scenario: ${test4Result ? '✓ PASS' : '✗ FAIL'}`);
  
  const allPassed = test1Result && test2Result && test3Result && test4Result;
  if (allPassed) {
    console.log('\n%c🎉 All tests passed! Firebase path tracing is working correctly.', 'font-size: 16px; font-weight: bold; color: green;');
  } else {
    console.error('\n%c❌ Some tests failed. See above for details.', 'font-size: 16px; font-weight: bold; color: red;');
  }
  
  return {
    manualPathTracking: test1Result,
    regularOperations: test2Result,
    tracedOperations: test3Result,
    realWorldScenario: test4Result,
    allPassed
  };
};

// Make it available in the browser console
window.FirebaseTraceTest = {
  testManualPathTracking,
  testRegularOperations,
  testTracedOperations,
  testInRealScenario,
  runTest
};

export default {
  testManualPathTracking,
  testRegularOperations,
  testTracedOperations,
  testInRealScenario,
  runTest
};