// Debug utility to check Firebase structure
// You can run this in the browser console to verify the structure

export const debugAudioMatchFirebase = async () => {
  const { db } = await import('../../../firebase');
  const { collection, getDocs } = await import('firebase/firestore');
  
  console.log('=== Audio Match Firebase Debug ===');
  
  try {
    // Check signatures collection
    const signaturesRef = collection(db, 'signatures');
    const signaturesSnapshot = await getDocs(signaturesRef);
    
    console.log('Signatures collections found:', signaturesSnapshot.docs.length);
    
    for (const roomDoc of signaturesSnapshot.docs) {
      const roomId = roomDoc.id;
      const roomData = roomDoc.data();
      
      console.log(`Room ${roomId}:`, roomData);
      
      // Check signatures subcollection
      const roomSignaturesRef = collection(db, 'signatures', roomId, 'signatures');
      const roomSignaturesSnapshot = await getDocs(roomSignaturesRef);
      
      console.log(`- Signatures in room ${roomId}:`, roomSignaturesSnapshot.docs.length);
      
      roomSignaturesSnapshot.docs.forEach(signatureDoc => {
        const signatureData = signatureDoc.data();
        console.log(`  - Signature ${signatureDoc.id}:`, {
          roomName: signatureData.roomName,
          keywords: signatureData.keywords,
          fingerprintPeaks: signatureData.fingerprint?.peaks?.length || 0,
          createdBy: signatureData.createdBy
        });
      });
    }
    
    // Check rooms collection
    const roomsRef = collection(db, 'rooms');
    const roomsSnapshot = await getDocs(roomsRef);
    
    console.log('\\nRooms found:', roomsSnapshot.docs.length);
    
    roomsSnapshot.docs.forEach(roomDoc => {
      const roomData = roomDoc.data();
      console.log(`Room ${roomDoc.id}:`, {
        name: roomData.name,
        type: roomData.type,
        keywords: roomData.keywords,
        createdBy: roomData.createdBy
      });
    });
    
  } catch (error) {
    console.error('Debug error:', error);
  }
};

// Add to window for easy access
if (typeof window !== 'undefined') {
  window.debugAudioMatch = debugAudioMatchFirebase;
}