import React, { useState, useEffect } from 'react';
import { 
  getFirestore, 
  collection, 
  query, 
  where, 
  orderBy, 
  onSnapshot,
  doc,
  getDoc
} from 'firebase/firestore';
import { 
  DollarSign, 
  TrendingUp, 
  Calendar, 
  Download,
  Filter,
  ChevronDown
} from 'lucide-react';
import './VenueEarnings.css';

const VenueEarnings = ({ venueId }) => {
  const [earnings, setEarnings] = useState([]);
  const [stats, setStats] = useState({
    totalEarnings: 0,
    monthlyEarnings: 0,
    weeklyEarnings: 0,
    totalTips: 0
  });
  const [loading, setLoading] = useState(true);
  const [timeFilter, setTimeFilter] = useState('all'); // all, month, week, day
  const [venueName, setVenueName] = useState('');
  
  useEffect(() => {
    if (!venueId) return;
    
    loadVenueInfo();
    loadEarningsData();
  }, [venueId, timeFilter]);

  const loadVenueInfo = async () => {
    try {
      const db = getFirestore();
      const venuesDoc = await getDoc(doc(db, 'admin', 'venues'));
      
      if (venuesDoc.exists()) {
        const venues = venuesDoc.data().venues || [];
        const venue = venues.find(v => v.id === venueId);
        if (venue) {
          setVenueName(venue.name);
        }
      }
    } catch (error) {
      console.error('Error loading venue info:', error);
    }
  };

  const loadEarningsData = () => {
    const db = getFirestore();
    
    // Calculate date filter
    let startDate = new Date(0); // Beginning of time
    const now = new Date();
    
    switch (timeFilter) {
      case 'day':
        startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        break;
      case 'week':
        startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
        break;
      case 'month':
        startDate = new Date(now.getFullYear(), now.getMonth(), 1);
        break;
    }

    // Query tips where venue is involved
    const tipsQuery = query(
      collection(db, 'tips'),
      where('venueId', '==', venueId),
      where('status', '==', 'completed'),
      orderBy('createdAt', 'desc')
    );

    const unsubscribe = onSnapshot(tipsQuery, (snapshot) => {
      const tipsData = [];
      let total = 0;
      let monthly = 0;
      let weekly = 0;
      
      const monthAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
      const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
      
      snapshot.forEach(doc => {
        const tip = { id: doc.id, ...doc.data() };
        const tipDate = tip.createdAt?.toDate ? tip.createdAt.toDate() : new Date(tip.createdAt);
        
        // Apply time filter
        if (tipDate >= startDate) {
          const venueShare = tip.venueSplit || 20; // Default 20% if not specified
          const venueAmount = (tip.amount * venueShare) / 100;
          
          tipsData.push({
            ...tip,
            venueAmount,
            date: tipDate
          });
          
          total += venueAmount;
          
          if (tipDate >= monthAgo) {
            monthly += venueAmount;
          }
          if (tipDate >= weekAgo) {
            weekly += venueAmount;
          }
        }
      });
      
      setEarnings(tipsData);
      setStats({
        totalEarnings: total,
        monthlyEarnings: monthly,
        weeklyEarnings: weekly,
        totalTips: tipsData.length
      });
      setLoading(false);
    });

    return () => unsubscribe();
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD'
    }).format(amount || 0);
  };

  const formatDate = (date) => {
    return new Intl.DateTimeFormat('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    }).format(date);
  };

  const exportEarnings = () => {
    // Create CSV content
    const headers = ['Date', 'Event', 'Artist', 'Total Tip', 'Venue Share %', 'Venue Earnings', 'Tipper'];
    const rows = earnings.map(earning => [
      formatDate(earning.date),
      earning.eventTitle || 'N/A',
      earning.artistName || 'N/A',
      formatCurrency(earning.amount),
      `${earning.venueSplit || 20}%`,
      formatCurrency(earning.venueAmount),
      earning.userName || 'Anonymous'
    ]);
    
    const csvContent = [headers, ...rows]
      .map(row => row.map(cell => `"${cell}"`).join(','))
      .join('\n');
    
    // Download CSV
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `venue-earnings-${venueName}-${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  if (loading) {
    return (
      <div className="venue-earnings-loading">
        <div className="loading-spinner"></div>
        <p>Loading earnings data...</p>
      </div>
    );
  }

  return (
    <div className="venue-earnings">
      <div className="earnings-header">
        <div className="header-content">
          <h2>Earnings Overview</h2>
          <p>Track your venue's revenue from events and tips</p>
        </div>
        
        <div className="header-actions">
          <div className="filter-dropdown">
            <button className="filter-button">
              <Filter size={16} />
              <span>{timeFilter === 'all' ? 'All Time' : 
                     timeFilter === 'month' ? 'This Month' :
                     timeFilter === 'week' ? 'This Week' : 'Today'}</span>
              <ChevronDown size={16} />
            </button>
            <div className="dropdown-content">
              <button onClick={() => setTimeFilter('all')}>All Time</button>
              <button onClick={() => setTimeFilter('month')}>This Month</button>
              <button onClick={() => setTimeFilter('week')}>This Week</button>
              <button onClick={() => setTimeFilter('day')}>Today</button>
            </div>
          </div>
          
          <button className="export-button" onClick={exportEarnings}>
            <Download size={16} />
            Export CSV
          </button>
        </div>
      </div>

      <div className="earnings-stats">
        <div className="stat-card primary">
          <div className="stat-icon">
            <DollarSign size={24} />
          </div>
          <div className="stat-content">
            <h3>Total Earnings</h3>
            <p className="stat-value">{formatCurrency(stats.totalEarnings)}</p>
            <p className="stat-label">From {stats.totalTips} tips</p>
          </div>
        </div>
        
        <div className="stat-card">
          <div className="stat-icon">
            <TrendingUp size={24} />
          </div>
          <div className="stat-content">
            <h3>Monthly Earnings</h3>
            <p className="stat-value">{formatCurrency(stats.monthlyEarnings)}</p>
            <p className="stat-label">Last 30 days</p>
          </div>
        </div>
        
        <div className="stat-card">
          <div className="stat-icon">
            <Calendar size={24} />
          </div>
          <div className="stat-content">
            <h3>Weekly Earnings</h3>
            <p className="stat-value">{formatCurrency(stats.weeklyEarnings)}</p>
            <p className="stat-label">Last 7 days</p>
          </div>
        </div>
      </div>

      <div className="earnings-table">
        <h3>Transaction History</h3>
        <div className="table-container">
          <table>
            <thead>
              <tr>
                <th>Date</th>
                <th>Event</th>
                <th>Artist</th>
                <th>Total Tip</th>
                <th>Venue Share</th>
                <th>Your Earnings</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {earnings.length === 0 ? (
                <tr>
                  <td colSpan="7" className="empty-state">
                    No earnings recorded yet
                  </td>
                </tr>
              ) : (
                earnings.map(earning => (
                  <tr key={earning.id}>
                    <td>{formatDate(earning.date)}</td>
                    <td>{earning.eventTitle || 'N/A'}</td>
                    <td>{earning.artistName || 'N/A'}</td>
                    <td>{formatCurrency(earning.amount)}</td>
                    <td>{earning.venueSplit || 20}%</td>
                    <td className="earnings-amount">{formatCurrency(earning.venueAmount)}</td>
                    <td>
                      <span className="status-badge completed">Completed</span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default VenueEarnings;