// src/utils/firebaseRulesBuilder.js
import { getDeniedAccessLogs, getAccessPatterns } from './firebaseAuditUtils';

/**
 * Parser for Firestore paths
 * @param {string} path - Firestore path
 * @returns {Object} Parsed path components
 */
const parsePath = (path) => {
  const parts = path.split('/');
  const result = {
    collections: [],
    documents: [],
    pathParts: []
  };
  
  // Parse collections and documents
  for (let i = 0; i < parts.length; i++) {
    if (i % 2 === 0) {
      // Even indexes are collections
      if (parts[i]) {
        result.collections.push(parts[i]);
        result.pathParts.push({ type: 'collection', value: parts[i] });
      }
    } else {
      // Odd indexes are documents
      if (parts[i]) {
        result.documents.push(parts[i]);
        result.pathParts.push({ type: 'document', value: parts[i] });
      }
    }
  }
  
  return result;
};

/**
 * Generates a Firestore path pattern for rules
 * @param {string} path - Firestore path
 * @returns {string} Path pattern for rules
 */
const generatePathPattern = (path) => {
  const parsed = parsePath(path);
  let rulePattern = '';
  
  parsed.pathParts.forEach((part, index) => {
    if (part.type === 'collection') {
      rulePattern += `${part.value}/`;
    } else {
      // Check if this looks like a document ID or a variable
      if (part.value.match(/^[a-zA-Z0-9]{20,}$/)) {
        // Appears to be a document ID, replace with variable
        const collectionName = parsed.pathParts[index - 1].value;
        const singularName = collectionName.endsWith('s') 
          ? collectionName.substring(0, collectionName.length - 1) 
          : collectionName;
        
        rulePattern += `{${singularName}Id}/`;
      } else {
        // Use the document name as-is
        rulePattern += `${part.value}/`;
      }
    }
  });
  
  // Remove trailing slash
  return rulePattern.endsWith('/') ? rulePattern.slice(0, -1) : rulePattern;
};

/**
 * Analyzes an error message to suggest a rule fix
 * @param {string} operation - Firestore operation
 * @param {string} errorMessage - Error message
 * @returns {string} Suggested rule condition
 */
const analyzeErrorForRule = (operation, errorMessage) => {
  // Error could be a string or parsed JSON object
  const errorString = typeof errorMessage === 'string' 
    ? errorMessage 
    : JSON.stringify(errorMessage);
  
  if (errorString.includes('permission-denied')) {
    // Permission denied error
    
    if (operation === 'read' || operation === 'get' || operation === 'list') {
      return 'request.auth != null';
    } else if (operation === 'create') {
      return 'request.auth != null && request.auth.uid == request.resource.data.userId';
    } else if (operation === 'update') {
      return 'request.auth != null && request.auth.uid == resource.data.userId';
    } else if (operation === 'delete') {
      return 'request.auth != null && request.auth.uid == resource.data.userId';
    }
  }
  
  // If we can't determine a specific rule, default to requiring authentication
  return 'request.auth != null';
};

/**
 * Determines the rule operation for a Firestore operation
 * @param {string} operation - Firestore operation
 * @returns {string} Rule operation
 */
const getRuleOperation = (operation) => {
  switch (operation) {
    case 'read':
    case 'get':
    case 'list':
      return 'read';
    case 'create':
    case 'add':
      return 'create';
    case 'update':
    case 'set':
      return 'update';
    case 'delete':
      return 'delete';
    default:
      return operation;
  }
};

/**
 * Parses existing Firestore rules
 * @param {string} rulesString - Existing rules as a string
 * @returns {Object} Parsed rules structure
 */
export const parseExistingRules = (rulesString) => {
  // Basic structure to hold parsed rules
  const result = {
    version: '2',
    services: {},
    rawText: rulesString
  };
  
  // Extract rules version
  const versionMatch = rulesString.match(/rules_version\s*=\s*['"](\d+)['"];/);
  if (versionMatch) {
    result.version = versionMatch[1];
  }
  
  // Extract service blocks
  const serviceMatches = rulesString.matchAll(/service\s+([a-z.]+)\s*{([^}]*)}/gs);
  
  for (const match of serviceMatches) {
    const serviceName = match[1];
    const serviceContent = match[2];
    
    result.services[serviceName] = {
      matches: [],
      rawText: serviceContent
    };
    
    // Extract match blocks
    const matchMatches = serviceContent.matchAll(/match\s+([^{]+)\s*{([^}]*)}/gs);
    
    for (const matchMatch of matchMatches) {
      const matchPath = matchMatch[1].trim();
      const matchContent = matchMatch[2];
      
      const matchObj = {
        path: matchPath,
        rules: [],
        subMatches: [],
        rawText: matchContent
      };
      
      // Extract rules
      const ruleMatches = matchContent.matchAll(/allow\s+([^:]+):\s*if\s+([^;]+);/g);
      
      for (const ruleMatch of ruleMatches) {
        const operations = ruleMatch[1].trim().split(/\s*,\s*/);
        const condition = ruleMatch[2].trim();
        
        operations.forEach(operation => {
          matchObj.rules.push({
            operation,
            condition
          });
        });
      }
      
      // Extract sub-matches recursively (not implemented fully here)
      const subMatchMatches = matchContent.matchAll(/match\s+([^{]+)\s*{([^}]*)}/gs);
      
      for (const subMatch of subMatchMatches) {
        const subMatchPath = subMatch[1].trim();
        const subMatchContent = subMatch[2];
        
        // Simplification - don't recursively parse
        matchObj.subMatches.push({
          path: subMatchPath,
          rawText: subMatchContent
        });
      }
      
      result.services[serviceName].matches.push(matchObj);
    }
  }
  
  return result;
};

/**
 * Generates rule text from a rule object
 * @param {Object} ruleObj - Rule object
 * @returns {string} Rule text
 */
const generateRuleText = (ruleObj) => {
  return `    allow ${ruleObj.operation}: if ${ruleObj.condition};`;
};

/**
 * Converts a parsed rules object back to a string
 * @param {Object} parsedRules - Parsed rules object
 * @returns {string} Rules as a string
 */
const generateRulesString = (parsedRules) => {
  let result = `rules_version = '${parsedRules.version}';\n`;
  
  Object.entries(parsedRules.services).forEach(([serviceName, service]) => {
    result += `service ${serviceName} {\n`;
    
    service.matches.forEach(match => {
      result += `  match ${match.path} {\n`;
      
      match.rules.forEach(rule => {
        result += `${generateRuleText(rule)}\n`;
      });
      
      match.subMatches.forEach(subMatch => {
        result += `    match ${subMatch.path} {\n`;
        result += `${subMatch.rawText}\n`;
        result += `    }\n`;
      });
      
      result += `  }\n`;
    });
    
    result += `}\n`;
  });
  
  return result;
};

/**
 * Builds suggested Firestore rules based on denied access logs
 * @returns {Promise<string>} Suggested rules
 */
export const buildSuggestedRules = async () => {
  try {
    // Get denied access logs
    const deniedLogs = await getDeniedAccessLogs();
    
    // If no denied logs, no suggestions needed
    if (deniedLogs.length === 0) {
      return null;
    }
    
    // Group by path and operation
    const suggestions = {};
    
    for (const log of deniedLogs) {
      const pathPattern = generatePathPattern(log.path);
      const ruleOperation = getRuleOperation(log.operation);
      
      if (!suggestions[pathPattern]) {
        suggestions[pathPattern] = {};
      }
      
      if (!suggestions[pathPattern][ruleOperation]) {
        suggestions[pathPattern][ruleOperation] = {
          count: 0,
          errors: [],
          suggestedCondition: null
        };
      }
      
      suggestions[pathPattern][ruleOperation].count += 1;
      
      // Only keep unique errors
      const errorString = JSON.stringify(log.error);
      if (!suggestions[pathPattern][ruleOperation].errors.includes(errorString)) {
        suggestions[pathPattern][ruleOperation].errors.push(errorString);
      }
    }
    
    // Analyze each group to suggest rules
    for (const pathPattern of Object.keys(suggestions)) {
      for (const operation of Object.keys(suggestions[pathPattern])) {
        const suggestion = suggestions[pathPattern][operation];
        
        // Use the most frequent error to suggest a rule
        const mainError = suggestion.errors[0];
        suggestion.suggestedCondition = analyzeErrorForRule(operation, mainError);
      }
    }
    
    return suggestions;
  } catch (error) {
    console.error('[Rules Builder] Error building suggested rules:', error);
    return null;
  }
};

/**
 * Merges suggested rules with existing rules
 * @param {string} existingRules - Existing Firestore rules
 * @param {Object} suggestedRules - Suggested rules object
 * @returns {string} Merged rules string
 */
export const mergeRulesWithSuggestions = (existingRules, suggestedRules) => {
  if (!suggestedRules) return existingRules;
  
  // Parse existing rules
  const parsedRules = parseExistingRules(existingRules);
  
  // Check if Firestore service exists
  if (!parsedRules.services['cloud.firestore']) {
    parsedRules.services['cloud.firestore'] = {
      matches: [],
      rawText: ''
    };
  }
  
  // Find the root match
  let rootMatch = parsedRules.services['cloud.firestore'].matches.find(
    match => match.path === '/databases/{database}/documents'
  );
  
  if (!rootMatch) {
    rootMatch = {
      path: '/databases/{database}/documents',
      rules: [],
      subMatches: [],
      rawText: ''
    };
    parsedRules.services['cloud.firestore'].matches.push(rootMatch);
  }
  
  // Process each suggested rule
  for (const pathPattern of Object.keys(suggestedRules)) {
    // Find if this path already exists in the rules
    let matchFound = false;
    
    // Check sub-matches
    for (const subMatch of rootMatch.subMatches) {
      if (subMatch.path === pathPattern) {
        matchFound = true;
        
        // If found, add suggested operations to this path
        const operations = Object.keys(suggestedRules[pathPattern]);
        
        // Extract existing rules from the raw text
        const existingRules = [];
        const ruleMatches = subMatch.rawText.matchAll(/allow\s+([^:]+):\s*if\s+([^;]+);/g);
        
        for (const ruleMatch of Array.from(ruleMatches)) {
          const subOperations = ruleMatch[1].trim().split(/\s*,\s*/);
          const condition = ruleMatch[2].trim();
          
          subOperations.forEach(op => {
            existingRules.push({
              operation: op,
              condition
            });
          });
        }
        
        // Prepare new rule text
        let newRuleText = subMatch.rawText;
        
        // Add suggested rules for missing operations
        for (const operation of operations) {
          if (!existingRules.some(rule => rule.operation === operation)) {
            const suggestedCondition = suggestedRules[pathPattern][operation].suggestedCondition;
            
            // Add new rule to the start of the match
            newRuleText = `allow ${operation}: if ${suggestedCondition};\n      ${newRuleText}`;
          }
        }
        
        // Update the sub-match
        subMatch.rawText = newRuleText;
        break;
      }
    }
    
    // If path not found, add a new sub-match
    if (!matchFound) {
      const operations = Object.keys(suggestedRules[pathPattern]);
      let ruleText = '';
      
      operations.forEach(operation => {
        const suggestedCondition = suggestedRules[pathPattern][operation].suggestedCondition;
        ruleText += `allow ${operation}: if ${suggestedCondition};\n      `;
      });
      
      rootMatch.subMatches.push({
        path: pathPattern,
        rawText: ruleText
      });
    }
  }
  
  // Convert back to string
  return generateRulesString(parsedRules);
};

/**
 * Gets suggested rules updates
 * @param {string} existingRules - Existing Firestore rules
 * @returns {Promise<string>} Updated rules
 */
export const getSuggestedRulesUpdates = async (existingRules) => {
  try {
    const suggestedRules = await buildSuggestedRules();
    
    if (!suggestedRules) {
      return existingRules;
    }
    
    return mergeRulesWithSuggestions(existingRules, suggestedRules);
  } catch (error) {
    console.error('[Rules Builder] Error getting suggested rules updates:', error);
    return existingRules;
  }
};