// Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\components\audio\DJStudioMixerPolished.jsx

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { 
  Play, 
  Pause, 
  Square, 
  Volume2, 
  VolumeX,
  Headphones,
  Radio,
  Upload,
  FolderOpen,
  SkipBack,
  SkipForward,
  RotateCcw,
  Settings,
  Disc,
  Mic,
  Music,
  Shuffle,
  Repeat,
  Loader,
  AlertCircle,
  CheckCircle
} from 'lucide-react';

const DJStudioMixerPolished = () => {
  const { currentUser } = useAuth();
  
  // Loading and error states
  const [isInitializing, setIsInitializing] = useState(true);
  const [initError, setInitError] = useState(null);
  const [trackLoadingStates, setTrackLoadingStates] = useState({
    A: false,
    B: false
  });

  // Core states
  const [isRecording, setIsRecording] = useState(false);
  const [isStreaming, setIsStreaming] = useState(false);
  const [masterVolume, setMasterVolume] = useState(80);
  const [crossfaderPosition, setCrossfaderPosition] = useState(50);
  const [cueVolume, setCueVolume] = useState(70);
  
  // Enhanced deck state with loading indicators
  const [deckA, setDeckA] = useState({
    track: null,
    isPlaying: false,
    volume: 80,
    gain: 0,
    eqHigh: 0,
    eqMid: 0,
    eqLow: 0,
    bpm: null,
    position: 0,
    duration: 0,
    cuePoint: 0,
    pitchBend: 0,
    tempoSlider: 0,
    keyLock: false,
    sync: false,
    loading: false,
    error: null
  });
  
  const [deckB, setDeckB] = useState({
    track: null,
    isPlaying: false,
    volume: 80,
    gain: 0,
    eqHigh: 0,
    eqMid: 0,
    eqLow: 0,
    bpm: null,
    position: 0,
    duration: 0,
    cuePoint: 0,
    pitchBend: 0,
    tempoSlider: 0,
    keyLock: false,
    sync: false,
    loading: false,
    error: null
  });

  // Library state with enhanced feedback
  const [library, setLibrary] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [showLibrary, setShowLibrary] = useState(true);
  const [selectedTrack, setSelectedTrack] = useState(null);
  const [draggedTrack, setDraggedTrack] = useState(null);
  const [uploadProgress, setUploadProgress] = useState(null);

  // Audio context refs
  const audioContextRef = useRef(null);
  const deckASourceRef = useRef(null);
  const deckBSourceRef = useRef(null);
  const fileInputRef = useRef(null);

  // Debounced slider updates for better performance
  const debouncedVolumeUpdate = useCallback(
    debounce((deck, volume) => {
      console.log(`Volume updated: Deck ${deck} = ${volume}%`);
      // Apply actual volume change here
    }, 50),
    []
  );

  // Initialize audio context with better error handling
  useEffect(() => {
    initializeAudioContext();
    return () => {
      cleanup();
    };
  }, []);

  const initializeAudioContext = async () => {
    try {
      setIsInitializing(true);
      setInitError(null);

      // Check for Web Audio API support
      if (!window.AudioContext && !window.webkitAudioContext) {
        throw new Error('Web Audio API not supported in this browser');
      }

      audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)();
      
      // Handle suspended audio context (common after Chrome autoplay policy)
      if (audioContextRef.current.state === 'suspended') {
        console.log('Audio context suspended, will resume on user interaction');
      }

      console.log('✅ Audio system initialized successfully');
      setIsInitializing(false);
    } catch (error) {
      console.error('❌ Failed to initialize audio system:', error);
      setInitError(error.message);
      setIsInitializing(false);
    }
  };

  const cleanup = () => {
    if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
      audioContextRef.current.close();
    }
  };

  // Resume audio context on user interaction
  const resumeAudioContext = async () => {
    if (audioContextRef.current && audioContextRef.current.state === 'suspended') {
      try {
        await audioContextRef.current.resume();
        console.log('Audio context resumed');
      } catch (error) {
        console.error('Failed to resume audio context:', error);
      }
    }
  };

  // Enhanced file upload with progress and validation
  const handleFileUpload = async (event) => {
    const files = Array.from(event.target.files);
    
    setUploadProgress({ total: files.length, completed: 0 });

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      
      try {
        // Validate file format
        const supportedFormats = ['audio/mpeg', 'audio/aac', 'audio/wav', 'audio/flac', 'audio/aiff'];
        if (!supportedFormats.includes(file.type)) {
          throw new Error(`Unsupported format: ${file.type}`);
        }

        // Validate file size (max 50MB)
        if (file.size > 50 * 1024 * 1024) {
          throw new Error('File too large (max 50MB)');
        }

        const url = URL.createObjectURL(file);
        const track = {
          id: Date.now() + Math.random(),
          name: file.name.replace(/\.[^/.]+$/, ''),
          artist: 'Unknown Artist',
          album: 'Unknown Album',
          url: url,
          format: file.type,
          size: file.size,
          artwork: null,
          status: 'ready'
        };
        
        setLibrary(prev => [track, ...prev]);
        setUploadProgress(prev => ({ ...prev, completed: prev.completed + 1 }));
        
      } catch (error) {
        console.error(`Failed to process ${file.name}:`, error);
        // Could add error notification here
      }
    }

    // Clear upload progress after a delay
    setTimeout(() => setUploadProgress(null), 2000);
    event.target.value = '';
  };

  // Enhanced track loading with proper error handling
  const loadTrackToDeck = async (track, deck) => {
    const setDeck = deck === 'A' ? setDeckA : setDeckB;
    
    try {
      // Resume audio context if needed
      await resumeAudioContext();
      
      setDeck(prev => ({ ...prev, loading: true, error: null }));
      setTrackLoadingStates(prev => ({ ...prev, [deck]: true }));

      const response = await fetch(track.url);
      if (!response.ok) {
        throw new Error(`Failed to fetch track: ${response.status}`);
      }

      const arrayBuffer = await response.arrayBuffer();
      const audioBuffer = await audioContextRef.current.decodeAudioData(arrayBuffer);
      
      // Enhanced BPM detection (placeholder - would use actual algorithm)
      const bpm = await detectBPM(audioBuffer);
      
      const trackData = {
        ...track,
        audioBuffer,
        bpm: bpm || 'Unknown',
        duration: audioBuffer.duration,
        status: 'loaded'
      };
      
      setDeck(prev => ({ 
        ...prev, 
        track: trackData, 
        bpm, 
        duration: audioBuffer.duration,
        loading: false,
        error: null,
        position: 0
      }));

      console.log(`✅ Track loaded to Deck ${deck}:`, trackData.name);
      
    } catch (error) {
      console.error(`❌ Failed to load track to Deck ${deck}:`, error);
      setDeck(prev => ({ 
        ...prev, 
        loading: false, 
        error: error.message 
      }));
    } finally {
      setTrackLoadingStates(prev => ({ ...prev, [deck]: false }));
    }
  };

  // Simplified BPM detection (placeholder)
  const detectBPM = async (audioBuffer) => {
    // In a real implementation, this would be a sophisticated BPM detection algorithm
    return new Promise(resolve => {
      setTimeout(() => {
        const fakeBPM = 120 + Math.floor(Math.random() * 60); // 120-180 BPM
        resolve(fakeBPM);
      }, 500);
    });
  };

  // Enhanced deck controls with haptic feedback
  const playPauseDeck = async (deck) => {
    await resumeAudioContext();
    
    // Haptic feedback for mobile devices
    if (navigator.vibrate) {
      navigator.vibrate(50);
    }

    if (deck === 'A') {
      setDeckA(prev => ({ ...prev, isPlaying: !prev.isPlaying }));
    } else {
      setDeckB(prev => ({ ...prev, isPlaying: !prev.isPlaying }));
    }
  };

  // Enhanced volume control with debouncing
  const updateDeckVolume = (deck, volume) => {
    if (deck === 'A') {
      setDeckA(prev => ({ ...prev, volume }));
    } else {
      setDeckB(prev => ({ ...prev, volume }));
    }
    debouncedVolumeUpdate(deck, volume);
  };

  // Drag and drop with visual feedback
  const handleDragStart = (track) => {
    setDraggedTrack(track);
  };

  const handleDragOver = (event) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = async (event, deck) => {
    event.preventDefault();
    if (draggedTrack) {
      await loadTrackToDeck(draggedTrack, deck);
      setDraggedTrack(null);
    }
  };

  // Format time with better precision
  const formatTime = (seconds) => {
    if (isNaN(seconds) || seconds < 0) return '0:00';
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // Filter library with better search
  const filteredLibrary = library.filter(track =>
    track.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    track.artist.toLowerCase().includes(searchQuery.toLowerCase()) ||
    track.album.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // Loading screen
  if (isInitializing) {
    return (
      <div className="dj-studio-loading">
        <div className="loading-content">
          <Loader size={48} className="loading-spinner" />
          <h2>Initializing DJ Studio</h2>
          <p>Setting up audio system...</p>
        </div>
      </div>
    );
  }

  // Error screen
  if (initError) {
    return (
      <div className="dj-studio-error">
        <div className="error-content">
          <AlertCircle size={48} className="error-icon" />
          <h2>Audio System Error</h2>
          <p>{initError}</p>
          <button onClick={initializeAudioContext} className="retry-btn">
            Try Again
          </button>
        </div>
      </div>
    );
  }

  // Main DJ Studio Interface
  return (
    <div className="dj-studio-mixer polished">
      {/* Enhanced Header */}
      <div className="mixer-header">
        <div className="logo-section">
          <Music size={24} />
          <h1>TalkStudio DJ</h1>
          <div className="status-indicator">
            <CheckCircle size={16} className="ready-icon" />
            <span>Ready</span>
          </div>
        </div>
        
        <div className="stream-controls">
          {uploadProgress && (
            <div className="upload-progress">
              <span>Uploading {uploadProgress.completed}/{uploadProgress.total}</span>
            </div>
          )}
          
          <button 
            onClick={() => setIsRecording(!isRecording)}
            className={`record-btn ${isRecording ? 'recording' : ''}`}
          >
            <Disc size={16} />
            {isRecording ? 'Stop Recording' : 'Record'}
          </button>
          
          <button 
            onClick={() => setIsStreaming(!isStreaming)}
            className={`stream-btn ${isStreaming ? 'streaming' : ''}`}
          >
            <Radio size={16} />
            {isStreaming ? 'Stop Stream' : 'Go Live'}
          </button>
        </div>
      </div>

      <div className="mixer-layout">
        {/* Enhanced Library Panel */}
        {showLibrary && (
          <div className="library-panel">
            <div className="library-header">
              <h3>Library ({library.length})</h3>
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="upload-btn"
                title="Upload audio files"
              >
                <Upload size={16} />
              </button>
            </div>
            
            <div className="search-bar">
              <input
                type="text"
                placeholder="Search by title, artist, or album..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
            
            <div className="track-list">
              {filteredLibrary.length === 0 ? (
                <div className="empty-library">
                  {library.length === 0 ? (
                    <>
                      <Music size={32} className="empty-icon" />
                      <p>No tracks in library</p>
                      <button 
                        onClick={() => fileInputRef.current?.click()}
                        className="upload-first-btn"
                      >
                        Upload Music
                      </button>
                    </>
                  ) : (
                    <p>No tracks match your search</p>
                  )}
                </div>
              ) : (
                filteredLibrary.map(track => (
                  <div
                    key={track.id}
                    className="track-item"
                    draggable
                    onDragStart={() => handleDragStart(track)}
                    onClick={() => setSelectedTrack(track)}
                  >
                    <div className="track-artwork">
                      {track.artwork ? (
                        <img src={track.artwork} alt="" />
                      ) : (
                        <Music size={16} />
                      )}
                    </div>
                    
                    <div className="track-info">
                      <div className="track-name" title={track.name}>{track.name}</div>
                      <div className="track-artist" title={track.artist}>{track.artist}</div>
                    </div>
                    
                    <div className="track-meta">
                      {track.bpm && <span className="bpm">{track.bpm}</span>}
                    </div>
                  </div>
                ))
              )}
            </div>
            
            <input
              ref={fileInputRef}
              type="file"
              multiple
              accept=".mp3,.aac,.wav,.flac,.aiff,audio/*"
              onChange={handleFileUpload}
              style={{ display: 'none' }}
            />
          </div>
        )}

        {/* Enhanced Main Mixer */}
        <div className="mixer-main">
          {/* Enhanced Deck A */}
          <div 
            className={`deck deck-a ${draggedTrack ? 'drag-target' : ''}`}
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, 'A')}
          >
            <div className="deck-header">
              <h3>DECK A</h3>
              {trackLoadingStates.A && (
                <div className="loading-indicator">
                  <Loader size={16} className="loading-spin" />
                  Loading...
                </div>
              )}
            </div>
            
            <div className="deck-info">
              {deckA.loading ? (
                <div className="track-loading">
                  <Loader size={20} className="loading-spin" />
                  <span>Loading track...</span>
                </div>
              ) : deckA.error ? (
                <div className="track-error">
                  <AlertCircle size={20} />
                  <span>{deckA.error}</span>
                </div>
              ) : deckA.track ? (
                <>
                  <span className="track-name" title={deckA.track.name}>{deckA.track.name}</span>
                  <span className="track-artist" title={deckA.track.artist}>{deckA.track.artist}</span>
                  {deckA.bpm && <span className="bpm">{deckA.bpm} BPM</span>}
                </>
              ) : (
                <span className="no-track">
                  {draggedTrack ? 'Drop here to load' : 'Drag track here or double-click library track'}
                </span>
              )}
            </div>
            
            <div className="deck-display">
              <div className="waveform-placeholder">
                {deckA.track ? 'Waveform' : 'No track loaded'}
              </div>
              <div className="position-info">
                <span>{formatTime(deckA.position)}</span>
                <span>/</span>
                <span>{formatTime(deckA.duration)}</span>
              </div>
            </div>
            
            <div className="deck-controls">
              <div className="transport-controls">
                <button 
                  onClick={() => playPauseDeck('A')}
                  className="play-pause-btn"
                  disabled={!deckA.track || deckA.loading}
                  title={deckA.isPlaying ? 'Pause' : 'Play'}
                >
                  {deckA.isPlaying ? <Pause size={20} /> : <Play size={20} />}
                </button>
              </div>
              
              <div className="volume-control">
                <label>VOLUME</label>
                <input
                  type="range"
                  min="0"
                  max="100"
                  value={deckA.volume}
                  onChange={(e) => updateDeckVolume('A', parseInt(e.target.value))}
                  className="volume-slider"
                  title={`Volume: ${deckA.volume}%`}
                />
                <span>{deckA.volume}%</span>
              </div>
            </div>
          </div>

          {/* Enhanced Crossfader Section */}
          <div className="crossfader-section">
            <div className="master-volume">
              <label>MASTER</label>
              <input
                type="range"
                min="0"
                max="100"
                value={masterVolume}
                onChange={(e) => setMasterVolume(parseInt(e.target.value))}
                className="master-volume-slider"
                title={`Master Volume: ${masterVolume}%`}
              />
              <span>{masterVolume}%</span>
            </div>
            
            <div className="crossfader">
              <label>CROSSFADER</label>
              <input
                type="range"
                min="0"
                max="100"
                value={crossfaderPosition}
                onChange={(e) => setCrossfaderPosition(parseInt(e.target.value))}
                className="crossfader-slider"
                title={`Crossfader: ${crossfaderPosition < 25 ? 'Deck A' : crossfaderPosition > 75 ? 'Deck B' : 'Center'}`}
              />
              <div className="crossfader-labels">
                <span>A</span>
                <span>B</span>
              </div>
            </div>
          </div>

          {/* Enhanced Deck B */}
          <div 
            className={`deck deck-b ${draggedTrack ? 'drag-target' : ''}`}
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, 'B')}
          >
            <div className="deck-header">
              <h3>DECK B</h3>
              {trackLoadingStates.B && (
                <div className="loading-indicator">
                  <Loader size={16} className="loading-spin" />
                  Loading...
                </div>
              )}
            </div>
            
            <div className="deck-info">
              {deckB.loading ? (
                <div className="track-loading">
                  <Loader size={20} className="loading-spin" />
                  <span>Loading track...</span>
                </div>
              ) : deckB.error ? (
                <div className="track-error">
                  <AlertCircle size={20} />
                  <span>{deckB.error}</span>
                </div>
              ) : deckB.track ? (
                <>
                  <span className="track-name" title={deckB.track.name}>{deckB.track.name}</span>
                  <span className="track-artist" title={deckB.track.artist}>{deckB.track.artist}</span>
                  {deckB.bpm && <span className="bpm">{deckB.bpm} BPM</span>}
                </>
              ) : (
                <span className="no-track">
                  {draggedTrack ? 'Drop here to load' : 'Drag track here or double-click library track'}
                </span>
              )}
            </div>
            
            <div className="deck-display">
              <div className="waveform-placeholder">
                {deckB.track ? 'Waveform' : 'No track loaded'}
              </div>
              <div className="position-info">
                <span>{formatTime(deckB.position)}</span>
                <span>/</span>
                <span>{formatTime(deckB.duration)}</span>
              </div>
            </div>
            
            <div className="deck-controls">
              <div className="transport-controls">
                <button 
                  onClick={() => playPauseDeck('B')}
                  className="play-pause-btn"
                  disabled={!deckB.track || deckB.loading}
                  title={deckB.isPlaying ? 'Pause' : 'Play'}
                >
                  {deckB.isPlaying ? <Pause size={20} /> : <Play size={20} />}
                </button>
              </div>
              
              <div className="volume-control">
                <label>VOLUME</label>
                <input
                  type="range"
                  min="0"
                  max="100"
                  value={deckB.volume}
                  onChange={(e) => updateDeckVolume('B', parseInt(e.target.value))}
                  className="volume-slider"
                  title={`Volume: ${deckB.volume}%`}
                />
                <span>{deckB.volume}%</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      <style jsx>{`
        /* Enhanced Styles with Polish */
        .dj-studio-mixer.polished {
          height: 100vh;
          background: linear-gradient(135deg, #1a1a1a 0%, #2d2d2d 100%);
          color: #ffffff;
          font-family: 'Inter', 'Arial', sans-serif;
          overflow: hidden;
          position: relative;
        }

        /* Loading States */
        .dj-studio-loading, .dj-studio-error {
          display: flex;
          align-items: center;
          justify-content: center;
          height: 100vh;
          background: linear-gradient(135deg, #1a1a1a 0%, #2d2d2d 100%);
          color: white;
        }

        .loading-content, .error-content {
          text-align: center;
          padding: 2rem;
        }

        .loading-spinner {
          animation: spin 2s linear infinite;
          color: #4ecdc4;
          margin-bottom: 1rem;
        }

        .error-icon {
          color: #ff6b6b;
          margin-bottom: 1rem;
        }

        .retry-btn {
          background: #4ecdc4;
          color: white;
          border: none;
          border-radius: 8px;
          padding: 0.75rem 1.5rem;
          cursor: pointer;
          font-weight: 500;
          margin-top: 1rem;
          transition: all 0.2s;
        }

        .retry-btn:hover {
          background: #45b7b8;
          transform: translateY(-2px);
        }

        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }

        /* Enhanced Header */
        .mixer-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          padding: 1rem 2rem;
          background: rgba(0, 0, 0, 0.3);
          border-bottom: 1px solid #444;
          backdrop-filter: blur(10px);
        }

        .logo-section {
          display: flex;
          align-items: center;
          gap: 1rem;
        }

        .status-indicator {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          font-size: 0.9rem;
          color: #4ecdc4;
        }

        .ready-icon {
          color: #22c55e;
        }

        .upload-progress {
          display: flex;
          align-items: center;
          background: rgba(78, 205, 196, 0.1);
          padding: 0.5rem 1rem;
          border-radius: 6px;
          font-size: 0.9rem;
          color: #4ecdc4;
        }

        /* Enhanced Library */
        .library-panel {
          width: 300px;
          background: rgba(0, 0, 0, 0.4);
          border-right: 1px solid #444;
          display: flex;
          flex-direction: column;
          backdrop-filter: blur(10px);
        }

        .empty-library {
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          padding: 3rem 1rem;
          text-align: center;
          color: #666;
        }

        .empty-icon {
          margin-bottom: 1rem;
          color: #444;
        }

        .upload-first-btn {
          background: #4ecdc4;
          color: white;
          border: none;
          border-radius: 8px;
          padding: 0.75rem 1.5rem;
          cursor: pointer;
          font-weight: 500;
          margin-top: 1rem;
          transition: all 0.2s;
        }

        .upload-first-btn:hover {
          background: #45b7b8;
          transform: translateY(-2px);
        }

        /* Enhanced Deck Styles */
        .deck {
          flex: 1;
          background: rgba(255, 255, 255, 0.05);
          border-radius: 12px;
          padding: 1.5rem;
          border: 2px solid transparent;
          transition: all 0.3s;
          backdrop-filter: blur(10px);
        }

        .deck.drag-target {
          border-color: #4ecdc4;
          background: rgba(78, 205, 196, 0.1);
          transform: scale(1.02);
        }

        .deck-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 1rem;
        }

        .loading-indicator {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          font-size: 0.9rem;
          color: #4ecdc4;
        }

        .loading-spin {
          animation: spin 1s linear infinite;
        }

        .track-loading, .track-error {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          padding: 1rem;
          border-radius: 8px;
          margin-bottom: 1rem;
        }

        .track-loading {
          background: rgba(78, 205, 196, 0.1);
          color: #4ecdc4;
        }

        .track-error {
          background: rgba(255, 107, 107, 0.1);
          color: #ff6b6b;
        }

        .waveform-placeholder {
          width: 100%;
          height: 100px;
          background: rgba(0, 0, 0, 0.3);
          border-radius: 8px;
          display: flex;
          align-items: center;
          justify-content: center;
          margin-bottom: 1rem;
          color: #666;
          font-size: 0.9rem;
        }

        /* Enhanced Controls */
        .play-pause-btn {
          background: linear-gradient(45deg, #ff6b6b, #4ecdc4) !important;
          width: 64px !important;
          height: 64px !important;
          border-radius: 50% !important;
          border: none;
          display: flex;
          align-items: center;
          justify-content: center;
          cursor: pointer;
          transition: all 0.3s;
          color: white;
          box-shadow: 0 4px 15px rgba(78, 205, 196, 0.3);
        }

        .play-pause-btn:hover:not(:disabled) {
          transform: scale(1.1);
          box-shadow: 0 6px 20px rgba(78, 205, 196, 0.4);
        }

        .play-pause-btn:disabled {
          opacity: 0.3;
          cursor: not-allowed;
          transform: none;
          box-shadow: none;
        }

        .volume-control {
          text-align: center;
          margin-top: 1.5rem;
        }

        .volume-control label {
          display: block;
          font-size: 0.8rem;
          font-weight: 600;
          margin-bottom: 0.5rem;
          color: #aaa;
        }

        .volume-slider {
          width: 100%;
          margin-bottom: 0.5rem;
          height: 6px;
          border-radius: 3px;
          background: rgba(255, 255, 255, 0.1);
          outline: none;
          -webkit-appearance: none;
        }

        .volume-slider::-webkit-slider-thumb {
          -webkit-appearance: none;
          width: 20px;
          height: 20px;
          border-radius: 50%;
          background: #4ecdc4;
          cursor: pointer;
          box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
          transition: all 0.2s;
        }

        .volume-slider::-webkit-slider-thumb:hover {
          transform: scale(1.2);
          box-shadow: 0 4px 12px rgba(78, 205, 196, 0.4);
        }

        /* Responsive Design */
        @media (max-width: 768px) {
          .mixer-layout {
            flex-direction: column;
          }
          
          .library-panel {
            width: 100%;
            height: 200px;
          }
          
          .mixer-main {
            flex-direction: column;
            padding: 1rem;
          }
          
          .crossfader-section {
            order: -1;
            margin-bottom: 1rem;
          }
          
          .deck {
            margin-bottom: 1rem;
          }
        }
      `}</style>
    </div>
  );
};

// Utility function for debouncing
function debounce(func, wait) {
  let timeout;
  return function executedFunction(...args) {
    const later = () => {
      clearTimeout(timeout);
      func(...args);
    };
    clearTimeout(timeout);
    timeout = setTimeout(later, wait);
  };
}

export default DJStudioMixerPolished;
