// src/pages/ArtistHomePage.jsx
//
// Streaming-first artist landing page.
//
// Layout:
//   HERO (top)      Featured live stream (LiveStreamViewer) | Mic search (AudioMatcherImproved)
//   LIVE NOW        Strip of active live events / streamers (EventsList)
//   CONVERSATIONS   Active chat rooms (ChatRooms)
//   FOOTER          CTAs: artist signup / browse people / create a room
//
// "Like Twitch but with a Shazam input."
//
// The mic flow is already wired to conversations: AudioMatcherImproved
// fingerprints audio, calls AudioMatchingService, and navigates to
// /room/${roomId} on match / create. No glue needed here.

import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import {
  Mic,
  MessageSquare,
  Radio,
  Users,
  Video,
  ArrowRight,
} from 'lucide-react';

import FeaturedStream from '../components/streaming/FeaturedStream';
import SmartMic from '../components/audio/SmartMic';
import EventsList from '../components/events/EventsList';
import ChatRooms from '../components/community/ChatRooms';
import { useAuth } from '../contexts/AuthContext';

const ArtistHomePage = ({ developerMode = false, isMobile = false }) => {
  const navigate = useNavigate();
  const { currentUser } = useAuth();

  const widgetError = (label) => {
    // eslint-disable-next-line no-console
    console.warn(`[ArtistHomePage] widget "${label}" failed to load`);
  };

  return (
    <div
      style={{
        minHeight: '100vh',
        background:
          'radial-gradient(circle at 15% 0%, rgba(99, 102, 241, 0.18), transparent 55%),' +
          'radial-gradient(circle at 85% 100%, rgba(236, 72, 153, 0.14), transparent 60%),' +
          '#0a0e17',
        color: '#f5f5f5',
      }}
    >
      {/* ===================== HERO ===================== */}
      <section
        style={{
          maxWidth: 1200,
          margin: '0 auto',
          padding: isMobile ? '1.25rem 0.75rem 1rem' : '2rem 1.5rem 1.5rem',
        }}
      >
        <SectionPill icon={<Radio size={14} />} label="LIVE NOW" />
        <h1
          style={{
            fontSize: isMobile ? '1.7rem' : '2.5rem',
            margin: '0.5rem 0 0.5rem',
            fontWeight: 700,
            letterSpacing: '-0.02em',
            lineHeight: 1.15,
          }}
        >
          Watch. Listen. Talk.
        </h1>
        <p
          style={{
            margin: '0 0 1.5rem',
            color: '#cbd5e1',
            fontSize: isMobile ? '0.95rem' : '1.05rem',
            maxWidth: 640,
          }}
        >
          Tune into a live performance, or tap the mic to find the conversation
          around the audio playing near you.
        </p>

        {/* Stream + mic, side-by-side on desktop, stacked on mobile. */}
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: isMobile ? '1fr' : 'minmax(0, 1.7fr) minmax(0, 1fr)',
            gap: '1rem',
            alignItems: 'stretch',
          }}
        >
          <Panel padding={0} style={{ overflow: 'hidden', minHeight: 280 }}>
            <FeaturedStream />
          </Panel>

          <Panel padding={0} style={{ overflow: 'hidden', minHeight: 280 }}>
            <div style={{ padding: '0.75rem 1rem 0', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <Mic size={16} color="#a5b4fc" />
              <span style={{ fontSize: '0.85rem', letterSpacing: '0.06em', textTransform: 'uppercase', color: '#a5b4fc' }}>
                Find the conversation
              </span>
            </div>
            <SmartMic />
          </Panel>
        </div>
      </section>

      {/* ===================== LIVE NOW STRIP ===================== */}
      <section
        style={{
          maxWidth: 1200,
          margin: '0 auto',
          padding: isMobile ? '1rem 0.75rem' : '1.5rem 1.5rem',
        }}
      >
        <SectionHeader
          icon={<Video size={20} color="#a5b4fc" />}
          title="People streaming now"
          subtitle="Jump into a live room."
          actionLabel="All events"
          actionTo="/events"
        />
        <Panel padding="0.5rem">
          <EventsList />
        </Panel>
      </section>

      {/* ===================== ACTIVE CONVERSATIONS ===================== */}
      <section
        style={{
          maxWidth: 1200,
          margin: '0 auto',
          padding: isMobile ? '1rem 0.75rem' : '1.5rem 1.5rem',
        }}
      >
        <SectionHeader
          icon={<MessageSquare size={20} color="#a5b4fc" />}
          title="Active conversations"
          subtitle="Or skip the scan and join a chat directly."
          actionLabel="Browse all rooms"
          actionTo="/chats"
        />
        <Panel>
          <ChatRooms onError={() => widgetError('chatRooms')} />
        </Panel>
      </section>

      {/* ===================== FOOTER CTAs ===================== */}
      <section
        style={{
          maxWidth: 1200,
          margin: '0 auto',
          padding: isMobile ? '1rem 0.75rem 3rem' : '2rem 1.5rem 4rem',
          display: 'grid',
          gap: '1rem',
          gridTemplateColumns: isMobile ? '1fr' : 'repeat(3, 1fr)',
        }}
      >
        <FooterCard
          icon={<Mic size={20} />}
          title="Are you an artist?"
          body="Claim your audio profile and let listeners find you the moment they hit play."
          ctaLabel="Artist signup"
          onClick={() => navigate('/artist-signup')}
        />
        <FooterCard
          icon={<Users size={20} />}
          title="Browse people"
          body="See who's listening and who's broadcasting right now."
          ctaLabel="See people"
          onClick={() => navigate('/people')}
        />
        <FooterCard
          icon={<MessageSquare size={20} />}
          title="Start a room"
          body="Have something playing? Create a room and let the matcher route listeners to you."
          ctaLabel={currentUser ? 'Create a room' : 'Sign in to create'}
          onClick={() => navigate(currentUser ? '/create-room' : '/login')}
        />
      </section>
    </div>
  );
};

/* ------------------------------- Sub-pieces ------------------------------- */

const Panel = ({ children, padding = '1rem', style = {} }) => (
  <div
    style={{
      background: 'rgba(17, 24, 39, 0.78)',
      border: '1px solid rgba(255,255,255,0.07)',
      borderRadius: 12,
      padding,
      ...style,
    }}
  >
    {children}
  </div>
);

const SectionPill = ({ icon, label }) => (
  <div
    style={{
      display: 'inline-flex',
      alignItems: 'center',
      gap: '0.5rem',
      padding: '0.3rem 0.8rem',
      borderRadius: 999,
      background: 'rgba(255,255,255,0.06)',
      border: '1px solid rgba(255,255,255,0.1)',
      fontSize: '0.75rem',
      letterSpacing: '0.08em',
      textTransform: 'uppercase',
      color: '#a5b4fc',
    }}
  >
    {icon}
    {label}
  </div>
);

const SectionHeader = ({ icon, title, subtitle, actionLabel, actionTo }) => (
  <div
    style={{
      display: 'flex',
      alignItems: 'baseline',
      justifyContent: 'space-between',
      marginBottom: '0.75rem',
      flexWrap: 'wrap',
      gap: '0.5rem',
    }}
  >
    <div>
      <h2
        style={{
          fontSize: '1.3rem',
          margin: 0,
          display: 'flex',
          alignItems: 'center',
          gap: '0.5rem',
        }}
      >
        {icon}
        {title}
      </h2>
      {subtitle && (
        <p style={{ margin: '0.2rem 0 0', color: '#94a3b8', fontSize: '0.9rem' }}>
          {subtitle}
        </p>
      )}
    </div>
    {actionLabel && actionTo && (
      <Link
        to={actionTo}
        style={{
          color: '#a5b4fc',
          textDecoration: 'none',
          display: 'inline-flex',
          alignItems: 'center',
          gap: '0.35rem',
          fontSize: '0.9rem',
        }}
      >
        {actionLabel} <ArrowRight size={16} />
      </Link>
    )}
  </div>
);

const FooterCard = ({ icon, title, body, ctaLabel, onClick }) => (
  <div
    style={{
      background: 'rgba(17, 24, 39, 0.85)',
      border: '1px solid rgba(255,255,255,0.08)',
      borderRadius: 12,
      padding: '1.25rem',
      display: 'flex',
      flexDirection: 'column',
      gap: '0.5rem',
    }}
  >
    <div
      style={{
        width: 36,
        height: 36,
        borderRadius: 8,
        background: 'rgba(99,102,241,0.18)',
        color: '#a5b4fc',
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center',
      }}
    >
      {icon}
    </div>
    <h3 style={{ margin: 0, fontSize: '1.05rem' }}>{title}</h3>
    <p style={{ margin: 0, color: '#cbd5e1', fontSize: '0.9rem', flex: 1 }}>{body}</p>
    <button
      onClick={onClick}
      style={{
        marginTop: '0.5rem',
        alignSelf: 'flex-start',
        background: 'transparent',
        border: '1px solid rgba(165,180,252,0.5)',
        color: '#a5b4fc',
        padding: '0.45rem 0.9rem',
        borderRadius: 8,
        cursor: 'pointer',
        fontSize: '0.85rem',
      }}
    >
      {ctaLabel}
    </button>
  </div>
);

export default ArtistHomePage;
