// src/services/BotMessageService.js
import { rtdb } from '../firebase';
import { ref, get, set, update, onValue, serverTimestamp } from 'firebase/database';

/**
 * Service for managing customizable bot messages
 */
class BotMessageServiceClass {
  constructor() {
    this.messageTemplates = {
      welcome: {
        default: "Welcome to {roomName}! I'm the moderation bot helping to keep this chat room safe and friendly for everyone."
      },
      warning: {
        default: "Please keep language appropriate in this room.",
        spam: "Multiple messages in quick succession detected. Please slow down to avoid flooding the chat."
      },
      moderation: {
        default: "A message has been removed for violating community guidelines.",
        language: "A message was removed due to inappropriate language."
      }
    };
    
    // Subscribe to message templates to keep local cache updated
    this.initializeMessageTemplates();
  }
  
  /**
   * Initialize the message templates by loading from Firebase
   */
  async initializeMessageTemplates() {
    try {
      const templatesRef = ref(rtdb, 'botConfig/messages');
      
      onValue(templatesRef, (snapshot) => {
        const templates = snapshot.val();
        if (templates) {
          this.messageTemplates = templates;
          console.log('Bot message templates updated:', this.messageTemplates);
        } else {
          // Initialize with default templates if none exist
          this.setupDefaultTemplates();
        }
      });
    } catch (error) {
      console.error('Error initializing message templates:', error);
    }
  }
  
  /**
   * Set up default templates in Firebase if they don't exist
   */
  async setupDefaultTemplates() {
    try {
      const templatesRef = ref(rtdb, 'botConfig/messages');
      await set(templatesRef, this.messageTemplates);
      console.log('Default bot message templates initialized in Firebase');
    } catch (error) {
      console.error('Error setting up default templates:', error);
    }
  }
  
  /**
   * Get a message template with variables replaced
   * @param {string} type - The type of message (welcome, warning, moderation)
   * @param {string} variant - The variant of the message (default, family, spam, etc.)
   * @param {object} variables - Variables to replace in the template
   * @returns {string} The processed message
   */
  getMessage(type, variant = 'default', variables = {}) {
    try {
      // Ensure the type exists
      if (!this.messageTemplates[type]) {
        console.warn(`Message type '${type}' not found, using welcome/default`);
        type = 'welcome';
        variant = 'default';
      }
      
      // Ensure the variant exists
      if (!this.messageTemplates[type][variant]) {
        console.warn(`Variant '${variant}' not found for type '${type}', using default variant`);
        variant = 'default';
      }
      
      // Get the template
      let message = this.messageTemplates[type][variant];
      
      // Replace variables in the template
      Object.keys(variables).forEach(key => {
        const regex = new RegExp(`\\{${key}\\}`, 'g');
        message = message.replace(regex, variables[key]);
      });
      
      return message;
    } catch (error) {
      console.error('Error getting message template:', error);
      return `Welcome to the chat room!`; // Fallback message
    }
  }
  
  /**
   * Get a welcome message for a room
   * @param {string} roomId - The ID of the room
   * @param {string} roomName - The name of the room
   * @param {string} variant - Optional variant to use
   * @returns {string} The welcome message
   */
  async getWelcomeMessage(roomId, roomName, variant = 'default') {
    try {
      // Check if the room has a custom template configured
      const roomConfigRef = ref(rtdb, `chats/public/${roomId}/botConfig`);
      const snapshot = await get(roomConfigRef);
      const roomConfig = snapshot.val() || {};
      
      // Use the room's configured variant if available
      const messageVariant = roomConfig.welcomeVariant || variant;
      
      return this.getMessage('welcome', messageVariant, { roomName });
    } catch (error) {
      console.error('Error getting welcome message:', error);
      return this.getMessage('welcome', 'default', { roomName });
    }
  }
  
  /**
   * Get a warning message for a room
   * @param {string} roomId - The ID of the room
   * @param {string} warningType - The type of warning (default, spam)
   * @returns {string} The warning message
   */
  async getWarningMessage(roomId, warningType = 'default') {
    try {
      // Check if the room has custom templates configured
      const roomConfigRef = ref(rtdb, `chats/public/${roomId}/botConfig`);
      const snapshot = await get(roomConfigRef);
      const roomConfig = snapshot.val() || {};
      
      // Room may specify specific warning variant to use
      const configKey = `${warningType}WarningVariant`;
      const messageVariant = roomConfig[configKey] || warningType;
      
      // Get room name for variable replacement
      const roomSnapshot = await get(ref(rtdb, `chats/public/${roomId}`));
      const roomData = roomSnapshot.val() || {};
      const roomName = roomData.name || 'this room';
      
      return this.getMessage('warning', messageVariant, { roomName });
    } catch (error) {
      console.error('Error getting warning message:', error);
      return this.getMessage('warning', warningType);
    }
  }
  
  /**
   * Get a moderation message for a room
   * @param {string} roomId - The ID of the room
   * @param {string} moderationType - The type of moderation (default, language)
   * @returns {string} The moderation message
   */
  async getModerationMessage(roomId, moderationType = 'default') {
    try {
      // Check if the room has custom templates configured
      const roomConfigRef = ref(rtdb, `chats/public/${roomId}/botConfig`);
      const snapshot = await get(roomConfigRef);
      const roomConfig = snapshot.val() || {};
      
      // Room may specify specific moderation variant to use
      const configKey = `${moderationType}ModerationVariant`;
      const messageVariant = roomConfig[configKey] || moderationType;
      
      // Get room name for variable replacement
      const roomSnapshot = await get(ref(rtdb, `chats/public/${roomId}`));
      const roomData = roomSnapshot.val() || {};
      const roomName = roomData.name || 'this room';
      
      return this.getMessage('moderation', messageVariant, { roomName });
    } catch (error) {
      console.error('Error getting moderation message:', error);
      return this.getMessage('moderation', moderationType);
    }
  }
  
  /**
   * Save a new message template to Firebase
   * @param {string} type - The type of message (welcome, warning, moderation)
   * @param {string} variant - The variant of the message
   * @param {string} content - The message content
   */
  async saveMessageTemplate(type, variant, content) {
    try {
      const templateRef = ref(rtdb, `botConfig/messages/${type}/${variant}`);
      await set(templateRef, content);
      console.log(`Message template ${type}/${variant} saved successfully`);
      return true;
    } catch (error) {
      console.error(`Error saving message template ${type}/${variant}:`, error);
      throw error;
    }
  }
  
  /**
   * Delete a message template from Firebase
   * @param {string} type - The type of message
   * @param {string} variant - The variant of the message
   */
  async deleteMessageTemplate(type, variant) {
    try {
      // Cannot delete default variant
      if (variant === 'default') {
        throw new Error('Cannot delete default message variant');
      }
      
      const templateRef = ref(rtdb, `botConfig/messages/${type}/${variant}`);
      await set(templateRef, null);
      console.log(`Message template ${type}/${variant} deleted successfully`);
      return true;
    } catch (error) {
      console.error(`Error deleting message template ${type}/${variant}:`, error);
      throw error;
    }
  }
  
  /**
   * Get all message templates
   * @returns {object} All message templates
   */
  getAllTemplates() {
    return this.messageTemplates;
  }
  
  /**
   * Configure which message templates a room should use
   * @param {string} roomId - The ID of the room
   * @param {object} config - Configuration object with variants to use
   */
  async configureRoomTemplates(roomId, config) {
    try {
      const roomConfigRef = ref(rtdb, `chats/public/${roomId}/botConfig`);
      await update(roomConfigRef, { 
        ...config,
        updatedAt: serverTimestamp()
      });
      console.log(`Room ${roomId} bot message configuration updated`);
      return true;
    } catch (error) {
      console.error(`Error configuring room templates for ${roomId}:`, error);
      throw error;
    }
  }
}

export const BotMessageService = new BotMessageServiceClass();