// src/predict/hooks/usePredictCredits.js
//
// Bridges Predict into the platform's existing one-time Credits model.
// Credits are the same balance users top up on /credits via Stripe
// (CreditsService.buyCreditPack) and that the Stripe webhook grants into
// `users/{uid}.credits.balance`. Predict simply *spends* against that shared
// balance — no separate currency, no new billing surface.
//
// Costs live here so the submit form and vote buttons agree on one source of
// truth. Tune freely; values are whole credits.

import { useEffect, useState, useCallback } from 'react';
import { useAuth } from '../contexts/AuthContext';
import {
  watchCreditBalance,
  spendCredits,
  InsufficientCreditsError,
} from '../../services/CreditsService';

export const PREDICT_CREDIT_COSTS = {
  // Creating a new prediction for the community to track.
  submit: 50,
  // Casting your first vote on a prediction (changing an existing vote is free).
  vote: 5,
};

export { InsufficientCreditsError };

/**
 * @returns {{
 *   uid: string|null,
 *   balance: number|null,            // null until first read resolves
 *   costs: typeof PREDICT_CREDIT_COSTS,
 *   canAfford: (action: keyof typeof PREDICT_CREDIT_COSTS) => boolean,
 *   spendForAction: (action: keyof typeof PREDICT_CREDIT_COSTS, meta?: object) => Promise<number>,
 * }}
 */
export function usePredictCredits() {
  const { currentUser } = useAuth();
  const uid = currentUser?.uid ?? currentUser?.id ?? null;
  const [balance, setBalance] = useState(null);

  useEffect(() => {
    if (!uid) {
      setBalance(null);
      return undefined;
    }
    const unsubscribe = watchCreditBalance(uid, setBalance);
    return unsubscribe;
  }, [uid]);

  const canAfford = useCallback(
    (action) => {
      const cost = PREDICT_CREDIT_COSTS[action] ?? 0;
      return balance != null && balance >= cost;
    },
    [balance],
  );

  const spendForAction = useCallback(
    async (action, meta = {}, idempotencyKey = null) => {
      if (!uid) throw new Error('Sign in to use credits.');
      if (PREDICT_CREDIT_COSTS[action] == null) {
        throw new Error(`Unknown predict credit action: ${action}`);
      }
      // The server resolves the actual cost from its own table; we only name
      // the action. Costs above are for display/affordability checks only.
      return spendCredits(`predict.${action}`, meta, idempotencyKey);
    },
    [uid],
  );

  return { uid, balance, costs: PREDICT_CREDIT_COSTS, canAfford, spendForAction };
}

export default usePredictCredits;
