// src/predict/services/firebaseVoting.js
//
// RTDB-backed votes. Mirrors votingService.js API.
//
// Schema:
//   predict_votes/{predictionId}/{userId}  → 'agree' | 'disagree'
//   predict_vote_counts/{predictionId}     → { agree: N, disagree: N }
//
// Counters live in a separate path so reads on the prediction list don't
// have to scan every user's vote. They are updated atomically alongside
// the per-user write.

import {
  ref,
  set,
  get,
  remove,
  update,
  onValue,
  serverTimestamp,
  runTransaction,
} from 'firebase/database';
import { rtdb } from '../../firebase';

const PATHS = {
  votes:  'predict_votes',
  counts: 'predict_vote_counts',
};

const listeners = new Set();
function notify(event) {
  for (const cb of listeners) {
    try { cb(event); } catch (e) { console.error('[predict-voting] listener error:', e); }
  }
}

// In-memory cache so repeated getVoteCounts() calls (e.g. inside list
// renders) don't all hit the network.
const countsCache = new Map();   // predictionId -> { agree, disagree }
const subscribedCounts = new Set(); // predictionIds we've attached onValue to

function ensureCountsSubscription(predictionId) {
  if (!rtdb || subscribedCounts.has(predictionId)) return;
  subscribedCounts.add(predictionId);
  onValue(
    ref(rtdb, `${PATHS.counts}/${predictionId}`),
    (snap) => {
      const v = snap.exists() ? snap.val() : { agree: 0, disagree: 0 };
      countsCache.set(predictionId, v);
      notify({ type: 'counts', predictionId, counts: v });
    }
  );
}

const firebaseVoting = {
  /** Get the current user's vote for a prediction (null if none). */
  async getVote(predictionId, userId) {
    if (!rtdb || !userId) return null;
    try {
      const snap = await get(ref(rtdb, `${PATHS.votes}/${predictionId}/${userId}`));
      return snap.exists() ? snap.val() : null;
    } catch {
      return null;
    }
  },

  /**
   * Cast (or toggle off) a vote.
   * Returns { vote, previousVote } where vote=null means the user un-voted.
   */
  async castVote(predictionId, userId, vote) {
    if (!rtdb) throw new Error('Firebase not initialized');
    if (!userId) throw new Error('Must be authenticated to vote');
    if (vote !== 'agree' && vote !== 'disagree') {
      throw new Error('Invalid vote value');
    }

    const voteRef = ref(rtdb, `${PATHS.votes}/${predictionId}/${userId}`);
    const priorSnap = await get(voteRef);
    const previousVote = priorSnap.exists() ? priorSnap.val() : null;

    // Counter delta map
    const delta = { agree: 0, disagree: 0 };
    if (previousVote === vote) {
      // Toggle off
      await remove(voteRef);
      delta[vote] = -1;
      await applyCounterDelta(predictionId, delta);
      notify({ type: 'vote', predictionId, userId, vote: null, previousVote });
      return { vote: null, previousVote };
    }

    if (previousVote) delta[previousVote] = -1;
    delta[vote] = 1;

    await set(voteRef, vote);
    await applyCounterDelta(predictionId, delta);
    notify({ type: 'vote', predictionId, userId, vote, previousVote });
    return { vote, previousVote };
  },

  /**
   * Synchronous read of cached counters. Triggers a subscription on first
   * call so subsequent reads stay live.
   */
  getVoteCounts(predictionId) {
    ensureCountsSubscription(predictionId);
    const cached = countsCache.get(predictionId);
    if (cached) return { ...cached, total: cached.agree + cached.disagree };
    return { agree: 0, disagree: 0, total: 0 };
  },

  /** Async one-shot fetch for counters (no caching). */
  async fetchVoteCounts(predictionId) {
    if (!rtdb) return { agree: 0, disagree: 0, total: 0 };
    try {
      const snap = await get(ref(rtdb, `${PATHS.counts}/${predictionId}`));
      const v = snap.exists() ? snap.val() : { agree: 0, disagree: 0 };
      countsCache.set(predictionId, v);
      return { ...v, total: v.agree + v.disagree };
    } catch {
      return { agree: 0, disagree: 0, total: 0 };
    }
  },

  /** Subscribe to vote / counter changes. */
  onVoteChange(callback) {
    listeners.add(callback);
    return () => listeners.delete(callback);
  },
};

/**
 * Apply +/-1 deltas to the counter document atomically. RTDB transactions
 * give us optimistic concurrency without needing Firestore.
 */
async function applyCounterDelta(predictionId, delta) {
  const counterRef = ref(rtdb, `${PATHS.counts}/${predictionId}`);
  await runTransaction(counterRef, (cur) => {
    const next = cur && typeof cur === 'object'
      ? { agree: cur.agree || 0, disagree: cur.disagree || 0 }
      : { agree: 0, disagree: 0 };
    next.agree    = Math.max(0, next.agree    + (delta.agree    || 0));
    next.disagree = Math.max(0, next.disagree + (delta.disagree || 0));
    next.updatedAt = Date.now();
    return next;
  });
}

export default firebaseVoting;
