// src/components/debug/DebuggerManager.jsx
import React, { useState, useEffect } from 'react';
import FirebasePerformanceDebugger from './FirebasePerformanceDebugger';
import FirebaseInitializationAnalyzer from './FirebaseInitializationAnalyzer';
import ChatPerformanceMonitor from './ChatPerformanceMonitor';
import { isPerformanceMonitoringEnabled } from '../../utils/firebase-performance';
import { isTracingEnabled } from '../../utils/firebase-trace-optimizer';
import { useDeveloperMode, isProduction } from '../../utils/devMode';

/**
 * DebuggerManager - Manages which debuggers to render based on environment and settings
 * Only renders in development environment
 */
const DebuggerManager = () => {
  // Master gate: production URL always wins (overlays off);
  // otherwise respect the Ctrl+Alt+D developer-mode flag.
  const devMode = useDeveloperMode();

  const [showPerformanceDebugger, setShowPerformanceDebugger] = useState(false);
  const [showInitAnalyzer, setShowInitAnalyzer] = useState(false);
  const [showChatMonitor, setShowChatMonitor] = useState(false);
  const [currentPath, setCurrentPath] = useState('');
  
  // Check if the current path is a chat room
  useEffect(() => {
    const updatePath = () => {
      setCurrentPath(window.location.pathname);
    };
    
    // Call once on mount
    updatePath();
    
    // Listen for path changes
    window.addEventListener('popstate', updatePath);
    return () => window.removeEventListener('popstate', updatePath);
  }, []);
  
  // Determine which debuggers to show based on path and environment
  useEffect(() => {
    // Only enable in development
    if (import.meta.env.DEV) {
      // Check if performance monitoring is enabled
      const isEnabled = isPerformanceMonitoringEnabled();
      setShowPerformanceDebugger(isEnabled);
      
      // Show initialization analyzer only when toggled (off by default)
      setShowInitAnalyzer(false);
      
      // Show chat performance monitor only on chat room paths
      const isChatPath = currentPath.includes('/room/') || 
                         currentPath.includes('/chat/') || 
                         currentPath.includes('/rooms');
      
      setShowChatMonitor(isChatPath);
      
      // Listen for keyboard shortcuts
      const handleKeyDown = (e) => {
        // Ctrl+Alt+F - Toggle Firebase Performance Monitoring
        if (e.ctrlKey && e.altKey && e.key === 'f') {
          // The actual toggle logic is in firebase-performance.js
          // We just need to update our state after a short delay
          setTimeout(() => {
            setShowPerformanceDebugger(isPerformanceMonitoringEnabled());
          }, 100);
        }
        
        // Ctrl+Alt+I - Toggle Initialization Analyzer
        if (e.ctrlKey && e.altKey && e.key === 'i') {
          setShowInitAnalyzer(prev => !prev);
        }
        
        // Ctrl+Alt+C - Toggle Chat Performance Monitor
        if (e.ctrlKey && e.altKey && e.key === 'c') {
          setShowChatMonitor(prev => !prev);
        }
      };
      
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
    }
  }, [currentPath]);

  // Don't render anything on the production domain, even if a dev build is
  // pointed at it. Also respect the developer-mode toggle (Ctrl+Alt+D).
  if (isProduction() || !devMode) {
    return null;
  }

  return (
    <>
      {showPerformanceDebugger && <FirebasePerformanceDebugger />}
      {showInitAnalyzer && <FirebaseInitializationAnalyzer />}
      {showChatMonitor && <ChatPerformanceMonitor />}
      
      {/* Help tooltip for debug shortcuts */}
      <div 
        style={{
          position: 'fixed',
          bottom: '10px',
          left: '10px',
          backgroundColor: 'rgba(0, 0, 0, 0.7)',
          color: 'white',
          padding: '8px 12px',
          borderRadius: '4px',
          fontSize: '12px',
          zIndex: 9999,
          maxWidth: '250px',
          boxShadow: '0 2px 5px rgba(0,0,0,0.2)'
        }}
      >
        <div style={{ marginBottom: '5px', fontWeight: 'bold' }}>Debug Shortcuts:</div>
        <div style={{ marginBottom: '3px' }}>Ctrl+Alt+F: Toggle Firebase Performance</div>
        <div style={{ marginBottom: '3px' }}>Ctrl+Alt+I: Toggle Init Analyzer</div>
        <div style={{ marginBottom: '3px' }}>Ctrl+Alt+C: Toggle Chat Monitor</div>
        <div style={{ marginBottom: '3px' }}>Ctrl+Alt+D: Toggle Developer Mode</div>
      </div>
    </>
  );
};

export default DebuggerManager;