// src/services/StripeService.js
import { getAuth } from 'firebase/auth';
import { getFunctions, httpsCallable } from 'firebase/functions';
import { getFirestore, collection, addDoc, serverTimestamp, doc, getDoc } from 'firebase/firestore';
import { getStripeInstance } from './StripeInitializer';

/**
 * Create a payment intent for direct payment
 * @param {number} amount - Amount in dollars
 * @param {string} currency - Currency code (e.g., 'usd')
 * @param {Object} metadata - Additional metadata
 * @returns {Promise<{ clientSecret: string }>} Client secret for Stripe Elements
 */
export const createPaymentIntent = async (amount, currency = 'usd', metadata = {}, forceTest = false) => {
  try {
    // Check environment variables to determine test mode
    const paymentMode = import.meta.env.VITE_PAYMENT_MODE || 'test';
    const appEnv = import.meta.env.VITE_APP_ENV || 'development';
    
    // Determine if we should use test mode
    const isTestMode = forceTest || 
                     metadata.isTest === true || 
                     paymentMode === 'test' || 
                     appEnv === 'development' || 
                     appEnv === 'test';
                     
    console.log(`Creating payment intent in ${isTestMode ? 'TEST' : 'LIVE'} mode`);
    console.log(`Environment: ${appEnv}, Payment Mode: ${paymentMode}`);
    const amountInCents = Math.round(amount * 100);
    const auth = getAuth();
    const userId = auth.currentUser?.uid;
    
    if (!userId) {
      throw new Error('User must be logged in to create a payment intent');
    }
    
    // Call Firebase function to create payment intent
    const functions = getFunctions();
    const createPaymentIntentFn = httpsCallable(functions, 'createPaymentIntent');
    
    const result = await createPaymentIntentFn({
      amount: amountInCents,
      currency: currency,
      metadata: {
        userId: userId,
        ...metadata
      },
      isTest: isTestMode // Add test mode flag
    });
    
    return result.data;
  } catch (error) {
    console.error('Error creating payment intent:', error);
    throw new Error('Failed to initialize payment: ' + error.message);
  }
};

/**
 * Process a subscription
 * @param {Object} paymentData - Payment data including amount and payment method
 * @param {string} userId - User ID
 * @param {string} productId - Product ID (streamId or 'premium_membership')
 * @param {string} accessLevel - Access level (e.g., 'premium')
 * @param {number} accessDuration - Access duration in days (0 for permanent)
 * @returns {Promise<Object>} Result object with success flag
 */
export const processSubscription = async (paymentData, userId, productId, accessLevel, accessDuration) => {
  try {
    if (!userId) {
      throw new Error('User ID is required');
    }
    
    // Call Firebase function to process subscription
    const functions = getFunctions();
    const processSubscriptionFn = httpsCallable(functions, 'processSubscription');
    
    const result = await processSubscriptionFn({
      paymentMethodId: paymentData.paymentMethodId,
      amount: paymentData.amount,
      currency: 'usd',
      userId: userId,
      productId: productId,
      accessLevel: accessLevel,
      accessDuration: accessDuration
    });
    
    return result.data;
  } catch (error) {
    console.error('Error processing subscription:', error);
    throw new Error('Failed to process subscription: ' + error.message);
  }
};

/**
 * Create Stripe Checkout session
 * @param {number} amount - Amount in dollars
 * @param {string} currency - Currency code (e.g., 'usd')
 * @param {Object} metadata - Additional metadata
 * @param {boolean} forceTest - Force test mode (for dev/testing environments)
 * @returns {Promise<{ url: string }>} Checkout session URL
 */
export const createCheckoutSession = async (amount, currency = 'usd', metadata = {}, forceTest = false) => {
  try {
    console.log('Starting createCheckoutSession with params:', { amount, currency, metadata });
    
    // Check environment variables to determine test mode
    const paymentMode = import.meta.env.VITE_PAYMENT_MODE || 'test';
    const appEnv = import.meta.env.VITE_APP_ENV || 'development';
    
    // Determine if we should use test mode
    const isTestMode = forceTest || 
                      metadata.isTest === true || 
                      paymentMode === 'test' || 
                      appEnv === 'development' || 
                      appEnv === 'test';
                      
    console.log(`Creating checkout session in ${isTestMode ? 'TEST' : 'LIVE'} mode`);
    console.log(`Environment: ${appEnv}, Payment Mode: ${paymentMode}`);
    
    const amountInCents = Math.round(amount * 100);
    const auth = getAuth();
    const userId = auth.currentUser?.uid;
    
    if (!userId) {
      console.error('User not logged in during createCheckoutSession');
      throw new Error('User must be logged in to create a checkout session');
    }
    
    // Call Firebase function to create checkout session
    const functions = getFunctions();
    const createCheckoutSessionFn = httpsCallable(functions, 'createCheckoutSession');
    
    console.log('Calling createCheckoutSession Firebase function with params:', {
      amount: amountInCents,
      currency: currency,
      userId: userId,
      email: auth.currentUser?.email,
      displayName: auth.currentUser?.displayName || 'User',
      metadata: {
        userId: userId,
        ...metadata
      },
      productName: metadata.productName || 'Premium Content',
      description: metadata.description || 'Access to premium content',
      isTest: isTestMode
    });
    
    try {
      // Add timeout for better error handling
      const timeoutPromise = new Promise((_, reject) => {
        setTimeout(() => reject(new Error('Timeout: The request to create a checkout session took too long. Please try again.')), 15000);
      });
      
      // Race between actual request and timeout
      const result = await Promise.race([
        createCheckoutSessionFn({
          amount: amountInCents,
          currency: currency,
          userId: userId,
          email: auth.currentUser?.email,
          displayName: auth.currentUser?.displayName || 'User',
          metadata: {
            userId: userId,
            ...metadata
          },
          productName: metadata.productName || 'Premium Content',
          description: metadata.description || 'Access to premium content',
          // Adding support for test mode flag based on environment variables
          isTest: isTestMode
        }),
        timeoutPromise
      ]);
      
      console.log('Checkout session creation result:', result.data);
      
      if (!result.data || (!result.data.url && !result.data.sessionId)) {
        console.error('Invalid response from createCheckoutSession:', result);
        throw new Error('Invalid response from payment server. Please try again.');
      }
      
      return {
        success: true,
        url: result.data.url,
        sessionId: result.data.sessionId
      };
    } catch (fnError) {
      console.error('Error in Firebase function call:', fnError);
      
      // Special handling for specific error types
      if (fnError.message.includes('timeout') || fnError.message.includes('Timeout')) {
        throw new Error('The payment system is not responding. Please try again later.');
      }
      
      if (fnError.code === 'functions/internal') {
        console.error('Internal Firebase Function error:', fnError);
        throw new Error('There was an internal error in the payment system. This is likely a configuration issue. Please contact support.');
      }
      
      if (fnError.code === 'functions/unavailable') {
        throw new Error('The payment system is currently unavailable. Please try again later.');
      }
      
      if (fnError.code) {
        throw new Error(`Payment system error (${fnError.code}): ${fnError.message}`);
      }
      
      throw fnError;
    }
  } catch (error) {
    console.error('Error creating checkout session:', error);
    return {
      success: false,
      error: error.message,
      errorCode: error.code,
      errorDetails: error.details
    };
  }
};

/**
 * Process a tip for an artist
 * @param {Object} tipData - Tip data including amount and payment method
 * @param {string} userId - User ID of the tipper
 * @param {string} artistId - Artist ID
 * @param {string} streamId - Stream ID
 * @param {string} message - Optional message with the tip
 * @returns {Promise<Object>} Result object with success flag
 */
export const processTip = async (tipData, userId, artistId, streamId, message = '') => {
  try {
    if (!userId || !artistId) {
      throw new Error('User ID and Artist ID are required');
    }
    
    // Call Firebase function to process tip
    const functions = getFunctions();
    const processTipFn = httpsCallable(functions, 'processTip');
    
    const result = await processTipFn({
      paymentMethodId: tipData.paymentMethodId,
      amount: tipData.amount,
      currency: 'usd',
      userId: userId,
      artistId: artistId,
      streamId: streamId || null,
      message: message
    });
    
    return result.data;
  } catch (error) {
    console.error('Error processing tip:', error);
    throw new Error('Failed to process tip: ' + error.message);
  }
};

/**
 * Check if a user has premium access
 * @param {string} userId - User ID
 * @returns {Promise<boolean>} Whether the user has premium access
 */
export const checkPremiumAccess = async (userId) => {
  try {
    if (!userId) {
      return false;
    }
    
    const db = getFirestore();
    const userRef = doc(db, 'users', userId);
    const userDoc = await getDoc(userRef);
    
    if (userDoc.exists()) {
      return userDoc.data().isPremium === true;
    }
    
    return false;
  } catch (error) {
    console.error('Error checking premium access:', error);
    return false;
  }
};

/**
 * Check if a user has access to a specific stream
 * @param {string} userId - User ID
 * @param {string} streamId - Stream ID
 * @returns {Promise<Object>} Access details
 */
export const checkStreamAccess = async (userId, streamId) => {
  try {
    if (!userId || !streamId) {
      return { hasAccess: false };
    }
    
    const db = getFirestore();
    const accessRef = doc(db, 'users', userId, 'streamAccess', streamId);
    const accessDoc = await getDoc(accessRef);
    
    if (accessDoc.exists()) {
      const accessData = accessDoc.data();
      const now = new Date();
      const expiresAt = accessData.expiresAt?.toDate() || now;
      
      return {
        hasAccess: accessData.level === 'premium' && expiresAt > now,
        level: accessData.level,
        expiresAt: expiresAt
      };
    }
    
    return { hasAccess: false };
  } catch (error) {
    console.error('Error checking stream access:', error);
    return { hasAccess: false, error: error.message };
  }
};