// src/hooks/useSubscription.js
import { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useAdminAuth } from '../contexts/AdminAuthContext';
import { subscriptionService } from '../services/SubscriptionService';
import { periodicValidator } from '../services/PeriodicSubscriptionValidator';

/**
 * Custom hook for managing subscription status with periodic validation
 */
export const useSubscription = () => {
  const { currentUser } = useAuth();
  // Admin elevation: Firestore users/{uid}.isAdmin === true grants the
  // highest tier (elite) regardless of subscription state. Pulled from
  // the existing AdminAuthContext so we don't duplicate the Firestore read.
  const { isAdmin } = useAdminAuth() || { isAdmin: false };
  const [subscription, setSubscription] = useState({
    isActive: false,
    isPremium: false,
    isExpired: false,
    plan: null,
    startDate: null,
    endDate: null,
    stripeCustomerId: null,
    stripeSubscriptionId: null,
    transactions: [],
    lastUpdated: null,
    error: null,
    cached: false,
    lastValidation: null
  });
  const [loading, setLoading] = useState(true);

  // Load subscription status using periodic validator
  const loadSubscriptionStatus = useCallback(async (forceRefresh = false) => {
    if (!currentUser) {
      setSubscription({
        isActive: false,
        isPremium: false,
        isExpired: false,
        plan: null,
        startDate: null,
        endDate: null,
        stripeCustomerId: null,
        stripeSubscriptionId: null,
        transactions: [],
        lastUpdated: null,
        error: null,
        cached: false,
        lastValidation: null
      });
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      
      // Use periodic validator instead of direct service call
      const status = await periodicValidator.getSubscriptionStatus(
        currentUser.uid, 
        currentUser.email, 
        forceRefresh
      );
      
      // Add cache info
      const cacheInfo = periodicValidator.getCacheInfo(currentUser.uid);
      const enhancedStatus = {
        ...status,
        cached: !!status.cachedAt,
        lastValidation: cacheInfo.lastValidation,
        nextValidation: cacheInfo.nextValidation
      };
      
      setSubscription(enhancedStatus);
    } catch (error) {
      console.error('Error loading subscription status:', error);
      setSubscription(prev => ({
        ...prev,
        error: error.message
      }));
    } finally {
      setLoading(false);
    }
  }, [currentUser]);

  // Set up periodic validation and real-time listener
  useEffect(() => {
    if (!currentUser) {
      setLoading(false);
      return;
    }

    // Start periodic validation
    periodicValidator.startPeriodicValidation(currentUser.uid, currentUser.email);

    // Load initial status (will use cache if valid)
    loadSubscriptionStatus();

    // Also set up real-time listener for immediate updates
    // This catches manual changes via dev controls, payments, etc.
    const unsubscribe = subscriptionService.subscribeToStatusChanges((status) => {
      // When Firebase changes, clear cache so next call gets fresh data
      periodicValidator.clearCache(currentUser.uid);
      
      // Update subscription state
      const cacheInfo = periodicValidator.getCacheInfo(currentUser.uid);
      setSubscription({
        ...status,
        cached: false, // This came from real-time update
        lastValidation: cacheInfo.lastValidation,
        nextValidation: cacheInfo.nextValidation
      });
      setLoading(false);
    });

    // Cleanup function
    return () => {
      if (typeof unsubscribe === 'function') {
        unsubscribe();
      }
      // Don't stop periodic validation here - let it continue for the session
    };
  }, [currentUser, loadSubscriptionStatus]);

  // Cleanup periodic validation when component unmounts
  useEffect(() => {
    return () => {
      periodicValidator.cleanup();
    };
  }, []);

  // Update subscription after successful payment
  const updateSubscription = useCallback(async (subscriptionData) => {
    try {
      setLoading(true);
      const result = await subscriptionService.updateSubscriptionStatus(subscriptionData);
      
      if (result.success) {
        // Clear cache so next load gets fresh data
        if (currentUser) {
          periodicValidator.clearCache(currentUser.uid);
        }
        // The real-time listener will automatically update the state
        return { success: true };
      } else {
        throw new Error(result.error);
      }
    } catch (error) {
      console.error('Error updating subscription:', error);
      setSubscription(prev => ({
        ...prev,
        error: error.message
      }));
      return { success: false, error: error.message };
    } finally {
      setLoading(false);
    }
  }, [currentUser]);

  // Cancel subscription
  const cancelSubscription = useCallback(async () => {
    try {
      setLoading(true);
      const result = await subscriptionService.cancelSubscription();
      
      if (result.success) {
        // Clear cache so next load gets fresh data
        if (currentUser) {
          periodicValidator.clearCache(currentUser.uid);
        }
        // The real-time listener will automatically update the state
        return { success: true };
      } else {
        throw new Error(result.error);
      }
    } catch (error) {
      console.error('Error cancelling subscription:', error);
      setSubscription(prev => ({
        ...prev,
        error: error.message
      }));
      return { success: false, error: error.message };
    } finally {
      setLoading(false);
    }
  }, [currentUser]);

  // Check if user has premium access
  const hasPremiumAccess = useCallback(() => {
    return subscription.isActive === true;
  }, [subscription.isActive]);

  // Force refresh subscription status (for dev controls)
  const forceRefreshSubscription = useCallback(async () => {
    console.log('🔧 Force refreshing subscription status...');
    await loadSubscriptionStatus(true);
  }, [loadSubscriptionStatus]);

  // Regular refresh (respects cache)
  const refreshSubscription = useCallback(async () => {
    console.log('🔄 Refreshing subscription status...');
    await loadSubscriptionStatus(false);
  }, [loadSubscriptionStatus]);

  // Helper to format expiry date
  const getFormattedExpiryDate = useCallback(() => {
    if (!subscription.endDate) return null;

    let date = subscription.endDate;
    if (date && typeof date === 'object' && date.toDate) {
      date = date.toDate();
    } else if (typeof date === 'string') {
      date = new Date(date);
    } else if (typeof date === 'number') {
      date = new Date(date);
    }

    const options = { year: 'numeric', month: 'long', day: 'numeric' };
    return date.toLocaleDateString(undefined, options);
  }, [subscription.endDate]);

  // Helper to get days remaining
  const getDaysRemaining = useCallback(() => {
    if (!subscription.endDate) return null;

    let endDate = subscription.endDate;
    if (endDate && typeof endDate === 'object' && endDate.toDate) {
      endDate = endDate.toDate();
    } else if (typeof endDate === 'string') {
      endDate = new Date(endDate);
    } else if (typeof endDate === 'number') {
      endDate = new Date(endDate);
    }

    const now = new Date();
    const diffTime = endDate - now;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    
    return diffDays > 0 ? diffDays : 0;
  }, [subscription.endDate]);

  // Get cache information for debugging
  const getCacheInfo = useCallback(() => {
    if (!currentUser) return null;
    return periodicValidator.getCacheInfo(currentUser.uid);
  }, [currentUser]);

  // --- Tier system (dealmaker platform) ---
  // Derive tier from (in priority order):
  //   1. Admin flag in Firestore — admins always get elite (full access for
  //      ops, support, internal demos)
  //   2. VITE_OVERRIDE_TIER env var — for local dev without Stripe
  //   3. subscription.plan — derived from Stripe webhook
  // Tiers: 'free' | 'data' ($20) | 'crm' ($99) | 'elite' ($999)
  const TIER_RANK = { free: 0, data: 1, crm: 2, elite: 3 };

  const devOverride = import.meta?.env?.VITE_OVERRIDE_TIER;

  let tier = 'free';
  if (isAdmin) {
    // Admins get the top tier no matter what — they need to see/test all
    // features and support paying users. This also means an admin can never
    // be paywalled out of their own product.
    tier = 'elite';
  } else if (devOverride && TIER_RANK[devOverride] !== undefined) {
    tier = devOverride;
  } else if (subscription.isActive) {
    const plan = (subscription.plan || '').toLowerCase();
    if (plan.includes('elite')) tier = 'elite';
    else if (plan.includes('crm')) tier = 'crm';
    else if (plan.includes('data')) tier = 'data';
    else tier = 'data'; // legacy premium = data tier (backward compat)
  }

  const features = {
    data: TIER_RANK[tier] >= TIER_RANK.data,
    crm: TIER_RANK[tier] >= TIER_RANK.crm,
    ai: TIER_RANK[tier] >= TIER_RANK.elite,
  };

  const meetsTier = useCallback((minTier) => {
    return TIER_RANK[tier] >= (TIER_RANK[minTier] ?? 0);
  }, [tier]);

  return {
    // Subscription data
    subscription,
    loading,

    // Status helpers
    isActive: subscription.isActive,
    isPremium: subscription.isPremium,
    isExpired: subscription.isExpired,
    plan: subscription.plan,
    error: subscription.error,

    // Tier system
    tier,
    features,
    meetsTier,
    isAdmin,             // surfaced for admin-only UI (e.g. tier badges)
    
    // Cache info
    cached: subscription.cached,
    lastValidation: subscription.lastValidation,
    nextValidation: subscription.nextValidation,
    
    // Actions
    updateSubscription,
    cancelSubscription,
    refreshSubscription,          // Respects 4-hour cache
    forceRefreshSubscription,     // Bypasses cache (for dev)
    hasPremiumAccess,
    
    // Debug helpers
    getCacheInfo,
    
    // Formatted data
    formattedExpiryDate: getFormattedExpiryDate(),
    daysRemaining: getDaysRemaining(),
    
    // Raw data for advanced use
    rawSubscription: subscription
  };
};
