// src/services/scheduledRoomsService.js
//
// Scheduled public rooms: a host defines a show once — name, start, duration,
// repeat rule, genre, visibility, replay — and it keeps the same public URL
// (/r/late-shift) week to week. Listeners browse what's live now, what's on
// tonight, and replays of what they missed.
//
// Three collections:
//   scheduledRooms — the show definition, one per permanent link
//   occurrences    — expanded instances of the recurrence, one per airing;
//                    this is what Discover queries and what RSVPs point at
//   rsvps          — (userId, occurrenceId), id'd `${uid}_${occurrenceId}`
//                    so a toggle is a single write with no lookup
//
// The handoff expands recurrences server-side. Until those Cloud Functions
// exist the expansion runs here, at publish time and again whenever a room is
// read with fewer than MIN_FUTURE_OCCURRENCES ahead of it, which keeps the
// schedule populated without a backend deploy.

import {
  getFirestore,
  collection,
  doc,
  addDoc,
  setDoc,
  getDoc,
  getDocs,
  updateDoc,
  deleteDoc,
  query,
  where,
  orderBy,
  limit as fsLimit,
  onSnapshot,
  serverTimestamp,
  increment,
  Timestamp,
} from 'firebase/firestore';
import { app } from '../firebase';

const db = () => getFirestore(app);

const ROOMS = 'scheduledRooms';
const OCCURRENCES = 'occurrences';
const RSVPS = 'rsvps';

/** How many future airings to keep expanded per room. */
const FUTURE_OCCURRENCES = 8;
const MIN_FUTURE_OCCURRENCES = 3;
const HORIZON_DAYS = 120;

export const REPEAT_RULES = [
  { id: 'weekly', label: 'Weekly', cadence: 'weekly' },
  { id: 'biweekly', label: 'Every 2 weeks', cadence: 'every 2 weeks' },
  { id: 'monthly', label: 'Monthly', cadence: 'monthly' },
  { id: 'once', label: 'One-off', cadence: 'one-off' },
];

export const GENRES = ['house', 'breaks', 'techno', 'soul', 'dub', 'ambient', 'talk'];

export const MIN_DURATION_MIN = 15;
export const MAX_DURATION_MIN = 360;

/* ------------------------------------------------------------------ *
 * Slugs — the permanent link, derived from the name and fixed once
 * published so anything already posted keeps working.
 * ------------------------------------------------------------------ */

export function slugify(title) {
  return (title || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 48);
}

export async function isSlugAvailable(slug, { ignoreRoomId = null } = {}) {
  if (!slug) return false;
  const snap = await getDocs(query(collection(db(), ROOMS), where('slug', '==', slug), fsLimit(1)));
  if (snap.empty) return true;
  return ignoreRoomId ? snap.docs[0].id === ignoreRoomId : false;
}

/** First free variant of the slug: late-shift, late-shift-2, late-shift-3… */
export async function uniqueSlug(base, { ignoreRoomId = null } = {}) {
  const root = slugify(base) || 'room';
  for (let n = 1; n <= 25; n += 1) {
    const candidate = n === 1 ? root : `${root}-${n}`;
    // eslint-disable-next-line no-await-in-loop
    if (await isSlugAvailable(candidate, { ignoreRoomId })) return candidate;
  }
  return `${root}-${Date.now().toString(36)}`;
}

/* ------------------------------------------------------------------ *
 * Recurrence
 * ------------------------------------------------------------------ */

const addDays = (date, days) => {
  const next = new Date(date.getTime());
  next.setDate(next.getDate() + days);
  return next;
};

const addMonths = (date, months) => {
  const next = new Date(date.getTime());
  next.setMonth(next.getMonth() + months);
  return next;
};

/** The airing after `date` under `repeat`, or null for a one-off. */
export function nextStart(date, repeat) {
  switch (repeat) {
    case 'weekly': return addDays(date, 7);
    case 'biweekly': return addDays(date, 14);
    case 'monthly': return addMonths(date, 1);
    default: return null;
  }
}

/**
 * Future start times for a show, beginning at `from`. A recurring show that
 * started in the past is rolled forward to its next airing first, so a room
 * published months ago still lists correctly.
 */
export function expandStarts(firstStart, repeat, { count = FUTURE_OCCURRENCES, from = new Date() } = {}) {
  const starts = [];
  let cursor = firstStart instanceof Date ? new Date(firstStart.getTime()) : new Date(firstStart);
  if (Number.isNaN(cursor.getTime())) return starts;

  const horizon = addDays(from, HORIZON_DAYS);

  if (repeat === 'once') {
    return cursor > from ? [cursor] : [];
  }

  // Roll a past start forward rather than emitting airings that already aired.
  let guard = 0;
  while (cursor <= from && guard < 500) {
    const next = nextStart(cursor, repeat);
    if (!next) return [];
    cursor = next;
    guard += 1;
  }

  while (starts.length < count && cursor <= horizon) {
    starts.push(new Date(cursor.getTime()));
    const next = nextStart(cursor, repeat);
    if (!next) break;
    cursor = next;
  }
  return starts;
}

/* ------------------------------------------------------------------ *
 * Rooms
 * ------------------------------------------------------------------ */

const roomSummary = (room, id) => ({
  roomId: id || room.id,
  slug: room.slug,
  title: room.title,
  hostId: room.hostId,
  hostName: room.hostName,
  hostPhotoURL: room.hostPhotoURL || null,
  artworkUrl: room.artworkUrl || null,
  genres: room.genres || [],
  durationMin: room.durationMin,
  repeat: room.repeat,
  timezone: room.timezone || null,
  visibility: room.visibility || 'public',
  publishReplay: room.publishReplay !== false,
});

/**
 * Create or update a show. `status: 'draft'` keeps it off Discover; publishing
 * expands the recurrence into occurrence documents.
 */
export async function saveScheduledRoom({ id = null, user, data, status = 'published' }) {
  if (!user || !user.uid) throw new Error('Must be signed in to schedule a room');
  if (!data.title || !data.title.trim()) throw new Error('Give the show a name');

  const startAt = data.startAt instanceof Date ? data.startAt : new Date(data.startAt);
  if (Number.isNaN(startAt.getTime())) throw new Error('Pick a start time');

  // A draft is a work in progress and never reaches Discover, so only the
  // name has to hold up; publishing is what enforces the rest.
  if (status === 'published') {
    if (data.repeat === 'once' && startAt <= new Date()) {
      throw new Error('A one-off show has to start in the future');
    }
    if (data.durationMin < MIN_DURATION_MIN || data.durationMin > MAX_DURATION_MIN) {
      throw new Error('Shows run between 15 minutes and 6 hours');
    }
    if (!data.genres || !data.genres.length) throw new Error('Pick at least one genre');
    if (data.visibility === 'invite' && !(data.accessCode || '').trim()) {
      throw new Error('Invite-only rooms need an access code');
    }
  }

  const slug = data.slug ? slugify(data.slug) : await uniqueSlug(data.title);
  if (!(await isSlugAvailable(slug, { ignoreRoomId: id }))) {
    throw new Error(`The link /r/${slug} is taken — try another name`);
  }

  const payload = {
    slug,
    title: data.title.trim(),
    hostId: user.uid,
    hostName: user.displayName || user.email || 'host',
    hostPhotoURL: user.photoURL || null,
    artworkUrl: data.artworkUrl || null,
    startAt: Timestamp.fromDate(startAt),
    durationMin: data.durationMin,
    timezone: data.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone,
    repeat: data.repeat,
    genres: data.genres || [],
    visibility: data.visibility,
    accessCode: data.visibility === 'invite' ? (data.accessCode || '').trim() : null,
    publishReplay: data.publishReplay !== false,
    emailReplay: Boolean(data.emailReplay),
    status,
    updatedAt: serverTimestamp(),
  };

  let roomId = id;
  if (roomId) {
    await updateDoc(doc(db(), ROOMS, roomId), payload);
  } else {
    const ref = await addDoc(collection(db(), ROOMS), { ...payload, createdAt: serverTimestamp() });
    roomId = ref.id;
  }

  if (status === 'published') {
    await syncOccurrences({ id: roomId, ...payload, startAt });
  }

  return { id: roomId, slug };
}

export async function getRoomBySlug(slug) {
  const snap = await getDocs(query(collection(db(), ROOMS), where('slug', '==', slug), fsLimit(1)));
  if (snap.empty) return null;
  return { id: snap.docs[0].id, ...snap.docs[0].data() };
}

export async function getRoom(id) {
  const snap = await getDoc(doc(db(), ROOMS, id));
  return snap.exists() ? { id: snap.id, ...snap.data() } : null;
}

export async function listRoomsByHost(uid) {
  const snap = await getDocs(query(collection(db(), ROOMS), where('hostId', '==', uid)));
  return snap.docs
    .map(d => ({ id: d.id, ...d.data() }))
    .sort((a, b) => (a.startAt?.seconds || 0) - (b.startAt?.seconds || 0));
}

export async function deleteScheduledRoom(roomId) {
  const snap = await getDocs(query(collection(db(), OCCURRENCES), where('roomId', '==', roomId)));
  await Promise.all(
    snap.docs
      .filter(d => d.data().state === 'scheduled')
      .map(d => deleteDoc(doc(db(), OCCURRENCES, d.id))),
  );
  await deleteDoc(doc(db(), ROOMS, roomId));
}

/* ------------------------------------------------------------------ *
 * Occurrences
 * ------------------------------------------------------------------ */

const toDate = (value) => {
  if (!value) return null;
  if (typeof value.toDate === 'function') return value.toDate();
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
};

/**
 * Bring a room's future occurrences in line with its definition: airings that
 * already happened are left alone (they carry replays and RSVP counts), future
 * ones are refreshed, and missing ones are created.
 */
export async function syncOccurrences(room) {
  const roomId = room.id;
  const startAt = toDate(room.startAt);
  if (!roomId || !startAt) return [];

  const existingSnap = await getDocs(
    query(collection(db(), OCCURRENCES), where('roomId', '==', roomId)),
  );
  const existing = existingSnap.docs.map(d => ({ id: d.id, ...d.data() }));
  const now = new Date();
  const summary = roomSummary(room, roomId);

  const wanted = expandStarts(startAt, room.repeat, { count: FUTURE_OCCURRENCES, from: now });
  const written = [];

  for (const start of wanted) {
    const end = new Date(start.getTime() + room.durationMin * 60000);
    const match = existing.find(
      o => Math.abs((toDate(o.startAt)?.getTime() || 0) - start.getTime()) < 60000,
    );

    if (match) {
      // Only future, not-yet-aired occurrences follow edits to the show.
      if (match.state === 'scheduled') {
        // eslint-disable-next-line no-await-in-loop
        await updateDoc(doc(db(), OCCURRENCES, match.id), {
          ...summary,
          startAt: Timestamp.fromDate(start),
          endAt: Timestamp.fromDate(end),
          updatedAt: serverTimestamp(),
        });
      }
      written.push({ ...match, ...summary, startAt: Timestamp.fromDate(start) });
      continue;
    }

    // eslint-disable-next-line no-await-in-loop
    const ref = await addDoc(collection(db(), OCCURRENCES), {
      ...summary,
      startAt: Timestamp.fromDate(start),
      endAt: Timestamp.fromDate(end),
      state: 'scheduled',
      rsvpCount: 0,
      listenerCount: 0,
      replayId: null,
      createdAt: serverTimestamp(),
      updatedAt: serverTimestamp(),
    });
    written.push({ id: ref.id, ...summary, startAt: Timestamp.fromDate(start) });
  }

  // Stale scheduled airings (the show moved, or stopped repeating) go away.
  const keep = new Set(wanted.map(d => d.getTime()));
  await Promise.all(
    existing
      .filter(o => o.state === 'scheduled')
      .filter(o => {
        const at = toDate(o.startAt)?.getTime();
        return at && at > now.getTime() && !Array.from(keep).some(k => Math.abs(k - at) < 60000);
      })
      .map(o => deleteDoc(doc(db(), OCCURRENCES, o.id))),
  );

  return written;
}

/** Top up a published room that has run low on expanded airings. */
export async function ensureUpcomingOccurrences(room) {
  if (!room || room.status !== 'published') return;
  const snap = await getDocs(
    query(collection(db(), OCCURRENCES), where('roomId', '==', room.id), where('state', '==', 'scheduled')),
  );
  const future = snap.docs.filter(d => (toDate(d.data().startAt) || 0) > new Date());
  if (future.length < MIN_FUTURE_OCCURRENCES) await syncOccurrences(room);
}

export async function getOccurrence(id) {
  const snap = await getDoc(doc(db(), OCCURRENCES, id));
  return snap.exists() ? { id: snap.id, ...snap.data() } : null;
}

/** Live right now — equality-only, so no composite index is needed. */
export async function listLiveOccurrences({ max = 12 } = {}) {
  const snap = await getDocs(
    query(
      collection(db(), OCCURRENCES),
      where('state', '==', 'live'),
      where('visibility', '==', 'public'),
      fsLimit(max),
    ),
  );
  return snap.docs
    .map(d => ({ id: d.id, ...d.data() }))
    .sort((a, b) => (b.listenerCount || 0) - (a.listenerCount || 0));
}

/** Live rooms as they change — Discover keeps this open. */
export function subscribeToLiveOccurrences(callback) {
  return onSnapshot(
    query(
      collection(db(), OCCURRENCES),
      where('state', '==', 'live'),
      where('visibility', '==', 'public'),
      fsLimit(12),
    ),
    (snap) => {
      callback(
        snap.docs
          .map(d => ({ id: d.id, ...d.data() }))
          .sort((a, b) => (b.listenerCount || 0) - (a.listenerCount || 0)),
      );
    },
    (err) => {
      console.warn('[scheduledRooms] live subscription failed:', err.message);
      callback([]);
    },
  );
}

/**
 * Live ad-hoc events, for Discover's "live now" band.
 *
 * Not every broadcast is a scheduled room: the DJ Studio creates an event and
 * goes live into it, and the event studios do the same. Those are real live
 * rooms and belong on Discover, so this reads the events collection alongside
 * the occurrences one. An event already bound to a live airing is filtered out
 * by the caller — it is the same broadcast seen twice.
 *
 * Events are marked live but not always marked ended (a closed tab leaves one
 * behind), so anything older than STALE_LIVE_HOURS is treated as finished
 * rather than shown as live forever.
 */
const STALE_LIVE_HOURS = 12;

export function subscribeToLiveEvents(callback) {
  const cutoff = () => Date.now() - STALE_LIVE_HOURS * 3600000;

  const startedAtMs = (event) => {
    const started = event.streamStartedAt || event.startTime || event.createdAt;
    const date = toDate(started);
    if (date) return date.getTime();
    return typeof started === 'number' ? started : 0;
  };

  return onSnapshot(
    query(collection(db(), 'events'), where('status', '==', 'live'), fsLimit(30)),
    (snap) => {
      const rows = snap.docs
        .map(d => ({ id: d.id, ...d.data() }))
        .filter(e => e.isLive !== false)
        .filter(e => startedAtMs(e) >= cutoff())
        .sort((a, b) => startedAtMs(b) - startedAtMs(a));
      callback(rows);
    },
    (err) => {
      console.warn('[scheduledRooms] live events subscription failed:', err.message);
      callback([]);
    },
  );
}

/** Present a live event in the same shape Discover renders airings in. */
export const liveEventAsCard = (event) => ({
  id: event.id,
  eventId: event.id,
  isEvent: true,
  title: event.title || 'Live set',
  hostId: event.artistId || null,
  hostName: event.artistName || 'Artist',
  artworkUrl: event.artworkUrl || event.coverImageUrl || null,
  genres: event.genre ? [event.genre] : [],
  listenerCount: event.viewerCount || event.listenerCount || 0,
  startAt: event.streamStartedAt || event.startTime || event.createdAt || null,
  wentLiveAt: event.streamStartedAt || null,
  publishReplay: false,
  state: 'live',
});

/** Window bounds for the Discover time filter, in the viewer's own zone. */
export function windowRange(windowId, now = new Date()) {
  const startOfDay = (d) => new Date(d.getFullYear(), d.getMonth(), d.getDate());
  const today = startOfDay(now);
  switch (windowId) {
    case 'tomorrow':
      return { from: addDays(today, 1), to: addDays(today, 2) };
    case 'week':
      return { from: now, to: addDays(today, 7) };
    case 'tonight':
    default:
      // Tonight runs to 06:00 tomorrow so a 00:00 show still counts as tonight.
      return { from: now, to: new Date(addDays(today, 1).getTime() + 6 * 3600000) };
  }
}

/**
 * Upcoming airings in a window. The ordered range query wants a composite
 * index; without it we read the scheduled set and filter in memory rather than
 * showing the listener an error.
 */
export async function listUpcomingOccurrences({ window: windowId = 'tonight', genre = null, max = 40 } = {}) {
  const { from, to } = windowRange(windowId);
  const base = collection(db(), OCCURRENCES);
  const inWindow = (o) => {
    const start = toDate(o.startAt);
    return start && start >= from && start < to;
  };
  const matchesGenre = (o) => !genre || (o.genres || []).includes(genre);

  let rows;
  try {
    const snap = await getDocs(
      query(
        base,
        where('state', '==', 'scheduled'),
        where('visibility', '==', 'public'),
        where('startAt', '>=', Timestamp.fromDate(from)),
        where('startAt', '<', Timestamp.fromDate(to)),
        orderBy('startAt', 'asc'),
        fsLimit(max),
      ),
    );
    rows = snap.docs.map(d => ({ id: d.id, ...d.data() }));
  } catch (err) {
    console.warn('[scheduledRooms] ordered upcoming query unavailable:', err.message);
    const snap = await getDocs(
      query(base, where('state', '==', 'scheduled'), where('visibility', '==', 'public'), fsLimit(200)),
    );
    rows = snap.docs
      .map(d => ({ id: d.id, ...d.data() }))
      .filter(inWindow)
      .sort((a, b) => (toDate(a.startAt) || 0) - (toDate(b.startAt) || 0))
      .slice(0, max);
  }

  return rows.filter(matchesGenre);
}

/** Everything already recorded — replays stay up 30 days. */
export async function listReplays({ hostId = null, max = 12 } = {}) {
  const filters = [where('state', '==', 'replay')];
  if (hostId) filters.push(where('hostId', '==', hostId));
  const snap = await getDocs(query(collection(db(), OCCURRENCES), ...filters, fsLimit(max)));
  return snap.docs
    .map(d => ({ id: d.id, ...d.data() }))
    .sort((a, b) => (toDate(b.startAt) || 0) - (toDate(a.startAt) || 0));
}

export async function listOccurrencesForRoom(roomId, { max = 30 } = {}) {
  const snap = await getDocs(
    query(collection(db(), OCCURRENCES), where('roomId', '==', roomId), fsLimit(max)),
  );
  return snap.docs
    .map(d => ({ id: d.id, ...d.data() }))
    .sort((a, b) => (toDate(a.startAt) || 0) - (toDate(b.startAt) || 0));
}

/** The airing a room's page should show: live one first, else the next up. */
export function pickCurrentOccurrence(occurrences) {
  if (!occurrences || !occurrences.length) return null;
  const live = occurrences.find(o => o.state === 'live');
  if (live) return live;
  const now = new Date();
  const next = occurrences.find(o => o.state === 'scheduled' && (toDate(o.startAt) || 0) >= now);
  if (next) return next;
  const past = occurrences.filter(o => o.state === 'replay' || o.state === 'ended');
  return past.length ? past[past.length - 1] : occurrences[occurrences.length - 1];
}

/** The host's next airing — the Studio binds to this to go live in one click. */
export async function getNextOccurrenceForHost(uid, { withinHours = null } = {}) {
  if (!uid) return null;
  const snap = await getDocs(
    query(collection(db(), OCCURRENCES), where('hostId', '==', uid), fsLimit(50)),
  );
  const now = new Date();
  const rows = snap.docs
    .map(d => ({ id: d.id, ...d.data() }))
    .filter(o => o.state === 'live' || (o.state === 'scheduled' && (toDate(o.endAt) || toDate(o.startAt)) >= now))
    .sort((a, b) => (toDate(a.startAt) || 0) - (toDate(b.startAt) || 0));

  const next = rows[0] || null;
  if (!next || withinHours == null) return next;
  if (next.state === 'live') return next;
  const start = toDate(next.startAt);
  return start && start.getTime() - now.getTime() <= withinHours * 3600000 ? next : null;
}

/* ------------------------------------------------------------------ *
 * Airing lifecycle — the Studio drives these
 * ------------------------------------------------------------------ */

/**
 * Point a scheduled airing at the room a host has actually gone live in.
 *
 * The DJ Studio (and the event studios) broadcast into an event's LiveKit
 * room rather than one derived from the occurrence, so the airing records
 * which room to listen to — `liveRoomKey` — and /r/:slug subscribes to that
 * instead of its own derived key. Without this the room page sits on its
 * pre-show countdown while the host is on air somewhere else.
 *
 * Binds the host's next airing within `withinHours`. Never throws: a
 * scheduling nicety must not be able to break going live.
 */
export async function bindOccurrenceToLiveRoom({ user, roomKey, eventId = null, withinHours = 2 }) {
  if (!user || !user.uid || !roomKey) return null;
  try {
    const occurrence = await getNextOccurrenceForHost(user.uid, { withinHours });
    if (!occurrence) return null;

    await updateDoc(doc(db(), OCCURRENCES, occurrence.id), {
      state: 'live',
      liveRoomKey: roomKey,
      liveEventId: eventId,
      wentLiveAt: serverTimestamp(),
      updatedAt: serverTimestamp(),
    });
    return { ...occurrence, state: 'live', liveRoomKey: roomKey, liveEventId: eventId };
  } catch (err) {
    console.warn('[scheduledRooms] could not attach the live room:', err.message);
    return null;
  }
}

/** Live view of one airing — the room page flips from pre-show to live on it. */
export function subscribeToOccurrence(occurrenceId, callback) {
  if (!occurrenceId) return () => {};
  return onSnapshot(
    doc(db(), OCCURRENCES, occurrenceId),
    (snap) => { if (snap.exists()) callback({ id: snap.id, ...snap.data() }); },
    (err) => console.warn('[scheduledRooms] occurrence subscription failed:', err.message),
  );
}

export async function markOccurrenceLive(occurrenceId) {
  await updateDoc(doc(db(), OCCURRENCES, occurrenceId), {
    state: 'live',
    wentLiveAt: serverTimestamp(),
    updatedAt: serverTimestamp(),
  });
}

/**
 * End an airing. With replays on it goes to 'replay' so it shows in the replay
 * grid; otherwise 'ended'. Also tops the room's schedule back up.
 *
 * `replayUrl` is the recording the egress uploaded to the replay bucket — the
 * room page plays it, and without it the airing shows as "processing" until the
 * server's egress webhook fills it in.
 */
export async function markOccurrenceEnded(
  occurrence,
  { publishReplay = true, replayId = null, replayUrl = null, durationMs = 0 } = {},
) {
  const id = typeof occurrence === 'string' ? occurrence : occurrence.id;
  const patch = {
    state: publishReplay ? 'replay' : 'ended',
    endedAt: serverTimestamp(),
    replayId,
    updatedAt: serverTimestamp(),
  };
  if (publishReplay && replayUrl) patch.replayUrl = replayUrl;
  if (publishReplay && durationMs > 0) patch.durationMin = Math.max(1, Math.round(durationMs / 60000));

  await updateDoc(doc(db(), OCCURRENCES, id), patch);

  const roomId = typeof occurrence === 'object' ? occurrence.roomId : null;
  if (roomId) {
    try {
      const room = await getRoom(roomId);
      if (room) await ensureUpcomingOccurrences(room);
    } catch (err) {
      console.warn('[scheduledRooms] could not top up the schedule:', err.message);
    }
  }
}

export async function setListenerCount(occurrenceId, count) {
  try {
    await updateDoc(doc(db(), OCCURRENCES, occurrenceId), { listenerCount: count });
  } catch (err) {
    console.warn('[scheduledRooms] listener count write failed:', err.message);
  }
}

/* ------------------------------------------------------------------ *
 * RSVPs
 * ------------------------------------------------------------------ */

const rsvpId = (uid, occurrenceId) => `${uid}_${occurrenceId}`;

export async function hasRsvp(uid, occurrenceId) {
  if (!uid || !occurrenceId) return false;
  const snap = await getDoc(doc(db(), RSVPS, rsvpId(uid, occurrenceId)));
  return snap.exists();
}

export async function listRsvpsForUser(uid, { max = 100 } = {}) {
  if (!uid) return [];
  const snap = await getDocs(query(collection(db(), RSVPS), where('userId', '==', uid), fsLimit(max)));
  return snap.docs.map(d => ({ id: d.id, ...d.data() }));
}

/**
 * Toggle "Notify me" / "Going ✓". Returns the new going state. The count on
 * the occurrence moves with it so the schedule row updates without a re-read.
 */
export async function toggleRsvp({ user, occurrence, notify = true }) {
  if (!user || !user.uid) throw new Error('Sign in to RSVP');
  const id = rsvpId(user.uid, occurrence.id);
  const ref = doc(db(), RSVPS, id);
  const existing = await getDoc(ref);

  if (existing.exists()) {
    await deleteDoc(ref);
    await updateDoc(doc(db(), OCCURRENCES, occurrence.id), { rsvpCount: increment(-1) }).catch(() => {});
    return false;
  }

  await setDoc(ref, {
    userId: user.uid,
    userName: user.displayName || user.email || 'listener',
    occurrenceId: occurrence.id,
    roomId: occurrence.roomId,
    slug: occurrence.slug,
    title: occurrence.title,
    startAt: occurrence.startAt,
    notify,
    createdAt: serverTimestamp(),
  });
  await updateDoc(doc(db(), OCCURRENCES, occurrence.id), { rsvpCount: increment(1) }).catch(() => {});
  return true;
}

/* ------------------------------------------------------------------ *
 * Calendar
 * ------------------------------------------------------------------ */

const icsStamp = (date) => date.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');

const RRULE = {
  weekly: 'FREQ=WEEKLY',
  biweekly: 'FREQ=WEEKLY;INTERVAL=2',
  monthly: 'FREQ=MONTHLY',
};

/**
 * An .ics for one airing — or, when the show repeats, the whole recurrence.
 */
export function buildIcs(occurrence, { recurring = true } = {}) {
  const start = toDate(occurrence.startAt);
  const end = toDate(occurrence.endAt) ||
    new Date(start.getTime() + (occurrence.durationMin || 60) * 60000);
  const url = `${window.location.origin}/r/${occurrence.slug}`;
  const rule = recurring ? RRULE[occurrence.repeat] : null;

  return [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//TalkStudio//Scheduled Rooms//EN',
    'BEGIN:VEVENT',
    `UID:${occurrence.id}@talkstudio`,
    `DTSTAMP:${icsStamp(new Date())}`,
    `DTSTART:${icsStamp(start)}`,
    `DTEND:${icsStamp(end)}`,
    rule ? `RRULE:${rule}` : null,
    `SUMMARY:${occurrence.title}`,
    `DESCRIPTION:${occurrence.hostName || ''} on TalkStudio — ${url}`,
    `URL:${url}`,
    'END:VEVENT',
    'END:VCALENDAR',
  ].filter(Boolean).join('\r\n');
}

export function downloadIcs(occurrence) {
  const blob = new Blob([buildIcs(occurrence)], { type: 'text/calendar;charset=utf-8' });
  const href = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = href;
  link.download = `${occurrence.slug || 'show'}.ics`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(href);
}

/* ------------------------------------------------------------------ *
 * Formatting shared by the schedule, room and profile screens
 * ------------------------------------------------------------------ */

export const occurrenceDate = toDate;

export const formatClock = (value) => {
  const date = toDate(value);
  return date ? date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }) : '';
};

export const formatDayTime = (value) => {
  const date = toDate(value);
  return date
    ? date.toLocaleString([], { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', hour12: false })
    : '';
};

export const formatDuration = (minutes) => {
  if (!minutes) return '';
  if (minutes < 60) return `${minutes} min`;
  const hours = minutes / 60;
  return Number.isInteger(hours) ? `${hours} hr${hours > 1 ? 's' : ''}` : `${Math.floor(hours)}h ${minutes % 60}m`;
};

export const cadenceLabel = (repeat) =>
  (REPEAT_RULES.find(r => r.id === repeat) || {}).cadence || 'one-off';

/** "in 3 days" / "in 2 hrs" / "in 12 min" — the preview card's countdown. */
export const formatLeadTime = (value) => {
  const date = toDate(value);
  if (!date) return '';
  const diffMs = date.getTime() - Date.now();
  if (diffMs <= 0) return 'now';
  const minutes = Math.round(diffMs / 60000);
  if (minutes < 60) return `in ${minutes} min`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `in ${hours} hr${hours > 1 ? 's' : ''}`;
  const days = Math.round(hours / 24);
  return `in ${days} day${days > 1 ? 's' : ''}`;
};

/** Elapsed time inside a live airing: "41 min in". */
export const formatElapsed = (value) => {
  const date = toDate(value);
  if (!date) return '';
  const minutes = Math.max(0, Math.round((Date.now() - date.getTime()) / 60000));
  if (minutes < 60) return `${minutes} min in`;
  return `${Math.floor(minutes / 60)}h ${minutes % 60}m in`;
};

/**
 * The LiveKit room / chat key for an airing. Deriving it from the occurrence
 * id keeps the Studio's publish side and the listener's subscribe side on the
 * same room without either needing to create anything.
 */
export const occurrenceRoomKey = (occurrence) =>
  `sr-${typeof occurrence === 'string' ? occurrence : occurrence.id}`;

/**
 * Where to actually listen: the room the host bound when they went live, or
 * the airing's own derived key when the Set Studio published straight into it.
 */
export const listenRoomKey = (occurrence) =>
  (occurrence && occurrence.liveRoomKey) || occurrenceRoomKey(occurrence);

