// Phase-1 stand-in for `contextService.getSignalsForTags(tags)`.
// Returns ContextSignal[] whose `tag` matches any of the requested tags.
export function getMockSignalsForTags(tags = []) {
  if (!Array.isArray(tags) || tags.length === 0) return []
  const set = new Set(tags)
  return MOCK_CONTEXT_SIGNALS.filter(s => set.has(s.tag))
}
