// src/contexts/AuthContext.js
import React, { createContext, useState, useEffect, useContext } from 'react';
import {
  getAuth,
  onAuthStateChanged,
  signOut,
  signInAnonymously,
  signInWithEmailAndPassword,
  createUserWithEmailAndPassword,
  sendPasswordResetEmail,
  signInWithPopup,
  GoogleAuthProvider
} from 'firebase/auth';
import { getFirestore, doc, getDoc, setDoc, serverTimestamp } from 'firebase/firestore';

// Create the authentication context
const AuthContext = createContext();

// Custom hook to use the auth context
export function useAuth() {
  return useContext(AuthContext);
}

// Creator access is granted automatically to every signed-in (non-anonymous)
// user — there is no approval step and no separate signup gate. This is the
// single source of truth for "can this user create / stream". It deliberately
// does NOT depend on the `artistProfiles`/`users.isArtist` Firestore write,
// which may be absent or fail; access must never hinge on that write.
export function useIsCreator() {
  const { isCreator } = useContext(AuthContext);
  return isCreator;
}

// Provider component
export function AuthProvider({ children }) {
  const [currentUser, setCurrentUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [userRole, setUserRole] = useState(null);
  const [isVenueUser, setIsVenueUser] = useState(false);
  const [venueId, setVenueId] = useState(null);
  
  // Initialize Firebase auth
  const auth = getAuth();
  const db = getFirestore();

  // Effect for auth state changes
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      setCurrentUser(user);
      
      if (user) {
        // Fetch user role and venue information
        try {
          const db = getFirestore();
          const userDoc = await getDoc(doc(db, 'users', user.uid));
          
          if (userDoc.exists()) {
            const userData = userDoc.data();
            setUserRole(userData.role || 'user');
            setIsVenueUser(userData.isVenueUser === true);
            setVenueId(userData.venueId || null);
          }
        } catch (error) {
          console.error('Error fetching user role:', error);
        }
      } else {
        setUserRole(null);
        setIsVenueUser(false);
        setVenueId(null);
      }
      
      setLoading(false);
    });
    
    // Cleanup subscription
    return unsubscribe;
  }, [auth]);
  
  // Logout function
  const logout = async () => {
    try {
      await signOut(auth);
      // Clear any local storage if needed
      localStorage.removeItem('developerMode');
      console.log('User logged out successfully');
    } catch (error) {
      console.error('Error during logout:', error);
      throw error;
    }
  };
  
  // Anonymous login function
  const loginAnonymously = async () => {
    try {
      console.log('Attempting anonymous sign-in...');
      const result = await signInAnonymously(auth);
      console.log('Anonymous sign-in successful:', result.user.uid);
      return result;
    } catch (error) {
      console.error('Error during anonymous sign-in:', error);
      throw error;
    }
  };
  
  // Session time management for anonymous users
  const getRemainingSessionTime = () => {
    // For anonymous users, implement session time tracking
    if (currentUser?.isAnonymous) {
      const sessionStart = localStorage.getItem('anonymousSessionStart');
      if (!sessionStart) {
        const now = Date.now();
        localStorage.setItem('anonymousSessionStart', now.toString());
        return {
          remainingTime: 5 * 60 * 1000, // 5 minutes in milliseconds
          expired: false,
          canJoinEvents: false,
          canJoinRooms: true,
          userType: 'anonymous'
        };
      }
      
      const startTime = parseInt(sessionStart);
      const elapsed = Date.now() - startTime;
      const fiveMinutes = 5 * 60 * 1000;
      const remaining = Math.max(0, fiveMinutes - elapsed);
      
      return {
        remainingTime: remaining,
        expired: remaining <= 0,
        canJoinEvents: false,
        canJoinRooms: remaining > 0,
        userType: 'anonymous'
      };
    }
    
    // For authenticated users, return unlimited session
    return {
      remainingTime: Infinity,
      expired: false,
      canJoinEvents: true,
      canJoinRooms: true,
      userType: 'authenticated'
    };
  };
  
  // Email/password login
  const login = async (email, password) => {
    try {
      return await signInWithEmailAndPassword(auth, email, password);
    } catch (error) {
      console.error('Error during email/password login:', error);
      throw error;
    }
  };

  // Email/password signup (called by ConvertAccount as
  // signup(email, password, displayName, username))
  const signup = async (email, password, displayName, username) => {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      const user = userCredential.user;

      // Create/merge the user document in Firestore
      await setDoc(
        doc(db, 'users', user.uid),
        {
          email,
          username: username || '',
          displayName: displayName || username || '',
          createdAt: serverTimestamp(),
          isAdmin: false,
          isAnonymous: false,
          canJoinEvents: true,
          canJoinRooms: true
        },
        { merge: true }
      );

      return user;
    } catch (error) {
      console.error('Error during signup:', error);
      throw error;
    }
  };

  // Password reset
  const resetPassword = async (email) => {
    try {
      return await sendPasswordResetEmail(auth, email);
    } catch (error) {
      console.error('Error sending password reset email:', error);
      throw error;
    }
  };

  // Google sign-in. Returns the shape the Login/ConvertAccount components
  // expect: { usernameRequired, result }.
  const googleLogin = async () => {
    try {
      const provider = new GoogleAuthProvider();
      provider.addScope('profile');
      provider.addScope('email');
      provider.setCustomParameters({ prompt: 'select_account' });

      const result = await signInWithPopup(auth, provider);
      const user = result.user;

      // Ensure a Firestore user document exists for first-time Google users
      const userRef = doc(db, 'users', user.uid);
      const userDoc = await getDoc(userRef);
      if (!userDoc.exists()) {
        await setDoc(
          userRef,
          {
            email: user.email,
            displayName: user.displayName || user.email,
            photoURL: user.photoURL || null,
            createdAt: serverTimestamp(),
            isAdmin: false,
            isAnonymous: false,
            canJoinEvents: true,
            canJoinRooms: true
          },
          { merge: true }
        );
      }

      return { usernameRequired: false, result };
    } catch (error) {
      console.error('Error during Google sign-in:', error);
      throw error;
    }
  };

  // Every authenticated, non-anonymous user is a creator by default. Creator
  // access is intentionally equal to a regular signed-in user — no artist
  // profile, approval, or Firestore write required.
  const isCreator = !!currentUser && !currentUser.isAnonymous;

  // Context value
  const value = {
    currentUser,
    loading,
    isCreator,
    login,
    signup,
    resetPassword,
    googleLogin,
    logout,
    loginAnonymously,
    getRemainingSessionTime,
    userRole,
    isVenueUser,
    venueId
  };
  
  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
}

export { AuthContext };
export default AuthContext;