// src/components/monetization/StreamMonetization.jsx
import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { getStripeInstance } from '../../services/StripeInitializer';
import { createCheckoutSession } from '../../services/StripeService';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../../firebase';
import { AlertTriangle, CreditCard, Check } from 'lucide-react';
import './StreamMonetization.css';

const StreamMonetization = ({ streamId, streamTitle, amount = 9.99, accessLevel = 'premium', accessDuration = 30, onSuccess, onError }) => {
  const { currentUser } = useAuth();
  const [stripePromise, setStripePromise] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    const initStripe = async () => {
      try {
        setLoading(true);
        const stripe = await getStripeInstance();
        setStripePromise(stripe);
        setError(null);
      } catch (err) {
        console.error('Error initializing Stripe:', err);
        setError('Could not initialize payment system. Please try again later.');
      } finally {
        setLoading(false);
      }
    };

    initStripe();
  }, []);

  const handleCheckout = async () => {
    if (!currentUser) {
      setError('You must be logged in to purchase access.');
      return;
    }

    setIsProcessing(true);
    setError(null);

    try {
      // Create checkout session using the Stripe extension
      const result = await createCheckoutSession(
        amount,
        'usd',
        {
          productName: `Access to ${streamTitle || 'Premium Content'}`,
          description: `${accessDuration === 0 ? 'Permanent' : accessDuration + ' day'} access to premium content`,
          streamId,
          accessLevel,
          accessDuration
        }
      );

      if (result.success && result.url) {
        // Redirect to Stripe's hosted checkout page
        window.location.href = result.url;
      } else {
        throw new Error('Failed to create checkout session');
      }
    } catch (err) {
      console.error('Checkout error:', err);
      setError(err.message || 'An error occurred during checkout');
      setIsProcessing(false);
      if (onError) onError(err);
    }
  };

  if (loading) {
    return (
      <div className="stream-monetization loading">
        <div className="loading-spinner">
          Loading payment system...
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="stream-monetization error">
        <div className="error-message">
          <AlertTriangle size={18} />
          <span>{error}</span>
        </div>
        <button className="retry-button" onClick={() => window.location.reload()}>
          Retry
        </button>
      </div>
    );
  }

  return (
    <div className="stream-monetization">
      <h3>Access this premium content</h3>
      <p className="content-description">
        {streamTitle ? (
          <>Purchase access to "{streamTitle}"</>
        ) : (
          <>Purchase access to this premium content</>
        )}
      </p>

      <div className="payment-details">
        <div className="payment-amount">${amount.toFixed(2)}</div>
        <div className="payment-info">
          {accessDuration === 0 ? (
            <span>One-time purchase (permanent access)</span>
          ) : (
            <span>
              {accessDuration === 30 ? '1 month' : 
               accessDuration === 90 ? '3 months' :
               accessDuration === 180 ? '6 months' :
               accessDuration === 365 ? '12 months' :
               `${accessDuration} days`} of access
            </span>
          )}
        </div>
      </div>

      <div className="checkout-container">
        <div className="checkout-info">
          <p>Click the button below to proceed to our secure checkout page. You'll be able to enter your payment details on the next screen.</p>
          <p>After completing your purchase, you'll be redirected back to our site automatically.</p>
        </div>
        
        <button 
          className="primary-button checkout-button" 
          onClick={handleCheckout}
          disabled={isProcessing}
        >
          {isProcessing ? 'Processing...' : (
            <>
              <CreditCard size={16} style={{ marginRight: '8px' }} />
              <span>Proceed to Checkout</span>
            </>
          )}
        </button>
      </div>

      <div className="secure-payment-notice">
        <div className="lock-icon">🔒</div>
        <p>Your payment information is secure and encrypted. We use industry-standard security measures to protect your data.</p>
      </div>
    </div>
  );
};

export default StreamMonetization;