import { useState, useEffect } from 'react'

export function useCountdown(deadline) {
  const [timeLeft, setTimeLeft] = useState(() => calc(deadline))

  useEffect(() => {
    const id = setInterval(() => setTimeLeft(calc(deadline)), 60000)
    return () => clearInterval(id)
  }, [deadline])

  return timeLeft
}

function calc(deadline) {
  const diff = new Date(deadline) - new Date()
  if (diff <= 0) return { days: 0, hours: 0, minutes: 0, isExpired: true, label: 'Expired' }

  const days = Math.floor(diff / 86400000)
  const hours = Math.floor((diff % 86400000) / 3600000)
  const minutes = Math.floor((diff % 3600000) / 60000)

  let label
  if (days > 30) label = `${Math.floor(days / 30)}mo`
  else if (days > 0) label = `${days}d ${hours}h`
  else label = `${hours}h ${minutes}m`

  return { days, hours, minutes, isExpired: false, label }
}
