import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../../../contexts/AuthContext';
import { 
  getFirestore, 
  collection, 
  query, 
  where, 
  orderBy, 
  onSnapshot, 
  addDoc, 
  updateDoc, 
  doc, 
  serverTimestamp 
} from 'firebase/firestore';
import { 
  getDatabase, 
  ref, 
  onValue, 
  push, 
  set, 
  off 
} from 'firebase/database';
import { 
  Radio, 
  Users, 
  DollarSign, 
  Crown, 
  Calendar,
  Settings,
  Play,
  Square,
  Plus,
  Clock,
  Star,
  Music,
  Mic,
  Video,
  ChevronDown,
  MessageCircle,
  Send,
  Eye
} from 'lucide-react';
import './StreamToEventBridge.css';

const StreamToEventBridge = ({ 
  isStreaming, 
  streamConfig, 
  onEventStreamStart, 
  onEventStreamStop,
  streamTitle,
  streamDescription,
  streamCategory
}) => {
  const { currentUser } = useAuth();
  
  // UI State
  const [showEventSettings, setShowEventSettings] = useState(false);
  const [eventMode, setEventMode] = useState('select'); // 'select' or 'create'
  
  // Event Selection
  const [availableEvents, setAvailableEvents] = useState([]);
  const [selectedEventId, setSelectedEventId] = useState('');
  const [selectedEvent, setSelectedEvent] = useState(null);
  
  // Event Creation
  const [eventConfig, setEventConfig] = useState({
    title: '',
    description: '',
    category: 'music',
    accessLevel: 'premium',
    maxViewers: 500,
    recordingEnabled: true,
    chatEnabled: true,
    reactionsEnabled: true,
    tipsEnabled: false,
    duration: 60,
    startTime: new Date().toISOString().slice(0, 16) // Current time in datetime-local format
  });
  
  // Stream State
  const [eventStreamId, setEventStreamId] = useState(null);
  const [isEventStreaming, setIsEventStreaming] = useState(false);
  const [selectedEventForStream, setSelectedEventForStream] = useState('');
  const [eventStats, setEventStats] = useState({
    viewers: 0,
    earnings: 0,
    duration: '00:00:00'
  });
  
  // Chat State
  const [eventChatMessages, setEventChatMessages] = useState([]);
  const [newChatMessage, setNewChatMessage] = useState('');
  const [showEventChat, setShowEventChat] = useState(false);
  const [activeChatRoom, setActiveChatRoom] = useState(null);
  const chatMessagesEndRef = useRef(null);

  // Load available events on mount
  useEffect(() => {
    if (!currentUser) return;
    
    const db = getFirestore();
    const eventsQuery = query(
      collection(db, 'events'),
      where('artistId', '==', currentUser.uid),
      orderBy('startTime', 'asc')
    );
    
    const unsubscribe = onSnapshot(eventsQuery, (snapshot) => {
      const events = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setAvailableEvents(events);
      
      console.log('📋 Available events loaded:', events.length);
      
      // If no events available, switch to create mode
      if (events.length === 0 && eventMode === 'select') {
        setEventMode('create');
      }
    });
    
    return () => unsubscribe();
  }, [currentUser, eventMode]);

  // Auto-populate event creation form with stream info
  useEffect(() => {
    if (streamTitle && eventMode === 'create') {
      setEventConfig(prev => ({
        ...prev,
        title: streamTitle,
        description: streamDescription || '',
        category: streamCategory || 'music'
      }));
    }
  }, [streamTitle, streamDescription, streamCategory, eventMode]);

  // Set up chat listener when event is selected
  useEffect(() => {
    if (selectedEventForStream && isEventStreaming) {
      setupEventChatListener(selectedEventForStream);
      setShowEventChat(true);
    }
    
    return () => {
      if (activeChatRoom) {
        cleanupChatListener(activeChatRoom);
      }
    };
  }, [selectedEventForStream, isEventStreaming]);

  // Auto-scroll chat to bottom
  useEffect(() => {
    if (chatMessagesEndRef.current) {
      chatMessagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [eventChatMessages]);

  const createNewEvent = async () => {
    try {
      if (!eventConfig.title.trim()) {
        alert('Please enter an event title');
        return;
      }
      
      const db = getFirestore();
      
      // Create event document
      const eventData = {
        title: eventConfig.title,
        description: eventConfig.description,
        category: eventConfig.category,
        artistId: currentUser.uid,
        artistName: currentUser.displayName || 'Unknown Artist',
        artistAvatar: currentUser.photoURL || null,
        artistVerified: true, // Assume verified if they can stream
        
        // Stream configuration
        streamKey: `event_${currentUser.uid}_${Date.now()}`,
        streamUrl: `rtmp://live.restream.io/live/event_${currentUser.uid}_${Date.now()}`,
        
        // Event settings
        status: 'scheduled',
        startTime: new Date(eventConfig.startTime).getTime(),
        duration: eventConfig.duration,
        maxViewers: eventConfig.maxViewers,
        
        // Access control
        accessLevel: eventConfig.accessLevel,
        
        // Features
        chatEnabled: eventConfig.chatEnabled,
        reactionsEnabled: eventConfig.reactionsEnabled,
        recordingEnabled: eventConfig.recordingEnabled,
        tipsEnabled: eventConfig.tipsEnabled,
        
        // Analytics
        viewerCount: 0,
        peakViewers: 0,
        totalViews: 0,
        revenue: 0,
        
        // Timestamps
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp()
      };
      
      const eventRef = await addDoc(collection(db, 'events'), eventData);
      const eventId = eventRef.id;
      
      // Create chat room for the event
      await createEventChatRoom(eventId, eventData);
      
      console.log('🎭 Event created:', eventId);
      
      // Select the newly created event
      setSelectedEventId(eventId);
      setSelectedEvent({ id: eventId, ...eventData });
      setEventMode('select');
      setShowEventSettings(false);
      
      return eventId;
      
    } catch (error) {
      console.error('Failed to create event:', error);
      alert(`Failed to create event: ${error.message}`);
      return null;
    }
  };

  const createEventChatRoom = async (eventId, eventData) => {
    try {
      const database = getDatabase();
      
      // Create chat room in RTDB under chats/public/
      const chatRoomPath = `chats/public/event_${eventId}`;
      const chatRoomData = {
        type: 'event',
        eventId: eventId,
        eventTitle: eventData.title,
        artistId: eventData.artistId,
        artistName: eventData.artistName,
        artistAvatar: eventData.artistAvatar,
        
        // Chat room settings
        isActive: false, // Will be activated when event goes live
        allowUserStreaming: true,
        artistPriority: true,
        maxConcurrentUserStreams: 8, // Updated to 8 as per requirements
        
        // Moderation settings
        moderationEnabled: true,
        autoModeration: true,
        slowModeEnabled: false,
        slowModeDelay: 0,
        
        // Access control
        accessLevel: eventData.accessLevel,
        allowAnonymous: true, // Allow anonymous users in chat
        
        // Video streaming settings
        artistVideoActive: false,
        userStreams: {},
        
        // Analytics
        totalMessages: 0,
        activeUsers: 0,
        peakUsers: 0,
        
        // Timestamps
        createdAt: Date.now(),
        updatedAt: Date.now()
      };
      
      // Create the chat room
      await set(ref(database, chatRoomPath), chatRoomData);
      
      // Create initial system message
      const messagesRef = ref(database, `${chatRoomPath}/messages`);
      await push(messagesRef, {
        type: 'system',
        message: `Welcome to ${eventData.title}! Event chat room created. Anonymous users can chat, registered users can stream.`,
        timestamp: Date.now(),
        userId: 'system',
        userName: 'System'
      });
      
      console.log('💬 Event chat room created in RTDB:', chatRoomPath);
      
    } catch (error) {
      console.error('Failed to create event chat room:', error);
      // Don't block event creation if chat room fails
    }
  };

  const setupEventChatListener = (eventId) => {
    try {
      const database = getDatabase();
      const chatRoomPath = `chats/public/event_${eventId}`;
      const messagesPath = `${chatRoomPath}/messages`;
      
      console.log('🔗 Setting up event chat listener for:', messagesPath);
      
      // Listen to chat messages
      const messagesRef = ref(database, messagesPath);
      const unsubscribe = onValue(messagesRef, (snapshot) => {
        const data = snapshot.val();
        if (data) {
          const messagesList = Object.entries(data).map(([id, message]) => ({
            id,
            ...message
          })).sort((a, b) => a.timestamp - b.timestamp);
          
          setEventChatMessages(messagesList);
          console.log('💬 Event chat messages updated:', messagesList.length);
        } else {
          setEventChatMessages([]);
        }
      });
      
      setActiveChatRoom({ eventId, unsubscribe, chatRoomPath });
      
    } catch (error) {
      console.error('Failed to setup event chat listener:', error);
    }
  };

  const cleanupChatListener = (chatRoom) => {
    if (chatRoom && chatRoom.unsubscribe) {
      chatRoom.unsubscribe();
      console.log('🧹 Cleaned up chat listener for event:', chatRoom.eventId);
    }
  };

  const sendEventChatMessage = async () => {
    if (!newChatMessage.trim() || !activeChatRoom) return;
    
    try {
      const database = getDatabase();
      const messagesRef = ref(database, `${activeChatRoom.chatRoomPath}/messages`);
      
      const messageData = {
        type: 'artist',
        message: newChatMessage.trim(),
        timestamp: Date.now(),
        userId: currentUser.uid,
        userName: currentUser.displayName || 'Artist',
        userAvatar: currentUser.photoURL || null,
        isArtist: true,
        isStreamer: true
      };
      
      await push(messagesRef, messageData);
      setNewChatMessage('');
      
      console.log('📨 Artist message sent to event chat');
      
    } catch (error) {
      console.error('Failed to send chat message:', error);
      alert('Failed to send message');
    }
  };

  const handleChatKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendEventChatMessage();
    }
  };

  const startEventStream = async () => {
    try {
      let eventId = selectedEventId;
      
      // If using the stream association dropdown
      if (selectedEventForStream && !eventId) {
        eventId = selectedEventForStream;
        const associatedEvent = availableEvents.find(e => e.id === selectedEventForStream);
        setSelectedEvent(associatedEvent);
      }
      
      // If creating a new event, create it first
      if (eventMode === 'create') {
        eventId = await createNewEvent();
        if (!eventId) return;
      }
      
      if (!eventId) {
        alert('Please select or create an event');
        return;
      }
      
      const selectedEventData = selectedEvent || availableEvents.find(e => e.id === eventId) || eventConfig;
      const eventStartTime = new Date(selectedEventData.startTime || eventConfig.startTime).getTime();
      const now = Date.now();
      
      // Always start streaming immediately for artist portal integration
      const db = getFirestore();
      
      // Update event status to live
      await updateDoc(doc(db, 'events', eventId), {
        status: 'live',
        actualStartTime: serverTimestamp(),
        streamActive: true,
        artistStreaming: true // New field to indicate artist is streaming
      });
      
      // Activate chat room
      try {
        const database = getDatabase();
        const chatRoomRef = ref(database, `chats/public/event_${eventId}`);
        await set(chatRoomRef, { 
          isActive: true,
          artistVideoActive: true,
          artistStreaming: true,
          updatedAt: Date.now()
        });
        
        // Send artist joined message
        const messagesRef = ref(database, `chats/public/event_${eventId}/messages`);
        await push(messagesRef, {
          type: 'system',
          message: `🎭 ${currentUser.displayName || 'Artist'} has started streaming!`,
          timestamp: Date.now(),
          userId: 'system',
          userName: 'System'
        });
      } catch (chatError) {
        console.warn('Chat room activation failed:', chatError);
      }
      
      setEventStreamId(eventId);
      setSelectedEventForStream(eventId); // Set for chat listener
      setIsEventStreaming(true);
      setShowEventSettings(false);
      
      // Start analytics tracking
      startEventAnalytics();
      
      // Notify parent component
      if (onEventStreamStart) {
        onEventStreamStart({
          eventId: eventId,
          eventConfig: selectedEventData
        });
      }
      
      console.log('🔴 Event stream started:', eventId);
      
    } catch (error) {
      console.error('Failed to start event stream:', error);
      alert(`Failed to start event stream: ${error.message}`);
    }
  };

  const createGoogleCalendarReminder = (eventData) => {
    try {
      const startTime = new Date(eventData.startTime || eventConfig.startTime);
      const endTime = new Date(startTime.getTime() + (eventData.duration || eventConfig.duration) * 60000);
      
      // Format dates for Google Calendar (YYYYMMDDTHHMMSSZ)
      const formatDateForCalendar = (date) => {
        return date.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
      };
      
      const startTimeFormatted = formatDateForCalendar(startTime);
      const endTimeFormatted = formatDateForCalendar(endTime);
      
      // Create event description
      const description = `${eventData.description || eventConfig.description}\n\n` +
        `Access Level: ${eventData.accessLevel || eventConfig.accessLevel}\n` +
        `Max Viewers: ${eventData.maxViewers || eventConfig.maxViewers}\n` +
        `Category: ${eventData.category || eventConfig.category}\n\n` +
        `This is a reminder for your streaming event. Make sure to start your stream on time!`;
      
      // Create Google Calendar URL
      const calendarUrl = `https://calendar.google.com/calendar/render?action=TEMPLATE` +
        `&text=${encodeURIComponent(eventData.title || eventConfig.title)}` +
        `&dates=${startTimeFormatted}/${endTimeFormatted}` +
        `&details=${encodeURIComponent(description)}` +
        `&location=${encodeURIComponent('Streaming Studio - Events Theatre')}` +
        `&sf=true&output=xml`;
      
      // Open Google Calendar in new tab
      window.open(calendarUrl, '_blank');
      
      console.log('📅 Google Calendar reminder created');
      
    } catch (error) {
      console.error('Failed to create calendar reminder:', error);
      // Don't block the main flow if calendar creation fails
    }
  };

  const stopEventStream = async () => {
    try {
      if (eventStreamId) {
        const db = getFirestore();
        
        // Update event status
        await updateDoc(doc(db, 'events', eventStreamId), {
          status: 'ended',
          endTime: serverTimestamp(),
          streamActive: false,
          artistStreaming: false,
          finalStats: eventStats
        });
        
        // Deactivate chat room and send goodbye message
        try {
          const database = getDatabase();
          const chatRoomRef = ref(database, `chats/public/event_${eventStreamId}`);
          await set(chatRoomRef, {
            isActive: false,
            artistVideoActive: false,
            artistStreaming: false,
            updatedAt: Date.now()
          });
          
          // Send artist left message
          const messagesRef = ref(database, `chats/public/event_${eventStreamId}/messages`);
          await push(messagesRef, {
            type: 'system',
            message: `👋 ${currentUser.displayName || 'Artist'} has ended the stream. Thanks for watching!`,
            timestamp: Date.now(),
            userId: 'system',
            userName: 'System'
          });
        } catch (chatError) {
          console.warn('Chat room deactivation failed:', chatError);
        }
        
        // Clean up chat listener
        if (activeChatRoom) {
          cleanupChatListener(activeChatRoom);
          setActiveChatRoom(null);
        }
        
        setIsEventStreaming(false);
        setEventStreamId(null);
        setSelectedEventForStream('');
        setEventChatMessages([]);
        setShowEventChat(false);
        
        // Notify parent component
        if (onEventStreamStop) {
          onEventStreamStop();
        }
        
        console.log('⏹️ Event stream stopped');
      }
    } catch (error) {
      console.error('Failed to stop event stream:', error);
    }
  };

  const startEventAnalytics = () => {
    // Simulate real-time analytics
    const interval = setInterval(() => {
      if (!isEventStreaming) {
        clearInterval(interval);
        return;
      }
      
      setEventStats(prev => {
        const newViewers = Math.max(0, prev.viewers + (Math.random() - 0.3) * 10);
        const newEarnings = prev.earnings + (Math.random() * 5);
        
        return {
          viewers: Math.floor(newViewers),
          earnings: newEarnings,
          duration: prev.duration // This would be calculated from start time
        };
      });
    }, 3000);
  };

  const getAccessLevelIcon = (level) => {
    switch (level) {
      case 'vip': return <Crown className="vip-icon" />;
      case 'premium': return <Crown className="premium-icon" />;
      case 'free': return <Users className="free-icon" />;
      default: return <Crown className="premium-icon" />;
    }
  };

  const getAccessLevelText = (level) => {
    switch (level) {
      case 'vip': return 'VIP Members Only';
      case 'premium': return 'Premium Members Only';
      case 'free': return 'Free Access';
      default: return 'Premium Members Only';
    }
  };

  const getCategoryIcon = (category) => {
    switch (category) {
      case 'music': return <Music size={16} />;
      case 'talk': return <Mic size={16} />;
      case 'performance': return <Video size={16} />;
      default: return <Play size={16} />;
    }
  };

  const formatEventTime = (timestamp) => {
    return new Date(timestamp).toLocaleString();
  };

  return (
    <div className="stream-to-event-bridge">
      <div className="bridge-header">
        <div className="bridge-title">
          <Radio size={20} />
          <span>Events Theatre</span>
        </div>
        
        {isEventStreaming && (
          <div className="event-live-indicator">
            <div className="live-dot"></div>
            <span>LIVE EVENT</span>
          </div>
        )}
      </div>

      {!isEventStreaming ? (
        <div className="event-setup">
          {/* Stream Information Section */}
          <div className="stream-info-section">
            <h4>Stream Information</h4>
            <div className="form-group">
              <label>Associate with Event (Optional)</label>
              <div className="select-wrapper">
                <select
                  value={selectedEventForStream}
                  onChange={(e) => setSelectedEventForStream(e.target.value)}
                >
                  <option value="">No Event Association</option>
                  {availableEvents.map((event) => {
                    const eventTime = new Date(event.startTime);
                    const now = new Date();
                    const isUpcoming = eventTime > now;
                    const timeStatus = isUpcoming ? 'Upcoming' : (event.status === 'live' ? 'Live' : 'Ended');
                    
                    return (
                      <option key={event.id} value={event.id}>
                        {event.title} - {timeStatus} - {formatEventTime(event.startTime)}
                      </option>
                    );
                  })}
                </select>
                <ChevronDown size={16} />
              </div>
              {selectedEventForStream && (
                <div className="event-info-preview">
                  {(() => {
                    const selectedEvt = availableEvents.find(e => e.id === selectedEventForStream);
                    if (!selectedEvt) return null;
                    
                    const eventTime = new Date(selectedEvt.startTime);
                    const now = new Date();
                    const isUpcoming = eventTime > now;
                    const isLive = selectedEvt.status === 'live';
                    const timeStatus = isUpcoming ? 'Upcoming' : (isLive ? 'Live' : 'Ended');
                    const statusColor = isLive ? '#ef4444' : (isUpcoming ? '#f59e0b' : '#6b7280');
                    
                    return (
                      <div className="preview-content">
                        <span className="preview-label">Selected:</span>
                        <span className="preview-text">{selectedEvt.title}</span>
                        <span className="preview-status" style={{ color: statusColor }}>
                          {timeStatus}
                        </span>
                        <span className="preview-access">{getAccessLevelText(selectedEvt.accessLevel)}</span>
                        {selectedEvt.ticketPrice && (
                          <span className="preview-price">${selectedEvt.ticketPrice}</span>
                        )}
                      </div>
                    );
                  })()} 
                </div>
              )}
            </div>
          </div>
          
          <div className="setup-info">
            <h4>Broadcast to Events Theatre</h4>
            <p>Stream directly to paying customers in our premium Events Theatre</p>
          </div>
          
          {showEventSettings ? (
            <div className="event-settings">
              {/* Event Mode Toggle */}
              <div className="mode-selector">
                <button 
                  className={`mode-btn ${eventMode === 'select' ? 'active' : ''}`}
                  onClick={() => setEventMode('select')}
                  disabled={availableEvents.length === 0}
                >
                  Select Event
                </button>
                <button 
                  className={`mode-btn ${eventMode === 'create' ? 'active' : ''}`}
                  onClick={() => setEventMode('create')}
                >
                  Create New
                </button>
              </div>

              {eventMode === 'select' ? (
                <div className="event-selector">
                  {availableEvents.length > 0 ? (
                    <>
                      <div className="form-group">
                        <label>Select Event</label>
                        <div className="select-wrapper">
                          <select
                            value={selectedEventId}
                            onChange={(e) => {
                              setSelectedEventId(e.target.value);
                              const event = availableEvents.find(ev => ev.id === e.target.value);
                              setSelectedEvent(event);
                            }}
                          >
                            <option value="">Choose an event...</option>
                            {availableEvents.map((event) => (
                              <option key={event.id} value={event.id}>
                                {event.title} - {formatEventTime(event.startTime)}
                              </option>
                            ))}
                          </select>
                          <ChevronDown size={16} />
                        </div>
                      </div>
                      
                      {selectedEvent && (
                        <div className="event-preview">
                          <div className="event-preview-header">
                            {getCategoryIcon(selectedEvent.category)}
                            <h4>{selectedEvent.title}</h4>
                            <span className={`status-badge ${selectedEvent.status}`}>
                              {selectedEvent.status.toUpperCase()}
                            </span>
                          </div>
                          
                          <p>{selectedEvent.description}</p>
                          
                          <div className="event-details">
                            <div className="detail-row">
                              <Clock size={14} />
                              <span>{formatEventTime(selectedEvent.startTime)}</span>
                            </div>
                            <div className="detail-row">
                              <Users size={14} />
                              <span>Max {selectedEvent.maxViewers} viewers</span>
                            </div>
                            <div className="detail-row">
                              {getAccessLevelIcon(selectedEvent.accessLevel)}
                              <span>{getAccessLevelText(selectedEvent.accessLevel)}</span>
                            </div>

                          </div>
                        </div>
                      )}
                    </>
                  ) : (
                    <div className="no-events">
                      <Calendar size={32} />
                      <h4>No Events Available</h4>
                      <p>Create your first event to start streaming</p>
                      <button 
                        className="create-first-btn"
                        onClick={() => setEventMode('create')}
                      >
                        <Plus size={16} />
                        Create Event
                      </button>
                    </div>
                  )}
                </div>
              ) : (
                <div className="event-creator">
                  <div className="settings-form">
                    <div className="form-group">
                      <label>Event Title *</label>
                      <input
                        type="text"
                        value={eventConfig.title}
                        onChange={(e) => setEventConfig({...eventConfig, title: e.target.value})}
                        placeholder="Enter event title..."
                      />
                    </div>
                    
                    <div className="form-group">
                      <label>Description</label>
                      <textarea
                        value={eventConfig.description}
                        onChange={(e) => setEventConfig({...eventConfig, description: e.target.value})}
                        placeholder="Describe your event..."
                        rows={3}
                      />
                    </div>
                    
                    <div className="form-row">
                      <div className="form-group">
                        <label>Category</label>
                        <select
                          value={eventConfig.category}
                          onChange={(e) => setEventConfig({...eventConfig, category: e.target.value})}
                        >
                          <option value="music">Music</option>
                          <option value="talk">Talk Show</option>
                          <option value="performance">Performance</option>
                          <option value="education">Education</option>
                          <option value="other">Other</option>
                        </select>
                      </div>
                      
                      <div className="form-group">
                        <label>Access Level</label>
                        <select
                          value={eventConfig.accessLevel}
                          onChange={(e) => setEventConfig({...eventConfig, accessLevel: e.target.value})}
                        >
                          <option value="premium">Premium Members</option>
                          <option value="vip">VIP Members Only</option>
                          <option value="free">Free Access</option>
                        </select>
                      </div>
                    </div>
                    
                    <div className="form-row">
                      <div className="form-group">
                        <label>Start Time</label>
                        <input
                          type="datetime-local"
                          value={eventConfig.startTime}
                          onChange={(e) => setEventConfig({...eventConfig, startTime: e.target.value})}
                        />
                      </div>
                      
                      <div className="form-group">
                        <label>Duration (minutes)</label>
                        <input
                          type="number"
                          value={eventConfig.duration}
                          onChange={(e) => setEventConfig({...eventConfig, duration: parseInt(e.target.value) || 60})}
                          min="15"
                          max="300"
                        />
                      </div>
                    </div>
                    

                    
                    <div className="form-group">
                      <label>Max Viewers</label>
                      <input
                        type="number"
                        value={eventConfig.maxViewers}
                        onChange={(e) => setEventConfig({...eventConfig, maxViewers: parseInt(e.target.value) || 100})}
                        min="10"
                        max="10000"
                      />
                    </div>
                    
                    <div className="feature-toggles">
                      <label className="toggle-label">
                        <input
                          type="checkbox"
                          checked={eventConfig.recordingEnabled}
                          onChange={(e) => setEventConfig({...eventConfig, recordingEnabled: e.target.checked})}
                        />
                        <span>Enable Recording</span>
                      </label>
                      
                      <label className="toggle-label">
                        <input
                          type="checkbox"
                          checked={eventConfig.chatEnabled}
                          onChange={(e) => setEventConfig({...eventConfig, chatEnabled: e.target.checked})}
                        />
                        <span>Enable Chat</span>
                      </label>
                      
                      <label className="toggle-label">
                        <input
                          type="checkbox"
                          checked={eventConfig.reactionsEnabled}
                          onChange={(e) => setEventConfig({...eventConfig, reactionsEnabled: e.target.checked})}
                        />
                        <span>Enable Reactions</span>
                      </label>
                      
                      <label className="toggle-label">
                        <input
                          type="checkbox"
                          checked={eventConfig.tipsEnabled}
                          onChange={(e) => setEventConfig({...eventConfig, tipsEnabled: e.target.checked})}
                        />
                        <span>Enable Tips</span>
                      </label>
                    </div>
                  </div>
                </div>
              )}
              
              <div className="settings-actions">
                <button 
                  className="cancel-btn"
                  onClick={() => setShowEventSettings(false)}
                >
                  Cancel
                </button>
                <button 
                  className="start-event-btn"
                  onClick={startEventStream}
                  disabled={(eventMode === 'select' && !selectedEventId) || (eventMode === 'create' && !eventConfig.title.trim())}
                >
                  <Play size={16} />
                  {eventMode === 'create' ? 'Create Event' : 'Select Event'}
                </button>
              </div>
            </div>
          ) : (
            <div className="quick-setup">
              <div className="quick-info">
                <p>
                  {availableEvents.length > 0 
                    ? `${availableEvents.length} event${availableEvents.length === 1 ? '' : 's'} available` 
                    : 'No events created yet'
                  }
                </p>
              </div>
              
              <div className="setup-actions">
                <button 
                  className="settings-btn"
                  onClick={() => setShowEventSettings(true)}
                >
                  <Settings size={16} />
                  {availableEvents.length > 0 ? 'Select Event' : 'Create Event'}
                </button>
                
                {availableEvents.length > 0 && (
                  <button 
                    className="quick-start-btn"
                    onClick={() => {
                      // Auto-select first available event
                      const firstEvent = availableEvents[0];
                      setSelectedEventId(firstEvent.id);
                      setSelectedEvent(firstEvent);
                      startEventStream();
                    }}
                  >
                    <Radio size={16} />
                    Use Event
                  </button>
                )}
              </div>
            </div>
          )}
        </div>
      ) : (
        <div className="event-active">
          <div className="event-info">
            <h4>{selectedEvent?.title || 'Live Event'}</h4>
            <div className="event-details">
              <div className="detail-item">
                {getAccessLevelIcon(selectedEvent?.accessLevel)}
                <span>{getAccessLevelText(selectedEvent?.accessLevel)}</span>
              </div>
            </div>
          </div>
          
          <div className="event-stats">
            <div className="stat-item">
              <Users size={16} />
              <div>
                <span className="stat-value">{eventStats.viewers}</span>
                <span className="stat-label">Viewers</span>
              </div>
            </div>
            
            <div className="stat-item">
              <Clock size={16} />
              <div>
                <span className="stat-value">{eventStats.duration}</span>
                <span className="stat-label">Duration</span>
              </div>
            </div>
            
            {selectedEvent?.tipsEnabled && (
              <div className="stat-item">
                <DollarSign size={16} />
                <div>
                  <span className="stat-value">${eventStats.earnings.toFixed(2)}</span>
                  <span className="stat-label">Earnings</span>
                </div>
              </div>
            )}
          </div>
          
          {/* Event Chat Section */}
          <div className="event-chat-section">
            <div className="chat-header">
              <div className="chat-title">
                <MessageCircle size={16} />
                <span>Event Chat</span>
                <span className="chat-count">({eventChatMessages.length})</span>
              </div>
              <button 
                className="chat-toggle-btn"
                onClick={() => setShowEventChat(!showEventChat)}
              >
                {showEventChat ? 'Hide' : 'Show'}
              </button>
            </div>
            
            {showEventChat && (
              <div className="event-chat-container">
                <div className="chat-messages">
                  {eventChatMessages.length > 0 ? (
                    eventChatMessages.map((message) => (
                      <div key={message.id} className={`chat-message ${message.type}`}>
                        {message.type === 'system' ? (
                          <div className="system-message">
                            <span className="system-text">{message.message}</span>
                            <span className="message-time">
                              {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                            </span>
                          </div>
                        ) : (
                          <div className="user-message">
                            <div className="message-avatar">
                              {message.userAvatar ? (
                                <img src={message.userAvatar} alt={message.userName} />
                              ) : (
                                <div className="avatar-placeholder">
                                  {message.userName?.charAt(0) || 'U'}
                                </div>
                              )}
                            </div>
                            <div className="message-content">
                              <div className="message-header">
                                <span className={`message-author ${
                                  message.isArtist ? 'artist' : 
                                  message.isStreamer ? 'streamer' : 'user'
                                }`}>
                                  {message.userName}
                                  {message.isArtist && <span className="artist-badge">ARTIST</span>}
                                </span>
                                <span className="message-time">
                                  {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                </span>
                              </div>
                              <p className="message-text">{message.message}</p>
                            </div>
                          </div>
                        )}
                      </div>
                    ))
                  ) : (
                    <div className="no-messages">
                      <MessageCircle size={32} className="no-messages-icon" />
                      <p>No messages yet</p>
                      <small>Chat with your viewers here</small>
                    </div>
                  )}
                  <div ref={chatMessagesEndRef} />
                </div>
                
                <div className="chat-input-container">
                  <input
                    type="text"
                    value={newChatMessage}
                    onChange={(e) => setNewChatMessage(e.target.value)}
                    onKeyPress={handleChatKeyPress}
                    placeholder="Chat with your viewers..."
                    className="chat-input"
                    maxLength={500}
                  />
                  <button 
                    className="send-btn"
                    onClick={sendEventChatMessage}
                    disabled={!newChatMessage.trim()}
                  >
                    <Send size={16} />
                  </button>
                </div>
              </div>
            )}
          </div>
          
          <button 
            className="stop-event-btn"
            onClick={stopEventStream}
          >
            <Square size={16} />
            End Event
          </button>
        </div>
      )}
    </div>
  );
};

export default StreamToEventBridge;