// Streaming configuration that uses CORS proxy for development

import streamingConfigFallback from './streaming-fallback.js';

// Environment detection
const isDevelopment = import.meta.env.DEV;
const isProduction = !isDevelopment;

// CORS proxy configuration
const CORS_PROXY_BASE = 'http://localhost:8081'; // Streaming CORS proxy port

// Helper function to create proxy URL
const createProxyUrl = (targetService, endpoint) => {
  if (isDevelopment) {
    return `${CORS_PROXY_BASE}${endpoint}?service=${targetService}`;
  }
  return `https://${targetService}${endpoint}`;
};

// Get streaming URLs with CORS proxy support
const getStreamingUrls = () => {
  if (isDevelopment) {
    console.log('🔗 Using CORS proxy for streaming services');
    return {
      baseUrl: "http://talkstudio-2c55dh9q.livekit.cloud",
      ffmpegApi: "http://ffmpeg-api.talkstudio.space",
      rtmpApi: "http://rtmp-api.talkstudio.space",
      rtmpStream: "rtmp://talkstudio-2c55dh9q.livekit.cloud:1935/live/",
      protocol: "http:",
      secure: false,
      useCorsProxy: true
    };
  } else {
    console.log('🔒 Using direct HTTPS streaming services (production)');
    return {
      baseUrl: "https://talkstudio-2c55dh9q.livekit.cloud",
      ffmpegApi: "https://ffmpeg-api.talkstudio.space",
      rtmpApi: "https://rtmp-api.talkstudio.space",
      rtmpStream: "rtmps://talkstudio-2c55dh9q.livekit.cloud:443/live/",
      protocol: "https:",
      secure: true,
      useCorsProxy: false
    };
  }
};

const urls = getStreamingUrls();

console.log(`🌍 Streaming Environment: ${isProduction ? 'PRODUCTION' : 'DEVELOPMENT'}`);
console.log(`🔗 Using CORS Proxy: ${urls.useCorsProxy}`);
console.log(`🏠 Base URL: ${urls.baseUrl}`);

