// src/components/chat/ChatMessageInput.jsx
import React, { useState, useEffect, useRef } from 'react';
import { getDatabase, ref, push, serverTimestamp } from 'firebase/database';
import { useAuth } from '../../contexts/AuthContext';
import { Send, Smile, Paperclip, Image } from 'lucide-react';

const ChatMessageInput = ({ roomId }) => {
  const { currentUser } = useAuth();
  const [message, setMessage] = useState('');
  const [sending, setSending] = useState(false);
  const [anonymousUsername, setAnonymousUsername] = useState('');
  const textareaRef = useRef(null);

  // Auto-resize textarea as content grows
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = '40px';
      const scrollHeight = textareaRef.current.scrollHeight;
      textareaRef.current.style.height = scrollHeight + 'px';
    }
  }, [message]);

  // Retrieve anonymous username from localStorage
  useEffect(() => {
    if (!currentUser || currentUser.isAnonymous) {
      const storedUsername = localStorage.getItem('anonymousUsername');
      
      if (storedUsername) {
        setAnonymousUsername(storedUsername);
      } else {
        // Generate a random username if none exists
        const adjectives = ['Solar', 'Cosmic', 'Lunar', 'Stellar', 'Quantum', 'Cyber', 'Digital', 'Mystic', 'Astro', 'Neon'];
        const nouns = ['Fox', 'Wolf', 'Eagle', 'Tiger', 'Dragon', 'Lion', 'Hawk', 'Bear', 'Panther', 'Phoenix'];
        
        const randomAdjective = adjectives[Math.floor(Math.random() * adjectives.length)];
        const randomNoun = nouns[Math.floor(Math.random() * nouns.length)];
        const randomNumber = Math.floor(1000 + Math.random() * 9000); // 4 digit number
        
        const username = `${randomAdjective}${randomNoun}${randomNumber}`;
        localStorage.setItem('anonymousUsername', username);
        setAnonymousUsername(username);
      }
    }
  }, [currentUser]);

  const handleSubmit = async (e) => {
    if (e) e.preventDefault();
    
    if (!message.trim() || sending) return;
    
    try {
      setSending(true);
      
      const db = getDatabase();
      const messagesRef = ref(db, `chats/public/${roomId}/messages`);
      
      if (currentUser) {
        // For logged in users
        await push(messagesRef, {
          text: message.trim(),
          userId: currentUser.uid,
          displayName: currentUser.displayName || 'Anonymous',
          photoURL: currentUser.photoURL || null,
          timestamp: serverTimestamp()
        });
      } else {
        // For anonymous users
        await push(messagesRef, {
          text: message.trim(),
          userId: 'anonymous',
          displayName: `Anonymous (${anonymousUsername})`,
          isAnonymous: true,
          photoURL: null,
          timestamp: serverTimestamp()
        });
      }
      
      setMessage('');
      
      // Reset textarea height
      if (textareaRef.current) {
        textareaRef.current.style.height = '40px';
      }
    } catch (error) {
      console.error('Error sending message:', error);
      alert('Failed to send message');
    } finally {
      setSending(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  return (
    <div className="chat-message-input">
      <form onSubmit={handleSubmit}>
        <div className="input-wrapper">
          <div className="additional-actions">
            <button type="button" className="action-button" title="Attach file">
              <Paperclip size={18} />
            </button>
            <button type="button" className="action-button" title="Add image">
              <Image size={18} />
            </button>
          </div>
          
          <div className="input-container">
            <textarea
              ref={textareaRef}
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              onKeyDown={handleKeyPress}
              placeholder={currentUser ? (currentUser.isAnonymous ? `Send as Anonymous (${anonymousUsername})...` : "Type a message...") : `Send as Anonymous (${anonymousUsername})...`}
              disabled={sending}
              className="message-textarea"
              rows={1}
            />
            
            <div className="input-actions">
              <button type="button" className="emoji-button" title="Add emoji">
                <Smile size={18} />
              </button>
              
              <button 
                type="submit" 
                disabled={!message.trim() || sending}
                className="send-button"
                title="Send message"
              >
                <Send size={18} />
              </button>
            </div>
          </div>
        </div>
        
        <div className="input-hint">
          Press Enter to send, Shift+Enter for new line
        </div>
      </form>
      
      <style jsx>{`
        .chat-message-input {
          padding: 12px 16px;
          border-top: 1px solid #e5e7eb;
          background-color: #ffffff;
        }
        
        .input-wrapper {
          display: flex;
          align-items: flex-end;
          gap: 8px;
        }
        
        .additional-actions {
          display: flex;
          align-items: center;
          gap: 4px;
        }
        
        .action-button {
          display: flex;
          align-items: center;
          justify-content: center;
          width: 32px;
          height: 32px;
          background-color: transparent;
          border: none;
          border-radius: 6px;
          color: #6b7280;
          cursor: pointer;
          transition: background-color 0.2s;
        }
        
        .action-button:hover {
          background-color: #f3f4f6;
          color: #4b5563;
        }
        
        .input-container {
          flex-grow: 1;
          display: flex;
          align-items: flex-end;
          border: 1px solid #e5e7eb;
          border-radius: 12px;
          background-color: #f9fafb;
          overflow: hidden;
          transition: border-color 0.2s, box-shadow 0.2s;
        }
        
        .input-container:focus-within {
          border-color: #6366f1;
          box-shadow: 0 0 0 2px rgba(99, 102, 241, 0.2);
        }
        
        .message-textarea {
          flex-grow: 1;
          padding: 10px 12px;
          height: 40px;
          max-height: 120px;
          border: none;
          outline: none;
          resize: none;
          font-size: 15px;
          line-height: 1.5;
          color: #111827;
          background-color: transparent;
          font-family: inherit;
        }
        
        .message-textarea::placeholder {
          color: #9ca3af;
        }
        
        .input-actions {
          display: flex;
          align-items: center;
          padding-right: 6px;
        }
        
        .emoji-button {
          display: flex;
          align-items: center;
          justify-content: center;
          width: 32px;
          height: 32px;
          background-color: transparent;
          border: none;
          color: #6b7280;
          cursor: pointer;
          transition: color 0.2s;
        }
        
        .emoji-button:hover {
          color: #4b5563;
        }
        
        .send-button {
          display: flex;
          align-items: center;
          justify-content: center;
          width: 36px;
          height: 36px;
          margin-left: 4px;
          background-color: #4f46e5;
          color: white;
          border: none;
          border-radius: 10px;
          cursor: pointer;
          transition: background-color 0.2s, transform 0.1s;
        }
        
        .send-button:hover:not(:disabled) {
          background-color: #4338ca;
        }
        
        .send-button:active:not(:disabled) {
          transform: scale(0.95);
        }
        
        .send-button:disabled {
          background-color: #a5b4fc;
          cursor: not-allowed;
          opacity: 0.7;
        }
        
        .input-hint {
          margin-top: 6px;
          font-size: 11px;
          color: #9ca3af;
          text-align: right;
        }
        
        @media (max-width: 640px) {
          .additional-actions {
            display: none;
          }
          
          .chat-message-input {
            padding: 8px 12px;
          }
          
          .input-hint {
            display: none;
          }
        }
      `}</style>
    </div>
  );
};

export default ChatMessageInput;