import React, { useEffect, useState } from 'react';
import { useSiteConfig } from '../contexts/SiteConfigContext';

// A very simple background component with no dependencies on any CSS
const SimpleBackground = () => {
  const { config } = useSiteConfig();
  const [background, setBackground] = useState(null);
  const [error, setError] = useState(false);

  useEffect(() => {
    // Find active background
    if (config?.backgrounds) {
      const activeBg = config.backgrounds.find(bg => bg.isActive);
      
      if (activeBg) {
        console.log('Active background found:', activeBg);
        setBackground(activeBg);
      } else {
        console.log('No active background in config');
        setBackground(null);
      }
    }
  }, [config]);

  // Simple error handler for images
  const handleImageError = () => {
    console.error('Failed to load background image');
    setError(true);
  };
  
  // Render appropriate background based on type
  if (!background) {
    // Default background
    return (
      <div 
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: '#1e293b', // Default dark blue
          zIndex: 0
        }} 
      />
    );
  }

  if (background.type === 'color') {
    return (
      <div 
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: background.color || '#1e293b',
          zIndex: 0
        }} 
      />
    );
  }

  if (background.type === 'image' && !error) {
    return (
      <>
        {/* Fallback color in case image fails */}
        <div 
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: '#1e293b',
            zIndex: 0
          }} 
        />
        <img 
          src={background.url}
          alt="Background"
          onError={handleImageError}
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            zIndex: 1
          }}
        />
      </>
    );
  }

  if (background.type === 'video') {
    return (
      <>
        {/* Fallback color in case video fails */}
        <div 
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: '#1e293b',
            zIndex: 0
          }} 
        />
        <video
          autoPlay
          loop
          muted
          playsInline
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            zIndex: 1
          }}
          onError={handleImageError}
        >
          <source src={background.url} />
        </video>
      </>
    );
  }

  // Fallback if type is not recognized
  return (
    <div 
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        backgroundColor: '#1e293b',
        zIndex: 0
      }} 
    />
  );
};

export default SimpleBackground;