// src/services/AuditService.js
import { db, auth } from '../firebase';
import { 
  doc, 
  getDoc, 
  updateDoc, 
  collection, 
  addDoc, 
  getDocs, 
  query, 
  where,
  serverTimestamp,
  deleteDoc
} from 'firebase/firestore';

/**
 * Set a user's audit permission status
 * @param {string} userId - The user ID to update
 * @param {boolean} isAudit - Whether the user should have audit permissions
 * @returns {Promise<void>}
 */
export const setUserAuditPermission = async (userId, isAudit) => {
  // Check if the current user is an admin
  const currentUser = auth.currentUser;
  if (!currentUser) {
    throw new Error('You must be logged in to perform this action');
  }
  
  const userDoc = await getDoc(doc(db, 'users', currentUser.uid));
  if (!userDoc.exists() || userDoc.data().isAdmin !== true) {
    throw new Error('Only administrators can modify audit permissions');
  }
  
  // Update the user's audit permission
  await updateDoc(doc(db, 'users', userId), {
    isAudit: isAudit
  });
  
  // Log the permission change
  await addDoc(collection(db, 'auditPermissionChanges'), {
    userId,
    grantedBy: currentUser.uid,
    isAudit,
    timestamp: serverTimestamp()
  });
};

/**
 * Get all users with audit permissions
 * @returns {Promise<Array>} List of users with audit permissions
 */
export const getAuditUsers = async () => {
  // Check if the current user is an admin or has audit permissions
  const currentUser = auth.currentUser;
  if (!currentUser) {
    throw new Error('You must be logged in to perform this action');
  }
  
  const userDoc = await getDoc(doc(db, 'users', currentUser.uid));
  if (!userDoc.exists()) {
    throw new Error('User data not found');
  }
  
  const userData = userDoc.data();
  if (userData.isAdmin !== true && userData.isAudit !== true) {
    throw new Error('You need admin or audit permissions to view audit users');
  }
  
  // Query for users with audit permissions
  const q = query(collection(db, 'users'), where('isAudit', '==', true));
  const querySnapshot = await getDocs(q);
  
  return querySnapshot.docs.map(doc => ({
    id: doc.id,
    ...doc.data()
  }));
};

/**
 * Upload Firestore rules for validation and deployment
 * @param {string} rulesContent - The rules content to upload
 * @returns {Promise<Object>} Validation result
 */
export const uploadFirestoreRules = async (rulesContent) => {
  // Check if the current user is an admin or has audit permissions
  const currentUser = auth.currentUser;
  if (!currentUser) {
    throw new Error('You must be logged in to perform this action');
  }
  
  const userDoc = await getDoc(doc(db, 'users', currentUser.uid));
  if (!userDoc.exists()) {
    throw new Error('User data not found');
  }
  
  const userData = userDoc.data();
  if (userData.isAdmin !== true && userData.isAudit !== true) {
    throw new Error('You need admin or audit permissions to upload rules');
  }
  
  // Save rules to a rules collection for processing
  // In a real app, this would trigger a Cloud Function to validate
  // and deploy the rules to the Firebase project
  const docRef = await addDoc(collection(db, 'firestoreRules'), {
    content: rulesContent,
    uploadedBy: currentUser.uid,
    timestamp: serverTimestamp(),
    status: 'pending' // pending, validated, deployed, error
  });
  
  // For this example, we'll simulate validation success
  // In a real app, a Cloud Function would handle this
  await updateDoc(docRef, {
    status: 'validated',
    validationResult: {
      success: true,
      message: 'Rules validated successfully'
    }
  });
  
  // Return the document
  const updatedDoc = await getDoc(docRef);
  return {
    id: updatedDoc.id,
    ...updatedDoc.data()
  };
};

/**
 * Get all Firestore rules uploads
 * @returns {Promise<Array>} List of rule uploads
 */
export const getFirestoreRuleUploads = async () => {
  // Check if the current user is an admin or has audit permissions
  const currentUser = auth.currentUser;
  if (!currentUser) {
    throw new Error('You must be logged in to perform this action');
  }
  
  const userDoc = await getDoc(doc(db, 'users', currentUser.uid));
  if (!userDoc.exists()) {
    throw new Error('User data not found');
  }
  
  const userData = userDoc.data();
  if (userData.isAdmin !== true && userData.isAudit !== true) {
    throw new Error('You need admin or audit permissions to view rule uploads');
  }
  
  // Get all rule uploads
  const querySnapshot = await getDocs(collection(db, 'firestoreRules'));
  
  return querySnapshot.docs.map(doc => ({
    id: doc.id,
    ...doc.data()
  }));
};

/**
 * Export audit logs to a downloadable format
 * @param {string} type - The type of logs to export ('file', 'firebase', or 'all')
 * @returns {Promise<Blob>} Exported logs as a downloadable blob
 */
export const exportAuditLogs = async (type = 'all') => {
  // Check if the current user is an admin or has audit permissions
  const currentUser = auth.currentUser;
  if (!currentUser) {
    throw new Error('You must be logged in to perform this action');
  }
  
  const userDoc = await getDoc(doc(db, 'users', currentUser.uid));
  if (!userDoc.exists()) {
    throw new Error('User data not found');
  }
  
  const userData = userDoc.data();
  if (userData.isAdmin !== true && userData.isAudit !== true) {
    throw new Error('You need admin or audit permissions to export audit logs');
  }
  
  let fileAuditLogs = [];
  let firebaseAuditLogs = [];
  
  // Get file audit logs if requested
  if (type === 'file' || type === 'all') {
    const fileSnapshot = await getDocs(collection(db, 'fileAudit'));
    fileAuditLogs = fileSnapshot.docs.map(doc => ({
      id: doc.id,
      ...doc.data(),
      timestamp: doc.data().timestamp?.toDate().toISOString()
    }));
  }
  
  // Get Firebase audit logs if requested
  if (type === 'firebase' || type === 'all') {
    const fbSnapshot = await getDocs(collection(db, 'firebaseAudit'));
    firebaseAuditLogs = fbSnapshot.docs.map(doc => ({
      id: doc.id,
      ...doc.data(),
      timestamp: doc.data().timestamp?.toDate().toISOString()
    }));
  }
  
  // Create the export object
  const exportData = {
    exportedAt: new Date().toISOString(),
    exportedBy: currentUser.uid,
    fileAuditLogs,
    firebaseAuditLogs
  };
  
  // Convert to JSON
  const jsonString = JSON.stringify(exportData, null, 2);
  
  // Create a blob
  const blob = new Blob([jsonString], { type: 'application/json' });
  
  return blob;
};