/**
 * ReplayServiceDirect.js - Simple direct URL implementation
 * Since the video URL works in plain HTML, let's use it directly
 */

class ReplayServiceDirect {
  constructor() {
    this.currentEvent = null;
    this.availableQualities = [];
    this.eventCache = new Map();
    this.videoCache = new Map();
    
    // Event listeners - Initialize with default functions
    this.onEventLoaded = () => {};
    this.onQualitiesChanged = () => {};
    this.onError = (error) => console.error('ReplayService Error:', error);
    this.onLoadingStateChange = () => {};
    
    // Loading states
    this.isLoading = false;
    this.loadingProgress = 0;
    
    console.log('ReplayServiceDirect: Initialized - Using direct URLs');
  }

  /**
   * Get video data for a specific event
   * @param {string} eventId - The event ID
   * @returns {Promise<Object>} Video data structure
   */
  async getEventVideoData(eventId) {
    try {
      const videoData = {
        combined: {},
        individual: {}
      };

      // Direct URL that we know works
      const videoUrl = `https://storage.googleapis.com/talkstudio-fb.appspot.com/finished-events/${eventId}/${eventId}.mp4`;
      
      console.log('Using direct video URL:', videoUrl);
      
      // Since we know the URL works, just return it for all qualities
      const qualities = ['standard', 'hd', '720p', '1080p', '480p'];
      for (const quality of qualities) {
        videoData.combined[quality] = {
          url: videoUrl,
          metadata: null,
          size: 0, // We'll skip the HEAD request since it might cause issues
          format: 'mp4'
        };
      }
      
      return videoData;

    } catch (error) {
      console.error('Error getting event video data:', error);
      return { combined: {}, individual: {} };
    }
  }

  /**
   * Get all available replay events
   * @param {Object} options - Query options
   * @returns {Promise<Array>} Array of event objects
   */
  async getReplayEvents(options = {}) {
    try {
      console.log('ReplayServiceDirect: Returning events');
      return [
        {
          id: 'hskxzuvrySas45xJ2ZjX',
          title: 'Live Event Recording',
          description: 'Recorded live event',
          createdAt: new Date(),
          viewCount: 15,
          duration: 3600
        },
        {
          id: 'J8wJa3NbySdXzmzXFPZL',
          title: 'Test Event',
          description: 'Test recording',
          createdAt: new Date(),
          viewCount: 5,
          duration: 1800
        }
      ];
    } catch (error) {
      console.error('Error loading events:', error);
      return [];
    }
  }

  /**
   * Load a specific replay event
   * @param {string} eventId - The event ID to load
   * @returns {Promise<Object>} Event object with video data
   */
  async loadReplayEvent(eventId) {
    try {
      console.log('Loading replay event:', eventId);
      
      // Get video data
      const videoData = await this.getEventVideoData(eventId);
      
      const event = {
        id: eventId,
        title: `Event ${eventId}`,
        description: 'Recorded event',
        videos: videoData,
        createdAt: new Date(),
        updatedAt: new Date()
      };
      
      // Update available qualities
      this.availableQualities = Object.keys(videoData.combined || {});
      this.currentEvent = event;
      
      console.log('Event loaded successfully');
      
      if (this.onEventLoaded) {
        this.onEventLoaded(event);
      }
      
      return event;
      
    } catch (error) {
      console.error('Error loading event:', error);
      if (this.onError) {
        this.onError(error);
      }
      return null;
    }
  }

  /**
   * Get video URL for specific quality
   * @param {string} eventId - The event ID
   * @param {string} quality - The quality level (ignored - all use same URL)
   * @returns {Promise<string>} Video URL
   */
  async getVideoUrl(eventId, quality = 'standard') {
    // Always return the same URL
    return `https://storage.googleapis.com/talkstudio-fb.appspot.com/finished-events/${eventId}/${eventId}.mp4`;
  }

  // Simple implementations of other methods
  getRecentReplays(limit) {
    return this.getReplayEvents({ limit });
  }
  
  getPopularReplays(limit) {
    return this.getReplayEvents({ limit });
  }
  
  incrementViewCount(eventId) {
    console.log('View count incremented for:', eventId);
  }
  
  setLoadingState(loading, progress = 0) {
    this.isLoading = loading;
    this.loadingProgress = progress;
    if (this.onLoadingStateChange && typeof this.onLoadingStateChange === 'function') {
      this.onLoadingStateChange(loading, progress);
    }
  }
  
  initialize(callbacks = {}) {
    this.onEventLoaded = callbacks.onEventLoaded || (() => {});
    this.onQualitiesChanged = callbacks.onQualitiesChanged || (() => {});
    this.onError = callbacks.onError || ((error) => console.error('ReplayService Error:', error));
    this.onLoadingStateChange = callbacks.onLoadingStateChange || (() => {});
    console.log('ReplayServiceDirect initialized with callbacks');
    return true;
  }
  
  cleanup() {
    this.currentEvent = null;
    this.availableQualities = [];
    this.eventCache.clear();
    this.videoCache.clear();
  }
}

// Export singleton instance
const replayServiceDirect = new ReplayServiceDirect();
export default replayServiceDirect;