import React, { useState, useEffect } from 'react';
import { 
  getFirestore, 
  collection, 
  query, 
  where, 
  orderBy, 
  onSnapshot,
  doc,
  setDoc,
  deleteDoc,
  serverTimestamp,
  getDocs
} from 'firebase/firestore';
import { 
  Users, 
  Plus, 
  Calendar,
  Music,
  Edit,
  Trash2,
  Search,
  Check,
  X
} from 'lucide-react';
import './VenueArtistLineup.css';

const VenueArtistLineup = ({ venueId }) => {
  const [lineup, setLineup] = useState([]);
  const [events, setEvents] = useState([]);
  const [artists, setArtists] = useState([]);
  const [showAddArtist, setShowAddArtist] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedArtist, setSelectedArtist] = useState(null);
  const [loading, setLoading] = useState(true);
  const [editingLineup, setEditingLineup] = useState(null);
  
  useEffect(() => {
    if (!venueId) {
      setLoading(false);
      return;
    }
    
    setLoading(true);
    
    const unsubscribers = [];
    
    // Load lineup with listener
    const unsubscribeLineup = loadLineup();
    if (unsubscribeLineup) unsubscribers.push(unsubscribeLineup);
    
    // Load events with listener
    const unsubscribeEvents = loadEvents();
    if (unsubscribeEvents) unsubscribers.push(unsubscribeEvents);
    
    // Load artists (one-time fetch)
    loadArtists();
    
    // Cleanup function
    return () => {
      unsubscribers.forEach(unsub => {
        if (typeof unsub === 'function') unsub();
      });
    };
  }, [venueId]);

  const loadLineup = () => {
    try {
      const db = getFirestore();
      
      // Query venue lineup
      const lineupQuery = query(
        collection(db, 'venueLineups'),
        where('venueId', '==', venueId),
        orderBy('performanceDate', 'asc')
      );

      const unsubscribe = onSnapshot(
        lineupQuery, 
        (snapshot) => {
          const lineupData = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
          }));
          
          setLineup(lineupData);
          setLoading(false);
        },
        (error) => {
          console.error('Error loading lineup:', error);
          setLoading(false);
        }
      );

      return unsubscribe;
    } catch (error) {
      console.error('Error setting up lineup listener:', error);
      setLoading(false);
      return null;
    }
  };

  const loadEvents = () => {
    try {
      const db = getFirestore();
      
      // Query events at this venue
      const eventsQuery = query(
        collection(db, 'events'),
        where('venueId', '==', venueId),
        orderBy('startTime', 'asc')
      );

      const unsubscribe = onSnapshot(
        eventsQuery,
        (snapshot) => {
          const eventsData = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
          }));
          
          setEvents(eventsData);
        },
        (error) => {
          console.error('Error loading events:', error);
          // Continue anyway since events are optional
        }
      );

      return unsubscribe;
    } catch (error) {
      console.error('Error setting up events listener:', error);
      return null;
    }
  };

  const loadArtists = async () => {
    try {
      const db = getFirestore();
      
      // Query all artists
      const artistsQuery = query(
        collection(db, 'users'),
        where('isArtist', '==', true)
      );

      const snapshot = await getDocs(artistsQuery);
      const artistsData = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      
      setArtists(artistsData);
    } catch (error) {
      console.error('Error loading artists:', error);
      setArtists([]);
    }
  };

  const addArtistToLineup = async () => {
    if (!selectedArtist || !selectedArtist.performanceDate) return;
    
    try {
      const db = getFirestore();
      const lineupDoc = doc(collection(db, 'venueLineups'));
      
      await setDoc(lineupDoc, {
        venueId,
        artistId: selectedArtist.id,
        artistName: selectedArtist.displayName || selectedArtist.name,
        performanceDate: new Date(selectedArtist.performanceDate),
        performanceTime: selectedArtist.performanceTime || '20:00',
        genre: selectedArtist.genre || 'Various',
        notes: selectedArtist.notes || '',
        status: 'scheduled',
        createdAt: serverTimestamp()
      });
      
      setShowAddArtist(false);
      setSelectedArtist(null);
    } catch (error) {
      console.error('Error adding artist to lineup:', error);
      alert('Failed to add artist to lineup');
    }
  };

  const removeFromLineup = async (lineupId) => {
    if (!confirm('Are you sure you want to remove this artist from the lineup?')) return;
    
    try {
      const db = getFirestore();
      await deleteDoc(doc(db, 'venueLineups', lineupId));
    } catch (error) {
      console.error('Error removing from lineup:', error);
      alert('Failed to remove artist from lineup');
    }
  };

  const updateLineupItem = async (lineupId, updates) => {
    try {
      const db = getFirestore();
      await setDoc(doc(db, 'venueLineups', lineupId), {
        ...updates,
        updatedAt: serverTimestamp()
      }, { merge: true });
      
      setEditingLineup(null);
    } catch (error) {
      console.error('Error updating lineup:', error);
      alert('Failed to update lineup');
    }
  };

  const formatDate = (date) => {
    if (!date) return 'N/A';
    const d = date.toDate ? date.toDate() : new Date(date);
    return new Intl.DateTimeFormat('en-US', {
      weekday: 'short',
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    }).format(d);
  };

  const filteredArtists = artists.filter(artist => 
    artist.displayName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    artist.name?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return (
      <div className="venue-lineup-loading">
        <div className="loading-spinner"></div>
        <p>Loading artist lineup...</p>
      </div>
    );
  }
  
  if (!venueId) {
    return (
      <div className="venue-lineup-loading">
        <p>No venue selected. Please contact support if this issue persists.</p>
      </div>
    );
  }

  return (
    <div className="venue-artist-lineup">
      <div className="lineup-header">
        <div className="header-content">
          <h2>Artist Lineup</h2>
          <p>Manage your venue's performing artists and schedule</p>
        </div>
        
        <button 
          className="add-artist-button"
          onClick={() => setShowAddArtist(true)}
        >
          <Plus size={16} />
          Add Artist
        </button>
      </div>

      {showAddArtist && (
        <div className="add-artist-modal">
          <div className="modal-content">
            <div className="modal-header">
              <h3>Add Artist to Lineup</h3>
              <button onClick={() => setShowAddArtist(false)}>
                <X size={20} />
              </button>
            </div>
            
            <div className="modal-body">
              <div className="search-box">
                <Search size={16} />
                <input
                  type="text"
                  placeholder="Search artists..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
              
              <div className="artists-list">
                {filteredArtists.map(artist => (
                  <div 
                    key={artist.id}
                    className={`artist-item ${selectedArtist?.id === artist.id ? 'selected' : ''}`}
                    onClick={() => setSelectedArtist(artist)}
                  >
                    <div className="artist-info">
                      <h4>{artist.displayName || artist.name}</h4>
                      <p>{artist.genre || 'Various'}</p>
                    </div>
                    {selectedArtist?.id === artist.id && <Check size={16} />}
                  </div>
                ))}
              </div>
              
              {selectedArtist && (
                <div className="performance-details">
                  <h4>Performance Details</h4>
                  <div className="form-group">
                    <label>Performance Date</label>
                    <input
                      type="date"
                      onChange={(e) => setSelectedArtist({
                        ...selectedArtist,
                        performanceDate: e.target.value
                      })}
                    />
                  </div>
                  <div className="form-group">
                    <label>Performance Time</label>
                    <input
                      type="time"
                      defaultValue="20:00"
                      onChange={(e) => setSelectedArtist({
                        ...selectedArtist,
                        performanceTime: e.target.value
                      })}
                    />
                  </div>
                  <div className="form-group">
                    <label>Notes (optional)</label>
                    <textarea
                      placeholder="Special requirements, set duration, etc."
                      onChange={(e) => setSelectedArtist({
                        ...selectedArtist,
                        notes: e.target.value
                      })}
                    />
                  </div>
                </div>
              )}
            </div>
            
            <div className="modal-footer">
              <button 
                className="cancel-button"
                onClick={() => setShowAddArtist(false)}
              >
                Cancel
              </button>
              <button 
                className="confirm-button"
                onClick={addArtistToLineup}
                disabled={!selectedArtist || !selectedArtist.performanceDate}
              >
                Add to Lineup
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="lineup-stats">
        <div className="stat-item">
          <Users size={20} />
          <div>
            <h4>{lineup.length}</h4>
            <p>Total Artists</p>
          </div>
        </div>
        <div className="stat-item">
          <Calendar size={20} />
          <div>
            <h4>{lineup.filter(l => new Date(l.performanceDate.toDate ? l.performanceDate.toDate() : l.performanceDate) >= new Date()).length}</h4>
            <p>Upcoming Shows</p>
          </div>
        </div>
        <div className="stat-item">
          <Music size={20} />
          <div>
            <h4>{events.length}</h4>
            <p>Total Events</p>
          </div>
        </div>
      </div>

      <div className="lineup-table">
        <h3>Scheduled Performances</h3>
        <div className="table-container">
          <table>
            <thead>
              <tr>
                <th>Artist</th>
                <th>Performance Date</th>
                <th>Time</th>
                <th>Genre</th>
                <th>Status</th>
                <th>Notes</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {lineup.length === 0 ? (
                <tr>
                  <td colSpan="7" className="empty-state">
                    No artists in lineup yet
                  </td>
                </tr>
              ) : (
                lineup.map(item => (
                  <tr key={item.id}>
                    <td className="artist-name">{item.artistName}</td>
                    <td>{formatDate(item.performanceDate)}</td>
                    <td>{item.performanceTime || 'TBD'}</td>
                    <td>{item.genre}</td>
                    <td>
                      <span className={`status-badge ${item.status}`}>
                        {item.status}
                      </span>
                    </td>
                    <td className="notes">{item.notes || '-'}</td>
                    <td className="actions">
                      <button 
                        className="action-button edit"
                        onClick={() => setEditingLineup(item)}
                      >
                        <Edit size={14} />
                      </button>
                      <button 
                        className="action-button delete"
                        onClick={() => removeFromLineup(item.id)}
                      >
                        <Trash2 size={14} />
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {editingLineup && (
        <div className="edit-modal">
          <div className="modal-content">
            <div className="modal-header">
              <h3>Edit Performance</h3>
              <button onClick={() => setEditingLineup(null)}>
                <X size={20} />
              </button>
            </div>
            
            <div className="modal-body">
              <div className="form-group">
                <label>Performance Date</label>
                <input
                  type="date"
                  defaultValue={editingLineup.performanceDate.toDate ? 
                    editingLineup.performanceDate.toDate().toISOString().split('T')[0] :
                    new Date(editingLineup.performanceDate).toISOString().split('T')[0]
                  }
                  onChange={(e) => setEditingLineup({
                    ...editingLineup,
                    performanceDate: new Date(e.target.value)
                  })}
                />
              </div>
              <div className="form-group">
                <label>Performance Time</label>
                <input
                  type="time"
                  defaultValue={editingLineup.performanceTime}
                  onChange={(e) => setEditingLineup({
                    ...editingLineup,
                    performanceTime: e.target.value
                  })}
                />
              </div>
              <div className="form-group">
                <label>Status</label>
                <select
                  value={editingLineup.status}
                  onChange={(e) => setEditingLineup({
                    ...editingLineup,
                    status: e.target.value
                  })}
                >
                  <option value="scheduled">Scheduled</option>
                  <option value="confirmed">Confirmed</option>
                  <option value="cancelled">Cancelled</option>
                  <option value="completed">Completed</option>
                </select>
              </div>
              <div className="form-group">
                <label>Notes</label>
                <textarea
                  value={editingLineup.notes}
                  onChange={(e) => setEditingLineup({
                    ...editingLineup,
                    notes: e.target.value
                  })}
                />
              </div>
            </div>
            
            <div className="modal-footer">
              <button 
                className="cancel-button"
                onClick={() => setEditingLineup(null)}
              >
                Cancel
              </button>
              <button 
                className="confirm-button"
                onClick={() => updateLineupItem(editingLineup.id, editingLineup)}
              >
                Update
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default VenueArtistLineup;