// src/components/tracking/UserActivityTracker.jsx
import { useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { updateOnlineStatus, ensureUserProfile } from '../../services/profiles';

const UserActivityTracker = () => {
  const { currentUser } = useAuth();

  useEffect(() => {
    // Only track for authenticated non-anonymous users
    if (!currentUser || currentUser.isAnonymous) {
      return;
    }

    // Ensure the user has a profile and set status to online when component mounts
    const initializeUserProfile = async () => {
      try {
        // Create or update profile
        await ensureUserProfile(currentUser);
      } catch (error) {
        console.error('Error initializing user profile:', error);
      }
    };
    
    initializeUserProfile();

    // Set up interval to update the lastActive timestamp periodically
    const interval = setInterval(() => {
      if (currentUser && !currentUser.isAnonymous) {
        updateOnlineStatus(currentUser.uid, true);
      }
    }, 60000); // Update every minute

    // Track user activity based on page events
    const updateUserActivity = () => {
      if (currentUser && !currentUser.isAnonymous) {
        updateOnlineStatus(currentUser.uid, true);
      }
    };

    // Handle page visibility changes
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        if (currentUser && !currentUser.isAnonymous) {
          updateOnlineStatus(currentUser.uid, true);
        }
      } else {
        if (currentUser && !currentUser.isAnonymous) {
          updateOnlineStatus(currentUser.uid, false);
        }
      }
    };

    // Set up beforeunload to update status when user closes the page
    const handleBeforeUnload = () => {
      if (currentUser && !currentUser.isAnonymous) {
        updateOnlineStatus(currentUser.uid, false);
      }
    };

    // Add event listeners
    document.addEventListener('mousemove', updateUserActivity);
    document.addEventListener('keydown', updateUserActivity);
    document.addEventListener('click', updateUserActivity);
    document.addEventListener('visibilitychange', handleVisibilityChange);
    window.addEventListener('beforeunload', handleBeforeUnload);

    // Cleanup
    return () => {
      clearInterval(interval);
      document.removeEventListener('mousemove', updateUserActivity);
      document.removeEventListener('keydown', updateUserActivity);
      document.removeEventListener('click', updateUserActivity);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      window.removeEventListener('beforeunload', handleBeforeUnload);

      // Set user to offline when component unmounts
      if (currentUser && !currentUser.isAnonymous) {
        updateOnlineStatus(currentUser.uid, false);
      }
    };
  }, [currentUser]);

  // This component doesn't render anything
  return null;
};

export default UserActivityTracker;