/**
 * Enhanced Tip Button Component
 * Uses environment-specific Stripe URLs for tipping
 * Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\components\monetization\EnhancedTipButton.jsx
 */

import React, { useState, useEffect } from 'react';
import { Gift, Heart, Star, AlertCircle, ExternalLink, Lock, Info } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import TipManager from '../../services/TipManager.js';
import './EnhancedTipButton.css';

const EnhancedTipButton = ({ 
  event, 
  artistId, 
  venueId = null, 
  className = '', 
  size = 'medium',
  showAmountSelector = true,
  onTipStart = null,
  onTipComplete = null 
}) => {
  const { currentUser } = useAuth();
  const [isLoading, setIsLoading] = useState(true);
  const [eligibility, setEligibility] = useState(null);
  const [selectedAmount, setSelectedAmount] = useState(20);
  const [showAmountModal, setShowAmountModal] = useState(false);
  const [tipStats, setTipStats] = useState(null);

  useEffect(() => {
    checkTippingEligibility();
    loadTipStats();
  }, [event, artistId]);

  const checkTippingEligibility = async () => {
    try {
      setIsLoading(true);
      const eligibilityCheck = TipManager.checkTippingEligibility(event);
      setEligibility(eligibilityCheck);
      console.log('🎁 Tipping eligibility:', eligibilityCheck);
    } catch (error) {
      console.error('❌ Failed to check tipping eligibility:', error);
      setEligibility({ enabled: false, reason: 'Error checking eligibility' });
    } finally {
      setIsLoading(false);
    }
  };

  const loadTipStats = async () => {
    if (!event?.id) return;
    
    try {
      const stats = await TipManager.getEventTipStats(event.id);
      setTipStats(stats);
    } catch (error) {
      console.error('❌ Failed to load tip stats:', error);
    }
  };

  const handleTipClick = async (amount = selectedAmount) => {
    if (!TipManager.canUserTip(currentUser)) {
      alert('Please log in to send tips');
      return;
    }

    if (!eligibility?.enabled) {
      alert(eligibility?.reason || 'Tipping is not available for this event');
      return;
    }

    try {
      // Create tip record in Firestore
      const tipRecord = await TipManager.createTipRecord({
        eventId: event.id,
        artistId,
        venueId,
        userId: currentUser.uid,
        userName: currentUser.displayName || currentUser.email,
        amount,
        eventTitle: event.title,
        artistName: event.artistName
      });

      // Call onTipStart callback
      if (onTipStart) {
        onTipStart(tipRecord);
      }

      // Get Stripe URL and redirect
      const stripeUrl = TipManager.getStripeUrl(amount);
      
      // Add success callback parameters to URL
      const urlParams = new URLSearchParams({
        tipId: tipRecord.id,
        eventId: event.id,
        amount: amount.toString(),
        returnUrl: window.location.href
      });
      
      const finalUrl = `${stripeUrl}?${urlParams.toString()}`;
      
      console.log('🚀 Redirecting to Stripe:', {
        amount,
        stripeUrl,
        tipRecord: tipRecord.id,
        finalUrl
      });

      // Open Stripe checkout in new tab/window
      window.open(finalUrl, '_blank', 'width=800,height=600,scrollbars=yes,resizable=yes');
      
    } catch (error) {
      console.error('❌ Failed to process tip:', error);
      alert('Failed to process tip. Please try again.');
    }
  };

  const handleAmountSelect = (amount) => {
    setSelectedAmount(amount);
    setShowAmountModal(false);
    handleTipClick(amount);
  };

  if (isLoading) {
    return (
      <div className={`enhanced-tip-button loading ${className}`}>
        <div className="loading-spinner-small"></div>
        <span>Loading...</span>
      </div>
    );
  }

  // Don't show button if tipping is not enabled
  if (!eligibility?.enabled) {
    return (
      <div className={`enhanced-tip-button disabled ${className}`} title={eligibility?.reason}>
        <Lock size={16} />
        <span>Tips Unavailable</span>
        <div className="tip-info-tooltip">
          <Info size={12} />
          <div className="tooltip-content">
            {eligibility?.reason}
            <br />
            <small>Event Type: {eligibility?.eventType || 'Unknown'}</small>
          </div>
        </div>
      </div>
    );
  }

  // Anonymous user button
  if (!TipManager.canUserTip(currentUser)) {
    return (
      <div className={`enhanced-tip-button anonymous ${className}`}>
        <Lock size={16} />
        <span>Login to Tip</span>
      </div>
    );
  }

  const tipAmounts = TipManager.getFormattedAmounts();

  return (
    <div className={`enhanced-tip-button-container ${className}`}>
      {/* Main Tip Button */}
      <div className={`enhanced-tip-button ${size} enabled`}>
        {showAmountSelector ? (
          <button 
            className="tip-trigger"
            onClick={() => setShowAmountModal(true)}
            title={`Send a tip to ${event?.artistName || 'the artist'}`}
          >
            <Gift size={size === 'small' ? 14 : 16} />
            <span>Send Tip</span>
            <span className="tip-amounts-preview">
              ${tipAmounts.map(a => a.amount).join(', $')}
            </span>
          </button>
        ) : (
          <button 
            className="tip-trigger"
            onClick={() => handleTipClick()}
            title={`Send $${selectedAmount} tip to ${event?.artistName || 'the artist'}`}
          >
            <Gift size={size === 'small' ? 14 : 16} />
            <span>Tip ${selectedAmount}</span>
          </button>
        )}

        {/* Tip Stats */}
        {tipStats && tipStats.totalTips > 0 && (
          <div className="tip-stats-preview">
            <Heart size={12} />
            <span>{tipStats.totalTips} tips • ${tipStats.totalAmount}</span>
          </div>
        )}
      </div>

      {/* Amount Selection Modal */}
      {showAmountModal && (
        <div className="tip-amount-modal">
          <div className="modal-backdrop" onClick={() => setShowAmountModal(false)}></div>
          <div className="modal-content">
            <div className="modal-header">
              <h3>Choose Tip Amount</h3>
              <button 
                className="close-btn" 
                onClick={() => setShowAmountModal(false)}
              >
                ×
              </button>
            </div>
            
            <div className="modal-body">
              <div className="event-info">
                <div className="event-details">
                  <h4>{event?.title}</h4>
                  <p>Supporting: {event?.artistName}</p>
                  {event?.venueName && <p>Venue: {event.venueName}</p>}
                </div>
                
                <div className="environment-badge">
                  <span className={eligibility?.environment === 'Production' ? 'prod' : 'dev'}>
                    {eligibility?.environment}
                  </span>
                </div>
              </div>

              <div className="tip-amounts">
                <h5>Select Amount:</h5>
                <div className="amount-buttons">
                  {tipAmounts.map(({ amount, formatted }) => (
                    <button
                      key={amount}
                      className={`amount-btn ${selectedAmount === amount ? 'selected' : ''}`}
                      onClick={() => handleAmountSelect(amount)}
                    >
                      <div className="amount-value">{formatted}</div>
                      <div className="amount-description">
                        {amount === 20 && 'Show Support'}
                        {amount === 50 && 'Great Performance'}
                        {amount === 100 && 'Amazing Show'}
                      </div>
                    </button>
                  ))}
                </div>
              </div>

              <div className="tip-info">
                <div className="info-item">
                  <ExternalLink size={14} />
                  <span>Opens secure Stripe checkout</span>
                </div>
                <div className="info-item">
                  <Heart size={14} />
                  <span>Supports artist and venue</span>
                </div>
                <div className="info-item">
                  <Star size={14} />
                  <span>Safe and secure payment</span>
                </div>
              </div>

              {tipStats && tipStats.totalTips > 0 && (
                <div className="event-tip-stats">
                  <h6>Event Tip Stats:</h6>
                  <div className="stats-grid">
                    <div className="stat">
                      <span className="value">{tipStats.totalTips}</span>
                      <span className="label">Total Tips</span>
                    </div>
                    <div className="stat">
                      <span className="value">${tipStats.totalAmount}</span>
                      <span className="label">Total Amount</span>
                    </div>
                    <div className="stat">
                      <span className="value">{tipStats.uniqueTippers}</span>
                      <span className="label">Supporters</span>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Environment indicator for development */}
      {eligibility?.environment !== 'Production' && (
        <div className="dev-indicator">
          <AlertCircle size={12} />
          <span>{eligibility?.environment} Mode</span>
        </div>
      )}
    </div>
  );
};

export default EnhancedTipButton;
