// src/components/premium/PremiumCheckoutModal.jsx
//
// Stripe Elements checkout for TalkStudio Premium. Opened from the membership
// page: fetches a client secret from the payment proxy, mounts PaymentElement,
// and on success hands off to /subscription-success, which is what actually
// grants premium on users/{uid}.

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Elements, PaymentElement, useElements, useStripe } from '@stripe/react-stripe-js';
import { loadStripe } from '@stripe/stripe-js';
import { AlertTriangle, CreditCard, Loader, Shield, X } from 'lucide-react';
import { getStripePublishableKey } from '../../services/StripeInitializer';
import {
  createPremiumMembershipIntent,
  getPlan,
  successUrl,
} from '../../services/PremiumCheckoutService';
import './PremiumCheckoutModal.css';

// loadStripe is memoized outside the component so re-renders don't re-load
// Stripe.js. The key is environment-resolved (live on talkstudio.space).
// loadStripe throws on an empty key, so a misconfigured build surfaces as the
// modal's error banner rather than a blank dialog.
let stripePromise = null;
const getStripe = () => {
  if (!stripePromise) {
    const key = getStripePublishableKey();
    if (!key) throw new Error('Payments are misconfigured (no Stripe key). Please contact support.');
    stripePromise = loadStripe(key);
  }
  return stripePromise;
};

const formatUsd = (cents) => `$${(cents / 100).toFixed(2)}`;

/** The form itself — must live inside <Elements> to use the Stripe hooks. */
const CheckoutForm = ({ plan, onClose }) => {
  const stripe = useStripe();
  const elements = useElements();
  const navigate = useNavigate();
  const [isProcessing, setIsProcessing] = useState(false);
  const [errorMessage, setErrorMessage] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!stripe || !elements || isProcessing) return;

    setIsProcessing(true);
    setErrorMessage(null);

    const { error, paymentIntent } = await stripe.confirmPayment({
      elements,
      confirmParams: { return_url: successUrl(plan.id) },
      // Card payments finish inline; redirect methods still leave the page.
      redirect: 'if_required',
    });

    if (error) {
      setErrorMessage(error.message || 'Your payment could not be completed.');
      setIsProcessing(false);
      return;
    }

    if (paymentIntent?.status === 'succeeded' || paymentIntent?.status === 'processing') {
      // Same destination Stripe would have redirected to, so the success page
      // sees the identical query shape either way.
      navigate(
        `/subscription-success?plan=${plan.id}` +
          `&amount=${(plan.priceCents / 100).toFixed(2)}` +
          `&payment_intent=${paymentIntent.id}&redirect_status=${paymentIntent.status}`
      );
      return;
    }

    setErrorMessage(
      `Payment status: ${paymentIntent?.status || 'unknown'}. Please contact support if you were charged.`
    );
    setIsProcessing(false);
  };

  return (
    <form className="premium-checkout-form" onSubmit={handleSubmit}>
      {errorMessage && (
        <div className="premium-checkout-error" role="alert">
          <AlertTriangle size={18} />
          <span>{errorMessage}</span>
        </div>
      )}

      <PaymentElement />

      <button className="premium-checkout-pay" type="submit" disabled={!stripe || isProcessing}>
        {isProcessing ? (
          <>
            <Loader size={18} className="premium-checkout-spin" />
            <span>Processing…</span>
          </>
        ) : (
          <>
            <CreditCard size={18} />
            <span>Pay {formatUsd(plan.priceCents)}</span>
          </>
        )}
      </button>

      <button className="premium-checkout-cancel" type="button" onClick={onClose} disabled={isProcessing}>
        Cancel
      </button>

      <p className="premium-checkout-secure">
        <Shield size={14} /> Secured by Stripe. Cancel anytime from Settings.
      </p>
    </form>
  );
};

const PremiumCheckoutModal = ({ isOpen, planId, userId, onClose }) => {
  const [clientSecret, setClientSecret] = useState(null);
  const [error, setError] = useState(null);
  const plan = getPlan(planId);

  useEffect(() => {
    if (!isOpen || !plan) return;

    let cancelled = false;
    setClientSecret(null);
    setError(null);

    Promise.resolve()
      // Load Stripe.js alongside the intent so a bad key fails here, where we
      // can show it, instead of inside <Elements>.
      .then(() => getStripe())
      .then(() => createPremiumMembershipIntent(plan.id, userId))
      .then(({ clientSecret: secret }) => {
        if (!cancelled) setClientSecret(secret);
      })
      .catch((err) => {
        if (!cancelled) setError(err.message);
      });

    return () => {
      cancelled = true;
    };
  }, [isOpen, plan, userId]);

  if (!isOpen || !plan) return null;

  return (
    <div className="premium-checkout-backdrop" onClick={onClose}>
      <div
        className="premium-checkout-modal"
        role="dialog"
        aria-modal="true"
        aria-label={`Checkout — ${plan.name}`}
        onClick={(e) => e.stopPropagation()}
      >
        <button className="premium-checkout-close" onClick={onClose} aria-label="Close checkout">
          <X size={18} />
        </button>

        <div className="premium-checkout-header">
          <h2>{plan.name}</h2>
          <p className="premium-checkout-amount">
            {formatUsd(plan.priceCents)}
            <span>{plan.interval}</span>
          </p>
          <p className="premium-checkout-tagline">{plan.tagline}</p>
        </div>

        {error && (
          <div className="premium-checkout-error" role="alert">
            <AlertTriangle size={18} />
            <span>{error}</span>
          </div>
        )}

        {!error && !clientSecret && (
          <div className="premium-checkout-loading">
            <Loader size={22} className="premium-checkout-spin" />
            <p>Setting up secure checkout…</p>
          </div>
        )}

        {clientSecret && (
          <Elements
            stripe={getStripe()}
            options={{
              clientSecret,
              appearance: { theme: 'night', variables: { colorPrimary: '#8b5cf6' } },
            }}
          >
            <CheckoutForm plan={plan} onClose={onClose} />
          </Elements>
        )}
      </div>
    </div>
  );
};

export default PremiumCheckoutModal;
