// Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\pages\StreamTestPage.jsx
// Updated Stream Test Page for NEW Google Cloud Run FFmpeg streaming service

import React, { useState, useEffect } from 'react';
import { streamingConfigFixed as streamingConfig, rtmpService, ffmpegService } from "../config/streaming-fixed.js"
// UPDATED: Use main FFmpegStreamingService instead of Fixed version
import ffmpegStreamingService from "../services/streaming/FFmpegStreamingService.js"
import { useAuth } from '../contexts/AuthContext';
import { useStreamingLiveKit as useStreaming } from '../contexts/StreamingContextLiveKit';
import { 
  CheckCircle, 
  XCircle, 
  AlertCircle, 
  Play, 
  Square, 
  Wifi, 
  WifiOff,
  Activity,
  Monitor,
  Settings,
  RefreshCw,
  ExternalLink,
  Cloud
} from 'lucide-react';

const StreamTestPage = () => {
  const { currentUser } = useAuth();
  const { 
    streamingServiceReady, 
    testStreamingConnectivity, 
    getStreamingStats,
    error: streamingError 
  } = useStreaming();

  // Test states
  const [testResults, setTestResults] = useState({
    newStreamingServiceHealth: null,
    newStreamingServiceConnectivity: null,
    rtmpHealth: null,
    ffmpegHealth: null,
    rtmpConnectivity: null,
    ffmpegConnectivity: null,
    streamCapability: null,
    serviceInitialization: null,
    endpointTests: {}
  });
  
  const [isRunningTests, setIsRunningTests] = useState(false);
  const [testMode, setTestMode] = useState('comprehensive'); // 'simple' or 'comprehensive'
  const [selectedQuality, setSelectedQuality] = useState('medium');
  const [testEventId, setTestEventId] = useState('test_event_stream');
  const [streamStats, setStreamStats] = useState(null);
  const [testLogs, setTestLogs] = useState([]);
  const [activeTestStreamId, setActiveTestStreamId] = useState(null);

  // NEW: Endpoints to test
  const NEW_ENDPOINTS = {
    health: `${ffmpegService.baseUrl}/health`,
    startStream: `${ffmpegService.baseUrl}/api/streams/start`,
    listStreams: `${ffmpegService.baseUrl}/api/streams`,
    streamStatus: `${ffmpegService.baseUrl}/api/streams`,
    stopStream: `${ffmpegService.baseUrl}/api/streams`,
    processJobs: `${ffmpegService.baseUrl}/api/jobs`
  };

  // Add log function
  const addLog = (message, type = 'info') => {
    const timestamp = new Date().toLocaleTimeString();
    setTestLogs(prev => [...prev, { timestamp, message, type }]);
    console.log(`[${timestamp}] ${message}`);
  };

  // NEW: Test individual endpoints
  const testNewEndpoint = async (name, url, method = 'GET', body = null) => {
    addLog(`🔍 Testing NEW ${name}: ${method} ${url}`, 'info');
    try {
      const options = {
        method,
        headers: {
          'Content-Type': 'application/json'
        }
      };
      
      if (body) {
        options.body = JSON.stringify(body);
      }
      
      const response = await fetch(url, options);
      const isSuccess = response.ok;
      
      setTestResults(prev => ({
        ...prev,
        endpointTests: {
          ...prev.endpointTests,
          [name]: { success: isSuccess, status: response.status, url }
        }
      }));
      
      if (isSuccess) {
        addLog(`✅ ${name} endpoint working (${response.status})`, 'success');
        if (method === 'GET') {
          try {
            const data = await response.json();
            addLog(`📊 ${name} response data available`, 'info');
            return data;
          } catch (e) {
            addLog(`📄 ${name} returned non-JSON response`, 'info');
          }
        }
        return { success: true, status: response.status };
      } else {
        addLog(`❌ ${name} endpoint failed (${response.status})`, 'error');
        return { success: false, status: response.status };
      }
    } catch (error) {
      setTestResults(prev => ({
        ...prev,
        endpointTests: {
          ...prev.endpointTests,
          [name]: { success: false, error: error.message, url }
        }
      }));
      addLog(`❌ ${name} endpoint error: ${error.message}`, 'error');
      return { success: false, error: error.message };
    }
  };

  // NEW: Test the new streaming service health
  const testNewStreamingServiceHealth = async () => {
    addLog('🔍 Testing NEW FFmpeg streaming service health...', 'info');
    addLog(`📡 NEW Endpoint: ${NEW_ENDPOINTS.health}`, 'info');
    try {
      const response = await fetch(NEW_ENDPOINTS.health, {
        method: 'GET',
        headers: { 'Content-Type': 'application/json' }
      });
      
      if (response.ok) {
        const data = await response.json();
        addLog(`✅ NEW streaming service healthy!`, 'success');
        addLog(`📊 Service: ${data.service || 'unknown'}`, 'info');
        addLog(`⏱️ Uptime: ${data.uptime ? (data.uptime / 60).toFixed(1) + ' minutes' : 'unknown'}`, 'info');
        addLog(`🎥 Active Streams: ${data.activeStreams || 0}`, 'info');
        addLog(`⚙️ Active Jobs: ${data.activeJobs || 0}`, 'info');
        if (data.features) {
          addLog(`🎯 Features: ${data.features.join(', ')}`, 'info');
        }
        if (data.limits) {
          addLog(`📈 Max Concurrent Streams: ${data.limits.maxConcurrentStreams || 'unknown'}`, 'info');
        }
        return { success: true, data };
      } else {
        addLog(`❌ NEW streaming service unhealthy: HTTP ${response.status}`, 'error');
        return { success: false, status: response.status };
      }
    } catch (error) {
      addLog(`❌ NEW streaming service health check failed: ${error.message}`, 'error');
      return { success: false, error: error.message };
    }
  };

  // NEW: Test all endpoints of the new service
  const testAllNewEndpoints = async () => {
    addLog('🧪 Testing all NEW streaming service endpoints...', 'info');
    
    // Test Health endpoint
    await testNewEndpoint('Health', NEW_ENDPOINTS.health);
    
    // Test List Streams endpoint
    await testNewEndpoint('List Streams', NEW_ENDPOINTS.listStreams);
    
    // Test Process Jobs endpoint (with sample job)
    const sampleJob = {
      type: 'test',
      input: 'test-input',
      output: 'test-output'
    };
    await testNewEndpoint('Process Jobs', NEW_ENDPOINTS.processJobs, 'POST', sampleJob);
    
    addLog('✅ NEW endpoint testing complete!', 'success');
  };

  // NEW: Start a test stream using the new API
  const startNewTestStream = async () => {
    addLog('🚀 Starting test stream using NEW API...', 'info');
    if (!currentUser) {
      addLog('❌ No user logged in for test stream', 'error');
      return { success: false, error: 'No user logged in' };
    }

    try {
      const streamId = `test-stream-${Date.now()}`;
      const streamConfig = {
        streamId,
        eventId: testEventId,
        userId: currentUser.uid,
        quality: selectedQuality,
        options: {
          qualities: [
            {
              name: selectedQuality,
              width: streamingConfig.streamQualities[selectedQuality].resolution.split('x')[0],
              height: streamingConfig.streamQualities[selectedQuality].resolution.split('x')[1],
              bitrate: `${streamingConfig.streamQualities[selectedQuality].bitrate}k`,
              audioBitrate: `${streamingConfig.streamQualities[selectedQuality].audiobitrate}k`
            }
          ],
          uploadToGcs: false,
          enableRecording: true
        }
      };
      
      addLog(`🎬 Stream config: ${streamId}`, 'info');
      addLog(`📺 Quality: ${selectedQuality}`, 'info');
      addLog(`🎯 Event: ${testEventId}`, 'info');
      
      const response = await fetch(NEW_ENDPOINTS.startStream, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(streamConfig)
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const result = await response.json();
      setActiveTestStreamId(result.streamId);
      addLog(`✅ Test stream started successfully!`, 'success');
      addLog(`🆔 Stream ID: ${result.streamId}`, 'info');
      
      if (result.rtmpUrl) {
        addLog(`📡 RTMP URL: ${result.rtmpUrl}`, 'info');
      }
      
      if (result.masterPlaylistUrl) {
        addLog(`🎵 Master Playlist: ${result.masterPlaylistUrl}`, 'info');
      }
      
      return { success: true, streamId: result.streamId, result };
      
    } catch (error) {
      addLog(`❌ Failed to start test stream: ${error.message}`, 'error');
      return { success: false, error: error.message };
    }
  };

  // NEW: Stop test stream using the new API
  const stopNewTestStream = async () => {
    if (!activeTestStreamId) {
      addLog('⚠️ No active test stream to stop', 'warning');
      return { success: false, error: 'No active test stream' };
    }

    addLog(`🛑 Stopping test stream: ${activeTestStreamId}`, 'info');
    try {
      const response = await fetch(`${NEW_ENDPOINTS.stopStream}/${activeTestStreamId}/stop`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        }
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const result = await response.json();
      addLog(`✅ Test stream stopped successfully!`, 'success');
      
      if (result.duration) {
        addLog(`⏱️ Duration: ${result.duration}ms`, 'info');
      }
      
      setActiveTestStreamId(null);
      return { success: true, result };
      
    } catch (error) {
      addLog(`❌ Failed to stop test stream: ${error.message}`, 'error');
      return { success: false, error: error.message };
    }
  };

  // Enhanced test functions with better logging (legacy functions)
  const testRtmpHealth = async () => {
    addLog('🔍 Testing legacy RTMP service health...', 'info');
    addLog(`📡 Endpoint: ${rtmpService.healthUrl}`, 'info');
    try {
      const response = await fetch(rtmpService.healthUrl, {
        method: 'GET',
        headers: { 'Content-Type': 'application/json' }
      });
      
      if (response.ok) {
        const data = await response.json();
        addLog(`✅ RTMP service healthy!`, 'success');
        addLog(`📊 Service: ${data.service || 'unknown'}`, 'info');
        addLog(`⏱️ Uptime: ${data.uptime ? (data.uptime / 60).toFixed(1) + ' minutes' : 'unknown'}`, 'info');
        addLog(`🎥 Active Streams: ${data.activeStreams || 0}`, 'info');
        return { success: true, data };
      } else {
        addLog(`❌ RTMP service unhealthy: HTTP ${response.status}`, 'error');
        return { success: false, status: response.status };
      }
    } catch (error) {
      addLog(`❌ RTMP health check failed: ${error.message}`, 'error');
      return { success: false, error: error.message };
    }
  };

  const testServiceInitialization = async () => {
    addLog('🔧 Testing FFmpeg service initialization...', 'info');
    try {
      await ffmpegStreamingService.initialize();
      addLog('✅ FFmpeg streaming service initialized successfully', 'success');
      addLog('🔗 WebSocket connection attempted', 'info');
      return { success: true };
    } catch (error) {
      addLog(`❌ Service initialization failed: ${error.message}`, 'error');
      addLog('💡 This may indicate WebSocket connectivity issues', 'warning');
      return { success: false, error: error.message };
    }
  };

  const testStreamConnectivity = async () => {
    addLog('🌐 Testing stream connectivity using legacy method...', 'info');
    if (!currentUser) {
      addLog('❌ No user logged in for connectivity test', 'error');
      addLog('💡 Please log in to test streaming connectivity', 'warning');
      return { success: false, error: 'No user logged in' };
    }

    addLog(`👤 Testing as user: ${currentUser.displayName || currentUser.uid}`, 'info');
    addLog(`🎯 Event ID: ${testEventId}`, 'info');

    try {
      const result = await testStreamingConnectivity(testEventId);
      if (result.success) {
        addLog(`✅ Stream connectivity test passed!`, 'success');
        addLog(`📝 Result: ${result.message}`, 'info');
      } else {
        addLog(`❌ Stream connectivity test failed`, 'error');
        addLog(`📝 Reason: ${result.message}`, 'error');
        addLog('💡 Check network connectivity and service availability', 'warning');
      }
      return result;
    } catch (error) {
      addLog(`❌ Connectivity test error: ${error.message}`, 'error');
      return { success: false, error: error.message };
    }
  };

  const testStreamCapability = async () => {
    addLog('⚙️ Testing stream capability...', 'info');
    if (!currentUser) {
      addLog('❌ No user logged in for stream capability test', 'error');
      return { success: false, error: 'No user logged in' };
    }

    try {
      // Generate a test stream configuration
      addLog(`🎨 Generating ${selectedQuality} quality config...`, 'info');
      const config = streamingConfig.generateEventStreamConfig(testEventId, currentUser.uid, selectedQuality);
      
      // Log key configuration details
      addLog(`🔑 Stream ID: ${config.streamId}`, 'info');
      addLog(`🎥 Resolution: ${config.settings.video.width}x${config.settings.video.height}`, 'info');
      addLog(`📊 Bitrate: ${config.settings.video.bitrate}kbps`, 'info');
      addLog(`🎞️ FPS: ${config.settings.video.framerate}`, 'info');
      
      // Validate the configuration
      const validation = streamingConfig.validateStreamConfig(config);
      if (validation.isValid) {
        addLog('✅ Stream configuration is valid and ready', 'success');
        addLog('🚀 Ready to start streaming!', 'success');
        return { success: true, config, validation };
      } else {
        addLog(`❌ Stream configuration invalid`, 'error');
        validation.errors.forEach(error => addLog(`   • ${error}`, 'error'));
        return { success: false, errors: validation.errors };
      }
    } catch (error) {
      addLog(`❌ Stream capability test failed: ${error.message}`, 'error');
      return { success: false, error: error.message };
    }
  };

  const runAllTests = async () => {
    setIsRunningTests(true);
    setTestLogs([]);
    addLog('🚀 Starting comprehensive stream testing...', 'info');
    addLog(`🔧 Testing against NEW streaming service:`, 'info');
    addLog(`   • NEW Service: ffmpeg-streaming-service-3ibabnlfhq-uc.a.run.app`, 'info');
    addLog(`   • Legacy RTMP: rtmp-working-3ibabnlfhq-uc.a.run.app`, 'info');
    addLog('', 'info'); // Empty line for spacing
    
    const results = {};
    
    // Test 1: NEW Streaming Service Health
    addLog('🗺 Step 1/8: NEW Streaming Service Health Check', 'info');
    results.newStreamingServiceHealth = await testNewStreamingServiceHealth();
    addLog('', 'info');
    
    // Test 2: NEW Streaming Service Endpoints
    addLog('🗺 Step 2/8: NEW Streaming Service Endpoints', 'info');
    await testAllNewEndpoints();
    addLog('', 'info');
    
    // Test 3: Legacy RTMP Health  
    addLog('🗺 Step 3/8: Legacy RTMP Service Health Check', 'info');
    results.rtmpHealth = await testRtmpHealth();
    addLog('', 'info');
    
    // Test 4: Service Initialization
    addLog('🗺 Step 4/8: Service Initialization', 'info');
    results.serviceInitialization = await testServiceInitialization();
    addLog('', 'info');
    
    // Test 5: Stream Connectivity (Legacy)
    addLog('🗺 Step 5/8: Legacy Stream Connectivity', 'info');
    results.rtmpConnectivity = await testStreamConnectivity();
    addLog('', 'info');
    
    // Test 6: Stream Capability
    addLog('🗺 Step 6/8: Stream Capability', 'info');
    results.streamCapability = await testStreamCapability();
    addLog('', 'info');
    
    // Test 7: NEW API Stream Test
    addLog('🗺 Step 7/8: NEW API Stream Start/Stop Test', 'info');
    const startResult = await startNewTestStream();
    if (startResult.success) {
      addLog('⏳ Waiting 3 seconds before stopping...', 'info');
      await new Promise(resolve => setTimeout(resolve, 3000));
      const stopResult = await stopNewTestStream();
      results.newStreamingServiceConnectivity = { 
        success: startResult.success && stopResult.success,
        startResult,
        stopResult
      };
    } else {
      results.newStreamingServiceConnectivity = startResult;
    }
    addLog('', 'info');
    
    // Test 8: Summary
    addLog('🗺 Step 8/8: Test Summary', 'info');
    
    setTestResults(results);
    
    // Summary
    const coreTests = ['newStreamingServiceHealth', 'serviceInitialization', 'streamCapability', 'newStreamingServiceConnectivity'];
    const passed = coreTests.filter(key => results[key]?.success).length;
    const total = coreTests.length;
    
    addLog('📊 TEST SUMMARY', 'info');
    addLog('='.repeat(50), 'info');
    
    if (passed === total) {
      addLog(`🎉 ALL CORE TESTS PASSED! (${passed}/${total})`, 'success');
      addLog('✅ Your NEW streaming infrastructure is ready!', 'success');
      addLog('🚀 You can now start streaming with confidence', 'success');
    } else {
      addLog(`⚠️ ${passed}/${total} core tests passed`, 'warning');
      addLog('🔍 Check the failed tests above for details', 'warning');
      
      // Provide specific guidance based on failures
      if (!results.newStreamingServiceHealth?.success) {
        addLog('💡 NEW streaming service is down - streaming will not work', 'error');
      }
      if (!results.serviceInitialization?.success) {
        addLog('💡 Service initialization failed - check WebSocket connectivity', 'error');
      }
      if (!results.newStreamingServiceConnectivity?.success) {
        addLog('💡 NEW API streaming test failed - check stream start/stop functionality', 'error');
      }
    }
    
    setIsRunningTests(false);
  };

  const runQuickTest = async () => {
    setIsRunningTests(true);
    setTestLogs([]);
    addLog('⚡ Running quick health check...', 'info');
    addLog('📊 Checking NEW streaming service availability', 'info');
    addLog('', 'info');
    
    const results = {};
    results.newStreamingServiceHealth = await testNewStreamingServiceHealth();
    addLog('', 'info');
    
    setTestResults(results);
    
    if (results.newStreamingServiceHealth?.success) {
      addLog('🎉 Quick test complete: NEW streaming service is healthy!', 'success');
      addLog('✅ NEW streaming infrastructure is operational', 'success');
    } else {
      addLog('⚠️ Quick test complete: NEW streaming service unavailable', 'warning');
      addLog('🔍 Run comprehensive tests for detailed analysis', 'warning');
    }
    
    setIsRunningTests(false);
  };

  const clearTests = () => {
    setTestResults({
      newStreamingServiceHealth: null,
      newStreamingServiceConnectivity: null,
      rtmpHealth: null,
      ffmpegHealth: null,
      rtmpConnectivity: null,
      ffmpegConnectivity: null,
      streamCapability: null,
      serviceInitialization: null,
      endpointTests: {}
    });
    setTestLogs([]);
    setStreamStats(null);
    setActiveTestStreamId(null);
  };

  const getTestResultIcon = (result) => {
    if (result === null) return <AlertCircle className="text-gray-400" size={20} />;
    if (result.success) return <CheckCircle className="text-green-500" size={20} />;
    return <XCircle className="text-red-500" size={20} />;
  };

  const getTestResultColor = (result) => {
    if (result === null) return 'text-gray-500';
    if (result.success) return 'text-green-600';
    return 'text-red-600';
  };

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-6xl mx-auto px-6">
        {/* Header */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold text-gray-900">NEW Stream Services Test Center</h1>
              <p className="text-gray-600 mt-1">Test NEW Google Cloud Run FFmpeg streaming service</p>
            </div>
            <div className="flex items-center gap-3">
              <div className={`flex items-center gap-2 px-3 py-1 rounded-full text-sm ${
                streamingServiceReady ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
              }`}>
                {streamingServiceReady ? <Wifi size={16} /> : <WifiOff size={16} />}
                {streamingServiceReady ? 'Services Ready' : 'Services Not Ready'}
              </div>
            </div>
          </div>
        </div>

        {/* NEW Service Endpoints */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
            <Cloud size={20} />
            NEW Streaming Service Endpoints
          </h2>
          <div className="bg-blue-50 p-4 rounded-lg mb-4">
            <h3 className="font-medium text-blue-900 mb-2">NEW FFmpeg Streaming Service</h3>
            <div className="text-sm text-blue-700 space-y-1">
              <div><strong>Base:</strong> {ffmpegService.baseUrl}</div>
              <div><strong>API:</strong> {ffmpegService.apiUrl}</div>
              <div><strong>WebSocket:</strong> {ffmpegService.websocketUrl}</div>
              <div><strong>Health:</strong> <a href={ffmpegService.healthUrl} target="_blank" rel="noopener noreferrer" className="underline hover:text-blue-900">{ffmpegService.healthUrl}</a></div>
            </div>
          </div>
          
          {/* NEW Endpoint Status Grid */}
          <div className="grid md:grid-cols-3 gap-3">
            {Object.entries(NEW_ENDPOINTS).map(([name, url]) => {
              const test = testResults.endpointTests[name];
              return (
                <div key={name} className="bg-gray-50 p-3 rounded border">
                  <div className="flex items-center justify-between mb-1">
                    <span className="font-medium text-sm">{name}</span>
                    {test && (
                      <span className={`${test.success ? 'text-green-500' : 'text-red-500'}`}>
                        {test.success ? <CheckCircle size={14} /> : <XCircle size={14} />}
                      </span>
                    )}
                  </div>
                  <div className="text-xs text-gray-600 truncate">{url}</div>
                  {test && !test.success && test.error && (
                    <div className="text-xs text-red-600 mt-1">{test.error}</div>
                  )}
                </div>
              );
            })}
          </div>
          
          {/* Legacy Services for comparison */}
          <div className="mt-4 pt-4 border-t">
            <h4 className="font-medium text-gray-900 mb-2">Legacy Services (for comparison):</h4>
            <div className="grid md:grid-cols-1 gap-4">
              <div className="bg-orange-50 p-3 rounded-lg">
                <h5 className="font-medium text-orange-900">Legacy RTMP Service</h5>
                <div className="text-sm text-orange-700 mt-1">
                  <div><strong>Health:</strong> <a href={rtmpService.healthUrl} target="_blank" rel="noopener noreferrer" className="underline">{rtmpService.healthUrl}</a></div>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Test Controls */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
            <Play size={20} />
            Test Controls
          </h2>
          
          {/* Test Configuration */}
          <div className="grid md:grid-cols-3 gap-4 mb-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Test Mode</label>
              <select 
                value={testMode} 
                onChange={(e) => setTestMode(e.target.value)}
                className="w-full p-2 border border-gray-300 rounded-lg"
              >
                <option value="simple">Quick Health Check</option>
                <option value="comprehensive">Comprehensive Testing</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Stream Quality</label>
              <select 
                value={selectedQuality} 
                onChange={(e) => setSelectedQuality(e.target.value)}
                className="w-full p-2 border border-gray-300 rounded-lg"
              >
                <option value="low">Low (640x360)</option>
                <option value="medium">Medium (1280x720)</option>
                <option value="high">High (1920x1080)</option>
                <option value="ultra">Ultra (2560x1440)</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Test Event ID</label>
              <input 
                type="text" 
                value={testEventId} 
                onChange={(e) => setTestEventId(e.target.value)}
                className="w-full p-2 border border-gray-300 rounded-lg"
                placeholder="test_event_stream"
              />
            </div>
          </div>

          {/* Action Buttons */}
          <div className="flex gap-3 flex-wrap">
            <button
              onClick={testMode === 'simple' ? runQuickTest : runAllTests}
              disabled={isRunningTests}
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
            >
              {isRunningTests ? <RefreshCw size={16} className="animate-spin" /> : <Play size={16} />}
              {isRunningTests ? 'Running...' : (testMode === 'simple' ? 'Quick Test' : 'Run All Tests')}
            </button>
            
            <button
              onClick={clearTests}
              className="flex items-center gap-2 px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700"
            >
              <Square size={16} />
              Clear Results
            </button>

            <button
              onClick={activeTestStreamId ? stopNewTestStream : startNewTestStream}
              disabled={!currentUser || isRunningTests}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg text-white ${
                activeTestStreamId 
                  ? 'bg-red-600 hover:bg-red-700' 
                  : 'bg-green-600 hover:bg-green-700'
              } disabled:opacity-50`}
            >
              {activeTestStreamId ? <Square size={16} /> : <Play size={16} />}
              {activeTestStreamId ? 'Stop Test Stream' : 'Start Test Stream'}
            </button>

            {currentUser && (
              <div className="flex items-center gap-2 text-sm text-gray-600">
                <span>User:</span>
                <span className="font-medium">{currentUser.displayName || currentUser.uid}</span>
              </div>
            )}
          </div>

          {activeTestStreamId && (
            <div className="mt-3 p-3 bg-green-50 border border-green-200 rounded-lg">
              <div className="text-green-800 text-sm">
                <strong>Active Test Stream:</strong> {activeTestStreamId}
              </div>
            </div>
          )}
        </div>

        {/* Test Results */}
        <div className="grid md:grid-cols-2 gap-6 mb-6">
          {/* Results Grid */}
          <div className="bg-white rounded-lg shadow-sm p-6">
            <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <Activity size={20} />
              Test Results
            </h2>
            
            <div className="space-y-3">
              <div className="flex items-center justify-between p-3 bg-blue-50 rounded-lg">
                <span className="font-medium">NEW Streaming Service Health</span>
                <div className="flex items-center gap-2">
                  {getTestResultIcon(testResults.newStreamingServiceHealth)}
                  <span className={getTestResultColor(testResults.newStreamingServiceHealth)}>
                    {testResults.newStreamingServiceHealth ? (testResults.newStreamingServiceHealth.success ? 'Healthy' : 'Unhealthy') : 'Not Tested'}
                  </span>
                </div>
              </div>

              <div className="flex items-center justify-between p-3 bg-blue-50 rounded-lg">
                <span className="font-medium">NEW API Stream Test</span>
                <div className="flex items-center gap-2">
                  {getTestResultIcon(testResults.newStreamingServiceConnectivity)}
                  <span className={getTestResultColor(testResults.newStreamingServiceConnectivity)}>
                    {testResults.newStreamingServiceConnectivity ? (testResults.newStreamingServiceConnectivity.success ? 'Working' : 'Failed') : 'Not Tested'}
                  </span>
                </div>
              </div>

              <div className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                <span className="font-medium">Legacy RTMP Service Health</span>
                <div className="flex items-center gap-2">
                  {getTestResultIcon(testResults.rtmpHealth)}
                  <span className={getTestResultColor(testResults.rtmpHealth)}>
                    {testResults.rtmpHealth ? (testResults.rtmpHealth.success ? 'Healthy' : 'Unhealthy') : 'Not Tested'}
                  </span>
                </div>
              </div>

              {testMode === 'comprehensive' && (
                <>
                  <div className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                    <span className="font-medium">Service Initialization</span>
                    <div className="flex items-center gap-2">
                      {getTestResultIcon(testResults.serviceInitialization)}
                      <span className={getTestResultColor(testResults.serviceInitialization)}>
                        {testResults.serviceInitialization ? (testResults.serviceInitialization.success ? 'Initialized' : 'Failed') : 'Not Tested'}
                      </span>
                    </div>
                  </div>

                  <div className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                    <span className="font-medium">Legacy Stream Connectivity</span>
                    <div className="flex items-center gap-2">
                      {getTestResultIcon(testResults.rtmpConnectivity)}
                      <span className={getTestResultColor(testResults.rtmpConnectivity)}>
                        {testResults.rtmpConnectivity ? (testResults.rtmpConnectivity.success ? 'Connected' : 'Failed') : 'Not Tested'}
                      </span>
                    </div>
                  </div>

                  <div className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                    <span className="font-medium">Stream Capability</span>
                    <div className="flex items-center gap-2">
                      {getTestResultIcon(testResults.streamCapability)}
                      <span className={getTestResultColor(testResults.streamCapability)}>
                        {testResults.streamCapability ? (testResults.streamCapability.success ? 'Ready' : 'Not Ready') : 'Not Tested'}
                      </span>
                    </div>
                  </div>
                </>
              )}
            </div>
          </div>

          {/* Test Logs */}
          <div className="bg-white rounded-lg shadow-sm p-6">
            <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <Monitor size={20} />
              Test Logs
            </h2>
            
            <div className="bg-black text-green-400 p-4 rounded-lg font-mono text-sm h-80 overflow-y-auto">
              {testLogs.length === 0 ? (
                <div className="text-gray-500">No tests run yet. Click a test button to start.</div>
              ) : (
                testLogs.map((log, index) => (
                  <div key={index} className={`mb-1 ${
                    log.type === 'error' ? 'text-red-400' : 
                    log.type === 'success' ? 'text-green-400' : 
                    log.type === 'warning' ? 'text-yellow-400' : 'text-white'
                  }`}>
                    <span className="text-gray-500">[{log.timestamp}]</span> {log.message}
                  </div>
                ))
              )}
            </div>
          </div>
        </div>

        {/* Stream Quality Info */}
        <div className="bg-white rounded-lg shadow-sm p-6">
          <h2 className="text-lg font-semibold mb-4">Available Stream Qualities</h2>
          <div className="grid md:grid-cols-4 gap-4">
            {Object.entries(streamingConfig.streamQualities).map(([quality, settings]) => (
              <div key={quality} className={`p-4 rounded-lg border-2 ${
                selectedQuality === quality ? 'border-blue-500 bg-blue-50' : 'border-gray-200'
              }`}>
                <h3 className="font-medium capitalize mb-2">{quality}</h3>
                <div className="text-sm text-gray-600 space-y-1">
                  <div>Resolution: {settings.resolution}</div>
                  <div>Bitrate: {settings.bitrate}kbps</div>
                  <div>FPS: {settings.framerate}</div>
                  <div>Audio: {settings.audiobitrate}kbps</div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Error Display */}
        {streamingError && (
          <div className="bg-red-50 border border-red-200 rounded-lg p-4 mt-6">
            <div className="flex items-center gap-2 text-red-800">
              <XCircle size={20} />
              <span className="font-medium">Streaming Service Error:</span>
            </div>
            <p className="text-red-700 mt-1">{streamingError}</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default StreamTestPage;