import React, { useState, useEffect } from 'react';
import { 
  getFirestore, 
  collection, 
  query, 
  where, 
  getDocs,
  doc,
  updateDoc,
  getDoc,
  setDoc
} from 'firebase/firestore';
import { 
  Building2, 
  UserPlus, 
  Search,
  Edit,
  Trash2,
  Check,
  X,
  Users
} from 'lucide-react';
import './VenueUserManagement.css';

const VenueUserManagement = () => {
  const [users, setUsers] = useState([]);
  const [venueUsers, setVenueUsers] = useState([]);
  const [venues, setVenues] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);
  const [selectedVenue, setSelectedVenue] = useState('');

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const db = getFirestore();
      
      // Load all users
      const usersQuery = query(collection(db, 'users'));
      const usersSnapshot = await getDocs(usersQuery);
      const allUsers = usersSnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setUsers(allUsers);
      
      // Filter venue users
      const venueUsersList = allUsers.filter(user => user.isVenueUser === true);
      setVenueUsers(venueUsersList);
      
      // Load venues
      const venuesDoc = await getDoc(doc(db, 'admin', 'venues'));
      if (venuesDoc.exists()) {
        setVenues(venuesDoc.data().venues || []);
      }
      
      setLoading(false);
    } catch (error) {
      console.error('Error loading data:', error);
      setLoading(false);
    }
  };

  const grantVenueAccess = async () => {
    if (!selectedUser || !selectedVenue) return;
    
    try {
      const db = getFirestore();
      const userRef = doc(db, 'users', selectedUser.id);
      
      await updateDoc(userRef, {
        isVenueUser: true,
        venueId: selectedVenue,
        venueGrantedAt: new Date()
      });
      
      alert('Venue access granted successfully');
      setShowAddModal(false);
      setSelectedUser(null);
      setSelectedVenue('');
      loadData();
    } catch (error) {
      console.error('Error granting venue access:', error);
      alert('Failed to grant venue access');
    }
  };

  const revokeVenueAccess = async (userId) => {
    if (!confirm('Are you sure you want to revoke venue access for this user?')) return;
    
    try {
      const db = getFirestore();
      const userRef = doc(db, 'users', userId);
      
      await updateDoc(userRef, {
        isVenueUser: false,
        venueId: null,
        venueRevokedAt: new Date()
      });
      
      alert('Venue access revoked successfully');
      loadData();
    } catch (error) {
      console.error('Error revoking venue access:', error);
      alert('Failed to revoke venue access');
    }
  };

  const filteredUsers = users.filter(user => 
    !user.isVenueUser && (
      user.displayName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.email?.toLowerCase().includes(searchTerm.toLowerCase())
    )
  );

  if (loading) {
    return (
      <div className="venue-management-loading">
        <div className="loading-spinner"></div>
        <p>Loading venue users...</p>
      </div>
    );
  }

  return (
    <div className="venue-user-management">
      <div className="management-header">
        <div className="header-content">
          <Building2 size={28} />
          <div>
            <h2>Venue User Management</h2>
            <p>Grant and manage venue portal access for users</p>
          </div>
        </div>
        
        <button 
          className="add-venue-user-button"
          onClick={() => setShowAddModal(true)}
        >
          <UserPlus size={16} />
          Add Venue User
        </button>
      </div>

      <div className="stats-row">
        <div className="stat-card">
          <Building2 size={20} />
          <div>
            <h4>{venues.length}</h4>
            <p>Total Venues</p>
          </div>
        </div>
        <div className="stat-card">
          <Users size={20} />
          <div>
            <h4>{venueUsers.length}</h4>
            <p>Venue Users</p>
          </div>
        </div>
      </div>

      <div className="venue-users-table">
        <h3>Current Venue Users</h3>
        <div className="table-container">
          <table>
            <thead>
              <tr>
                <th>User</th>
                <th>Email</th>
                <th>Venue</th>
                <th>Granted Date</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {venueUsers.length === 0 ? (
                <tr>
                  <td colSpan="5" className="empty-state">
                    No venue users configured yet
                  </td>
                </tr>
              ) : (
                venueUsers.map(user => {
                  const venue = venues.find(v => v.id === user.venueId);
                  return (
                    <tr key={user.id}>
                      <td>{user.displayName || 'Unknown User'}</td>
                      <td>{user.email || 'No email'}</td>
                      <td>{venue?.name || 'Unknown Venue'}</td>
                      <td>{user.venueGrantedAt ? new Date(user.venueGrantedAt.seconds ? user.venueGrantedAt.seconds * 1000 : user.venueGrantedAt).toLocaleDateString() : 'N/A'}</td>
                      <td>
                        <button 
                          className="action-button delete"
                          onClick={() => revokeVenueAccess(user.id)}
                        >
                          <Trash2 size={14} />
                          Revoke Access
                        </button>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {showAddModal && (
        <div className="add-modal">
          <div className="modal-content">
            <div className="modal-header">
              <h3>Grant Venue Access</h3>
              <button onClick={() => setShowAddModal(false)}>
                <X size={20} />
              </button>
            </div>
            
            <div className="modal-body">
              <div className="form-group">
                <label>Select Venue</label>
                <select 
                  value={selectedVenue}
                  onChange={(e) => setSelectedVenue(e.target.value)}
                >
                  <option value="">Choose a venue...</option>
                  {venues.map(venue => (
                    <option key={venue.id} value={venue.id}>
                      {venue.name}
                    </option>
                  ))}
                </select>
              </div>
              
              <div className="form-group">
                <label>Search Users</label>
                <div className="search-box">
                  <Search size={16} />
                  <input
                    type="text"
                    placeholder="Search by name or email..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                  />
                </div>
              </div>
              
              <div className="users-list">
                {filteredUsers.map(user => (
                  <div 
                    key={user.id}
                    className={`user-item ${selectedUser?.id === user.id ? 'selected' : ''}`}
                    onClick={() => setSelectedUser(user)}
                  >
                    <div className="user-info">
                      <h4>{user.displayName || 'Unknown User'}</h4>
                      <p>{user.email || 'No email'}</p>
                    </div>
                    {selectedUser?.id === user.id && <Check size={16} />}
                  </div>
                ))}
              </div>
            </div>
            
            <div className="modal-footer">
              <button 
                className="cancel-button"
                onClick={() => setShowAddModal(false)}
              >
                Cancel
              </button>
              <button 
                className="confirm-button"
                onClick={grantVenueAccess}
                disabled={!selectedUser || !selectedVenue}
              >
                Grant Access
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default VenueUserManagement;