// src/admin/components/ActiveStreamsDisplay.jsx
import React, { useState, useEffect } from 'react';
import { 
  Video, 
  Users, 
  RefreshCw, 
  AlertCircle, 
  PlayCircle, 
  StopCircle,
  Monitor,
  Clock,
  Activity,
  ExternalLink,
  Zap
} from 'lucide-react';

const ActiveStreamsDisplay = () => {
  const [streams, setStreams] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastUpdate, setLastUpdate] = useState(null);
  const [autoRefresh, setAutoRefresh] = useState(true);

  const fetchActiveStreams = async () => {
    try {
      setError(null);
      const response = await fetch('https://talkstudio-2c55dh9q.livekit.cloud/api/streams');
      
      if (!response.ok) {
        throw new Error(`Failed to fetch streams: ${response.status} ${response.statusText}`);
      }
      
      const data = await response.json();
      setStreams(data);
      setLastUpdate(new Date());
    } catch (err) {
      console.error('Error fetching active streams:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchActiveStreams();
    
    let interval;
    if (autoRefresh) {
      interval = setInterval(fetchActiveStreams, 10000); // Refresh every 10 seconds
    }
    
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [autoRefresh]);

  const getStreamStatus = (stream) => {
    if (!stream) return 'unknown';
    
    const hasActiveProducers = stream.producers && 
                              Array.isArray(stream.producers) && 
                              stream.producers.length > 0 &&
                              stream.producers.some(p => p.url && p.url !== '[]');
    
    const hasActiveConsumers = stream.consumers && 
                              Array.isArray(stream.consumers) && 
                              stream.consumers.length > 0;
    
    if (hasActiveProducers && hasActiveConsumers) return 'active_full';
    if (hasActiveProducers) return 'broadcasting';
    if (hasActiveConsumers) return 'consuming_only';
    return 'inactive';
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'active_full': return '#10b981'; // Green
      case 'broadcasting': return '#3b82f6'; // Blue
      case 'consuming_only': return '#f59e0b'; // Orange
      case 'inactive': return '#6b7280'; // Gray
      default: return '#ef4444'; // Red
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'active_full': return <Activity size={16} />;
      case 'broadcasting': return <PlayCircle size={16} />;
      case 'consuming_only': return <Users size={16} />;
      case 'inactive': return <StopCircle size={16} />;
      default: return <AlertCircle size={16} />;
    }
  };

  const getStatusLabel = (status) => {
    switch (status) {
      case 'active_full': return 'Active (Full)';
      case 'broadcasting': return 'Broadcasting';
      case 'consuming_only': return 'Viewers Only';
      case 'inactive': return 'Inactive';
      default: return 'Unknown';
    }
  };

  const parseProducerUrl = (url) => {
    if (!url || url === '[]') return null;
    
    try {
      // Handle ffmpeg URLs
      if (url.startsWith('ffmpeg:')) {
        const parts = url.split('#');
        const sourceUrl = parts[0].replace('ffmpeg:', '');
        const params = parts.slice(1).reduce((acc, part) => {
          const [key, value] = part.split('=');
          acc[key] = value;
          return acc;
        }, {});
        
        return {
          type: 'ffmpeg',
          source: sourceUrl,
          video: params.video,
          audio: params.audio
        };
      }
      
      // Handle direct URLs
      return {
        type: 'direct',
        source: url
      };
    } catch (e) {
      return { type: 'unknown', source: url };
    }
  };

  const activeStreams = Object.entries(streams).filter(([_, stream]) => {
    const status = getStreamStatus(stream);
    return status === 'active_full' || status === 'broadcasting';
  });

  const inactiveStreams = Object.entries(streams).filter(([_, stream]) => {
    const status = getStreamStatus(stream);
    return status === 'inactive' || status === 'consuming_only';
  });

  return (
    <div className="active-streams-display">
      {/* Header */}
      <div className="flex justify-between items-center mb-6">
        <div className="flex items-center">
          <Monitor className="mr-2" size={24} />
          <div>
            <h2 className="text-xl font-bold">Active Streams</h2>
            <p className="text-sm text-gray-600">
              Real-time streaming status from talkstudio-2c55dh9q.livekit.cloud
            </p>
          </div>
        </div>
        
        <div className="flex items-center gap-3">
          <label className="flex items-center text-sm">
            <input
              type="checkbox"
              checked={autoRefresh}
              onChange={(e) => setAutoRefresh(e.target.checked)}
              className="mr-2"
            />
            Auto-refresh
          </label>
          
          <button
            onClick={fetchActiveStreams}
            disabled={loading}
            className="flex items-center px-3 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:opacity-50"
          >
            <RefreshCw size={16} className={`mr-2 ${loading ? 'animate-spin' : ''}`} />
            Refresh
          </button>
        </div>
      </div>

      {/* Status Bar */}
      <div className="bg-gray-100 rounded-lg p-4 mb-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center">
            <Clock size={16} className="mr-2 text-gray-500" />
            <span className="text-sm text-gray-600">
              Last updated: {lastUpdate ? lastUpdate.toLocaleTimeString() : 'Never'}
            </span>
          </div>
          
          <div className="flex items-center gap-4">
            <div className="flex items-center">
              <div className="w-3 h-3 bg-green-500 rounded-full mr-2"></div>
              <span className="text-sm">{activeStreams.length} Active</span>
            </div>
            <div className="flex items-center">
              <div className="w-3 h-3 bg-gray-400 rounded-full mr-2"></div>
              <span className="text-sm">{inactiveStreams.length} Inactive</span>
            </div>
            <div className="flex items-center">
              <div className="w-3 h-3 bg-blue-500 rounded-full mr-2"></div>
              <span className="text-sm">{Object.keys(streams).length} Total</span>
            </div>
          </div>
        </div>
      </div>

      {/* Error Display */}
      {error && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6">
          <div className="flex items-center text-red-700">
            <AlertCircle size={16} className="mr-2" />
            <span className="font-medium">Error fetching streams</span>
          </div>
          <p className="text-sm text-red-600 mt-1">{error}</p>
        </div>
      )}

      {/* Loading State */}
      {loading && Object.keys(streams).length === 0 && (
        <div className="text-center py-8">
          <RefreshCw size={32} className="animate-spin mx-auto mb-4 text-gray-400" />
          <p className="text-gray-600">Loading active streams...</p>
        </div>
      )}

      {/* Active Streams Section */}
      {activeStreams.length > 0 && (
        <div className="mb-8">
          <h3 className="text-lg font-semibold mb-4 flex items-center">
            <Zap size={18} className="mr-2 text-green-500" />
            Active Streams ({activeStreams.length})
          </h3>
          
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {activeStreams.map(([streamId, stream]) => {
              const status = getStreamStatus(stream);
              const statusColor = getStatusColor(status);
              
              return (
                <div key={streamId} className="bg-white rounded-lg border border-gray-200 overflow-hidden">
                  {/* Stream Header */}
                  <div className="p-4 border-b border-gray-100">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center">
                        <Video size={18} className="mr-2 text-gray-600" />
                        <h4 className="font-medium truncate">{streamId}</h4>
                      </div>
                      
                      <div 
                        className="flex items-center px-2 py-1 rounded-full text-xs font-medium text-white"
                        style={{ backgroundColor: statusColor }}
                      >
                        {getStatusIcon(status)}
                        <span className="ml-1">{getStatusLabel(status)}</span>
                      </div>
                    </div>
                  </div>
                  
                  {/* Stream Details */}
                  <div className="p-4">
                    {/* Producers */}
                    {stream.producers && stream.producers.length > 0 && (
                      <div className="mb-3">
                        <h5 className="text-sm font-medium text-gray-700 mb-2">
                          Producers ({stream.producers.length})
                        </h5>
                        {stream.producers.map((producer, index) => {
                          const parsedUrl = parseProducerUrl(producer.url);
                          
                          return (
                            <div key={index} className="text-xs bg-gray-50 rounded p-2 mb-1">
                              {parsedUrl ? (
                                <div>
                                  <div className="flex items-center justify-between">
                                    <span className="font-medium capitalize">{parsedUrl.type}</span>
                                    {parsedUrl.source && parsedUrl.source.startsWith('http') && (
                                      <a 
                                        href={parsedUrl.source} 
                                        target="_blank" 
                                        rel="noopener noreferrer"
                                        className="text-blue-600 hover:text-blue-800"
                                      >
                                        <ExternalLink size={12} />
                                      </a>
                                    )}
                                  </div>
                                  <div className="text-gray-600 truncate">{parsedUrl.source}</div>
                                  {parsedUrl.video && (
                                    <div className="text-gray-500">Video: {parsedUrl.video}</div>
                                  )}
                                  {parsedUrl.audio && (
                                    <div className="text-gray-500">Audio: {parsedUrl.audio}</div>
                                  )}
                                </div>
                              ) : (
                                <div className="text-gray-500">No active producer</div>
                              )}
                            </div>
                          );
                        })}
                      </div>
                    )}
                    
                    {/* Consumers */}
                    {stream.consumers && stream.consumers.length > 0 && (
                      <div>
                        <h5 className="text-sm font-medium text-gray-700 mb-2">
                          Consumers ({stream.consumers.length})
                        </h5>
                        <div className="text-xs bg-gray-50 rounded p-2">
                          {stream.consumers.length} active viewer{stream.consumers.length !== 1 ? 's' : ''}
                        </div>
                      </div>
                    )}
                    
                    {/* No Active Content */}
                    {(!stream.producers || stream.producers.length === 0) && 
                     (!stream.consumers || stream.consumers.length === 0) && (
                      <div className="text-center text-gray-500 text-sm py-4">
                        No active producers or consumers
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Inactive Streams Section */}
      {inactiveStreams.length > 0 && (
        <div>
          <h3 className="text-lg font-semibold mb-4 flex items-center">
            <StopCircle size={18} className="mr-2 text-gray-400" />
            Inactive Streams ({inactiveStreams.length})
          </h3>
          
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
            {inactiveStreams.map(([streamId, stream]) => {
              const status = getStreamStatus(stream);
              const statusColor = getStatusColor(status);
              
              return (
                <div key={streamId} className="bg-gray-50 rounded-lg border border-gray-200 p-3">
                  <div className="flex items-center justify-between">
                    <span className="text-sm font-medium text-gray-700 truncate">
                      {streamId}
                    </span>
                    <div 
                      className="flex items-center px-2 py-1 rounded-full text-xs font-medium text-white"
                      style={{ backgroundColor: statusColor }}
                    >
                      {getStatusIcon(status)}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Empty State */}
      {!loading && Object.keys(streams).length === 0 && (
        <div className="text-center py-12">
          <Monitor size={48} className="mx-auto mb-4 text-gray-300" />
          <h3 className="text-lg font-medium text-gray-700 mb-2">No streams found</h3>
          <p className="text-gray-500">No active or inactive streams detected on the server.</p>
        </div>
      )}
    </div>
  );
};

export default ActiveStreamsDisplay;
