import { WalletService } from './walletService';

class TipService {
  constructor() {
    this.tipSettings = {
      creatorPercentage: 50,
      platformPercentage: 30,
      venuePercentage: 20,
      minimumTip: 1.00
    };
  }

  // Get current tip settings
  getTipSettings() {
    const stored = localStorage.getItem('tipSettings');
    if (stored) {
      this.tipSettings = { ...this.tipSettings, ...JSON.parse(stored) };
    }
    return this.tipSettings;
  }

  // Update tip settings (admin only)
  updateTipSettings(newSettings) {
    this.tipSettings = { ...this.tipSettings, ...newSettings };
    localStorage.setItem('tipSettings', JSON.stringify(this.tipSettings));
    return this.tipSettings;
  }

  // Calculate revenue splits (for display purposes)
  calculateRevenueSplits(amount) {
    const settings = this.getTipSettings();
    
    const creatorAmount = (amount * settings.creatorPercentage) / 100;
    const platformAmount = (amount * settings.platformPercentage) / 100;
    const venueAmount = (amount * settings.venuePercentage) / 100;
    
    // Ensure total adds up to original amount (handle rounding)
    const total = creatorAmount + platformAmount + venueAmount;
    const difference = amount - total;
    
    return {
      creator: creatorAmount + difference, // Add any rounding difference to creator
      platform: platformAmount,
      venue: venueAmount,
      total: amount
    };
  }

  // Process a tip transaction using WalletService
  async processTip({ eventId, creatorId, amount, tipperId, venueId = null }) {
    try {
      if (amount < this.tipSettings.minimumTip) {
        return {
          success: false,
          message: `Minimum tip amount is $${this.tipSettings.minimumTip}`
        };
      }

      // Use WalletService to process the tip with splits
      const result = await WalletService.processTipWithSplits(
        tipperId,
        creatorId,
        amount,
        '', // message
        null, // streamId
        eventId,
        venueId
      );

      return {
        success: true,
        transaction: result,
        message: 'Tip sent successfully!'
      };

    } catch (error) {
      console.error('Tip processing error:', error);
      return {
        success: false,
        message: error.message || 'Failed to process tip'
      };
    }
  }

  // Get tip statistics (basic local stats for admin panel display)
  getTipStats(timeframe = 'all') {
    // For now, return mock data since WalletService handles the real stats
    // In a full implementation, you'd query Firebase for real statistics
    return {
      totalAmount: 0,
      totalTips: 0,
      averageTip: 0,
      platformRevenue: 0,
      transactions: []
    };
  }

  // Validate tip settings
  validateTipSettings(settings) {
    const total = settings.creatorPercentage + settings.platformPercentage + settings.venuePercentage;
    
    if (Math.abs(total - 100) > 0.01) { // Allow for small floating point differences
      return {
        valid: false,
        message: 'Percentages must add up to 100%'
      };
    }

    if (settings.minimumTip <= 0) {
      return {
        valid: false,
        message: 'Minimum tip must be greater than 0'
      };
    }

    return { valid: true };
  }

  // Get recent tip activities (simplified for demo)
  getRecentTipActivities(limit = 10) {
    // In a full implementation, this would query Firebase
    return [];
  }

  // Store tip transaction (handled by WalletService)
  storeTipTransaction(transaction) {
    // This is now handled by WalletService in Firebase
    // Keeping this method for backwards compatibility
    console.log('Tip transaction stored via WalletService:', transaction);
  }

  // Get tip transactions (would query Firebase in full implementation)
  getTipTransactions() {
    // This would query Firebase walletTransactions collection
    return [];
  }

  // Get tip transactions for a specific event
  getEventTips(eventId) {
    // This would query Firebase tips collection filtered by eventId
    return [];
  }

  // Get tip transactions for a specific creator
  getCreatorTips(creatorId) {
    // This would query Firebase tips collection filtered by recipientId
    return [];
  }

  // Record tip activity (handled by WalletService)
  recordTipActivity(activity) {
    // This is now handled by WalletService in Firebase
    console.log('Tip activity recorded via WalletService:', activity);
  }
}

export const tipService = new TipService();