// src/components/chat/ChatRoomPage.jsx
import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { getDatabase, ref, get, onValue, push, serverTimestamp, update } from 'firebase/database';
import { useAuth } from '../../contexts/AuthContext';
import { useStreamingLiveKit } from '../../contexts/StreamingContextLiveKit';
import ChatRoomsList from './ChatRoomsList';
import ChatParticipantsList from './ChatParticipantsList';
import ChatMessageList from './ChatMessageList';
import ChatMessageInput from './ChatMessageInput';
import UserStatusBadge from '../common/UserStatusBadge';
import { Video, Users, ArrowLeftRight, Info, X, ChevronLeft, Send, Search, Filter } from 'lucide-react';
import './ChatRoomPage.css';

const ChatRoomPage = () => {
  const { roomId } = useParams();
  const { currentUser } = useAuth();
  const { roomActiveStreamers } = useStreamingLiveKit();
  const navigate = useNavigate();
  
  const [room, setRoom] = useState(null);
  const [messages, setMessages] = useState([]);
  const [participants, setParticipants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showParticipants, setShowParticipants] = useState(window.innerWidth >= 1280);
  const [messageInput, setMessageInput] = useState('');
  const [showRoomInfo, setShowRoomInfo] = useState(false);
  const [showRoomList, setShowRoomList] = useState(window.innerWidth >= 1024);
  
  const messagesEndRef = useRef(null);
  const messageInputRef = useRef(null);
  
  // Scroll to bottom when new messages arrive
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);
  
  // Add responsive behavior
  useEffect(() => {
    const handleResize = () => {
      setShowParticipants(window.innerWidth >= 1280);
      setShowRoomList(window.innerWidth >= 1024);
    };
    
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);
  
  // Fetch room data and setup listeners
  useEffect(() => {
    const fetchRoom = async () => {
      try {
        setLoading(true);
        
        const db = getDatabase();
        const roomRef = ref(db, `chats/public/${roomId}`);
        
        // Get initial room data
        const roomSnapshot = await get(roomRef);
        
        if (!roomSnapshot.exists()) {
          setError('Room not found');
          setLoading(false);
          return;
        }
        
        const roomData = {
          id: roomId,
          ...roomSnapshot.val()
        };
        
        setRoom(roomData);
        
        // Set up real-time listener for room updates
        const unsubscribe = onValue(roomRef, (snapshot) => {
          if (snapshot.exists()) {
            setRoom({
              id: roomId,
              ...snapshot.val()
            });
          } else {
            // Room was deleted
            setError('This room no longer exists');
            navigate('/rooms');
          }
        }, (err) => {
          console.error('Error in room listener:', err);
          setError(`Access denied: ${err.message}`);
        });
        
        setLoading(false);
        return () => unsubscribe();
      } catch (err) {
        console.error('Error loading room:', err);
        setError(`Failed to load room: ${err.message}`);
        setLoading(false);
      }
    };
    
    if (roomId) {
      fetchRoom();
    }
  }, [roomId, navigate]);
  
  // Add user to participants when joining room
  useEffect(() => {
    if (!roomId || !currentUser) return;
    
    const db = getDatabase();
    const participantRef = ref(db, `chats/public/${roomId}/participants/${currentUser.uid}`);
    
    // Add or update participant
    update(participantRef, {
      displayName: currentUser.displayName || 'Anonymous',
      photoURL: currentUser.photoURL || null,
      lastActive: serverTimestamp()
    });
    
    // Set up interval to update last active status
    const interval = setInterval(() => {
      update(participantRef, {
        lastActive: serverTimestamp()
      });
    }, 60000); // Every minute
    
    // Clean up on unmount
    return () => {
      clearInterval(interval);
    };
  }, [roomId, currentUser]);
  
  const toggleParticipants = () => {
    setShowParticipants(prev => !prev);
  };
  
  const toggleRoomInfo = () => {
    setShowRoomInfo(prev => !prev);
  };
  
  const toggleRoomList = () => {
    setShowRoomList(prev => !prev);
  };
  
  const handleSendMessage = () => {
    if (!roomId || !messageInput.trim() || !currentUser) return;
    
    const db = getDatabase();
    const messagesRef = ref(db, `chats/public/${roomId}/messages`);
    
    push(messagesRef, {
      text: messageInput.trim(),
      userId: currentUser.uid,
      displayName: currentUser.displayName || 'Anonymous',
      photoURL: currentUser.photoURL || null,
      timestamp: serverTimestamp()
    })
      .then(() => {
        setMessageInput('');
        messageInputRef.current?.focus();
      })
      .catch(err => {
        console.error('Error sending message:', err);
      });
  };
  
  const handleInputChange = (e) => {
    setMessageInput(e.target.value);
  };
  
  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };
  
  // Format timestamp
  const formatTimestamp = (timestamp) => {
    if (!timestamp) return '';
    
    const date = new Date(timestamp);
    const now = new Date();
    const isToday = date.toDateString() === now.toDateString();
    
    if (isToday) {
      return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    } else {
      return date.toLocaleDateString([], { month: 'short', day: 'numeric' }) + 
             ' ' + date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    }
  };
  
  if (loading) {
    return (
      <div className="chat-room-loading">
        <div className="spinner"></div>
        <p>Loading room...</p>
      </div>
    );
  }
  
  if (error) {
    return (
      <div className="chat-room-error">
        <p className="error-message">{error}</p>
        <button onClick={() => navigate('/rooms')} className="back-button">
          Back to Room List
        </button>
      </div>
    );
  }
  
  const hasActiveStreamers = roomActiveStreamers && roomActiveStreamers.length > 0;
  
  return (
    <div className="chat-room-page">
      {/* Chat Room Header */}
      <div className="chat-room-header">
        <div className="header-left">
          <button 
            className="menu-button"
            onClick={toggleRoomList}
            aria-label="Toggle Room List"
            title="Toggle Room List"
          >
            {showRoomList ? <X size={20} /> : <ChevronLeft size={20} />}
          </button>
          
          <div className="room-info">
            <h2>{room.name}</h2>
            <div className="room-meta">
              <p className="room-description">{room.description}</p>
            </div>
          </div>
        </div>
        
        <div className="header-right">
          {/* Streaming Button - Only show for event rooms */}
          {room.type === 'event' && (
            <Link 
              to={`/room/${roomId}/stream`}
              className={`streaming-button ${hasActiveStreamers ? 'active' : ''}`}
            >
              <Video size={18} />
              <span>
                {hasActiveStreamers 
                  ? `Live (${roomActiveStreamers.length})` 
                  : 'Stream'}
              </span>
            </Link>
          )}
          
          <button 
            className={`action-button ${showRoomInfo ? 'active' : ''}`}
            onClick={toggleRoomInfo}
            aria-label="Room Information"
            title="Room Information"
          >
            <Info size={18} />
          </button>
          
          <button 
            className={`action-button ${showParticipants ? 'active' : ''}`}
            onClick={toggleParticipants}
            aria-label="Show Participants"
            title="Show Participants"
          >
            <Users size={18} />
          </button>
        </div>
      </div>
      
      <div className="chat-room-content">
        {/* Room List Sidebar */}
        {showRoomList && (
          <div className="room-list-sidebar">
            <div className="sidebar-header">
              <h3>Chat Rooms</h3>
              <div className="sidebar-actions">
                <button className="icon-button" aria-label="Search Rooms">
                  <Search size={16} />
                </button>
                <button className="icon-button" aria-label="Filter Rooms">
                  <Filter size={16} />
                </button>
                <button 
                  className="close-sidebar visible-mobile"
                  onClick={toggleRoomList}
                >
                  <X size={16} />
                </button>
              </div>
            </div>
            <ChatRoomsList />
          </div>
        )}
        
        {/* Main Chat Area */}
        <div className="chat-main-content">
          {/* Room Info Panel (conditionally rendered) */}
          {showRoomInfo && (
            <div className="room-info-panel">
              <div className="panel-header">
                <h3>Room Information</h3>
                <button className="close-panel" onClick={toggleRoomInfo}>
                  <X size={18} />
                </button>
              </div>
              
              <div className="panel-content">
                <div className="info-group">
                  <h4>Room Name</h4>
                  <p>{room.name}</p>
                </div>
                
                <div className="info-group">
                  <h4>Description</h4>
                  <p>{room.description || 'No description provided.'}</p>
                </div>
                
                <div className="info-group">
                  <h4>Created</h4>
                  <p>{room.createdAt ? formatTimestamp(room.createdAt) : 'Unknown'}</p>
                </div>
                
                <div className="info-group">
                  <h4>Created By</h4>
                  <p>{room.createdBy || 'Unknown'}</p>
                </div>
                
                {room.rules && (
                  <div className="info-group">
                    <h4>Room Rules</h4>
                    <p>{room.rules}</p>
                  </div>
                )}
                
                {room.tags && room.tags.length > 0 && (
                  <div className="info-group">
                    <h4>Tags</h4>
                    <div className="room-tags">
                      {room.tags.map((tag, index) => (
                        <span key={index} className="room-tag">{tag}</span>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}
          
          <UserStatusBadge />
          <ChatMessageList roomId={roomId} />
          
          {/* Message Input */}
          <div className="message-input-container">
            <div className="message-form">
              <textarea
                ref={messageInputRef}
                className="message-input"
                value={messageInput}
                onChange={handleInputChange}
                onKeyDown={handleKeyPress}
                placeholder="Type a message..."
                rows={1}
              />
              
              <button 
                className="send-button"
                onClick={handleSendMessage}
                disabled={!messageInput.trim() || !currentUser}
              >
                <Send size={20} />
              </button>
            </div>
            <div className="input-hint">
              Press Enter to send, Shift+Enter for new line
            </div>
          </div>
          
          {/* Reference for scrolling to bottom */}
          <div ref={messagesEndRef} />
        </div>
        
        {/* Participants Sidebar */}
        {showParticipants && (
          <div className="participants-sidebar">
            <div className="sidebar-header">
              <h3>Participants</h3>
              <button 
                className="close-sidebar"
                onClick={toggleParticipants}
              >
                <X size={18} />
              </button>
            </div>
            <ChatParticipantsList roomId={roomId} />
          </div>
        )}
      </div>
    </div>
  );
};

export default ChatRoomPage;