import React, { useState, useRef } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { getStorage, ref, uploadBytesResumable, getDownloadURL } from 'firebase/storage';
import { getFirestore, doc, updateDoc, arrayUnion, serverTimestamp } from 'firebase/firestore';
import { Upload, Music, X, Check, AlertCircle } from 'lucide-react';

const DJSetUpload = ({ onUploadComplete, onClose }) => {
  const { currentUser } = useAuth();
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);
  const fileInputRef = useRef(null);

  const [setData, setSetData] = useState({
    title: '',
    description: '',
    genre: '',
    bpm: '',
    duration: '',
    tags: []
  });

  const [selectedFile, setSelectedFile] = useState(null);
  const [tagInput, setTagInput] = useState('');

  // Handle file selection
  const handleFileSelect = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Validate file type
    const allowedTypes = ['audio/mp3', 'audio/mpeg', 'audio/wav', 'audio/ogg', 'audio/aac', 'audio/flac'];
    if (!allowedTypes.includes(file.type)) {
      setError('Please select a valid audio file (MP3, WAV, OGG, AAC, or FLAC)');
      return;
    }

    // Validate file size (100MB limit)
    const maxSize = 100 * 1024 * 1024; // 100MB
    if (file.size > maxSize) {
      setError('File size must be less than 100MB');
      return;
    }

    setSelectedFile(file);
    setError(null);

    // Auto-populate title if empty
    if (!setData.title) {
      const fileName = file.name.replace(/\.[^/.]+$/, ''); // Remove extension
      setSetData(prev => ({ ...prev, title: fileName }));
    }
  };

  // Handle form input changes
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setSetData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  // Handle tag input
  const handleTagKeyPress = (e) => {
    if (e.key === 'Enter' || e.key === ',') {
      e.preventDefault();
      addTag();
    }
  };

  const addTag = () => {
    const tag = tagInput.trim().toLowerCase();
    if (tag && !setData.tags.includes(tag)) {
      setSetData(prev => ({
        ...prev,
        tags: [...prev.tags, tag]
      }));
      setTagInput('');
    }
  };

  const removeTag = (tagToRemove) => {
    setSetData(prev => ({
      ...prev,
      tags: prev.tags.filter(tag => tag !== tagToRemove)
    }));
  };

  // Upload the DJ set
  const handleUpload = async () => {
    if (!selectedFile || !setData.title.trim()) {
      setError('Please select a file and enter a title');
      return;
    }

    if (!currentUser) {
      setError('You must be logged in to upload');
      return;
    }

    setUploading(true);
    setError(null);
    setUploadProgress(0);

    try {
      const storage = getStorage();
      const db = getFirestore();

      // Create unique filename
      const timestamp = Date.now();
      const fileExtension = selectedFile.name.split('.').pop();
      const fileName = `${setData.title.replace(/[^a-zA-Z0-9]/g, '_')}_${timestamp}.${fileExtension}`;
      const storageRef = ref(storage, `artists/${currentUser.uid}/sets/${fileName}`);

      // Create upload task
      const uploadTask = uploadBytesResumable(storageRef, selectedFile);

      uploadTask.on(
        'state_changed',
        (snapshot) => {
          const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
          setUploadProgress(Math.round(progress));
        },
        (error) => {
          console.error('Upload error:', error);
          setError('Upload failed. Please try again.');
          setUploading(false);
        },
        async () => {
          try {
            // Get download URL
            const downloadURL = await getDownloadURL(uploadTask.snapshot.ref);

            // Create set object
            const djSet = {
              id: `set_${timestamp}`,
              title: setData.title.trim(),
              description: setData.description.trim(),
              genre: setData.genre.trim(),
              bpm: setData.bpm ? parseInt(setData.bpm) : null,
              duration: setData.duration.trim(),
              tags: setData.tags,
              audioUrl: downloadURL,
              fileName: fileName,
              fileSize: selectedFile.size,
              fileType: selectedFile.type,
              // serverTimestamp() is invalid inside an array element (arrayUnion),
              // so use a client-side Date — Firestore stores it as a Timestamp.
              uploadedAt: new Date(),
              plays: 0,
              likes: 0
            };

            // Update user document with new set
            const userRef = doc(db, 'users', currentUser.uid);
            await updateDoc(userRef, {
              djSets: arrayUnion(djSet),
              lastUpdated: serverTimestamp()
            });

            setSuccess(true);
            setUploading(false);

            // Call completion callback
            onUploadComplete?.(djSet);

            // Auto-close after success
            setTimeout(() => {
              onClose?.();
            }, 2000);

          } catch (error) {
            console.error('Error saving set data:', error);
            setError('Failed to save set information');
            setUploading(false);
          }
        }
      );

    } catch (error) {
      console.error('Error starting upload:', error);
      setError('Failed to start upload');
      setUploading(false);
    }
  };

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  return (
    <div className="dj-set-upload-overlay">
      <div className="upload-modal">
        <div className="modal-header">
          <h2>Upload DJ Set</h2>
          <button onClick={onClose} className="close-button">
            <X size={20} />
          </button>
        </div>

        {error && (
          <div className="error-message">
            <AlertCircle size={16} />
            <span>{error}</span>
          </div>
        )}

        {success && (
          <div className="success-message">
            <Check size={16} />
            <span>DJ Set uploaded successfully!</span>
          </div>
        )}

        <div className="modal-content">
          {/* File Upload Section */}
          <div className="upload-section">
            {!selectedFile ? (
              <div 
                className="file-drop-area"
                onClick={() => fileInputRef.current?.click()}
              >
                <Upload size={40} />
                <h3>Drop your audio file here</h3>
                <p>or click to browse</p>
                <p className="file-requirements">
                  Supported: MP3, WAV, OGG, AAC, FLAC (max 100MB)
                </p>
              </div>
            ) : (
              <div className="selected-file">
                <Music size={24} />
                <div className="file-info">
                  <h4>{selectedFile.name}</h4>
                  <p>{formatFileSize(selectedFile.size)}</p>
                </div>
                <button 
                  onClick={() => setSelectedFile(null)}
                  className="remove-file-button"
                  disabled={uploading}
                >
                  <X size={16} />
                </button>
              </div>
            )}

            <input
              ref={fileInputRef}
              type="file"
              accept="audio/*"
              onChange={handleFileSelect}
              style={{ display: 'none' }}
            />
          </div>

          {/* Set Information Form */}
          {selectedFile && (
            <div className="set-form">
              <div className="form-group">
                <label>Title *</label>
                <input
                  type="text"
                  name="title"
                  value={setData.title}
                  onChange={handleInputChange}
                  placeholder="Enter set title"
                  disabled={uploading}
                />
              </div>

              <div className="form-group">
                <label>Description</label>
                <textarea
                  name="description"
                  value={setData.description}
                  onChange={handleInputChange}
                  placeholder="Describe your set..."
                  rows={3}
                  disabled={uploading}
                />
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Genre</label>
                  <input
                    type="text"
                    name="genre"
                    value={setData.genre}
                    onChange={handleInputChange}
                    placeholder="e.g., House, Techno"
                    disabled={uploading}
                  />
                </div>

                <div className="form-group">
                  <label>BPM</label>
                  <input
                    type="number"
                    name="bpm"
                    value={setData.bpm}
                    onChange={handleInputChange}
                    placeholder="128"
                    min="60"
                    max="200"
                    disabled={uploading}
                  />
                </div>

                <div className="form-group">
                  <label>Duration</label>
                  <input
                    type="text"
                    name="duration"
                    value={setData.duration}
                    onChange={handleInputChange}
                    placeholder="1h 30m"
                    disabled={uploading}
                  />
                </div>
              </div>

              <div className="form-group">
                <label>Tags</label>
                <div className="tags-input">
                  <input
                    type="text"
                    value={tagInput}
                    onChange={(e) => setTagInput(e.target.value)}
                    onKeyDown={handleTagKeyPress}
                    placeholder="Add tags (press Enter)"
                    disabled={uploading}
                  />
                  <button 
                    type="button" 
                    onClick={addTag}
                    className="add-tag-button"
                    disabled={uploading}
                  >
                    Add
                  </button>
                </div>
                
                {setData.tags.length > 0 && (
                  <div className="tags-list">
                    {setData.tags.map((tag, index) => (
                      <span key={index} className="tag">
                        {tag}
                        <button 
                          onClick={() => removeTag(tag)}
                          className="remove-tag-button"
                          disabled={uploading}
                        >
                          <X size={12} />
                        </button>
                      </span>
                    ))}
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Upload Progress */}
          {uploading && (
            <div className="upload-progress">
              <div className="progress-bar">
                <div 
                  className="progress-fill" 
                  style={{ width: `${uploadProgress}%` }}
                />
              </div>
              <span className="progress-text">{uploadProgress}% uploaded</span>
            </div>
          )}

          {/* Action Buttons */}
          <div className="modal-actions">
            <button 
              onClick={onClose} 
              className="cancel-button"
              disabled={uploading}
            >
              Cancel
            </button>
            <button 
              onClick={handleUpload}
              className="upload-button"
              disabled={!selectedFile || !setData.title.trim() || uploading}
            >
              {uploading ? 'Uploading...' : 'Upload Set'}
            </button>
          </div>
        </div>

        <style jsx>{`
          .dj-set-upload-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0, 0, 0, 0.7);
            backdrop-filter: blur(4px);
            display: flex;
            align-items: center;
            justify-content: center;
            z-index: 1000;
            padding: 1rem;
          }

          .upload-modal {
            background: white;
            border-radius: 16px;
            width: 100%;
            max-width: 600px;
            max-height: 90vh;
            overflow-y: auto;
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
          }

          .modal-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 1.5rem 2rem;
            border-bottom: 1px solid #e5e7eb;
          }

          .modal-header h2 {
            margin: 0;
            color: #1e293b;
            font-size: 1.5rem;
          }

          .close-button {
            background: none;
            border: none;
            cursor: pointer;
            color: #6b7280;
            padding: 0.5rem;
            border-radius: 8px;
            transition: all 0.2s;
          }

          .close-button:hover {
            background: #f3f4f6;
            color: #374151;
          }

          .error-message,
          .success-message {
            display: flex;
            align-items: center;
            gap: 0.5rem;
            margin: 1rem 2rem;
            padding: 1rem;
            border-radius: 8px;
            font-weight: 500;
          }

          .error-message {
            background: #fee2e2;
            color: #dc2626;
            border: 1px solid #fca5a5;
          }

          .success-message {
            background: #d1fae5;
            color: #059669;
            border: 1px solid #6ee7b7;
          }

          .modal-content {
            padding: 2rem;
          }

          .file-drop-area {
            border: 2px dashed #d1d5db;
            border-radius: 12px;
            padding: 3rem 2rem;
            text-align: center;
            cursor: pointer;
            transition: all 0.2s;
            margin-bottom: 2rem;
          }

          .file-drop-area:hover {
            border-color: #7c3aed;
            background: #faf5ff;
          }

          .file-drop-area h3 {
            margin: 1rem 0 0.5rem;
            color: #374151;
          }

          .file-drop-area p {
            color: #6b7280;
            margin: 0.25rem 0;
          }

          .file-requirements {
            font-size: 0.875rem !important;
            margin-top: 1rem !important;
          }

          .selected-file {
            display: flex;
            align-items: center;
            gap: 1rem;
            padding: 1rem;
            background: #f8fafc;
            border: 1px solid #e2e8f0;
            border-radius: 8px;
            margin-bottom: 2rem;
          }

          .file-info h4 {
            margin: 0 0 0.25rem;
            color: #1e293b;
          }

          .file-info p {
            margin: 0;
            color: #6b7280;
            font-size: 0.875rem;
          }

          .remove-file-button {
            background: #fee2e2;
            color: #dc2626;
            border: none;
            border-radius: 6px;
            padding: 0.5rem;
            cursor: pointer;
            transition: all 0.2s;
          }

          .remove-file-button:hover:not(:disabled) {
            background: #fca5a5;
          }

          .remove-file-button:disabled {
            opacity: 0.5;
            cursor: not-allowed;
          }

          .set-form {
            display: flex;
            flex-direction: column;
            gap: 1.5rem;
          }

          .form-group {
            display: flex;
            flex-direction: column;
            gap: 0.5rem;
          }

          .form-row {
            display: grid;
            grid-template-columns: 2fr 1fr 1fr;
            gap: 1rem;
          }

          .form-group label {
            font-weight: 500;
            color: #374151;
          }

          .form-group input,
          .form-group textarea {
            padding: 0.75rem 1rem;
            border: 1px solid #d1d5db;
            border-radius: 8px;
            font-size: 1rem;
            transition: border-color 0.2s;
          }

          .form-group input:focus,
          .form-group textarea:focus {
            outline: none;
            border-color: #7c3aed;
          }

          .form-group input:disabled,
          .form-group textarea:disabled {
            background: #f9fafb;
            color: #6b7280;
          }

          .tags-input {
            display: flex;
            gap: 0.5rem;
          }

          .tags-input input {
            flex: 1;
          }

          .add-tag-button {
            background: #7c3aed;
            color: white;
            border: none;
            border-radius: 8px;
            padding: 0.75rem 1rem;
            cursor: pointer;
            font-weight: 500;
            transition: all 0.2s;
          }

          .add-tag-button:hover:not(:disabled) {
            background: #6d28d9;
          }

          .add-tag-button:disabled {
            background: #a5b4fc;
            cursor: not-allowed;
          }

          .tags-list {
            display: flex;
            flex-wrap: wrap;
            gap: 0.5rem;
            margin-top: 0.5rem;
          }

          .tag {
            display: flex;
            align-items: center;
            gap: 0.25rem;
            background: #e0e7ff;
            color: #3730a3;
            padding: 0.25rem 0.5rem;
            border-radius: 6px;
            font-size: 0.875rem;
          }

          .remove-tag-button {
            background: none;
            border: none;
            color: #3730a3;
            cursor: pointer;
            padding: 0.125rem;
            border-radius: 3px;
            transition: all 0.2s;
          }

          .remove-tag-button:hover:not(:disabled) {
            background: #c7d2fe;
          }

          .upload-progress {
            margin: 2rem 0;
          }

          .progress-bar {
            width: 100%;
            height: 8px;
            background: #e5e7eb;
            border-radius: 4px;
            overflow: hidden;
          }

          .progress-fill {
            height: 100%;
            background: linear-gradient(90deg, #7c3aed, #a855f7);
            transition: width 0.3s ease;
          }

          .progress-text {
            display: block;
            text-align: center;
            margin-top: 0.5rem;
            font-size: 0.875rem;
            color: #6b7280;
          }

          .modal-actions {
            display: flex;
            gap: 1rem;
            justify-content: flex-end;
            margin-top: 2rem;
            padding-top: 2rem;
            border-top: 1px solid #e5e7eb;
          }

          .cancel-button,
          .upload-button {
            padding: 0.75rem 1.5rem;
            border-radius: 8px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s;
          }

          .cancel-button {
            background: #f3f4f6;
            color: #4b5563;
            border: 1px solid #d1d5db;
          }

          .cancel-button:hover:not(:disabled) {
            background: #e5e7eb;
          }

          .upload-button {
            background: #7c3aed;
            color: white;
            border: none;
          }

          .upload-button:hover:not(:disabled) {
            background: #6d28d9;
          }

          .upload-button:disabled {
            background: #a5b4fc;
            cursor: not-allowed;
          }

          @media (max-width: 640px) {
            .upload-modal {
              margin: 0.5rem;
              max-height: 95vh;
            }

            .modal-header,
            .modal-content {
              padding: 1rem;
            }

            .form-row {
              grid-template-columns: 1fr;
            }

            .modal-actions {
              flex-direction: column;
            }

            .file-drop-area {
              padding: 2rem 1rem;
            }
          }
        `}</style>
      </div>
    </div>
  );
};

export default DJSetUpload;