// src/admin/AdminPanel.js
import UserManagement from './UserManagement.jsx';
import React, { useState, useEffect } from 'react';
import { Routes, Route, NavLink, useNavigate, useLocation } from 'react-router-dom';
import { Save, Image, Layout, Settings, Home, Search, Bell, Database, Video, RefreshCw, Activity, Shield, MessageSquare, Volume2, AlertTriangle, CreditCard, Users, Crown } from 'lucide-react';
import { useSiteConfig } from '../contexts/SiteConfigContext';
import BackgroundManager from './BackgroundManager.jsx';
import WidgetManager from './WidgetManager';
import SiteSettings from './SiteSettings';
import AnnouncementManager from './AnnouncementManager';
import StreamManager from './StreamManager';
import CounterManager from './CounterManager';
import AuditManager from './AuditManager';
import ModerationBot from './ModerationBot'; 
import BotMessageConfig from './BotMessageConfig';
import AudioDetectionManager from './audio/AudioDetectionManager';
import MaintenanceControl from './MaintenanceControl';
import AdminDashboard from './AdminDashboard';
import PremiumCleanupTool from '../components/admin/PremiumCleanupTool';
import SubscriptionManagement from './components/SubscriptionManagement';
import UserList from './UserList';
import TipAdminPanel from './TipAdminPanel';
import VenueUserManagement from './VenueUserManagement';

const AdminPanel = () => {
  const { config, updateConfig } = useSiteConfig();
  const [isUpdating, setIsUpdating] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  
  // Check if we're at the root admin path
  const isRootPath = location.pathname === '/admin' || location.pathname === '/admin/';

  // Function to save configuration changes
  const saveChanges = async () => {
    if (!config) return;
    
    setIsUpdating(true);
    try {
      await updateConfig(config);
      alert('Configuration saved successfully!');
    } catch (error) {
      alert(`Failed to save configuration: ${error.message}`);
    } finally {
      setIsUpdating(false);
    }
  };

  // Ensure the backgrounds array exists in the config
  useEffect(() => {
    if (config && !config.backgrounds) {
      updateConfig({
        ...config,
        backgrounds: []
      });
    }
    // Initialize video settings if they don't exist
    if (config && !config.videoSettings) {
      updateConfig({
        ...config,
        videoSettings: {
          autoplay: true,
          loop: true,
          muted: true,
          controls: false,
          playbackRate: 1
        }
      });
    }
  }, [config, updateConfig]);

  // Get the active background
  const activeBackground = config?.backgrounds?.find(bg => bg.isActive);
  
  // Default background as fallback if no active background is set
  const defaultBackground = {
    type: 'image',
    url: '/images/default-background.jpg'
  };

  // Use default background if no active background exists
  const displayBackground = activeBackground || defaultBackground;

  return (
    <div className="min-h-screen bg-gray-100">
      {/* Header */}
      <header className="bg-indigo-600 text-white p-4 shadow-md">
        <div className="container mx-auto flex justify-between items-center">
          <h1 className="text-2xl font-bold flex items-center">
            <Settings className="mr-2" size={24} />
            TalkStudio Admin
          </h1>
          <div className="flex gap-2">
            <button 
              onClick={() => navigate('/')}
              className="bg-transparent text-white px-4 py-2 rounded-md flex items-center font-medium hover:bg-indigo-700 border border-white"
            >
              <Home className="mr-2" size={18} />
              Back to Site
            </button>
            <button 
              onClick={saveChanges}
              disabled={isUpdating}
              className={`bg-white text-indigo-600 px-4 py-2 rounded-md flex items-center font-medium 
                ${isUpdating ? 'opacity-70 cursor-not-allowed' : 'hover:bg-gray-100'}`}
            >
              <Save className="mr-2" size={18} />
              {isUpdating ? 'Saving...' : 'Save Changes'}
            </button>
          </div>
        </div>
      </header>
      
      {/* Main Content */}
      <div className="container mx-auto p-6">
        
        <div className="bg-white rounded-lg shadow-md overflow-hidden">
          {/* Navigation Tabs */}
          <div className="flex border-b overflow-x-auto">
            <NavLink
              to="/admin"
              className={({ isActive }) => 
                `px-6 py-3 font-medium flex items-center whitespace-nowrap ${isActive || isRootPath 
                  ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                  : 'text-gray-600 hover:bg-gray-50'
                }`
              }
              end
            >
              <Home className="mr-2" size={18} />
              Dashboard
            </NavLink>
            <NavLink
              to="/admin/backgrounds"
              className={({ isActive }) => 
                `px-6 py-3 font-medium flex items-center whitespace-nowrap ${
                  isActive 
                    ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                    : 'text-gray-600 hover:bg-gray-50'
                }`
              }
            >
              <Image className="mr-2" size={18} />
              Background Media
            </NavLink>
            <NavLink
              to="/admin/widgets"
              className={({ isActive }) => 
                `px-6 py-3 font-medium flex items-center whitespace-nowrap ${
                  isActive 
                    ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                    : 'text-gray-600 hover:bg-gray-50'
                }`
              }
            >
              <Layout className="mr-2" size={18} />
              Widgets
            </NavLink>
            <NavLink
              to="/admin/announcements"
              className={({ isActive }) => 
                `px-6 py-3 font-medium flex items-center whitespace-nowrap ${
                  isActive 
                    ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                    : 'text-gray-600 hover:bg-gray-50'
                }`
              }
            >
              <Bell className="mr-2" size={18} />
              Announcements
            </NavLink>
            <NavLink
              to="/admin/stream"
              className={({ isActive }) => 
                `px-6 py-3 font-medium flex items-center whitespace-nowrap ${
                  isActive 
                    ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                    : 'text-gray-600 hover:bg-gray-50'
                }`
              }
            >
              <Video className="mr-2" size={18} />
              Stream Manager
            </NavLink>
            <NavLink
              to="/admin/counters"
              className={({ isActive }) => 
                `px-6 py-3 font-medium flex items-center whitespace-nowrap ${
                  isActive 
                    ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                    : 'text-gray-600 hover:bg-gray-50'
                }`
              }
            >
              <RefreshCw className="mr-2" size={18} />
              Counters
            </NavLink>
            <NavLink
              to="/admin/database"
              className={({ isActive }) => 
                `px-6 py-3 font-medium flex items-center whitespace-nowrap ${
                  isActive 
                    ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                    : 'text-gray-600 hover:bg-gray-50'
                }`
              }
            >
              <Database className="mr-2" size={18} />
              Stream Database
            </NavLink>
            <NavLink
              to="/admin/audio-detection"
              className={({ isActive }) => 
                `px-6 py-3 font-medium flex items-center whitespace-nowrap ${
                  isActive 
                    ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                    : 'text-gray-600 hover:bg-gray-50'
                }`
              }
            >
              <Volume2 className="mr-2" size={18} />
              Audio Detection
            </NavLink>
            <NavLink
              to="/admin/moderation"
              className={({ isActive }) => 
                `px-6 py-3 font-medium flex items-center whitespace-nowrap ${
                  isActive 
                    ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                    : 'text-gray-600 hover:bg-gray-50'
                }`
              }
            >
              <Shield className="mr-2" size={18} />
              Moderation Bot
            </NavLink>
            <NavLink
              to="/admin/bot-messages"
              className={({ isActive }) => 
                `px-6 py-3 font-medium flex items-center whitespace-nowrap ${
                  isActive 
                    ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                    : 'text-gray-600 hover:bg-gray-50'
                }`
              }
            >
              <MessageSquare className="mr-2" size={18} />
              Bot Messages
            </NavLink>
            <NavLink
              to="/admin/audit"
              className={({ isActive }) => 
                `px-6 py-3 font-medium flex items-center whitespace-nowrap ${
                  isActive 
                    ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                    : 'text-gray-600 hover:bg-gray-50'
                }`
              }
            >
              <Activity className="mr-2" size={18} />
              Audit Manager
            </NavLink>
            {/* Maintenance Mode link removed since we're using DigitalOcean's maintenance mode
            <NavLink
              to="/admin/maintenance"
              className={({ isActive }) => 
                `px-6 py-3 font-medium flex items-center whitespace-nowrap ${
                  isActive 
                    ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                    : 'text-gray-600 hover:bg-gray-50'
                }`
              }
            >
              <AlertTriangle className="mr-2" size={18} />
              Maintenance Mode
            </NavLink>
            */}
            <NavLink
              to="/admin/tips"
              className={({ isActive }) => 
                `px-6 py-3 font-medium flex items-center whitespace-nowrap ${
                  isActive 
                    ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                    : 'text-gray-600 hover:bg-gray-50'
                }`
              }
            >
              <CreditCard className="mr-2" size={18} />
              Tip Administration
            </NavLink>
            <NavLink
              to="/admin/subscriptions"
              className={({ isActive }) => 
                `px-6 py-3 font-medium flex items-center whitespace-nowrap ${
                  isActive 
                    ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                    : 'text-gray-600 hover:bg-gray-50'
                }`
              }
            >
              <Crown className="mr-2" size={18} />
              Subscriptions
            </NavLink>
            {/* Users dropdown */}
            <div className="relative group">
              <NavLink
                to="/admin/users"
                className={({ isActive }) => 
                  `px-6 py-3 font-medium flex items-center whitespace-nowrap ${
                    isActive || location.pathname.startsWith('/admin/users/') 
                      ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                      : 'text-gray-600 hover:bg-gray-50'
                  }`
                }
              >
                <Users className="mr-2" size={18} />
                User Management
              </NavLink>
              
              <div className="absolute hidden group-hover:block left-0 bg-white border shadow-lg rounded-md z-50 mt-1 w-48">
                <NavLink
                  to="/admin/users"
                  className={({ isActive }) => 
                    `block px-4 py-2 text-sm ${isActive ? 'bg-indigo-50 text-indigo-600' : 'text-gray-700 hover:bg-gray-50'}`
                  }
                  end
                >
                  User List
                </NavLink>
                <NavLink
                  to="/admin/users/roles"
                  className={({ isActive }) => 
                    `block px-4 py-2 text-sm ${isActive ? 'bg-indigo-50 text-indigo-600' : 'text-gray-700 hover:bg-gray-50'}`
                  }
                >
                  Admin Roles
                </NavLink>
                <NavLink
                  to="/admin/users/venues"
                  className={({ isActive }) => 
                    `block px-4 py-2 text-sm ${isActive ? 'bg-indigo-50 text-indigo-600' : 'text-gray-700 hover:bg-gray-50'}`
                  }
                >
                  Venue Users
                </NavLink>
              </div>
            </div>
            <NavLink
              to="/admin/settings"
              className={({ isActive }) => 
                `px-6 py-3 font-medium flex items-center whitespace-nowrap ${
                  isActive 
                    ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' 
                    : 'text-gray-600 hover:bg-gray-50'
                }`
              }
            >
              <Settings className="mr-2" size={18} />
              Site Settings
            </NavLink>
          </div>
          
          {/* Content */}
          <div className="p-6">
            <Routes>
              <Route path="/" element={<AdminDashboard />} />
              <Route path="/backgrounds" element={<BackgroundManager />} />
              <Route path="/widgets" element={<WidgetManager />} />
              <Route path="/announcements" element={<AnnouncementManager />} />
              <Route path="/stream" element={<StreamManager />} />
              <Route path="/counters" element={<CounterManager />} />
              <Route path="/database" element={<AuditManager />} />
              <Route path="/audio-detection" element={<AudioDetectionManager />} />
              <Route path="/settings" element={<SiteSettings />} />
              <Route path="/audit" element={<AuditManager />} />
              <Route path="/moderation" element={<ModerationBot />} />
              <Route path="/bot-messages" element={<BotMessageConfig />} />
              <Route path="/bot-messages/room/:roomId" element={<BotMessageConfig />} />
              {/* Maintenance route removed - using Digital Ocean's maintenance mode
              <Route path="/maintenance" element={<MaintenanceControl />} />
              */}
              <Route path="/tips" element={<TipAdminPanel />} />
              <Route path="/premium-cleanup" element={<PremiumCleanupTool />} />
              <Route path="/subscriptions" element={<SubscriptionManagement />} />
              <Route path="/users" element={<UserList />} />
              <Route path="/users/roles" element={<UserManagement />} />
              <Route path="/users/venues" element={<VenueUserManagement />} />
            </Routes>
          </div>
        </div>
        
        {/* Preview Section */}
        <div className="mt-8 bg-white rounded-lg shadow-md overflow-hidden">
          <div className="bg-gray-800 p-4 text-white font-medium">
            Preview (changes not saved until you click "Save Changes")
          </div>
          <div className="p-4">
            <div className="relative w-full h-64 rounded-lg overflow-hidden border">
              {/* Background Preview - Supporting both image and video with fallback */}
              {displayBackground.type === 'video' ? (
                <video 
                  className="absolute inset-0 w-full h-full object-cover"
                  src={displayBackground.url || ''}
                  autoPlay={config?.videoSettings?.autoplay !== false}
                  loop={config?.videoSettings?.loop !== false}
                  muted={config?.videoSettings?.muted !== false}
                  controls={config?.videoSettings?.controls || false}
                  style={{ filter: 'brightness(0.7)' }}
                  onError={(e) => {
                    console.error("Video loading error:", e);
                    e.target.style.display = 'none';
                    // Create a fallback element
                    const fallback = document.createElement('div');
                    fallback.className = 'absolute inset-0 w-full h-full bg-gray-300 flex items-center justify-center';
                    fallback.innerHTML = '<span class="text-gray-600">Video preview unavailable</span>';
                    e.target.parentNode.appendChild(fallback);
                  }}
                />
              ) : (
                <div 
                  className="absolute inset-0 w-full h-full bg-cover bg-center"
                  style={{ 
                    backgroundImage: `url(${displayBackground.url || '/images/default-background.jpg'})`,
                    filter: 'brightness(0.7)'
                  }}
                />
              )}
              
              {/* Content Preview */}
              <div className="absolute inset-0 flex flex-col items-center justify-center p-6">
                <h1 className="text-3xl text-white font-bold text-center mb-4 z-10">
                  {config?.headerTagline || 'Discover Conversations'}
                </h1>
                
                <div className="relative w-full max-w-md mb-4">
                  <input
                    type="text"
                    placeholder={config?.searchBarText || 'Search for topics...'}
                    className="w-full px-4 py-2 rounded-full bg-gray-800 bg-opacity-70 text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                    readOnly
                  />
                  <button className="absolute right-2 top-1/2 transform -translate-y-1/2 bg-indigo-600 p-2 rounded-full">
                    <Search className="text-white" size={16} />
                  </button>
                </div>
                
                <div className="flex flex-wrap gap-2 justify-center">
                  {config?.widgets
                    ?.filter(widget => widget.enabled)
                    .sort((a, b) => a.position - b.position)
                    .map(widget => (
                      <div key={widget.id} className="bg-gray-800 bg-opacity-70 text-white px-3 py-1 rounded-md text-sm">
                        {widget.title}
                      </div>
                    ))}
                </div>
              </div>
            </div>
          </div>
        </div>
        
        {/* Debug Panel - Remove in production */}
        <div className="mt-4 p-4 bg-gray-50 rounded-lg border border-gray-200">
          <div className="text-sm text-gray-700">
            <h3 className="font-medium mb-2">Debug Information:</h3>
            <p>Active Background: {activeBackground ? activeBackground.url : 'None'}</p>
            <p>Background Type: {displayBackground.type}</p>
            <p>Total Backgrounds: {config?.backgrounds?.length || 0}</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminPanel;
