// src/components/widgets/ResourcesWidget.jsx
import React from 'react';
import { Link } from 'react-router-dom';
import { BookOpen, ArrowRight } from 'lucide-react';

// Curated learning steps. Each points at a Learn hub slug; see /learn page.
// Keep the list short — 3 to 5 cards on the main page.
const RESOURCES = [
  {
    slug: 'profile-setup',
    title: 'Set up your profile',
    blurb: 'Your bio, market, and specialties are your first impression.',
  },
  {
    slug: 'generate-leads',
    title: 'Generate leads',
    blurb: 'Inbound, outbound, and referral tactics that actually work.',
  },
  {
    slug: 'first-open-house',
    title: 'Run your first open house',
    blurb: 'A checklist to make a strong first impression.',
  },
  {
    slug: 'negotiate-contract',
    title: 'Negotiate + get under contract',
    blurb: 'Key clauses, counters, and how to move fast.',
  },
  {
    slug: 'close-and-log',
    title: 'Close and log your first deal',
    blurb: 'Earn your first gray star — you’re officially on the board.',
  },
];

const ResourcesWidget = ({ limit = 5 }) => {
  const items = RESOURCES.slice(0, limit);
  return (
    <ul className="resources-list">
      {items.map((r) => (
        <li key={r.slug} className="resources-row">
          <Link to={`/learn/${r.slug}`} className="resources-link">
            <BookOpen size={16} className="resources-icon" />
            <div className="resources-body">
              <div className="resources-title">{r.title}</div>
              <div className="resources-blurb">{r.blurb}</div>
            </div>
            <ArrowRight size={14} />
          </Link>
        </li>
      ))}
      <style>{`
        .resources-list { list-style:none; padding:0; margin:0; display:flex; flex-direction:column; gap:6px; }
        .resources-row { border-bottom:1px solid #f1f5f9; }
        .resources-row:last-child { border-bottom:none; }
        .resources-link {
          display:flex; align-items:center; gap:10px;
          padding:10px 0; text-decoration:none; color:#0f172a;
        }
        .resources-icon { color:#7C3AED; flex-shrink:0; }
        .resources-body { flex:1; min-width:0; }
        .resources-title { font-weight:600; font-size:14px; }
        .resources-blurb { font-size:12px; color:#6b7280; }
      `}</style>
    </ul>
  );
};

export default ResourcesWidget;
