// src/contexts/PaymentContext.jsx
import React, { createContext, useContext, useState, useEffect } from 'react';
import { Elements } from '@stripe/react-stripe-js';
import { getStripeInstance } from '../services/StripeInitializer.js';
import { useAuth } from '../contexts/AuthContext';
import { doc, getDoc, onSnapshot, collection, query, where, limit, getDocs } from 'firebase/firestore';
import { getFunctions, httpsCallable } from 'firebase/functions';
import { db } from '../firebase';
import { checkPremiumAccess } from '../services/StripeService.js';
// PAYMENT_PROXY_URL import removed since payment proxy is disabled

// Create context
const PaymentContext = createContext();

/**
 * PaymentProvider - Context provider for payment-related functionality
 * 
 * Initializes Stripe and provides payment-related state and functions
 */
export const PaymentProvider = ({ children }) => {
  const { currentUser } = useAuth();
  const [stripePromise, setStripePromise] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isPremium, setIsPremium] = useState(false);
  const [premiumExpires, setPremiumExpires] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState(null);
  const [error, setError] = useState(null);
  
  // Initialize Stripe
  useEffect(() => {
    const initializeStripe = async () => {
      try {
        setLoading(true);
        const stripe = await getStripeInstance();
        setStripePromise(stripe);
        setLoading(false);
      } catch (err) {
        console.error('Error initializing Stripe:', err);
        setError('Failed to initialize payment system');
        setLoading(false);
      }
    };
    
    initializeStripe();
  }, []);
  
  // Check premium status when user changes
  useEffect(() => {
    if (!currentUser) {
      setIsPremium(false);
      setPremiumExpires(null);
      setPaymentMethod(null);
      return;
    }
    
    const checkStatus = async () => {
      try {
        // Check premium status
        const isPremiumUser = await checkPremiumAccess(currentUser.uid);
        setIsPremium(isPremiumUser);
        
        // Get user details including premium expiration
        const userRef = doc(db, 'users', currentUser.uid);
        
        // Set up listener for premium status changes
        const unsubscribe = onSnapshot(userRef, (docSnap) => {
          if (docSnap.exists()) {
            const userData = docSnap.data();
            setIsPremium(userData.isPremium === true);
            
            if (userData.premiumExpires) {
              setPremiumExpires(userData.premiumExpires.toDate());
            } else {
              setPremiumExpires(null);
            }
            
            // Skip payment method check for now since proxy is not available
            // if (userData.stripeCustomerId) {
            //   checkPaymentMethod(userData.stripeCustomerId);
            // }
          }
        }, (err) => {
          console.error('Error listening to user document:', err);
        });
        
        return unsubscribe;
      } catch (err) {
        console.error('Error checking premium status:', err);
      }
    };
    
    const unsubscribe = checkStatus();
    return () => {
      if (unsubscribe && typeof unsubscribe === 'function') {
        unsubscribe();
      }
    };
  }, [currentUser]);
  
  // DISABLED: Check if the user has a saved payment method using Cloud Run proxy
  // This function is disabled since payment proxy is not currently in use
  const checkPaymentMethod = async (customerId) => {
    console.log('Payment method check disabled - payment proxy not in use');
    setPaymentMethod(null);
    return;
    
    // The original implementation is commented out below:
    /*
    if (!currentUser || !customerId) return;
    
    try {
      console.log('=== PAYMENT METHOD CHECK START ===');
      console.log('Checking payment methods for customer:', customerId);
      console.log('Using Cloud Run proxy endpoint:', PAYMENT_PROXY_URL);
      
      // ... rest of the original payment method check code ...
    } catch (err) {
      console.log('Payment method check error (expected since proxy is disabled):', err.message);
      setPaymentMethod(null);
    }
    */
  };
  
  // Check if user has access to a specific stream
  const checkStreamAccess = async (streamId) => {
    if (!currentUser || !streamId) {
      return { hasAccess: false };
    }
    
    try {
      // First check if user is premium, which grants access to all content
      if (isPremium) {
        return { hasAccess: true, level: 'premium', isPremiumMember: true };
      }
      
      // Otherwise check for specific stream access
      const accessRef = doc(db, 'users', currentUser.uid, 'streamAccess', streamId);
      const accessDoc = await getDoc(accessRef);
      
      if (accessDoc.exists()) {
        const accessData = accessDoc.data();
        const now = new Date();
        const expiresAt = accessData.expiresAt?.toDate() || now;
        
        return {
          hasAccess: accessData.level === 'premium' && expiresAt > now,
          level: accessData.level,
          expiresAt: expiresAt
        };
      }
      
      return { hasAccess: false };
    } catch (err) {
      console.error('Error checking stream access:', err);
      return { hasAccess: false, error: err.message };
    }
  };
  
  // Format payment method for display
  const formatPaymentMethod = (method) => {
    if (!method) return null;
    
    // Format credit card
    if (method.type === 'card') {
      return {
        type: 'card',
        brand: method.card.brand,
        last4: method.card.last4,
        expMonth: method.card.exp_month,
        expYear: method.card.exp_year,
        displayName: `${method.card.brand} •••• ${method.card.last4}`
      };
    }
    
    return {
      type: method.type,
      displayName: `Payment method (${method.type})`
    };
  };
  
  // Calculate days remaining in premium subscription
  const getPremiumDaysRemaining = () => {
    if (!isPremium || !premiumExpires) return 0;
    
    const now = new Date();
    const diff = premiumExpires.getTime() - now.getTime();
    return Math.max(0, Math.ceil(diff / (1000 * 60 * 60 * 24)));
  };
  
  const value = {
    stripePromise,
    loading,
    isPremium,
    premiumExpires,
    premiumDaysRemaining: getPremiumDaysRemaining(),
    paymentMethod: formatPaymentMethod(paymentMethod),
    error,
    checkStreamAccess
  };
  
  return (
    <PaymentContext.Provider value={value}>
      {stripePromise ? (
        <Elements stripe={stripePromise}>
          {children}
        </Elements>
      ) : (
        children
      )}
    </PaymentContext.Provider>
  );
};

// Custom hook to use the payment context
export const usePayment = () => {
  const context = useContext(PaymentContext);
  if (context === undefined) {
    throw new Error('usePayment must be used within a PaymentProvider');
  }
  return context;
};