// src/utils/stars.js
//
// Single source of truth for the talkstud.io real-estate star system.
//
// Rules (from REAL_ESTATE_PIVOT_PLAN.md §5):
//   - Gold   : >= 100 closed deals
//   - Purple : >=  10 closed deals
//   - Gray   : >=   1 closed deal
//   - None   :     0 closed deals
//
// Stars are awarded only for deals whose status === 'closed'.
// The UI should always derive the tier locally (not trust a denormalized
// field) so a stale users/{uid}.starTier can never show a wrong badge.

export const STAR_TIERS = Object.freeze({
  NONE: 'none',
  GRAY: 'gray',
  PURPLE: 'purple',
  GOLD: 'gold',
});

export const STAR_THRESHOLDS = Object.freeze({
  [STAR_TIERS.GRAY]: 1,
  [STAR_TIERS.PURPLE]: 10,
  [STAR_TIERS.GOLD]: 100,
});

export const STAR_COLORS = Object.freeze({
  [STAR_TIERS.NONE]: '#D1D5DB',   // tailwind gray-300, used when count === 0
  [STAR_TIERS.GRAY]: '#9CA3AF',   // tailwind gray-400
  [STAR_TIERS.PURPLE]: '#7C3AED', // tailwind violet-600
  [STAR_TIERS.GOLD]: '#F59E0B',   // tailwind amber-500
});

export const STAR_LABELS = Object.freeze({
  [STAR_TIERS.NONE]: 'No deals yet',
  [STAR_TIERS.GRAY]: 'Closed 1+ deals',
  [STAR_TIERS.PURPLE]: 'Closed 10+ deals',
  [STAR_TIERS.GOLD]: 'Closed 100+ deals',
});

/**
 * Derive the star tier for a given closed-deal count.
 *
 * @param {number|null|undefined} closedDealCount - integer >= 0
 * @returns {'none'|'gray'|'purple'|'gold'}
 */
export function deriveStarTier(closedDealCount) {
  const n = Number(closedDealCount);
  if (!Number.isFinite(n) || n <= 0) return STAR_TIERS.NONE;
  if (n >= STAR_THRESHOLDS[STAR_TIERS.GOLD]) return STAR_TIERS.GOLD;
  if (n >= STAR_THRESHOLDS[STAR_TIERS.PURPLE]) return STAR_TIERS.PURPLE;
  if (n >= STAR_THRESHOLDS[STAR_TIERS.GRAY]) return STAR_TIERS.GRAY;
  return STAR_TIERS.NONE;
}

/**
 * How many more closed deals until the next tier, or null if already gold.
 *
 * @param {number} closedDealCount
 * @returns {{ nextTier: string, remaining: number } | null}
 */
export function nextTierProgress(closedDealCount) {
  const n = Math.max(0, Number(closedDealCount) || 0);
  if (n >= STAR_THRESHOLDS[STAR_TIERS.GOLD]) return null;
  if (n >= STAR_THRESHOLDS[STAR_TIERS.PURPLE]) {
    return {
      nextTier: STAR_TIERS.GOLD,
      remaining: STAR_THRESHOLDS[STAR_TIERS.GOLD] - n,
    };
  }
  if (n >= STAR_THRESHOLDS[STAR_TIERS.GRAY]) {
    return {
      nextTier: STAR_TIERS.PURPLE,
      remaining: STAR_THRESHOLDS[STAR_TIERS.PURPLE] - n,
    };
  }
  return {
    nextTier: STAR_TIERS.GRAY,
    remaining: STAR_THRESHOLDS[STAR_TIERS.GRAY] - n,
  };
}

/**
 * Read a user doc's star tier. Prefer the denormalized field if present and
 * consistent with closedDealCount; otherwise fall back to local derivation.
 *
 * @param {{ starTier?: string, closedDealCount?: number }} userDoc
 * @returns {'none'|'gray'|'purple'|'gold'}
 */
export function starTierFromUserDoc(userDoc) {
  if (!userDoc) return STAR_TIERS.NONE;
  const derived = deriveStarTier(userDoc.closedDealCount);
  const stored = userDoc.starTier;
  // If storage matches derivation, trust storage; otherwise derive fresh.
  if (stored && Object.values(STAR_TIERS).includes(stored) && stored === derived) {
    return stored;
  }
  return derived;
}
