// src/components/widgets/DealActivityWidget.jsx
import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import {
  getFirestore,
  collection,
  query,
  where,
  orderBy,
  limit as qLimit,
  onSnapshot,
} from 'firebase/firestore';
import { MapPin } from 'lucide-react';
import StarBadge from '../stars/StarBadge';

const STATUS_CHIPS = {
  listed: { label: 'Listed', bg: '#e2e8f0', fg: '#334155' },
  under_contract: { label: 'Under contract', bg: '#cffafe', fg: '#0e7490' },
  closed: { label: 'Closed', bg: '#dcfce7', fg: '#166534' },
  cancelled: { label: 'Cancelled', bg: '#f3f4f6', fg: '#6b7280' },
};

function formatPrice(price) {
  const n = Number(price);
  if (!Number.isFinite(n) || n <= 0) return '—';
  if (n >= 1_000_000) return `$${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}M`;
  if (n >= 1_000) return `$${Math.round(n / 1_000)}K`;
  return `$${n.toLocaleString()}`;
}

/**
 * Live feed of recent public deals across the site.
 * Shows who closed/listed, city+state (public view), price, and star tier.
 */
const DealActivityWidget = ({ limitCount = 10 }) => {
  const [deals, setDeals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const db = getFirestore();
    const q = query(
      collection(db, 'deals'),
      where('visibility', '==', 'public'),
      orderBy('createdAt', 'desc'),
      qLimit(limitCount)
    );
    const unsub = onSnapshot(
      q,
      (snap) => {
        setDeals(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
        setLoading(false);
      },
      (err) => {
        console.warn('DealActivityWidget error:', err.message);
        setError('Deal feed not available yet.');
        setLoading(false);
      }
    );
    return () => unsub();
  }, [limitCount]);

  if (loading) return <div className="widget-empty">Loading deals…</div>;
  if (error) return <div className="widget-empty">{error}</div>;
  if (deals.length === 0) {
    return (
      <div className="widget-empty">
        No deals yet. Be the first to log one on your profile.
      </div>
    );
  }

  return (
    <ul className="deal-activity-list">
      {deals.map((deal) => {
        const chip = STATUS_CHIPS[deal.status] || STATUS_CHIPS.listed;
        const loc = [deal.address?.city, deal.address?.state].filter(Boolean).join(', ');
        return (
          <li key={deal.id} className="deal-activity-row">
            <div className="deal-activity-main">
              <Link to={`/agent/${deal.agentId}`} className="deal-activity-agent">
                {deal.agentName || 'Agent'}
              </Link>
              <div className="deal-activity-meta">
                <span
                  className="deal-activity-chip"
                  style={{ background: chip.bg, color: chip.fg }}
                >
                  {chip.label}
                </span>
                <span className="deal-activity-loc">
                  <MapPin size={12} /> {loc || '—'}
                </span>
                <span className="deal-activity-price">{formatPrice(deal.price)}</span>
              </div>
              {deal.note && <div className="deal-activity-note">{deal.note}</div>}
            </div>
            {deal.status === 'closed' && (
              <StarBadge tier="gray" size="sm" title="Closed deal — star earned" />
            )}
          </li>
        );
      })}
      <style>{`
        .deal-activity-list {
          list-style: none;
          padding: 0;
          margin: 0;
          display: flex;
          flex-direction: column;
          gap: 10px;
        }
        .deal-activity-row {
          display: flex;
          justify-content: space-between;
          align-items: flex-start;
          gap: 10px;
          padding: 10px 0;
          border-bottom: 1px solid #f1f5f9;
        }
        .deal-activity-row:last-child { border-bottom: none; }
        .deal-activity-agent {
          font-weight: 600;
          color: #0f172a;
          text-decoration: none;
        }
        .deal-activity-meta {
          display: flex;
          flex-wrap: wrap;
          gap: 8px;
          align-items: center;
          margin-top: 4px;
          font-size: 12px;
        }
        .deal-activity-chip {
          padding: 2px 8px;
          border-radius: 999px;
          font-weight: 600;
        }
        .deal-activity-loc {
          color: #4b5563;
          display: inline-flex;
          align-items: center;
          gap: 4px;
        }
        .deal-activity-price {
          color: #0f172a;
          font-weight: 600;
        }
        .deal-activity-note {
          margin-top: 4px;
          font-size: 13px;
          color: #1f2937;
        }
        .widget-empty {
          text-align: center;
          color: #6b7280;
          padding: 24px 8px;
          font-size: 14px;
        }
      `}</style>
    </ul>
  );
};

export default DealActivityWidget;
