// src/components/debug/FirebaseInitializationAnalyzer.jsx
import React, { useState, useEffect } from 'react';
import { createTimingContext } from '../../utils/performance-monitor';

// Import services to test initialization
import { 
  getDb, 
  getRtdb, 
  getAuthInstance, 
  getStorageInstance, 
  getFunctionsInstance 
} from '../../firebase';

// Timing context for test initializations
const testPerformance = createTimingContext('firebase_init_test');

const FirebaseInitializationAnalyzer = () => {
  const [testResults, setTestResults] = useState({
    running: false,
    completed: false,
    results: {}
  });
  
  const [expanded, setExpanded] = useState(true);
  const [serviceToTest, setServiceToTest] = useState('all');
  
  // Run performance tests on specific Firebase services
  const runTests = async () => {
    setTestResults({
      running: true,
      completed: false,
      results: {}
    });
    
    const results = {};
    
    try {
      // Test Firestore initialization
      if (serviceToTest === 'firestore' || serviceToTest === 'all') {
        testPerformance.start('firestore_init');
        const db = getDb();
        testPerformance.end('firestore_init');
        
        results.firestore = {
          name: 'Firestore',
          duration: testPerformance.getAll()['firebase_init_test:firestore_init']?.duration || 0,
          success: Boolean(db)
        };
      }
      
      // Test RTDB initialization
      if (serviceToTest === 'rtdb' || serviceToTest === 'all') {
        testPerformance.start('rtdb_init');
        const rtdb = getRtdb();
        testPerformance.end('rtdb_init');
        
        results.rtdb = {
          name: 'Realtime Database',
          duration: testPerformance.getAll()['firebase_init_test:rtdb_init']?.duration || 0,
          success: Boolean(rtdb)
        };
      }
      
      // Test Auth initialization
      if (serviceToTest === 'auth' || serviceToTest === 'all') {
        testPerformance.start('auth_init');
        const auth = getAuthInstance();
        testPerformance.end('auth_init');
        
        results.auth = {
          name: 'Authentication',
          duration: testPerformance.getAll()['firebase_init_test:auth_init']?.duration || 0,
          success: Boolean(auth)
        };
      }
      
      // Test Storage initialization
      if (serviceToTest === 'storage' || serviceToTest === 'all') {
        testPerformance.start('storage_init');
        const storage = getStorageInstance();
        testPerformance.end('storage_init');
        
        results.storage = {
          name: 'Storage',
          duration: testPerformance.getAll()['firebase_init_test:storage_init']?.duration || 0,
          success: Boolean(storage)
        };
      }
      
      // Test Functions initialization
      if (serviceToTest === 'functions' || serviceToTest === 'all') {
        testPerformance.start('functions_init');
        const functions = getFunctionsInstance();
        testPerformance.end('functions_init');
        
        results.functions = {
          name: 'Cloud Functions',
          duration: testPerformance.getAll()['firebase_init_test:functions_init']?.duration || 0,
          success: Boolean(functions)
        };
      }
      
      // Sort results by duration (slowest first)
      const sortedResults = Object.values(results).sort((a, b) => b.duration - a.duration);
      
      setTestResults({
        running: false,
        completed: true,
        results: sortedResults
      });
    } catch (error) {
      console.error('Error in Firebase initialization tests:', error);
      
      setTestResults({
        running: false,
        completed: true,
        error: error.message,
        results: results
      });
    }
  };
  
  const toggleExpanded = () => {
    setExpanded(!expanded);
  };
  
  const handleServiceSelect = (e) => {
    setServiceToTest(e.target.value);
  };
  
  // Render the analyzer panel
  return (
    <div 
      style={{
        position: 'fixed',
        top: '20px',
        right: '20px',
        width: expanded ? '400px' : '200px',
        backgroundColor: 'rgba(0, 0, 0, 0.8)',
        color: 'white',
        borderRadius: '4px',
        zIndex: 9999,
        boxShadow: '0 2px 8px rgba(0, 0, 0, 0.2)',
        transition: 'all 0.3s ease',
        fontFamily: 'system-ui, -apple-system, sans-serif'
      }}
    >
      <div 
        style={{
          padding: '10px',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          borderBottom: '1px solid rgba(255, 255, 255, 0.2)',
          cursor: 'pointer'
        }}
        onClick={toggleExpanded}
      >
        <div>🔥 Firebase Initialization Analyzer</div>
        <div>{expanded ? '▼' : '▲'}</div>
      </div>
      
      {expanded && (
        <div style={{ padding: '15px' }}>
          <div style={{ marginBottom: '15px' }}>
            <div style={{ marginBottom: '10px' }}>
              <label style={{ marginRight: '10px' }}>Service to test:</label>
              <select 
                value={serviceToTest}
                onChange={handleServiceSelect}
                style={{
                  background: '#333',
                  color: 'white',
                  border: '1px solid #555',
                  padding: '5px',
                  borderRadius: '3px'
                }}
              >
                <option value="all">All Services</option>
                <option value="firestore">Firestore</option>
                <option value="rtdb">Realtime Database</option>
                <option value="auth">Authentication</option>
                <option value="storage">Storage</option>
                <option value="functions">Cloud Functions</option>
              </select>
            </div>
            
            <button 
              onClick={runTests}
              disabled={testResults.running}
              style={{
                background: testResults.running ? '#555' : '#4285F4',
                color: 'white',
                border: 'none',
                padding: '8px 15px',
                borderRadius: '3px',
                cursor: testResults.running ? 'not-allowed' : 'pointer',
                width: '100%'
              }}
            >
              {testResults.running ? 'Testing...' : 'Run Initialization Test'}
            </button>
          </div>
          
          {testResults.error && (
            <div 
              style={{
                backgroundColor: 'rgba(255, 0, 0, 0.2)',
                padding: '10px',
                borderRadius: '3px',
                marginBottom: '15px'
              }}
            >
              Error: {testResults.error}
            </div>
          )}
          
          {testResults.completed && testResults.results.length > 0 && (
            <div>
              <h4 style={{ margin: '0 0 10px 0', fontSize: '16px' }}>Results</h4>
              
              {testResults.results.map((result, index) => {
                // Determine color based on duration
                let color = '#4CAF50'; // Fast (< 100ms)
                if (result.duration > 1000) {
                  color = '#F44336'; // Very slow (> 1s)
                } else if (result.duration > 500) {
                  color = '#FF9800'; // Slow (> 500ms)
                } else if (result.duration > 100) {
                  color = '#FFEB3B'; // Medium (> 100ms)
                }
                
                return (
                  <div 
                    key={index}
                    style={{
                      display: 'flex',
                      justifyContent: 'space-between',
                      padding: '8px',
                      borderRadius: '3px',
                      marginBottom: '5px',
                      backgroundColor: 'rgba(255, 255, 255, 0.1)'
                    }}
                  >
                    <div>{result.name}</div>
                    <div style={{ color }}>
                      {result.duration.toFixed(2)}ms
                    </div>
                  </div>
                );
              })}
              
              <div style={{ marginTop: '15px', fontSize: '13px' }}>
                <strong>Recommendation:</strong> 
                {testResults.results.some(r => r.duration > 1000) ? (
                  <div style={{ color: '#F44336' }}>
                    Initialize Firebase services on-demand using the optimized accessor functions 
                    provided in firebase.js rather than importing them directly.
                  </div>
                ) : (
                  <div style={{ color: '#4CAF50' }}>
                    Firebase initialization is performing within acceptable limits.
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default FirebaseInitializationAnalyzer;