import { useEffect } from 'react';
import { useLocation } from 'react-router-dom';

import {
  SEO_BY_PATH,
  SEO_ROUTES,
  SITE_URL,
  DEFAULT_TITLE,
  DEFAULT_DESCRIPTION,
  formatTitle,
  canonicalUrl,
} from './siteMeta.js';

/**
 * Keeps <title>, the meta description and the canonical link in step with the
 * current route.
 *
 * The build already bakes correct metadata into each generated page
 * (scripts/generate-seo.js), which is what a crawler reads on first fetch.
 * This hook covers the other half: once the SPA takes over navigation, the
 * head would otherwise keep whichever page the visitor happened to land on.
 * That matters for Google's render pass, for browser tabs and history, and for
 * anything that reads the live DOM.
 *
 * Routes not listed in SEO_ROUTES (auth pages, rooms, debug views) fall back to
 * the site defaults and are marked noindex — they should never become search
 * results, and robots.txt alone won't stop a URL that gets linked to.
 */

function upsertMeta(selector, attrName, attrValue, content) {
  let el = document.head.querySelector(selector);
  if (!el) {
    el = document.createElement('meta');
    el.setAttribute(attrName, attrValue);
    document.head.appendChild(el);
  }
  el.setAttribute('content', content);
}

function upsertCanonical(href) {
  let el = document.head.querySelector('link[rel="canonical"]');
  if (!el) {
    el = document.createElement('link');
    el.setAttribute('rel', 'canonical');
    document.head.appendChild(el);
  }
  el.setAttribute('href', href);
}

/** Longest-prefix match, so /predict/leaderboard inherits /predict's metadata. */
function resolveRoute(pathname) {
  const normalized =
    pathname.length > 1 && pathname.endsWith('/') ? pathname.slice(0, -1) : pathname;

  if (SEO_BY_PATH[normalized]) return SEO_BY_PATH[normalized];

  return (
    SEO_ROUTES.filter(
      (route) => route.path !== '/' && normalized.startsWith(`${route.path}/`)
    ).sort((a, b) => b.path.length - a.path.length)[0] || null
  );
}

export default function useRouteSeo() {
  const { pathname } = useLocation();

  useEffect(() => {
    const route = resolveRoute(pathname);

    const title = route ? formatTitle(route) : DEFAULT_TITLE;
    const description = route ? route.description : DEFAULT_DESCRIPTION;

    document.title = title;
    upsertMeta('meta[name="description"]', 'name', 'description', description);
    upsertMeta('meta[property="og:title"]', 'property', 'og:title', title);
    upsertMeta('meta[property="og:description"]', 'property', 'og:description', description);
    upsertMeta('meta[property="og:url"]', 'property', 'og:url', `${SITE_URL}${pathname}`);

    // Only pages we deliberately publish are indexable. A sub-path that merely
    // inherits a parent's copy (e.g. /predict/42) is not a page we've written
    // metadata for, so it points its canonical at the parent instead.
    const indexable = Boolean(route);
    upsertMeta(
      'meta[name="robots"]',
      'name',
      'robots',
      indexable
        ? 'index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1'
        : 'noindex, follow'
    );

    if (route) {
      upsertCanonical(canonicalUrl(route.path));
    } else {
      upsertCanonical(`${SITE_URL}${pathname}`);
    }
  }, [pathname]);
}
