// src/components/chat/ChatRoomWithStreaming.jsx
import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getFirestore, doc, getDoc, updateDoc, onSnapshot, collection, addDoc, serverTimestamp, query, orderBy, limit } from 'firebase/firestore';
import { getDatabase, ref, onValue, off, push } from 'firebase/database';
import { useAuth } from '../../contexts/AuthContext';
import { useStreamingLiveKit as useStreaming } from '../../contexts/StreamingContextLiveKit';
import ChatMessageList from './ChatMessageList';
import ChatMessageInput from './ChatMessageInput';
import StreamControlPanel from '../streaming/StreamControlPanel';
import StreamsPanel from '../streaming/StreamsPanel';
import VideoStream from '../streaming/VideoStream';
import { Video, VideoOff, Users, X, ChevronLeft, ChevronRight } from 'lucide-react';

const ChatRoomWithStreaming = () => {
  const { roomId } = useParams();
  const { currentUser } = useAuth();
  const { 
    userStreamPermission, 
    isStreaming, 
    startStreamingInRoom, 
    stopStreamingInRoom,
    getActiveRoomStreamers,
    roomActiveStreamers
  } = useStreaming();
  const navigate = useNavigate();
  
  const [room, setRoom] = useState(null);
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  
  const [showStreaming, setShowStreaming] = useState(true);
  const [showStreamPanel, setShowStreamPanel] = useState(true);
  const [maximizedStream, setMaximizedStream] = useState(null);
  
  // WebRTC state
  const [localStream, setLocalStream] = useState(null);
  const [remoteStreams, setRemoteStreams] = useState({});
  const [peers, setPeers] = useState([]);
  const [activeStreamers, setActiveStreamers] = useState([]);
  const [mediaInitialized, setMediaInitialized] = useState(false);
  
  // Refs
  const webRTCServiceRef = useRef(null);
  
  // Load room data
  useEffect(() => {
    const fetchRoom = async () => {
      try {
        setLoading(true);
        console.log('Attempting to load room with ID:', roomId);
        
        let roomData = null;
        let dataSource = null;
        
        // Try Firebase Realtime Database first (at 'chats/public/' path)
        try {
          console.log('Checking Realtime Database for room...');
          const rtdb = getDatabase();
          const rtdbRoomRef = ref(rtdb, `chats/public/${roomId}`);
          
          // Get room data from Realtime Database
          const snapshot = await new Promise((resolve, reject) => {
            onValue(rtdbRoomRef, resolve, reject, { onlyOnce: true });
          });
          
          if (snapshot.exists()) {
            roomData = {
              id: roomId,
              ...snapshot.val(),
              source: 'rtdb',
              rtdbPath: `chats/public/${roomId}`
            };
            dataSource = 'rtdb';
            console.log('Found room in Realtime Database:', roomData.name);
          }
        } catch (rtdbErr) {
          console.log('Error getting room from Realtime Database:', rtdbErr);
        }
        
        // If not found in RTDB, try Firestore collections
        if (!roomData) {
          const db = getFirestore();
          const collections = ['rooms', 'publicChats', 'chatRooms'];
          
          for (const collectionName of collections) {
            try {
              console.log(`Checking Firestore collection '${collectionName}' for room...`);
              const roomRef = doc(db, collectionName, roomId);
              const roomSnapshot = await getDoc(roomRef);
              
              if (roomSnapshot.exists()) {
                roomData = {
                  id: roomSnapshot.id,
                  ...roomSnapshot.data(),
                  source: 'firestore',
                  collectionName
                };
                dataSource = 'firestore';
                console.log(`Found room in Firestore collection '${collectionName}'`, roomData.name);
                break;
              }
            } catch (firestoreErr) {
              console.log(`Error checking ${collectionName} collection:`, firestoreErr);
            }
          }
        }
        
        if (!roomData) {
          setError('Room not found. Please check the room ID and try again.');
          setLoading(false);
          return;
        }
        
        // Set the room data
        console.log('Setting room data:', roomData);
        setRoom(roomData);
        
        // Set up real-time listener based on data source
        let unsubscribe;
        
        if (dataSource === 'rtdb') {
          // For Realtime Database
          const rtdb = getDatabase();
          const rtdbRoomRef = ref(rtdb, `chats/public/${roomId}`);
          
          // Set up the listener
          const rtdbCallback = (snapshot) => {
            if (snapshot.exists()) {
              setRoom({
                id: roomId,
                ...snapshot.val(),
                source: 'rtdb',
                rtdbPath: `chats/public/${roomId}`
              });
            } else {
              setError('This room no longer exists');
              navigate('/rooms');
            }
          };
          
          onValue(rtdbRoomRef, rtdbCallback);
          unsubscribe = () => off(rtdbRoomRef, 'value', rtdbCallback);
        } else {
          // For Firestore
          const db = getFirestore();
          const collectionName = roomData.collectionName;
          unsubscribe = onSnapshot(doc(db, collectionName, roomId), (docSnapshot) => {
            if (docSnapshot.exists()) {
              setRoom({
                id: docSnapshot.id,
                ...docSnapshot.data(),
                source: 'firestore',
                collectionName
              });
            } else {
              setError('This room no longer exists');
              navigate('/rooms');
            }
          });
        }
        
        setLoading(false);
        return unsubscribe;
      } catch (err) {
        console.error('Error loading room:', err);
        setError('Failed to load room: ' + err.message);
        setLoading(false);
      }
    };
    
    if (roomId) {
      fetchRoom();
    }
  }, [roomId, navigate]);
  
  // Load messages
  useEffect(() => {
    if (!roomId || !room) return;
    
    const fetchMessages = async () => {
      console.log('Fetching messages for room:', roomId, 'from source:', room.source);
      
      // Handle different data sources
      if (room.source === 'rtdb') {
        // For Realtime Database
        const rtdb = getDatabase();
        const messagesRef = ref(rtdb, `chats/public/${roomId}/messages`);
        
        // Set up listener for messages
        const messagesCallback = (snapshot) => {
          if (snapshot.exists()) {
            const messagesList = [];
            snapshot.forEach((childSnapshot) => {
              messagesList.push({
                id: childSnapshot.key,
                ...childSnapshot.val()
              });
            });
            
            // Sort by timestamp
            messagesList.sort((a, b) => {
              return (a.timestamp || 0) - (b.timestamp || 0);
            });
            
            setMessages(messagesList);
          } else {
            setMessages([]);
          }
        };
        
        onValue(messagesRef, messagesCallback);
        return () => off(messagesRef, 'value', messagesCallback);
      } else {
        // For Firestore
        const db = getFirestore();
        const collectionName = room.collectionName || 'rooms';
        
        // Try the collection specified in the room data
        let messagesCollection = collection(db, collectionName, roomId, 'messages');
        let messagesQuery = query(
          messagesCollection,
          orderBy('timestamp', 'desc'),
          limit(50)
        );
        
        try {
          // Check if this query works
          await getDoc(doc(db, collectionName, roomId));
          console.log('Confirmed room exists in', collectionName);
        } catch (err) {
          console.log('Error accessing messages in', collectionName, err);
          
          // If not, try each collection in sequence
          const collections = ['rooms', 'publicChats', 'chatRooms'];
          let found = false;
          
          for (const col of collections) {
            if (col === collectionName) continue; // Skip the one we already tried
            
            try {
              const roomDoc = await getDoc(doc(db, col, roomId));
              if (roomDoc.exists()) {
                messagesCollection = collection(db, col, roomId, 'messages');
                messagesQuery = query(
                  messagesCollection,
                  orderBy('timestamp', 'desc'),
                  limit(50)
                );
                found = true;
                console.log('Found messages in alternate collection:', col);
                break;
              }
            } catch (innerErr) {
              console.log(`Couldn't find room in ${col}:`, innerErr);
            }
          }
          
          if (!found) {
            console.error('Could not find messages in any collection');
          }
        }
        
        // Set up Firestore listener
        const unsubscribe = onSnapshot(messagesQuery, (snapshot) => {
          const messagesList = [];
          snapshot.forEach((doc) => {
            messagesList.push({
              id: doc.id,
              ...doc.data()
            });
          });
          
          // Sort by timestamp (oldest first)
          messagesList.sort((a, b) => {
            const timestampA = a.timestamp?.toDate ? a.timestamp.toDate() : new Date();
            const timestampB = b.timestamp?.toDate ? b.timestamp.toDate() : new Date();
            return timestampA - timestampB;
          });
          
          setMessages(messagesList);
        });
        
        return unsubscribe;
      }
    };
    
    return fetchMessages();
  }, [roomId, room]);
  
  // Initialize streaming context
  useEffect(() => {
    if (!roomId || !currentUser) return;
    
    const fetchActiveStreamers = async () => {
      try {
        const unsubscribe = await getActiveRoomStreamers(roomId);
        return unsubscribe;
      } catch (err) {
        console.error('Error fetching active streamers:', err);
      }
    };
    
    fetchActiveStreamers();
    
    return () => {
      // Clean up WebRTC connections on unmount
      if (webRTCServiceRef.current) {
        webRTCServiceRef.current.cleanup();
      }
      
      // Stop local stream
      if (localStream) {
        localStream.getTracks().forEach(track => track.stop());
      }
    };
  }, [roomId, currentUser, getActiveRoomStreamers]);
  
  // Track active streamers
  useEffect(() => {
    if (roomActiveStreamers) {
      setActiveStreamers(roomActiveStreamers);
    }
  }, [roomActiveStreamers]);
  
  // Handle starting a stream
  const handleStartStream = async (stream) => {
    try {
      setLocalStream(stream);
      
      // Update streaming state in context
      await startStreamingInRoom(roomId, stream);
    } catch (err) {
      console.error('Error starting stream:', err);
      setError(`Failed to start streaming: ${err.message}`);
    }
  };
  
  // Handle stopping a stream
  const handleStopStream = async () => {
    try {
      // Stop local stream tracks
      if (localStream) {
        localStream.getTracks().forEach(track => track.stop());
        setLocalStream(null);
      }
      
      // Update streaming state in context
      await stopStreamingInRoom(roomId);
    } catch (err) {
      console.error('Error stopping stream:', err);
      setError(`Failed to stop streaming: ${err.message}`);
    }
  };
  
  // Handle sending a message
  const handleSendMessage = async (text) => {
    if (!text.trim() || !roomId || !currentUser || !room) return;
    
    try {
      // Determine where to send message based on room source
      if (room.source === 'rtdb') {
        // Send to Realtime Database
        const rtdb = getDatabase();
        const messagesRef = ref(rtdb, `chats/public/${roomId}/messages`);
        const newMessageRef = push(messagesRef);
        
        const newMessage = {
          text,
          userId: currentUser.uid,
          displayName: currentUser.displayName || 'Anonymous',
          photoURL: currentUser.photoURL || null,
          timestamp: Date.now(),
          isAnonymous: currentUser.isAnonymous || false
        };
        
        await set(newMessageRef, newMessage);
        
        // Update room's last activity
        const roomRef = ref(rtdb, `chats/public/${roomId}`);
        await update(roomRef, {
          lastActivity: Date.now(),
          lastMessage: text.slice(0, 100),
          lastMessageUser: currentUser.displayName || 'Anonymous'
        });
      } else {
        // Send to Firestore
        const db = getFirestore();
        
        const newMessage = {
          text,
          userId: currentUser.uid,
          displayName: currentUser.displayName || 'Anonymous',
          photoURL: currentUser.photoURL || null,
          timestamp: serverTimestamp(),
          isAnonymous: currentUser.isAnonymous || false
        };
        
        // Try to determine which collection to use
        const collectionName = room.collectionName || 'rooms';
        const collectionPath = collection(db, collectionName, roomId, 'messages');
        
        await addDoc(collectionPath, newMessage);
        
        // Update room's last activity
        const roomRef = doc(db, collectionName, roomId);
        await updateDoc(roomRef, {
          lastActivity: serverTimestamp()
        });
      }
    } catch (err) {
      console.error('Error sending message:', err);
      setError('Failed to send message: ' + err.message);
    }
  };
  
  // Toggle streaming section visibility
  const toggleStreamingSection = () => {
    setShowStreaming(!showStreaming);
  };
  
  // Toggle stream panel visibility
  const toggleStreamPanel = () => {
    setShowStreamPanel(!showStreamPanel);
  };
  
  // Handle maximizing a stream
  const handleMaximizeStream = (stream) => {
    setMaximizedStream(stream);
  };
  
  // Handle clearing maximized stream
  const handleClearMaximized = () => {
    setMaximizedStream(null);
  };
  
  if (loading) {
    return (
      <div className="loading-container">
        <div className="spinner"></div>
        <p>Loading room...</p>
      </div>
    );
  }
  
  if (error) {
    return (
      <div className="error-container">
        <p className="error-message">{error}</p>
        <button onClick={() => navigate('/rooms')} className="back-button">
          Back to Room List
        </button>
      </div>
    );
  }
  
  return (
    <div className="chat-room-with-streaming">
      {/* Room Header */}
      <div className="room-header">
        <h1 className="room-title">{room?.name || 'Chat Room'}</h1>
        <div className="room-actions">
          <button 
            className="stream-toggle-button"
            onClick={toggleStreamingSection}
            title={showStreaming ? 'Hide streaming section' : 'Show streaming section'}
          >
            {showStreaming ? <VideoOff size={20} /> : <Video size={20} />}
            <span>{showStreaming ? 'Hide Streaming' : 'Show Streaming'}</span>
          </button>
          
          <div className="room-stats">
            <div className="room-stat">
              <Users size={16} />
              <span>{activeStreamers.length} streaming</span>
            </div>
          </div>
        </div>
      </div>
      
      <div className={`chat-content-container ${showStreaming ? 'with-streaming' : ''}`}>
        {/* Streaming Section */}
        {showStreaming && (
          <div className="streaming-section">
            {/* Stream Control Panel */}
            <div className="stream-control-container">
              <StreamControlPanel 
                roomId={roomId}
                onStartStream={handleStartStream}
                onStopStream={handleStopStream}
              />
            </div>
            
            {/* Streams Display */}
            <div className="streams-display-container">
              {maximizedStream ? (
                <div className="maximized-stream-container">
                  <button 
                    className="close-maximized"
                    onClick={handleClearMaximized}
                  >
                    <X size={20} />
                  </button>
                  <VideoStream
                    stream={maximizedStream.stream}
                    displayName={maximizedStream.displayName}
                    photoURL={maximizedStream.photoURL}
                    hasAudio={maximizedStream.hasAudio}
                    hasVideo={maximizedStream.hasVideo}
                    isSelf={maximizedStream.isSelf}
                  />
                </div>
              ) : (
                <div className={`streams-panel-container ${showStreamPanel ? 'expanded' : 'collapsed'}`}>
                  <button 
                    className="toggle-panel-button"
                    onClick={toggleStreamPanel}
                  >
                    {showStreamPanel ? <ChevronRight size={20} /> : <ChevronLeft size={20} />}
                  </button>
                  
                  {showStreamPanel && (
                    <StreamsPanel 
                      roomId={roomId}
                      peers={peers}
                      streams={{
                        ...(localStream ? { [currentUser.uid]: localStream } : {}),
                        ...remoteStreams
                      }}
                      onMaximize={handleMaximizeStream}
                    />
                  )}
                </div>
              )}
            </div>
          </div>
        )}
        
        {/* Chat Section */}
        <div className="chat-section">
          <div className="messages-container">
            <ChatMessageList 
              messages={messages}
              currentUser={currentUser}
            />
          </div>
          
          <div className="message-input-container">
            <ChatMessageInput 
              onSendMessage={handleSendMessage}
              disabled={!currentUser}
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatRoomWithStreaming;