import { mockPredictions, mockUsers } from '../utils/mockData'

// Bump this whenever seed data changes materially (new taxonomy, new mock
// predictions, new user list). Clients with an older version re-seed on
// next load. Preserves the user's custom submissions by merging.
const SEED_VERSION = 'dealmaker-2026-04-v1'

const KEYS = {
  predictions: 'predict_predictions',
  users: 'predict_users',
  votes: 'predict_votes',
  initialized: 'predict_initialized',
  seedVersion: 'predict_seed_version',
}

function seed() {
  const existingVersion = localStorage.getItem(KEYS.seedVersion)
  if (localStorage.getItem(KEYS.initialized) && existingVersion === SEED_VERSION) {
    return
  }

  // Version changed (or fresh client): replace mock content, preserve any
  // user-submitted predictions (ids starting with 'user-' or not in mock set).
  let preservedUserPredictions = []
  try {
    const prior = JSON.parse(localStorage.getItem(KEYS.predictions) || '[]')
    const mockIds = new Set(mockPredictions.map(p => p.id))
    preservedUserPredictions = prior.filter(p => !mockIds.has(p.id))
  } catch { /* ignore malformed prior data */ }

  localStorage.setItem(
    KEYS.predictions,
    JSON.stringify([...mockPredictions, ...preservedUserPredictions])
  )
  localStorage.setItem(KEYS.users, JSON.stringify(mockUsers))
  // Don't clobber votes on reseed — community votes carry over.
  if (!localStorage.getItem(KEYS.votes)) {
    localStorage.setItem(KEYS.votes, JSON.stringify({}))
  }
  localStorage.setItem(KEYS.initialized, 'true')
  localStorage.setItem(KEYS.seedVersion, SEED_VERSION)
}

seed()

const storageService = {
  async getPredictions() {
    const data = localStorage.getItem(KEYS.predictions)
    return data ? JSON.parse(data) : mockPredictions
  },

  async getPrediction(id) {
    const predictions = await this.getPredictions()
    return predictions.find(p => p.id === id) || null
  },

  async savePrediction(prediction) {
    const predictions = await this.getPredictions()
    const idx = predictions.findIndex(p => p.id === prediction.id)
    if (idx >= 0) {
      predictions[idx] = prediction
    } else {
      predictions.unshift(prediction)
    }
    localStorage.setItem(KEYS.predictions, JSON.stringify(predictions))
    return prediction
  },

  async deletePrediction(id) {
    const predictions = await this.getPredictions()
    const filtered = predictions.filter(p => p.id !== id)
    localStorage.setItem(KEYS.predictions, JSON.stringify(filtered))
  },

  async getUsers() {
    const data = localStorage.getItem(KEYS.users)
    return data ? JSON.parse(data) : mockUsers
  },

  async saveVote(predictionId, userId, vote) {
    const votes = JSON.parse(localStorage.getItem(KEYS.votes) || '{}')
    votes[`${userId}_${predictionId}`] = vote
    localStorage.setItem(KEYS.votes, JSON.stringify(votes))

    const predictions = await this.getPredictions()
    const pred = predictions.find(p => p.id === predictionId)
    if (pred) {
      if (vote === 'agree') pred.communityVotes.agree++
      else pred.communityVotes.disagree++
      await this.savePrediction(pred)
    }
  },

  async getUserVote(predictionId, userId) {
    const votes = JSON.parse(localStorage.getItem(KEYS.votes) || '{}')
    return votes[`${userId}_${predictionId}`] || null
  },

  resetData() {
    localStorage.removeItem(KEYS.initialized)
    seed()
  },
}

export default storageService
