// Test component to debug artist profile issues
import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../firebase';

const FirebaseArtistTest = () => {
  const { currentUser } = useAuth();
  const [loading, setLoading] = useState(false);
  const [testResult, setTestResult] = useState('');
  const [error, setError] = useState(null);

  const testFirebaseConnection = async () => {
    setLoading(true);
    setError(null);
    setTestResult('');
    
    try {
      // Test 1: Check if db is initialized
      if (!db) {
        setError('Firebase db is not initialized');
        setLoading(false);
        return;
      }
      setTestResult(prev => prev + '✅ Firebase db is initialized\n');
      
      // Test 2: Check current user
      if (!currentUser) {
        setError('No current user logged in');
        setLoading(false);
        return;
      }
      setTestResult(prev => prev + `✅ Current user: ${currentUser.uid}\n`);
      
      // Test 3: Try to fetch user document
      const userRef = doc(db, 'users', currentUser.uid);
      setTestResult(prev => prev + 'Fetching user document...\n');
      
      const userDoc = await getDoc(userRef);
      
      if (!userDoc.exists()) {
        setError('User document does not exist');
        setLoading(false);
        return;
      }
      
      const userData = userDoc.data();
      setTestResult(prev => prev + '✅ User document found\n');
      setTestResult(prev => prev + `User data: ${JSON.stringify(userData, null, 2)}\n`);
      
      // Test 4: Check artist status
      setTestResult(prev => prev + `\nIs Artist: ${userData.isArtist === true ? 'Yes' : 'No'}\n`);
      
      setLoading(false);
    } catch (err) {
      console.error('Test error:', err);
      setError(`Error: ${err.message}`);
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: '2rem', maxWidth: '800px', margin: '0 auto' }}>
      <h2>Firebase Artist Profile Test</h2>
      
      <button 
        onClick={testFirebaseConnection}
        disabled={loading}
        style={{
          padding: '0.5rem 1rem',
          backgroundColor: '#4f46e5',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          cursor: loading ? 'not-allowed' : 'pointer',
          opacity: loading ? 0.5 : 1
        }}
      >
        {loading ? 'Testing...' : 'Test Firebase Connection'}
      </button>
      
      {error && (
        <div style={{
          marginTop: '1rem',
          padding: '1rem',
          backgroundColor: '#fee2e2',
          color: '#dc2626',
          borderRadius: '4px'
        }}>
          {error}
        </div>
      )}
      
      {testResult && (
        <pre style={{
          marginTop: '1rem',
          padding: '1rem',
          backgroundColor: '#f3f4f6',
          borderRadius: '4px',
          whiteSpace: 'pre-wrap',
          wordBreak: 'break-word'
        }}>
          {testResult}
        </pre>
      )}
    </div>
  );
};

export default FirebaseArtistTest;