// src/components/profile/Profile.jsx
import React, { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  doc,
  getDoc,
  collection,
  query,
  where,
  orderBy,
  limit as qLimit,
  getDocs,
} from 'firebase/firestore';
import { db } from '../../firebase';
import { useAuth } from '../../contexts/AuthContext';
import Feed from '../posts/Feed';
import StarBadge from '../stars/StarBadge';
import DealCard from '../deals/DealCard';
import CreateDealModal from '../deals/CreateDealModal';
import TrackCard from '../audio/TrackCard';
import { useJamPlayer } from '../../hooks/useJamPlayer';
import { listJamsByUser } from '../../services/jamService';
import { starTierFromUserDoc, nextTierProgress } from '../../utils/stars';
import './Profile.css';

const TABS = ['deals', 'music', 'events', 'posts', 'about'];

const Profile = () => {
  const { userId } = useParams();
  const navigate = useNavigate();
  const { currentUser } = useAuth();
  const [userProfile, setUserProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [activeTab, setActiveTab] = useState('deals');
  const [deals, setDeals] = useState([]);
  const [dealsLoading, setDealsLoading] = useState(false);
  const [logDealOpen, setLogDealOpen] = useState(false);
  const [tracks, setTracks] = useState(null); // null = not yet loaded
  const [tracksLoading, setTracksLoading] = useState(false);
  const jamPlayer = useJamPlayer();

  const isOwnProfile = Boolean(currentUser && currentUser.uid === userId);

  const fetchProfile = useCallback(async () => {
    try {
      setLoading(true);
      const userDoc = await getDoc(doc(db, 'users', userId));
      if (userDoc.exists()) {
        setUserProfile({ id: userDoc.id, ...userDoc.data() });
      } else {
        setError('User not found');
      }
    } catch (err) {
      console.error('Error fetching user profile:', err);
      setError('Failed to load profile');
    } finally {
      setLoading(false);
    }
  }, [userId]);

  const fetchDeals = useCallback(async () => {
    if (!userId) return;
    setDealsLoading(true);
    try {
      const baseConstraints = [
        where('agentId', '==', userId),
        orderBy('createdAt', 'desc'),
        qLimit(25),
      ];
      // Hide non-public deals when viewing someone else's profile.
      const constraints = isOwnProfile
        ? baseConstraints
        : [where('visibility', '==', 'public'), ...baseConstraints];

      const q = query(collection(db, 'deals'), ...constraints);
      const snap = await getDocs(q);
      setDeals(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    } catch (err) {
      // Deals collection may not yet exist on a fresh env; don't block profile.
      console.warn('Could not load deals for profile:', err.message);
      setDeals([]);
    } finally {
      setDealsLoading(false);
    }
  }, [userId, isOwnProfile]);

  useEffect(() => {
    fetchProfile();
  }, [fetchProfile]);

  useEffect(() => {
    if (activeTab === 'deals') fetchDeals();
  }, [activeTab, fetchDeals]);

  useEffect(() => {
    if (activeTab !== 'music' || tracks !== null) return;
    (async () => {
      setTracksLoading(true);
      try {
        setTracks(await listJamsByUser(userId));
      } catch (err) {
        console.warn('Could not load tracks for profile:', err.message);
        setTracks([]);
      } finally {
        setTracksLoading(false);
      }
    })();
  }, [activeTab, tracks, userId]);

  // Stop playback when leaving the music tab.
  useEffect(() => {
    if (activeTab !== 'music') jamPlayer.stop();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab]);

  if (loading) {
    return <div className="profile-loading">Loading profile...</div>;
  }
  if (error) {
    return <div className="profile-error">{error}</div>;
  }
  if (!userProfile) {
    return <div className="profile-error">User not found</div>;
  }

  const closedDealCount =
    userProfile.closedDealCount ??
    // fallback: older accounts may only have dealCount; treat it as closed.
    userProfile.dealCount ??
    0;
  const tier = starTierFromUserDoc({ ...userProfile, closedDealCount });
  const progress = nextTierProgress(closedDealCount);
  const market = userProfile.market || {};
  const marketLabel = [market.city, market.state].filter(Boolean).join(', ');

  return (
    <div className="profile-container">
      <div className="profile-header">
        <div className="profile-info">
          <div className="profile-avatar">
            {userProfile.photoURL ? (
              <img src={userProfile.photoURL} alt={userProfile.displayName || 'agent'} />
            ) : (
              <div className="avatar-placeholder">
                {userProfile.displayName?.charAt(0) || 'A'}
              </div>
            )}
          </div>

          <div className="profile-details">
            <div className="profile-headline">
              <h1>{userProfile.displayName || 'Anonymous Agent'}</h1>
              <StarBadge tier={tier} count={closedDealCount} size="lg" showCount />
            </div>

            {marketLabel && (
              <div className="profile-market">{marketLabel}</div>
            )}

            {Array.isArray(userProfile.specialties) && userProfile.specialties.length > 0 && (
              <div className="profile-specialties">
                {userProfile.specialties.map((s) => (
                  <span key={s} className="chip">{s}</span>
                ))}
              </div>
            )}

            <p className="profile-bio">{userProfile.bio || 'No bio yet'}</p>

            <div className="profile-stats">
              <div className="stat">
                <span className="stat-value">{closedDealCount}</span>
                <span className="stat-label">Closed deals</span>
              </div>
              <div className="stat">
                <span className="stat-value">{userProfile.yearsActive ?? 0}</span>
                <span className="stat-label">Years active</span>
              </div>
              <div className="stat">
                <span className="stat-value">{userProfile.followersCount || 0}</span>
                <span className="stat-label">Followers</span>
              </div>
            </div>

            {progress && (
              <div className="profile-progress">
                {progress.remaining} more to reach{' '}
                <span className={`tier-label tier-${progress.nextTier}`}>
                  {progress.nextTier}
                </span>{' '}
                tier
              </div>
            )}
          </div>
        </div>

        <div className="profile-actions">
          {isOwnProfile && (
            <>
              <button className="edit-profile-btn" onClick={() => navigate('/settings')}>
                Edit Profile
              </button>
              <button
                className="edit-profile-btn log-deal-btn"
                onClick={() => setLogDealOpen(true)}
              >
                Log a deal
              </button>
            </>
          )}
        </div>
      </div>

      <div className="profile-content">
        <div className="content-tabs">
          {TABS.map((t) => (
            <button
              key={t}
              className={`tab ${activeTab === t ? 'active' : ''}`}
              onClick={() => setActiveTab(t)}
            >
              {t.charAt(0).toUpperCase() + t.slice(1)}
            </button>
          ))}
        </div>

        <div className="profile-feed">
          {activeTab === 'deals' && (
            <div className="deals-pane">
              {dealsLoading ? (
                <div className="profile-loading">Loading deals…</div>
              ) : deals.length === 0 ? (
                <div className="empty-state">
                  {isOwnProfile
                    ? 'No deals logged yet. Click “Log a deal” to add your first one.'
                    : 'This agent hasn’t logged any public deals yet.'}
                </div>
              ) : (
                <div className="deals-grid">
                  {deals.map((d) => (
                    <DealCard key={d.id} deal={d} publicView={!isOwnProfile} />
                  ))}
                </div>
              )}
            </div>
          )}

          {activeTab === 'music' && (
            <div className="music-pane">
              {tracksLoading ? (
                <div className="profile-loading">Loading tracks…</div>
              ) : !tracks || tracks.length === 0 ? (
                <div className="empty-state">
                  {isOwnProfile ? (
                    <>
                      No tracks yet.{' '}
                      <span
                        onClick={() => navigate('/sketch')}
                        style={{ color: '#7F77DD', cursor: 'pointer', textDecoration: 'underline' }}
                      >
                        Open the Jam Studio
                      </span>{' '}
                      to make your first one.
                    </>
                  ) : (
                    'No tracks published yet.'
                  )}
                </div>
              ) : (
                <div>
                  {isOwnProfile && (
                    <div style={{ display: 'flex', gap: 8, marginBottom: 12 }}>
                      <button className="edit-profile-btn" onClick={() => navigate('/sketch')}>
                        + New jam
                      </button>
                      <button className="edit-profile-btn" onClick={() => navigate('/set')}>
                        Build a set
                      </button>
                    </div>
                  )}
                  {tracks.map((t) => (
                    <TrackCard key={t.id} jam={t} player={jamPlayer} showCreator={false} />
                  ))}
                </div>
              )}
            </div>
          )}

          {activeTab === 'events' && (
            <div className="empty-state">
              Events will appear here. Create one from the main page.
            </div>
          )}

          {activeTab === 'posts' && (
            <Feed authorId={userId} showCreatePost={isOwnProfile} />
          )}

          {activeTab === 'about' && (
            <div className="about-pane">
              <p className="profile-bio">{userProfile.bio || 'No bio yet.'}</p>
              {userProfile.brokerage && (
                <p><strong>Brokerage:</strong> {userProfile.brokerage}</p>
              )}
              {marketLabel && (
                <p><strong>Market:</strong> {marketLabel}</p>
              )}
            </div>
          )}
        </div>
      </div>

      <CreateDealModal
        open={logDealOpen}
        onClose={() => setLogDealOpen(false)}
        onCreated={() => {
          // refresh list after logging
          fetchDeals();
          fetchProfile();
        }}
      />
    </div>
  );
};

export default Profile;
