import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { ThumbsUp, ThumbsDown } from 'lucide-react'
import { useAuth } from '../../contexts/AuthContext'
import { useLiveData } from '../../contexts/LiveDataContext'
import { usePredictCredits, InsufficientCreditsError } from '../../hooks/usePredictCredits'

export default function VoteButtons({ predictionId, initialVotes }) {
  const navigate = useNavigate()
  const { currentUser } = useAuth()
  const { votingService: vs } = useLiveData()
  const { costs, spendForAction } = usePredictCredits()
  const [userVote, setUserVote] = useState(null)
  const [counts, setCounts] = useState(initialVotes || { agree: 0, disagree: 0 })
  const [voteError, setVoteError] = useState(null)

  useEffect(() => {
    let cancelled = false

    // Async load of the user's existing vote (Firebase RTDB read).
    if (currentUser?.id) {
      Promise.resolve(vs.getVote(predictionId, currentUser.id))
        .then(v => { if (!cancelled) setUserVote(v) })
        .catch(() => {})
    } else {
      setUserVote(null)
    }

    // Seed counters from cache (sync) + subscribe for live updates.
    const cached = vs.getVoteCounts(predictionId)
    if (cached.total > 0) setCounts(cached)

    const unsubscribe = vs.onVoteChange?.((event) => {
      if (cancelled) return
      if (event?.type === 'counts' && event.predictionId === predictionId) {
        setCounts({ agree: event.counts.agree, disagree: event.counts.disagree })
      }
      // If THIS user voted from another tab, reflect it locally too.
      if (event?.type === 'vote'
          && event.predictionId === predictionId
          && event.userId === currentUser?.id) {
        setUserVote(event.vote)
      }
    })

    return () => { cancelled = true; unsubscribe?.() }
  }, [predictionId, currentUser, vs])

  async function handleVote(vote) {
    if (!currentUser?.id) return
    setVoteError(null)
    // Only the user's FIRST vote on a prediction costs credits — changing or
    // confirming an existing vote is free.
    const isFirstVote = !userVote
    try {
      if (isFirstVote) {
        // predictionId as idempotency key → charged once per prediction per
        // user, even across sessions; later vote changes stay free.
        await spendForAction('vote', { predictionId, vote }, predictionId)
      }
      const result = await vs.castVote(predictionId, currentUser.id, vote)
      setUserVote(result.vote)
      // Optimistic counter update — the RTDB transaction will fire
      // the `counts` event shortly after to reconcile.
      setCounts(prev => {
        const next = { ...prev }
        if (result.previousVote === 'agree')    next.agree    = Math.max(0, next.agree - 1)
        if (result.previousVote === 'disagree') next.disagree = Math.max(0, next.disagree - 1)
        if (result.vote === 'agree')    next.agree++
        if (result.vote === 'disagree') next.disagree++
        return next
      })
    } catch (e) {
      if (e instanceof InsufficientCreditsError) {
        setVoteError(`Voting costs ${costs.vote} credits.`)
      } else {
        console.warn('[VoteButtons] vote failed:', e?.message)
        setVoteError('Could not record your vote. Please try again.')
      }
    }
  }

  const total = counts.agree + counts.disagree
  const agreePercent = total > 0 ? (counts.agree / total) * 100 : 50

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-3">
        <button
          onClick={() => handleVote('agree')}
          className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium transition-all ${
            userVote === 'agree'
              ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30'
              : 'bg-gray-800/50 text-gray-400 border border-gray-700 hover:border-emerald-500/30 hover:text-emerald-400'
          }`}
        >
          <ThumbsUp size={14} />
          <span className="font-mono">{counts.agree.toLocaleString()}</span>
        </button>
        <button
          onClick={() => handleVote('disagree')}
          className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium transition-all ${
            userVote === 'disagree'
              ? 'bg-red-500/20 text-red-400 border border-red-500/30'
              : 'bg-gray-800/50 text-gray-400 border border-gray-700 hover:border-red-500/30 hover:text-red-400'
          }`}
        >
          <ThumbsDown size={14} />
          <span className="font-mono">{counts.disagree.toLocaleString()}</span>
        </button>
      </div>
      <div className="h-1.5 bg-gray-800 rounded-full overflow-hidden flex">
        <div className="bg-emerald-500 h-full transition-all duration-500" style={{ width: `${agreePercent}%` }} />
        <div className="bg-red-500 h-full transition-all duration-500" style={{ width: `${100 - agreePercent}%` }} />
      </div>
      <div className="flex items-center justify-between">
        <p className="text-[10px] text-gray-600">{total.toLocaleString()} total votes</p>
        {!userVote && (
          <p className="text-[10px] text-gray-600">
            First vote: <span className="font-mono text-amber-500/80">{costs.vote}</span> credits
          </p>
        )}
      </div>
      {voteError && (
        <p className="text-[10px] text-red-400">
          {voteError}{' '}
          <button
            type="button"
            onClick={() => navigate('/credits')}
            className="underline hover:text-red-300"
          >
            Top up
          </button>
        </p>
      )}
    </div>
  )
}
