// Unified Session Screen - Twitch-like layout with all features in one screen
// Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\components\events\UnifiedSessionScreen.jsx

import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { 
  getFirestore, 
  doc, 
  getDoc, 
  onSnapshot,
  updateDoc
} from 'firebase/firestore';
import { 
  getDatabase, 
  ref, 
  onValue, 
  push, 
  set, 
  off 
} from 'firebase/database';
import { 
  Play, 
  Users, 
  Clock, 
  DollarSign, 
  Star,
  MessageCircle,
  Eye,
  Zap,
  Radio,
  Monitor,
  Settings,
  Send,
  Crown,
  Maximize2,
  Minimize2,
  Mic,
  MicOff,
  Video,
  VideoOff,
  Share,
  MoreVertical,
  Volume2,
  VolumeX,
  ScreenShare,
  ScreenShareOff,
  Camera,
  CameraOff,
  Activity,
  Heart,
  Gift,
  ExternalLink,
  Layers,
  PictureInPicture,
  Layout
} from 'lucide-react';

// Import the unified stream manager
import UnifiedStreamManager from '../streaming/UnifiedStreamManager.jsx';
import LiveKitErrorBoundary from '../common/LiveKitErrorBoundary.jsx';

// Who is allowed to broadcast into this event (creator's choice, not a default)
import {
  checkStreamPermission,
  getStreamRoleLabel,
  buildStreamPermissionUpdate,
  STREAM_PERMISSION_TYPES,
  STREAM_PERMISSION_DESCRIPTIONS,
  getEventStreamPermission,
  getEventCreatorId
} from '../../utils/streamPermissions.js';

// Import CSS for styling
import '../../styles/UnifiedSession.css';

const UnifiedSessionScreen = () => {
  const { eventId } = useParams();
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  
  // Event state
  const [event, setEvent] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [viewerCount, setViewerCount] = useState(0);
  
  // Chat state
  const [chatMessages, setChatMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [activeUsers, setActiveUsers] = useState({});
  const [chatRoomData, setChatRoomData] = useState(null);
  const [isConnected, setIsConnected] = useState(false);
  
  // UI state
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [chatCollapsed, setChatCollapsed] = useState(false);
  const [controlsVisible, setControlsVisible] = useState(true);
  const [creatorInfoVisible, setCreatorInfoVisible] = useState(true);
  const [streamMode, setStreamMode] = useState('viewer'); // 'viewer' or 'streamer'
  // Result of checkStreamPermission() for this user + event
  const [streamPermission, setStreamPermission] = useState(null);
  const [savingPermission, setSavingPermission] = useState(false);
  const [localVideoPosition, setLocalVideoPosition] = useState('bottom-right');
  
  // Stream controls state
  const [isAudioEnabled, setIsAudioEnabled] = useState(true);
  const [isVideoEnabled, setIsVideoEnabled] = useState(true);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  
  // Refs
  const messagesEndRef = useRef(null);
  const chatInputRef = useRef(null);
  const controlsTimeoutRef = useRef(null);

  // Decide whether this user may broadcast into this event.
  //
  // Being an artist no longer grants streaming rights on someone else's event:
  // the event's own `streamPermission` decides, and it defaults to creator-only.
  // Platform admins keep an override.
  useEffect(() => {
    const checkStreamerStatus = async () => {
      // Allow viewing without login - default to viewer mode
      if (!event) return;
      if (!currentUser) {
        setStreamPermission(checkStreamPermission(null, event));
        setStreamMode('viewer');
        console.log('👀 Anonymous viewer (no login)');
        return;
      }

      let isAdmin = false;
      try {
        const db = getFirestore();
        const userDoc = await getDoc(doc(db, 'users', currentUser.uid));
        isAdmin = userDoc.data()?.isAdmin === true;
      } catch (error) {
        console.error('Error loading user profile for permission check:', error);
      }

      const permission = checkStreamPermission(currentUser, event, { isAdmin });
      setStreamPermission(permission);
      setStreamMode(permission.canStream ? 'streamer' : 'viewer');
      console.log(
        permission.canStream ? '🎨 User can broadcast to this event' : '👀 User is a viewer for this event',
        { role: permission.role, reason: permission.reason }
      );
    };

    checkStreamerStatus();
  }, [currentUser, event]);

  // Host-only: change who is allowed to broadcast into this event.
  const updateStreamPermission = async (nextPermission) => {
    if (!eventId || streamPermission?.role !== 'creator') return;

    setSavingPermission(true);
    try {
      const db = getFirestore();
      await updateDoc(doc(db, 'events', eventId), buildStreamPermissionUpdate(nextPermission));
      console.log('✅ Stream permission updated:', nextPermission);
    } catch (error) {
      console.error('❌ Failed to update stream permission:', error);
    } finally {
      setSavingPermission(false);
    }
  };

  // Load event data
  useEffect(() => {
    if (!eventId) {
      setError('No event ID provided');
      setLoading(false);
      return;
    }

    const db = getFirestore();
    const eventRef = doc(db, 'events', eventId);

    // Set up real-time listener for event data
    const unsubscribe = onSnapshot(eventRef, (doc) => {
      if (doc.exists()) {
        const eventData = {
          id: doc.id,
          ...doc.data()
        };
        setEvent(eventData);
        setViewerCount(eventData.viewerCount || 0);
        setError(null);
      } else {
        setError('Event not found');
      }
      setLoading(false);
    }, (error) => {
      console.error('Error loading event:', error);
      setError('Failed to load event');
      setLoading(false);
    });

    return () => unsubscribe();
  }, [eventId]);

  // Setup event chat (only if logged in)
  useEffect(() => {
    if (!eventId || !currentUser) {
      console.log('ℹ️ Chat disabled - login required');
      return;
    }

    const rtdb = getDatabase();
    const chatRoomPath = `chats/public/event_${eventId}`;
    
    console.log('🔗 Setting up unified session chat for:', chatRoomPath);
    
    // Listen to chat room data
    const chatRoomRef = ref(rtdb, chatRoomPath);
    const roomUnsubscribe = onValue(chatRoomRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setChatRoomData(data);
        setActiveUsers(data.activeUsers || {});
        setIsConnected(true);
      }
    });
    
    // Listen to messages
    const messagesRef = ref(rtdb, `${chatRoomPath}/messages`);
    const messagesUnsubscribe = onValue(messagesRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const messagesList = Object.entries(data).map(([id, message]) => ({
          id,
          ...message
        })).sort((a, b) => a.timestamp - b.timestamp);
        setChatMessages(messagesList);
      } else {
        setChatMessages([]);
      }
    });
    
    // Add user to active users
    const userRef = ref(rtdb, `${chatRoomPath}/activeUsers/${currentUser.uid}`);
    set(userRef, {
      uid: currentUser.uid,
      name: currentUser.displayName || 'Anonymous',
      avatar: currentUser.photoURL || null,
      joinedAt: Date.now(),
      page: 'unified-session',
      isAnonymous: currentUser.isAnonymous || false,
      mode: streamMode
    });
    
    // Cleanup function
    return () => {
      off(chatRoomRef);
      off(messagesRef);
    };
  }, [eventId, currentUser, streamMode]);

  // Scroll to bottom when new messages arrive
  useEffect(() => {
    scrollToBottom();
  }, [chatMessages]);

  // Auto-hide controls after inactivity
  useEffect(() => {
    const resetControlsTimer = () => {
      if (controlsTimeoutRef.current) {
        clearTimeout(controlsTimeoutRef.current);
      }
      
      setControlsVisible(true);
      
      controlsTimeoutRef.current = setTimeout(() => {
        setControlsVisible(false);
      }, 3000);
    };
    
    const handleMouseMove = () => {
      resetControlsTimer();
    };
    
    document.addEventListener('mousemove', handleMouseMove);
    resetControlsTimer();
    
    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      if (controlsTimeoutRef.current) {
        clearTimeout(controlsTimeoutRef.current);
      }
    };
  }, []);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const sendChatMessage = async () => {
    if (!newMessage.trim() || !eventId || !currentUser) return;
    
    const rtdb = getDatabase();
    const messagesPath = `chats/public/event_${eventId}/messages`;
    const messagesRef = ref(rtdb, messagesPath);
    
    const messageData = {
      type: 'user',
      message: newMessage.trim(),
      timestamp: Date.now(),
      userId: currentUser.uid,
      userName: currentUser.displayName || 'Anonymous',
      userAvatar: currentUser.photoURL || null,
      isAnonymous: currentUser.isAnonymous || false,
      page: 'unified-session',
      mode: streamMode
    };
    
    try {
      await push(messagesRef, messageData);
      setNewMessage('');
      chatInputRef.current?.focus();
    } catch (error) {
      console.error('Failed to send chat message:', error);
    }
  };

  const handleChatKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendChatMessage();
    }
  };

  const formatTime = (timestamp) => {
    return new Date(timestamp).toLocaleTimeString([], { 
      hour: '2-digit', 
      minute: '2-digit' 
    });
  };

  const formatEventTime = (timestamp) => {
    if (!timestamp) return 'Not scheduled';
    return new Date(timestamp).toLocaleString();
  };

  // Hide creator info box after 10 seconds
  useEffect(() => {
    const timer = setTimeout(() => {
      setCreatorInfoVisible(false);
    }, 10000); // 10 seconds

    return () => clearTimeout(timer);
  }, []);

  // Auto-hide controls with mouse movement
  const handleMouseMove = () => {
    setControlsVisible(true);

    // Clear existing timeout
    if (controlsTimeoutRef.current) {
      clearTimeout(controlsTimeoutRef.current);
    }

    // Set new timeout to hide controls after 3 seconds of no mouse movement
    controlsTimeoutRef.current = setTimeout(() => {
      setControlsVisible(false);
    }, 3000);
  };

  const handleMouseLeave = () => {
    // Hide controls immediately when mouse leaves
    if (controlsTimeoutRef.current) {
      clearTimeout(controlsTimeoutRef.current);
    }
    setControlsVisible(false);
  };

  const getEventStatusColor = (status) => {
    switch (status) {
      case 'live': return '#ef4444';
      case 'scheduled': return '#f59e0b';
      case 'ended': return '#6b7280';
      default: return '#6b7280';
    }
  };

  const toggleFullscreen = () => {
    if (!isFullscreen) {
      document.documentElement.requestFullscreen?.();
    } else {
      document.exitFullscreen?.();
    }
    setIsFullscreen(!isFullscreen);
  };

  const toggleLocalVideo = () => {
    setLocalVideoVisible(!localVideoVisible);
  };

  const toggleAudio = () => {
    setIsAudioEnabled(!isAudioEnabled);
  };

  const toggleVideo = () => {
    setIsVideoEnabled(!isVideoEnabled);
  };

  const toggleScreenShare = () => {
    setIsScreenSharing(!isScreenSharing);
  };

  const toggleMute = () => {
    setIsMuted(!isMuted);
  };

  if (loading) {
    return (
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        height: '100vh',
        backgroundColor: '#0f0f0f',
        flexDirection: 'column',
        gap: '1rem',
        color: 'white',
      }}>
        <div style={{
          width: '40px',
          height: '40px',
          border: '4px solid #333',
          borderTop: '4px solid #9146ff',
          borderRadius: '50%',
          animation: 'spin 1s linear infinite',
        }} />
        <p>Loading session...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        height: '100vh',
        backgroundColor: '#0f0f0f',
        flexDirection: 'column',
        gap: '1rem',
        color: '#ff6b6b',
      }}>
        <h2>Error Loading Session</h2>
        <p>{error}</p>
        <button
          onClick={() => navigate('/events')}
          style={{
            backgroundColor: '#9146ff',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            padding: '0.75rem 1.5rem',
            cursor: 'pointer',
          }}
        >
          Back to Events
        </button>
      </div>
    );
  }

  return (
    <div className="unified-session">
      {/* Top Header Bar */}
      <div className="unified-session-header">
        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: '1rem',
        }}>
          <button
            onClick={() => navigate('/events')}
            style={{
              backgroundColor: 'transparent',
              border: 'none',
              color: '#9146ff',
              cursor: 'pointer',
              fontSize: '1.1rem',
              fontWeight: 'bold',
            }}
          >
            ← Events
          </button>
          
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: '0.5rem',
          }}>
            <span
              style={{
                backgroundColor: getEventStatusColor(event.status),
                color: 'white',
                padding: '0.25rem 0.5rem',
                borderRadius: '12px',
                fontSize: '0.7rem',
                fontWeight: 'bold',
                textTransform: 'uppercase',
              }}
            >
              {event.status === 'live' ? '🔴 LIVE' : event.status}
            </span>
            
            <h1 style={{
              margin: 0,
              fontSize: '1.2rem',
              fontWeight: 'bold',
            }}>
              {event.title}
            </h1>

            {/* Your role in this session - makes it obvious whether you can go live */}
            {streamPermission && (
              <span
                title={streamPermission.message}
                style={{
                  border: `1px solid ${streamPermission.canStream ? '#9146ff' : '#2a2a2d'}`,
                  color: streamPermission.canStream ? '#9146ff' : '#adadb8',
                  padding: '0.2rem 0.5rem',
                  borderRadius: '12px',
                  fontSize: '0.7rem',
                  fontWeight: 'bold',
                  textTransform: 'uppercase',
                  whiteSpace: 'nowrap',
                }}
              >
                {getStreamRoleLabel(streamPermission.role)}
              </span>
            )}
          </div>
        </div>

        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: '1rem',
        }}>
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: '0.5rem',
            fontSize: '0.9rem',
            color: '#adadb8',
          }}>
            <Eye size={16} />
            <span>{viewerCount} viewers</span>
          </div>
          
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: '0.5rem',
            fontSize: '0.9rem',
            color: '#adadb8',
          }}>
            <Users size={16} />
            <span>{Object.keys(activeUsers).length} in chat</span>
          </div>
          
          {/* Host-only: who is allowed to broadcast into this event */}
          {streamPermission?.role === 'creator' && (
            <label
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '0.4rem',
                fontSize: '0.8rem',
                color: '#adadb8',
              }}
              title="Choose who is allowed to broadcast into this event"
            >
              <Radio size={14} />
              Who can stream
              <select
                value={getEventStreamPermission(event)}
                disabled={savingPermission}
                onChange={(e) => updateStreamPermission(e.target.value)}
                style={{
                  backgroundColor: '#18181b',
                  color: 'white',
                  border: '1px solid #2a2a2d',
                  borderRadius: '4px',
                  padding: '0.3rem 0.4rem',
                  fontSize: '0.8rem',
                  cursor: savingPermission ? 'wait' : 'pointer',
                }}
              >
                {Object.entries(STREAM_PERMISSION_DESCRIPTIONS).map(([value, meta]) => (
                  <option key={value} value={value}>{meta.label}</option>
                ))}
              </select>
            </label>
          )}

          {/* Host shortcut back to the studio (RTMP keys, DJ studio) */}
          {streamPermission?.role === 'creator' && (
            <button
              onClick={() => navigate(`/events/studio?event=${eventId}`)}
              style={{
                backgroundColor: 'transparent',
                border: '1px solid #2a2a2d',
                color: '#adadb8',
                cursor: 'pointer',
                padding: '0.4rem 0.6rem',
                borderRadius: '4px',
                fontSize: '0.8rem',
                display: 'flex',
                alignItems: 'center',
                gap: '0.35rem',
              }}
            >
              <Settings size={14} />
              Studio
            </button>
          )}

          <button
            onClick={toggleFullscreen}
            style={{
              backgroundColor: 'transparent',
              border: '1px solid #2a2a2d',
              color: '#adadb8',
              cursor: 'pointer',
              padding: '0.5rem',
              borderRadius: '4px',
            }}
          >
            {isFullscreen ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
          </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div style={{
        flex: 1,
        display: 'flex',
        overflow: 'hidden',
      }}>
        {/* Video Area */}
        <div style={{
          flex: 1,
          position: 'relative',
          backgroundColor: '#000',
          display: 'flex',
          flexDirection: 'column',
        }}>
          {/* Main Stream */}
          <div
            style={{
              flex: 1,
              position: 'relative',
              overflow: 'hidden',
            }}
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
          >
            <LiveKitErrorBoundary>
              <UnifiedStreamManager
                eventId={eventId}
                creatorId={getEventCreatorId(event)}
                mode={streamMode}
                canStream={streamPermission ? streamPermission.canStream : null}
                allowGuestStreaming={
                  getEventStreamPermission(event) === STREAM_PERMISSION_TYPES.ANYONE
                }
                onGuestStreamingChange={(allow) =>
                  updateStreamPermission(
                    allow ? STREAM_PERMISSION_TYPES.ANYONE : STREAM_PERMISSION_TYPES.CREATOR_ONLY
                  )
                }
                showDebug={false}
                hideShareSection={true}
                className="unified-session-stream"
                style={{
                  width: '100%',
                  height: '100%',
                }}
              />
            </LiveKitErrorBoundary>

            {/* Local Video Overlay - REMOVED (not functional) */}
            {false && localVideoVisible && streamMode === 'streamer' && (
              <div style={{
                position: 'absolute',
                [localVideoPosition.includes('bottom') ? 'bottom' : 'top']: '20px',
                [localVideoPosition.includes('right') ? 'right' : 'left']: '20px',
                width: '240px',
                height: '135px',
                backgroundColor: '#18181b',
                borderRadius: '8px',
                border: '2px solid #9146ff',
                overflow: 'hidden',
                cursor: 'move',
              }}>
                <div style={{
                  width: '100%',
                  height: '100%',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  backgroundColor: '#000',
                  fontSize: '0.8rem',
                  color: '#adadb8',
                }}>
                  <Camera size={24} />
                  <span style={{ marginLeft: '0.5rem' }}>Local Video</span>
                </div>
                
                <button
                  onClick={toggleLocalVideo}
                  style={{
                    position: 'absolute',
                    top: '4px',
                    right: '4px',
                    backgroundColor: 'rgba(0,0,0,0.7)',
                    border: 'none',
                    color: 'white',
                    padding: '4px',
                    borderRadius: '4px',
                    cursor: 'pointer',
                    fontSize: '0.7rem',
                  }}
                >
                  ×
                </button>
              </div>
            )}

            {/* Stream Controls Overlay - REMOVED (not functional, controls work inside video) */}
            {false && controlsVisible && streamMode === 'streamer' && (
              <div style={{
                position: 'absolute',
                bottom: '20px',
                left: '50%',
                transform: 'translateX(-50%)',
                backgroundColor: 'rgba(0,0,0,0.8)',
                padding: '1rem',
                borderRadius: '12px',
                display: 'flex',
                gap: '0.5rem',
                alignItems: 'center',
                backdropFilter: 'blur(10px)',
              }}>
                <button
                  onClick={toggleAudio}
                  style={{
                    backgroundColor: isAudioEnabled ? '#9146ff' : '#e91e63',
                    color: 'white',
                    border: 'none',
                    borderRadius: '8px',
                    padding: '0.75rem',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.5rem',
                  }}
                >
                  {isAudioEnabled ? <Mic size={16} /> : <MicOff size={16} />}
                </button>
                
                <button
                  onClick={toggleVideo}
                  style={{
                    backgroundColor: isVideoEnabled ? '#9146ff' : '#e91e63',
                    color: 'white',
                    border: 'none',
                    borderRadius: '8px',
                    padding: '0.75rem',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.5rem',
                  }}
                >
                  {isVideoEnabled ? <Video size={16} /> : <VideoOff size={16} />}
                </button>
                
                <button
                  onClick={toggleScreenShare}
                  style={{
                    backgroundColor: isScreenSharing ? '#00bcd4' : '#4a4a4a',
                    color: 'white',
                    border: 'none',
                    borderRadius: '8px',
                    padding: '0.75rem',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.5rem',
                  }}
                >
                  {isScreenSharing ? <ScreenShare size={16} /> : <ScreenShareOff size={16} />}
                </button>
                
                <div style={{
                  width: '1px',
                  height: '24px',
                  backgroundColor: '#2a2a2d',
                  margin: '0 0.5rem',
                }} />
                
                <button
                  onClick={() => setLocalVideoVisible(!localVideoVisible)}
                  style={{
                    backgroundColor: localVideoVisible ? '#9146ff' : '#4a4a4a',
                    color: 'white',
                    border: 'none',
                    borderRadius: '8px',
                    padding: '0.75rem',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.5rem',
                  }}
                >
                  <PictureInPicture size={16} />
                </button>
                
                <button
                  style={{
                    backgroundColor: '#4a4a4a',
                    color: 'white',
                    border: 'none',
                    borderRadius: '8px',
                    padding: '0.75rem',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.5rem',
                  }}
                >
                  <Settings size={16} />
                </button>
              </div>
            )}

            {/* Event Info Overlay - Disappears after 10 seconds */}
            {creatorInfoVisible && (
            <div style={{
              position: 'absolute',
              top: '20px',
              left: '20px',
              backgroundColor: 'rgba(0,0,0,0.8)',
              padding: '1rem',
              borderRadius: '8px',
              maxWidth: '300px',
              backdropFilter: 'blur(10px)',
            }}>
              <div style={{
                display: 'flex',
                alignItems: 'center',
                gap: '0.5rem',
                marginBottom: '0.5rem',
              }}>
                <Star size={16} color="#ffd700" />
                <span style={{ fontWeight: 'bold' }}>{event.artistName}</span>
              </div>
              
              <div style={{
                fontSize: '0.8rem',
                color: '#adadb8',
                display: 'flex',
                alignItems: 'center',
                gap: '1rem',
              }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
                  <Clock size={14} />
                  <span>{formatEventTime(event.startTime)}</span>
                </div>
                
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
                  <DollarSign size={14} />
                  <span>{event.ticketPrice ? `$${event.ticketPrice}` : 'Free'}</span>
                </div>
              </div>
            </div>
            )}
          </div>
        </div>

        {/* Chat Panel */}
        {!chatCollapsed && (
          <div style={{
            width: '340px',
            backgroundColor: '#18181b',
            borderLeft: '1px solid #2a2a2d',
            display: 'flex',
            flexDirection: 'column',
          }}>
            {/* Chat Header */}
            <div style={{
              padding: '1rem',
              borderBottom: '1px solid #2a2a2d',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
            }}>
              <div style={{
                display: 'flex',
                alignItems: 'center',
                gap: '0.5rem',
              }}>
                <MessageCircle size={20} />
                <span style={{ fontWeight: 'bold' }}>Stream Chat</span>
              </div>
              
              <button
                onClick={() => setChatCollapsed(true)}
                style={{
                  backgroundColor: 'transparent',
                  border: 'none',
                  color: '#adadb8',
                  cursor: 'pointer',
                  padding: '0.25rem',
                }}
              >
                <Minimize2 size={16} />
              </button>
            </div>

            {/* Chat Messages */}
            <div style={{
              flex: 1,
              overflow: 'auto',
              padding: '1rem',
              display: 'flex',
              flexDirection: 'column',
              gap: '0.75rem',
            }}>
              {chatMessages.map((message) => (
                <div key={message.id} className={`message ${message.type}`}>
                  {message.type === 'system' ? (
                    <div style={{
                      textAlign: 'center',
                      fontSize: '0.8rem',
                      color: '#adadb8',
                      fontStyle: 'italic',
                    }}>
                      {message.message}
                    </div>
                  ) : (
                    <div style={{
                      display: 'flex',
                      gap: '0.5rem',
                      alignItems: 'flex-start',
                    }}>
                      <div style={{
                        width: '24px',
                        height: '24px',
                        borderRadius: '50%',
                        backgroundColor: '#2a2a2d',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        flexShrink: 0,
                      }}>
                        {message.userAvatar ? (
                          <img 
                            src={message.userAvatar} 
                            alt={message.userName}
                            style={{
                              width: '100%',
                              height: '100%',
                              borderRadius: '50%',
                              objectFit: 'cover',
                            }}
                          />
                        ) : (
                          <div style={{
                            fontSize: '0.7rem',
                            fontWeight: 'bold',
                            color: '#adadb8',
                          }}>
                            {message.userName?.charAt(0) || 'A'}
                          </div>
                        )}
                      </div>
                      
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: '0.5rem',
                          marginBottom: '0.25rem',
                        }}>
                          <span style={{
                            fontWeight: 'bold',
                            color: message.mode === 'streamer' ? '#9146ff' : '#ffffff',
                            fontSize: '0.8rem',
                          }}>
                            {message.userName}
                          </span>
                          
                          {message.mode === 'streamer' && (
                            <Crown size={10} color="#ffd700" />
                          )}
                          
                          <span style={{
                            fontSize: '0.7rem',
                            color: '#adadb8',
                          }}>
                            {formatTime(message.timestamp)}
                          </span>
                        </div>
                        
                        <p style={{
                          margin: 0,
                          fontSize: '0.8rem',
                          color: '#efeff1',
                          lineHeight: '1.4',
                          wordBreak: 'break-word',
                        }}>
                          {message.message}
                        </p>
                      </div>
                    </div>
                  )}
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>

            {/* Chat Input */}
            <div style={{
              padding: '1rem',
              borderTop: '1px solid #2a2a2d',
            }}>
              {currentUser ? (
                <div style={{
                  display: 'flex',
                  gap: '0.5rem',
                }}>
                  <input
                    ref={chatInputRef}
                    type="text"
                    value={newMessage}
                    onChange={(e) => setNewMessage(e.target.value)}
                    onKeyPress={handleChatKeyPress}
                    placeholder="Send a message..."
                    maxLength={500}
                    style={{
                      flex: 1,
                      padding: '0.75rem',
                      backgroundColor: '#2a2a2d',
                      border: '1px solid #3a3a3d',
                      borderRadius: '8px',
                      color: 'white',
                      fontSize: '0.9rem',
                    }}
                  />

                  <button
                    onClick={sendChatMessage}
                    disabled={!newMessage.trim()}
                    style={{
                      backgroundColor: newMessage.trim() ? '#9146ff' : '#4a4a4a',
                      color: 'white',
                      border: 'none',
                      borderRadius: '8px',
                      padding: '0.75rem',
                      cursor: newMessage.trim() ? 'pointer' : 'not-allowed',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                    }}
                  >
                    <Send size={16} />
                  </button>
                </div>
              ) : (
                <button
                  onClick={() => navigate('/login')}
                  style={{
                    width: '100%',
                    padding: '0.75rem',
                    backgroundColor: '#9146ff',
                    color: 'white',
                    border: 'none',
                    borderRadius: '8px',
                    cursor: 'pointer',
                    fontSize: '0.9rem',
                    fontWeight: '600',
                  }}
                >
                  Login to Chat
                </button>
              )}
            </div>
          </div>
        )}

        {/* Chat Collapsed Button */}
        {chatCollapsed && (
          <button
            onClick={() => setChatCollapsed(false)}
            style={{
              position: 'absolute',
              right: '20px',
              top: '50%',
              transform: 'translateY(-50%)',
              backgroundColor: '#9146ff',
              color: 'white',
              border: 'none',
              borderRadius: '8px 0 0 8px',
              padding: '1rem 0.5rem',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              gap: '0.5rem',
              writingMode: 'vertical-lr',
            }}
          >
            <MessageCircle size={16} />
            <span>Chat</span>
          </button>
        )}
      </div>

      {/* Bottom Status Bar */}
      <div style={{
        padding: '0.5rem 1rem',
        backgroundColor: '#18181b',
        borderTop: '1px solid #2a2a2d',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        fontSize: '0.8rem',
        color: '#adadb8',
      }}>
        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: '1rem',
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
            <Zap size={14} color="#9146ff" />
            <span>Unified Session</span>
          </div>
          
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
            <Activity size={14} />
            <span>LiveKit</span>
          </div>
          
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
            <Layers size={14} />
            <span>Room: event-{eventId}</span>
          </div>
        </div>
        
        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: '1rem',
        }}>
          <div>Mode: {streamMode}</div>
          <div>Connected: {isConnected ? '✓' : '✗'}</div>
          <div>v1.0.0</div>
        </div>
      </div>
    </div>
  );
};

export default UnifiedSessionScreen;