// src/services/SubscriptionService.js
import { getFirestore, doc, getDoc, setDoc, updateDoc, onSnapshot } from 'firebase/firestore';
import { getAuth } from 'firebase/auth';
import { stripeSubscriptionService } from './StripeSubscriptionService';
import { detectEnvironment, isDevelopment, isTest } from '../utils/environmentDetection';

class SubscriptionService {
  constructor() {
    this.db = getFirestore();
    this.auth = getAuth();
    this.listeners = new Map();
    this.environment = detectEnvironment();
  }

  /**
   * Get current user's subscription status
   * Enhanced with environment-based Stripe checking
   */
  async getSubscriptionStatus(userId = null) {
    try {
      const uid = userId || this.auth.currentUser?.uid;
      if (!uid) {
        return { isActive: false, error: 'User not authenticated' };
      }

      const userRef = doc(this.db, 'users', uid);
      const userDoc = await getDoc(userRef);

      if (!userDoc.exists()) {
        return { 
          isActive: false, 
          isPremium: false,
          plan: null,
          error: 'User document not found' 
        };
      }

      const userData = userDoc.data();
      const now = new Date();

      // Get local Firebase data
      const localPremium = userData.isPremium === true;
      let isExpired = false;

      // Check expiration if end date exists
      if (userData.premiumEndDate) {
        let endDate;
        if (userData.premiumEndDate.toDate) {
          // Firebase Timestamp
          endDate = userData.premiumEndDate.toDate();
        } else if (userData.premiumEndDate instanceof Date) {
          // JS Date object
          endDate = userData.premiumEndDate;
        } else {
          // String or timestamp
          endDate = new Date(userData.premiumEndDate);
        }
        isExpired = endDate < now;
      }

      const localIsActive = localPremium && !isExpired;

      // In development and test environments, also check Stripe status
      let stripeStatus = null;
      if (isDevelopment() || isTest()) {
        console.log(`🔍 Environment is ${this.environment} - checking Stripe status`);
        
        try {
          stripeStatus = await stripeSubscriptionService.checkSubscriptionStatus(
            uid, 
            userData.email || this.auth.currentUser?.email
          );
          
          console.log('Stripe status result:', stripeStatus);
          
          // If Stripe shows active subscription but local doesn't, update local
          if (stripeStatus.success && stripeStatus.isActive && !localIsActive) {
            console.log('🔄 Stripe shows active subscription - updating local status');
            await this.updateSubscriptionFromStripe(uid, stripeStatus);
            
            // Return updated status
            return {
              isActive: true,
              isPremium: true,
              isExpired: false,
              plan: stripeStatus.subscription?.plan || 'Premium',
              startDate: userData.premiumStartDate || now,
              endDate: userData.premiumEndDate,
              stripeCustomerId: stripeStatus.customer?.id,
              stripeSubscriptionId: stripeStatus.subscription?.id,
              transactions: userData.transactions || [],
              lastUpdated: now,
              environment: this.environment,
              stripeEnvironment: stripeStatus.stripeEnvironment,
              syncedFromStripe: true,
              error: null
            };
          }
          
          // If local shows active but Stripe doesn't, and it's dev/test, trust Stripe
          if (stripeStatus.success && !stripeStatus.isActive && localIsActive && (isDevelopment() || isTest())) {
            console.log('⚠️ Local shows active but Stripe doesn\'t - updating local status');
            await updateDoc(userRef, {
              isPremium: false,
              subscriptionLastUpdated: now,
              stripeStatusMismatch: true
            });
            
            return {
              isActive: false,
              isPremium: false,
              isExpired: true,
              plan: userData.premiumTier || 'Premium',
              startDate: userData.premiumStartDate,
              endDate: userData.premiumEndDate,
              stripeCustomerId: userData.stripeCustomerId,
              stripeSubscriptionId: userData.stripeSubscriptionId,
              transactions: userData.transactions || [],
              lastUpdated: now,
              environment: this.environment,
              stripeEnvironment: stripeStatus.stripeEnvironment,
              syncedFromStripe: true,
              error: null
            };
          }
        } catch (error) {
          console.warn('Error checking Stripe status:', error);
          // Continue with local status if Stripe check fails
        }
      }

      // Return combined status
      return {
        isActive: localIsActive,
        isPremium: localPremium,
        isExpired,
        plan: userData.premiumTier || 'Premium',
        startDate: userData.premiumStartDate,
        endDate: userData.premiumEndDate,
        stripeCustomerId: userData.stripeCustomerId,
        stripeSubscriptionId: userData.stripeSubscriptionId,
        transactions: userData.transactions || [],
        lastUpdated: userData.subscriptionLastUpdated,
        environment: this.environment,
        stripeStatus: stripeStatus,
        error: null
      };
    } catch (error) {
      console.error('Error getting subscription status:', error);
      return { 
        isActive: false, 
        error: error.message 
      };
    }
  }

  /**
   * Update local subscription status from Stripe data
   */
  async updateSubscriptionFromStripe(uid, stripeStatus) {
    try {
      const userRef = doc(this.db, 'users', uid);
      const now = new Date();
      
      // Calculate end date (30 days from now for active subscriptions)
      const endDate = new Date(now.getTime() + (30 * 24 * 60 * 60 * 1000));
      
      const updateData = {
        isPremium: stripeStatus.isActive,
        premiumTier: stripeStatus.subscription?.plan || 'Premium',
        premiumStartDate: now,
        premiumEndDate: stripeStatus.isActive ? endDate : null,
        subscriptionLastUpdated: now,
        stripeCustomerId: stripeStatus.customer?.id,
        stripeSubscriptionId: stripeStatus.subscription?.id,
        syncedFromStripe: true,
        stripeEnvironment: stripeStatus.stripeEnvironment,
        lastStripeSync: now
      };
      
      await updateDoc(userRef, updateData);
      console.log('✅ Updated local subscription from Stripe');
      
      return { success: true };
    } catch (error) {
      console.error('Error updating subscription from Stripe:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Update subscription status after successful payment
   */
  async updateSubscriptionStatus(subscriptionData) {
    try {
      const uid = this.auth.currentUser?.uid;
      if (!uid) {
        throw new Error('User not authenticated');
      }

      const userRef = doc(this.db, 'users', uid);
      const now = new Date();

      // Calculate end date (default to 30 days from now)
      const durationDays = subscriptionData.durationDays || 30;
      const endDate = new Date(now.getTime() + (durationDays * 24 * 60 * 60 * 1000));

      const updateData = {
        isPremium: true,
        premiumTier: subscriptionData.plan || 'Premium',
        premiumStartDate: subscriptionData.startDate || now,
        premiumEndDate: endDate,
        subscriptionLastUpdated: now,
        stripeCustomerId: subscriptionData.stripeCustomerId || null,
        stripeSubscriptionId: subscriptionData.stripeSubscriptionId || null,
        environment: this.environment,
        // Add transaction record
        transactions: [
          ...(subscriptionData.existingTransactions || []),
          {
            id: subscriptionData.transactionId || `tx_${Date.now()}`,
            amount: subscriptionData.amount,
            currency: subscriptionData.currency || 'usd',
            status: 'completed',
            date: now,
            description: subscriptionData.description || 'Premium membership purchase',
            stripePaymentIntentId: subscriptionData.stripePaymentIntentId || null,
            environment: this.environment
          }
        ]
      };

      // Check if user document exists, create if it doesn't
      const userDoc = await getDoc(userRef);
      if (!userDoc.exists()) {
        // Create new user document
        const userData = {
          uid,
          email: this.auth.currentUser.email,
          displayName: this.auth.currentUser.displayName || '',
          createdAt: now,
          ...updateData
        };
        await setDoc(userRef, userData);
      } else {
        // Update existing document
        const existingData = userDoc.data();
        updateData.transactions = [
          ...(existingData.transactions || []),
          updateData.transactions[updateData.transactions.length - 1]
        ];
        await updateDoc(userRef, updateData);
      }

      console.log('Subscription status updated successfully');
      return { success: true, data: updateData };
    } catch (error) {
      console.error('Error updating subscription status:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Listen to real-time subscription status changes
   * Enhanced with environment awareness
   */
  subscribeToStatusChanges(callback, userId = null) {
    try {
      const uid = userId || this.auth.currentUser?.uid;
      if (!uid) {
        callback({ isActive: false, error: 'User not authenticated' });
        return () => {};
      }

      const userRef = doc(this.db, 'users', uid);
      
      const unsubscribe = onSnapshot(userRef, async (doc) => {
        if (doc.exists()) {
          const userData = doc.data();
          const now = new Date();

          // Check if premium is active
          const isPremium = userData.isPremium === true;
          let isExpired = false;

          // Check expiration if end date exists
          if (userData.premiumEndDate) {
            let endDate;
            if (userData.premiumEndDate.toDate) {
              endDate = userData.premiumEndDate.toDate();
            } else if (userData.premiumEndDate instanceof Date) {
              endDate = userData.premiumEndDate;
            } else {
              endDate = new Date(userData.premiumEndDate);
            }
            isExpired = endDate < now;
          }

          const isActive = isPremium && !isExpired;

          const status = {
            isActive,
            isPremium,
            isExpired,
            plan: userData.premiumTier || 'Premium',
            startDate: userData.premiumStartDate,
            endDate: userData.premiumEndDate,
            stripeCustomerId: userData.stripeCustomerId,
            stripeSubscriptionId: userData.stripeSubscriptionId,
            transactions: userData.transactions || [],
            lastUpdated: userData.subscriptionLastUpdated,
            environment: this.environment,
            error: null
          };

          callback(status);
        } else {
          callback({ 
            isActive: false, 
            isPremium: false,
            error: 'User document not found' 
          });
        }
      }, (error) => {
        console.error('Error listening to subscription changes:', error);
        callback({ isActive: false, error: error.message });
      });

      // Store unsubscribe function
      this.listeners.set(uid, unsubscribe);
      
      return unsubscribe;
    } catch (error) {
      console.error('Error setting up subscription listener:', error);
      callback({ isActive: false, error: error.message });
      return () => {};
    }
  }

  /**
   * Cancel subscription (mark as inactive)
   */
  async cancelSubscription() {
    try {
      const uid = this.auth.currentUser?.uid;
      if (!uid) {
        throw new Error('User not authenticated');
      }

      const userRef = doc(this.db, 'users', uid);
      const now = new Date();

      await updateDoc(userRef, {
        isPremium: false,
        subscriptionLastUpdated: now,
        cancellationDate: now
      });

      console.log('Subscription cancelled successfully');
      return { success: true };
    } catch (error) {
      console.error('Error cancelling subscription:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Check if user has access to premium features
   */
  async hasPremiumAccess(userId = null) {
    const status = await this.getSubscriptionStatus(userId);
    return status.isActive === true;
  }

  /**
   * Manual premium toggle for development/testing
   * Only works in dev/test environments
   */
  async setManualPremiumStatus(isActive, userId = null) {
    console.log(`🎯 setManualPremiumStatus called with isActive: ${isActive}`);
    
    if (!isDevelopment() && !isTest()) {
      console.warn('❌ Manual premium status only allowed in dev/test environments');
      return { success: false, error: 'Not allowed in production' };
    }

    try {
      const uid = userId || this.auth.currentUser?.uid;
      const email = this.auth.currentUser?.email;
      
      console.log(`👤 User info - UID: ${uid}, Email: ${email}`);
      
      if (!uid || !email) {
        const error = 'User not authenticated';
        console.error('❌', error);
        throw new Error(error);
      }

      // Set manual override in Stripe service
      console.log('🔧 Setting Stripe manual override...');
      stripeSubscriptionService.setManualOverride(uid, isActive, email);
      
      // Also update local Firebase data
      const userRef = doc(this.db, 'users', uid);
      const now = new Date();
      
      const updateData = {
        isPremium: isActive,
        premiumTier: isActive ? 'Premium' : null,
        premiumStartDate: isActive ? now : null,
        premiumEndDate: isActive ? new Date(now.getTime() + (30 * 24 * 60 * 60 * 1000)) : null,
        subscriptionLastUpdated: now,
        manualOverride: true,
        environment: this.environment,
        debugTimestamp: now.toISOString()
      };
      
      console.log('📝 About to update Firebase with data:', updateData);
      
      // Check if user document exists first
      const userDoc = await getDoc(userRef);
      console.log(`📄 User document exists: ${userDoc.exists()}`);
      
      if (!userDoc.exists()) {
        console.log('🆕 Creating new user document...');
        const userData = {
          uid,
          email,
          displayName: this.auth.currentUser?.displayName || '',
          createdAt: now,
          ...updateData
        };
        await setDoc(userRef, userData);
        console.log('✅ Created new user document');
      } else {
        console.log('📝 Updating existing user document...');
        await updateDoc(userRef, updateData);
        console.log('✅ Updated existing user document');
      }
      
      // Verify the update
      const updatedDoc = await getDoc(userRef);
      const updatedData = updatedDoc.data();
      console.log('🔍 Verification - Updated document data:', {
        isPremium: updatedData.isPremium,
        premiumTier: updatedData.premiumTier,
        debugTimestamp: updatedData.debugTimestamp
      });
      
      console.log(`🧪 Manual premium status set to ${isActive} for ${this.environment}`);
      return { success: true, data: updatedData };
      
    } catch (error) {
      console.error('❌ Error setting manual premium status:', error);
      console.error('Stack trace:', error.stack);
      return { success: false, error: error.message };
    }
  }

  /**
   * Clear manual premium override
   */
  async clearManualOverride(userId = null) {
    if (!isDevelopment() && !isTest()) {
      return { success: false, error: 'Not allowed in production' };
    }
    
    const uid = userId || this.auth.currentUser?.uid;
    if (uid) {
      stripeSubscriptionService.clearManualOverride(uid);
    }
    
    return { success: true };
  }

  /**
   * Clean up listeners
   */
  cleanup() {
    this.listeners.forEach((unsubscribe) => {
      if (typeof unsubscribe === 'function') {
        unsubscribe();
      }
    });
    this.listeners.clear();
  }
}

// Export singleton instance
export const subscriptionService = new SubscriptionService();
export default subscriptionService;
