import { ADROLL_CONFIG, initializeAdRoll, trackAdRollEvent } from '../config/adroll';

class AdManager {
  constructor() {
    this.adQueue = [];
    this.isAdActive = false;
    this.anonymousTimerStarted = false;
    this.adTimer = null;
    this.sessionStartTime = null;
    this.adCallbacks = new Map();
  }
  
  initialize() {
    // Initialize AdRoll
    initializeAdRoll();
    
    // Track initial page view
    trackAdRollEvent('pageView');
  }
  
  startAnonymousSession() {
    if (this.anonymousTimerStarted) return;
    
    this.anonymousTimerStarted = true;
    this.sessionStartTime = Date.now();
    
    // Schedule ad display after the configured delay
    this.adTimer = setTimeout(() => {
      this.showAd('video');
    }, ADROLL_CONFIG.anonymousUserAdDelay);
    
    // Track anonymous session start
    trackAdRollEvent('anonymousSessionStart');
  }
  
  stopAnonymousSession() {
    if (this.adTimer) {
      clearTimeout(this.adTimer);
      this.adTimer = null;
    }
    this.anonymousTimerStarted = false;
    this.sessionStartTime = null;
    
    // Hide any active ads
    this.hideCurrentAd();
  }
  
  showAd(type = 'video', options = {}) {
    if (this.isAdActive) {
      // Queue the ad if one is already showing
      this.adQueue.push({ type, options });
      return;
    }
    
    this.isAdActive = true;
    
    // Track ad impression
    trackAdRollEvent('adImpression', {
      ad_type: type,
      session_duration: this.sessionStartTime ? Date.now() - this.sessionStartTime : 0
    });
    
    // Notify listeners that an ad should be shown
    if (this.adCallbacks.has('onShowAd')) {
      this.adCallbacks.get('onShowAd')(type, options);
    }
  }
  
  hideCurrentAd() {
    this.isAdActive = false;
    
    // Notify listeners that the ad should be hidden
    if (this.adCallbacks.has('onHideAd')) {
      this.adCallbacks.get('onHideAd')();
    }
    
    // Check if there are queued ads
    if (this.adQueue.length > 0) {
      const nextAd = this.adQueue.shift();
      setTimeout(() => {
        this.showAd(nextAd.type, nextAd.options);
      }, 1000); // Small delay between ads
    }
  }
  
  onAdComplete() {
    // Track ad completion
    trackAdRollEvent('adComplete', {
      ad_type: this.currentAdType
    });
    
    this.hideCurrentAd();
  }
  
  // Register callbacks for ad events
  on(event, callback) {
    this.adCallbacks.set(event, callback);
  }
  
  off(event) {
    this.adCallbacks.delete(event);
  }
  
  // Check if user should see ads (anonymous users only)
  shouldShowAds(user) {
    return user?.isAnonymous === true;
  }
  
  // Get remaining time until ad display
  getRemainingTimeUntilAd() {
    if (!this.sessionStartTime || !this.anonymousTimerStarted) {
      return null;
    }
    
    const elapsed = Date.now() - this.sessionStartTime;
    const remaining = ADROLL_CONFIG.anonymousUserAdDelay - elapsed;
    
    return Math.max(0, remaining);
  }
  
  // Force show ad (for testing)
  forceShowAd(type = 'video') {
    this.showAd(type, { forced: true });
  }
}

// Create singleton instance
const adManager = new AdManager();

export default adManager;