// src/utils/auditIntegration.js
import { auth } from '../firebase';
import { logFileUsage, isFileAuditEnabled, checkUserAuditPermission } from './fileAuditUtils';
import { instrumentFirestore, isFirebaseAuditEnabled } from './firebaseAuditUtils';

/**
 * Global audit session ID
 */
let auditSessionId = null;

/**
 * Initializes the audit system
 * This should be called as early as possible in your application
 */
export const initAuditSystem = () => {
  // Generate a session ID if one doesn't exist
  if (!auditSessionId) {
    auditSessionId = generateSessionId();
    
    if (typeof window !== 'undefined' && window.sessionStorage) {
      window.sessionStorage.setItem('fileAuditSessionId', auditSessionId);
    }
  }
  
  // Instrument Firestore for Firebase auditing
  if (isFirebaseAuditEnabled) {
    instrumentFirestore();
  }
  
  // Log application start
  if (isFileAuditEnabled) {
    logApplicationStart();
  }
  
  console.debug('[Audit System] Initialized');
};

/**
 * Generates a unique session ID
 * @returns {string} Session ID
 */
const generateSessionId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substr(2);
};

/**
 * Logs application start
 */
const logApplicationStart = async () => {
  try {
    const userId = auth.currentUser ? auth.currentUser.uid : 'anonymous';
    
    // Check if user has audit permissions
    const canAudit = await checkUserAuditPermission(auth);
    if (!canAudit) return;
    
    // Log application start
    await logFileUsage('AppRoot', 'InitialLoad', userId, {
      timestamp: new Date().toISOString(),
      sessionId: auditSessionId,
    });
  } catch (error) {
    console.error('[Audit System] Error logging application start:', error);
  }
};

/**
 * Reusable higher-order function to wrap any function with audit logging
 * @param {Function} fn - Function to wrap
 * @param {string} filePath - Path of the file containing the function
 * @param {string} functionName - Name of the function
 * @returns {Function} Wrapped function
 */
export const withAudit = (fn, filePath, functionName) => {
  return async function(...args) {
    if (!isFileAuditEnabled) {
      return fn.apply(this, args);
    }
    
    try {
      // Check if user has audit permissions
      const canAudit = await checkUserAuditPermission(auth);
      if (!canAudit) {
        return fn.apply(this, args);
      }
      
      const userId = auth.currentUser ? auth.currentUser.uid : 'anonymous';
      
      // Log function call
      await logFileUsage(filePath, `Function:${functionName}`, userId, {
        timestamp: new Date().toISOString(),
        sessionId: auditSessionId,
        args: JSON.stringify(args)
      });
      
      // Call the original function
      return fn.apply(this, args);
    } catch (error) {
      console.error(`[Audit System] Error in audited function ${functionName}:`, error);
      throw error;
    }
  };
};

/**
 * Decorator for React components to track file usage
 * @param {string} filePath - Path of the component file
 * @returns {Function} Component decorator
 */
export const auditComponent = (filePath) => {
  return (Component) => {
    // Import React here to avoid circular dependencies
    const React = require('react');
    
    // Store the original render method
    const originalRender = Component.prototype ? Component.prototype.render : null;
    
    // If it's a class component with a render method
    if (originalRender) {
      Component.prototype.render = function() {
        if (isFileAuditEnabled) {
          const userId = auth.currentUser ? auth.currentUser.uid : 'anonymous';
          
          // Only log once per component instance
          if (!this.__auditLogged) {
            this.__auditLogged = true;
            
            // Check user permissions before logging
            checkUserAuditPermission(auth).then(canAudit => {
              if (canAudit) {
                logFileUsage(filePath, 'ClassComponent', userId, {
                  componentName: Component.name,
                  timestamp: new Date().toISOString(),
                  sessionId: auditSessionId
                });
              }
            });
          }
        }
        
        return originalRender.apply(this);
      };
    }
    
    // For functional components, wrap with useEffect
    const WrappedComponent = (props) => {
      const originalComponent = Component;
      
      React.useEffect(() => {
        if (isFileAuditEnabled) {
          const userId = auth.currentUser ? auth.currentUser.uid : 'anonymous';
          
          // Check user permissions before logging
          checkUserAuditPermission(auth).then(canAudit => {
            if (canAudit) {
              logFileUsage(filePath, 'FunctionalComponent', userId, {
                componentName: originalComponent.name,
                timestamp: new Date().toISOString(),
                sessionId: auditSessionId
              });
            }
          });
        }
      }, []);
      
      return React.createElement(originalComponent, props);
    };
    
    WrappedComponent.displayName = `Audited(${Component.displayName || Component.name || 'Component'})`;
    
    return WrappedComponent;
  };
};

/**
 * Auto-audit a file
 * This should be imported at the top of every file you want to audit
 * @param {string} filePath - Path of the current file
 */
export const auditFile = (filePath) => {
  if (!isFileAuditEnabled) return;
  
  if (typeof window !== 'undefined') {
    // Delay execution to ensure authentication is initialized
    setTimeout(async () => {
      try {
        const userId = auth.currentUser ? auth.currentUser.uid : 'anonymous';
        
        // Check if user has audit permissions
        const canAudit = await checkUserAuditPermission(auth);
        if (!canAudit) return;
        
        // Log file import
        await logFileUsage(filePath, 'FileImport', userId, {
          timestamp: new Date().toISOString(),
          sessionId: auditSessionId
        });
      } catch (error) {
        console.error(`[Audit System] Error in auditFile for ${filePath}:`, error);
      }
    }, 0);
  }
};

/**
 * Get current audit status
 * @returns {Object} Audit status
 */
export const getAuditStatus = () => {
  return {
    fileAuditEnabled: isFileAuditEnabled,
    firebaseAuditEnabled: isFirebaseAuditEnabled,
    sessionId: auditSessionId,
    userId: auth.currentUser ? auth.currentUser.uid : 'anonymous'
  };
};

// Export constants
export const FILE_AUDIT_ENABLED = isFileAuditEnabled;
export const FIREBASE_AUDIT_ENABLED = isFirebaseAuditEnabled;