// src/contexts/AdminAuthContext.jsx
import React, { createContext, useContext, useState, useEffect } from 'react';
import { useAuth } from './AuthContext';
import { getFirestore, doc, getDoc } from 'firebase/firestore';

// Create the admin auth context
const AdminAuthContext = createContext();

// Provider component that wraps your app and makes admin auth available to any
// child component that calls useAdminAuth().
export function AdminAuthProvider({ children }) {
  const { currentUser, loading: authLoading } = useAuth();
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAudit, setIsAudit] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const checkAdminStatus = async () => {
      setLoading(true);
      setError(null);
      
      try {
        // If no user is logged in, they're definitely not an admin
        if (!currentUser || authLoading) {
          setIsAdmin(false);
          setLoading(false);
          return;
        }
        
        // Check Firestore for admin and audit status
        const db = getFirestore();
        const userRef = doc(db, 'users', currentUser.uid);
        const userDoc = await getDoc(userRef);
        
        if (userDoc.exists()) {
          const userData = userDoc.data();
          setIsAdmin(userData.isAdmin === true);
          setIsAudit(userData.isAudit === true);
        } else {
          setIsAdmin(false);
          setIsAudit(false);
        }
      } catch (err) {
        console.error('Error checking admin/audit status:', err);
        setError(err);
        setIsAdmin(false);
        setIsAudit(false);
      } finally {
        setLoading(false);
      }
    };
    
    checkAdminStatus();
  }, [currentUser, authLoading]);

  // The value passed to the provider gives access to these items
  const value = {
    isAdmin,
    isAudit,
    loading,
    error
  };

  return (
    <AdminAuthContext.Provider value={value}>
      {children}
    </AdminAuthContext.Provider>
  );
}

// Custom hook for using admin auth
export function useAdminAuth() {
  return useContext(AdminAuthContext);
}